local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["quest:1013"] = {n="乌尔之书",s="《乌尔之书》是看守者贝尔杜加在幽暗城的Apothecarium发布的一项任务。贝尔杜加派遣部落勇士潜入影牙城堡，找回达拉然已故法师乌尔的奥术著作。被遗忘者渴求乌尔关于异界的各种研究，意图将他因心怀顾虑而未曾利用的魔法见解武器化。",h="《乌尔之书》是看守者贝尔杜加在幽暗城的Apothecarium发布的一项任务。贝尔杜加派遣部落勇士潜入影牙城堡，找回达拉然已故法师乌尔的奥术著作。被遗忘者渴求乌尔关于异界的各种研究，意图将他因心怀顾虑而未曾利用的魔法见解...",kw={"apothecarium","阿鲁高","贝尔杜加","乌尔之书","达拉然","芬鲁斯","肯瑞托","影牙城堡","狼人"},ang={["class:Mage"]="《乌尔之书》作为肯瑞托历史上一件阴暗的文物，揭示了达拉然对异界实体的理论研究是如何被阿鲁高这类不稳定的施法者扭曲成末日诅咒的。",["class:Warlock"]="乌尔探索凡人现实之外的意愿反映了术士对异界知识的渴望，尽管贝尔杜加指出，乌尔的失败在于没有胆量去驾驭他所发现的东西。",["faction:Horde"]="扫清影牙城堡并夺取阿鲁高的研究来源有助于稳定银松森林，遏制威胁部落领地的凶残狼人。",["race:Undead"]="找回这本书直接服务于希尔瓦娜斯女士和皇家药剂师学会，巩固了被遗忘者的信条：生存需要毫无保留地拥抱禁忌知识，摒弃凡人的那种妇人之仁。"},sec={{t="异界魔法的遗物",b="在第三次战争摧毁达拉然之前，一位才华横溢的人类法师乌尔将他的毕生精力都投入到了艾泽拉斯之外领域的研究中。与肯瑞托严格限制咒法和外位面接触的教条不同，乌尔对来自其他维度的实体进行了编目，其中包括凶残的狼人。尽管充满好奇心，乌尔最终还是不敢操纵这些异界力量，认为它们危险且难以控制。然而，正是这种克制，使得他留下的书稿成为了那些毫无道德顾虑之人的心头好。"},{t="落入黑暗之手",b="大法师阿鲁高在入驻影牙城堡之前，获得了乌尔的著作并利用了其中的研究成果。阿鲁高缺乏乌尔那样的道德顾虑，他利用书中的内容将嗜血的狼人召唤到了银松森林，引发了一场吞噬了焚木村及周边峡谷的诅咒。现在，这本书被遗弃在影牙城堡的塔楼里，由阿鲁高那些野性难驯的宠物守卫着。"},{t="被遗忘者的野心",b="对于皇家药剂师学会和看守者贝尔杜加来说，乌尔的陨落并非傲慢的警世恒言，而是凡人脆弱的写照。贝尔杜加认为乌尔的死是因为他在危机时刻被良知所束缚。通过为幽暗城夺取《乌尔之书》，被遗忘者打算剔除书中那些学术上的迟疑，利用异维度的知识来确保他们的生存，并巩固Sylvanas Windrunner在洛丹伦的统治。"}},faq={{q="乌尔是谁？",a="乌尔是一位著名的达拉然法师，在第三次战争之前，他研究过魔法现象和其他世界。在天灾军团入侵达拉然时丧生之前，他深入研究过包括狼人在内的异维度生物。",al={"乌尔背景故事","乌尔是谁","法师乌尔"}},{q="《乌尔之书》在哪里？",a="这本书位于影牙城堡内，放在深处吞噬者芬鲁斯所在的房间里的书架上。",al={"书在哪里","乌尔之书位置","影牙城堡书籍位置"}},{q="看守者贝尔杜加是谁？",a="看守者贝尔杜加是一位被遗忘者档案管理员和研究员，驻扎在幽暗城的Apothecarium。他收集黑暗、奥术和异界的知识，以促进被遗忘者的力量和生存。",al={"贝尔杜加","看守者贝尔杜加","任务发布者"}},{q="为什么被遗忘者想要这本书？",a="贝尔杜加和他的同僚渴求乌尔关于异界实体的研究。被遗忘者认为乌尔之所以没能从天灾的浩劫中幸存，仅仅是因为他的道德良知阻止他去利用所发现的力量——而幽暗城绝不打算重蹈覆辙。",al={"为什么被遗忘者想要乌尔的书","幽暗城对乌尔之书的用途"}},{q="这本书是怎么落到影牙城堡的？",a="达拉然陷落后，大法师阿鲁高获得了乌尔的笔记，并利用它们将狼人召唤到了洛丹伦。阿鲁高在占领影牙城堡时，将这份研究带到了那里。",al={"阿鲁高怎么得到的书","为什么书在影牙城堡"}},{q="《乌尔之书》与狼人诅咒有关吗？",a="是的。乌尔的研究详细描述了狼人起源的恐怖维度。阿鲁高利用这份论著将那些野兽释放到了银松森林，造成了困扰该地区的瘟疫般的灾难。",al={"狼人起源书籍","乌尔之书狼人"}}},fp="14,223,29.437.0,24.315.0,23.411.1,11.195.0,32.123.0,24.186.0,36.260.0,43.174.0,46.168.0"}
P.entries["quest:1014"] = {n="除掉阿鲁高",s="“阿鲁高必须死”是一项由瑟伯切尔的达拉尔·道恩维沃尔发布的决定性部落任务。任务要求勇敢的勇士们突袭影牙城堡，击杀流亡的大法师阿鲁高，并取回他的头颅。消灭阿鲁高对于Sylvanas Windrunner女士打破狼人威胁并为被遗忘者稳固银松森林至关重要。",h="“阿鲁高必须死”是一项由瑟伯切尔的达拉尔·道恩维沃尔发布的决定性部落任务。任务要求勇敢的勇士们突袭影牙城堡，击杀流亡的大法师阿鲁高，并取回他的头颅。消灭阿鲁高对于Sylvanas...",kw={"阿鲁高","达拉尔·道恩维沃尔","阿鲁高的头颅","瑟伯切尔","影牙城堡","银松森林","sylvanas","狼人"},ang={["class:Mage"]="与阿鲁高的对决是一个关于奥术傲慢的警示故事，它让魔法修行者们与一位因异界召唤而扭曲的肯瑞托法师展开了较量。",["faction:Horde"]="击败阿鲁高展示了部落在东部王国日益增长的军事影响力，这不仅击溃了一位盘踞在此的巫师，还打通了关键的道路。",["race:Undead"]="对于被遗忘者来说，消灭阿鲁高巩固了他们的西南边境，并确保了连接瑟伯切尔和幽暗城的路线安全。"},sec={{t="黑暗女王心头的一根刺",b="尽管被遗忘者已经在瑟伯切尔建立了一处基地，但银松森林依然险象环生，且争夺激烈。影牙城堡坐落在俯瞰森林的悬崖高处，那是大法师阿鲁高的巢穴。因内疚和黑暗魔法而陷入疯狂的阿鲁高，将野性的狼人释放到了洛丹伦。他那些贪婪的野兽在林间小道上游荡，直接阻碍了Sylvanas Windrunner女士在该地区建立坚固战略据点的努力。"},{t="扼住野兽的咽喉",b="达拉尔·道恩维沃尔意识到，仅仅猎杀森林中游荡的野兽永远无法净化这片土地。腐化的核心就在影牙城堡之内。部落的勇士们必须攻破这座古老的堡垒，杀穿阿鲁高忠诚的狼人族群，并在他的巢穴中直面这位疯狂的巫师。将他的头颅带回瑟伯切尔，终将粉碎他对该地区的魔法控制，为被遗忘者的统治扫清道路。"}},faq={{q="为什么达拉尔·道恩维沃尔想要阿鲁高死？",a="达拉尔·道恩维沃尔是奉黑暗女王之命行事。阿鲁高的狼人横行银松森林，除非杀死这位疯狂的法师，否则被遗忘者无法将该地区变成一个安全的战略据点。",al={"为什么要杀阿鲁高","达拉尔·道恩维沃尔的目标","阿鲁高目标"}},{q="阿鲁高在哪里？",a="大法师阿鲁高居住在影牙城堡的最顶端，这是一座俯瞰银松森林南部的阴森堡垒。",al={"阿鲁高在哪里","阿鲁高位置","寻找阿鲁高"}},{q="完成任务需要什么证明？",a="达拉尔·道恩维沃尔需要该巫师死亡的切实证据：勇士们必须取回并呈交阿鲁高的头颅。",al={"达拉尔需要什么","阿鲁高的头颅任务","死亡证明"}},{q="阿鲁高对部落构成了什么威胁？",a="除了强大的攻击性魔法外，阿鲁高还指挥着成群受诅咒的狼人，他们骚扰部落军队，并威胁着被遗忘者在整个银松森林的统治。",al={"阿鲁高为什么危险","银松森林的狼人威胁","阿鲁高是威胁吗"}},{q="达拉尔·道恩维沃尔效忠于谁？",a="达拉尔·道恩维沃尔效忠于Sylvanas Windrunner女士和被遗忘者，他在瑟伯切尔开展工作，以巩固被遗忘者在洛丹伦的统治。",al={"道恩维沃尔为谁工作","瑟伯切尔的领导层"}},{q="阿鲁高被击败后会怎样？",a="阿鲁高死后，他对银松森林邪恶的魔法控制将解除，这使得被遗忘者可以在无需担心他协调指挥的狼人兽群的情况下，将其统治范围扩大到整个洛丹伦西部。",al={"阿鲁高死后","阿鲁高之死的结果"}}},fp="15,184,31.394.0,30.335.0,43.162.0,26.87.0,47.86.0,42.164.0,32.143.0,38.167.1"}
P.entries["quest:1016"] = {n="元素护腕",s="水元素开始污染灰谷纯净的湖泊与溪流，这让驻扎在银风避难所的暗夜精灵感到困扰。哨兵维尔莉妮·星坠委托旅行者从这些生物身上收集完整的护腕，以便占卜出负责召唤它们的流氓施法者的身份。",h="水元素开始污染灰谷纯净的湖泊与溪流，这让驻扎在银风避难所的暗夜精灵感到困扰。哨兵维尔莉妮·星坠委托旅行者从这些生物身上收集完整的护腕，以便占卜出负责召唤它们的流氓施法者的身份。",kw={"灰谷","使用过的占卜卷轴","占卜卷轴","元素护腕","法师召唤者","密斯特拉湖","哨兵维尔莉妮·星坠","银风避难所"},ang={["class:Mage"]="被召唤元素佩戴的束缚物带有其主人独特的奥术特征，这使得受过训练的眼睛能够追溯鲁莽召唤行为的源头。",["faction:Alliance"]="协助银风哨兵有助于巩固联盟在灰谷中部交战腹地的地位。",["race:NightElf"]="灰谷的天然水池是圣地，看到奥术召唤者蓄意引入外部腐化，这对卡多雷来说是一种难以容忍的冒犯。"},sec={{t="被污染的水域",b="灰谷圣洁的水域正遭受非自然的枯萎病折磨，被流氓水元素大肆侵占。与这个世界上自然存在的野生灵魂不同，这些实体带有明显的受人工召唤的迹象。对于驻扎在银风避难所的哨兵而言，这些敌对元素的突然出现是一个令人担忧的信号，意味着外部腐化正愈发深入地侵蚀着森林纯净的水道。"},{t="占卜召唤者",b="哨兵维尔莉妮·星坠相信这些元素是被人蓄意束缚并释放的，于是她提供了一张魔法占卜卷轴来揭穿罪魁祸首。该法术需要与被召唤生物相关的原始试剂——具体来说，就是从灵魂消散前回收的完整护腕。通过将卷轴聚焦于这些附魔的束缚物上，魔法能够读取到最初召唤这些元素的始作俑者所留下的奥术特征。"},{t="法师的干预",b="一旦卷轴成功对完整的护腕施放，奥术残留便证实了维尔莉妮最担心的事：一名独行的法师正在蓄意制造腐化的元素并投入灰谷的水池中。这一发现激怒了暗夜精灵守卫，为迅速报复威胁森林神圣性的召唤者埋下了伏笔。"}},faq={{q="为什么灰谷会出现水元素？",a="困扰灰谷的敌对水元素并非与森林和谐共生的自然居民。它们是由外部施法者人工召唤出来的，扰乱了神圣的水池并激怒了暗夜精灵。",al={"为什么这里会有元素","灰谷水元素","元素从哪里来"}},{q="是谁发布了元素护腕这个任务？",a="该任务由哨兵维尔莉妮·星坠发布，她是一名驻扎在灰谷密斯特拉湖畔银风避难所的军官。",al={"任务发布者","谁开启元素护腕任务","在哪里接元素护腕任务"}},{q="占卜卷轴的用途是什么？",a="占卜卷轴是一种附魔羊皮纸，旨在读取元素身上残留的魔法特征。当对五个完整护腕使用时，它能追溯奥术纽带，找到创造它们的召唤者。",al={"卷轴有什么用","占卜卷轴用途","为什么要用占卜卷轴"}},{q="为什么只有完整的护腕才能用于仪式？",a="消灭元素通常会损坏或粉碎其魔法束缚护腕。只有保持完整的护腕才保留了足够的稳定奥术共鸣，供卷轴的魔法分析并揭示召唤者。",al={"为什么需要完整护腕","破损的护腕","完整的元素护腕"}},{q="占卜卷轴使用后会发生什么？",a="将使用过的占卜卷轴交还给哨兵维尔莉妮·星坠后，她会识别出负责此事的流氓施法者，并立即委托你在后续任务“法师召唤者”中追捕该召唤者。",al={"元素护腕后续","what comes next","元素护腕后的下一个任务"}},{q="为什么哨兵维尔莉妮如此在意这些元素？",a="暗夜精灵尊崇灰谷森林与水域的自然纯净。让一名凡人法师蓄意用腐化的元素污染并破坏他们湖泊的稳定性，是对他们守护职责的难以容忍的侮辱。",al={"哨兵维尔莉妮的动机","为什么暗夜精灵在意元素"}}},fp="17,231,14.320.0,21.401.0,19.325.1,44.187.0,38.126.0,43.164.0,47.200.0,39.183.1,61.197.0"}
P.entries["quest:1017"] = {n="召唤者",s="“法师召唤者”是联盟的一项突袭任务，由银风避难所的哨兵维尔莉妮·星坠指挥。在调查了密斯特拉湖附近的受腐蚀水元素之后，哨兵派遣冒险者越过边界进入贫瘠之地，在鬼雾峰上处决亡灵法师萨利鲁斯·福尔波恩。",h="“法师召唤者”是联盟的一项突袭任务，由银风避难所的哨兵维尔莉妮·星坠指挥。在调查了密斯特拉湖附近的受腐蚀水元素之后，哨兵派遣冒险者越过边界进入贫瘠之地，在鬼雾峰上处决亡灵法师萨利鲁斯·福尔波恩。",kw={"灰谷","鬼雾峰","月神之光","萨利鲁斯·福尔波恩","银风避难所","贫瘠之地","维尔莉妮·星坠","水元素"},ang={["class:Mage"]="与福尔波恩的对抗，是联盟纪律严明的奥术师与一名将元素召唤术扭曲到鲁莽极致的流亡亡灵施法者之间的较量。",["class:Priest"]="直接从哨兵手中获得月神之光，将该任务与女神对抗亡灵腐蚀的稀有奇迹恩典联系在了一起。",["faction:Alliance"]="对贫瘠之地深处的被遗忘者目标进行打击，是一次大胆的Show of Force，以此反击部落对灰谷南部边境的入侵。",["race:NightElf"]="萨利鲁斯在森林边界对自然进行的奥术亵渎是对卡多雷的侮辱，因此对他的处决既关乎森林平衡，也关乎种族的尊严。"},sec={{t="越境",b="除非事态紧急，否则暗夜精灵很少向南派遣侦察兵深入贫瘠之地那片被烈日炙烤的大草原。在调查了密斯特拉湖周围水元素的不自然骚动后，哨兵维尔莉妮·星坠将这些干扰直接追踪到了萨利鲁斯·福尔波恩身上，他是一名在边界另一侧练习技艺的被遗忘者施法者。对于守护银风避难所的哨兵们来说，让敌方巫师在他们的家门口亵渎自然是无法容忍的。"},{t="山峰上的施法者",b="萨利鲁斯·福尔波恩在鬼雾峰高处安营扎寨，那是一座布满火刃氏族邪教徒的崎岖山峰。他从高处召唤并强迫大量水元素屈服于他的意志，在部落控制的土地上嘲弄暗夜精灵的权威。要除掉他，就必须深入敌后，击溃他召唤的部队，并割下他的头颅，以此证明哨兵的复仇之火足以跨越森林的边界。"},{t="月神之赐",b="在收到福尔波恩的头颅后，维尔莉妮·星坠抹去了这位巫师的嘲弄，并给予击杀者一份非凡的礼物：月神之光。这种神圣的月光药剂是女祭司和哨兵们珍视的护身符，能在面临死亡时提供绝对的无敌状态。它是暗夜精灵对抗蔓延至卡利姆多的邪恶魔法时，所获神圣庇护的有力证明。"}},faq={{q="萨利鲁斯·福尔波恩是谁？",a="萨利鲁斯·福尔波恩是一位逃入贫瘠之地并在鬼雾峰定居的亡灵法师。他利用奥术召唤奴役水元素，引来了附近灰谷哨兵们的愤怒。",al={"萨利鲁斯·福尔波恩","法师召唤者是谁","福尔波恩背景故事"}},{q="鬼雾峰位于哪里？",a="鬼雾峰是一座位于贫瘠之地北部、灰谷边界以南的著名崎岖山峰。萨利鲁斯·福尔波恩就在其最高处等待着。",al={"鬼雾峰在哪里","鬼雾峰位置","如何找到鬼雾峰"}},{q="为什么哨兵维尔莉妮·星坠想要萨利鲁斯死？",a="萨利鲁斯一直在灰谷边界附近亵渎和腐蚀水元素。维尔莉妮无法容忍他的傲慢，并试图终结他的非自然召唤术，同时证明敌人无法越过边界嘲弄哨兵。",al={"为什么要杀萨利鲁斯","维尔莉妮·星坠的动机"}},{q="作为奖励给予的“月神之光”是什么？",a="月神之光是一瓶罕见的、受过神圣月光祝福的消耗品。在危急时刻饮用，可以在短时间内使使用者免疫所有伤害和法术效果，从而使他们免于必死的命运。",al={"月神之光药水","月神之光背景故事"}},{q="这个任务之前有什么任务？",a="该任务紧随“元素护腕”之后，在该任务中，冒险者需要从灰谷密斯特拉湖周围的占卜水元素身上收集完好的护腕，以帮助维尔莉妮查明是谁在操纵它们。",al={"法师召唤者的前置任务","法师召唤者之前的任务"}},{q="为什么进入贫瘠之地对联盟玩家来说很危险？",a="贫瘠之地是部落的领土，是牛头人和兽人的家园。进入该地区的联盟士兵和冒险者有被部落巡逻队和敌对勇士拦截的风险。",al={"贫瘠之地危险吗","部落领地任务"}}},fp="13,266,21.416.0,24.422.0,17.314.1,25.206.0,32.146.0,54.233.0,45.195.0,29.180.0,59.164.0"}
P.entries["quest:102"] = {n="西部荒野的豺狼人",s="“巡视西部荒野”是由哨兵岭的丹努文队长发布的一项赏金任务。由于对暴风城缺乏军事援助感到沮丧，当地的人民民兵招募志愿人员来清理在草原上游荡的侵略性豺狼人部族。丹努文怀疑这些食腐动物已经与盘踞在死亡矿井里的盗贼团伙结盟了。",h="“巡视西部荒野”是由哨兵岭的丹努文队长发布的一项赏金任务。由于对暴风城缺乏军事援助感到沮丧，当地的人民民兵招募志愿人员来清理在草原上游荡的侵略性豺狼人部族。丹努文怀疑这些食腐动物已经与盘踞在死亡矿井里的盗贼团伙结盟了。",kw={"丹努文","死亡矿井","豺狼人","爪子","人民民兵","哨兵岭","暴风城","西部荒野"},ang={["faction:Alliance"]="这次巡视凸显了西部荒野陷入困境的农村农民与统治Stormwind Keep的冷漠贵族之间深刻的政治鸿沟。",["race:Human"]="对于人类而言，目睹西部荒野的金色田野被野蛮的豺狼人部族所蹂躏，这痛苦地提醒着人们：在近期的战争之后，王国的恢复依然是多么脆弱。"},sec={{t="被王权抛弃",b="哨兵岭是西部荒野最后一道有组织的防线，但其守军并不听从Stormwind Keep发出的皇家指令。由于首都拒绝派遣军队来保卫外围农田，当地民众组成了人民民兵。丹努文队长本人曾是一位农民，他拒绝放弃自己的家园。由于缺乏正规军，民兵组织主要依靠过往的旅行者和冒险者来防止防线彻底崩溃。"},{t="草原上的食腐者",b="豺狼人长期潜伏在人类文明的边缘，但它们在西部荒野日益猖獗的行径对那些勉强维持生存的难民和擅自居住者构成了直接威胁。更糟糕的是，丹努文的侦察兵报告说，这些野兽部族似乎正在与在死亡矿井中活动的强盗协同行动。通过派遣猎人收集豺狼人的爪子，丹努文旨在压制它们不断扩张的巡逻范围，并瓦解这些野兽与法外之徒之间形成的某种合作。"}},faq={{q="谁是丹努文队长？",a="丹努文队长是驻扎在哨兵岭的防御指挥官之一。他曾经是一名当地农民，在暴风城撤回官方支持后，他挺身而出领导志愿者进行防御，并发誓永远不会抛弃仍留在西部荒野的公民。",al={"丹努文队长","谁是丹努文","哨兵岭任务发布者"}},{q="为什么是人民民兵在与豺狼人作战，而不是暴风城的士兵？",a="暴风城的贵族议会对西部荒野的困境基本上视而不见，导致该地区没有皇家士兵驻守。流离失所的农民和劳工不得不组建人民民兵，以保卫自己的土地免受强盗和野兽的侵害。",al={"为什么没有暴风城军队","暴风城卫兵在哪里","为什么会有民兵"}},{q="西部荒野的豺狼人是有组织的吗？",a="虽然豺狼人以混乱的食腐习性而闻名，但丹努文队长注意到了一些令人不安的迹象，表明这些部族正在与在死亡矿井中活动的盗贼进行协作，实际上充当了这个犯罪集团的外围缓冲力量。",al={"豺狼人是否与迪菲亚兄弟会合作","豺狼人联盟","死亡矿井盗贼与豺狼人"}},{q="为什么丹努文队长要收集豺狼人的爪子？",a="各个王国的赏金任务都需要确认击杀的实物证明。豺狼人的爪子是这些漫游野兽已被永久从草原上清除的铁证。",al={"为什么收集豺狼人爪子","爪子赏金","击杀证明"}},{q="豺狼人通常在哪里出没？",a="豺狼人的狩猎队和营地散布在西部荒野的中部和南部平原，经常在废弃农庄周围的开阔地带和山坡附近游荡。",al={"豺狼人地点","在西部荒野哪里可以找到豺狼人"}},{q="一旦豺狼人的威胁被击退，会发生什么？",a="人民民兵希望通过不断削减豺狼人和不法之徒的数量，最终能够收复这些平原，并将其恢复成曾经滋养王国的繁荣粮仓。",al={"西部荒野下一步","民兵目标","暴风城的粮仓"}}},fp="19,206,22.417.0,32.309.0,23.188.0,74.219.0,37.190.0,44.110.0,37.156.0,50.157.0"}
P.entries["quest:1020"] = {n="奥雷迪尔的药剂",s="“奥雷迪尔的药剂”是一项紧急递送任务，由草药师奥雷迪尔·阔叶委托给联盟旅行者。在利用稀有植物配制出解药后，奥雷迪尔派遣信使沿着林间道路飞速赶往阿斯特兰纳，以挽救一名垂死的暗夜精灵孩童。",h="“奥雷迪尔的药剂”是一项紧急递送任务，由草药师奥雷迪尔·阔叶委托给联盟旅行者。在利用稀有植物配制出解药后，奥雷迪尔派遣信使沿着林间道路飞速赶往阿斯特兰纳，以挽救一名垂死的暗夜精灵孩童。",kw={"灰谷","阿斯特兰纳","巴斯兰的头发","解药","奥雷迪尔·阔叶","皮尔图拉斯·怀特姆恩","relara"},ang={["class:Priest"]="虽然草药为Relara提供了暂时的身体缓解，但这种挥之不去的疾病很快就需要艾露恩的神圣干预和月亮仪式。",["profession:Herbalism"]="这次递送展示了原始植物学与战场医疗之间的关键界限，凸显了像巴斯兰的头发这样采集自灰谷的草药如何维系着一个孩子的生命。",["race:NightElf"]="对于卡多雷来说，保护阿斯特兰纳意味着守护它的后代；帮助皮尔图拉斯和Relara触及了暗夜精灵在充满纷争的森林中生存的核心。"},sec={{t="父亲的绝望",b="在阿斯特兰纳的中心定居点，皮尔图拉斯·怀特姆恩守护着他的女儿Relara，看着她因一种严重而神秘的疾病日渐消瘦。面对当地知识的局限，皮尔图拉斯在荒野灰谷中四处求援，向远方的草药师寻求智慧，以免希望彻底破灭。"},{t="林间竞速",b="在成功获取了必要的成分——特别是巴斯兰的头发——之后，奥雷迪尔·阔叶配制出了一种能够抑制这种疾病的特制药剂。奥雷迪尔将这瓶脆弱的解药托付给了一位路过的冒险者，并指引他们沿着林间主干道向东南方向行进，务必在为时已晚之前将其送达。"},{t="脆弱的喘息",b="虽然奥雷迪尔的药剂为Relara提供了急需的缓解，但这草药疗法并非根治她精神深处那种超自然恶疾的永久方案。递送药剂争取到了宝贵的时间，这也开启了在古老的卡多雷废墟中寻找受月神艾露恩祝福的神圣遗物的更广泛搜寻，以彻底拯救她。"}},faq={{q="谁在阿斯特兰纳生病了？",a="Relara Whitemoon，皮尔图拉斯·怀特姆恩的幼女，正卧病在阿斯特兰纳。她的病情危急，这让她的父亲迫切需要任何能阻止她病情恶化的药剂。",al={"谁生病了","谁需要解药","阿斯特兰纳生病的孩童"}},{q="谁配制了“奥雷迪尔的药剂”？",a="奥雷迪尔·阔叶，一位驻扎在北灰谷的熟练暗夜精灵草药师，在收到从巴斯兰鬼屋采集的植物后，配制了这种药剂。",al={"谁制作了药剂","奥雷迪尔·阔叶","药剂来自哪里"}},{q="皮尔图拉斯·怀特姆恩在哪里？",a="皮尔图拉斯·怀特姆恩居住在阿斯特兰纳，这是位于灰谷中部、坐落在主干道沿线的联盟主要城镇。他就在林间住所之一内守护着女儿的病榻。",al={"皮尔图拉斯的位置","皮尔图拉斯在哪里","寻找阿斯特兰纳的皮尔图拉斯"}},{q="“奥雷迪尔的药剂”能完全治愈Relara吗？",a="不能。虽然这草药剂成功稳定了Relara的即时病情，并带给了她父亲新的希望，但她的疾病需要更深层的精神干预，这促使旅行者去寻找月神之泪。",al={"relara治愈了吗","药剂有效果吗","药剂结果"}},{q="配制这种解药使用了什么成分？",a="主要成分是巴斯兰的头发，这是一种稀有而强效的植物，采集自迈斯特拉岗哨以北、巴斯兰鬼屋那片被诅咒的土地。",al={"药剂成分","药剂由什么制成","巴斯兰的头发"}},{q="为什么阿斯特兰纳的当地治疗者没有自己配制这种解药？",a="Relara的病症对阿斯特兰纳的日常药物产生了抗性，这促使皮尔图拉斯求助于奥雷迪尔·阔叶的专业植物学知识，他知道如何处理北灰谷中发现的强效植物。",al={"为什么找奥雷迪尔","为什么阿斯特兰纳的治疗者失败了","为什么找阔叶"}}},fp="14,149,18.206.0,27.238.0,17.230.1,25.154.0,26.142.0,36.177.0,43.171.1,47.118.0,62.199.0"}
P.entries["quest:1021"] = {n="身陷危险的树妖！",s="“萨特之患！树妖的危机！”是联盟在灰谷由树妖伊莉亚娜开启的一项紧急任务。她急需援助，因此招募旅行者去寻找她那些失踪的姐妹，她们为了夺回一件被盗的圣物，冒险进入了遭受腐化的萨维亚废墟。",h="“萨特之患！树妖的危机！”是联盟在灰谷由树妖伊莉亚娜开启的一项紧急任务。她急需援助，因此招募旅行者去寻找她那些失踪的姐妹，她们为了夺回一件被盗的圣物，冒险进入了遭受腐化的萨维亚废墟。",kw={"安妮莉亚","灰谷","塞纳留斯的树枝","塞纳留斯","树妖","伊莉亚娜","萨特","萨维亚"},ang={["class:Druid"]="德鲁伊与塞纳留斯的后代有着深厚的血缘羁绊，并誓要清除从萨维亚这样的萨特据点中蔓延开来的恶魔腐化。",["faction:Alliance"]="在区域威胁不断升级的情况下，帮助伊莉亚娜加强了联盟与灰谷神秘居民之间的联系。",["race:NightElf"]="树妖是塞纳留斯神圣的女儿，她们的困境以及萨维亚古老精灵神殿遭受的亵渎，不仅关乎个人荣誉，更是精神上的职责所在。"},sec={{t="绝望的姐妹",b="在灰谷休息时，树妖伊莉亚娜心急如焚。她的一群树妖姐妹为了夺回被邪恶萨特窃走的圣物——塞纳留斯的树枝，踏入了森林北部那片遭受腐化的险地，执行一项危险的任务。尽管她们承诺会迅速返回，但如今已经过了两天，却音信全无。伊莉亚娜不得不恳求路过的联盟旅行者在为时已晚之前找到她们。"},{t="萨维亚废墟",b="树妖们的目标是位于东北方向的萨维亚，那是一处古老的暗夜精灵神殿建筑群，长期以来一直笼罩在燃烧军团挥之不去的腐化阴影之下。萨维亚挤满了受邪能污染的萨特，是一个极其危险的狩猎场。深入这些废墟，便能直接找到树妖探险队的领队安妮莉亚，她在遭受了废墟中恶魔居民的残酷暴行后，身受重伤，奄奄一息。"}},faq={{q="伊莉亚娜是谁？",a="伊莉亚娜是居住在灰谷森林中的一名树妖。她因担忧姐妹们的命运而焦虑不安，于是派遣旅行者前往萨维亚废墟寻找她们失踪的队伍。",al={"伊莉亚娜","谁给予萨特之患任务","任务发放者"}},{q="塞纳留斯的树枝是什么？",a="塞纳留斯的树枝是树妖和暗夜精灵极其珍视的一件圣物。灰谷北部的萨特窃走了它，导致安妮莉亚和她的姐妹们不得不前往萨维亚，执行一项危险的夺回任务。",al={"塞纳留斯的树枝","她们在寻找什么圣物","树妖神器"}},{q="萨维亚是什么？",a="萨维亚是一座古老的暗夜精灵神殿的废墟，位于灰谷东部。该地被邪恶的萨特所占据，充斥着邪能腐化，对自然的守护者充满敌意。",al={"萨维亚","萨维亚废墟","树妖在哪里"}},{q="安妮莉亚是谁？",a="安妮莉亚是率领搜寻队从萨特手中夺回塞纳留斯的树枝的树妖领队。伊莉亚娜请求旅行者在萨维亚找到她。",al={"安妮莉亚","失踪的树妖领队","安妮莉亚在哪里"}},{q="为什么树妖与萨特之间存在冲突？",a="树妖是半神塞纳留斯的女儿，致力于保护自然和森林的平衡。萨特是受到邪恶恶魔魔法扭曲的古老暗夜精灵，他们积极地腐化荒野并亵渎神圣的林地。",al={"为什么树妖憎恨萨特","树妖与萨特的战争","萨特腐化"}},{q="此任务的后续任务是什么？",a="找到安妮莉亚即可完成此搜寻任务，并开启“塞纳留斯的树枝”任务，继续夺回被盗圣物的努力。",al={"下一个任务","树妖的危机任务链","萨特之患之后"}}},fp="29,163,18.358.0,19.312.1,16.152.0,31.200.0,15.150.0,14.142.1,46.222.0,28.132.1"}
P.entries["quest:1022"] = {n="狼嚎谷",s="这项任务由艾森娜神殿的哨兵梅丽瑞亚·霜影指派，派遣联盟探险者前往费伍德森林边界附近的狼嚎谷。梅尔桑德里斯神殿的废墟已经被被称为狼人的凶猛狼人所占据。通过查阅神圣的梅尔桑德里斯之书，调查者们希望能揭开这些奇异生物出现在灰谷的原因。",h="这项任务由艾森娜神殿的哨兵梅丽瑞亚·霜影指派，派遣联盟探险者前往费伍德森林边界附近的狼嚎谷。梅尔桑德里斯神殿的废墟已经被被称为狼人的凶猛狼人所占据。通过查阅神圣的梅尔桑德里斯之书，调查者们希望能揭开这些奇异生物出现在灰谷...",kw={"灰谷","费伍德森林","狼嚎谷","梅尔桑德里斯","梅丽瑞亚·霜影","艾露恩之镰","恐怖狼","梅尔桑德里斯之书","维琳德·星歌","狼人"},ang={["class:Priest"]="牧师们会发现对女祭司维琳德·星歌的搜寻是一个关于对艾露恩虔诚信仰的警示故事。",["faction:Alliance"]="对狼嚎谷的调查标志着联盟开始寻找那些潜伏在卡利姆多北部和东部王国的恐怖狼人野兽的起源。",["race:NightElf"]="梅尔桑德里斯神殿的亵渎和女祭司维琳德·星歌的悲剧幻象，直击暗夜精灵保护灰谷免受奇怪诅咒这一神圣职责的核心。"},sec={{t="令人胆寒的现身",b="当暗夜精灵哨兵们消耗大量资源以抵御从费伍德森林溢出的恶魔腐蚀时，一个全新的威胁已经悄然在灰谷北部的山丘中扎根。梅尔桑德里斯神殿的废墟隐藏在费伍德森林边界附近的一条洞穴小径之后，现在已落入凶猛的狼人之手，它们令人毛骨悚然的嚎叫声在树冠间回荡。该地区现在被称为狼嚎谷，哨兵梅丽瑞亚·霜影担心这种野兽的泛滥可能预示着这片林地王国将迎来另一场灾难。"},{t="活着的编年史",b="为了了解这些野兽的起源，梅丽瑞亚指引探索者们去寻找位于被占领神殿内的梅尔桑德里斯之书。这本书绝非普通的文献；其书页由梅尔桑德里斯本人亲自祝福，能够超自然地记录并重现重大事件。当在充满敌意的狼人中间打开时，该神器会召唤出女祭司维琳德·星歌的灵魂幻象，揭示出被称为艾露恩之镰的神器那充满宿命感的召唤过程。"}},faq={{q="狼嚎谷在哪里？",a="狼嚎谷位于灰谷的中北部，就在费伍德森林边界的西南方。一条洞穴通道通向隐秘的山谷和梅尔桑德里斯神殿的废墟。",al={"狼嚎谷位置","如何前往狼嚎谷","梅尔桑德里斯神殿在哪里"}},{q="山谷里的狼人是什么？",a="这些野蛮的狼人是狼人的一种，具体来说是恐怖狼群的成员。它们是突然出现在卡利姆多的非自然的、凶猛的类人野兽，在费伍德森林边境附近的废墟中制造恐怖。",al={"灰谷狼人","狼嚎谷里的怪物是什么","恐怖狼人"}},{q="什么是梅尔桑德里斯之书？",a="梅尔桑德里斯之书是一件安放在神殿废墟中的附魔遗物。它并非像普通书籍那样书写，其书页由梅尔桑德里斯祝福过，可以直接向研读者记录并投射关键历史时刻的幻象。",al={"梅尔桑德里斯之书","书的作用"}},{q="维琳德·星歌是谁？",a="维琳德·星歌是一位与费伍德森林附近对抗恶魔的斗争有关的暗夜精灵女祭司。梅尔桑德里斯之书或许能提供关于她故事的线索。",al={"维琳德·星歌","女祭司维琳德","书中的幽灵是谁"}},{q="是谁发布了这个任务？",a="哨兵梅丽瑞亚·霜影在灰谷的艾森娜神殿发布此任务。她对来自费伍德森林的恶魔入侵以及附近无法解释的狼人出现深感担忧。",al={"谁开启狼嚎谷任务","狼嚎谷任务发布者","梅丽瑞亚·霜影"}},{q="为什么哨兵梅丽瑞亚关心这座神殿？",a="灰谷的哨兵们是抵御费伍德森林腐蚀的堡垒。当神秘的狼人在边界处暴力占据了一座古老的暗夜精灵圣地时，哨兵们必须查明这究竟是恶魔的阴谋还是全新的危险。",al={"为什么要调查狼嚎谷","林歌神殿哨兵"}}},fp="16,146,19.335.0,20.319.1,34.164.0,34.196.0,33.171.0,25.151.1,21.171.0,48.220.0"}
P.entries["quest:1023"] = {n="莱恩的净化",s="此任务标志着寻找泰洛尼斯的悲剧性延续，他是一名被派往法拉希姆湖的暗夜精灵哨兵。在岸边发现他的遗体后，任务转变为回收他的研究日记并从当地鱼人手中取回发光的宝石，最后将这令人悲伤的消息带回阿斯特兰纳。",h="此任务标志着寻找泰洛尼斯的悲剧性延续，他是一名被派往法拉希姆湖的暗夜精灵哨兵。在岸边发现他的遗体后，任务转变为回收他的研究日记并从当地鱼人手中取回发光的宝石，最后将这令人悲伤的消息带回阿斯特兰纳。",kw={"灰谷","阿斯特兰纳","发光的宝石","法拉希姆湖","鱼人","莱恩的净化","哨兵","泰洛尼斯"},ang={["faction:Alliance"]="保卫阿斯特兰纳的北部入口并协助莱恩·狼行者，巩固了联盟与守卫灰谷的哨兵之间的联系。",["race:NightElf"]="一名哨兵在法拉希姆湖的死亡，凸显了威胁着卡利姆多古老圣林的蔓延危机。"},sec={{t="堕落的侦察兵",b="The Adventurer受莱恩·狼行者之托前往法拉希姆湖，却在水边发现了泰洛尼斯的尸体。任务不再是救援，而是变成了遗物回收与调查。在他的随身物品中，有一本完整的日记，详细记录了他的指派任务以及关于灰谷奇怪动荡的发现。"},{t="发光的宝石",b="泰洛尼斯追踪一颗稀有的发光石至湖边，但这颗石头落入了盘踞在浅滩的暴躁鱼人手中。为了完成这位已故侦察兵原本的任务，回收泰洛尼斯的日记和那颗被抢走的宝石是必须的。"},{t="阿斯特兰纳的悲伤",b="回到阿斯特兰纳后，莱恩·狼行者陷入了悲伤，她必须组织巡逻队来回收她那牺牲的同伴的遗体。然而，面对森林的腐化，莱恩无法承担长久的哀悼，她请求The Adventurer接过泰洛尼斯的职责，完成他至死都在追求的任务：重建那根他希望能够减缓熊怪攻击的法杖。"}},faq={{q="泰洛尼斯是谁？",a="泰洛尼斯是一名由莱恩·狼行者从阿斯特兰纳派出的暗夜精灵侦察兵。他被指派调查法拉希姆湖的水域并获取一颗神秘的宝石，但在完成使命之前，他被当地敌对的野生生物围攻并杀害了。",al={"泰洛尼斯","泰洛尼斯是谁","泰洛尼斯背景故事"}},{q="在哪里可以找到发光的宝石？",a="发光的宝石由栖息在灰谷西北部法拉希姆湖岸边和水中的鱼人携带，就在发现泰洛尼斯的尸体的地方附近。",al={"发光的宝石在哪里","发光的宝石位置","寻找发光的宝石"}},{q="为什么莱恩·狼行者如此专注于这项任务？",a="泰洛尼斯是莱恩的老友，他相信他所寻找的法杖能够减缓熊怪对她族人的攻击。鉴于灰谷的熊怪仍在袭击，尽管泰洛尼斯已经牺牲，莱恩仍将他未竟的使命视为重中之重。",al={"为什么莱恩的净化","莱恩·狼行者的动机"}},{q="任务完成后泰洛尼斯的遗体怎么处理？",a="莱恩·狼行者承诺会派遣一队阿斯特兰纳的哨兵去妥善回收泰洛尼斯的遗体，以便进行哀悼和传统的暗夜精灵葬礼仪式。",al={"泰洛尼斯的尸体结局","泰洛尼斯发生了什么"}},{q="泰洛尼斯的日记有什么用？",a="这本记录了泰洛尼斯对人类法师达索尔的调查，达索尔曾试图利用德鲁伊魔法来结交并控制熊怪，日记中还记录了他关于找回达索尔所造法杖碎片的笔记。",al={"泰洛尼斯的日记","什么是日记"}},{q="这个任务链在交还任务后还会继续吗？",a="是的。当把宝石和日记带回给莱恩·狼行者后，她会请你继续泰洛尼斯的工作，从而开启寻找达索尔法杖剩余碎片的任务。",al={"任务进度","泰洛尼斯之后的任务"}}},fp="17,257,14.251.0,15.182.0,18.281.1,16.183.0,31.121.0,48.213.0,47.156.0,29.202.0,51.146.0"}
P.entries["quest:1024"] = {n="莱恩的净化",s="作为调查灰谷腐蚀过程中的中间环节，这一步会将联盟冒险者派遣至伊瑞斯湖以东的神圣树林深处。你受托携带一颗寻回的“发光的宝石”，必须去请教树妖莎尔蒂恩，了解如何修复达图尔的远古之杖。",h="作为调查灰谷腐蚀过程中的中间环节，这一步会将联盟冒险者派遣至伊瑞斯湖以东的神圣树林深处。你受托携带一颗寻回的“发光的宝石”，必须去请教树妖莎尔蒂恩，了解如何修复达图尔的远古之杖。",kw={"灰谷","达图尔之杖","发光的宝石","伊瑞斯湖","月亮井","莱恩·狼行者","莱恩的净化","莎尔蒂恩","泰罗尼斯"},ang={["class:Druid"]="协助树妖莎尔蒂恩直接符合塞纳里奥议会的职责，即修复自然与卡多雷魔法之间破碎的纽带。",["faction:Alliance"]="加固阿斯特兰纳的北部防线并确保远古神器的安全，有助于联盟对抗日益增长的区域性威胁。",["race:NightElf"]="修复这根长杖将继续泰罗尼斯未竟的事业，即调查灰谷熊怪所面临的问题。"},sec={{t="泰罗尼斯笔记中的线索",b="在哨兵泰罗尼斯不幸身亡后，莱恩·狼行者仔细查阅了他留下的笔记。他的研究表明，调查灰谷境内陷入困境的熊怪可能需要一件远古神器：一根很久以前由一名叫达图尔的暗夜精灵所制的长杖。由于手中只有一颗“发光的宝石”，莱恩坦言她作为猎手的战术专长并不擅长解读失落的奥术与自然之谜。"},{t="寻找塞纳留斯的女儿",b="为了不再对达图尔之杖其余部分的下落进行猜测，莱恩指引旅行者向东北方向前往伊瑞斯湖。在静谧的月亮井旁隐居着树妖莎尔蒂恩，她与森林的自然沟通使她对远古圣物有着深刻的洞察力。通过将宝石交给她，冒险者希望能找到缺失的组件并知晓如何重铸这根长杖。"}},faq={{q="泰罗尼斯是谁？",a="泰罗尼斯是阿斯特兰纳派遣的一名暗夜精灵斥候，负责调查在灰谷蔓延的邪恶腐蚀。尽管他在任务中不幸丧生，但他留下的日志提供了关键线索，表明修复达图尔之杖或许能帮助这片土地。",al={"泰罗尼斯","泰罗尼斯笔记","泰罗尼斯是谁"}},{q="什么是达图尔之杖？",a="达图尔之杖是一件远古魔法神器，莱恩·狼行者希望它能协助她调查灰谷的熊怪。寻回的“发光的宝石”是修复它所需的组件之一。",al={"达图尔之杖","长杖是什么","达图尔的长杖"}},{q="我在哪里可以找到莎尔蒂恩？",a="莎尔蒂恩居住在阿斯特兰纳东北部的一口僻静月亮井旁，位于伊瑞斯湖正东方的山丘中。最安全的路径是沿着道路向东走，在到达林中树居附近的危险区域之前向北转向。",al={"莎尔蒂恩在哪里","莎尔蒂恩位置","寻找树妖"}},{q="什么是发光的宝石？",a="“发光的宝石”是达图尔之杖不可或缺的组成部分，它是从泰罗尼斯那次注定失败的调查遗迹中寻回的。它与强大的魔法产生共鸣，莎尔蒂恩需要用它来占卜出长杖其余部分的下落。",al={"发光的宝石","宝石有什么用","泰罗尼斯的宝石"}},{q="为什么莱恩·狼行者要派你去找一位树妖？",a="作为一名猎手兼阿斯特兰纳哨兵领袖，莱恩专注于军事防御。理解远古圣物的锻造和自然的修复属于树妖——也就是塞纳留斯的女儿们——所掌管的精神领域。",al={"为什么见树妖","莱恩·狼行者 树妖","为什么是莎尔蒂恩"}},{q="为什么伊瑞斯湖周围的森林处于危险之中？",a="灰谷的野生生物和熊怪部族正面临蔓延的腐蚀和动荡。莱恩希望修复这根长杖能帮助她进一步了解熊怪的困境。",al={"灰谷腐蚀","灰谷为什么被腐蚀","伊瑞斯湖的危险"}}},fp="17,186,25.339.0,33.282.0,16.217.0,21.184.0,28.193.0,24.154.0,46.190.0,45.159.0"}
P.entries["quest:1025"] = {n="先发制人",s="“积极的防御”是一项联盟任务，由阿斯特兰纳的哨兵莱恩·狼行者发布。面对灰谷主要干道上猖獗的熊怪腐化，暗夜精灵被迫对陷入疯狂的木喉部族采取主动的清理行动。",h="“积极的防御”是一项联盟任务，由阿斯特兰纳的哨兵莱恩·狼行者发布。面对灰谷主要干道上猖獗的熊怪腐化，暗夜精灵被迫对陷入疯狂的木喉部族采取主动的清理行动。",kw={"灰谷","阿斯特兰纳","弗伦河","木喉","熊怪","莱恩·狼行者","哨兵"},ang={["class:Druid"]="德鲁伊们将木喉的疯狂视为对困扰卡利姆多神圣荒野圣地的邪能污染的一个痛苦提醒。",["faction:Alliance"]="清除木喉熊怪保护了连接阿斯特兰纳与灰谷东部哨所的关键联盟补给和运输通道。",["race:NightElf"]="对于卡多雷而言，处决木喉部族是一个源于悲剧的痛苦必要之举，他们不得不将利刃挥向那些已经彻底因腐化而丧失理智的昔日森林同胞。"},sec={{t="对公路的威胁",b="从阿斯特兰纳向东延伸至弗伦河的道路是贯穿灰谷的一条重要生命线，但现在它变得极其危险。受恶魔腐化而陷入疯狂的熊怪开始直接在主路附近劫掠旅人。哨兵莱恩·狼行者没有选择单纯地加固路障等待下一次伏击，而是派遣有能力的冒险者去摧毁位于公路南侧的木喉营地。"},{t="痛苦的历史",b="击杀木喉熊怪对于暗夜精灵来说有着沉重的意义。在远古时代，这些熊人曾是卡多雷长期的朋友和盟友，共同敬畏着自然和荒野之神。然而，燃烧军团入侵所留下的挥之不去的污秽摧毁了许多部族的心智，将曾经和平的邻居变成了暴力威胁无辜旅人的嗜血掠夺者。"}},faq={{q="谁提供了这项任务？他们位于何处？",a="该任务由驻扎在阿斯特兰纳的哨兵指挥官莱恩·狼行者提供，阿斯特兰纳是灰谷中部主要的暗夜精灵定居点。",al={"任务发布者","谁发布积极的防御任务","莱恩·狼行者位置"}},{q="为什么灰谷的熊怪具有敌意？",a="木喉部族和其他散布在卡利姆多的熊怪部族一样，屈服于燃烧军团在第三次战争期间留下的恶魔污秽。他们的心智变得扭曲而狂暴，驱使他们屠杀旅人并攻击曾经的盟友。",al={"为什么熊怪发疯","木喉敌对","熊怪腐化"}},{q="木喉营地在哪里？",a="他们的营地位于从阿斯特兰纳向东延伸的主路南侧，坐落在弗伦河以西。",al={"木喉位置","在哪里找到木喉","熊怪在哪里"}},{q="熊怪一直是暗夜精灵的敌人吗？",a="不。几千年来，熊怪和暗夜精灵一直和谐共处。直到恶魔腐化席卷了灰谷和费伍德森林，木喉这样的部族才失去了理智并变得充满敌意。",al={"熊怪与暗夜精灵的传说","熊怪曾经是好的吗","卡多雷与熊怪"}},{q="这项任务与阿斯特兰纳的其他事件有关联吗？",a="是的。莱恩·狼行者在发布这项临时防御任务的同时，也在引导英雄们调查受腐化的月亮井，并进行更大范围的森林净化工作。",al={"任务前置条件","莱恩与净化任务的联系"}},{q="必须消灭哪些具体的熊怪？",a="莱恩要求清理一个木喉巢穴看守者、两个巨熊怪、十个图腾怪和十二个战士，以瓦解他们的指挥结构并驱散公路附近的威胁。",al={"任务目标","我要杀谁","木喉目标"}}},fp="21,160,21.289.0,16.315.0,48.117.0,42.164.0,36.96.0,52.172.0,53.141.0,42.144.0"}
P.entries["quest:1026"] = {n="莱恩的净化",s="这个任务是修复达图尔的变形魔棒这一关键步骤，这是莱恩·狼行者正在寻找的一件古老的暗夜精灵神器。在莎尔蒂恩的月井指引下，冒险者们必须向北前往费伍德森林那邪恶的边缘，从一个隐藏的宝箱中取回一根铁杆。这项任务带着一丝悲剧色彩，迫使联盟不得不面对守护着钥匙的堕落远古守护者。",h="这个任务是修复达图尔的变形魔棒这一关键步骤，这是莱恩·狼行者正在寻找的一件古老的暗夜精灵神器。在莎尔蒂恩的月井指引下，冒险者们必须向北前往费伍德森林那邪恶的边缘，从一个隐藏的宝箱中取回一根铁杆。这项任务带着一丝悲剧色彩，...",kw={"灰谷","疯狂的古树","达图尔的魔棒","费伍德森林","铁杆","月井","莱恩的净化","莎尔蒂恩","枯萎的古树","木制钥匙"},ang={["class:Druid"]="目睹远古守护者因费伍德森林蔓延的腐蚀而陷入疯狂，这深刻地提醒了我们翡翠梦境在治愈受伤的地表世界时所面临的艰辛。",["faction:Alliance"]="重建达图尔的遗物对于保卫灰谷北部的道路网络，对抗日益猖獗的堕落熊怪和恶魔势力至关重要。",["race:NightElf"]="消灭那些疯狂的古树是一项痛苦的职责，因为这些活着的树木在恶魔瘟疫毒害它们的灵魂之前，曾是深受爱戴的伙伴和森林卫士。"},sec={{t="枯萎边缘的碎片",b="为了修复达图尔的变形魔棒，莱恩指引我去寻找莎尔蒂恩。她是一位知识渊博的守护者，看守着灰谷深处的一口宁静月井。莎尔蒂恩知道魔棒铁杆的下落，但想要取回它，就必须面对正威胁着北部森林的蔓延腐蚀。这件物品被锁在一个安静林地里的旧宝箱中，靠近费伍德森林的边界。"},{t="陨落的守护者",b="想要打开宝箱需要一把木制钥匙，但这把钥匙已经落入了森林里扭曲的守护者手中。沿着向北通往费伍德森林的山路，被称为疯狂的古树和枯萎的古树在痛苦中徘徊。从恶魔荒野向南渗出的腐蚀力量已经摧毁了它们自然的和谐，将曾经的森林卫士变成了充满敌意、饱受折磨的生物，必须击败它们才能夺回达图尔的遗物。"}},faq={{q="莎尔蒂恩是谁？",a="莎尔蒂恩是一位林精，驻守在灰谷的一口隐蔽月井处，位于阿斯特兰纳东侧和费伍德森林道路南侧。她拥有关于森林历史和达图尔古代技艺的深厚知识，为那些试图修复魔棒的人提供静默的指引。",al={"莎尔蒂恩","谁是月井守护者","莎尔蒂恩的背景故事"}},{q="为什么树人会被腐蚀？",a="这些树人居住在与费伍德森林接壤的北部山脊上。第三次战争遗留的恶魔腐蚀不断向南蔓延进入灰谷，扭曲了树木，使古老的守护者陷入疯狂，并破坏了它们与大地之间自然的联系。",al={"被腐蚀的树人","树人为何疯狂","疯狂的古树背景"}},{q="达图尔的变形魔棒是什么？",a="达图尔的变形魔棒是一件由已故邪恶巫师达图尔制造的附魔遗物。一旦完全组装并净化，它便拥有强大的变形魔法，可以将使用者伪装成熊怪，这对莱恩调查当地部落的计划至关重要。",al={"达图尔的变形魔棒","变形魔棒","魔棒有什么用"}},{q="隐藏的宝箱在哪里？",a="装着铁杆的磨损的宝箱位于一片安静的小林地中，就在从灰谷向北爬向费伍德森林边界的山路以西。",al={"磨损的宝箱位置","铁杆在哪里","宝箱在哪里"}},{q="为什么莎尔蒂恩为树人哀伤？",a="树人是卡多雷森林永恒的看护者，被尊为神圣的自然之灵。看着他们陷入疯狂和腐蚀却毫无治愈良方，这让莎尔蒂恩深感痛苦，因为终结它们的生命是一种悲哀，而非出于恶意。",al={"莎尔蒂恩与树人","莎尔蒂恩为何悲伤"}},{q="这项任务如何融入更广泛的净化任务链？",a="这是组装达图尔破损魔棒物理组件的阶段。一旦铁杆和其他碎片收集完毕，后续的工作将转向净化魔棒中残留的魔法力量。",al={"莱恩的净化任务链","莱恩任务线"}}},fp="17,209,26.307.0,20.323.0,18.218.0,30.203.0,21.197.1,34.147.0,38.225.0,54.175.0"}
P.entries["quest:1027"] = {n="莱恩的净化",s="这个任务标志着寻找修复达图尔的权杖所需的最后一部分组件，这是一件与净化灰谷有关的古代遗物。莎尔蒂恩指引旅行者前往陨落的德鲁伊圣所——朵丹尼尔兽穴，以找回丢失的铁质柄头。",h="这个任务标志着寻找修复达图尔的权杖所需的最后一部分组件，这是一件与净化灰谷有关的古代遗物。莎尔蒂恩指引旅行者前往陨落的德鲁伊圣所——朵丹尼尔兽穴，以找回丢失的铁质柄头。",kw={"灰谷","达图尔的权杖","朵丹尼尔","铁质柄头","月井","莱恩的净化","莎尔蒂恩"},ang={["class:Druid"]="访问朵丹尼尔那片被亵渎的土地，让人清醒地意识到塞纳里奥议会和卡多雷德鲁伊在灰谷中所遭受的损失。",["faction:Alliance"]="保护灰谷免受腐蚀对联盟在北卡利姆多的控制至关重要，尤其是考虑到部落军队正从碎木岗哨推进。",["race:NightElf"]="找回达图尔的传家宝既是对朵丹尼尔牺牲的守护者的纪念，也是对保卫古老卡多雷领地的持续贡献。"},sec={{t="朵丹尼尔废墟",b="达图尔的权杖的最后一部分——铁质柄头——曾被托付给居住在朵丹尼尔兽穴的暗夜精灵德鲁伊。不幸的是，这座圣所遭遇了灾难，守护者们惨遭杀害。随着德鲁伊的死亡和避难所的沦陷，遗物的具体藏匿地点也随之遗失，只剩下拾荒者和游荡的软泥怪吞噬了南路以东废墟中留下的任何东西。"},{t="重建达图尔的遗产",b="达图尔是一位已故的邪恶巫师，但他创造的权杖拥有改变的力量。莱恩·狼行者和莎尔蒂恩试图重组这件神器，希望它能帮助减缓熊怪对灰谷暗夜精灵的攻击。在莎尔蒂恩能够尝试在月井修复破碎的权杖之前，获得铁质柄头是最后一步。"}},faq={{q="什么是铁质柄头？",a="铁质柄头是达图尔的权杖的最后一部分。没有它，这件遗物就无法重铸，也无法用来净化灰谷。",al={"铁质柄头","权杖最后的部分","什么是柄头"}},{q="朵丹尼尔的德鲁伊发生了什么事？",a="居住在朵丹尼尔兽穴的德鲁伊在他们的圣所沦陷时被杀害了，避难所被废弃，留给了潜伏的软泥怪和野兽。莎尔蒂恩认为他们悲惨的命运是一个令人痛苦的话题。",al={"朵丹尼尔德鲁伊","谁杀害了德鲁伊","朵丹尼尔"}},{q="朵丹尼尔在哪里？",a="朵丹尼尔位于灰谷南部，在通往贫瘠之地边界的主路以东，碎木岗哨以南。",al={"朵丹尼尔在哪里","朵丹尼尔位置"}},{q="莎尔蒂恩是谁？",a="莎尔蒂恩是一位照料灰谷圣洁月井的树妖。她协助莱恩·狼行者搜寻达图尔的权杖分散的残片，并指引英雄们修复它。",al={"莎尔蒂恩","莎尔蒂恩是谁"}},{q="为什么柄头被软泥怪吞噬了？",a="兽穴沦陷后，胶状的软泥怪占据了该区域，并吞噬了废弃的遗物、箱子和尸体，在无意中将铁质柄头连同其他碎片一起吞了下去。",al={"软泥怪箱子","柄头软泥怪","为什么软泥怪有它"}},{q="找到柄头后会发生什么？",a="将柄头交给莎尔蒂恩，她就能开始修复权杖，从而最终用来协助莱恩·狼行者净化森林。",al={"下一步","莎尔蒂恩做什么"}}},fp="17,175,22.315.0,26.335.0,24.127.0,41.185.0,27.117.0,18.163.0,37.178.0,38.136.0"}
P.entries["quest:1028"] = {n="莱恩的净化",s="灰谷净化任务的这一步需要你带着修复后的达图尔的权杖前往一处隐秘的山间神殿。这座神殿隐藏在莎尔蒂恩隐居处东南方的山脊之中，其神圣的盆地中蕴含着为这件圣物重新充能所需的潜在魔法。",h="灰谷净化任务的这一步需要你带着修复后的达图尔的权杖前往一处隐秘的山间神殿。这座神殿隐藏在莎尔蒂恩隐居处东南方的山脊之中，其神圣的盆地中蕴含着为这件圣物重新充能所需的潜在魔法。",kw={"灰谷","盆地","达图尔的权杖","隐秘神殿","月井","莱恩的净化","修复后的权杖","莎尔蒂恩"},ang={["class:Druid"]="在神殿中苏醒的微妙共鸣揭示了古老的暗夜精灵工艺与自然之力的原始能量结合得有多么深厚。",["faction:Alliance"]="修复这件圣物是帮助莱恩·狼行者保卫阿斯特兰纳并治愈卡利姆多北部受腐蚀土地的关键一步。",["race:NightElf"]="灰谷隐秘的山间神殿代表着在你祖先们遭遇现代入侵之前，他们在这片荒野中编织出的宁静而永恒的圣所。"},sec={{t="通往高地之路",b="在拼凑好达图尔的权杖碎片后，树妖莎尔蒂恩指引旅行者离开她的月井，前往东南方荒野的斜坡。灰谷的古老神殿往往被刻意安置在深山岩壁的高处，远离道路，并被茂密的森林树冠所遮蔽。要到达这处宁静的圣所，你需要沿着岩壁寻找未经标记的路径，攀登那些大多只有哨兵和森林隐士才知道的蜿蜒小径。"},{t="恢复达图尔的权杖",b="神殿本身坐落在一处被生机勃勃的森林环绕的静谧小凹地中。即使在休眠状态下，这些石块依然散发着古代暗夜精灵所注入的潜在守护魔法。将修复后的权杖放置在神殿的石盆中，遗迹内沉睡的力量便会苏醒，让空地沐浴在柔和的共鸣之中，并为达图尔的造物注入纯净的附魔，使其终于能发挥净化这片土地的作用。"}},faq={{q="隐秘的神殿位于何处？",a="神殿隐藏在莎尔蒂恩的月井东南方的群山之中。你无需沿主路行进，而是要绕过岩石峭壁，寻找一条向上延伸至山脊的蜿蜒小径。",al={"神殿位置","神殿在哪里","如何找到神殿","隐秘神殿路径"}},{q="达图尔是谁？",a="达图尔是一位现已死去的邪恶巫师，是他创造了这根权杖。莱恩希望权杖的魔法能有助于调查灰谷发生的熊怪袭击事件。",al={"达图尔是谁","达图尔背景故事","权杖的创造者"}},{q="为什么要把达图尔的权杖放在神殿里？",a="虽然莎尔蒂恩可以从物理上重组破碎的权杖，但其古老的附魔已经耗尽。这座隐秘的神殿是一处未受干扰的自然魔法储藏地，能够重新点燃权杖的力量。",al={"为什么要为权杖充能","权杖用途","神殿有什么作用"}},{q="莎尔蒂恩是谁？",a="莎尔蒂恩是一位居住在灰谷东部静谧月井旁的树妖，她协助莱恩·狼行者研究那些能够净化被腐蚀荒野的圣物与仪式。",al={"莎尔蒂恩","任务发放者","月井女祭司"}},{q="权杖充能后会发生什么？",a="当神殿为权杖注入力量后，它就可以交还给莎尔蒂恩，并用于莱恩对灰谷熊怪的调查之中。",al={"接下来做什么","神殿之后","下一步"}},{q="神殿有守卫吗？",a="神殿本身是一处宁静的避难所，但周围的山脉和森林中游荡着野生猛兽和堕落的熊怪部落，这使得攀登过程险象环生。",al={"神殿里有怪物吗","神殿危险"}}},fp="17,178,23.335.0,22.303.0,35.167.0,15.140.0,54.162.0,18.173.0,40.132.0,22.151.0"}
P.entries["quest:1029"] = {n="莱恩的净化",s="在灰谷漫长的调查中，这一步见证了达图尔的变形魔棒被完全修复。你从树妖莎尔蒂恩手中接过这件完成的遗物，回到阿斯特兰纳向莱恩·狼行者报告这一成就，并以此纪念阵亡的哨兵泰罗尼斯。",h="在灰谷漫长的调查中，这一步见证了达图尔的变形魔棒被完全修复。你从树妖莎尔蒂恩手中接过这件完成的遗物，回到阿斯特兰纳向莱恩·狼行者报告这一成就，并以此纪念阵亡的哨兵泰罗尼斯。",kw={"灰谷","阿斯特兰纳","达图尔的魔棒","莱恩·狼行者","莱恩的净化","莎尔蒂恩","泰罗尼斯"},ang={["faction:Alliance"]="阿斯特兰纳是联盟在灰谷的支柱；直接协助莱恩·狼行者可以巩固你在隐居的哨兵部队中的地位。",["race:NightElf"]="传承泰罗尼斯的遗志为阿斯特兰纳带来了慰藉，证明在卡利姆多神圣丛林面临日益严峻的威胁时，牺牲的族人不会被遗忘。"},sec={{t="修复魔棒",b="在搜寻了灰谷中遭受腐蚀的区域，寻回了组件和古老的宝石碎片后，被称为达图尔的变形魔棒的遗物终于被重铸完成。它被交给伊瑞斯湖附近的树妖莎尔蒂恩，其魔法属性得到了净化和重塑。随着工艺完成，她指引你穿过森林道路回到阿斯特兰纳，将这件神器交给莱恩·狼行者。"},{t="纪念泰罗尼斯",b="整个任务最初是一次由泰罗尼斯领导的探险，他是莱恩的一位老友，他寻求达图尔的魔棒是为了希望能减缓熊怪对他族人的攻击。泰罗尼斯被发现死在法拉希姆湖的岛上，他被夺走了目标宝石的鱼人杀害，没能看到任务完成。将修复好的魔棒交还给莱恩·狼行者标志着一场苦乐参半的胜利，确保了他危险的牺牲没有白费。"}},faq={{q="什么是达图尔的变形魔棒？",a="这是一根由已故邪恶巫师达图尔所创造的魔法棒。一旦修复，它就能辅助莱恩调查灰谷中熊怪的袭击事件。",al={"达图尔的魔棒","魔棒有什么用"}},{q="泰罗尼斯是谁？",a="泰罗尼斯是一位年轻的暗夜精灵哨兵，他受莱恩·狼行者的委派，在灰谷寻找古老魔法的组件。他被发现死在法拉希姆湖的岛上，被夺走了目标宝石的鱼人杀害，将他重要使命的最后一步留给了路过的联盟旅行者。",al={"泰罗尼斯是谁","泰罗尼斯之死"}},{q="莱恩·狼行者是谁？",a="莱恩·狼行者是一位经验丰富的暗夜精灵哨兵指挥官，驻扎在阿斯特兰纳中心。她负责监督灰谷中部对抗入侵的恶魔污秽、敌对萨特以及当地野兽腐化的防御工作。",al={"莱恩","莱恩·狼行者"}},{q="莎尔蒂恩是谁？",a="莎尔蒂恩是一位静静居住在伊瑞斯湖以东月井附近的树妖。她对森林及其古老遗物的深刻了解使她能够净化遭受腐蚀的遗物，并修复古老的强力工具。",al={"莎尔蒂恩","伊瑞斯湖女祭司"}},{q="这个任务发生在哪里？",a="这个跑腿任务会带你从灰谷中部宁静的伊瑞斯湖岸边，沿着主路向西回到该区域主要的联盟中心——阿斯特兰纳。",al={"任务地点","我该去哪里"}},{q="将魔棒交给莱恩之后会发生什么？",a="莱恩对泰罗尼斯最终任务的成功感到深深的宽慰和自豪。然而，灰谷的净化工作远未结束，她立即开始寻找利用魔棒的力量对抗林地中挥之不去的腐蚀的方法。",al={"后续任务","莱恩的净化延续"}}},fp="17,191,16.304.0,16.358.1,39.170.0,16.257.0,24.203.0,18.188.0,33.133.0,47.188.1"}
P.entries["quest:103"] = {n="长明的灯塔",s="“灯塔的守护者”是由葛瑞森船长发布的一项任务，他是徘徊在西部荒野灯塔岩石海岸上的一名幽灵水手。在一场残酷的鱼人屠杀导致原本的守塔人丧生后，葛瑞森正在寻找灯油，以维持海岸灯塔的燃烧，引导船只安全避开危险的暗礁。",h="“灯塔的守护者”是由葛瑞森船长发布的一项任务，他是徘徊在西部荒野灯塔岩石海岸上的一名幽灵水手。在一场残酷的鱼人屠杀导致原本的守塔人丧生后，葛瑞森正在寻找灯油，以维持海岸灯塔的燃烧，引导船只安全避开危险的暗礁。",kw={"灯塔信标","葛瑞森船长","一瓶油","无尽之海","收割傀儡","老瞎眼","西部荒野灯塔"},ang={["faction:Alliance"]="保持西部荒野灯塔的燃烧可以保护前往暴风城港口的商船和海军舰艇，防止它们在王国破碎的海岸线上搁浅。",["profession:Engineering"]="在西部荒野的农场里横冲直撞的机械收割傀儡携带的易挥发机器流体，在紧要关头可以当做灯油使用。"},sec={{t="幽灵的职责",b="这座灯塔矗立在西部荒野西南海岸外的一座崎岖小岛上，它曾经引导过无数航行在无尽之海危险浅滩上的水手。但这一切随着臭名昭著的鱼人袭击者老瞎眼发动的突袭而告终，它杀害了守塔人和他的家人。葛瑞森船长在这些岩石上遭遇了不幸，死于溺水，如今他的灵魂依然守护着这座灯塔。作为幽灵，他无法阻止那场大屠杀，但他拒绝让灯塔熄灭。"},{t="为灯塔添加燃料",b="由于没有活着的守塔人来照看火焰，维持灯光需要一种特殊的燃料来源。在西部荒野废弃农场中徘徊的那些失控的收割傀儡，它们锈迹斑斑的腹部里藏着装有机械油的烧瓶。葛瑞森派遣冒险者回到岸上，从这些失控的构造体身上收集这些油料，以确保灯火不熄，防止其他迷航的船长重蹈他的覆辙。"}},faq={{q="葛瑞森船长是谁？",a="葛瑞森船长是一个不安的灵魂，他生前在西部荒野危险的海岸线上遭遇海难身亡。由于无法安息，他担负起了守护西部荒野灯塔的责任，保护活着的船员免于遭遇同样的悲惨结局。",al={"葛瑞森船长","灯塔幽灵","西部荒野灯塔的幽灵是谁"}},{q="原本的灯塔守卫发生了什么事？",a="灯塔管理员和他的家人被老瞎眼领导的一场突袭残酷杀害。老瞎眼是一个在该海岸线游荡的臭名昭著的鱼人首领。当屠杀发生时，葛瑞森船长作为幽灵，只能无助地在一旁目睹这一切。",al={"灯塔管理员发生了什么","是谁杀了灯塔管理员","灯塔守卫一家死亡"}},{q="灯塔火焰所需的油来自哪里？",a="这些油是从在西部荒野休耕的田地和废弃的谷物农场中横冲直撞的机械收割傀儡身上搜刮来的。",al={"去哪里获取灯油","收割傀儡之油","一瓶油"}},{q="为什么葛瑞森如此在意保持灯塔的照明？",a="葛瑞森认为这是他死后神圣的职责，旨在拯救航行在无尽之海上的凡人船员，使他们免于驶向海岸线上锯齿般的岩石，因为他自己生前就是在那几块礁石上白白送了命。",al={"为什么点亮火炬","葛瑞森的动机","灯塔火焰的目的"}},{q="老瞎眼是谁？",a="老瞎眼是一个臭名昭著且残暴的鱼人，在西部荒野的海岸线上游荡。他因组织对岸边凡人定居点的袭击而闻名，其中包括屠杀灯塔管理员一家。",al={"老瞎眼","西部荒野鱼人首领"}},{q="西部荒野灯塔位于何处？",a="灯塔矗立在西部荒野西南海岸外的一座锯齿状岩石小岛上，可以游过浅浅的海岸水域到达那里。",al={"灯塔位置","西部荒野灯塔在哪里","寻找灯塔"}}},fp="19,201,15.440.0,18.363.0,23.190.0,49.144.0,54.99.0,51.146.0,20.161.0,41.145.0"}
P.entries["quest:1030"] = {n="莱恩的净化",s="莱恩·狼行者这项任务的关键阶段需要使用达图尔新修复的魔棒，来伪装成局外人并尝试与一只未受腐化的熊怪接触。在密斯特拉湖的东南部，一位名叫克罗格的流亡者让我们得以一窥幸存熊怪对暗夜精灵的深刻怨恨。",h="莱恩·狼行者这项任务的关键阶段需要使用达图尔新修复的魔棒，来伪装成局外人并尝试与一只未受腐化的熊怪接触。在密斯特拉湖的东南部，一位名叫克罗格的流亡者让我们得以一窥幸存熊怪对暗夜精灵的深刻怨恨。",kw={"灰谷","达图尔的变形魔棒","魔苔","熊怪","克罗格","密斯特拉湖","莱恩·狼行者","莱恩的净化"},ang={["class:Druid"]="德鲁伊们试图恢复森林的平衡，却不得不面对熊怪们的残酷悲剧。这些曾经与自然紧密相连的盟友，如今正遭受着挥之不去的恶魔污秽所带来的可怕疯狂。",["faction:Alliance"]="阿斯特兰纳的生存取决于能否化解潜伏在边境道路上的威胁，因此这次秘密会谈对于确保东灰谷的安全至关重要。",["race:NightElf"]="倾听克罗格的肺腑之言让人清醒地意识到，许多灰谷的土著居民并不把卡多雷视为仁慈的守护者，而是将他们看作这片土地灾难重演的鲁莽缔造者。"},sec={{t="皮毛与利爪的伪装",b="随着达图尔的变形魔棒被修复，莱恩·狼行者怀疑这位已故的暗夜精灵当初想要通过伪装来安全接近熊怪。灰谷的森林变得危机四伏，在各部落间蔓延的疯狂让直接的外交接触成为不可能。通过运用这件奥术圣物，冒险者将化身为熊怪的模样，希望能避开其本能的领地狂怒，找到愿意交谈的对象。"},{t="流亡者的苦涩",b="在密斯特拉湖的东南部住着克罗格，这是一只孤立的熊怪，他设法逃脱了魔苔的腐化侵蚀。克罗格以为自己是在与同族中洁净的成员交谈，因此毫无顾忌地讲述了他的流亡经历和深切的悲伤。然而，他并没有把暗夜精灵看作盟友或保护者，反而对他们怀有深刻的苦涩，公开指责正是暗夜精灵的傲慢和古老的失败，才导致了蹂躏他族人的恶魔污染。"}},faq={{q="达图尔的变形魔棒有什么用？",a="达图尔的变形魔棒可以暂时将使用者的外形变为熊怪。这种伪装允许冒险者在未受腐化的熊怪中行走，而不会立即引发暴力攻击。",al={"魔棒有什么用","达图尔的变形魔棒","熊怪伪装魔棒"}},{q="克罗格是谁？",a="克罗格是一只未受腐化的熊怪，流亡在密斯特拉湖的东南部。他避开了感染了族人的魔苔，独自生活在一条插着火把的溪流对面，哀悼着他部落的覆灭，同时对暗夜精灵怀有深深的积怨。",al={"克罗格是谁","密斯特拉湖未受腐化的熊怪","密斯特拉湖东南部的熊怪"}},{q="为什么如果不使用魔棒克罗格就会发起攻击？",a="克罗格感到恐惧，且对局外人极度不信任，尤其是他认为是导致其族人衰落罪魁祸首的暗夜精灵。如果没有让你看起来像是一只未受腐化熊怪的幻象，他会将你视为入侵者，并对你的营地进行暴力防卫。",al={"克罗格为什么发起攻击","克罗格攻击性","为什么对克罗格使用魔棒"}},{q="为什么克罗格将腐化归咎于暗夜精灵？",a="克罗格认为森林遭受的恶魔腐化——即军团入侵和历史上奥术干预所带来的后果——是暗夜精灵骄傲自大直接造成的。在他眼中，古老的卡多雷给卡利姆多带来了毁灭，却让土著部落独自承担后果。",al={"克罗格为什么憎恨暗夜精灵","熊怪指责暗夜精灵","克罗格对暗夜精灵的仇恨"}},{q="在哪里可以找到克罗格？",a="你可以在灰谷的密斯特拉湖东南部找到他。沿着一条蜿蜒的土路走，路上有燃烧的火把标记，它会带你穿过一条小溪，抵达他孤独的营地。",al={"克罗格在哪里","克罗格位置","寻找未受腐化的熊怪"}},{q="什么是魔苔，它是如何影响熊怪的？",a="魔苔是一种在灰谷蔓延的恶魔植被，它将恶魔的污染渗入土壤和植物中。当地的熊怪部落成为了这种影响的受害者，这使他们陷入了一种狂乱、暴力的疯狂状态，进而导致其社会分崩离析。",al={"什么是魔苔","魔苔熊怪","为什么熊怪会发疯"}}},fp="17,199,23.378.0,22.305.1,44.166.0,13.220.0,47.193.0,56.201.0,25.152.0,52.178.0"}
P.entries["quest:1031"] = {n="塞纳留斯的树枝",s="在一阵来自垂死的树妖安妮莉亚的绝望请求后，一位冒险者受命从卑劣的萨特格尔萨里斯手中夺回一件神圣的遗物。收复塞纳留斯的树枝意味着必须面对潜伏在灰谷东部的恶魔走狗，并将这件珍贵的树枝交还给树妖伊莉亚娜。",h="在一阵来自垂死的树妖安妮莉亚的绝望请求后，一位冒险者受命从卑劣的萨特格尔萨里斯手中夺回一件神圣的遗物。收复塞纳留斯的树枝意味着必须面对潜伏在灰谷东部的恶魔走狗，并将这件珍贵的树枝交还给树妖伊莉亚娜。",kw={"安妮莉亚","灰谷的树妖","塞纳留斯的树枝","格尔萨里斯","伊莉亚娜","夜道谷","萨特"},ang={["class:Druid"]="塞纳留斯传授了第一批凡人德鲁伊，这使他的遗物变得神圣无比。从恶魔污染的萨特手中收回他的树枝是一项精神上的使命。",["faction:Alliance"]="灰谷的树妖们依靠联盟的援助来击退灰谷东部荒野中的恶魔威胁。",["race:NightElf"]="塞纳留斯的女儿们是卡多雷珍爱的盟友。为安妮莉亚复仇，清除那些亵渎你们祖先森林的萨特败类。"},sec={{t="垂死的请求",b="被派往灰谷东部那片被腐蚀的土地寻找失踪的树妖时，联盟的旅行者们偶然发现了生命垂危的安妮莉亚。这位受伤的塞纳留斯之女在咽下最后一口气前，指了指北方的萨特废墟。她用尽最后的力气，艰难地吐出了夺走圣物的萨特名字——格尔萨里斯——并在临终前恳求冒险者收回塞纳留斯的树枝。"},{t="废墟中的腐蚀",b="窃贼格尔萨里斯是一名盘踞在萨维亚古老暗夜精灵废墟中的卑劣萨特。对萨特而言，与半神塞纳留斯有关的古老遗物是极好的亵渎对象和用来嘲弄自然的战利品。击败格尔萨里斯并从他爪中夺回树枝，不仅是对安妮莉亚的正义伸张，也是为了防御燃烧军团的远古仆从对灰谷神圣植物所散布的腐蚀。"},{t="树妖的哀伤",b="将树枝交还给树妖伊莉亚娜为这场搜寻画上了一个苦涩的句号。虽然神圣的遗物免遭了恶魔的玷污，但安妮莉亚死亡的消息对她幸存的姐妹们造成了沉重的打击。灰谷的树妖们曾习惯于在古老的树荫下无忧无虑地嬉戏，如今却被迫面对战争与蔓延的腐蚀这一残酷现实。"}},faq={{q="什么是塞纳留斯的树枝？",a="这是一件与森林之王塞纳留斯有关的神圣自然遗物，深受他树妖女儿们的珍视。萨特们夺走了它，安妮莉亚在带领姐妹们夺回它的过程中受了致命伤；她在临终前说出了格尔萨里斯的名字，指认他就是夺走圣物的人。",al={"塞纳留斯的树枝 遗物","什么是塞纳留斯的树枝","塞纳留斯的树枝"}},{q="是谁杀害了安妮莉亚？",a="安妮莉亚在试图收回塞纳留斯的树枝时，在萨特盘踞的萨维亚废墟中受了致命伤。在咽气前，她指认萨特格尔萨里斯夺走了树枝。",al={"杀害安妮莉亚的凶手","谁袭击了安妮莉亚","谁杀了树妖"}},{q="格尔萨里斯在哪里？",a="格尔萨里斯潜伏在安妮莉亚遇难处北方的萨维亚废墟，躲在石拱门和被腐蚀的建筑下方。",al={"格尔萨里斯的位置","寻找格尔萨里斯","去哪里击杀格尔萨里斯"}},{q="夺回塞纳留斯的树枝后我该把它交给谁？",a="你必须将收回的树枝交给在灰谷艾森娜神殿等候的树妖伊莉亚娜。",al={"塞纳留斯的树枝任务交还","伊莉亚娜的位置","谁来接收树枝"}},{q="为什么萨特想要塞纳留斯的文物？",a="萨特是因恶魔契约而发生畸变的古老暗夜精灵，他们对自然和半神塞纳留斯怀有持久的仇恨。腐蚀或窃取这些神圣的遗物既是为了服务于他们的恶魔主人，也是为了向昔日的同胞泄愤。",al={"萨特的动机","为什么要偷塞纳留斯的树枝","格尔萨里斯为什么要偷它"}},{q="安妮莉亚和伊莉亚娜是什么关系？",a="她们是亲密的树妖伙伴，也是精神上的姐妹，在腐蚀带来的威胁夺走安妮莉亚的生命之前，她们曾有无数天在灰谷的荒野中自由奔跑玩耍。",al={"安妮莉亚和伊莉亚娜的关系","树妖是姐妹吗"}}},fp="22,154,15.265.0,23.325.0,23.245.1,31.279.0,18.177.0,27.69.0,60.76.0,44.203.0,27.187.0"}
P.entries["quest:1032"] = {n="猎杀萨特！",s="因为失去了姐妹安妮莉亚而悲痛不已，在艾森娜神殿的树妖伊莉亚娜试图向潜伏在灰谷的萨特复仇。她请求联盟的勇士们除掉这些被腐化的生物，并带回它们的角作为它们被消灭的证明。",h="因为失去了姐妹安妮莉亚而悲痛不已，在艾森娜神殿的树妖伊莉亚娜试图向潜伏在灰谷的萨特复仇。她请求联盟的勇士们除掉这些被腐化的生物，并带回它们的角作为它们被消灭的证明。",kw={"安妮莉亚","灰谷","树妖","伊莉亚娜","萨特","萨特的角","猎杀萨特"},ang={["class:Druid"]="为倒下的树妖复仇并割下恶魔萨特的角，是对污染了塞纳留斯钟爱的荒野的腐化力量的直接打击。",["faction:Alliance"]="削减萨特的数量为灰谷的联盟军队提供了一个更安全的森林环境，以抵御周围的野生威胁。",["race:NightElf"]="萨特是上层精灵古老堕落为邪能奴仆的挥之不去的耻辱记忆。帮助伊莉亚娜可以洗净这片土地上的祖辈之祸。"},sec={{t="树妖的悲伤",b="树妖通常是顽皮而宁静的森林之灵，与自然有着深厚的联系，对凡人来说难以捉摸。安妮莉亚的惨死打破了居住在艾森娜神殿的伊莉亚娜的这份宁静。在超脱了她无忧无虑的天性并陷入陌生的悲伤之后，她转向联盟的旅人们，请求他们击倒那些罪魁祸首的恶魔野兽。"},{t="被腐化的族群",b="萨特代表了远古暗夜精灵血统中一支黑暗而扭曲的分支，在上古之战中不可逆转地受到了恶魔能量的污染。这些潜伏在灰谷各处被玷污的树林中的燃烧军团的邪恶仆从，正积极捕食森林中的居民。夺取它们的角不仅是复仇的证明，也对侵蚀灰谷东部的邪能存在给予了直接的打击。"}},faq={{q="伊莉亚娜是谁？",a="伊莉亚娜是一位居住在灰谷艾森娜神殿的树妖。她以温和的天性而闻名，目前正在哀悼她那死于当地萨特之手的姐妹安妮莉亚的悲剧。",al={"伊莉亚娜背景故事","任务发布者是谁","林歌神殿树妖"}},{q="安妮莉亚是谁？",a="安妮莉亚是一位树妖，也是伊莉亚娜心爱的姐妹。她们俩在灰谷的古老树冠间嬉戏了漫长岁月，直到安妮莉亚遭到该地区潜伏的萨特的伏击并被杀害。",al={"安妮莉亚","伊莉亚娜的姐妹","谁死了"}},{q="为什么伊莉亚娜要萨特的角？",a="萨特的角是确凿无疑的实体证明，表明那些应对安妮莉亚谋杀案负责的被腐化的恶魔已被击杀，这能使她姐妹的灵魂获得安宁。",al={"为什么要萨特的角","萨特的角作为证明"}},{q="萨特是什么？",a="萨特是前暗夜精灵，在上古之战中被燃烧军团的恶魔力量诅咒和变异。它们居住在腐化的据点中，试图传播污秽并摧毁自然的森林之灵。",al={"萨特背景故事","灰谷的萨特是什么"}},{q="林歌神殿在哪里？",a="林歌神殿是一处位于灰谷最东端、靠近艾萨拉边界的古老且几乎被废弃的暗夜精灵遗迹。伊莉亚娜不住在那里；她在艾森娜神殿等候。",al={"林歌神殿位置","林歌神殿在哪里"}},{q="这和其他狩猎活动有关联吗？",a="即使在为她的姐妹复仇之后，伊莉亚娜仍继续接受萨特的角，这表明灰谷的保卫者们正在进行一场持续的行动，以从灰谷清除萨特的威胁。",al={"萨特的角任务","后续任务","可重复的萨特任务"}}},fp="14,193,15.309.0,17.331.0,16.147.0,15.141.0,38.145.0,16.196.0,21.173.0,37.142.0"}
P.entries["quest:1033"] = {n="月神之泪",s="皮尔图拉斯·怀特姆恩年幼的女儿蕾拉拉被一种邪恶而持续不断的疾病折磨着，即便是从北方废墟带回的草药也无法治愈。绝望中的皮尔图拉斯为了寻求更强效的治疗方法，派遣一位冒险者前往伊瑞斯湖，去取回月神之泪。这是一种被暗夜精灵奉为神圣的矿石，因其能够洗净腐蚀的力量而备受推崇。",h="皮尔图拉斯·怀特姆恩年幼的女儿蕾拉拉被一种邪恶而持续不断的疾病折磨着，即便是从北方废墟带回的草药也无法治愈。绝望中的皮尔图拉斯为了寻求更强效的治疗方法，派遣一位冒险者前往伊瑞斯湖，去取回月神之泪。这是一种被暗夜精灵奉为神...",kw={"灰谷","阿斯特兰纳","治疗方法","月神","月神之泪","伊瑞斯湖","奥雷迪尔·阔叶","皮尔图拉斯·怀特姆恩","蕾拉拉","水元素"},ang={["class:Druid"]="德鲁伊既了解灰谷水域的微妙平衡，也了解守护着伊瑞斯湖中心未受干扰之地的那些反常水元素的存在。",["class:Priest"]="侍奉月神的女祭司们深知，当祈祷本身需要物理催化剂时，依靠神圣遗物来对抗黑暗的、非自然的瘟疫在精神上是何等重要。",["faction:Alliance"]="在区域性危险加剧的时期，协助阿斯特兰纳的防御者解决个人危机，可以加强灰谷中联盟的团结。",["race:NightElf"]="对于卡多雷来说，转向以月亮女神命名的圣石，反映了他们绝对的信念，即月神的恩典可以净化传统疗法无法触及的伤口。"},sec={{t="父亲日益增长的恐慌",b="蕾拉拉·怀特姆恩卧病在阿斯特兰纳，被一种来源不明的恶性疾病折磨得日益虚弱。皮尔图拉斯曾寄希望于药剂师奥雷迪尔·阔叶用巴斯兰的头发调配的药剂。虽然那种药剂成功遏制了病情的迅速恶化，但却无法完全清除她体内的毒素。面对普通恢复魔法和野生草药已无济于事的残酷现实，皮尔图拉斯转向了他族人的古老传统，恳求能够获得蕴含神圣净化之光的疗法来施以援手。"},{t="伊瑞斯湖之石",b="在告别之前，奥雷迪尔与皮尔图拉斯分享了一些更令人忧虑的预防措施，并指出如果草药混合物不起作用，可以使用传说中的疗法。其中最重要的是月神之泪，这是一种发光的圣石，仅见于阿斯特兰纳东部伊瑞斯湖中的一座小岛上。据信这种石头承载着月亮女神的祝福，拥有清除活体组织深层腐蚀的力量。取回它并非一次轻松的朝圣，因为不安的水元素在湖泊的浅滩和湖岸巡逻，凶猛地守护着这片水域中心未受侵扰的圣地。"},{t="一丝希望",b="当被安全带回阿斯特兰纳后，皮尔图拉斯准备将这块石头浸泡在药汤中，喂给他生病的女儿。然而，尽管他怀着绝望的心情表达了谢意，但腐蚀那种挥之不去的特性表明，在孩子的生命真正安全之前，这场磨难可能还需要更罕见的试剂。"}},faq={{q="什么是月神之泪？",a="月神之泪是一种罕见的、受过祝圣的石头，发现在灰谷伊瑞斯湖的中央岛屿上。暗夜精灵的传说将强大的净化和治疗属性归因于这种矿物，认为它能够洗净严重的毒素和挥之不去的腐蚀。",al={"什么是月神之泪","月神之泪物品","伊瑞斯湖之石"}},{q="为什么奥雷迪尔之前的治疗失败了？",a="奥雷迪尔·阔叶用一种被称为巴斯兰的头发的植物调配的药剂成功减缓了疾病的进程，但无法克服蕾拉拉病情的恶性本质。她的父亲皮尔图拉斯意识到普通的草药学已不足以应对，因此促使他寻求受灵性祝福的治疗方法。",al={"为什么奥雷迪尔的治疗失败","奥雷迪尔的治疗有效吗","蕾拉拉仍然生病"}},{q="伊瑞斯湖在哪里？",a="伊瑞斯湖位于灰谷阿斯特兰纳的东部。旅行者可以沿着镇上向东的主路，跟随一条沿着供水溪流向北蜿蜒进入湖盆的土路到达那里。",al={"伊瑞斯湖在哪里","伊瑞斯湖位置","如何找到伊瑞斯湖"}},{q="伊瑞斯湖周围潜伏着什么危险？",a="伊瑞斯湖的水域和中央岛屿上居住着具有领地意识的水元素。任何试图接近岛屿以获取月神之泪的人，都必须避开这些充满敌意的自然之灵。",al={"伊瑞斯湖的敌人","伊瑞斯湖有什么攻击者"}},{q="皮尔图拉斯打算如何使用这块石头？",a="皮尔图拉斯打算将月神之泪浸泡在药汤中，依靠这种神圣矿物众所周知的净化特性，来排出正在吞噬他女儿蕾拉拉的黑暗恶疾。",al={"如何使用月神之泪","月神之泪药汤"}},{q="谁是蕾拉拉·怀特姆恩？",a="蕾拉拉是皮尔图拉斯·怀特姆恩年幼的暗夜精灵女儿，居住在阿斯特兰纳。她患上了一种威胁生命的非自然腐蚀恶疾，病情严重。",al={"谁是蕾拉拉","皮尔图拉斯的女儿"}}},fp="12,266,24.374.0,22.345.0,17.181.1,21.161.0,37.169.0,27.152.0,35.154.0,40.139.0,24.172.0"}
P.entries["quest:1034"] = {n="星尘废墟",s="皮尔图拉斯·怀特姆恩为了治愈他的女儿蕾拉，在阿斯特兰纳进行了绝望的搜寻。虽然圣物月神之泪缓解了她可怕的噩梦，但高烧依然折磨着她。在奥雷迪尔·阔叶的草药知识指引下，冒险者们前往南方，采集那些在古老的暗夜精灵遗迹中沉淀的、具有冷却效果的荧光粉尘。",h="皮尔图拉斯·怀特姆恩为了治愈他的女儿蕾拉，在阿斯特兰纳进行了绝望的搜寻。虽然圣物月神之泪缓解了她可怕的噩梦，但高烧依然折磨着她。在奥雷迪尔·阔叶的草药知识指引下，冒险者们前往南方，采集那些在古老的暗夜精灵遗迹中沉淀的、具...",kw={"灰谷","阿斯特兰纳","治疗","月神","高烧","奥雷迪尔","皮尔图拉斯","药膏","蕾拉","星尘"},ang={["class:Druid"]="采集这种舒缓的星尘需要面对栖息在被淹没遗迹中的狂躁水灵，这是灰谷脆弱的生态平衡遭到破坏的鲜明写照。",["class:Priest"]="虽然月神之恩缓解了蕾拉的梦魇，但肉体凡胎除了祈求神圣的祷告，往往还需要尘世的药物来维持生命。",["profession:Herbalism"]="从灌木丛中收集闪烁粉末的过程，展示了识别灰谷湿润微气候中稀有植物现象所需的专业知识。",["race:NightElf"]="散落在阿斯特兰纳以南的遗迹是古老卡多雷文明的遗存，提醒着暗夜精灵：石头中残留的魔法依然可以被引导用于治疗。"},sec={{t="父亲挥之不去的绝望",b="皮尔图拉斯·怀特姆恩已经在女儿蕾拉的床边守了无数个不眠之夜，眼睁睁看着那恶毒的疾病折磨着她。虽然献上一份月神之泪暂时缓解了困扰她神智的梦魇，但病根依然深种。她的身体遭受着剧烈高烧的侵袭，世俗的药物已束手无策。随着神殿治疗师们也已尽力，皮尔图拉斯再次求助于古老的自然疗法，希望能保住女儿的性命。"},{t="星尘的光芒",b="听取了资深草药师奥雷迪尔·阔叶的建议后，皮尔图拉斯将目光投向了星尘废墟，那里位于阿斯特兰纳以南，穿过河流即是。这座古老的卡多雷圣殿中倾倒的大理石柱和拱门处存在着一种奇特的现象：一种霜状的、闪烁的物质沉淀在当地的植被上。这种粉末状的凝结物被俗称为“星尘”，具有极其强效的天然冷却特性，足以驱散不自然的灼热。皮尔图拉斯打算将收集到的残留物研磨成药膏，希望能用它那宁静的寒意最终击退蕾拉身上的高烧。"},{t="水中的潜行者",b="由于废墟中不仅淹水而且沉入水底的石块里潜伏着守卫和野生生物，采集这种霜状粉尘十分危险。水元素受到灰谷平衡被打破的影响，变得腐化或狂躁，在灌木丛最茂密的水下广场周围汹涌肆虐。采集者们必须涉水进入看起来宁静的浅滩，同时时刻警惕来自浑浊深处的突袭，在被星尘覆盖的灌木丛中搜寻足够的纯净残留物，然后尽快将其送回阿斯特兰纳。"}},faq={{q="为什么皮尔图拉斯需要星尘？",a="皮尔图拉斯·怀特姆恩的女儿蕾拉在阿斯特兰纳因某种严重的魔法或腐化引起的高烧而濒临死亡。虽然月神之泪缓解了她的梦魇，但高烧依然无法控制。资深草药师奥雷迪尔建议，收集在星尘废墟中的霜状残留物具有强效的冷却特性，可以制成舒缓药膏。",al={"为什么需要星尘","星尘废墟的目的","蕾拉的高烧治疗"}},{q="星尘废墟在哪里？",a="星尘废墟位于阿斯特兰纳正南方，地处灰谷中部，环绕着一个小湖泊，周围是古老且杂草丛生的卡多雷建筑。",al={"星尘废墟的位置","星尘废墟在哪里","寻找星尘废墟"}},{q="在此处提到的“星尘”是什么？",a="皮尔图拉斯希望利用从湖畔植被上收集到的冷却霜状粉尘来制作药膏，以降低女儿的高烧。",al={"什么是星尘","星尘的本质","星尘背景传说"}},{q="星尘能完全治愈蕾拉吗？",a="皮尔图拉斯希望用星尘制成的药膏能降低蕾拉的高烧。至于它能否让女儿完全恢复元气，只有在治疗后才能知晓。",al={"星尘能治愈蕾拉吗","蕾拉被治愈了吗","女孩得救了吗"}},{q="在星尘废墟中会遇到什么威胁？",a="这些被淹没的遗迹中栖息着极具攻击性的水元素，它们潜伏在水面下，守护着这片平静的水域，对任何涉水进入浅滩去查看那些闪烁灌木丛的人来说都是巨大的威胁。",al={"星尘废墟的敌人","星尘废墟有什么攻击"}},{q="奥雷迪尔是谁？",a="奥雷迪尔·阔叶是一位知识渊博的暗夜精灵草药师，居住在灰谷北部靠近迈斯特拉岗哨的地方。他研究该地区的独特植物已有数百年，当标准的神殿疗法失效时，他会为皮尔图拉斯提供稀有植物疗法的建议。",al={"谁告诉皮尔图拉斯关于星尘的事","奥雷迪尔·阔叶"}}},fp="21,230,28.372.0,21.410.0,22.390.0,32.231.0,40.130.0,33.145.0,41.130.1,48.178.0,15.227.0"}
P.entries["quest:1035"] = {n="坠星湖",s="“坠星湖”是皮尔图拉斯·怀特姆恩为了拯救他身处阿斯特兰纳、命在旦夕的女儿瑞拉拉而进行的任务链中的情感高潮。虽然她最初的退烧了，但她的生命力依然严重枯竭，需要一颗天界月亮石来恢复她的生命能量。玩家必须深入坠星湖那未经驯化的水域，从一个被腐蚀的影冠神谕者手中夺取这些被囤积的石头之一。",h="“坠星湖”是皮尔图拉斯·怀特姆恩为了拯救他身处阿斯特兰纳、命在旦夕的女儿瑞拉拉而进行的任务链中的情感高潮。虽然她最初的退烧了，但她的生命力依然严重枯竭，需要一颗天界月亮石来恢复她的生命能量。玩家必须深入坠星湖那未经驯化的...",kw={"灰谷","阿斯特兰纳","陨落的月亮石","坠星湖","皮尔图拉斯·怀特姆恩","瑞拉拉","影冠神谕者"},ang={["class:Druid"]="屠杀敌对的影冠沼泽兽凸显了正在灰谷的自然守护者中蔓延的悲剧性不和，需要沉重的心情来恢复平衡。",["class:Priest"]="陨落的月亮石因其神圣的能量而受到追捧，它们代表了月亮女神艾露恩那实实在在的治疗恩典，是拯救垂死孩童的希望。",["faction:Alliance"]="帮助皮尔图拉斯·怀特姆恩巩固了联盟保护阿斯特兰纳公民免受灰谷蔓延的腐蚀侵袭的承诺。",["race:NightElf"]="对于卡多雷来说，保护阿斯特兰纳的年轻人是一项神圣的集体职责，而取回与艾露恩的祝福相关联的神圣月亮石既是一种仁慈的表现，也是一种崇敬的行为。"},sec={{t="女儿微弱的呼吸",b="皮尔图拉斯·怀特姆恩已经度过了痛苦的几天，看着他年幼的女儿瑞拉拉一步步走向死亡。虽然用巴斯兰的头发和星尘酿造的强效药物帮助她退了高烧，但这次磨难使她的身体变得空虚而虚弱。时间已经不再站在她这一边；皮尔图拉斯担心，如果没有超自然的干预，她只剩下最后几口气，灵魂就会永远消散在黑夜之中。"},{t="陨落的月亮石",b="为了使这个女孩重获新生，皮尔图拉斯转向了月亮石的魔法——这些天界碎片曾经自由地坠落在阿斯特兰纳东南方的坠星湖水域中。这些遗迹传统上由暗夜精灵收集并用于其恢复性的特性，但现在这些月光恩赐的遗留物已被充满攻击性的元素或受腐蚀的树皮生物占据，使得收集它们变成了刀剑与法术的较量，而非平和的采摘。"},{t="影冠领地",b="当影冠沼泽兽迁入并占领了周围的荒野后，暗夜精灵就失去了轻松进入该湖泊的机会。它们的领袖，影冠神谕者，将每一颗陨落的月亮石囤积在湖中心的一个孤立小岛上。即使是想要收回一颗圣物，也需要在瑞拉拉体力耗尽之前面对并杀死这位神谕者。皮尔图拉斯将回收的月亮石碾碎泡茶，瑞拉拉喝下后恢复了体力。"}},faq={{q="既然瑞拉拉已经退烧了，为什么还需要月亮石？",a="剧烈的高烧严重耗尽了瑞拉拉的生命力，导致自然休息无法使她恢复。她的父亲皮尔图拉斯相信，只有陨落的月亮石所蕴含的纯净恢复力量，才能在她因精疲力竭而倒下之前恢复她枯竭的灵魂。",al={"为什么需要月亮石","瑞拉拉仍然生病","瑞拉拉退烧了"}},{q="坠星湖位于何处？",a="坠星湖位于灰谷中东部，阿斯特兰纳的东南方。这里被古老且充满敌意的沼泽兽所占据，湖中心有一座小岛。",al={"坠星湖在哪里","湖泊位置","影冠湖位置"}},{q="谁拥有陨落的月亮石？",a="月亮石由影冠神谕者持有，它是栖息在该湖泊中的敌对沼泽兽的首领。这位神谕者就在坠星湖正中心的一座岛屿上筑巢。",al={"谁掉落月亮石","影冠神谕者位置","哪里获取月亮石"}},{q="这个任务之后会发生什么？",a="这是皮尔图拉斯寻找疗法任务中的最后一项差事。他需要一颗陨落的月亮石来恢复瑞拉拉的体力；当石头送达后，她的命运将揭晓。",al={"有后续任务吗","接下来做什么","任务后续"}},{q="为什么影冠生物要囤积月亮石？",a="随着灰谷中的野生生物和沼泽兽变得日益暴躁和腐化，影冠生物开始暴力驱逐外来者。它们的神谕者系统性地收集并守卫着这些月光遗物，拒绝让阿斯特兰纳的暗夜精灵获得它们。",al={"为什么树精在抢石头","神谕者囤积月亮石"}},{q="在这项任务之前有哪些前置任务？",a="该任务链始于“巴斯兰的头发”，随后是“奥雷迪尔的药剂”、“月神之泪”和“星尘废墟”。每一步都在收集稀有成分来治疗瑞拉拉不断恶化的病情。",al={"坠星湖之前的任务链","任务前提","之前有什么任务"}}},fp="15,266,27.309.0,20.316.0,23.397.1,60.211.0,33.157.0,29.155.0,30.169.1,50.233.0,42.179.0"}
P.entries["quest:1037"] = {n="维琳德·星歌",s="这个任务在灰谷的一场诡异调查与达纳苏斯的军事层级之间架起了一座桥梁。在发现与失踪的暗夜精灵指挥官维琳德·星歌有关的不安事件后，冒险者被派往海外，就她的神秘命运向哨兵领导层进行咨询。",h="这个任务在灰谷的一场诡异调查与达纳苏斯的军事层级之间架起了一座桥梁。在发现与失踪的暗夜精灵指挥官维琳德·星歌有关的不安事件后，冒险者被派往海外，就她的神秘命运向哨兵领导层进行咨询。",kw={"灰谷","达纳苏斯","费伍德森林","梅丽瑞亚·霜影","哨兵","塞恩提尔·刃纹","维琳德·星歌","战士区"},ang={["class:Priest"]="艾露恩的牧师们会特别感兴趣，想了解这位信仰姐妹在试图阻止从费伍德森林涌出的恶魔浪潮时是如何挣扎的。",["faction:Alliance"]="这个任务展示了达纳苏斯严苛的军事规程，在这里，敏感的战场失踪事件被哨兵指挥官们严格地保密起来。",["race:NightElf"]="对于暗夜精灵的保卫者来说，揭开一位受人尊敬的指挥官兼女祭司的命运，触及了第三次战争后卡利姆多北部脆弱的局势。"},sec={{t="失踪的前任",b="哨兵梅丽瑞亚·霜影在灰谷守望，但她并非第一个承担此重任的人。在她之前是维琳德·星歌，一位负责遏制从费伍德森林向南蔓延的恶魔腐蚀的女祭司。虽然最初的报告显示星歌已经控制住了险情，但她的防御战役却逐渐崩溃。随后，在没有预警也没有正式交接的情况下，她彻底消失了，留下了一场未竟的战争和未解的谜团。"},{t="露台的秘密",b="在森林中发现令人不安的线索后，梅丽瑞亚不愿让谜团悬而未决，于是指引寻求者前往首都达纳苏斯。在那里，高耸于战士区的哨兵指挥官塞恩提尔·刃纹负责统筹军事部署。虽然关于星歌突然离职的传言在军中不胫而走，但具体的细节仍被高层严密封锁，需要真诚的劝说才能解开更深层的记录。"}},faq={{q="维琳德·星歌是谁？",a="维琳德·星歌是一位驻扎在灰谷的暗夜精灵女祭司和哨兵指挥官。在神秘失踪之前，她的任务是守住北部边境，抵御从费伍德森林蔓延出的恶魔恐怖。",al={"维琳德·星歌背景故事","维琳德是谁","女祭司维琳德"}},{q="为什么哨兵梅丽瑞亚现在要询问关于她的事？",a="哨兵梅丽瑞亚·霜影是在维琳德莫名失踪后接替她的。随着与狼嚎谷有关的发现，梅丽瑞亚意识到，无论她的前任发生了什么，这依然是灰谷安全的一个长期隐患。",al={"为何调查维琳德","梅丽瑞亚任务缘由"}},{q="我需要去哪里完成这个任务？",a="你必须从灰谷前往位于泰达希尔之上的暗夜精灵首都达纳苏斯。指挥官塞恩提尔·刃纹就驻扎在战士区。",al={"维琳德·星歌任务交还地点","塞恩提尔·刃纹位置"}},{q="为什么指挥官刃纹不愿交谈？",a="虽然维琳德失踪在哨兵中已是众所周知的事，但围绕她最后任务的具体情况和机密细节属于敏感的军事事务，领导层不会轻易向外人透露。",al={"为何保密","为何塞恩提尔不愿交谈"}},{q="维琳德与费伍德森林有什么联系？",a="维琳德领导了哨兵在第一线遏制从费伍德森林侵入的恶魔腐蚀的努力。尽管她最初的遏制工作看起来很成功，但她的战役最终在她失踪前失败了。",al={"维琳德与费伍德森林","费伍德森林发生了什么"}},{q="哪个任务直接引向了这个任务？",a="此项任务紧随“狼嚎谷”之后，在该任务中，冒险者调查了灰谷森林深处酝酿的奇异且充满敌意的事件。",al={"维琳德·星歌前置任务","上一个任务"}}},fp="16,210,22.393.0,22.318.1,25.191.0,45.166.0,45.122.0,47.172.0,45.159.0,40.108.0"}
P.entries["quest:1038"] = {n="维琳德的日记",s="“维琳德的遗物”是达纳苏斯的一项联盟调查任务，旨在查明哨兵Velinde Starsong的下落。在塞恩提尔·刃纹的指引下，冒险者们需要从哨兵宿舍的一个箱子里取回Velinde的私人日志，以了解这位受人尊敬的女祭司为何失踪。",h="“维琳德的遗物”是达纳苏斯的一项联盟调查任务，旨在查明哨兵Velinde...",kw={"刃纹","宿舍","达纳苏斯","日志","mel'thandris","哨兵","starsong","thyn'tel","贸易区","velinde"},ang={["class:Priest"]="Velinde曾是一位受人尊敬的女祭司，她对神圣职责的坚守，使得艾露恩的信徒们有充分的理由去追查究竟是什么导致她误入歧途。",["faction:Alliance"]="对暗夜精灵高级军官的调查突显了卡利姆多各地挥之不去的威胁，而达纳苏斯羽翼未丰的联盟领导层正努力遏制这些威胁。",["race:NightElf"]="Velinde Starsong代表了The Sisterhood of Elune和哨兵们所做的默默牺牲，她的突然失踪让达纳苏斯的族人们深感不安。"},sec={{t="一位值得信赖的哨兵",b="女祭司Velinde Starsong凭借其长期以来的忠诚服务，在暗夜精灵中赢得了极大的信任。当她悄然离开岗位失踪时，哨兵们以为她是因为个人原因而离开，并期待着她的归来。直到外来者发现了与Tome of Mel'Thandris有关的线索，哨兵指挥部才允许对她的私人物品进行调查。"},{t="宿舍里的箱子",b="塞恩提尔·刃纹驻扎在达纳苏斯的战士区，他提供了一把钥匙，用于打开存放在贸易区哨兵宿舍里的Velinde的锁着的行李箱。箱子里装着Velinde的私人日志，详细记录了她的任务和内心想法。这本日志非但没有让哨兵们感到安心，反而暗示了一些可怕的、秘密的事件，正是这些事件促使她独自离开了泰达希尔。"}},faq={{q="Velinde Starsong是谁？",a="Velinde Starsong是一位受人尊敬的暗夜精灵女祭司兼哨兵指挥官。她因其忠诚的服务在同僚中深得敬重，但在执行一项无法解释的任务时突然失踪了。",al={"velinde starsong背景故事","velinde是谁","velinde背景故事"}},{q="Velinde的箱子在哪里？",a="该箱子保存在达纳苏斯贸易区一栋建筑的上层哨兵宿舍中，通过隔壁锁甲护甲店的高架桥即可到达。",al={"velinde箱子位置","维琳德的遗物在哪里","达纳苏斯哨兵宿舍"}},{q="为什么哨兵们没有早点寻找她？",a="由于Velinde享有极高的声誉，她的指挥官们认为她是因为正当的私人原因而离开，并推测她会在事情处理完后回来。",al={"为什么哨兵们忽视了velinde","为什么没有报告velinde失踪"}},{q="在日志中发现了什么？",a="她的日志显示，她的离去远比例行休假更令人不安，这促使塞恩提尔·刃纹立即寻求外援来追踪她的旅行路线。",al={"velinde的日志内容","velinde写了什么"}},{q="Velinde与Tome of Mel'Thandris有什么联系？",a="这本古老的精灵文献中包含了关于她过去调查和活动的记录，成为了吸引研究者和冒险者调查她下落的最初契机。",al={"tome of mel'thandris与velinde","为什么是tome of mel'thandris"}},{q="找到她的遗物后，调查指向哪里？",a="日志中的线索将调查者引向了贫瘠之地，沿着Velinde的足迹向南追踪至卡利姆多的交通枢纽和港口。",al={"完成维琳德的遗物后去哪","维琳德的遗物的后续任务"}}},fp="17,239,18.366.0,26.383.1,24.177.0,33.192.0,48.170.0,38.150.0,54.178.0,60.118.1"}
P.entries["quest:1039"] = {n="贫瘠之地的港口",s="“贫瘠之地的港口”是达纳苏斯的塞恩提尔·刃纹给予联盟玩家的一项任务，这是调查维琳德·星歌失踪事件的一部分。哨兵部队认为维琳德乘船横跨无尽之海前往了东部王国，因此指引你穿越危险的部落领地，前往地精掌控的棘齿城港口，查阅码头管理员迪兹维格的账目。",h="“贫瘠之地的港口”是达纳苏斯的塞恩提尔·刃纹给予联盟玩家的一项任务，这是调查维琳德·星歌失踪事件的一部分。哨兵部队认为维琳德乘船横跨无尽之海前往了东部王国，因此指引你穿越危险的部落领地，前往地精掌控的棘齿城港口，查阅码头...",kw={"灰谷","棘齿城","艾露恩之镰","热砂港","贫瘠之地","塞恩提尔·刃纹","维琳德·星歌","码头管理员迪兹维格"},ang={["faction:Alliance"]="穿越卡利姆多的心脏地带使得联盟侦察兵暴露在贫瘠之地沉重的部落巡逻队面前，在到达地精码头这个中立避风港之前需要格外小心。",["race:NightElf"]="维琳德·星歌是一位受人尊敬的哨兵，她的失踪让达纳苏斯的领导层感到沉重；重走她那绝望的旅程是卡多雷的职责所在。"},sec={{t="追踪女祭司",b="在检查了维琳德·星歌的个人物品后，哨兵部队发现了线索，暗示她曾试图寻找横跨海洋前往东部王国的航线。棘齿城是贫瘠之地唯一运作的海运港口，也是北卡利姆多的旅客若不想直接从暗夜精灵领地乘船离开，唯一能够安排前往南方或东方航运的通道。塞恩提尔·刃纹派遣你向南前往，查阅码头管理员的航运账目，寻找任何有关维琳德名字的迹象。"},{t="危险的旅程",b="前往棘齿城需要联盟探员勇敢地深入部落控制之地的核心。灰谷以南，莫尔杉壁垒和贫瘠之地干旱的草原上到处都是兽人斥候和牛头人巡逻队。棘齿城本身由中立的热砂港管辖，在地精法律下提供安全的避风港，那里的贸易高于阵营纷争，码头管理员迪兹维格仔细追踪着每一位经过码头的乘客和每一个货物板条箱。"}},faq={{q="为什么哨兵部队派我前往贫瘠之地？",a="棘齿城是卡利姆多中部主要的贸易中立港口。自从维琳德·星歌失踪并寻求前往东部王国的通道后，暗夜精灵推断她很可能搭乘了一艘地精商船安全出海，而不是通过官方军事渠道。",al={"为什么要前往棘齿城","为什么是贫瘠之地的港口"}},{q="码头管理员迪兹维格是谁？",a="码头管理员迪兹维格是负责监督棘齿城码头离港和货物登记的地精官员。他代表热砂港工作，并保留着详尽的账目，详细记录了进出港口的每一艘船只、每一名乘客和每一批货物。",al={"迪兹维格是谁","棘齿城码头管理员"}},{q="为什么联盟成员在棘齿城是安全的？",a="棘齿城由中立的热砂港运营，而非部落。地精将商业和利润置于阵营纷争之上，这意味着他们的保镖会维持和平，并允许联盟旅客在不违反城内禁止动武规定的前提下平安地进行交易。",al={"棘齿城对联盟安全吗","守卫会在棘齿城攻击我吗"}},{q="找到码头管理员迪兹维格后会发生什么？",a="一旦迪兹维格核对了舱单，他便会确认维琳德搭乘了一艘前往东部王国的船只，并指引你继续前往荆棘谷的藏宝海湾，以便在无尽之海的另一侧拾起她的踪迹。",al={"贫瘠之地的港口任务后做什么","维琳德任务后续"}},{q="联盟旅客如何安全到达棘齿城？",a="联盟旅客通常从灰谷向南旅行，经过银翼树林，绕过重兵把守的莫尔杉壁垒，穿过大路以东的丘陵。一旦进入贫瘠之地，沿着通往东海岸的道路走，就能直接到达棘齿城的码头。",al={"联盟去棘齿城最安全的路","联盟如何前往棘齿城"}},{q="维琳德·星歌是谁？",a="维琳德·星歌是一位暗夜精灵女祭司，也是梅莉亚·霜影在灰谷的前任，负责清除森林中的恶魔。她的努力逐渐受挫，直到她突然失踪，现在看来她的踪迹指向了海的另一边。",al={"维琳德是谁","维琳德·星歌背景故事"}}},fp="16,223,22.365.0,20.349.0,46.267.0,28.204.0,48.236.0,48.197.1,51.240.0,24.225.0"}
P.entries["quest:104"] = {n="海岸上的威胁",s="葛瑞森船长那不得安宁的幽灵在西部荒野的岩石海岸边徘徊，他深受那场让他丧命的沉船事故，以及灯塔守卫一家惨遭屠杀的记忆所折磨。他委托旅人们去猎杀那个罪魁祸首：鱼人头目老瞎眼。将这头野兽击杀不仅能为海岸带来一丝公正，也有助于保护未来的航海者。",h="葛瑞森船长那不得安宁的幽灵在西部荒野的岩石海岸边徘徊，他深受那场让他丧命的沉船事故，以及灯塔守卫一家惨遭屠杀的记忆所折磨。他委托旅人们去猎杀那个罪魁祸首：鱼人头目老瞎眼。将这头野兽击杀不仅能为海岸带来一丝公正，也有助于保...",kw={"葛瑞森船长","海岸威胁","无尽之海","鱼人","老瞎眼","老瞎眼的鳞片","西部荒野","西部荒野灯塔"},ang={["faction:Alliance"]="西部荒野的沿海水域是暴风城重要的航运通道。铲除像老瞎眼这样的领袖，能确保南部海运路线的畅通，使其免受破坏。",["race:Human"]="灯塔守卫一家的遇害是西部荒野失去安宁这一残酷篇章的又一例证，这也为向王国的同胞复仇增添了一份个人的分量。"},sec={{t="黑暗中的指路明灯",b="西部荒野灯塔是这片南部海岸布满礁石的浅滩中唯一的指路明灯，但它的光芒却在血腥的悲剧中几度闪烁。当葛瑞森船长的船在黑暗中撞上岩石沉没时，他失去了生命。那场事故的起因是鱼人恐吓了灯塔守卫的一家，迫使他们弃守岗位。尽管这家人后来回来重新点亮了灯火，但他们获得的喘息机会转瞬即逝。海岸线依然被一只极为狡猾且残忍的掠食者所窥伺。"},{t="海岸的灾祸",b="老瞎眼不仅仅是在潮汐水潭边徘徊的又一头野兽。葛瑞森讲述说，他亲眼看着这个生物在海岸边蛊惑了那些心智薄弱的鱼人，并将它们集结起来，对灯塔发动了协同袭击。第二次突袭最终导致了惨剧，在葛瑞森无助的幽灵之眼的注视下，守塔人一家被尽数屠戮。为了让死者安息并维护无尽之海残存的安宁，这位幽灵船长要求击杀老瞎眼，并以它的一片鳞片作为证明。"}},faq={{q="谁是老瞎眼？",a="老瞎眼是一个臭名昭著、狡猾无比的鱼人头目，它在西部荒野的南部海岸线徘徊。与普通的鱼人不同，它拥有足够的邪恶智慧，能够集结并指挥它的族群，对岸边的人类定居点发动协同且致命的袭击。",al={"老瞎眼","谁是老瞎眼","谁是海岸威胁"}},{q="为什么葛瑞森船长想要老瞎眼死？",a="葛瑞森的船撞上岩石是因为老瞎眼和它的追随者吓跑了灯塔守卫，让海岸陷入了黑暗。后来，葛瑞森无助地目睹了老瞎眼领导了第二次突袭，屠杀了返回岗位守塔的守卫一家。",al={"葛瑞森的怨恨","为什么要杀老瞎眼","葛瑞森背景故事"}},{q="在哪里可以找到老瞎眼？",a="老瞎眼在西部荒野海岸的开阔沙滩和浅滩上巡逻，通常出现在西部荒野灯塔周边的水域以及附近的鱼人营地附近。",al={"老瞎眼位置","在哪里找到老瞎眼","寻找老瞎眼"}},{q="葛瑞森要求什么证明？",a="葛瑞森船长要求从老瞎眼的皮上剥下一片鳞片，以确认这个海岸的恐怖威胁终于被消灭了。",al={"死亡证明","老瞎眼的鳞片","任务交还"}},{q="葛瑞森船长生前是谁？",a="葛瑞森船长是一位船长，他的船在西部荒野灯塔下的岩石中终结了航程。死后，他的灵魂徘徊在海岸附近，寻求向鱼人复仇，并试图让这片水域对过往的船只来说更加安全。",al={"葛瑞森船长","灯塔幽灵"}},{q="灯塔守卫一家遭遇了什么？",a="守塔人一家最初是在老瞎眼骚扰灯塔时逃离的。在他们勇敢地返回并重新点亮灯火后，老瞎眼又胁迫了一群鱼人对灯塔发动了第二次突袭，并将全家人屠杀殆尽。",al={"守卫家庭","谁住在灯塔","灯塔屠杀"}}},fp="18,297,20.346.0,24.330.0,20.169.0,48.276.0,32.117.0,32.89.0,32.205.0,48.181.0"}
P.entries["quest:1040"] = {n="藏宝海湾的航道",s="这一任务将追踪失踪的哨兵维琳德·星歌穿越无尽之海，前往法外之地藏宝海湾。在码头管理员迪兹维格发现的航运记录指引下，联盟的旅行者必须从棘齿城前往东部王国，寻找一位名叫拉兹戈特的地精商队车夫。",h="这一任务将追踪失踪的哨兵维琳德·星歌穿越无尽之海，前往法外之地藏宝海湾。在码头管理员迪兹维格发现的航运记录指引下，联盟的旅行者必须从棘齿城前往东部王国，寻找一位名叫拉兹戈特的地精商队车夫。",kw={"黑隼号","藏宝海湾","旅行者拉兹戈特","通往藏宝海湾","棘齿城","艾露恩之镰","维琳德·星歌","码头管理员迪兹维格"},ang={["faction:Alliance"]="在棘齿城和藏宝海湾这类中立地精领地航行需要耐心与外交手腕，这迫使联盟旅行者必须与雇佣兵和财阀官僚打交道。",["race:NightElf"]="寻找维琳德·星歌对卡多雷来说是一项紧迫的职责，因为她带着艾露恩之镰失踪，在灰谷的森林中留下了一个挥之不去的危险谜团。"},sec={{t="穿越海洋的足迹",b="对暗夜精灵哨兵维琳德·星歌的搜寻使人们离开了熟悉的灰谷树荫，踏上了远洋贸易航线。在热闹的地精港口棘齿城，码头管理员迪兹维格最终发掘出旧的航运清单，确认维琳德预订了名为“黑隼号”的船只，直接前往位于荆棘谷的海盗避风港——藏宝海湾。"},{t="通往藏宝海湾之路",b="前往藏宝海湾需要搭乘在棘齿城和东部王国南端之间往返的中立地精跨洋渡轮。抵达后，线索指向了旅行者拉兹戈特，他是迪兹维格向维琳德推荐的地精运输专家，当时维琳德曾打听过关于穿越南部荒野的危险陆路旅程的相关信息。"}},faq={{q="维琳德·星歌是谁？",a="维琳德·星歌是一位暗夜精灵祭司，她曾在灰谷领导抵抗费伍德森林恶魔势力的战斗。她的努力逐渐受挫，直到最终失踪，如今哨兵们正在追踪她穿越海洋的旅程。",al={"维琳德","维琳德是谁","维琳德·星歌背景故事"}},{q="维琳德为什么要前往藏宝海湾？",a="藏宝海湾是连接卡利姆多中部与东部王国南端的主要海上枢纽。维琳德需要穿越无尽之海，而从棘齿城出发的黑隼号提供了前往人类和矮人王国的直达航线，她在那里询问了关于陆路旅行的情况。",al={"为什么要去藏宝海湾","维琳德 藏宝海湾","她为什么去藏宝海湾"}},{q="码头管理员迪兹维格是谁？",a="码头管理员迪兹维格为热砂港管理着棘齿城的码头。他以脾气暴躁著称，负责维护港口的航海日志以及所有往返于卡利姆多和东部王国之间的船只载货清单。",al={"迪兹维格","迪兹维格是谁","码头管理员"}},{q="旅行者拉兹戈特是谁？",a="旅行者拉兹戈特是一位常驻藏宝海湾的地精车夫，他负责协调补给车队，并安排穿越荆棘谷危险丛林及更远地区的陆路运输。",al={"拉兹戈特","旅行者拉兹戈特","拉兹戈特是谁"}},{q="维琳德乘坐的是哪艘船？",a="根据码头管理员迪兹维格的航运记录，维琳德·星歌预订了黑隼号的船位，该船成功地从棘齿城穿越无尽之海，抵达了藏宝海湾。",al={"维琳德的船","维琳德乘坐什么船","黑隼号"}},{q="我该如何从棘齿城前往藏宝海湾？",a="热砂港运营着一艘客运渡轮，直接从棘齿城的南码头出发，穿越无尽之海，停靠在位于荆棘谷南端的海盗港口藏宝海湾。",al={"前往藏宝海湾","如何前往藏宝海湾","前往藏宝海湾的船"}}},fp="20,166,22.298.0,21.299.0,24.201.0,36.195.0,28.210.0,26.176.0,27.172.0,42.164.0"}
P.entries["quest:1041"] = {n="商队通路",s="“商旅之路”是一项联盟任务，旨在追寻失踪的暗夜精灵女祭司维琳德·星歌的踪迹。根据在藏宝海湾获得的情报，这条线索从荆棘谷危险的丛林向北延伸，直抵笼罩在阴影之中的夜色镇。",h="“商旅之路”是一项联盟任务，旨在追寻失踪的暗夜精灵女祭司维琳德·星歌的踪迹。根据在藏宝海湾获得的情报，这条线索从荆棘谷危险的丛林向北延伸，直抵笼罩在阴影之中的夜色镇。",kw={"藏宝海湾","旅行者拉兹戈特","书记员达尔塔","夜色镇","暮色森林","荆棘谷","商旅之路","维琳德·星歌"},ang={["faction:Alliance"]="在中立地精港口和像夜色镇这样偏远的联盟哨所之间传递消息，加强了在这个因近期战争而分崩离析的世界中的联系。",["race:NightElf"]="维琳德·星歌是一位受人尊敬的艾露恩哨兵女祭司，她在东部王国的隐秘行动引起了她在卡利姆多的族人的深切担忧。"},sec={{t="丛林中的女祭司",b="为了追踪维琳德·星歌，冒险者们跨越了整个世界，从灰谷的森林一直来到了南方的港口城市藏宝海湾。在那里，旅行者拉兹戈特回想起了一位不同寻常的乘客：一位曾搭乘他那尘土飞扬的商队的暗夜精灵女祭司。对于她的族人来说，这样的独行极其罕见，这使得她穿越荆棘谷无法无天的丛林的旅程在商人们心中留下了深刻的印象。"},{t="北上夜色镇",b="据拉兹戈特所言，他和维琳德在穿越丛林北上的途中分道扬镳，这位女祭司随后动身前往暮色森林。她的线索直指饱受困扰的夜色镇，那里的城镇记录由书记员达尔塔严谨地维护着。在这个深受超自然威胁困扰的时代，达尔塔会记录下每一位进入定居点的陌生旅行者，这使得他的账簿成为了解开维琳德命运的下一个关键环节。"}},faq={{q="维琳德·星歌是谁？",a="维琳德·星歌是一位艾露恩的暗夜精灵女祭司，她因神秘的原因离开了自己在卡利姆多的家园。她的失踪引发了横跨各大洲的广泛搜寻，人们追踪着她从灰谷前往东部王国的旅程。",al={"维琳德","谁是维琳德","我们在寻找谁"}},{q="为什么维琳德要搭乘商队？",a="维琳德独自一人穿越地精领地，她在藏宝海湾雇用了旅行者拉兹戈特的商队，以便完成向北穿越荆棘谷的危险陆路旅程。",al={"为什么搭乘商队","维琳德商队","拉兹戈特商队"}},{q="书记员达尔塔是谁？",a="书记员达尔塔是暮色森林夜色镇的城镇书记员兼档案管理员。鉴于该地区弥漫的威胁和频发的怪事，他会对进入城镇的外部人员和访客进行详细记录。",al={"书记员达尔塔","达尔塔夜色镇","谁是达尔塔"}},{q="在夜色镇之后，这条任务线通向何处？",a="在查阅过书记员达尔塔的市政记录后，他会指引旅行者去寻找乔纳森·卡尔文，从而开启任务“卡尔文家族”，以揭开更多关于维琳德在暮色森林逗留的细节。",al={"后续任务","what comes next","夜色镇之后"}},{q="为什么从藏宝海湾前往夜色镇很危险？",a="荆棘谷到处都是掠食性野兽、敌对的巨魔部落以及血帆海盗，这些威胁远比暮色森林当地的生物危险得多。想要向北通行，必须紧贴大路行进。",al={"丛林危险","荆棘谷等级","荆棘谷危险"}},{q="这项调查是从哪里开始的？",a="搜寻始于灰谷，暗夜精灵调查员在那里注意到维琳德带着一件拥有强大力量的神器莫名离开，随后根据线索追踪到了一艘驶往南方海域的船只。",al={"起点","任务线从哪里开始","灰谷开始"}}},fp="16,191,25.308.0,18.307.0,24.238.0,41.162.0,20.155.0,49.170.1,55.178.0,35.186.0"}
P.entries["quest:1042"] = {n="卡尔文家族",s="“卡尔文家族”是一个简短的联盟调查任务，将维琳德·星歌的谜团与暮色森林的怪物猎人联系在了一起。在夜色镇的档案管理员书记员达尔塔的指引下，寻找失踪女祭司的冒险者们求助于乔纳森·卡尔文，他是该家族的族长，致力于猎杀野兽和邪魔。",h="“卡尔文家族”是一个简短的联盟调查任务，将维琳德·星歌的谜团与暮色森林的怪物猎人联系在了一起。在夜色镇的档案管理员书记员达尔塔的指引下，寻找失踪女祭司的冒险者们求助于乔纳森·卡尔文，他是该家族的族长，致力于猎杀野兽和邪魔...",kw={"卡洛尔","卡尔文家族","书记员达尔塔","夜色镇","暮色森林","乔纳森·卡尔文","维琳德·星歌","狼人"},ang={["class:Hunter"]="卡尔文家族代表了一群坚韧的城镇周边野兽猎人，他们专门从事清除超自然邪魔和被诅咒的捕食者的工作。",["faction:Alliance"]="调查的这一阶段突显了暮色森林中的联盟定居点为了在被诅咒的森林中生存下去，必须保持怎样的孤立与警惕。",["race:NightElf"]="发现人类怪物猎人手持与维琳德·星歌有关的生物的断头，对于追踪这位女祭司命运之旅的暗夜精灵来说，是一条令人不安的线索。"},sec={{t="利爪与阴影的踪迹",b="寻找维琳德·星歌的过程使人从卡利姆多古老的森林一路深入到暮色森林那阴森的迷雾之中。到达夜色镇后，市政书记员达尔塔没有找到任何关于这位精灵女祭司曾在镇上投宿的官方记录。然而，当提到在灰谷见到的野蛮狼人时，他立刻引起了警觉，因为符合这一描述的野兽最近已经开始在周围的树林中制造恐怖事件。"},{t="夜幕猎手",b="对付这种超自然恐怖威胁的任务并非由普通的城镇卫兵负责，而是落在了卡尔文家族身上。他们作为恶魔、亡灵和其他恐怖生物的无情猎手而在当地闻名。他们的追踪者卡洛尔最近拖着一串血淋淋的狼人头颅穿过了夜色镇的街道。书记员达尔塔指引外来者去寻找乔纳森·卡尔文，这位严厉的族长，以便了解该家族对这些凶残的狼人有哪些了解。"},{t="冷遇",b="接近卡尔文家族的族长可不是什么轻松的会面。由于饱受吞噬暮色森林的无尽恐怖威胁，乔纳森·卡尔文对任何不请自来、打听狼人的陌生人都抱有极大的戒心。在分享他的猎手们关于这些野兽的发现之前，他要求知道站在他面前的是谁，以及为什么他们要寻求那些最好被埋藏在黑暗中的东西。"}},faq={{q="乔纳森·卡尔文是谁？",a="乔纳森·卡尔文是夜色镇卡尔文家族的族长。他带领着一个家族，在这个被诅咒的地区，他们以专门追踪和猎杀恶魔、亡灵和怪物猎手的资深猎人而闻名。",al={"乔纳森·卡尔文","卡尔文是谁","卡尔文家族族长"}},{q="书记员达尔塔为什么要指引你去找卡尔文家族？",a="虽然书记员达尔塔没有关于失踪的暗夜精灵维琳德·星歌的记录，但他认出了你所描述的狼人。卡尔文家族的追踪者卡洛尔最近将这些生物的残骸带进了夜色镇，这使该家族成为了镇上处理这些怪物的首要专家。",al={"为什么要见卡尔文","书记员达尔塔与卡尔文","为什么要去找乔纳森"}},{q="卡洛尔是谁？",a="卡洛尔是与夜色镇卡尔文家族结盟的一名猎人和追踪者。他最近带了一串被砍下的狼人头颅走进镇子，给镇民留下了毛骨悚然的印象，这证明了狼人正在附近活动。",al={"卡洛尔","卡洛尔是谁","卡尔文家族猎人卡洛尔"}},{q="这个任务是如何将灰谷和暮色森林联系在一起的？",a="该任务线起源于灰谷，起因是维琳德·星歌的失踪和狼人的神秘出现。追踪商队路线可以从卡利姆多跨越海洋到达暮色森林，同样凶猛的狼形野兽也出现在了那里。",al={"维琳德·星歌的联系","为什么是暮色森林","从灰谷到夜色镇"}},{q="为什么乔纳森·卡尔文对陌生人如此怀疑？",a="暮色森林完全被阴影、亡灵和邪恶势力所侵蚀，这使得幸存的居民产生了深深的偏执。当一个不知名的冒险者突然赶来询问致命的狼人时，乔纳森会怀疑对方动机不纯，直到旅行者证明了自己的身份。",al={"为什么卡尔文充满敌意","卡尔文的怀疑"}},{q="卡尔文家族擅长猎杀什么怪物？",a="卡尔文家族致力于消灭怪物威胁，主要是恶魔、亡灵和像纠缠暮色森林的狼人那样离奇变异的野兽。",al={"卡尔文猎杀的怪物","卡尔文家族猎杀什么"}}},fp="18,165,28.308.0,20.402.0,16.314.1,24.182.0,55.263.0,13.195.0,50.228.0,51.219.0,53.126.0"}
P.entries["quest:1043"] = {n="月神的镰刀",s="“艾露恩之镰”是一项联盟的任务，旨在将卡利姆多的一件古老的暗夜精灵遗物与肆虐暮色森林的狼人瘟疫联系起来。冒险者受夜色镇的乔纳森·卡尔文之托，深入阴森的罗兰之墓，试图揭开究竟是什么将这些凶残的野兽引到了东部王国。",h="“艾露恩之镰”是一项联盟的任务，旨在将卡利姆多的一件古老的暗夜精灵遗物与肆虐暮色森林的狼人瘟疫联系起来。冒险者受夜色镇的乔纳森·卡尔文之托，深入阴森的罗兰之墓，试图揭开究竟是什么将这些凶残的野兽引到了东部王国。",kw={"卡洛尔","夜色镇","暮色森林","乔纳森·卡尔文","夜行狼人","罗兰之墓","艾露恩之镰","维琳德·星歌","狼人"},ang={["class:Druid"]="由艾露恩之镰释放的狂野且不可驯服的狼人，为德鲁伊们敲响了关于失控力量的警钟。",["faction:Alliance"]="揭开夜行狼人的谜团，为夜色镇和联盟提供了关于潜伏在暮色森林南部的恐怖事件的第一手确凿答案。",["race:NightElf"]="找到维琳德·星歌祭司的最终安息地，揭示了当艾露恩之镰脱离姐妹会监管时所付出的惨痛代价。"},sec={{t="黑暗中的狩猎",b="在追踪神秘的维琳德·星歌祭司穿过卡利姆多，并与夜色镇的卡尔文家族交谈后，旅行者们与乔纳森·卡尔文达成了共识。夜行狼人已经占领了暮色森林南部，赶走了矿工，并威胁到了镇上仅存的居民。虽然卡尔文并不完全了解这些野兽的超自然起源，但他认识到愿意铲除它们的人的价值，于是指引搜寻者前往罗兰之墓——这些恶魔最初被发现的矿坑。"},{t="罗兰之墓的幽灵",b="在罗兰之墓的更深处，在一群凶残的夜行狼人中间，有一堆未被触动过的土堆。触动这些土壤会唤醒维琳德·星歌本人的残影。这个鬼魂证实，这位暗夜精灵祭司带着艾露恩之镰进入了这个凄惨的洞穴，却在暮色森林的土地下遭遇了悲剧且神秘的结局。她的幽灵哀叹说，她释放的狼人现在正肆意横行，而她从女神那里获得的镰刀也已遗失。"}},faq={{q="我在哪里寻找关于镰刀的线索？",a="前往位于暮色森林东南部的废弃矿坑罗兰之墓。杀出一条血路，穿过夜行狼人，找到隧道内一堆未被触动的泥土。",al={"镰刀在哪里","艾露恩之镰位置","罗兰之墓洞穴"}},{q="乔纳森·卡尔文是谁？",a="乔纳森·卡尔文是居住在夜色镇的卡尔文家族成员。面对抵御邪恶的人手短缺，他非常乐意与那些寻求消灭危险狼人的外来者交换情报。",al={"乔纳森·卡尔文","卡尔文夜色镇"}},{q="维琳德·星歌在矿坑里发生了什么？",a="在罗兰之墓深处，一堆未被触动的泥土里隐藏着维琳德命运的答案和镰刀的下落。检查它会揭示你带回给乔纳森·卡尔文的故事。",al={"维琳德·星歌的命运","维琳德发生了什么"}},{q="什么是艾露恩之镰？",a="艾露恩之镰是一件神圣的暗夜精灵神器，由维琳德·星歌祭司获得。哨兵部队认为这是女神艾露恩赐予她的恩惠。",al={"什么是镰刀","艾露恩之镰传说"}},{q="为什么狼人会出现在暮色森林？",a="据乔纳森·卡尔文所说，狼人是凭空出现的，而南部的罗兰之墓是他们最初被发现的地方。在那个矿坑中搜寻艾露恩之镰的线索就能找到原因。",al={"为什么暮色森林有狼人","暮色森林狼人起源"}},{q="卡洛尔是谁？",a="卡洛尔是夜色镇卡尔文家族的一名成员，在冒险者于罗兰之墓发现真相后，乔纳森指示他全力专注于遏制狼人的威胁。",al={"npc卡洛尔","卡洛尔是谁"}}},fp="19,238,18.479.0,23.406.1,40.150.0,24.171.0,46.185.1,28.159.0,38.181.1,13.172.1"}
P.entries["quest:1044"] = {n="回复珊蒂斯",s="对 Velinde Starsong 的搜寻带你从灰谷来到 Darnassus，一份报告正在那里等候。",h="对 Velinde Starsong 的搜寻带你从灰谷来到 Darnassus，一份报告正在那里等候。",kw={"已回答的问题","达纳苏斯","暮色森林","乔纳森·卡尔文","罗兰之墓","艾露恩之镰","塞恩提尔·刃纹","维林德·星歌","狼人"},ang={["class:Priest"]="艾露恩的祭司们对维林德的故事有着深刻的精神共鸣，她们既认识到了女神恩赐的力量，也意识到了试图驾驭未知野兽的危险与愚蠢。",["faction:Alliance"]="该任务突显了卡利姆多的暗夜精灵与饱受困扰的暮色森林人类定居点之间，因共同面对阴影威胁而建立的脆弱的跨大陆联系。",["race:NightElf"]="对于暗夜精灵来说，汇报这些发现有助于领导层追踪失踪女祭司和失落神器的足迹。"},sec={{t="悲剧的真相",b="追踪维林德·星歌的任务链始于灰谷，跨越多个大陆，延伸至暮色森林阴森的树林和荒废的矿井。追踪她的足迹揭示了维林德为了保卫卡利姆多抵御恶魔势力，曾绝望地动用艾露恩之镰召唤了凶猛的狼人。然而，她失去了控制，导致了悲剧的发生，她本人也命丧罗兰之墓深处的矿井中，留下了暮色森林去面对那场怪物造成的浩劫。"},{t="回到达纳苏斯",b="在找回维林德的日记并得知她的最终结局后，暮色森林的乔纳森·卡尔文敦促冒险者返回泰达希尔。在达纳苏斯，哨兵塞恩提尔·刃纹接收了这份报告。维林德曾是高阶女祭司泰兰德·语风的挚友，因此她的噩耗对The Sisterhood of Elune而言是一个沉重的个人和精神打击。"},{t="丢失的神器",b="虽然维林德的命运最终有了定论，但一个更深层的危机仍未解决：艾露恩之镰本身消失了。这把镰刀作为女神赐予的神圣恩赐和武器，如今已遗失在荒野之中，远离了曾经尊崇它的女祭司之手。狼人在东部王国的肆虐是这一损失所带来的挥之不去且不可预测的威胁。"}},faq={{q="任务“已回答的问题”是什么？",a="“已回答的问题”是一个联盟任务，用于结束对维林德·星歌的调查。它由暮色森林的乔纳森·卡尔文开启，指引玩家将维林德的结局和艾露恩之镰的消息带回达纳苏斯，交给塞恩提尔·刃纹。",al={"已回答的问题任务","已回答的问题经典旧世","艾露恩之镰任务终章"}},{q="维林德·星歌是谁？",a="维林德·星歌是一位艾露恩的暗夜精灵女祭司，也是哨兵梅丽瑞亚·霜影在灰谷的前任，负责抵御费伍德森林中的恶魔势力。她获得了艾露恩之镰，随后失踪，她的足迹跨越重洋，一直延伸到暮色森林。",al={"维林德·星歌","维林德是谁","维林德发生了什么"}},{q="在这个任务结束时，艾露恩之镰在哪里？",a="艾露恩之镰的下落是调查的核心。乔纳森·卡尔文要求你将你所了解的情况报告给达纳苏斯的塞恩提尔·刃纹。",al={"艾露恩之镰在哪里","我们找到镰刀了吗","艾露恩之镰位置"}},{q="泰兰德·语风与维林德有何联系？",a="高阶女祭司泰兰德·语风和维林德·星歌在维林德失踪前是挚友，这使得这次搜寻对暗夜精灵领导层来说至关重要。",al={"泰兰德与维林德","高阶女祭司的联系"}},{q="乔纳森·卡尔文是谁？",a="乔纳森·卡尔文是暮色森林的一名人类居民，他协助冒险者在当地矿井中进行搜寻。他发誓要遏制暮色森林中的狼人，并派遣玩家回到卡利姆多，将发现的情况告诉维林德的族人。",al={"乔纳森·卡尔文","谁给予已回答的问题任务"}},{q="塞恩提尔·刃纹在哪里？",a="塞恩提尔·刃纹驻扎在泰达希尔岛上的达纳苏斯，为暗夜精灵领导层效力，并负责监督对失踪哨兵和女祭司的搜寻工作。",al={"塞恩提尔·刃纹在哪里","塞恩提尔·刃纹位置","已回答的问题任务交付"}}},fx={["6f485fee"]={q="乔纳森·卡尔文为什么派你返回达纳苏斯？",a="乔纳森·卡尔文明白，在暮色森林矿井中发现的事情远远超出了守夜人的职责范围。维琳德·星歌曾为暗夜精灵和女神艾露恩效力，卡尔文认为，她的命运以及月神镰刀失踪这件令人不安的事，是必须直接送到她族人所在的达纳苏斯的重要消息，不该埋没在矿井中。",al={"乔纳森·卡尔文为什么要完成这件事","乔纳森·卡尔文的动机","为什么返回达纳苏斯"}}},fp="18,95,14.461.1,19.372.1,18.380.1,37.259.1,25.269.0,54.168.1,48.163.0,24.241.1,38.171.0"}
P.entries["quest:1045"] = {n="莱恩的净化",s="通过达图尔的变形魔棒伪装自己，冒险者们赢得了Lake Mystral附近一只未受腐蚀的熊怪克罗格的信任。克罗格对傲慢的暗夜精灵和腐蚀他族人的堕落感到幻灭，他请求除掉堕落的酋长Ran Bloodtooth，以便熊怪们能清理自己的门户。",h="通过达图尔的变形魔棒伪装自己，冒险者们赢得了Lake Mystral附近一只未受腐蚀的熊怪克罗格的信任。克罗格对傲慢的暗夜精灵和腐蚀他族人的堕落感到幻灭，他请求除掉堕落的酋长Ran...",kw={"灰谷","bloodtooth卫兵","腐蚀","达图尔的变形魔棒","熊怪","克罗格","lake mystral","ran bloodtooth"},ang={["class:Druid"]="对于致力于维护灰谷平衡的德鲁伊来说，Ran Bloodtooth代表了完全屈服于恶魔腐蚀的自然生物的悲剧性堕落。",["faction:Alliance"]="在达图尔的变形魔棒的帮助下，Alliance勇士充当秘密中间人，深入敌后平定叛变的酋长。",["race:NightElf"]="与克罗格的对峙为暗夜精灵提供了一面令人不安的镜子：尽管守卫灰谷已有数千年，但当地部落直接将古代的大分裂和挥之不去的腐蚀归咎于Kaldorei的傲慢。"},sec={{t="一位痛苦的隐士",b="在Lake Mystral的水域附近，克罗格独自守护着。他流离失所，满心疲惫，对暗夜精灵怀有深深的怨恨，他认为正是这些精灵古老的傲慢给卡利姆多带来了毁灭，并引发了在灰谷滋生的黑暗腐烂。为了接近他，寻求者需要使用达图尔的变形魔棒，以便在熊怪中行走而不被发现。然而，尽管他对Kaldorei怀有苦涩的仇恨，但克罗格并不寻求毫无意义的屠杀或无辜的死亡。"},{t="清理门户",b="克罗格认为，他的族人必须对自己的行为负责，而不是完全屈服于控制着各个部落的恶魔污秽。恶魔的腐蚀并非他们缺点的根源——它只是放大了他们最坏的冲动。Ran Bloodtooth就是这种堕落的体现：在受到腐蚀之前，他就已经残忍且渴望权力，Ran热切地拥抱了黑暗，这对精灵和无辜的野兽都构成了生存威胁。克罗格拒绝让这种恶意代表所有的熊怪。"},{t="共同的职责",b="通过请求一个伪装成熊怪的外来者——借助达图尔的变形魔棒的魔法——去击杀Ran Bloodtooth和他的精英卫兵，克罗格确保了正义得到伸张，同时没有引发部落内部进一步的纷争。Ran的死打击了不断蔓延的疯狂，让一个痛苦的熊怪和一个Alliance代理人因渴望净化这片神圣的林地而短暂地团结在了一起。"}},faq={{q="克罗格为什么憎恨暗夜精灵？",a="克罗格认为暗夜精灵是傲慢的管理者，他们历史上对危险魔法的干涉给这片土地带来了腐蚀。他认为他们对灰谷的腐化状态和当地部落的苦难负有责任。",al={"克罗格对暗夜精灵的仇恨","克罗格为什么仇恨精灵","克罗格背景故事"}},{q="Ran Bloodtooth是谁？",a="Ran Bloodtooth是一个腐败且贪权的熊怪酋长，他在Lake Mystral以东的山区扎营。被毒害灰谷的黑暗力量逼疯后，他对他人的暴力渴望对森林中所有的自然生物构成了威胁。",al={"ran bloodtooth背景故事","谁是bloodtooth","ran bloodtooth"}},{q="克罗格为什么要杀掉Ran Bloodtooth？",a="尽管克罗格怨恨暗夜精灵，但他对针对无辜者的肆意野蛮行径划定了界限。他认为熊怪必须清理自己的邪恶，而Ran的腐化已经将他变成了一个威胁整个森林的怪物。",al={"为什么要击杀ran bloodtooth","克罗格对bloodtooth的动机"}},{q="Alliance玩家如何在不被攻击的情况下与克罗格交谈？",a="Alliance英雄使用达图尔的变形魔棒（在任务链中获得的一种附魔魔棒）来伪装成熊怪，从而安全地接近克罗格。",al={"如何与克罗格交谈","达图尔的变形魔棒与克罗格","克罗格为什么友好"}},{q="Ran Bloodtooth在哪里？",a="Ran Bloodtooth和他的卫兵在Lake Mystral附近克罗格避难所东边的山区维持着一个营地。",al={"ran bloodtooth的位置","ran bloodtooth在哪里","血牙营地"}},{q="击杀Ran Bloodtooth如何有助于净化灰谷？",a="击杀Ran Bloodtooth消除了最暴力、被污秽强化的熊怪之一，他是森林中每个自然生物的威胁。正如克罗格所说，森林依然受到腐蚀，但这只是使其恢复昔日荣光的一小步。",al={"净化灰谷与ran","为什么bloodtooth是raene's cleansing的一部分"}}},fp="17,321,15.445.0,18.487.0,13.357.1,36.230.0,22.236.0,40.242.0,63.162.0,32.114.0,55.238.0"}
P.entries["quest:1046"] = {n="莱恩的净化",s="这个任务标志着揭开Teronis遭遇及阻止笼罩在灰谷上空的熊怪威胁的最后篇章。冒险者带着从克罗格那里得到的兰恩·血牙的颅骨，回到了阿斯特兰纳向莱恩·狼行者哨兵报告他们这段危险旅程的终点。",h="这个任务标志着揭开Teronis遭遇及阻止笼罩在灰谷上空的熊怪威胁的最后篇章。冒险者带着从克罗格那里得到的兰恩·血牙的颅骨，回到了阿斯特兰纳向莱恩·狼行者哨兵报告他们这段危险旅程的终点。",kw={"灰谷","阿斯特兰纳","达图尔的变形棒","熊怪","克罗格","莱恩·狼行者","莱恩的净化","兰恩·血牙","teronis"},ang={["faction:Alliance"]="上交血牙的颅骨巩固了联盟保卫阿斯特兰纳并与暗夜精灵哨兵并肩作战的承诺。",["race:NightElf"]="对于卡多雷来说，终结兰恩·血牙的狂怒是对像Teronis这样阵亡盟友的纪念，也有助于收复灰谷神圣树林的圣洁。"},sec={{t="苦涩的战利品",b="在击败了凶猛的堕落熊怪酋长兰恩·血牙后，克罗格派这位勇士返回阿斯特兰纳。带着血牙被砍下的头颅，你回来作为证明，表明那潜伏在森林深处的野蛮威胁已经被彻底消灭。"},{t="纪念Teronis",b="在收到颅骨后，莱恩·狼行者将其与达图尔的变形棒一同放置在供奉之处。这个残酷的信物纪念了Teronis，正是他对净化堕落熊怪的悲剧性调查开启了整个绝望的努力。"}},faq={{q="谁是兰恩·血牙？",a="兰恩·血牙被认为是恐吓灰谷森林的最凶猛的堕落熊怪威胁。他的失败消除了一个积极猎食林地的危险酋长。",al={"兰恩·血牙","血牙的颅骨","兰恩·血牙是谁"}},{q="为什么莱恩·狼行者想要这个颅骨？",a="莱恩·狼行者将颅骨与达图尔的变形棒一起保存，作为胜利和纪念的象征。它是不容置疑的证据，证明了哨兵部队及其盟友消除了对灰谷的一个致命危险。",al={"为什么要颅骨","狼行者的颅骨","莱恩如何处理颅骨"}},{q="Teronis是谁？",a="Teronis是一位暗夜精灵调查员，他在任务线早期死亡，促使了对净化宝石和达图尔的变形棒的搜寻。完成这个任务就实现了他未竟的使命。",al={"teronis","teronis是谁","teronis的骄傲"}},{q="这个任务在哪里结束？",a="该任务在灰谷主要的暗夜精灵据点阿斯特兰纳完成，通过与莱恩·狼行者哨兵对话。",al={"交还地点","莱恩在哪里","莱恩·狼行者位置"}},{q="谁是克罗格？",a="克罗格是一位盟友，他指引你将兰恩·血牙被砍下的头颅带回阿斯特兰纳，以获得你的认可并在你的人民中享受胜利。",al={"克罗格","谁发布任务","npc克罗格"}},{q="什么是达图尔的变形棒？",a="达图尔的变形棒是在任务链中组装的一件强大的附魔遗物，它与熊怪的本质和净化有着深厚的魔法联系。",al={"达图尔的变形棒","变形棒","熊怪之棒"}}},fp="17,174,15.203.0,20.207.1,22.139.0,41.217.0,16.190.1,26.120.0,13.134.0,21.130.0"}
P.entries["quest:1050"] = {n="Mythology of the Titans",s="铁炉堡的图书管理员 Mae Paledust 想找一本据说曾收藏于提瑞斯法古修道院的书。研读此书或许能揭示过去的教训，帮助人们面对未知的未来。",h="铁炉堡的图书管理员 Mae Paledust 想找一本据说曾收藏于提瑞斯法古修道院的书。研读此书或许能揭示过去的教训，帮助人们面对未知的未来。",kw={"书","铁炉堡","图书管理员 mae paledust","mae paledust","mythology of the titans","古修道院","提瑞斯法林地","泰坦"},sec={{t="遗失的典籍",b="洛丹伦遭逢祸患之前，提瑞斯法林地的古修道院中藏有一座知识宝库。Mae 请你去那里找回一本名为 Mythology of the Titans 的书，并带到铁炉堡交给她。她希望通过研读此书，揭开过去的秘密。"}},faq={{q="谁在寻找这本书？",a="铁炉堡的图书管理员 Mae Paledust 请你把 Mythology of the Titans 带给她。",al={"谁想要这本书","mae paledust 的书","图书管理员 mae"}},{q="据说 Mythology of the Titans 在哪里？",a="据传，这本书位于提瑞斯法林地古修道院的图书馆中。",al={"书在哪里","修道院的书","泰坦之书的位置"}},{q="Mythology of the Titans 是什么？",a="据说，这本书曾收藏于提瑞斯法林地古修道院的图书馆中。",al={"这是什么书","泰坦神话","神话之书"}},{q="Mae 为什么想要这本书？",a="Mae 希望研读此书或许能揭开过去的秘密，帮助人们为未知做好准备。",al={"为什么要找它","mae 为什么需要它","这本书有何用途"}}},fp="23,180,13.274.0,27.82.0,44.81.0,32.88.0,27.92.0"}
P.entries["quest:1052"] = {n="血色之路",s="安东兄弟说你在凄凉之地对抗亡灵的功绩仅仅是个开始，因为瘟疫真正的威胁位于洛丹伦。他给了你一封盖有他印章的推荐信，让你交给南海镇的虔诚的莱雷恩。",h="安东兄弟说你在凄凉之地对抗亡灵的功绩仅仅是个开始，因为瘟疫真正的威胁位于洛丹伦。他给了你一封盖有他印章的推荐信，让你交给南海镇的虔诚的莱雷恩。",kw={"安东兄弟","血色之路","壁炉谷","推荐信","洛丹伦","虔诚的莱雷恩","血色修道院","南海镇","提瑞斯法林地"},sec={{t="十字军的据点",b="安东自豪地谈起了血色十字军在洛丹伦的净化堡垒。十字军声称他们拥有从壁炉谷到提瑞斯法林地之间所有的据点。安东说你在凄凉之地对抗亡灵的行动已经证明了你的能力，但瘟疫真正的威胁位于洛丹伦。"},{t="给南海镇的信",b="安东派你去东部王国的南海镇寻找一位名叫虔诚的莱雷恩的十字军战士。这封信上盖着安东的印章，安东说它会让你获得莱雷恩的护送，前往血色修道院内的一个荣誉之地。"},{t="莱雷恩的反应",b="莱雷恩拆开印章读了这封信。听说安东还在散布关于血色十字军的消息，莱雷恩感到不安，他告诉你这里有些事情超出了你的理解范围。"}},faq={{q="是谁派你踏上这段旅程的？",a="安东兄弟给了你一封盖有印章的推荐信，让你带给虔诚的莱雷恩。",al={"谁发布了血色之路","血色之路的任务发布者"}},{q="你要去哪里？",a="你要去东部王国的南海镇，寻找十字军战士虔诚的莱雷恩。",al={"去哪里","莱雷恩在哪里","血色之路的位置"}},{q="安东兄弟说这封信有什么用？",a="安东说，一旦莱雷恩看到他盖了章的信，莱雷恩就会带你前往血色修道院内的一个荣誉之地。",al={"这封信有什么用","推荐信的用途"}},{q="血色十字军在洛丹伦宣称拥有哪些领土？",a="安东兄弟说，血色十字军在壁炉谷和提瑞斯法林地之间拥有许多据点，他为这些净化堡垒感到自豪。",al={"血色十字军的领地","血色十字军的据点在哪里"}}},fp="21,221,26.278.0,23.249.0,18.184.1,30.87.0,25.87.0,47.124.0,59.158.0"}
P.entries["quest:1054"] = {n="解除威胁",s="“消灭威胁”是联盟在阿斯特兰纳由莱恩·狼行者发布的一项防御行动。面对正北方向迅速扩张的蓟皮熊怪，暗夜精灵们试图通过击杀它们的督军达尔·血爪，来阻止他们对定居点的袭击。这反映了一个残酷的现实：曾经的林地盟友现在必须被清除，以保卫卡多雷的家园。",h="“消灭威胁”是联盟在阿斯特兰纳由莱恩·狼行者发布的一项防御行动。面对正北方向迅速扩张的蓟皮熊怪，暗夜精灵们试图通过击杀它们的督军达尔·血爪，来阻止他们对定居点的袭击。这反映了一个残酷的现实：曾经的林地盟友现在必须被清除，...",kw={"灰谷","阿斯特兰纳","消灭威胁","达尔·血爪","熊怪","莱恩·狼行者","蓟皮"},ang={["class:Druid"]="德鲁伊们悲痛地注视着蓟皮部落的疯狂，见证了灰谷挥之不去的污秽如何将高贵的熊怪变成了嗜血的野兽。",["faction:Alliance"]="守住阿斯特兰纳对于联盟在卡利姆多中部的补给线和通讯至关重要，这使得镇北方向的任何威胁都成为紧迫的战术优先级。",["race:NightElf"]="对于卡多雷来说，消灭熊怪是一项悲剧性的必要措施，他们在为古老盟友的腐化感到哀悼的同时，也必须采取残酷手段来保护阿斯特兰纳免遭毁灭。"},sec={{t="来自北方的迫近威胁",b="阿斯特兰纳坐落在灰谷的中心地带，时刻被危险所包围。定居点的正北方向居住着蓟皮熊怪。它们曾经是古老森林的和平居民，如今却像它们的许多同胞一样陷入了疯狂与暴戾。哨兵侦察兵在过去几个月里目睹了它们人口的膨胀，这引发了人们的担忧，即对阿斯特兰纳发动协调一致的袭击只是时间问题。"},{t="打击酋长",b="与其坐等蓟皮大军冲垮阿斯特兰纳简陋的栅栏，莱恩·狼行者委托旅行者采取攻势。目标是达尔·血爪，这位酋长的领导力将大兽穴组织了起来并使其胆量倍增。通过斩下部落首领的头颅并将达尔·血爪的颅骨带回阿斯特兰纳，哨兵们希望打破熊怪的协调性，并为饱受困扰的城镇争取宝贵的时间。"}},faq={{q="谁发布了“消灭威胁”任务？",a="莱恩·狼行者，一位驻扎在灰谷暗夜精灵城镇阿斯特兰纳的哨兵指挥官，提供了这项任务。",al={"任务发布者","谁开启了消灭威胁","在哪里接消灭威胁"}},{q="为什么阿斯特兰纳想要达尔·血爪死？",a="达尔·血爪领导着阿斯特兰纳正北方向的蓟皮部落。随着他们的人数迅速增加，狼行者担心如果不能除掉他的领导，血爪会带领他们直接袭击城镇。",al={"为什么要杀达尔血爪","达尔血爪背景故事","为什么要攻击蓟皮"}},{q="为什么蓟皮熊怪对暗夜精灵怀有敌意？",a="尽管熊怪和暗夜精灵曾是历史上的盟友，但灰谷各地恶魔般的腐化力量已经驱使许多部族，包括蓟皮部族，陷入了暴力的疯狂和对领土的偏执。",al={"熊怪为什么会攻击","灰谷被腐化的熊怪","蓟皮部族背景故事"}},{q="在哪里可以找到达尔·血爪？",a="达尔·血爪居住在蓟皮村及其附近的兽穴中，位于灰谷阿斯特兰纳的正北方。",al={"达尔血爪位置","达尔血爪在哪里"}},{q="击杀达尔·血爪能永久解决熊怪威胁吗？",a="不能。莱恩·狼行者指出，击杀达尔·血爪只能在一段时间内压制它们的侵略性。只要腐化仍然笼罩着灰谷，熊怪人口就依然是一个持续的危险。",al={"蓟皮被击败了吗","我们拯救了阿斯特兰纳吗"}},{q="需要什么证明达尔·血爪已死？",a="你必须取得达尔·血爪的颅骨，并将其直接交给阿斯特兰纳的莱恩·狼行者。",al={"我该带给莱恩什么","消灭威胁任务物品"}}},fp="18,162,28.371.0,22.333.0,39.91.0,43.199.0,59.194.0,33.104.0,64.175.0,48.82.0"}
P.entries["quest:1055"] = {n="莱恩的净化",s="此任务标志着位于灰谷隐秘神龛的变身法杖已组装完成。神圣的神器已经拼凑完毕，必须立刻送还给位于月井圣地的树妖莎尔蒂恩。",h="此任务标志着位于灰谷隐秘神龛的变身法杖已组装完成。神圣的神器已经拼凑完毕，必须立刻送还给位于月井圣地的树妖莎尔蒂恩。",kw={"灰谷","阿斯特兰纳","艾露恩","隐秘神龛","月井","莱恩的净化","变身法杖","莎尔蒂恩"},ang={["class:Priest"]="协助莎尔蒂恩可以修复莱恩在灰谷进行调查所需的神器。",["faction:Alliance"]="保卫灰谷对于联盟在卡利姆多北部的地位至关重要，能保护阿斯特兰纳免受当地腐蚀和敌对势力的持续袭击。",["race:NightElf"]="修复法杖有助于莱恩调查威胁阿斯特兰纳及其周边树林的熊怪袭击事件。"},sec={{t="重铸遗物",b="组装变身法杖的艰苦努力在灰谷荒野深处的隐秘神龛迎来了一个安静的转折点。将杖身、杖柄和发光的宝石拼接在一起，并在隐秘神龛重新为重构后的法杖附魔，使其魔力得以恢复。这件神器已准备好送回莎尔蒂恩手中，以供莱恩·狼行者调查熊怪袭击事件之用。"},{t="回到莎尔蒂恩身边",b="随着组装完成，必须迅速将消息和圣物送回莎尔蒂恩处。这位驻扎在宁静森林月井旁的树妖一直指导着此次修复工作的每一步。将组装好的法杖呈交给她，不仅确认了法杖魔力的恢复，也让哨兵防卫者们能够采取下一步关键措施，保卫她们饱受围攻的家园。"}},faq={{q="这一阶段任务的目的是什么？",a="在隐秘神龛成功组装变身法杖后，你只需将成品法杖带回给位于灰谷北部月井处的树妖莎尔蒂恩即可。",al={"莱恩的净化第七步做什么","这是什么任务","任务目标"}},{q="莎尔蒂恩是谁？",a="莎尔蒂恩是一位看守灰谷神圣月井的树妖。为了净化古老森林中不断蔓延的腐蚀，她指引可靠的盟友收集遗物、净化部件并修复神圣的神器。",al={"莎尔蒂恩","莎尔蒂恩是谁","月井祭司"}},{q="莎尔蒂恩在哪里？",a="莎尔蒂恩居住在灰谷北部的一口宁静月井旁，位于连接阿斯特兰纳与费伍德森林的主路东侧，周围环绕着她所守护的静谧水域。",al={"莎尔蒂恩位置","莎尔蒂恩在哪","月井在哪里"}},{q="什么是变身法杖？",a="这根法杖是达图尔的魔法创造物。其恢复后的力量旨在帮助莱恩调查熊怪；它赋予何种形态稍后便知。",al={"什么是变身法杖","变身法杖背景故事","法杖"}},{q="为什么组装法杖对阿斯特兰纳如此重要？",a="莱恩·狼行者希望这根法杖能让调查员接近熊怪，并进一步了解威胁阿斯特兰纳的袭击事件。",al={"为什么要做莱恩的净化","为什么阿斯特兰纳很在意","莱恩的重要性"}},{q="组装法杖是否结束了净化任务线？",a="不。莎尔蒂恩接下来会请你回到阿斯特兰纳将法杖完成的消息告知莱恩·狼行者。",al={"这是最后一个任务吗","莱恩的净化到这里结束吗","任务线终点"}}},fp="17,204,16.231.0,20.247.0,47.140.0,18.221.0,28.149.0,34.163.0,52.133.0,48.105.0"}
P.entries["quest:1057"] = {n="夺回焦炭谷",s="“收复焦炭谷”是一项联盟任务，由位于石爪峰顶部的守护者奥巴格姆发布。他要求冒险者们铲除占据焦炭谷废墟的残暴的血怒鹰身人，为德鲁伊和护理员们开辟道路，以便他们开始修复那片焦灼的土地。",h="“收复焦炭谷”是一项联盟任务，由位于石爪峰顶部的守护者奥巴格姆发布。他要求冒险者们铲除占据焦炭谷废墟的残暴的血怒鹰身人，为德鲁伊和护理员们开辟道路，以便他们开始修复那片焦灼的土地。",kw={"血怒","焦炭谷","鹰身人","守护者奥巴格姆","收复焦炭谷","石爪山脉","石爪峰"},ang={["class:Druid"]="作为塞纳里奥议会的管家和自然和谐的捍卫者，德鲁伊直接协助守护者清理受污染的巢穴，以允许进行魔法植树造林。",["faction:Alliance"]="确保高山口和南部山谷的安全，可以保护石爪峰上脆弱的暗夜精灵定居点和避难所免受掠食者的威胁。",["race:NightElf"]="暗夜精灵崇敬石爪山脉的荒野森林；将卑劣的鹰身人从被外来机器玷污的神圣林地中清除出去，是一项紧迫的使命。"},sec={{t="伤痕累累的山谷",b="石爪峰以南便是焦炭谷，这片曾经郁郁葱葱的高山避风港如今已化为灰烬与冒烟的废墟。这场浩劫始于一支机械化的伐木与采矿军队横扫这片圣地，他们掠夺树木，引发了失控的大火。对于驻扎在石爪山脉周围的守护者来说，眼睁睁看着古老的林地屈从于工业贪婪，是对大自然极其沉重的伤害。"},{t="鹰身人威胁",b="虽然机械造成的火灾引发了这场毁灭，但一场投机取巧的入侵却在灰烬中扎下了根。残暴的血怒鹰身人成群结队地涌入烟雾缭绕的低地，建立巢穴，并疯狂伏击任何靠近山谷的人。守护者奥巴格姆和他的盟友甚至无法踏足这片土地去播撒新生的种子，因为血怒鹰身人暴力地拒绝让所有外来者通过。"},{t="开辟复苏之路",b="在进行任何有效的修复工作之前，必须先摧毁血怒部族的栖息地。奥巴格姆指派经验丰富的联盟战士深入敌阵，大量削减它们的数量——猎杀猎手、伏击者和流羽。减少这些掠食者的数量是收复这片土地并让森林之灵得以再次呼吸的关键第一步。"}},faq={{q="什么是焦炭谷？",a="焦炭谷坐落在石爪山脉的西南高地。它曾经是一片郁郁葱葱的森林，但在工业伐木势力对土地的肆意开发中，它被大火吞噬并烧焦至岩石地表。",al={"焦炭谷背景故事","焦炭谷发生了什么","为什么这里被烧毁了"}},{q="守护者奥巴格姆是谁？",a="守护者奥巴格姆是一位居住在石爪峰联盟定居点的林地守护者和护理员。作为自然与森林之灵的保护者，他致力于遏制山脉中的荒凉，并驱逐入侵的野兽。",al={"守护者奥巴格姆","谁发布收复焦炭谷任务","奥巴格姆背景"}},{q="为什么鹰身人会住在焦炭谷？",a="血怒鹰身人是残暴且投机取巧的食腐者，在被破坏和受到污染的领地上繁衍生息。当大火夷平了山谷后，鹰身人蜂拥而至，占据了这片荒凉的盆地，攻击任何试图进入的人。",al={"血怒鹰身人","为什么鹰身人在这里","石爪山脉的血怒鹰身人"}},{q="最初是谁烧毁了焦炭谷？",a="守护者奥巴格姆指出，罪魁祸首是一支贪婪的工业化机械军队，他们蹂躏了这些山丘。不受限制的伐木机械和爆炸性的扩张导致了毁灭性的大火，吞噬了林地。",al={"谁烧了焦炭谷","机械化工业军队","荆棘谷地精在焦炭谷"}},{q="削减鹰身人之后该做什么？",a="清理鹰身人仅仅是确保外围安全。一旦血怒鹰身人的数量得到控制，守护者奥巴格姆的工作重心将转向播种和引导恢复魔法，以诱导焦灼的土地焕发新生。",al={"焦炭谷后续任务","收复焦炭谷第二部分","接下来会发生什么"}},{q="部落冒险者可以接这个任务吗？",a="不能。守护者奥巴格姆在位于石爪峰顶部的联盟营地运作，这意味着这项清除血怒鹰身人的特殊任务仅限于联盟英雄。",al={"部落可以做这个任务吗","部落收复焦炭谷"}}},fp="27,213,18.340.0,16.330.0,28.321.0,25.207.0,23.215.0,43.169.0,52.191.0,45.152.1,45.139.0"}
P.entries["quest:1058"] = {n="金吉尔的森林魔法",s="在玛拉卡金这个小型哨所，巫医金吉尔用简陋的铁笼囚禁了三名暗夜精灵侦察者。这位古怪的巨魔并没有直接处决他们，也没有将他们扣为人质以勒索赎金，而是指派部落的冒险者从石爪峰采集荒野试剂，试图配制一种令人毛骨悚然的“森林魔法”。",h="在玛拉卡金这个小型哨所，巫医金吉尔用简陋的铁笼囚禁了三名暗夜精灵侦察者。这位古怪的巨魔并没有直接处决他们，也没有将他们扣为人质以勒索赎金，而是指派部落的冒险者从石爪峰采集荒野试剂，试图配制一种令人毛骨悚然的“森林魔法”。",kw={"巨角鹿的眼球","灵龙","森林魔法","金吉尔","玛拉卡金","俘虏","石爪山脉","暮光奔跑者","巫医"},ang={["class:Druid"]="看到神圣的灵龙、雄伟的奔跑者和古老的森林树液被采集来酿造致命的毒药，这是对自然平衡的一种严酷扭曲。",["faction:Horde"]="保住玛拉卡金意味着要镇压整个山脉的暗夜精灵抵抗力量，即使需要借助一位隐居巫医那不寻常的手段。",["race:NightElf"]="通过扭曲的林地材料来折磨处决暗夜精灵俘虏，是部落在石爪山脉所作所为中最残忍的行为之一。",["race:Troll"]="金吉尔那阴森的幽默感和他对巫毒炼金术的实际应用，是暗矛巨魔巫医技艺的经典标志。"},sec={{t="苦涩的药剂",b="在玛拉卡金的红岩峡谷中，巫医金吉尔在部落众人的注视下进行着他的研究。当三名暗夜精灵俘虏落入他的魔爪时，金吉尔并没有选择普通的屠杀，而是专门为这些被囚禁的林地敌人策划了一种嘲弄性的仪式。他指引旅行者向北前往未受驯服的山峰，去采集各种当地的素材：浓稠的树液、捕食性的暮光奔跑者的猫科胡须、闪闪发光的灵龙的鳞片，以及从当地森林奔跑者身上摘下的大量眼球。"},{t="家的味道",b="在金吉尔那副戏谑的态度背后，隐藏着一种残酷的巨魔式幽默。他假装要让被囚禁的精灵们在没有森林嬉戏的情况下“感到宾至如归”，实则利用这些魔法生物和浓缩的树液混合出了一种致命且易挥发的毒药。当这种有害的药剂在洞穴中释放时，瞬间便夺走了笼中俘虏的性命。随着他们的肉体消亡，精灵们的祖先之魂化作发光的小精灵，飘向山野之中，只留下空荡荡的笼子。"}},faq={{q="巫医金吉尔是谁？",a="巫医金吉尔是一名暗矛巨魔，驻扎在石爪山脉南部的玛拉卡金。他通过实践传统的巨魔炼金术、巫毒教和审讯手段，为部落对抗暗夜精灵的战争贡献力量。",al={"谁是金吉尔","巫医金吉尔","金吉尔背景故事"}},{q="为什么金吉尔需要这么多森林奔跑者的眼球？",a="金吉尔声称，如果没有大量的眼球，就无法酿造出凶猛的森林魔法。虽然巨魔巫医经常在药剂中使用奇异的有机成分，但这荒谬的数量也反映了他古怪而又心怀报复的性格。",al={"为什么需要奔跑者的眼球","30个奔跑者的眼球","为什么需要这么多眼球"}},{q="任务完成后，被囚禁的暗夜精灵会怎么样？",a="在交付试剂后，金吉尔将有毒的药剂释放到整个洞穴中。这种混合物使三名俘虏中毒身亡，他们的灵魂化作小精灵飘向荒野。",al={"精灵们会发生什么","笼中精灵的命运","金吉尔的俘虏"}},{q="这些试剂都在哪里可以找到？",a="森林奔跑者的眼球和石爪苔液可以在暗色湖和北部高地周围采集。暮光奔跑者的胡须和稀有的灵龙的鳞片则在更北面的石爪峰附近，那是那些山地魔法生物出没的地方。",al={"在哪里可以找到森林魔法试剂","石爪苔液的位置","灵龙的鳞片采集点"}},{q="为什么部落在石爪山脉与暗夜精灵作战？",a="部落在邻近灰谷的伐木作业引发了哨兵部队的激烈抵抗，而暗夜精灵仍然占据着石爪峰及其神圣的树林，并在玛拉卡金等部落哨所之上。",al={"为什么要在石爪山脉与暗夜精灵战斗","石爪山脉的部落与暗夜精灵冲突","石爪之战"}},{q="为什么垂死的精灵会变成小精灵？",a="小精灵是死去的暗夜精灵的灵魂，他们与自然保持着紧密的联系。在死亡时，他们的灵魂会呈现这种发光的树木形态，而不是像普通的鬼魂或阴影那样徘徊。",al={"为什么精灵会变成小精灵","洞穴中的精灵小精灵","小精灵背景故事"}}},fp="22,192,13.425.0,15.455.1,28.193.0,43.203.0,62.159.1,35.219.0,52.192.0,39.175.0"}
P.entries["quest:1059"] = {n="夺回焦炭谷",s="“收复焦炭谷”是一项由石爪峰的守护者奥巴格姆委托的送信任务。在暂时压制了当地的鹰身人后，奥巴格姆派遣一名联盟旅行者远赴南方的菲拉斯，去招募德鲁伊法芬德尔以寻求援助。",h="“收复焦炭谷”是一项由石爪峰的守护者奥巴格姆委托的送信任务。在暂时压制了当地的鹰身人后，奥巴格姆派遣一名联盟旅行者远赴南方的菲拉斯，去招募德鲁伊法芬德尔以寻求援助。",kw={"血怒鹰身人","焦炭谷","法芬德尔","菲拉斯","萨兰纳尔","守护者奥巴格姆","石爪峰","千针石林"},ang={["class:Druid"]="这项任务突显了塞纳里奥议会的职责，即超越地方驻军的局限，召唤原始自然之灵来治愈遭受非自然灾害破坏的土地。",["faction:Alliance"]="联盟在石爪峰的立足点依赖于连接卡利姆多广袤且充满争端的边境前哨站。"},sec={{t="焦炭谷的伤痕",b="位于石爪山脉南部的焦炭谷如今仍是一片被灰烬覆盖的灾难废墟。尽管在守护者奥巴格姆指挥下的联盟部队已经反击并驱逐了盘踞在废墟中的狂暴血怒鹰身人，但这仅仅是权宜之计。奥巴格姆深知，如果不采取进一步行动，在鹰身人重整旗鼓夺回统治地位之前，仅靠武力无法修复这片饱受蹂躏的土地。"},{t="南方的呼唤",b="为了永久修复这片焦土，林地守护者需要超出他们目前能力的神秘力量干预。奥巴格姆派遣了一名信使前往遥远的南方，绕过千针石林的盐碱地和峡谷，前往菲拉斯边界的萨兰纳尔。那里驻守着暗夜精灵德鲁伊法芬德尔，据说他拥有罕见的力量，能够召唤原始森林之灵来让贫瘠的土壤焕发新生。"}},faq={{q="谁是守护者奥巴格姆？",a="守护者奥巴格姆是一位驻扎在石爪峰的林地守护者，负责监督联盟净化和修复受污染的焦炭谷的行动。",al={"谁是奥巴格姆","守护者奥巴格姆"}},{q="法芬德尔在哪里？",a="法芬德尔驻扎在萨兰纳尔，位于千针石林通往菲拉斯茂密荒野的西侧边界上。",al={"法芬德尔在哪里","法芬德尔位置","寻找法芬德尔"}},{q="为什么要大费周章去菲拉斯找德鲁伊？",a="守护者奥巴格姆认为法芬德尔拥有独特的能力，可以召唤强大的古老森林之灵，从而扭转焦炭谷深重的生态破坏。",al={"为什么要去菲拉斯","为什么要找法芬德尔"}},{q="焦炭谷里有什么威胁？",a="这片山谷被敌对的血怒鹰身人、火元素以及在土地燃烧后滋生的野兽所占领。",al={"焦炭谷的敌人","什么在袭击焦炭谷"}},{q="这个任务需要战斗吗？",a="不需要。任务“收复焦炭谷”的第二部分纯粹是一个陆路旅行任务，要求你将奥巴格姆的信息送达卡利姆多中部和南部。",al={"这个任务难吗","焦炭谷任务有战斗吗"}},{q="如何从石爪山脉到达千针石林？",a="旅行者必须先向东走出石爪山脉进入贫瘠之地，沿着黄金之路向南行进，乘坐升降梯进入千针石林，然后继续向西前往菲拉斯。",al={"如何前往千针石林","前往菲拉斯的路线"}}},fp="27,175,21.370.0,19.344.0,23.139.0,37.96.0,44.129.0,40.116.0,31.89.0,50.169.0"}
P.entries["quest:106"] = {n="年轻的恋人",s="“年轻的恋人”是艾尔文森林的一个任务，讲述了梅贝尔·马科伦和托米·乔·斯通菲尔德之间禁忌的恋情。由于两家相互敌对，梅贝尔委托一名冒险者将一封深情的情书秘密送到河边的托米·乔手中。",h="“年轻的恋人”是艾尔文森林的一个任务，讲述了梅贝尔·马科伦和托米·乔·斯通菲尔德之间禁忌的恋情。由于两家相互敌对，梅贝尔委托一名冒险者将一封深情的情书秘密送到河边的托米·乔手中。",kw={"艾尔文森林","世仇","情书","马科伦农场","梅贝尔·马科伦","斯通菲尔德农场","托米·乔·斯通菲尔德","年轻的恋人"},ang={["faction:Alliance"]="经过艾尔文森林的联盟冒险者经常会发现自己往返于敌对的斯通菲尔德家族和马科伦家族之间传递消息，从而了解到即使在王国面临的威胁中，当地人的心酸事也依然存在。",["race:Human"]="对于熟悉艾尔文森林的人类来说，斯通菲尔德家族和马科伦家族之间的长期积怨是一场众所周知的当地世仇，这使得梅贝尔和托米·乔的恋情成了一桩微妙的社区丑闻。"},sec={{t="禁忌之恋",b="在艾尔文森林的田园乡间，一场激烈的世仇将两户邻近的农家分裂开来：斯通菲尔德家和马科伦家。尽管家族间充满敌意，年轻的梅贝尔·马科伦还是深深爱上了托米·乔·斯通菲尔德。由于无法公开相见，否则会招致家人的愤怒，梅贝尔只能依靠路过的旅行者来传递穿越这两个敌对庄园边界的秘密信件。"},{t="河畔幽会",b="为了不让家人的眼睛发现他们的恋情，托米·乔·斯通菲尔德经常待在斯通菲尔德农场以西静谧的河岸边。送达梅贝尔的信件让他倍感宽慰并重新燃起思念，这让分离变得难以忍受，也促使他们进一步尝试在世仇的阴影下让这对年轻恋人团聚。"}},faq={{q="谁发布了“年轻的恋人”任务？",a="该任务由艾尔文森林马科伦农场的梅贝尔·马科伦发布。她深深爱着托米·乔·斯通菲尔德，但他们的家族却是死对头，这使他们无法公开见面。",al={"谁给予年轻的恋人任务","谁开始年轻的恋人任务","年轻的恋人任务发布者"}},{q="在哪里可以找到托米·乔·斯通菲尔德？",a="托米·乔·斯通菲尔德站在斯通菲尔德农场以西的河岸边，该处位于艾尔文森林马科伦农场的正西方。他在那里等待，避开了家人的视线。",al={"托米·乔·斯通菲尔德在哪里","找到托米·乔","托米·乔的位置"}},{q="为什么梅贝尔和托米·乔会被迫分开？",a="斯通菲尔德家族和马科伦家族是死对头，他们之间有着长期的积怨。由于这种根深蒂固的敌意，双方家庭都不允许他们的孩子来往，迫使这对年轻的情侣只能通过秘密信件来交流。",al={"为什么家族在争斗","斯通菲尔德和马科伦的世仇","为什么梅贝尔和托米·乔不能见面"}},{q="在这个任务中你需要递送什么物品？",a="你的任务是将梅贝尔的情书直接送到河边交给托米·乔·斯通菲尔德。这封信承载了她热切的情感，并向托米·乔保证，尽管两家有世仇，她依然对他忠贞不渝。",al={"什么是梅贝尔的情书","年轻的恋人任务中递送什么","艾尔文森林的情书"}},{q="托米·乔收到信后有何反应？",a="收到梅贝尔的信后，托米·乔欣喜若狂，并宣称梅贝尔是他枯燥生活中的光芒。读着她的信，分离变得让他无法忍受，促使他寻找与她见面的方法。",al={"托米·乔的反应","托米·乔的回应","递送信件后会发生什么"}},{q="这个任务发生在什么地方？",a="这个任务发生在艾尔文森林南部，横跨马科伦农场和毗邻斯通菲尔德农场的河流之间。这是人类王国中一个宁静的乡村角落，却深受琐碎的家庭纠纷所困。",al={"年轻的恋人任务地点","年轻的恋人区域","斯通菲尔德农场位置"}}},fp="12,278,19.433.0,24.368.0,33.209.0,40.217.0,41.264.0,43.227.0,39.209.0,33.217.0"}
P.entries["quest:1060"] = {n="写给金吉尔的信",s="“写给金吉尔的信”是一项部落运送任务，委托给在贫瘠之地北部击杀塞瑞娜·血羽的冒险者。兽人潜行者达索克·快刀会派遣你越过边境，前往石爪山脉崎岖的岩壁，将这位鹰身人女族长死亡的消息带给他的一位老友：巫医金吉尔。",h="“写给金吉尔的信”是一项部落运送任务，委托给在贫瘠之地北部击杀塞瑞娜·血羽的冒险者。兽人潜行者达索克·快刀会派遣你越过边境，前往石爪山脉崎岖的岩壁，将这位鹰身人女族长死亡的消息带给他的一位老友：巫医金吉尔。",kw={"血怒","达索克·快刀","鹰身人","写给金吉尔的信","玛拉卡金","塞瑞娜·血羽","石爪山脉","巫医金吉尔"},ang={["faction:Horde"]="递送这封信标志着部落战士的任务重心从平定贫瘠之地的内部贸易路线，转移到了在充满争议的石爪山脉建立据点上。",["race:Troll"]="金吉尔在玛拉卡金的洞穴是暗矛巨魔试图确保山地入口时的关键精神与战术前哨。"},sec={{t="传入群山的讯息",b="在系统性地清除了贫瘠之地北部的鹰身人威胁后，达索克·快刀透露，这些有翼的掠夺者并非这片灌木荒野的原住民。巫翼氏族和血羽氏族都是从西北方向石爪山脉的崎岖山脊中迁徙而来的。达索克对你击杀塞瑞娜·血羽的英勇表现印象深刻，于是派遣你深入那些危险的峰峦，将她死亡的消息带给他的一位旧识——居住在玛拉卡金巨魔定居点的巫医金吉尔。"},{t="血怒之爪的回响",b="在阴凉的洞穴中找到金吉尔，揭开了一段更早期的部落历史。听到塞瑞娜·血羽已经倒下的消息，这位巨魔巫医回忆起了早期的战役，当时暗影猎手洛坎和游荡的兽王雷克萨击杀了塞瑞娜的姐姐：血羽。塞瑞娜的消亡为部落边境哨所与卡利姆多嗜血的鹰身人之间长期的世仇画上了一个句号。"}},faq={{q="谁会给予“写给金吉尔的信”任务？",a="达索克·快刀在贫瘠之地的十字路口提供该任务。只有在你完成对塞瑞娜·血羽的狩猎后，他才会发布此任务。",al={"任务发布者","哪里接任务","谁开启写给金吉尔的信"}},{q="我在哪里可以找到巫医金吉尔？",a="巫医金吉尔居住在玛拉卡金的一个洞穴里，这是一个暗矛巨魔营地，位于从贫瘠之地进入石爪山脉的主路旁。",al={"金吉尔在哪里","金吉尔位置","玛拉卡金位置"}},{q="为什么达索克要派遣你去石爪山脉？",a="达索克希望通知他的老友金吉尔，随着塞瑞娜·血羽的死亡，鹰身人的威胁已经被打破；同时也为了引导一位有能力的冒险者前往石爪山脉的峰峦，去迎接部落在那里等待着的更广阔的挑战。",al={"为什么去石爪山脉","为什么达索克要寄信"}},{q="金吉尔提到的塞瑞娜的姐姐是谁？",a="金吉尔提到的是血羽，一位多年前曾恐吓卡利姆多的年长鹰身人。她在暗影猎手洛坎与半食人魔战士雷克萨跟随初创部落游历期间被他们所杀。",al={"塞瑞娜的姐姐","洛坎和雷克萨 鹰身人","血怒"}},{q="这个任务是大型任务链的一部分吗？",a="是的。它是贫瘠之地北部鹰身人狩猎任务链的终章，衔接在“鹰身人掠夺者”、“鹰身人中尉”和“塞瑞娜·血羽”之后，同时也作为引导玩家前往石爪山脉的任务。",al={"任务链","前置任务","什么导向此任务"}},{q="哪个阵营可以执行此任务？",a="这仅仅是部落任务，因为达索克·快刀和巫医金吉尔都服务于部落边境的利益。",al={"是否部落专属","联盟能做此任务吗"}}},fp="17,198,28.423.0,29.339.1,38.124.0,38.147.0,49.214.0,55.201.0,37.167.0,37.114.0"}
P.entries["quest:1061"] = {n="石爪之灵",s="“石爪山的灵魂”是一项部落信使任务，由奥格瑞玛的兽人顾问佐尔·孤树发起。他察觉到西部山脊的土元素们正处于极度的不安之中，因此派遣年轻的勇士们前往石爪山脉。冒险者们向西穿过十字路口，随后直接向巨木谷附近的希雷斯·碎石报到，以解决那里猖獗的伐木活动。",h="“石爪山的灵魂”是一项部落信使任务，由奥格瑞玛的兽人顾问佐尔·孤树发起。他察觉到西部山脊的土元素们正处于极度的不安之中，因此派遣年轻的勇士们前往石爪山脉。冒险者们向西穿过十字路口，随后直接向巨木谷附近的希雷斯·碎石报到，...",kw={"十字路口","森林砍伐","巨木谷","希雷斯·碎石","石爪山脉","智慧谷","荆棘谷地精","佐尔·孤树"},ang={["class:Shaman"]="对于萨满祭司来说，这次召唤是来自元素本身的直接恳求，呼吁精神实践者去修补大地与生灵之间破碎的联系。",["faction:Horde"]="确保石爪山脉与贫瘠之地之间的边界安全，可以保证部落的通行走廊不受流氓商业集团的干扰。",["race:Tauren"]="牛头人冒险者感到了一种沉重的文化义务，他们需要抚慰哭泣的大地，并保卫神圣的森林免受地精肆无忌惮的掠夺。"},sec={{t="来自西方的呼唤",b="在奥格瑞玛的格罗玛什要塞，佐尔·孤树在与自然界的沟通中，感知到了从石爪山脉传来的深重痛苦。由于工业开发撕裂了森林，岩石山峰的元素之灵变得狂怒不已。听到了它们的痛苦呼喊后，部落的萨满祭司们意识到，高地西部毫无节制的破坏行为正在威胁卡利姆多的精神平衡。"},{t="工业森林砍伐",b="该地区的主要威胁来自荆棘谷地精，这是一个肆无忌惮的风险投资公司。他们并非以可持续的方式采伐，而是动用大型机械、锯子和劳动力，野蛮地砍伐着古老的林地。为了调查这次入侵，部落派遣了希雷斯·碎石，这是一位有洞察力的年轻萨满祭司，驻扎在边境监控森林并召集保卫者对抗破坏者。"}},faq={{q="谁发布了这个任务，他们位于哪里？",a="该任务由佐尔·孤树提供，他是一位睿智的兽人顾问，位于部落主城奥格瑞玛的格罗玛什要塞中。",al={"任务发布者","在哪接任务","佐尔·孤树位置"}},{q="我在哪里可以找到希雷斯·碎石？",a="希雷斯·碎石驻扎在石爪山脉，沿着巨木谷附近的小路，就在从北贫瘠之地过来的东部入口之后。",al={"希雷斯位置","希雷斯·碎石在哪里","石爪山脉营地"}},{q="为什么石爪山的灵魂们会愤怒？",a="地精——特别是那些为荆棘谷地精工作的地精——正在暴力地砍伐原始的山林，在荒野上留下疮痍，从而激怒了这片土地上古老的元素守护者。",al={"灵魂为何愤怒","石爪山脉骚乱","愤怒的灵魂"}},{q="我该如何从奥格瑞玛前往石爪山脉？",a="离开奥格瑞玛，向南穿过贫瘠之地前往十字路口，然后沿着向西的道路攀爬，穿过岩石山口直接进入石爪山脉。",al={"通往石爪山脉的道路","如何前往石爪山脉","前往石爪山脉的路线"}},{q="与希雷斯交谈后接下来要做什么？",a="到达她的营地后，希雷斯·碎石会指派你执行“地精入侵者”任务，让你前往巨木谷的树林中消灭伐木工，并直接切断他们的作业。",al={"后续任务","后续","石爪山的灵魂之后是什么"}},{q="为什么部落要干预石爪山的森林砍伐？",a="牛头人和兽人萨满祭司对元素之灵怀有神圣的敬意。容忍这种鲁莽的地精乱砍滥伐会损害土地的精神和谐，并对贫瘠之地的边界构成直接威胁。",al={"部落为何关注","牛头人对石爪山的关注"}}},fp="25,214,19.326.0,24.353.0,49.72.0,36.147.0,40.107.0,55.135.0,44.142.0,59.153.0"}
P.entries["quest:1062"] = {n="地精侵略者",s="“地精入侵”是一项部落任务，由希雷斯·碎石在贫瘠之地与石爪山脉的交界处发布。任务指引部落勇士前往狂风峭壁，直接打击那些正在破坏该地区古老林地的荆棘谷地精伐木工。",h="“地精入侵”是一项部落任务，由希雷斯·碎石在贫瘠之地与石爪山脉的交界处发布。任务指引部落勇士前往狂风峭壁，直接打击那些正在破坏该地区古老林地的荆棘谷地精伐木工。",kw={"地精","巨木谷","伐木工","希雷斯·碎石","灵魂","石爪山脉","荆棘谷地精","狂风峭壁"},ang={["class:Druid"]="在狂风峭壁对活生生的树林进行盲目破坏和对古老树木的屠戮，直接违背了德鲁伊誓死捍卫的自然秩序。",["class:Shaman"]="萨满可以敏锐地感受到当地元素和自然之灵的哭喊，它们已经被地精机械产生的烟雾和破坏折磨得陷入了疯狂的愤怒之中。",["faction:Horde"]="阻止荆棘谷地精可以守卫贫瘠之地与高处山口之间的边界，确保敌对的商业集团不会在卡利姆多中部建立防御据点。",["race:Tauren"]="石爪山脉森林的亵渎和大地之灵的痛苦，使得对抗荆棘谷地精成为每一位尊崇大地母亲的牛头人必须履行的紧急职责。"},sec={{t="痛苦的森林",b="荆棘谷地精已经深入石爪山脉，在峭壁和峡谷间造成了大面积的破坏。他们的伐木作业剥光了山坡上的树木，并放火焚烧灌木丛，留下一道道冒着烟的伤痕。对于牛头人和他们的盟友来说，这不仅仅是令人反感的采矿和伐木作业；禁锢在石爪山脉的原始之灵正在痛苦地哀嚎。驻扎在山区边界的希雷斯·碎石观察到，这些灵魂在地精肆无忌惮的攻击下，已经因痛苦和愤怒而变得疯狂。"},{t="武力的语言",b="对于眼中只有暴利、冷酷无情的荆棘谷地精高管和雇佣兵来说，理性和外交毫无意义。希雷斯深知这一点，因此命令旅行者穿过巨木谷，直接进入狂风峭壁，消灭十五名伐木工。通过以武力回应企业的贪婪，部落旨在阻止森林砍伐，并为牛头人长者安抚受惊的土地之灵争取时间。"}},faq={{q="希雷斯·碎石是谁？",a="希雷斯·碎石是一位驻扎在贫瘠之地和石爪山脉南界附近的兽人萨满。她负责监视敌对势力的入侵，并致力于保护该地区的精神平衡。",al={"希雷斯·碎石","任务发布者","谁发布了地精入侵任务"}},{q="为什么地精要在石爪山脉砍伐森林？",a="荆棘谷地精是一个唯利是图、毫无道德底线的企业。他们将石爪山脉茂密的古老森林和矿产丰富的山丘视为单纯的原材料，为了将其开采、加工并出售给出价最高的人，他们完全无视所造成的自然和精神破坏。",al={"为什么荆棘谷地精在伐木","荆棘谷地精在石爪山脉的目的","为什么要砍伐树木"}},{q="狂风峭壁在哪里？",a="狂风峭壁位于石爪山脉的中部。从贫瘠之地的边界出发，沿山路向西北方向穿过巨木谷，直到茂密的绿色森林被荆棘谷地精的机械化伐木营地和砍伐殆尽的山坡所取代，就到了目的地。",al={"狂风峭壁位置","伐木工在哪里","去哪里找荆棘谷地精伐木工"}},{q="灵魂对荆棘谷地精的出现有何反应？",a="根据希雷斯·碎石的说法，由于森林被肆意砍伐和焚烧，土地之灵正因愤怒和痛苦而近乎疯狂。它们的苦难破坏了自然平衡，对整个地区构成了精神层面的威胁。",al={"石爪山脉的灵魂愤怒","石爪山脉灵魂的反应"}},{q="消灭荆棘谷地精伐木工后会发生什么？",a="消灭伐木工只是针对这一行动的初步打击。希雷斯随后将部落的注意力转向拆除该公司机械化的基础设施，同时建议勇士寻求牛头人长者的指导，以帮助安抚受伤的灵魂。",al={"地精入侵任务之后","伐木工任务后的后续任务"}},{q="为什么部落关心石爪山脉的伐木活动？",a="石爪山脉对牛头人有着深厚的文化和精神意义，而整个部落认为荆棘谷地精肆无忌惮的侵略和资源掠夺，是对其领土影响力和精神和谐的威胁。",al={"部落对石爪山脉的利益","为什么部落要对抗荆棘谷地精"}}},fp="15,184,17.502.0,21.347.0,26.213.0,53.244.0,32.233.0,59.201.0,55.216.1,52.237.0"}
P.entries["quest:1063"] = {n="长者",s="“长者妖婆”是一个部落任务，引导冒险者从伤痕累累的石爪山脉前往高耸的雷霆崖平顶。为了寻求灵性指导来安抚石爪山脉狂暴的元素，希雷斯·碎石派遣使者前往长者高地咨询颇具影响力的牛头人长者玛加萨·野性图腾。",h="“长者妖婆”是一个部落任务，引导冒险者从伤痕累累的石爪山脉前往高耸的雷霆崖平顶。为了寻求灵性指导来安抚石爪山脉狂暴的元素，希雷斯·碎石派遣使者前往长者高地咨询颇具影响力的牛头人长者玛加萨·野性图腾。",kw={"长者妖婆","长者高地","野性图腾","玛加萨","希雷斯·碎石","灵魂","石爪山脉","牛头人","雷霆崖"},ang={["class:Shaman"]="萨满们了解石爪山脉元素叛乱的严重性；在长者高地上向玛加萨这样的长者咨询，凸显了卡利姆多群峰间正在酝酿的深重灵性危机。",["faction:Horde"]="这项差事揭示了将部落维系在一起的务实纽带，将石爪山脉的前线危机与雷霆崖高层领导联系在了一起。",["race:Tauren"]="对于牛头人旅行者来说，拜访玛加萨提醒着人们，在凯恩统一的部族与居住在雷霆崖中心、高冷且极其守旧的野性图腾派系之间，存在着一种脆弱的平衡。"},sec={{t="来自石爪山脉的呼唤",b="在石爪山脉的峭壁中，地精的滥砍滥伐和采矿事业激怒了当地的元素之灵。希雷斯·碎石意识到仅凭蛮力无法平息这片土地遭受的灵性苦难，遂断定需要萨满长者的智慧。虽然对各部族领袖知之甚少，但希雷斯听说过玛加萨·野性图腾，这位长者以其深邃的知识和统御全局的气场而闻名。"},{t="长者高地上的觐见",b="玛加萨在雷霆崖的长者高地上主持大局，那里是萨满和灵性事务的聚集地。尽管野性图腾部族与凯恩·血蹄的领导层之间维持着一种脆弱且常有冲突的关系，但玛加萨被公认为是一位拥有强大影响力的长者，她的建议在整个部落中举足轻重。冒险者们抵达时并不知道，将石爪山脉的麻烦带到她面前，会把他们的行动引向更为黑暗的补救措施。"},{t="务实的联盟",b="在听闻元素动荡后，玛加萨并没有仅仅求助于传统的牛头人仪式，而是将问题引向了居住在城内的被遗忘者炼金术师。她乐于将部落最新、最玩世不恭的盟友卷入卡利姆多的灵性事务中，这展现了她在权力和解决问题上狡黠且非传统的手段。"}},faq={{q="是谁派我去找玛加萨的？",a="在你在石爪山脉对抗蹂躏山中森林的荆棘谷地精入侵者之后，驻扎在石爪山脉的希雷斯·碎石会交给你这项任务。",al={"任务发布者","谁开始了这个任务","希雷斯·碎石"}},{q="玛加萨·野性图腾在哪里？",a="玛加萨·野性图腾居住在雷霆崖的长者高地上，那是通过木桥与中心高地相连的东北部平顶。",al={"玛加萨位置","玛加萨在哪里","长者高地"}},{q="为什么希雷斯要向一位牛头人长者寻求帮助？",a="石爪山脉中地精的破坏性工业活动深深搅扰了当地的灵魂。希雷斯意识到仅靠军事力量无法治愈这片土地，需要真正的灵性指导来平息躁动的元素。",al={"为什么叫长者妖婆","为什么要咨询玛加萨"}},{q="玛加萨·野性图腾是谁？",a="玛加萨是野性图腾部族的族长和长者妖婆。虽然她的部族以性格狂暴和对统一的部落持怀疑态度而闻名，但玛加萨在雷霆崖顶依然保有显赫的政治和灵性影响力。",al={"长者妖婆背景故事","谁是长者妖婆","玛加萨背景"}},{q="和玛加萨谈过之后会发生什么？",a="玛加萨听取了你关于石爪山脉困境的报告，并立即派遣你前往灵魂高地下的预见之池，在任务“被遗忘者的援助”中咨询被遗忘者使者药剂师扎玛。",al={"接下来做什么","后续任务"}},{q="为什么这个任务叫“长者妖婆”？",a="这个称呼直接指向玛加萨·野性图腾本人。无论在她的部族还是更广泛的牛头人社会中，由于她高龄、深厚的萨满知识以及族长的权威，她被普遍称为“长者妖婆”。",al={"为什么叫妖婆","长者妖婆称号"}}},fp="15,238,19.344.0,22.368.0,20.314.1,29.136.0,35.129.0,47.153.0,25.222.0,41.148.1,43.174.0"}
P.entries["quest:1064"] = {n="被遗忘者的援助",s="玛加萨·野性图腾派遣一名The Adventurer深入雷霆崖的预见之池，就石爪山脉受到腐蚀的灵魂向被遗忘者使者药剂师扎玛进行咨询。这位长者利用石爪山脉的危机，将善于处理瘟疫的被遗忘者树立为专家，以此促进牛头人与其颇具争议的亡灵盟友之间更紧密的合作。",h="玛加萨·野性图腾派遣一名The...",kw={"药剂师扎玛","被遗忘者的援助","玛加萨·野性图腾","预见之池","蛇形信使","灵魂高地","石爪山脉","雷霆崖"},ang={["faction:Horde"]="这项任务展示了在第三次战争之后，将卡利姆多和洛丹伦紧密联系在一起的脆弱联盟网络。",["race:Tauren"]="传统的牛头人寄希望于德鲁伊教义和大地母亲来治愈大地；玛加萨坚持求助于亡灵炼金术士，展现了她在部落外交上非传统的手段。",["race:Undead"]="对于被遗忘者来说，向牛头人提供炼金术援助是一个重要的机会，可以借此证明他们的价值，并在一个原本对他们保持警惕的部落中获得信任。"},sec={{t="务实的合作",b="长者玛加萨·野性图腾是牛头人与被遗忘者结盟的最主要推动者之一，她通过实用主义的视角看待亡灵。当有关石爪山脉元素之灵遭到腐蚀、大地遭受苦难的报告传到雷霆崖时，玛加萨看到了被遗忘者专业知识的用武之地。她主张只有了解疾病才能治愈疾病，因此她将旅行者从传统的德鲁伊疗法指引向皇家药剂师学会。"},{t="灵魂高地之下",b="药剂师扎玛隐居在灵魂高地之下洞穴状的预见之池中，代表幽暗城在卡利姆多的利益。虽然该洞穴是牛头人萨满、牧师和先知的圣地，但这位被遗忘者药剂师的出现标志着一种微妙的政治转变。玛加萨在The Adventurer之前派遣了一名蛇形信使通知扎玛，在野性图腾女族长与被遗忘者的炼金研究人员之间建立了一条直接联系。"}},faq={{q="为什么玛加萨·野性图腾要就石爪山脉的事宜咨询被遗忘者？",a="玛加萨认为，由于被遗忘者对瘟疫和疾病有着深入的了解，他们具有独特的优势来诊断和治疗石爪山脉土地上的顽疾。",al={"被遗忘者为何提供援助","玛加萨与亡灵","为何咨询被遗忘者"}},{q="药剂师扎玛在哪里？",a="她居住在预见之池内，这是一个位于雷霆崖西北高地灵魂高地下方的地下洞穴，可以通过上方台地水池附近的洞穴隧道进入。",al={"药剂师扎玛的位置","扎玛在哪里","预见之池入口"}},{q="接受玛加萨的任务后会发生什么？",a="接受任务后，玛加萨会召唤一名蛇形信使，它会在雷霆崖上蜿蜒飞行，直接飞向药剂师扎玛以通报你的到来。",al={"蛇形信使","玛加萨的蛇"}},{q="被遗忘者对于帮助石爪山脉的牛头人有什么看法？",a="尽管身为亡灵，药剂师扎玛仍对石爪山脉受困的灵魂表示同情，并表示被遗忘者渴望提供援助，以巩固他们与部落之间的纽带。",al={"被遗忘者在石爪山脉的动机","扎玛为何提供帮助"}},{q="与扎玛交谈后会开启什么任务线？",a="在见到扎玛之后，调查深入到了被遗忘者的炼金术领域，并最终引向了在东部王国的“前往塔伦米尔”，以咨询更高级别的药剂师。",al={"what comes next","被遗忘者的援助之后的任务"}},{q="为什么被遗忘者会驻扎在神圣的预见之池内？",a="预见之池接待了各类的部落学者、法师和先知。药剂师扎玛在那里以官方使者和研究员的身份工作，将她那充满争议的实验安全地隐藏在远离主要道路的地方。",al={"亡灵为何在预见之池","灵魂高地的亡灵"}}},fp="12,217,23.367.0,23.363.0,66.134.0,36.187.0,52.160.0,64.152.0,50.184.0,65.199.0"}
P.entries["quest:1065"] = {n="塔伦米尔之旅",s="为了寻求一种非传统的解决方案，在不造成过度流血的情况下将荆棘谷地精赶出石爪山脉，雷霆崖的药剂师扎玛派遣了一名使者横跨大海前往洛丹伦。这项任务将部落的旅者们送往希尔斯布莱德丘陵的塔伦米尔，皇家药剂师协会在那里拥有一间由药剂师林度恩负责的邪恶实验室。",h="为了寻求一种非传统的解决方案，在不造成过度流血的情况下将荆棘谷地精赶出石爪山脉，雷霆崖的药剂师扎玛派遣了一名使者横跨大海前往洛丹伦。这项任务将部落的旅者们送往希尔斯布莱德丘陵的塔伦米尔，皇家药剂师协会在那里拥有一间由药剂...",kw={"药剂师林度恩","药剂师扎玛","希尔斯布莱德","前往塔伦米尔","石爪山脉","塔伦米尔","雷霆崖","幽暗城","荆棘谷地精"},ang={["faction:Horde"]="雷霆崖和塔伦米尔之间的后勤联系作为一种早期的试炼，将年轻的部落卫士与更广阔的跨大陆联盟联系在了一起。",["race:Tauren"]="石爪山脉的亵渎对牛头人来说是深沉的创痛，但接受被遗忘者的化学解决方案揭示了为保护神圣土地所必须做出的不安妥协。",["race:Undead"]="这段旅程代表了皇家药剂师协会的影响力，展示了幽暗城的化学专业知识是如何跨越海洋，去协助遥远的部落盟友的。"},sec={{t="跨越无尽之海的请求",b="在雷霆崖，药剂师扎玛代表了新建立的被遗忘者与大地母亲的孩子们之间脆弱的联盟。当牛头人发现他们在石爪山脉的神圣土地被荆棘谷地精无情的伐木和采矿活动所玷污时，常规手段已无济于事。扎玛提出了一种不同的策略：由她皇家药剂师协会的同僚们制作的一种非常规化学威慑手段。与其进行彻底的消耗战，她转而求助于跨越无尽之海精心研制的专业炼金药剂。"},{t="前往希尔斯布莱德之路",b="这段旅程需要跨越大陆，指引卡利姆多的冒险者搭乘飞艇前往洛丹伦废墟和幽暗城。从提瑞斯法林地受污染的草地出发，道路向南穿过银松森林阴影笼罩的树林，然后进入冲突不断的希尔斯布莱德丘陵。在那里，坐落在人类农庄和废墟附近的是塔伦米尔——一个曾经的人类小村庄，现在已被加固为被遗忘者的一处北部堡垒，也是皇家药剂师协会的一处研究前哨。"},{t="药剂师林度恩的技艺",b="药剂师林度恩在塔伦米尔开展工作，专注于不稳定的化学和生物制剂，经常在活体对象身上测试可疑的混合药剂。在收到扎玛关于荆棘谷地精困境的便笺后，林度恩表现出了欣喜若狂的热情。皇家药剂师协会乐于抓住一切机会在新的环境中进行化合物的实地测试，林度恩毫不拖延地准备黑暗试剂来解决地精的入侵问题。"}},faq={{q="为什么药剂师扎玛要让我远赴塔伦米尔？",a="药剂师扎玛需要一种特殊的药剂，以便在不进行公开战争的情况下将荆棘谷地精从石爪山脉驱逐出去。她在皇家药剂师协会的同事药剂师林度恩，精通所需的炼金化合物，并在洛丹伦的塔伦米尔开展工作。",al={"为什么要去塔伦米尔","为什么要送去给林度恩","前往塔伦米尔的目的"}},{q="塔伦米尔位于哪里？",a="塔伦米尔位于洛丹伦大陆的希尔斯布莱德丘陵北部地区。要从卡利姆多前往那里，请搭乘从杜隆塔尔飞往提瑞斯法林地幽暗城的飞艇，然后向南穿过银松森林，向东进入希尔斯布莱德。",al={"塔伦米尔在哪里","塔伦米尔的位置","如何前往塔伦米尔"}},{q="药剂师扎玛和药剂师林度恩是谁？",a="他们两人都是被遗忘者皇家药剂师协会的成员。扎玛作为一名使者驻扎在雷霆崖的预见之池，研究当地的植物并协助牛头人，而林度恩则在塔伦米尔进行更加冷酷的炼金和瘟疫实验。",al={"扎玛是谁","林度恩是谁","药剂师是谁"}},{q="为什么被遗忘者要协助处理石爪山脉的荆棘谷地精问题？",a="被遗忘者加入部落主要是出于生存和便利的考虑，他们极度依赖牛头人的支持来巩固自己在阵营中的地位。协助牛头人对抗荆棘谷地精有助于巩固这一政治联盟，同时也为被遗忘者的炼金术提供了试验场。",al={"为什么被遗忘者关心石爪山脉","亡灵协助牛头人对抗石爪山脉"}},{q="什么是皇家药剂师协会？",a="皇家药剂师协会是一个由被遗忘者炼金术士和科学家组成的组织，基地位于洛丹伦废墟之下的幽暗城。在Sylvanas Windrunner的授意下，他们不断开发新的药剂、毒药和瘟疫菌株，以保卫被遗忘者并消灭他们的敌人。",al={"什么是皇家药剂师协会","被遗忘者药剂师背景"}},{q="将便笺交给林度恩之后会发生什么？",a="在收到扎玛的请求后，药剂师林度恩立即开始制定解决方案，要求旅者从敦霍尔德城堡的辛迪加暗影法师那里收集无辜之血药瓶，以调制出合适的混合药剂。",al={"前往塔伦米尔后的下一个任务","林度恩需要什么"}}},fp="22,221,27.408.0,21.368.0,24.347.1,61.246.0,29.214.0,46.256.0,68.252.0,37.277.0,48.201.1"}
P.entries["quest:1066"] = {n="无辜者之血",s="“无辜者的血液”是塔伦米尔的药剂师林度恩交给玩家的一项差事，旨在收集邪恶的炼金材料。为了安抚石爪山脉中不断进犯的荆棘谷地精，皇家药剂师学会试图利用从当地强盗手中获取的阴暗原料。",h="“无辜者的血液”是塔伦米尔的药剂师林度恩交给玩家的一项差事，旨在收集邪恶的炼金材料。为了安抚石爪山脉中不断进犯的荆棘谷地精，皇家药剂师学会试图利用从当地强盗手中获取的阴暗原料。",kw={"药剂师林度恩","无辜者的血液","敦霍尔德城堡","暗影法师","石爪山脉","辛迪加","塔伦米尔","荆棘谷地精"},ang={["faction:Horde"]="这项任务突显了将部落凝聚在一起的跨大陆联系，即利用洛丹伦的被遗忘者炼金暗影艺术来保护卡利姆多的领土。",["race:Tauren"]="牛头人可能会觉得收集无辜者的血液令人深感不安，但其首要目标是终结荆棘谷地精在卡利姆多造成的环境破坏。",["race:Undead"]="对于被遗忘者来说，道德顾虑在效率面前必须让位。林度恩这种深思熟虑的方法表明，皇家药剂师学会是如何运用冷酷的逻辑来解决其在世盟友所面临的问题的。"},sec={{t="一种化学药剂",b="部落在石爪山脉面临着持续的冲突，贪婪的荆棘谷地精不顾土地和当地居民的死活，肆意破坏着荒野。药剂师林度恩并没有选择派遣军队去硬碰硬，而是提出了一种炼金术解决方案。他的计划是调制一种能让人麻痹、顺从的药剂，旨在抽干这些雇佣兵的侵略性，使他们变得虚弱而驯服。"},{t="从邪恶之徒手中窃取",b="酿造这种阴险的药剂需要一种极其罕见且在道德上备受争议的试剂：无辜者的血液。林度恩并没有强迫部落特工直接屠杀无辜者，而是利用了当地辛迪加的罪行。盘踞在敦霍尔德城堡的堕落贵族和强盗们雇佣了卑劣的暗影法师，这些法师为了进行亵渎的仪式而收集无辜者的血液，这使他们成为了炼金原料收集的绝佳目标。"}},faq={{q="为什么药剂师林度恩需要无辜者的血液？",a="药剂师林度恩将其作为一种实验性药剂的关键试剂。他计划酿造一种能够耗尽石爪山脉中荆棘谷地精暴力驱动力的虚弱毒素，从而让这些污染者变得顺从且容易控制。",al={"无辜者的血液有什么用","为什么需要无辜者的血液","林度恩血液任务"}},{q="谁拥有无辜者的血液药剂？",a="这些药剂由辛迪加暗影法师携带。这些卑劣的施法者潜伏在塔伦米尔东南方的敦霍尔德城堡废墟中，将血液私藏起来用于他们自己的邪恶法术。",al={"谁掉落血液","去哪里获取无辜者的血液","无辜者的血液位置"}},{q="为什么希尔斯布莱德的任务会涉及石爪山脉？",a="卡利姆多的部落领袖向东部王国的皇家药剂师学会寻求科学援助。尽管对抗荆棘谷地精的冲突发生在石爪山脉，但像塔伦米尔的药剂师林度恩这样的专家，掌握着调制专业生物药剂所需的邪恶技艺。",al={"与石爪山脉的联系","为什么塔伦米尔要管石爪山脉"}},{q="什么是辛迪加？",a="辛迪加是一个由奥特兰克废墟王国的前人类贵族组成的组织，他们沦为了强盗、刺客和暴徒。为了夺回失去的土地，他们不择手段，进行勒索、使用黑魔法，并劫掠任何经过希尔斯布莱德和奥特兰克地区的人。",al={"辛迪加是什么人","辛迪加背景故事"}},{q="敦霍尔德城堡在哪里？",a="敦霍尔德城堡位于希尔斯布莱德丘陵中塔伦米尔的东南部。它曾经是一座臭名昭著的人类堡垒和兽人收容所，如今已半成废墟，是辛迪加的主要据点之一。",al={"寻找敦霍尔德城堡","敦霍尔德在哪里"}},{q="部落是为了得到这些血液而实施谋杀吗？",a="不是。虽然皇家药剂师学会很少回避残酷的手段，但林度恩特别指示特工去搜集辛迪加暗影法师已经从受害者身上获取的血液。",al={"部落是否杀害无辜者","无辜者的血液来源"}}},fp="18,221,19.322.0,22.367.0,46.230.0,36.172.0,60.247.0,22.243.0,32.185.0,49.163.0"}
P.entries["quest:1067"] = {n="返回雷霆崖",s="这个任务要求一名特工将药剂师林度恩在塔伦米尔配制的一种强效化学药剂带回海对岸的雷霆崖。在那里，药剂师扎玛正在等待这种化合物，以便她能研制出一种对抗荆棘谷地精的喷洒装置。这标志着皇家药剂师协会在牛头人东道主的眼皮底下进行秘密研究的关键一步。",h="这个任务要求一名特工将药剂师林度恩在塔伦米尔配制的一种强效化学药剂带回海对岸的雷霆崖。在那里，药剂师扎玛正在等待这种化合物，以便她能研制出一种对抗荆棘谷地精的喷洒装置。这标志着皇家药剂师协会在牛头人东道主的眼皮底下进行秘...",kw={"药剂师林度恩","药剂师扎玛","林度恩的毒药","预见之池","返回雷霆崖","皇家药剂师协会","塔伦米尔","剧毒粮草","荆棘谷地精"},ang={["faction:Horde"]="被遗忘者炼金术师之间的合作努力通过针对荆棘谷地精的破坏性行动，有助于保护部落的利益。",["race:Tauren"]="尽管玛加萨·野性图腾和长老们欢迎被遗忘者来到雷霆崖，希望他们能找到救赎或治愈的方法，但灵魂高地下方的药剂师们却将时间花在了开发传染性生物武器上。",["race:Undead"]="这项任务展示了皇家药剂师协会影响深远的运作网络，协调着洛丹伦前线与卡利姆多研究哨所之间的研究工作。"},sec={{t="跨洲运送",b="在获得希尔斯布莱德丘陵所需的易挥发配料后，药剂师林度恩成功合成了他的剧毒药剂。林度恩非常渴望看到他的生物制品在活体对象身上进行测试，但单纯的原始毒素缺乏有效的投送机制。为了最大化其效果，必须将药瓶带回穿越无尽之海，送抵莫高雷的峭壁，交到药剂师扎玛等待的手中。"},{t="扎玛的装置",b="扎玛居住在雷霆崖灵魂高地下方的阴影底层，担任皇家药剂师协会的使节和研究员。在收到林度恩的配方后，她着手将液体转化为气溶胶试剂，制造出一种被称为剧毒粮草的加压装置。她的最终目标是将这种生物武器直接释放到入侵的荆棘谷地精身上。"}},faq={{q="将毒素带到雷霆崖的目的是什么？",a="药剂师林度恩制造了原始液体毒素，但它需要一种专门的散布系统来将其效果在大范围内最大化。药剂师扎玛拥有将配方改良为名为剧毒粮草的气溶胶装置所需的工程技能。",al={"为什么选择雷霆崖","扎玛用毒素做什么","林度恩毒素的用途"}},{q="这种药剂的目标是谁？",a="这种毒素是专门为对付荆棘谷地精而设计的，这是一个在石爪山脉及其他地区肆虐的无情地精采矿联合体。",al={"谁会被下毒","林度恩毒素的目标","我们在和谁作战"}},{q="药剂师扎玛在哪里？",a="药剂师扎玛位于预见之池，那是一个隐藏在雷霆崖灵魂高地下方的洞穴网络。",al={"寻找扎玛","药剂师扎玛在哪里","扎玛的位置"}},{q="为什么幽暗城的药剂师要在牛头人城市工作？",a="牛头人给予了被遗忘者庇护，并支持他们加入部落，主要是希望帮助他们找到治愈自己疾病的方法。药剂师扎玛担任皇家药剂师协会的使节，尽管她的工作往往更倾向于瘟疫和进攻性生物武器，而非治愈。",al={"雷霆崖的被遗忘者","为什么亡灵在雷霆崖","莫高雷的药剂师"}},{q="上交毒素后会发生什么？",a="一旦扎玛拿走药瓶，她就会在身边制造出剧毒粮草。随后她会派遣你去石爪山脉的一个荆棘谷地精设施部署这种气溶胶机器。",al={"下一个任务","返回雷霆崖之后","剧毒粮草任务"}},{q="谁创造了原始配方？",a="这种毒素是由药剂师林度恩调制的，他是皇家药剂师协会驻扎在希尔斯布莱德丘陵内塔伦米尔的一名研究员。",al={"谁制作了毒药","林度恩是谁","药剂师林度恩背景故事"}}},fp="23,164,27.269.0,17.259.1,59.153.0,37.129.0,34.81.0,56.239.0,40.146.1,33.88.0"}
P.entries["quest:1068"] = {n="伐木机",s="“碎木机”是部落的一项任务，要求冒险者在狂风峭壁追捕两台特制的荆棘谷地精伐木机甲。在萨满祭司希雷斯·碎石的指引下，玩家将对抗那种折磨着石爪山脉原生灵魂的机械毁林行为。",h="“碎木机”是部落的一项任务，要求冒险者在狂风峭壁追捕两台特制的荆棘谷地精伐木机甲。在萨满祭司希雷斯·碎石的指引下，玩家将对抗那种折磨着石爪山脉原生灵魂的机械毁林行为。",kw={"伐木","希雷斯·碎石","碎木机","碎木机任务","石爪山脉","荆棘谷地精","狂风峭壁","xt:4","xt:9"},ang={["class:Shaman"]="希雷斯强调了精神魔法与自然之间深刻的共鸣，提醒萨满祭司们元素平衡依赖于保卫居住在这片土地上的灵魂。",["faction:Horde"]="随着部落在卡利姆多各地建立立足点，遏制荆棘谷地精不受管制的贪婪对于保护这片土地和确保石爪山脉的安全通行至关重要。",["profession:Engineering"]="XT系列伐木机甲展示了先进的地精碎木机设计，平衡了机械液压锯与原始的蒸汽动力。",["race:Tauren"]="毫无灵魂的地精机械对石爪山脉古老森林的亵渎，直接违背了牛头人对大地母亲的虔诚。"},sec={{t="关于毁林的幻象",b="兽人萨满祭司希雷斯·碎石驻扎在贫瘠之地与石爪山脉之间尘土飞扬的边界线上，静静地倾听着无形界域的声音。虽然石爪山脉大部分的精神之声都被混乱所淹没，但有一个幻象却带着令人心碎的清晰感出现在她面前：类人形状的装置正以极不自然的速度撕裂着古老的森林。这些由地精设计的碎木机被标记为XT:4和XT:9，它们正在屠戮狂风峭壁的林地，向周围的自然之灵散发着阵阵痛苦。"},{t="让锯子沉寂",b="为了阻止这场破坏，部落勇士深入巨木谷西北方的狂风峭壁，即荆棘谷地精活动的区域。追踪并摧毁这些特定的伐木构装体，将对山脉的商业性毁林行为造成沉重打击。虽然摧毁XT:4和XT:9能平息受伤树灵暂时的哀鸣，但希雷斯警告说，除非荆棘谷地精彻底放弃石爪山脉，否则这片土地还将面临更黑暗的暴行。"}},faq={{q="希雷斯·碎石是谁？",a="希雷斯·碎石是一位驻扎在靠近贫瘠之地的石爪山脉南边界的兽人萨满祭司。她与这片土地的元素和精神力量息息相通，并作为痛苦的森林之灵的传导者，抗议荆棘谷地精的迅速扩张。",al={"希雷斯是谁","任务发布者希雷斯","希雷斯·碎石背景故事"}},{q="XT:4和XT:9是什么？",a="XT:4和XT:9是荆棘谷地精在狂风峭壁运营的特制指定伐木碎木机。这些机械行者由蒸汽引擎驱动，并由地精操作员驾驶，它们砍伐古老树木的速度远超人工劳工。",al={"什么是碎木机","xt:4和xt:9","碎木机目标"}},{q="狂风峭壁在哪里？",a="狂风峭壁位于石爪山脉的北部，地处巨木谷的西北方。它已经被荆棘谷地精改造成了一个巨大的工业伐木盆地。",al={"狂风峭壁位置","在哪里可以找到碎木机","机器在哪里"}},{q="为什么萨满祭司会关心树木和德鲁伊魔法？",a="正如希雷斯所解释的那样，萨满与灵魂的沟通与德鲁伊的自然魔法有着密切的联系。对活生生的森林造成的创伤会回荡在精神领域中，使敏锐的萨满祭司不仅能听到元素的不安，还能听到被屠戮的树灵的哀号。",al={"为什么萨满祭司关心树木","萨满与德鲁伊的联系","自然之灵与萨满"}},{q="谁拥有并操作这些碎木机？",a="这些碎木机属于荆棘谷地精，这是一个由地精经营的肆无忌惮的商业集团，因在艾泽拉斯各地残酷地掠夺宝贵的自然资源、丝毫不顾及当地生态系统或祖辈居民而臭名昭著。",al={"谁制造了xt:4","谁在操作碎木机","荆棘谷地精的碎木机"}},{q="摧毁XT:4和XT:9能赶走荆棘谷地精吗？",a="不能。虽然摧毁这些旗舰机器能平息哭泣的树灵并阻碍当地的伐木工作，但荆棘谷地精在狂风峭壁拥有广泛的工业立足点，需要荒野守护者们进行持续的抵抗。",al={"荆棘谷地精会离开吗","“碎木机”任务之后","任务结果"}}},fp="18,161,25.496.0,18.426.0,26.269.0,23.219.0,24.181.0,53.261.0,38.234.0,61.235.0"}
P.entries["quest:1069"] = {n="深苔蜘蛛的卵",s="位于棘齿城的麦伯克·米希瑞克斯想要抓住席卷藏宝海湾的一种异国美食潮流：蜘蛛蛋煎蛋卷。为了供应利润丰厚的海外市场，他雇佣冒险者前往石爪山脉采集新鲜的深苔蜘蛛卵。",h="位于棘齿城的麦伯克·米希瑞克斯想要抓住席卷藏宝海湾的一种异国美食潮流：蜘蛛蛋煎蛋卷。为了供应利润丰厚的海外市场，他雇佣冒险者前往石爪山脉采集新鲜的深苔蜘蛛卵。",kw={"藏宝海湾","深苔","迪兹维格","麦伯克·米希瑞克斯","煎蛋卷","棘齿城","希塞尔山谷","蜘蛛卵","狂风峭壁"},ang={["faction:Alliance"]="联盟侦察兵在贫瘠之地和石爪山脉的暗夜精灵飞地之间绘制路线时，可以利用棘齿城的地精中立地位赚取旅费。",["faction:Horde"]="对于穿越贫瘠之地干旱荒原前往石爪山脉的旅行者来说，棘齿城提供的报酬可以资助他们对抗当地鹰身人和荆棘谷地精伐木工的行动。",["profession:Cooking"]="对深苔蜘蛛卵的需求突显了像藏宝海湾这样的港口城市中，富有冒险精神的食客们是如何将怪诞的异国美味视为身份象征的。"},sec={{t="对奢华的渴望",b="藏宝海湾的豪客和古怪海盗们对蜘蛛蛋煎蛋卷产生了无法满足的渴望，这使得无尽之海各地对这种稀有食材的需求激增。棘齿城商人麦伯克·米希瑞克斯发现了这个快速致富的机会，立刻着手为这座南部港口供货。由于东部王国缺乏这种特殊的蜘蛛美味，卡利姆多崎岖的荒野提供了完美的供应链。"},{t="山中的巢穴",b="采集任务需要冒险进入石爪山脉寻找深苔蜘蛛。它们的卵可以从狂风峭壁中荆棘谷地精伐木作业后的残留木材下，或者希塞尔山谷那些布满蛛网的深处发现。收集这些卵意味着要冒着被毒咬的风险，并面对那些让老练的拾荒者都感到恶心的密集虫群。"},{t="蒸汽蛤蜊快递",b="在蜘蛛卵变质或孵化之前将其运过海洋，速度与物流至关重要。麦伯克与棘齿城的码头管理员迪兹维格紧密合作，安排货船直接驶往荆棘谷的码头。将卵安全地装入板条箱后，麦伯克便能从远洋美食贸易中赚取可观的利润。"}},faq={{q="为什么麦伯克·米希瑞克斯想要蜘蛛卵？",a="一种新的美食风潮在藏宝海湾兴起：蜘蛛蛋煎蛋卷。藏宝海湾本地缺乏这种蛋的供应，这为棘齿城的地精商人创造了一个有利可图的出口机会。",al={"为什么要蜘蛛卵","麦伯克 蜘蛛卵","蛋的用途"}},{q="在哪里可以找到深苔蜘蛛卵？",a="它们位于贫瘠之地西北方的石爪山脉。这些蛋可以在狂风峭壁的残存树木下，或者深入被蜘蛛盘踞的希塞尔山谷中收集。",al={"深苔蜘蛛卵在哪里","蛋的位置","石爪山脉蜘蛛卵位置"}},{q="为什么麦伯克警告不要去希塞尔山谷？",a="希塞尔山谷以大量的蜘蛛群、浓密的蛛网和半消化的猎物而闻名。麦伯克警告说，胃口不好的人最好还是在狂风峭壁的树下进行采集。",al={"希塞尔山谷警告","肠胃不适 希塞尔"}},{q="收集后的蛋由谁来运输？",a="麦伯克与棘齿城码头的码头管理员迪兹维格合作，安排商船穿越海洋直接运往藏宝海湾。",al={"谁运输这些蛋","码头管理员 运输","迪兹维格 蛋"}},{q="这些蛋是生吃还是煮熟吃？",a="它们被烹饪成煎蛋卷，作为造访藏宝海湾酒馆的富裕顾客和冒险者们的一种古怪奢华菜肴。",al={"蜘蛛卵怎么吃","蜘蛛煎蛋卷"}},{q="双方阵营的玩家都能完成这个任务吗？",a="是的。棘齿城是由热砂港管理的中立港口，因此麦伯克·米希瑞克斯会向联盟和部落的旅行者提供这份合同。",al={"这个任务是中立的吗","部落或联盟 蜘蛛卵"}}},fp="20,221,18.351.0,22.355.0,24.294.0,41.188.0,44.178.0,42.194.0,34.121.0,33.126.0,48.133.0"}
P.entries["quest:107"] = {n="给威廉·匹斯特的信",s="“致威廉的便条”是艾尔文森林南部的一个差事，由米莱德·斯通菲尔德委托，旨在帮助两个来自世仇家族的年轻恋人。通过将米莱德的信件送达闪金镇的药剂师威廉·匹斯特手中，冒险者们寻求通过炼金术来让梅贝尔和托米·乔终成眷属。",h="“致威廉的便条”是艾尔文森林南部的一个差事，由米莱德·斯通菲尔德委托，旨在帮助两个来自世仇家族的年轻恋人。通过将米莱德的信件送达闪金镇的药剂师威廉·匹斯特手中，冒险者们寻求通过炼金术来让梅贝尔和托米·乔终成眷属。",kw={"艾尔文森林","闪金镇","米莱德·斯通菲尔德","lion's pride inn","梅贝尔·马科伦","致威廉的便条","托米·乔·斯通菲尔德","威廉·匹斯特"},ang={["faction:Alliance"]="当官方卫兵专注于军事威胁时，穿行在艾尔文森林的联盟冒险者经常会帮助当地农户解决个人危机。",["race:Human"]="斯通菲尔德家族和马科伦家族之间持续不断的世仇使艾尔文森林的人类邻居们分裂开来，这使得富有同情心的长辈们不得不依赖谨慎的信使。"},sec={{t="艾尔文森林的苦命鸳鸯",b="斯通菲尔德家族和马科伦家族在艾尔文森林南部做邻居多年，但他们之间根深蒂固的世仇使得两家无法建立正常的关系。夹在中间的正是年轻的托米·乔·斯通菲尔德和梅贝尔·马科伦，他们的恋情必须在绝对保密的情况下进行。尽管他们的父母怀着无休止的怨恨，但米莱德·斯通菲尔德奶奶却对这对年轻恋人深表同情，并试图寻找一种非同寻常的方法来让他们在一起。"},{t="给闪金镇的请求",b="米莱德·斯通菲尔德奶奶认为世俗的劝说永远无法动摇这些互相敌对的家族，因此她派遣了一名信使前往北方的闪金镇Lion's Pride Inn。她的信是写给威廉·匹斯特的，这是一位经验丰富的炼金术士和药剂师，也是米莱德多年的老相识。在收到信件后，威廉被梅贝尔和托米·乔的困境所打动，决定利用他的炼金知识来帮助他们。"}},faq={{q="威廉·匹斯特是谁？",a="威廉·匹斯特是一位居住在闪金镇Lion's Pride Inn的炼金术士和药剂师。他是米莱德·斯通菲尔德奶奶的一位老友，以调制草药和特制药剂而闻名。",al={"威廉·匹斯特是谁","威廉·匹斯特 闪金镇","闪金镇 炼金术士"}},{q="是谁给威廉写了便条？",a="这封便条是由斯通菲尔德农场的女主人米莱德·斯通菲尔德奶奶所写。她同情梅贝尔·马科伦和托米·乔·斯通菲尔德之间被禁止的恋情，希望威廉·匹斯特能想出一个办法来帮助他们。",al={"谁写了便条","斯通菲尔德奶奶 便条","米莱德·斯通菲尔德"}},{q="为什么梅贝尔和托米·乔不能公开在一起？",a="梅贝尔·马科伦和托米·乔·斯通菲尔德深深相爱，但他们的家族之间存在着长期且激烈的对抗。米莱德·斯通菲尔德奶奶认为，威廉·匹斯特可能知道某种药水或计划，能让这两位恋人在家族的敌意下走到一起。",al={"为什么要帮助梅贝尔和托米·乔","年轻恋人 任务 艾尔文森林","斯通菲尔德 马科伦 世仇"}},{q="在哪里可以找到威廉·匹斯特？",a="威廉·匹斯特住在闪金镇的Lion's Pride Inn，这是艾尔文森林闪金镇的中心酒馆和聚会中心。",al={"威廉·匹斯特在哪里","匹斯特 位置","lion's pride inn 炼金术士"}},{q="米莱德·斯通菲尔德奶奶的真实名字是什么？",a="她的名字是米莱德，正如威廉·匹斯特在收到她的信后提到多年未见米莱德时所说的那样。",al={"斯通菲尔德奶奶的名字是什么","斯通菲尔德奶奶 名字"}},{q="威廉·匹斯特对这封便条有何反应？",a="在阅读了米莱德的信后，威廉感慨自己多年未见米莱德，并想知道信里写了什么，因为米莱德希望他的炼金术能帮助这对苦命鸳鸯。",al={"威廉如何处理便条","威廉·匹斯特 反应"}}},fp="15,295,22.448.0,22.423.0,22.217.0,29.228.0,59.270.0,34.148.0,38.138.0,42.195.0"}
P.entries["quest:1070"] = {n="守卫石爪山",s="“石爪山脉的守望”是一个联盟引导任务，指引冒险者从灰谷向南进入崎岖的石爪山脉。哨兵塞恩希尔派遣旅行者去查看她的侦察兵朋友凯拉·影矛的情况，凯拉和一名侏儒法师一起被派往峭壁，以监视荆棘谷地精的工业入侵活动。",h="“石爪山脉的守望”是一个联盟引导任务，指引冒险者从灰谷向南进入崎岖的石爪山脉。哨兵塞恩希尔派遣旅行者去查看她的侦察兵朋友凯拉·影矛的情况，凯拉和一名侏儒法师一起被派往峭壁，以监视荆棘谷地精的工业入侵活动。",kw={"灰谷","凯拉·影矛","石爪山脉的守望","哨兵塞恩希尔","石爪山脉","荆棘谷地精","狂风峭壁"},ang={["faction:Alliance"]="这项任务标志着联盟边境安全的南向扩张，将灰谷的防御哨所与石爪山脉中孤立的侦察哨点连接了起来。",["race:Gnome"]="哨兵们对侏儒的魔法和装置持有深深的怀疑，认为加入一名侏儒法师是卡利姆多荒野中一个古怪且不可预测的变数。",["race:NightElf"]="这项任务展现了传统暗夜精灵哨兵与他们东部王国盟友（特别是侏儒）在奥术和机械实践上的摩擦。"},sec={{t="一名南下的侦察兵",b="驻扎在阿斯特兰纳的哨兵塞恩希尔密切注视着威胁古老森林的敌人。由于深深担忧她的朋友凯拉·影矛，塞恩希尔请求路过的联盟勇士去寻找她。凯拉是由哨兵狼奔派遣进入石爪山脉，调查高地日益动荡的局势，但目前音讯全无，这让塞恩希尔对她的安全感到焦虑。"},{t="峭壁之上的不安合作",b="塞恩希尔的担忧因凯拉的搭档而加剧：一名由联盟领导层指派与她共同行动的侏儒法师。虽然暗夜精灵出于战略必要加入了大联盟，但许多哨兵对在纯净荒野中运作的奥术使用者和捣鼓装置的侏儒仍持怀疑态度。在狂风峭壁上方的断崖上找到凯拉，可以看到一个哨所，这里监视着荆棘谷地精所造成的广泛环境破坏。"}},faq={{q="谁提供这个任务？",a="该任务由驻扎在灰谷阿斯特兰纳的暗夜精灵哨兵，哨兵塞恩希尔提供。",al={"任务给予者","任务起始地点","谁发布石爪山脉的守望"}},{q="我在哪里可以找到凯拉·影矛？",a="凯拉·影矛在石爪山脉的一处高耸岩脊上扎营，俯瞰着通往狂风峭壁的峡谷入口。",al={"凯拉位置","寻找凯拉","凯拉·影矛具体点"}},{q="为什么哨兵塞恩希尔担心凯拉？",a="凯拉被派去调查石爪山脉的危险敌对入侵，但一直没有传回消息。此外，塞恩希尔感到担忧是因为联盟给凯拉安排了一名侏儒法师搭档，她认为这种组合是不祥之兆。",al={"为何担心","塞恩希尔的担忧"}},{q="石爪山脉有哪些活跃的威胁？",a="山脉深受荆棘谷地精之害，这是一个肆无忌惮的风险投资地精采矿和伐木集团，正在破坏荒野；此外还有好战的本地野兽，以及从南面入侵的部落军队。",al={"石爪山脉敌人","石爪山脉里有什么人"}},{q="塔拉是谁？",a="塔拉是哨兵塞恩希尔的名字。当你见到凯拉时，她会亲切地称呼她的老朋友为塔拉，并为她能协调侦察兵和冒险者而感到自豪。",al={"塔拉是谁","提及塔拉"}},{q="找到凯拉·影矛后会发生什么？",a="到达凯拉那里即完成了旅程，并会开启后续任务，协助她和她的侏儒搭档继续监视狂风峭壁的入侵威胁。",al={"后续任务","what comes next"}}},fp="22,207,18.334.0,32.341.0,21.75.0,35.125.0,45.204.0,52.184.0,12.164.0,45.145.0"}
P.entries["quest:1071"] = {n="侏儒学者",s="“侏儒的喘息”是一个联盟任务，由古怪的技师加克希姆·尘链在石爪山脉提供。面对荆棘谷地精在狂风峭壁的疯狂工业扩张，加克希姆不堪重负，他雇佣冒险者去清理那里的伐木工和毁林者，以便争取足够的时间来发明新的防御手段。",h="“侏儒的喘息”是一个联盟任务，由古怪的技师加克希姆·尘链在石爪山脉提供。面对荆棘谷地精在狂风峭壁的疯狂工业扩张，加克希姆不堪重负，他雇佣冒险者去清理那里的伐木工和毁林者，以便争取足够的时间来发明新的防御手段。",kw={"毁林者","炸药","加克希姆·尘链","侏儒","伐木工","石爪山脉","荆棘谷地精","狂风峭壁"},ang={["profession:Engineering"]="工程师们会赞赏加克希姆的哲学，即机械和化学可以解决环境危机，也会欣赏他对于高能炸药的偏爱。",["race:Gnome"]="加克希姆的任务代表了经典的侏儒抱负：通过卓越的智慧和一点点高能炸药，解决自然与文明之间古老的哲学冲突。",["race:NightElf"]="虽然卡多雷哨兵通常对侏儒机械怀有深深的怀疑，但荆棘谷地精的持续推进使得任何有效的威慑手段在石爪山脉都受到欢迎。"},sec={{t="冲突的联盟",b="加克希姆·尘链代表着奥术、炼金与工程科学启蒙大会。他驻扎在石爪山脉的古老树林中，其职责是向崇尚自然的暗夜精灵证明，现代侏儒发明——结合了魔法、化学药剂和机械工程——能够有效地保护她们受威胁的土地。然而，荆棘谷地精那永不停歇的推进速度让他几乎没有时间来验证他的防御装置原型。"},{t="在狂风峭壁争取时间",b="为了遏制这种势头，加克希姆直接派遣冒险者前往狂风峭壁的浓烟滚滚的作业区。通过针对前线的荆棘谷地精伐木工和毁林者，旅行者们为加克希姆赢得了他所需的喘息机会，让他可以整理工坊并设计他的下一道防线：战略性的可控高能炸药。"}},faq={{q="加克希姆·尘链是谁？",a="加克希姆·尘链是一位位于石爪山脉的联盟侏儒法师兼技师。他是奥术、炼金与工程科学启蒙大会的特工，试图帮助暗夜精灵对抗工业入侵者。",al={"加克希姆","加克希姆·尘链是谁","任务发布者加克希姆"}},{q="为什么一个侏儒要保护暗夜精灵的森林？",a="加克希姆认为，他的职责是向持怀疑态度的暗夜精灵证明，先进的侏儒科学——特别是奥术、炼金和工程学——可以与自然共存，并能积极帮助保护她们的荒野免受不受限制的工业开发。",al={"为什么侏儒在石爪山脉","为什么要帮助暗夜精灵","侏儒生态学"}},{q="狂风峭壁的荆棘谷地精是什么人？",a="荆棘谷地精是一个由地精运营的冷酷商业集团，正在对狂风峭壁进行露天开采和森林砍伐。他们纯粹受利益驱使，已经在山谷中部署了大量的伐木工、毁林者和重型伐木机械。",al={"石爪山脉荆棘谷地精","荆棘谷地精是谁","狂风峭壁地精"}},{q="伐木工和毁林者在哪里可以找到？",a="他们在整个狂风峭壁活动。那是一个重工业化的盆地，位于加克希姆在石爪山脉主路沿线位置的正东方向。",al={"伐木工在哪里","去哪里找毁林者","狂风峭壁位置"}},{q="加克希姆在有时间思考后打算做什么？",a="在逼退地精工人后，加克希姆打算补充他的高能炸药储备，利用针对性的山体爆破将荆棘谷地精从树林中驱赶出去。",al={"加克希姆计划","侏儒的喘息后续","炸药计划"}},{q="什么是奥术、炼金与工程科学启蒙大会？",a="这是一个侏儒学术社团，探索奥术法术、化学混合物和机械工程的整合，以解决艾泽拉斯各地的实际问题。",al={"侏儒大会","奥术大会","什么是启蒙大会"}}},fx={["8136de5d"]={q="加克希姆·尘链为什么想削减荆棘谷地精的人手？",a="加克希姆·尘链认为，身为奥术学、炼金术与工程科学启蒙议会的一员，他有责任证明侏儒的聪明才智能够守护暗夜精灵的圣林。荆棘谷地精持续快速地砍伐森林，让他忙得不可开交，根本抽不出空来设计、组织和组装扭转局势所需的巧妙装置与炸药。",al={"为何杀死伐木工","加克希姆的动机","为何削减荆棘谷地精的人手"}},["7aed6e2a"]={q="加克希姆·尘链为什么需要你去对付地精？",a="加克希姆是发明家和研究员，可不是一支军队；而且他在石爪山脉也得不到联盟大军的有力支援。他既要确保营地安全，又要设法绘制新的机械设计图，实在无法独自击退源源不断涌来的荆棘谷地精伐木工。他只能依靠你这样的能干冒险者削减敌人的人数，好腾出精力研制对策。",al={"加克希姆为何需要我","加克希姆为何需要帮助","为何派冒险者去"}}},fp="17,322,19.463.0,29.304.0,24.258.0,51.258.0,46.220.0,47.163.0,54.192.0,81.174.0"}
P.entries["quest:1072"] = {n="老同事",s="“一位老同事”是联盟的一项任务，由石爪山脉的侏儒工程师加克希姆·尘链发布。为了制造一种威力惊人的装置，加克希姆派冒险者跨越重洋前往铁炉堡，寻找一位能够合成危险爆炸混合物的老相识。完成这项差事是获得被称为硝基甘油炸药（即NG-5）的挥发性化合物的关键。",h="“一位老同事”是联盟的一项任务，由石爪山脉的侏儒工程师加克希姆·尘链发布。为了制造一种威力惊人的装置，加克希姆派冒险者跨越重洋前往铁炉堡，寻找一位能够合成危险爆炸混合物的老相识。完成这项差事是获得被称为硝基甘油炸药（即N...",kw={"炸药","加克希姆·尘链","铁炉堡","洛玛克·链带","ng-5","硝基甘油炸药","石爪山脉","tinker town"},ang={["faction:Alliance"]="这项任务派遣联盟冒险者踏上一段跨越大陆的旅程，从饱受战火蹂躏的卡利姆多山脊回到安全的铁炉堡。",["profession:Engineering"]="工程师们会赞赏加克希姆和洛玛克对最大火力的不懈追求，而不顾其中涉及的危险物流。",["race:Gnome"]="这是一个典型的侏儒式冒险，涉及远距离学术网络联络、古怪的竞争关系以及极不稳定的危险爆炸化合物。"},sec={{t="挥发性配方",b="在石爪山脉的群峰中驻扎时，加克希姆·尘链构思了他迄今为止最雄心勃勃的工程计划。制造那种规模的机械需要特殊的燃料，远非普通的火药或原油所能比拟。具体来说，加克希姆需要硝基甘油炸药（也被称为NG-5），这是一种威力足以确保毁灭性结果的爆炸混合物，前提是一切按计划进行。"},{t="工匠区的联系人",b="配置NG-5绝非易事，而加克希姆只知道一个人有足够的技能来提炼它：一位名叫洛玛克·链带的老相识。洛玛克住在遥远的东方，位于铁炉堡这座山中堡垒深处的侏儒区——工匠区。信使带着重任跋涉而来，却遭到了洛玛克充满疑虑和偏执的质问。"}},faq={{q="谁发布了“一位老同事”这个任务？",a="该任务由加克希姆·尘链提供，他是一位驻扎在石爪山脉的侏儒工程师。",al={"任务发布者","谁开启一位老同事任务","加克希姆任务"}},{q="我在哪里可以找到洛玛克·链带？",a="洛玛克·链带可以在工匠区找到，那是位于矮人城市铁炉堡东部的侏儒居住区。",al={"洛玛克在哪里","洛玛克·链带位置","铁炉堡洛玛克"}},{q="什么是硝基甘油炸药？",a="硝基甘油炸药，也称为NG-5，是一种由洛玛克·链带研发，并被加克希姆·尘链渴望用于其高能装置的极度挥发性化学炸药。",al={"什么是ng-5","硝基甘油炸药","ng 5"}},{q="为什么加克希姆派我大老远跑到铁炉堡去？",a="加克希姆声称洛玛克·链带是唯一有能力合成特殊的NG-5化合物的人，而这种化合物对于驱动他的实验装置至关重要。",al={"为什么要前往铁炉堡","为什么找洛玛克","为什么要前往工匠区"}},{q="找到洛玛克·链带后会发生什么？",a="一旦你向多疑的洛玛克确认了加克希姆的请求，他就会交给你任务“无能+化学品=乐趣”，要求你收集混合该批次炸药所需的危险试剂。",al={"后续任务","一位老同事之后是什么"}},{q="哪个阵营可以执行此任务？",a="这完全是联盟的任务，因为它源于石爪山脉的一名联盟阵营侏儒，并以联盟首都铁炉堡作为终点。",al={"这是联盟专属吗","部落版本","部落可以做吗"}}},fp="16,264,17.308.0,22.284.0,37.87.0,33.89.0,28.156.0,48.128.0,43.148.0,38.150.0"}
P.entries["quest:1073"] = {n="失职+药剂=快乐",s="为了在石爪山脉寻找对抗荆棘谷地精的爆炸性手段，联盟的冒险者们被派往海对岸的铁炉堡。在那里，古怪的侏儒洛玛克·链带同意调制他那不稳定的发明——硝基米甘油，前提是你得找回所需的炼金试剂。",h="为了在石爪山脉寻找对抗荆棘谷地精的爆炸性手段，联盟的冒险者们被派往海对岸的铁炉堡。在那里，古怪的侏儒洛玛克·链带同意调制他那不稳定的发明——硝基米甘油，前提是你得找回所需的炼金试剂。",kw={"初级坚韧药剂","加克希姆·尘链","铁炉堡","洛玛克·链带","法力药水","硝基米甘油","石爪山脉","荆棘谷地精"},ang={["faction:Alliance"]="从石爪山脉到铁炉堡的长途跋涉，凸显了在充满敌意的卡利姆多各处支持偏远联盟前哨站的后勤压力。",["profession:Engineering"]="在标准的爆破粉末无法对付荆棘谷地精的钢铁时，将深奥的炼金术与工程学原理结合起来，能产生更具毁灭性的结果。",["race:Gnome"]="洛玛克代表了侏儒创造力中不受约束、疯狂的一面，他将纯粹的化学产出和理论应用置于安全或外交谨慎之上。"},sec={{t="不稳定的解决方案",b="加克希姆·尘链驻扎在石爪山脉崎岖的山路上，他需要强力的炸药来驱动他为对抗荆棘谷地精而设计的最先进装置。为此，他求助于一位住在铁炉堡的古怪前同事：洛玛克·链带。洛玛克是硝基米甘油的创造者，这种物质极其不稳定且具有毁灭性，以至于他觉得无论是谁在使用它，或者是谁在过程中被炸飞，都非常滑稽。"},{t="烟火所需的药水",b="尽管洛玛克迫切想看到地精的机械——甚至可能包括冒险者——被炸成碎片，但他在铁炉堡的工作室里已经没有成品的化合物了。在他调制新一批硝基米甘油之前，洛玛克要求提供常见的炼金药水：初级法力药水和初级坚韧药剂。在他看来，强迫冒险者收集这些原料有双重目的：既能确保他拥有反应所需的原料，又能证明他们对炼金术哪怕有一丝的尊重。"}},faq={{q="洛玛克·链带是谁？",a="洛玛克·链带是位于矮人主城铁炉堡的一位古怪侏儒炼金师兼技师。他是加克希姆·尘链的老同事，也是极其不稳定的爆炸性化合物硝基米甘油的发明者。",al={"洛玛克·链带","谁是洛玛克","铁炉堡侏儒"}},{q="洛玛克为什么想要药水而不是标准的工程学零件？",a="洛玛克将炼金术与他的机械知识相结合，以制造出高等级的易爆反应。初级法力药水的魔法能量以及初级坚韧药剂所增强的身体体液稳定性，成为了他特制的硝基米甘油混合物的基本试剂。",al={"为什么需要药水","炼金原料","为什么需要法力药水"}},{q="为什么要派冒险者大老远跑到铁炉堡去办这件事？",a="加克希姆·尘链被困在石爪山脉的荒野中，无法使用重工业或化学工作间。铁炉堡的洛玛克·链带是他唯一信任——或者说唯一畏惧到足以让他相信能拥有足以驱动他最先进装置的强力炸药——的同事。",al={"为什么去铁炉堡","为什么要跑这么远","加克希姆去铁炉堡"}},{q="什么是硝基米甘油？",a="硝基米甘油是洛玛克·链带独有的爆炸性化学制剂。它以极其不稳定而闻名，洛玛克称其为他最伟大的创造。",al={"硝基米甘油","什么是爆炸物","侏儒炸弹药水"}},{q="洛玛克担心荆棘谷地精或森林吗？",a="一点也不。洛玛克对使用高爆炸药来拯救树木的想法嗤之以鼻。他交出这种化合物的唯一兴趣，就是看着地精或送信人被炸成碎片的那种混乱前景。",al={"洛玛克在乎自然吗","洛玛克的动机"}},{q="完成这项任务需要成为炼金师吗？",a="不需要。虽然洛玛克谈到要考验你的炼金水平，但他同样接受通过交易、商人或其他工匠获得的试剂，只要他能得到配方所需的药水就行。",al={"需要炼金术吗","需要炼金术"}}},fp="28,218,19.403.0,24.373.0,23.195.0,66.256.0,57.258.0,28.133.0,57.191.0,53.181.0"}
P.entries["quest:1074"] = {n="失职+药剂=快乐",s="这项任务需要将一罐易挥发的NG-5从技师洛玛克·链带手中送往石爪山脉的加克希姆·尘链那里。加克希姆需要这种不稳定的化学物质来为几辆装满炸药的马车制造强力点火器。由此产生的爆炸将为联盟在这些充满争议的峭壁间的行动制造至关重要的牵制。",h="这项任务需要将一罐易挥发的NG-5从技师洛玛克·链带手中送往石爪山脉的加克希姆·尘链那里。加克希姆需要这种不稳定的化学物质来为几辆装满炸药的马车制造强力点火器。由此产生的爆炸将为联盟在这些充满争议的峭壁间的行动制造至关重...",kw={"炸药","工程学","加克希姆·尘链","侏儒","洛玛克·链带","ng-5","硝化甘油混合物","石爪山脉"},ang={["faction:Alliance"]="石爪山脉是一个充满争议的前线，一场巨大的爆炸将为联盟作战人员提供他们迫切需要的喘息空间。",["profession:Engineering"]="搬运NG-5需要对易挥发的化学物质有所了解，并且必须手稳，以避免提前爆炸。",["race:Gnome"]="也只有侏儒的野心才会认为用硝化甘油混合物引爆满载高爆炸药的马车是一种合理的牵制手段。"},sec={{t="一次危险的运输",b="侏儒工程学总是在天才与灾难的刀尖上游走，硝化甘油混合物——也就是NG-5——也不例外。洛玛克·链带交出这种不稳定的化合物时给出了严厉的警告：务必极其小心地搬运，否则在回程去找加克希姆·尘链的路上，你可能会把自己炸得粉身碎骨。"},{t="制造混乱的配方",b="在完好无损地收到罐子后，加克希姆·尘链揭示了他手头工作的真正目的。NG-5是将整整几马车炸药引爆所需的关键催化剂。通过制造一场巨大的爆炸，加克希姆希望能在石爪山脉制造混乱并引开敌人的注意力，好让联盟能够推进其在该地区的战略目标。"}},faq={{q="什么是NG-5？",a="NG-5，即硝化甘油混合物的简称，是由洛玛克·链带调配的一种极易挥发的化学化合物。它被用作重型军械无可置疑的点火催化剂。",al={"什么是硝化甘油混合物","ng-5","洛玛克给了我什么"}},{q="加克希姆·尘链是谁？",a="加克希姆·尘链是一位驻扎在石爪山脉的侏儒法师，他负责策划针对该地区威胁的联盟爆破行动和战术牵制任务。",al={"加克希姆","加克希姆·尘链是谁"}},{q="洛玛克·链带是谁？",a="洛玛克·链带是一位工程师，也是加克希姆·尘链的同僚，他负责调制危险的NG-5化合物，并将其托付给可靠的信使。",al={"洛玛克","洛玛克·链带是谁"}},{q="为什么加克希姆需要如此强大的爆炸威力？",a="加克希姆布置了多辆装满炸药的马车。NG-5提供了足以同时引爆它们所需的可靠且巨大的火花，从而制造出一场压倒性的牵制行动。",al={"为什么要用装满炸药的马车","加克希姆的计划","为什么要爆炸"}},{q="这种化学物质运输起来危险吗？",a="洛玛克明确警告说，NG-5非常不稳定，如果搬运不当极易引发灾难性的意外爆炸，不过只要信使足够沉稳，就能将其安全地送到加克希姆手中。",al={"ng-5会爆炸吗","ng-5安全吗"}},{q="这次运输发生在哪里？",a="这次运输的终点是石爪山脉崎岖隘口内加克希姆·尘链的驻地。",al={"加克希姆在哪里","石爪山脉的位置"}}},fp="28,226,19.239.0,24.277.1,13.141.0,24.150.0,23.136.0,44.126.0,39.113.0,36.87.0"}
P.entries["quest:1075"] = {n="马伦的卷轴",s="“来自马伦的卷轴”是一个联盟任务，它在侏儒的创造力与人类的奥术工艺之间架起了一座桥梁。富有创意的加克希姆·尘链需要一种特殊的法术来远程引爆他那极不稳定的NG-5炸药，因此派遣信使前往暴风城的核心，向法师科林·马伦咨询。",h="“来自马伦的卷轴”是一个联盟任务，它在侏儒的创造力与人类的奥术工艺之间架起了一座桥梁。富有创意的加克希姆·尘链需要一种特殊的法术来远程引爆他那极不稳定的NG-5炸药，因此派遣信使前往暴风城的核心，向法师科林·马伦咨询。",kw={"科林·马伦","西部荒野的恶魔","爆炸物","加克希姆·尘链","mage quarter","ng-5","远程引爆器","暴风城"},ang={["class:Mage"]="这项任务展示了肯瑞托和暴风城的奥术从业者如何经常与工程师合作，将塑能和转化应用于机械挑战。",["faction:Alliance"]="这项任务突出了侏儒修补匠与在暴风城法师区学习的人类巫师之间的实际合作。",["profession:Engineering"]="修补匠们经常发现，将不稳定的黑火药与奥术催化剂结合起来，可以解决诸如远程点火之类的复杂问题。",["race:Gnome"]="侏儒们从不羞于将技术与巫术结合起来，如果这能让他们在舒适的距离内获得更有效、更具破坏性的爆炸的话。"},sec={{t="跨越距离的火花",b="侏儒工程学以雄心勃勃的构想而闻名，但安全实施往往需要巧妙的解决方案。当加克希姆·尘链着手设计一种能够远程激活的爆炸装置时，机械引信被证明是不够的。加克希姆没有完全依赖机械定时器或拖拽的导线，而是设想了一种装置，只需在安全的有利位置按下一个按钮，就能引爆NG-5炸药。为了填补不稳定的火药与瞬时触发器之间的空白，他将目光投向了奥术魔法。"},{t="法师区的联系",b="为了获得必要的法术，加克希姆指引旅行者穿过王国，前往暴风城熙熙攘攘的法师区。那里住着科林·马伦，一位人类施法者，他对奥术的实际理解使他成为雄心勃勃的修补匠们的理想合作伙伴。马伦正在思考如何将爆炸点火与遥远的指令绑定在一起这一微妙问题，这也标志着组装加克希姆危险项目所需的奥术咒语的第一步。"}},faq={{q="是谁派我去找科林·马伦的？",a="是加克希姆·尘链派你执行这项任务。他需要从他的人类熟人那里得到一个奥术公式，以完成远程引爆器的制造。",al={"任务发布者","谁发布了来自马伦的卷轴","加克希姆任务"}},{q="科林·马伦在哪里可以找到？",a="科林·马伦居住在暴风城的法师区。你可以在该区域的塔楼和商店周围驻扎的导师、学徒和奥术研究员中找到他。",al={"科林·马伦位置","科林·马伦在哪里","找到马伦"}},{q="为什么加克希姆需要用一个法术来引爆装置？",a="加克希姆想要在安全距离外，通过按下一个按钮来引爆他的NG-5炸药。纯机械结构在远距离上可能既笨重又不可靠，因此他寻求马伦的奥术专业知识来制造一个瞬时远程触发器。",al={"为什么炸弹需要魔法","远程引爆背景","为什么要找法师"}},{q="什么是NG-5？",a="NG-5，即硝基米甘油，是加克希姆在铁炉堡的老同事洛玛克·链带酿造的一种极不稳定炸药。为了使其既有效又安全地用于实地部署，加克希姆需要一个远程引爆系统，这样操作员在点火时就可以处于爆炸半径之外。",al={"ng-5","什么是ng-5","加克希姆炸药"}},{q="与科林·马伦交谈后接下来要做什么？",a="一旦科林·马伦评估了关于远程引爆法术的请求，他就会指派你在西部荒野协助他完成任务“西部荒野的恶魔”。",al={"后续任务","来自马伦的卷轴之后是什么","科林·马伦后续"}},{q="科林·马伦是侏儒还是人类？",a="科林·马伦是一名人类法师。加克希姆在他的说明中幽默地指出，因为马伦是人类，所以他在暴风城的人群中应该很容易辨认。",al={"科林·马伦种族","马伦是什么种族","马伦是人类吗"}}},fp="20,170,24.245.0,27.285.0,30.129.0,33.162.0,52.220.0,17.222.0,50.132.0,36.128.0"}
P.entries["quest:1076"] = {n="西部荒野中的恶魔",s="“西部荒野的尘魔”是联盟为暴风城Mage Quarter的科林·马伦承接的一项差事。冒险者受命协助侏儒发明家加克希姆·尘链进行一项古怪的实验，他们被派往西部荒野那片荒凉的平原，去从活生生的尘魔身上收集不稳定的尘魔的残骸。这些收集到的尘土提供了附魔一张特制通讯卷轴所需的原始魔法成分。",h="“西部荒野的尘魔”是联盟为暴风城Mage...",kw={"科林·马伦","尘魔","尘魔的残骸","加克希姆·尘链","mage quarter","通讯法术","卷轴","暴风城","西部荒野"},ang={["class:Mage"]="对于奥术修行者来说，收集尘魔的残骸展示了附魔的实用技艺：捕捉狂野的元素共鸣，从而将复杂的通讯法术束缚在实体卷轴中。",["faction:Alliance"]="在暴风城文明的塔楼与西部荒野废弃荒芜的土地之间穿梭，突显了首都的舒适与王国正在崩溃的边境之间鲜明的对比。",["profession:Engineering"]="这项差事的起因是加克希姆·尘链的捣鼓，这突显了先进的工程项目往往需要结合奥术卷轴制作工艺来解决通讯难题。"},sec={{t="信使的组件",b="巫师科林·马伦正在协助工匠加克希姆·尘链进行一项不同寻常的冒险，但奥术工作需要特殊的试剂。为了给一张能够承载加克希姆所需通讯法术的卷轴附魔，马伦不能仅仅依靠墨水和羊皮纸。困在西部荒野本土尘魔体内的旋转元素魔法，提供了将法术束缚在羊皮纸上所需的精确且不稳定的介质。"},{t="元素荒野",b="西部荒野曾经是暴风城富饶的粮仓，但干旱、强盗和忽视使这片土地变得贫瘠而荒凉。旋转的尘魔如今在未开垦的田野中游荡，对旅行者和孤独的农户构成了威胁。通过击败这些活生生的旋风并收集其残留物，冒险者可以获得让法师的附魔生效所需的凝聚元素精华。"}},faq={{q="科林·马伦是谁？",a="科林·马伦是一位居住在暴风城Mage Quarter的人类法师。他与城中的其他施法者一起工作，偶尔也会通过准备附魔卷轴和奥术组件来协助外部的研究人员，例如侏儒工程师加克希姆·尘链。",al={"科林·马伦","任务发布者是谁","暴风城的法师"}},{q="为什么科林·马伦需要尘魔的残骸？",a="马伦需要这些残骸来为加克希姆·尘链的一张特制通讯卷轴附魔。尘魔残骸中蕴含的残留元素能量，提供了将通讯法术刻印到羊皮纸上所必需的奥术亲和力。",al={"为什么需要尘魔的残骸","尘魔的残骸有什么用","为什么要前往西部荒野"}},{q="尘魔出没于何处？",a="尘魔在西部荒野的干旱平原和贫瘠田野中到处游荡，特别是在哨兵岭道路以南，那些被忽视的农场之间的尘土飞扬的地带。",al={"尘魔的位置","尘魔在哪里","西部荒野的尘魔"}},{q="加克希姆·尘链是谁？",a="加克希姆·尘链是一位雄心勃勃的侏儒发明家，热衷于深奥的工程学项目。科林·马伦通过起草附魔卷轴来协助他的实验，从而推动其项目进展。",al={"加克希姆","加克希姆·尘链","加克希姆是谁"}},{q="把残骸带给马伦后会发生什么？",a="一旦获得了残骸，马伦就会将通讯附魔编织进一张完整的卷轴中，并指示你将其带回给加克希姆，以便这位侏儒继续他的实验。",al={"任务奖励","what comes next","西部荒野的尘魔后续"}},{q="尘魔是魔法生物还是自然生物？",a="尘魔是小型风元素，它们表现为由沙砾构成的活旋风，在当今西部荒野那片干涸且动荡的土地上繁衍生息。",al={"尘魔是元素生物吗","尘魔的背景故事"}}},fp="18,250,24.333.0,20.278.0,21.211.0,46.163.0,28.150.0,24.160.0,49.152.0,45.139.0"}
P.entries["quest:1077"] = {n="给加克希姆的特快专递",s="“加克希姆的特别快递”代表了暴风城与卡利姆多荒野之间的一项联盟信使任务的返程。科林·马伦提供了一份特制的通讯卷轴，要求将其带回石爪山脉给侏儒技师加克希姆·尘链。卷轴内含制造远程爆炸物所需的奥术组件，用于对抗当地的森林砍伐活动。",h="“加克希姆的特别快递”代表了暴风城与卡利姆多荒野之间的一项联盟信使任务的返程。科林·马伦提供了一份特制的通讯卷轴，要求将其带回石爪山脉给侏儒技师加克希姆·尘链。卷轴内含制造远程爆炸物所需的奥术组件，用于对抗当地的森林砍伐...",kw={"科林·马伦","加克希姆·尘链","ng-5","远程爆炸物","通讯卷轴","石爪山脉","荆棘谷地精"},ang={["class:Mage"]="科林·马伦的工艺展示了聪明的技师如何将简单的羊皮纸附魔改造成实用的奥术中继器。",["faction:Alliance"]="这项任务展示了连接人类首都暴风城与卡利姆多对抗工业掠夺的偏远联盟前哨站之间的后勤联系。",["profession:Engineering"]="加克希姆的计划突显了侏儒工程学与法术的奇特结合，将不稳定的NG-5炸药与奥术触发器配对使用。"},sec={{t="奥术快递",b="加克希姆·尘链为破坏荆棘谷地精的破坏性作业而付出的努力，需要一些非常规的解决方案。在配制出一种名为NG-5的爆炸化合物后，这位技师发现自己缺乏一种可靠的远程引爆手段。加克希姆没有求助于粗糙的引信，而是跨越了无尽之海寻求帮助，联系了身处暴风城Mage Quarter的科林·马伦，以获得一份附魔的通讯卷轴。"},{t="远程干扰",b="在收到卷轴后，加克希姆揭示了他那古怪工程计划的全貌。这张附魔羊皮纸不仅用于长距离传递信息，其通讯魔法还能直接与不稳定的NG-5混合物相连。通过从远处魔法触发爆炸，加克希姆打算制造一场毁灭性的干扰，从而让特工们能够潜入荆棘谷地精的营地而不被察觉。"}},faq={{q="通讯卷轴有什么用？",a="虽然通讯卷轴最初是被设计作为一种传递信息的奥术工具，但加克希姆·尘链将其与不稳定的NG-5混合物结合了起来。其中的通讯魔法充当了远程引信，使他能够安全地在远处引爆炸药。",al={"为什么使用通讯卷轴","通讯卷轴有什么用","通讯卷轴的用途"}},{q="科林·马伦是谁？",a="科林·马伦是一位常驻暴风城Mage Quarter的联盟法师。他协助冒险者处理奥术事务，并制作了加克希姆在石爪山脉计划所需的附魔卷轴。",al={"科林·马伦背景","科林是谁"}},{q="为什么加克希姆·尘链要破坏荆棘谷地精？",a="荆棘谷地精正在无情地砍伐石爪山脉的原始森林。加克希姆旨在通过制造混乱、破坏他们的运作，并窃取他们的专有工程计划和通信文件，来减缓他们的森林砍伐速度。",al={"为什么攻击荆棘谷地精","加克希姆的动机","石爪山脉的荆棘谷地精"}},{q="这次运送任务会将冒险者带到哪里？",a="这次运送任务将信使从暴风城带回海上，最终抵达位于卡利姆多石爪山脉峭壁上的联盟营地。",al={"运送目的地","加克希姆在哪里","石爪山脉位置"}},{q="卷轴送达后会发生什么？",a="在拿到卷轴和NG-5之后，加克希姆准备了一个远程爆炸干扰，为特工潜入狂风峭壁的作业区，取回伐木信件和蓝图扫清了障碍。",al={"下一个任务","送达后做什么","干扰荆棘谷地精"}}},fp="26,213,17.367.0,20.305.1,41.184.0,21.157.0,55.232.0,45.132.0,43.198.1"}
P.entries["quest:1078"] = {n="完鳞归玛伦",s="“马伦的回收任务”是由暴风城Mage Quarter的科林·马伦发布的任务。听到旅行者深入卡利姆多的传闻后，这位法师委托联盟冒险者从栖息在石爪山脉焦炭谷的蛇怪身上收集结晶鳞片。马伦寻求这些稀有样本，将其研磨成粉末，作为他个人法术研究的施法材料。",h="“马伦的回收任务”是由暴风城Mage...",kw={"蛇怪鳞片","焦炭谷","科林·马伦","结晶鳞片","mage quarter","马伦的回收任务","石爪山脉","暴风城"},ang={["class:Mage"]="为同行法师采购深奥的施法材料是奥术研究的一个特征，展示了奇异的魔法野生生物如何助推新咒语的开发。",["faction:Alliance"]="这项任务展示了联盟在暴风城的势力如何维持活跃的利益和供应线，并深入到卡利姆多的荒野领地。"},sec={{t="法师的好奇施法材料",b="科林·马伦，一位居住在暴风城Mage Quarter的法师，时刻关注着游荡冒险者们的谈话。有消息传到他耳中，远方的卡利姆多石爪山脉已成为旅行者们的热门目的地，他们有的在寻找野外双足飞龙，有的在对抗难以驾驭的元素生物，还有的则在那里与荆棘谷地精进行有利可图的交易或发生冲突。与寻求财富或荣耀不同，马伦的兴趣在于该地区最严酷角落中所报道的稀有自然奇观。"},{t="焦炭谷的玻璃野兽",b="石爪山脉深处坐落着焦炭谷，这片被灰烬覆盖的广袤土地因荆棘谷地精的破坏而伤痕累累。根据马伦的研究，这片盆地过去曾栖息着一种独特的蛇怪。当采集并粉碎成细粉后，它们的鳞片可以作为他所开发的专业奥术法术的强效催化剂。由于不确定这些生物是否在焦炭谷严酷的变迁中幸存下来，马伦寄希望于无畏的探险者们采集一批新鲜的结晶鳞片，以确认该物种是否依然存在。"}},faq={{q="科林·马伦是谁？",a="科林·马伦是一位在暴风城Mage Quarter可以找到的奥术修行者。他研究深奥的法术，并经常依赖冒险旅行者从遥远的土地上获取稀有的魔法施法材料。",al={"科林·马伦","马伦的回收任务提供者","马伦 暴风城"}},{q="科林·马伦为什么需要蛇怪鳞片？",a="马伦将结晶鳞片研磨成细粉，利用其独特的矿物成分作为他所创原创法术的催化试剂。",al={"为什么需要鳞片","鳞片的用途","结晶鳞片的用途"}},{q="焦炭谷位于何处？",a="焦炭谷是一片废弃且覆盖着煤灰的盆地，位于卡利姆多大陆石爪山脉的西南方。",al={"焦炭谷在哪里","寻找焦炭谷","焦炭谷位置"}},{q="焦炭谷为何被烧焦？",a="焦炭谷遭到了荆棘谷地精的破坏，他们的行径激怒了谷中的灵魂并释放了元素生物，导致地面变黑、闷烧，并布满了顽强且扭曲的野兽。",al={"焦炭谷发生了什么","焦炭谷火灾","焦炭谷的破坏"}},{q="哪种生物会掉落该任务所需的鳞片？",a="这些鳞片是从在石爪山脉焦炭谷的闷烧荒原上游荡的各种蛇怪身上采集的。",al={"哪种蛇怪","谁掉落结晶鳞片","鳞片怪物"}},{q="为什么要派冒险者远渡重洋来做这件事？",a="马伦所需的特定结晶特性只能在焦炭谷原生的蛇怪身上找到。由于穿越无尽之海危机四伏，马伦征募了已经准备前往卡利姆多的经验丰富的旅行者。",al={"为什么去卡利姆多","为什么要从石爪山脉获取鳞片"}}},fp="20,187,25.399.0,29.451.0,21.127.0,44.105.0,34.85.0,32.210.0,52.83.0,59.180.0"}
P.entries["quest:1079"] = {n="隐秘行动：A",s="“隐秘行动——阿尔法”是由侏儒技师加克希姆·尘链在石爪山脉指挥的一项联盟渗透任务。特工们在山峰上展开行动，任务是潜入狂风峭壁的荆棘谷地精伐木场，夺取他们的专有工程图纸。获取这些蓝图能让联盟破解地精机械的结构弱点，并借用他们的伐木技术。",h="“隐秘行动——阿尔法”是由侏儒技师加克希姆·尘链在石爪山脉指挥的一项联盟渗透任务。特工们在山峰上展开行动，任务是潜入狂风峭壁的荆棘谷地精伐木场，夺取他们的专有工程图纸。获取这些蓝图能让联盟破解地精机械的结构弱点，并借用他...",kw={"阿尔法","隐秘行动","峭壁湖","工程图纸","加克希姆·尘链","伐木场","石爪山脉","荆棘谷地精","狂风峭壁"},ang={["faction:Alliance"]="在卡利姆多各处建立立足点并遏制工业掠夺，能确保联盟在对抗蚕食争议荒野的竞争势力时保持战术平衡。",["profession:Engineering"]="夺回的图纸揭示了荆棘谷地精所青睐的粗糙、高燃烧机械装置，提供了有关工业动力装置的宝贵技术见解。",["race:Gnome"]="对于侏儒技师来说，分析地精蓝图是终极奖赏：这提供了一个难得的机会，既能嘲笑地精的设计疏忽，又能窃取他们最赚钱的机械诡计。",["race:NightElf"]="荆棘谷地精在狂风峭壁的滥伐伤害了石爪山脉的古老森林，这使得对他们伐木基础设施的任何破坏都成为卡多雷的当务之急。"},sec={{t="破坏与间谍活动",b="加克希姆·尘链在狂风峭壁设立据点，持续开展隐秘行动，以干扰荆棘谷地精疯狂的伐木作业。当那些地精伐木工在峭壁湖以南砍伐原始森林时，加克希姆意识到仅仅靠肆意的破坏并不能阻止这个组织的运作。阿尔法计划并不只是为了炸毁工业设备，而是优先考虑情报收集，要求特工潜过地精伐木工和监工，直接从伐木场夺取他们的核心技术图纸。"},{t="逆向工程",b="侏儒对荆棘谷地精的兴趣不仅限于对暗夜精灵的生态同情。夺回的图纸详细记录了地精重型伐木机、机械切割机和机械运输工具的内部构造。通过研究这些蓝图，联盟工程师可以找出结构性缺陷来瓦解未来的行动，同时还能借用改进后的地精设计，以加强他们在铁炉堡的机械项目。"}},faq={{q="“隐秘行动——阿尔法”的主要目标是什么？",a="主要目标是从位于峭壁湖以南、狂风峭壁的荆棘谷地精伐木场中夺取他们的工程图纸。虽然整体隐秘行动涉及爆炸装置，但确保夺回这些蓝图才是衡量任务是否成功的唯一标准。",al={"什么是隐秘行动阿尔法","阿尔法任务目标","加克希姆想要什么"}},{q="是谁发布了“隐秘行动——阿尔法”任务？",a="该任务由加克希姆·尘链指派。他是一位驻扎在石爪山脉的联盟侏儒技师，负责监督针对地精工业行动的隐秘破坏任务。",al={"谁发布了隐秘行动阿尔法","加克希姆·尘链任务","隐秘行动任务发布者"}},{q="工程图纸在哪里？",a="荆棘谷地精工程图纸保存在狂风峭壁的作业伐木场内，该伐木场位于峭壁湖以南，周围有重重地精伐木防线。",al={"荆棘谷地精图纸在哪里","工程图纸位置","狂风峭壁伐木场图纸"}},{q="为什么加克希姆·尘链想要荆棘谷地精的蓝图？",a="加克希姆寻求这些图纸是为了研究地精伐木机的结构弱点。发现这些机械缺陷能让联盟更有效地破坏未来的机械，同时也能为联盟的设备采用实用的地精工程设计。",al={"为什么要偷荆棘谷地精图纸","加克希姆会怎么处理图纸","隐秘行动阿尔法的原因"}},{q="纯粹的破坏是这个任务的目的吗？",a="不是。加克希姆明确提醒特工，任务成功与否不取决于造成了多少破坏，而在于能否将图纸完整地从伐木场中提取出来。",al={"我要炸掉伐木场吗","我应该摧毁机器吗","任务破坏重点"}},{q="为什么联盟在这里与荆棘谷地精作战？",a="荆棘谷地精通过肆无忌惮的滥砍滥伐和工业污染掠夺石爪山脉的自然资源。联盟特工介入旨在削弱他们的工业足迹，并保护卡利姆多的战略领土。",al={"为什么要在石爪山脉对抗荆棘谷地精","联盟与荆棘谷地精的冲突","石爪山脉伐木战争"}}},fp="18,184,22.296.0,19.330.0,47.212.0,39.113.0,40.146.0,58.196.0,46.113.0,54.159.0"}
P.entries["quest:1080"] = {n="隐秘行动：B",s="“隐秘行动——B计划”是侏儒工程师加克希姆·尘链在石爪山脉组织的一项联盟任务。基于此前针对不断蚕食的荆棘谷地精的破坏行动，此次行动派遣一名特工深入狂风矿洞，引爆炸药制造骚乱，并窃取重要的行动函件。所获情报既满足了侏儒的好奇心，也服务于当地暗夜精灵哨兵部队的领土防御。",h="“隐秘行动——B计划”是侏儒工程师加克希姆·尘链在石爪山脉组织的一项联盟任务。基于此前针对不断蚕食的荆棘谷地精的破坏行动，此次行动派遣一名特工深入狂风矿洞，引爆炸药制造骚乱，并窃取重要的行动函件。所获情报既满足了侏儒的好...",kw={"隐秘行动——b计划","加克希姆·尘链","哨兵部队","石爪山脉","荆棘谷地精","风险投资公司函件","狂风峭壁","狂风矿洞"},ang={["faction:Alliance"]="将侏儒科技与暗夜精灵的领土防御相结合，巩固了联盟在卡利姆多中部的薄弱据点。",["profession:Engineering"]="该任务以加克希姆特制的隐秘行动工具包为核心，展示了精巧的烟火干扰如何达成仅靠蛮力无法完成的目标。",["race:Gnome"]="加克希姆·尘链将高威力的炸药、缜密的计划和秘密潜入相结合，代表了侏儒创造力在军事上的实际应用。",["race:NightElf"]="荆棘谷地精正在剥削这片古老的森林；支持加克希姆的秘密行动，确保了哨兵指挥官能够获得保护山脉所需的情报。"},sec={{t="深处的破坏",b="在对荆棘谷地精遍布狂风峭壁的滥砍滥伐行动进行了初步打击后，加克希姆·尘链制定了后续行动，直指其后勤核心。B计划遵循与其前身相同的基本逻辑：制造爆炸性的混乱以分散地精操作员和雇佣兵的注意力，同时让一名特工趁乱潜入矿洞搜寻书面信件。"},{t="聚焦狂风矿洞",b="狂风矿洞位于峭壁的最东端，是该公司区域性的地下基地。地精们通过挖掘岩石和采伐木材，维护着详细记录其补给线和高层指令的严格账目和通讯记录。通过潜入矿洞、安放加克希姆的特制隐秘行动工具包，并夺取风险投资公司函件，特工们在破坏公司防御的同时，也揭露了他们在卡利姆多的更深层野心。"},{t="务实的合作",b="虽然加克希姆以侏儒对烟火技术和精巧装置的典型热情来对待这项任务，但该任务对暗夜精灵具有严重的战略意义。在石爪山脉，以凯拉·影矛等指挥官为首的哨兵部队在对抗部落和无情的工业掠夺者时压力巨大。从矿洞中恢复的情报直接帮助哨兵部队预测并阻止了对他们神圣林地的亵渎。"}},faq={{q="“隐秘行动——B计划”的目标是什么？",a="目标是潜入狂风峭壁东部的狂风矿洞，使用加克希姆·尘链的工具包引爆炸药制造骚乱，并窃取概述其区域行动的风险投资公司函件。",al={"隐秘行动b计划目标","隐秘行动b计划怎么做","b计划目标"}},{q="加克希姆·尘链是谁？",a="加克希姆·尘链是驻扎在石爪山脉的一名侏儒工程师。他利用自己的机械专业知识和爆炸性发明，协助暗夜精灵哨兵部队对抗蚕食山脉的伐木和采矿企业。",al={"加克希姆·尘链","谁发布了隐秘行动b计划"}},{q="狂风矿洞位于何处？",a="狂风矿洞开凿在狂风峭壁东端的山脉中，深藏在荆棘谷地精大肆滥砍滥伐的区域内。",al={"狂风矿洞位置","矿洞在哪里"}},{q="加克希姆为什么要风险投资公司函件？",a="这些函件包含有关荆棘谷地精补给路线、领导层指令和行动计划的重要情报。找回它们有助于联盟和哨兵部队预判该公司的下一步行动，并破坏他们对森林的掠夺。",al={"为什么要窃取函件","风险投资公司函件是什么"}},{q="这项任务对暗夜精灵有什么好处？",a="暗夜精灵哨兵部队人数不足，无法监管石爪山脉的每个角落以防遭受工业破坏。加克希姆的爆炸破坏行动延缓了伐木工作，而找回的通讯记录为凯拉等哨兵指挥官提供了针对敌人的可行情报。",al={"暗夜精灵为什么关心此事","哨兵部队隐秘行动"}},{q="什么是A计划？",a="A计划是加克希姆之前的秘密行动：在峭壁湖以南的荆棘谷地精伐木场制造爆炸干扰，同时一名特工窃取了该公司的工程图纸。B计划在狂风矿洞重复了同样的战术。",al={"a计划","隐秘行动a计划","前置任务"}}},fp="17,237,22.309.0,22.407.0,23.342.0,38.193.0,24.187.0,32.102.0,44.203.0,46.193.0,20.238.0"}
P.entries["quest:1081"] = {n="泰兰德的接待",s="“泰兰德的接见”是一个联盟任务，它将冒险者从石爪山脉战火纷飞的山坡直接引向暗夜精灵的首都达纳苏斯。在协助哨兵部队稳固了他们在石爪山脉对抗荆棘谷地精的危险立足点后，阿斯特兰纳的哨兵塞恩希尔会将你引荐给月神殿中的泰兰德·语风大祭司，以获得正式的嘉奖。",h="“泰兰德的接见”是一个联盟任务，它将冒险者从石爪山脉战火纷飞的山坡直接引向暗夜精灵的首都达纳苏斯。在协助哨兵部队稳固了他们在石爪山脉对抗荆棘谷地精的危险立足点后，阿斯特兰纳的哨兵塞恩希尔会将你引荐给月神殿中的泰兰德·语风...",kw={"达纳苏斯","卡多雷","泰兰德的接见","哨兵塞恩希尔","石爪山脉","泰达希尔","temple of the moon","泰兰德·语风"},ang={["faction:Alliance"]="觐见泰兰德·语风是卡利姆多暗夜精灵与更广泛的联盟之间一座有意义的桥梁，将荒野中的小规模冲突转化为对达纳苏斯的公认服务。",["race:NightElf"]="向月神殿内的泰兰德·语风大祭司报告是一次令人自豪的归来，证明了你对保卫古代祖先土地的奉献。"},sec={{t="在石爪山脉的立足点",b="散布在石爪山脉各处的暗夜精灵哨所正面临着巨大的压力，尤其是来自蹂躏这片土地的荆棘谷地精的威胁。哨兵塞恩希尔负责协调阿斯特兰纳的防御工作，但维持这些偏远基地需要极大的韧性。确保补给线和情报畅通对于维持联盟在卡利姆多腹地的存在至关重要，因此外部的援助对驻扎在那里的哨兵来说意义重大。"},{t="觐见大祭司",b="鉴于你的协助极大地稳固了哨兵部队在该地区的控制力，哨兵塞恩希尔指示你返回泰达希尔。在达纳苏斯的月神殿中，泰兰德·语风大祭司会亲自接见你。泰兰德认可了你在卡利姆多各地不断增长的功绩，并欢迎你，不仅仅是作为一名流浪佣兵，而是作为与卡多雷并肩作战的联盟勇士。"}},faq={{q="这个任务在哪里开始？",a="该任务由灰谷阿斯特兰纳的哨兵塞恩希尔发布，在完成“给哨兵塞恩希尔的更新”后即可接取。",al={"哪里接泰兰德的接见任务","任务发布者","哨兵塞恩希尔位置"}},{q="我可以在哪里找到泰兰德·语风？",a="泰兰德·语风居住在月神殿内，该殿位于泰达希尔上暗夜精灵主城达纳苏斯的中心区。",al={"泰兰德在哪里","寻找泰兰德","月神殿位置"}},{q="为什么泰兰德想见我？",a="你在石爪山脉的努力有助于保护卡多雷在这一争议山区的立足点。哨兵塞恩希尔认为你对暗夜精灵的贡献值得他们的精神与军事领袖给予个人的嘉奖。",al={"为什么泰兰德要找我","觐见的目的"}},{q="石爪山脉有什么战略价值？",a="石爪山脉在灰谷和卡利姆多南部平原之间形成了一道崎岖的缓冲区。随着部落势力从贫瘠之地向外扩张，在此处坚守哨所对暗夜精灵监测敌方动向和守护神圣土地至关重要。",al={"为什么要关注石爪山脉","石爪山脉背景故事"}},{q="其他联盟种族也会在这里获得认可吗？",a="是的。任何协助过哨兵塞恩希尔的联盟冒险者都可以踏上前往达纳苏斯的旅程，这象征着暗夜精灵与更广泛的联盟之间日益增强的共同防御。",al={"非暗夜精灵能做这个吗","这是人类的任务吗"}},{q="觐见泰兰德之后还有后续任务吗？",a="这次觐见标志着石爪山脉为哨兵塞恩希尔进行的信使和支援任务圆满结束，它既是一个正式的总结，也提供了一个在达纳苏斯寻求进一步指令的机会。",al={"what comes next","后续任务链"}}},fp="22,235,24.328.0,32.308.0,28.113.0,37.96.0,32.208.0,56.190.0,44.162.0,49.130.0"}
P.entries["quest:1082"] = {n="向塞恩希尔报告",s="这项任务需要将来自石爪山脉峭壁的慰问消息带回暗夜精灵的哨所阿斯特兰纳。在协助凯拉·影矛和加克希姆·尘链对抗步步紧逼的荆棘谷地精之后，你需要向哨兵塔拉·塞恩希尔保证，他们的哨所依然坚固。",h="这项任务需要将来自石爪山脉峭壁的慰问消息带回暗夜精灵的哨所阿斯特兰纳。在协助凯拉·影矛和加克希姆·尘链对抗步步紧逼的荆棘谷地精之后，你需要向哨兵塔拉·塞恩希尔保证，他们的哨所依然坚固。",kw={"灰谷","阿斯特兰纳","加克希姆·尘链","凯拉·影矛","哨兵塞恩希尔","石爪山脉","哨兵塞恩希尔的更新","荆棘谷地精"},ang={["faction:Alliance"]="保持石爪山脉前哨站与灰谷据点之间的联系，有助于稳固联盟在卡利姆多中部的存在。",["race:Gnome"]="即便是哨兵塞恩希尔也勉强承认，得知加克希姆·尘链平安无事让她感到欣慰，这表明即使在传统的精灵眼中，侏儒的创造力也能赢得尊重。",["race:NightElf"]="传达凯拉幸存的消息让哨兵们确信，他们对卡利姆多边境地区的控制并没有因为工业侵蚀而崩溃。"},sec={{t="来自巅峰的公文",b="石爪山脉崎岖的山路是暗夜精灵一处孤立且脆弱的边境。由于地精的滥砍滥伐蚕食着峭壁并污染了水源，由凯拉·影矛和侏儒修理工加克希姆·尘链驻守的哨所时刻面临着威胁。一旦荆棘谷地精造成的直接危险被消除，向指挥层汇报情况就至关重要。凯拉派你向东北方向穿越边境回到灰谷，去确认他们的存活。"},{t="阿斯特兰纳的慰藉",b="在阿斯特兰纳的森林庇护所中，哨兵塔拉·塞恩希尔监视着灰谷内部的道路，同时担心着被派往更严酷地区的侦察兵。收到凯拉和她那位古怪的工程学伙伴仍然活着并积极修复土地的确认消息，这带来了一个难得的好消息。这证明了尽管兵力减少且面临多条敌对战线，与联盟盟友的合作仍能遏制生态破坏的浪潮。"}},faq={{q="哨兵塞恩希尔是谁？",a="塔拉·塞恩希尔是驻扎在灰谷主要联盟枢纽——阿斯特兰纳的一名暗夜精灵哨兵军官。她负责监控派往周围荒野和邻近地区的侦察兵和巡逻队的状态。",al={"哨兵塞恩希尔","塔拉·塞恩希尔","塞恩希尔 阿斯特兰纳"}},{q="凯拉·影矛为什么在石爪山脉？",a="凯拉·影矛被派往石爪山脉，以监控并打击荆棘谷地精进行的破坏性环境开发，并与侏儒加克希姆·尘链并肩作战，破坏地精的机器并修复土地。",al={"凯拉·影矛","凯拉的任务","为什么凯拉在石爪山脉"}},{q="加克希姆是谁？",a="加克希姆·尘链是一位联盟的侏儒工程师，与凯拉·影矛一起驻扎在石爪山脉。尽管他那吵闹的行业与传统的精灵观念格格不入，但他在破坏地精伐木机械方面的技术专长至关重要。",al={"加克希姆","加克希姆·尘链","和凯拉在一起的侏儒"}},{q="我在哪里可以找到哨兵塞恩希尔？",a="哨兵塞恩希尔驻扎在阿斯特兰纳，位于灰谷的中央道路旁，在从石爪山脉向下延伸的小路东北方向。",al={"塞恩希尔在哪里","塞恩希尔的位置","阿斯特兰纳在哪里"}},{q="向哨兵塞恩希尔复命后会发生什么？",a="向哨兵塞恩希尔报告在石爪山脉取得的成功，将开启在暗夜精灵军队中进一步发展的机会，并促成与达纳苏斯领导层更高层级的沟通。",al={"塞恩希尔之后的后续任务","接下来去哪里","泰兰德的接待"}},{q="为什么荆棘谷地精在石爪山脉是一个威胁？",a="荆棘谷地精在石爪山脉无情地砍伐神圣的树林，操作着大型伐木机械，并污染了水源，对暗夜精灵所守护的自然平衡构成了直接威胁。",al={"荆棘谷地精 石爪山脉","为什么要对抗荆棘谷地精"}}},fp="28,214,25.367.0,19.364.0,25.204.0,49.203.0,13.201.0,34.124.0,55.178.0,50.173.0"}
P.entries["quest:1083"] = {n="怒灵",s="“愤怒的灵魂”是一项由石爪山脉的凯拉·影矛提供给联盟的任务。在荆棘谷地精用火与重型机械摧毁了焦炭谷后，愤怒的火元素挣脱了束缚，占领了这片遭殃的盆地。联盟的勇士们被要求去平息这些游荡的火焰与岩石之灵，好让这片伤痕累累的土地有朝一日能在艾露恩的恩泽下痊愈。",h="“愤怒的灵魂”是一项由石爪山脉的凯拉·影矛提供给联盟的任务。在荆棘谷地精用火与重型机械摧毁了焦炭谷后，愤怒的火元素挣脱了束缚，占领了这片遭殃的盆地。联盟的勇士们被要求去平息这些游荡的火焰与岩石之灵，好让这片伤痕累累的土地...",kw={"焦炭谷","艾露恩","愤怒的灵魂","火元素","凯拉·影矛","闷烧余烬","石爪山脉","荆棘谷地精"},ang={["class:Druid"]="德鲁伊将肆虐的火元素视为对大自然平衡的灾难性破坏，在生命重返土壤之前需要积极的干预。",["class:Shaman"]="萨满了解这些元素的愤怒是对凡人矿工和伐木工鲁莽开采大地的直接、痛苦的反应。",["faction:Alliance"]="联盟通过石爪山脉的暗夜精灵哨兵来遏制由地精财团造成的混乱，并恢复山路的交通安全。",["race:NightElf"]="对于暗夜精灵来说，焦炭谷的荒废是毫无节制的工业贪婪对卡利姆多神圣荒野所造成的令人心碎的创伤。"},sec={{t="焦灼的悲剧",b="焦炭谷曾经是石爪山脉中一片郁郁葱葱的避风港，但荆棘谷地精鲁莽的贪婪将其变成了一片灰烬荒原。在砍伐木材和掠夺土地资源的驱使下，这些地精部署了纵火装置和重型机械，点燃了整个树冠。他们破坏性的干预不仅摧毁了树木，更破坏了大地之下脆弱的元素平衡。"},{t="释放的怒火",b="这次冒险对地精来说并未按计划进行。大火与深层的挖掘惊动了地底深处沉睡已久的火焰、岩石与愤怒之灵。这些愤怒的元素迅速转而攻击入侵者，将荆棘谷地精赶走，并占领了这片闷烧的陨坑。凯拉·影矛感叹道，在这些混乱的元素被消灭之前，大自然永远无法开始恢复。"}},faq={{q="谁发布了“愤怒的灵魂”这个任务？",a="凯拉·影矛，一位驻扎在石爪山脉的暗夜精灵哨兵，将这个任务交给了寻求帮助这片土地的联盟冒险者。",al={"任务发布者","在哪里接愤怒的灵魂","谁开始愤怒的灵魂"}},{q="为什么火元素会在焦炭谷肆虐？",a="荆棘谷地精使用破坏性机械对森林进行了全面砍伐和焚烧。他们这种入侵性的工业手段破坏了大地，并释放了沉睡的火焰、岩石与愤怒之灵，这些元素迅速淹没了该地区。",al={"为什么这里有元素","什么导致了火元素","焦炭谷火灵"}},{q="荆棘谷地精在焦炭谷遭遇了什么？",a="地精们引燃了森林，但他们的粗心大意释放出了比预期危险得多的元素。这些愤怒的火焰生物淹没了他们的营地，留下了废弃的营地和燃烧的残骸。",al={"荆棘谷地精的命运","地精在焦炭谷死了吗","焦炭谷的荆棘谷地精"}},{q="什么是闷烧余烬？",a="闷烧余烬是从焦炭谷被摧毁的火元素身上收集的燃烧残留物，带回给凯拉·影矛作为它们混乱的数量已被削减的实物证明。",al={"闷烧余烬背景故事","余烬有什么用","愤怒的灵魂的余烬"}},{q="焦炭谷还能恢复吗？",a="凯拉·影矛认为，只要敌对的元素还在灰烬中游荡，这片土地就没有机会感受到艾露恩的祝福或恢复生机。清除这些肆虐的灵魂是任何最终愈合过程的第一步。",al={"焦炭谷会愈合吗","治愈焦炭谷","山谷能被拯救吗"}},{q="焦炭谷位于哪里？",a="焦炭谷位于石爪山脉的西南部地区，以焦黑的土地、烧焦的树木和游荡的元素之灵为标志。",al={"焦炭谷位置","如何找到焦炭谷","元素在哪里"}}},fp="15,277,18.334.0,14.285.0,36.135.0,58.190.0,57.200.0,27.185.0,34.166.0,34.132.0"}
P.entries["quest:1084"] = {n="受伤的古树",s="“受伤的远古守护者”是凯拉·影矛在石爪山脉给予联盟玩家的一项任务。凯拉怀疑是地精的弹药使当地的森林守护者陷入疯狂，因此派遣冒险者从受腐蚀的树人身上回收弹片，以便侏儒工程师加克希姆·尘链能够分析其中的污染源。",h="“受伤的远古守护者”是凯拉·影矛在石爪山脉给予联盟玩家的一项任务。凯拉怀疑是地精的弹药使当地的森林守护者陷入疯狂，因此派遣冒险者从受腐蚀的树人身上回收弹片，以便侏儒工程师加克希姆·尘链能够分析其中的污染源。",kw={"被腐蚀的弹片","腐蚀","加克希姆·尘链","凯拉·影矛","石爪山脉","树人","荆棘谷地精","受伤的远古守护者"},ang={["class:Druid"]="树人代表了大自然的生命脉搏；提取毒害他们血肉的异物金属，是面对荆棘谷地精破坏行径时一种严酷的必要手段。",["profession:Engineering"]="从树人身上回收的被腐蚀金属，凸显了与精致的侏儒工艺相比，荆棘谷地精的弹药具有破坏性且粗制滥造的本质。",["race:Gnome"]="加克希姆·尘链敏锐的分析眼光表明，机械工艺可以用来理解和诊断不负责任的工程师所犯下的环境罪行。",["race:NightElf"]="看着远古的林地守护者在地精的工业蹂躏下腐烂和扭曲，对于任何致力于保护卡利姆多荒野的暗夜精灵来说，都是一种暴行。"},sec={{t="被腐蚀的保护者",b="石爪山脉的林地长期以来受到高大树人的守护，这些温柔而凶猛的卫士与大地的健康息息相关。当荆棘谷地精带着电锯、炸药和露天采矿作业闯入这里时，大自然进行了反击。树人成功地将入侵者驱逐出了部分山谷，但这场胜利付出了阴险的代价。这些守卫并没有回归宁静的看护工作，而是退化成了充满敌意、陷入疯狂的空壳。"},{t="侏儒的调查",b="驻扎在山中的联盟侦察兵凯拉·影矛认为，树人的衰败并非自然疾病所致。侏儒工程师加克希姆·尘链怀疑罪魁祸首在于地精在混乱撤退过程中使用的化学和机械武器库。通过从受伤的树木野兽身上撬出被腐蚀的弹片，加克希姆希望能确定荆棘谷地精的弹药是否正在积极毒害石爪山脉的远古守护者。"}},faq={{q="谁提供了“受伤的远古守护者”任务？",a="凯拉·影矛提供了这个任务。她是一名联盟特工，负责监控石爪山脉内不断升级的冲突和生态破坏。",al={"受伤的远古守护者任务提供者","谁给予受伤的远古守护者任务","凯拉·影矛任务"}},{q="为什么树人会受到腐蚀？",a="加克希姆·尘链怀疑是荆棘谷地精在混乱撤退过程中发射的有毒弹药和武器嵌入了树人体内，不断毒害并使这些森林守护者陷入疯狂。",al={"为什么树人会疯狂","石爪山脉树人腐蚀","树人腐蚀来源"}},{q="完成这项任务需要找回什么物品？",a="你需要找回一块被腐蚀的弹片，它嵌入在游荡于该地区的受伤树人的树皮和肉体之中。",al={"受伤的远古守护者物品","被腐蚀的弹片任务"}},{q="加克希姆·尘链是谁？",a="加克希姆是一位协助凯拉·影矛的联盟侏儒工程师。他利用自己的机械专业知识来检查荆棘谷地精的科技，并确定他们的武器是如何腐蚀自然生命的。",al={"加克希姆","石爪山脉的侏儒","加克希姆·尘链的作用"}},{q="荆棘谷地精在石爪山脉的势力如何？",a="荆棘谷地精是一个冷酷的地精伐木和采矿辛迪加，他们入侵石爪山脉是为了砍伐神圣的林地并掠夺矿藏，丝毫不顾及当地的生态平衡。",al={"荆棘谷地精石爪山脉","为什么地精在石爪山脉"}},{q="收集弹片能治愈树人吗？",a="不能。回收的弹片纯粹是用于让加克希姆分析毒素性质和来源的样本，而不是对受腐蚀守护者的直接治愈手段。",al={"能治愈树人吗","树人能恢复吗"}}},fp="16,240,19.381.0,21.398.0,38.138.0,30.184.0,42.115.0,24.186.0,53.184.0,46.150.0"}
P.entries["quest:1085"] = {n="守卫石爪山",s="“石爪山脉的守望”引导联盟旅行者从凯拉·影矛处前往狂风峭壁附近的营地，寻找加克希姆·尘链。面对荆棘谷地精肆无忌惮的掠夺，一对本不可能共事的搭档——一位谨慎的暗夜精灵哨兵和一位古怪的侏儒工匠——联手守护着这条山口。",h="“石爪山脉的守望”引导联盟旅行者从凯拉·影矛处前往狂风峭壁附近的营地，寻找加克希姆·尘链。面对荆棘谷地精肆无忌惮的掠夺，一对本不可能共事的搭档——一位谨慎的暗夜精灵哨兵和一位古怪的侏儒工匠——联手守护着这条山口。",kw={"工程学","加克希姆·尘链","侏儒","凯拉·影矛","暗夜精灵","石爪山脉","石爪峰","荆棘谷地精"},ang={["faction:Alliance"]="这种伙伴关系展示了更广泛的联盟精神：东部王国的专业知识与卡多雷哨兵相结合，共同遏制边境线上的各种威胁。",["profession:Engineering"]="加克希姆的任务强调了工程学在前线侦察和生态防御中的实用价值，证明了当齿轮被用于对抗毫无节制的开发时，它们同样可以服务于自然保护。",["race:Gnome"]="加克希姆·尘链自豪地代表了卡利姆多的侏儒智慧，他利用自己的存在来证明，当古老的传统受挫时，科学、工程学和魔法可以克服困难。",["race:NightElf"]="对于卡多雷哨兵来说，信任一位主张将工程学与魔法相结合的侏儒工匠需要放下巨大的自尊，这也反映了荆棘谷地精的伐木作业已经造成了多么严重的破坏。"},sec={{t="一段不可思议的联盟",b="暗夜精灵和侏儒很少有共同语言，尤其是在技术和自然世界方面。然而在石爪山脉的峭壁上，现实需求弥合了文化鸿沟。随着贪婪的荆棘谷地精在荒野中横行并砍伐古树，哨兵凯拉·影矛意识到，仅凭纯粹的武力无法战胜工业化的掠夺。将侏儒的独创性引入神圣的卡多雷领地，足以说明局势已经变得多么危急。"},{t="侏儒哲学",b="加克希姆·尘链代表了联盟较小盟友那种古怪的实用主义。虽然暗夜精灵社会在几千年前就以背弃奥术过度而闻名，但加克希姆认为，拒绝魔法和技术革新只会让自己陷入弱势。通过将炼金术、工程学与一丝奥术准则相结合，加克希姆旨在说服他的卡多雷东道主，实用科学保卫自然的效果丝毫不亚于弓箭和月刃。"}},faq={{q="为什么暗夜精灵和侏儒会在这里合作？",a="荆棘谷地精在石爪山脉破坏性的森林砍伐和资源开采极为严重，以至于凯拉·影矛不得不接受外援。加克希姆带来了暗夜精灵通常所缺乏的工程学和炼金术专业知识，为对抗现代工业机械提供了技术支持。",al={"为什么加克希姆和凯拉在一起","凯拉和加克希姆","侏儒暗夜精灵联盟"}},{q="加克希姆·尘链是谁？",a="加克希姆是一位富有冒险精神的侏儒工程师兼工匠，驻扎在狂风峭壁附近的营地。他坚定地认为暗夜精灵对奥术魔法的严格排斥使他们处于不利地位，因此他试图证明结合工程学、炼金术和受控魔法可以解决最严峻的威胁。",al={"加克希姆·尘链背景","加克希姆是谁","石爪峰的侏儒"}},{q="凯拉·影矛是谁？",a="凯拉·影矛是一位暗夜精灵哨兵，负责维持石爪山脉的警戒与防御。她担任地区指挥官，协调针对荆棘谷地精的抵抗行动。",al={"凯拉·影矛","凯拉是谁"}},{q="荆棘谷地精在石爪山脉构成了什么威胁？",a="荆棘谷地精是一个毫无道德底线的商业联合组织，为了获取快速商业利润，他们在整个石爪山脉砍伐神圣森林，操作破坏性的钻探设备，并污染着纯净的土地。",al={"石爪山脉荆棘谷地精","为什么要对抗荆棘谷地精"}},{q="凯拉提到的塔拉是谁？",a="塔拉是塔拉·塞尼斯哨兵，她是凯拉在阿斯特兰纳的朋友，派你来查看凯拉的情况。凯拉为塔拉在哨兵部队中表现出色，以至于能派遣冒险者执行任务而感到自豪。",al={"石爪山脉塔拉","送你回塔拉处"}},{q="这个任务接下来会导向何处？",a="与加克希姆·尘链交谈后，他会提供任务“侏儒的喘息”，征求你的帮助以在狂风峭壁阻击荆棘谷地精的伐木工，好让他有时间规划他的下一项发明。",al={"石爪山脉的守望后续任务","加克希姆任务后续"}}},fp="22,271,20.405.0,18.360.0,54.285.0,24.273.0,25.184.0,56.189.0,32.188.0,31.187.0"}
P.entries["quest:1086"] = {n="地精空港",s="受雷霆崖的药剂师扎玛之托，部落的冒险者们正在石爪山脉上方搜寻一处隐蔽的荆棘谷地精着陆点。特工们携带剧毒粮草潜入地精伐木作业的核心地带，意图毒杀他们的航空运输枢纽。这项任务直接打击了该集团的通讯，同时也突显了皇家药剂师协会那冷酷无情的行事手段。",h="受雷霆崖的药剂师扎玛之托，部落的冒险者们正在石爪山脉上方搜寻一处隐蔽的荆棘谷地精着陆点。特工们携带剧毒粮草潜入地精伐木作业的核心地带，意图毒杀他们的航空运输枢纽。这项任务直接打击了该集团的通讯，同时也突显了皇家药剂师协会...",kw={"机场","药剂师扎玛","直升机停机坪","峭壁湖","飞行器","石爪山脉","雷霆崖","剧毒粮草","荆棘谷地精"},ang={["faction:Horde"]="确保石爪山脉的安全需要切断荆棘谷地精的外援，而打击他们的空中交通是至关重要的后勤一击。",["profession:Engineering"]="地精的直升机停机坪展示了粗犷、实用的工程设计，正是这些设计支撑着荆棘谷地精在崎岖山脉间的快速运输。",["race:Tauren"]="虽然你们的人民憎恶荆棘谷地精对石爪山脉的破坏，但在被遗忘者药剂师的建议下使用化学毒素，考验着大地母亲的崇敬与残酷战场实用主义之间的平衡。",["race:Undead"]="对于被遗忘者而言，在石爪山脉部署剧毒粮草是例行公事，这向卡利姆多证明了幽暗城的炼金天赋可以解决蛮力无法解决的问题。"},sec={{t="无声的投递",b="当牛头人试图保护石爪山脉免遭滥砍滥伐和掠夺性机械的破坏时，被遗忘者却带来了截然不同的理念。药剂师扎玛准备了药剂师林度恩研制的毒素，以此扰乱荆棘谷地精的后勤补给。她没有直接攻击步兵或伐木工，而是将目标对准了该集团与外界联系的枢纽：据传是用于在石爪山脉与遥远的企业办公室之间转运轻型货物和信件的直升机停机坪。"},{t="峭壁湖的天空港",b="隐藏在峭壁湖地区大水车南侧高处的是荆棘谷地精的直升机停机坪，它高踞于烟尘与砍伐的木材之上。它规模不大，仅供轻型飞行器而非大型飞艇使用。直接在停机坪上引爆剧毒粮草，可以确保任何操作机器的飞行员、信使或机械师在发出警报前就被毒雾笼罩。"},{t="被遗忘者的实用主义",b="在收到轰炸的消息后，药剂师扎玛对使用化学武器对付地精一事毫无愧疚。在她眼中，荆棘谷地精对土地所做的一切，遭受更严重的惩罚也是罪有应得。更重要的是，她向部落传授了幽暗城信条中至关重要的一课：为了最终的胜利，永远不要畏惧黑暗的道路。"}},faq={{q="飞行器机场在哪里？",a="荆棘谷地精的直升机停机坪位于石爪山脉的峭壁湖地区。你会发现那座高架木制结构位于巨大的工业水车南侧，俯瞰着湖泊的南岸弯道。",al={"机场在哪里","直升机停机坪位置","天空港在哪里","荆棘谷地精着陆点"}},{q="为什么药剂师扎玛要给这个地点下毒？",a="扎玛想要切断荆棘谷地精在石爪山脉与其偏远总部之间的通讯和轻型补给线。通过污染直升机停机坪，她希望这种毒素能使地精飞行机组瘫痪，并有可能搭顺风车传回给他们的企业领导层。",al={"为什么要炸毁机场","为什么使用剧毒粮草","扎玛的动机"}},{q="药剂师扎玛是谁？",a="药剂师扎玛是驻扎在雷霆崖下方预见之池的皇家药剂师协会使者。她负责研究卡利姆多的动植物，同时代表被遗忘者和部落开发炼金武器。",al={"扎玛的身份","扎玛是谁","雷霆崖里的亡灵"}},{q="为什么部落在这里使用化学武器？",a="被遗忘者的战斗风格充满了务实的冷酷。尽管他们的牛头人盟友更倾向于精神疗法和对大地的直接保卫，但扎玛认为荆棘谷地精那毁灭性的贪婪应当受到毫不留情的手段制裁，她认为比起感伤的克制，胜利才是最重要的。",al={"部落使用瘟疫","为什么要毒杀地精","这是瘟疫吗"}},{q="荆棘谷地精在这里使用什么种类的飞行器？",a="该平台的大小适宜小型地精飞行器和旋翼机，而非全尺寸的飞艇。这些机动灵活的飞行器使该集团能够快速绕过石爪山脉崎岖的山道，运输高优先级的信件和货物。",al={"荆棘谷地精的直升机","什么样的飞行器","石爪山脉的地精飞行器"}},{q="部署剧毒粮草后会发生什么？",a="一旦你在停机坪顶部释放剧毒粮草，你必须在毒雾笼罩你之前撤离。扎玛认为这次部署是成功的，并预计这种毒素将严重扰乱地精的后勤。",al={"剧毒粮草的后果","放置剧毒粮草后"}}},fp="26,206,17.417.0,19.336.0,19.270.1,44.199.0,50.244.0,24.225.0,45.270.0,56.198.0,42.176.1"}
P.entries["quest:1087"] = {n="塞纳留斯的遗产",s="“塞纳留斯的遗产”是布莱林·火拳在石爪山脉的烈日石居附近发布的一项部落任务。这位血精灵法师对暗夜精灵和塞纳留斯之子所维持的自然结界感到沮丧，试图在石爪峰消灭他们的人数，以恢复奥术能量的原始流动。对于部落来说，打击塞纳里奥的守卫者同时也能削弱联盟在该地区的存在。",h="“塞纳留斯的遗产”是布莱林·火拳在石爪山脉的烈日石居附近发布的一项部落任务。这位血精灵法师对暗夜精灵和塞纳留斯之子所维持的自然结界感到沮丧，试图在石爪峰消灭他们的人数，以恢复奥术能量的原始流动。对于部落来说，打击塞纳里奥...",kw={"布莱林·火拳","塞纳里奥植物学家","塞纳留斯的遗产","塞纳留斯之女","加德纳尔","奥丹努斯","塞纳留斯之子","石爪峰","烈日石居"},ang={["class:Druid"]="对于牛头人德鲁伊来说，屠杀塞纳留斯的后裔和塞纳里奥议会的植物学家是一种令人不安且极具分歧的行为，凸显了派系忠诚与神圣自然之道之间悲剧性的摩擦。",["class:Mage"]="布莱林的抱怨引起了奥术实践者的共鸣，他们认识到古老的卡多雷结界与自由流动的地脉能量之间的摩擦，即使她鲁莽的狂热近乎偏执。",["faction:Horde"]="石爪峰代表了联盟和卡多雷在该山脉中最强大的堡垒；清除其守卫者对于保卫烈日石居和巨木谷至关重要。"},sec={{t="被压制的能量流",b="布莱林·火拳居住在烈日石居附近的山丘上，对石爪山脉的自然环境感到愤恨。据她说，塞纳里奥议会的德鲁伊和半神塞纳留斯的后裔积极地抑制并扼杀了这片土地上的奥术能量流。她形容在这里引导力量的过程就像是用漏水的桶打水一样，她渴望剥除他们的自然防御，以便原始的魔法能量能够再次畅通无阻地涌动。"},{t="对石爪峰的突袭",b="为了削弱这种青翠的束缚，布莱林征召部落勇士前往北部的石爪峰。在那里，在古老的卡多雷树林和寺庙场地周围，塞纳里奥植物学家与骄傲的塞纳留斯之子和塞纳留斯之女共同巡逻。击倒这些守卫者有两个目的：它拆除了压制布莱林法术的结界，并对威胁部落在山区立足点的暗夜精灵飞地进行了沉重打击。"},{t="与暗影议会的联系",b="虽然布莱林将她的不满表现为魔法便利性的问题，但她真正的忠诚却在更黑暗的角落。她渴望回到加德纳尔，那是暗影议会在北面费伍德森林隐藏的腐化据点，但她提到她的神秘主人禁止她返回，直到她在石爪山脉的工作完成。部落出于领土的权宜之计帮助她，通常并没有意识到那个操纵她的邪恶邪教。"}},faq={{q="布莱林·火拳是谁？",a="布莱林·火拳是一位驻扎在烈日石居附近岩石地带的血精灵施法者。虽然她接受部落的援助来清除石爪山脉的暗夜精灵，但她服务于一位位于费伍德森林加德纳尔的隐秘主人。",al={"布莱林·火拳背景故事","任务发布者是谁","布莱林"}},{q="布莱林为什么想杀死塞纳留斯的后裔？",a="她声称卡多雷植物学家和塞纳留斯的后裔所施行的德鲁伊魔法积极地抑制了原始奥术能量在整个山脉的流动。消灭他们会削弱树林的结界，并允许魔法自由地流入她的掌控之中。",al={"为什么要杀塞纳留斯之子","为什么讨厌塞纳里奥植物学家","布莱林为什么讨厌他们"}},{q="目标位于何处？",a="塞纳留斯之子、塞纳留斯之女和塞纳里奥植物学家集中在远北的石爪峰，守护着暗夜精灵维护的祖先遗迹、树林和月亮井。",al={"塞纳留斯之子在哪里","石爪峰怪物位置","去哪里找塞纳里奥植物学家"}},{q="布莱林提到的加德纳尔是什么？",a="加德纳尔是位于费伍德森林深处的一个峡谷和洞穴群，受到燃烧军团的严重腐化，目前是暗影议会在卡利姆多的中央行动基地。",al={"什么是加德纳尔","布莱林的主人加德纳尔","加德纳尔的联系"}},{q="为什么部落愿意帮助布莱林攻击塞纳里奥的守卫者？",a="石爪峰的暗夜精灵与联盟直接结盟，并阻碍部落在整个石爪山脉的扩张。削弱他们的树林可以确保部落在该地区的统治，而不论布莱林的个人动机如何。",al={"部落为什么要杀塞纳里奥议会","部落在石爪峰的冲突"}},{q="完成“塞纳留斯的遗产”后会发生什么？",a="布莱林的下一个任务目标是奥丹努斯，他是灰谷林中树居的树林守护者。他可以在那里的大树顶上找到。",al={"塞纳留斯的遗产之后的任务","任务链的下一步是什么","奥丹努斯任务线"}}},fx={["9bca5a54"]={q="在塞纳留斯的遗产中，你受命杀死谁？",a="布莱林派你去对付塞纳留斯之子与塞纳留斯之女，以及驻扎在石爪峰顶的塞纳里奥植物学家。这些守护者、树妖和暗夜精灵看护者照料着神圣的林地，辛勤培育土地，保护该地区免遭布莱林企图利用的混乱燃烧奥术魔法侵袭。",al={"塞纳留斯的遗产任务目标","塞纳留斯的遗产要杀谁","塞纳留斯之子与塞纳留斯之女是什么人"}}},fp="16,401,16.468.0,27.454.0,26.429.1,24.243.1,52.256.0,30.204.0,41.194.0,67.242.0,47.142.1"}
P.entries["quest:1088"] = {n="奥达努斯",s="布莱林·火拳在Sunrock Retreat运用她的奥术视觉来追踪Keeper Ordanus，他是Cenarius的一位长子，逃离了石爪峰。她认为他的人民亵渎了古老的Highborne遗迹，于是派遣Horde勇士跨越边境进入灰谷去取他的首级。",h="布莱林·火拳在Sunrock Retreat运用她的奥术视觉来追踪Keeper...",kw={"灰谷","布莱林·火拳","cenarius","highborne","ordanus","林中树居","石爪山脉","sunrock retreat"},ang={["class:Druid"]="Horde德鲁伊在这个任务中面临着严峻的困境，为了完成一个血精灵的古老宿怨，要夺走Cenarius亲生儿子的生命。",["class:Mage"]="布莱林·火拳代表了Highborne那不可动摇的奥术自豪感，主张奥术凌驾于Cenarion自然哲学之上。",["faction:Horde"]="击倒Cenarius的一位长子削弱了暗夜精灵在灰谷-石爪山脉边境的权威，有助于Horde扩张到有争议的林地中。"},sec={{t="因古老宿怨而起的狩猎",b="布莱林·火拳奉主人之命来到石爪山脉，以夺回艾萨拉古老神庙的神圣遗迹。她发现暗夜精灵已经占领了山峰，将她Highborne祖先的遗物视为需要被控制的蛮荒之物。她的主要目标，Keeper Ordanus，在她能包围他之前就逃走了，溜过了边境进入了灰谷。布莱林利用她的奥术视觉在林中树居的一处木制避难所高处探测到了他的藏身之处，并征募了Horde去完成这场狩猎。"},{t="森林之神的后裔",b="Ordanus被视为Cenarius最年长的儿子之一，与卡利姆多的野性魔法有着深厚的联系。暗夜精灵守卫将他从石爪峰转移到林中树居，试图保护他免受侵蚀神圣树林的奥术力量的侵害。在忠诚的Cenarion Vindicators和被召唤的树人保卫下，这位守护者既代表了森林半神的古老权威，也是布莱林复仇道路上的活体障碍。"},{t="Highborne的复仇",b="对于布莱林·火拳来说，夺取Ordanus的首级不仅是战术上的需要，更是极其私人的恩怨。她公开回忆起几个世纪前就认识他，记得Cenarius的后代曾以何种傲慢的态度俯视Highborne及其对奥术的掌握。砍下他的头颅可以报复古老的轻蔑，并为她主人在卡利姆多荒野中更深层的计划扫清道路。"}},faq={{q="谁是Keeper Ordanus？",a="Ordanus是一位林地守护者，也是半神Cenarius最年长的儿子之一。他最初驻扎在石爪峰附近，随后逃入灰谷以躲避Highborne的复仇。",al={"ordanus背景故事","谁是ordanus","谁是keeper ordanus"}},{q="在哪里可以找到Keeper Ordanus？",a="Ordanus居住在林中树居的一座巨大空心树结构顶部，位于穿过灰谷中部道路的沿途。",al={"ordanus位置","ordanus在哪里","林中树居树屋"}},{q="为什么布莱林·火拳想要Ordanus死？",a="布莱林认为暗夜精灵在石爪山脉的存在是对古老Highborne神庙遗迹的亵渎。她对Ordanus还怀有长期的个人仇恨，记得他在过去的岁月里对他的人民表现出的傲慢和轻视。",al={"为什么要杀ordanus","布莱林宿怨","为什么布莱林想要ordanus死"}},{q="布莱林·火拳的主人是谁？",a="布莱林提到她侍奉一位主人，该主人指示她前往石爪峰收复艾萨拉的古老神庙遗迹，但她对主人的真实身份守口如瓶。",al={"布莱林的主人","谁派遣了布莱林"}},{q="这场冲突如何符合Horde在石爪山脉的现状？",a="驻扎在Sunrock Retreat的Horde部队经常为了石爪山脉和灰谷的领土与资源，与暗夜精灵哨兵和Cenarion保护者发生冲突，这使得布莱林针对Cenarion领袖的打击具有互利性。",al={"为什么horde帮助布莱林","horde在石爪山脉的动机"}},{q="Ordanus被击杀后会发生什么？",a="一旦Ordanus死亡，布莱林会奖励勇士并指引他们前往大兽穴，进一步深入挖掘石爪山脉周围的威胁。",al={"ordanus之后做什么","ordanus之后的任务","接下来是大兽穴"}}},fp="7,269,32.483.0,27.413.0,19.333.1,22.175.0,34.130.0,44.209.0,33.138.0,67.222.0,36.119.1"}
P.entries["quest:1089"] = {n="大兽穴",s="大兽穴是部落针对盘踞在石爪峰的暗夜精灵德鲁伊所进行的一次渗透行动的高潮。在血精灵特工布莱林·火拳的指挥下，勇士们深入猛禽洞穴的地下古墓室，破解多重安全系统，并掠夺德鲁伊隐藏的圣物。",h="大兽穴是部落针对盘踞在石爪峰的暗夜精灵德鲁伊所进行的一次渗透行动的高潮。在血精灵特工布莱林·火拳的指挥下，勇士们深入猛禽洞穴的地下古墓室，破解多重安全系统，并掠夺德鲁伊隐藏的圣物。",kw={"古墓钥匙","布莱林·火拳","塞纳留斯的遗产","利爪钥匙","守门人的钥匙","欧尔达努斯","沉睡者的钥匙","石爪峰","猛禽洞穴","猛禽洞穴宝库"},ang={["class:Druid"]="部落的牛头人德鲁伊在这里面临着一种苦涩的讽刺，他们转动着那些基于传统古墓建筑——以沉睡者、利爪和古墓命名——设计的钥匙，去对抗同为塞纳里奥的守护者。",["class:Rogue"]="在昏暗的古墓大厅中穿梭，从隐藏的灯具和火炬支架上取下钥匙，需要敏锐的渗透能力和诡计。",["faction:Horde"]="突袭猛禽洞穴击碎了暗夜精灵在石爪峰顶的防御脊梁，确保了山路的安全，并为部落夺取了强大的魔法圣物。",["race:NightElf"]="对猛禽洞穴的亵渎标志着对神圣古墓圣所的严重侵犯，塞纳里奥守护者们古老的睡眠被打断，他们受结界保护的圣物也被掠夺一空。"},sec={{t="地下秘密",b="猛禽洞穴坐落在石爪山脉的最高处，是暗夜精灵德鲁伊的地下堡垒。这些古墓大厅深深开凿在坚固的岩石之中，旨在保护在此冥想的守护者，并将神圣的宝藏隐藏起来，避开窥探的目光。布莱林·火拳深知这里面藏着的东西具有重大的战略和奥术价值，她审问了一名被俘的德鲁伊，撬开了他们防御体系的秘密。"},{t="层层锁扣",b="为了保护他们最强大的圣物，德鲁伊们设计了一种错综复杂的机制，而不是仅仅信任一扇门。在古墓室的入口处，藏在盏不起眼的灯里的是守门人的钥匙。这把初始的钥匙可以打开位于综合设施深处的三处分散的缓存——从而获得沉睡者的钥匙、利爪钥匙和古墓钥匙。只有当这三块雕刻的石头在中央宝库中全部转动时，德鲁伊的封印才会解除，将他们古老的物品拱手让给部落。"}},faq={{q="什么是猛禽洞穴？",a="猛禽洞穴是一个开凿在石爪峰高处的暗夜精灵地下古墓群。它既是休息中的德鲁伊进行冥想的圣所，也是他们存放神圣圣物的安全仓库。",al={"猛禽洞穴在哪里","什么是大兽穴","石爪山脉古墓洞穴"}},{q="是谁下令渗透猛禽洞穴的？",a="布莱林·火拳，一名在石爪山脉与部落并肩作战的辛多雷特工，策划了这次突袭。在从一名不幸被俘的德鲁伊口中榨取了关键情报后，她指引部落特工绕过圣所的结界，洗劫了其中的宝库。",al={"谁发布大兽穴任务","布莱林·火拳的目的","谁派我前往大兽穴"}},{q="洞穴里的钥匙是如何运作的？",a="一把初始的守门人的钥匙被藏在入口附近的一盏灯里。那把钥匙可以打开古墓内三处分散的缓存，从中获得沉睡者的钥匙、利爪钥匙和古墓钥匙。当它们一起插入雕刻着石头的宝库时，结界就会消散。",al={"如何打开猛禽洞穴宝库","守门人的钥匙用法","石爪山脉的三把钥匙"}},{q="为什么要针对石爪峰的德鲁伊？",a="布莱林·火拳想要恢复该地区的魔法流动，她指责石爪峰的德鲁伊和塞纳留斯的后代阻碍了魔法的流动。她杀死了他们，以及他们的领袖欧尔达努斯（她声称曾认识此人），然后派你去搜刮大兽穴中的强大物品。",al={"为什么要攻击石爪山脉的德鲁伊","部落杀死欧尔达努斯的理由","为什么要洗劫大兽穴"}},{q="猛禽洞穴的宝库里有什么？",a="宝库里装载着暗夜精灵德鲁伊收集的强大圣物和宝藏。这些物品被封印在层层结界之下，在布莱林强行破解安全序列之前，它们一直处于安全状态，未受外来者的侵扰。",al={"猛禽洞穴宝库战利品背景","宝库里有什么","德鲁伊隐藏了什么"}},{q="在这个任务之前发生了什么？",a="在潜入大兽穴之前，部落的冒险者们被派往塞纳留斯的遗产调查暗夜精灵的动向，并刺杀守护者欧尔达努斯，以瓦解守军的指挥系统。",al={"大兽穴任务链","什么引导至大兽穴","大兽穴的前置条件"}}},fp="7,212,20.321.0,17.349.1,22.151.0,45.230.0,36.236.0,53.288.0,35.182.0,38.185.0"}
P.entries["quest:109"] = {n="向格里安·斯托曼报到",s="这一指令引导离开艾尔文森林的经验丰富的冒险者前往西部荒野受困的前线。由于王室疏于管理外围农场，当地守卫只能依靠愿意帮忙的雇佣兵，在哨兵岭集合并听从格里安·斯托曼的指挥。",h="这一指令引导离开艾尔文森林的经验丰富的冒险者前往西部荒野受困的前线。由于王室疏于管理外围农场，当地守卫只能依靠愿意帮忙的雇佣兵，在哨兵岭集合并听从格里安·斯托曼的指挥。",kw={"迪菲亚兄弟会","艾尔文森林","格里安·斯托曼","治安官杜汉","人民民兵","哨兵岭","暴风城","西部荒野"},ang={["class:Warrior"]="格里安·斯托曼最看重的是久经考验的军事纪律，这使得经验丰富的一线战士成为兵力匮乏的人民民兵不可或缺的资产。",["faction:Alliance"]="这项任务展现了正在考验联盟的内部压力：当王室法庭在暴风城争论政治问题时，普通公民为了生存不得不组织自己的民兵。",["race:Human"]="对于王国的平民来说，走进西部荒野突显了暴风城安全的石板街道与外围农场严酷、被忽视的现实之间的巨大鸿沟。"},sec={{t="河对岸的请求",b="无论是驻扎在艾尔文森林边界的卫兵，还是逃亡向西的绝望农夫，所传达的口信都是一样的：河对岸需要熟练的战士。随着强盗、豺狼人和充满敌意的收割傀儡蹂躏这片曾经的王国粮仓，西部荒野正迅速陷入混乱。由于没有正式的皇家军队响应号召，那些渴望保卫王国的人只能求助于当地的志愿者。"},{t="哨兵岭与民兵",b="顺着道路进入西部荒野后，新兵们会发现格里安·斯托曼正驻扎在哨兵岭顶部的加固石塔内。斯托曼领导着人民民兵，这是一个由当地农夫、退伍老兵和雇佣兵组成的非官方组织，他们是为了直接应对王室的不作为而自发集结的。见到他，标志着冒险者正式投身于这场艰苦的游击战，为了保护农田不至于完全陷入无法无天的境地。"}},faq={{q="格里安·斯托曼是谁？",a="格里安·斯托曼是一位老练的战士，也是人民民兵的指挥官。他驻扎在哨兵岭顶部的塔内，负责组织防御工作，并招募愿意作战的人员来保护西部荒野，使其免受威胁当地农夫的强盗和野兽的侵害。",al={"格里安·斯托曼","斯托曼是谁","哨兵岭领导者"}},{q="为什么需要人民民兵？",a="暴风城的军队已将重心撤回到了首都，使得像西部荒野这样的外围领地几乎得不到任何来自王室的支援。居民们组建了人民民兵作为自卫力量，以抵御强盗、失控的收割机器人和四处掠夺的河爪豺狼人。",al={"为何需要民兵","为何没有暴风城军队","为何西部荒野被遗弃"}},{q="哨兵岭在哪里？",a="哨兵岭位于西部荒野的中心地带，沿着主路即可到达。山顶上有一座坚固的石质瞭望塔和一个加固的营地，人民民兵就在那里集合。",al={"找到哨兵岭","哨兵岭位置","去哪里找斯托曼"}},{q="是谁指派冒险者执行这个任务？",a="当冒险者证明了自己的能力后，会有几位相关人士提供这条指引，包括闪金镇的治安官杜汉，像卫兵托马斯和瑞尼尔副队长这样的边境守卫，或者像农夫法布隆和农夫萨丁这样的流离失所的当地人。",al={"谁提供任务","任务发布者","向格里安报到任务发布者"}},{q="向格里安报到后会发生什么？",a="一旦你向格里安·斯托曼报到，他就会将你的战斗力直接编入人民民兵的队伍，首先分配给你的任务就是清剿威胁该地区的迪菲亚强盗和豺狼人。",al={"接下来做什么","斯托曼后续任务","民兵任务链"}},{q="西部荒野在名义上还属于联盟吗？",a="是的，西部荒野是属于暴风城管辖下的联盟领土。然而，当地的不满情绪日益高涨，因为王室的皇家卫戍部队疏忽了该地区，使其生存只能掌握在武装平民的手中。",al={"西部荒野是否属于联盟","暴风城是否拥有西部荒野"}}},fp="27,215,23.217.0,29.264.0,25.209.0,35.263.0,31.162.0,41.180.0,38.176.0,51.175.0"}
P.entries["quest:1090"] = {n="格雷苏的要求",s="在石爪山脉的荆棘谷地精挖掘场，一个被排挤的名为匹兹尼克的地精正密谋揭发他的新老板格伦佐。冒险者们通过在匹兹尼克挖掘一种奇特的金绿色矿石时保卫他，从而帮助揭开了该公司激进挖掘背后的利润丰厚的秘密。",h="在石爪山脉的荆棘谷地精挖掘场，一个被排挤的名为匹兹尼克的地精正密谋揭发他的新老板格伦佐。冒险者们通过在匹兹尼克挖掘一种奇特的金绿色矿石时保卫他，从而帮助揭开了该公司激进挖掘背后的利润丰厚的秘密。",kw={"格伦佐","金绿色矿石","神秘的矿石","匹兹尼克","石爪山脉","荆棘谷地精","狂风峭壁","吉兹·菲兹克斯"},ang={["faction:Horde"]="荆棘谷地精鲁莽的入侵式开采破坏了石爪山脉的自然景观，使得任何旨在监控、干扰或利用其行动的努力对附近的部落军队都很有价值。",["profession:Mining"]="荆棘谷地精矿工在石爪山脉发现的奇异金绿色矿石与传统的铁矿或锡矿不符，引起了任何对稀有矿物感兴趣的勘探者的好奇。"},sec={{t="峭壁上的公司背叛",b="荆棘谷地精在石爪山脉的大规模行动依赖于残酷的竞争，晋升是靠冷酷无情而非忠诚赢得的。匹兹尼克曾享受着挖掘场二把手的地位，直到格伦佐夺取了权力，赶走了主管吉兹·菲兹克斯，并将匹兹尼克降职为在泥土中挥舞镐头的劳工。匹兹尼克没有选择离开，而是在吉兹的指示下留下来作为线人，监视格伦佐的一举一动，等待时机反击他这位奸诈的新上司。"},{t="发掘金绿色矿脉",b="格伦佐突然夺权是出于对石爪山脉岩石中穿过的一种神秘金绿色矿石的痴迷。认为这种矿石具有非凡的商业价值，格伦佐下令矿工从地下大量开采。匹兹尼克怀疑吉兹·菲兹克斯神秘的新雇主会为关于此项风险投资的情报支付丰厚的报酬，于是冒着被发现的风险挖掘出一份原始样本，同时依靠盟友来抵御攻击性的挖掘者、害虫和监视行动的监工。"}},faq={{q="谁是匹兹尼克？",a="匹兹尼克是石爪山脉狂风峭壁行动中的一名地精劳工。他曾是吉兹·菲兹克斯手下挖掘场第二重要的经理，但在格伦佐夺取控制权后，匹兹尼克被降职为从事矿山苦力的普通工人。",al={"匹兹尼克","地精矿工是谁","石爪山脉的匹兹尼克"}},{q="为什么匹兹尼克要秘密开采这种矿石？",a="匹兹尼克正在秘密收集一种奇特的金绿色矿石样本，格伦佐已下令大量开采这种矿石。他的前任老板吉兹·菲兹克斯承诺，他的新雇主会为格伦佐正在进行的任何有价值行动的情报支付丰厚的报酬。",al={"为什么要开采矿石","神秘的矿石","金绿色矿石"}},{q="谁是格伦佐？",a="格伦佐是冷酷的荆棘谷地精主管，他通过解雇吉兹·菲兹克斯夺取了石爪山脉挖掘场的控制权。他立即将公司资源转向激进地挖掘遍布峭壁的一种不为人知、非常有价值的金绿色矿石。",al={"格伦佐","谁是格伦佐","格伦佐荆棘谷地精"}},{q="吉兹·菲兹克斯现在为谁工作？",a="在被格伦佐解雇后，吉兹·菲兹克斯与新的支持者结盟，他们对监控荆棘谷地精在该地区的活动很感兴趣。他雇佣了像匹兹尼克这样的行动人员和线人来破坏格伦佐的计划，并揭开荆棘谷地精正在发掘的秘密。",al={"吉兹的新老板","谁雇佣了吉兹","吉兹的雇主"}},{q="匹兹尼克挖掘时会受到什么攻击？",a="荆棘谷地精工人在挖掘过程中会发动攻击，包括狂风隧道鼠、狂风害虫、挖掘者、地卜师、石匠和监工。",al={"匹兹尼克受伏击","谁在攻击匹兹尼克","狂风峭壁的巡逻队"}},{q="矿石样本开采出来后会发生什么？",a="一旦匹兹尼克成功提取出矿石样本，他就会将其交给保护者，直接递交给吉兹·菲兹克斯，希望这能提供挫败格伦佐野心计划所需的筹码。",al={"把矿石带到哪里","如何处理样本"}}},fp="16,206,30.422.0,30.447.0,14.186.0,39.225.0,15.218.0,34.233.0,34.150.0,38.172.0"}
P.entries["quest:1091"] = {n="向凯拉回报",s="“凯拉的最新情况”是联盟在石爪山脉的一项调度任务，携带着前线行动人员之间被截获的信件。侏儒法师加克希姆·尘链将冒险者派回凯拉·影矛身边，送交截获的荆棘谷地精信件。这些情报有助于暗夜精灵哨兵追踪这个地精卡特尔在神圣土地上进行的破坏性扩张。",h="“凯拉的最新情况”是联盟在石爪山脉的一项调度任务，携带着前线行动人员之间被截获的信件。侏儒法师加克希姆·尘链将冒险者派回凯拉·影矛身边，送交截获的荆棘谷地精信件。这些情报有助于暗夜精灵哨兵追踪这个地精卡特尔在神圣土地上进...",kw={"加克希姆·尘链","凯拉·影矛","凯拉的最新情况","信件","哨兵","石爪峰","荆棘谷地精"},ang={["faction:Alliance"]="递交截获的荆棘谷地精通讯，加强了联盟在石爪山脉应对企业掠夺的脆弱立足点。",["race:Gnome"]="加克希姆·尘链自豪地代表了侏儒的奥术独创性，他确保他的暗夜精灵盟友们能认识到侏儒魔法不可或缺的价值。",["race:NightElf"]="每一份针对荆棘谷地精收集到的情报，都有助于哨兵保护卡利姆多伤痕累累的荒野免受工业玷污。"},sec={{t="山中的信使",b="在协助侏儒法师加克希姆·尘链揭露荆棘谷地精的动向后，他汇编了缴获的信件，详细说明了该卡特尔的行动。加克希姆可不想错过邀功的机会，他直接让玩家回到驻扎在狂风峭壁附近的暗夜精灵哨兵协调员凯拉·影矛那里。他还特意提醒传令兵要提到他的魔法能力是如何让这次调查取得成功的。"},{t="Eyes of the Sentinels",b="驻扎在石爪的哨兵们正怀着日益增长的忧虑注视着这些峭壁。虽然部落军队在争夺下方的小径，但荆棘谷地精的滥砍滥伐和采矿设备构成了迫在眉睫的生态和战术威胁。加克希姆缴获的信件为凯拉提供了关于该卡特尔内部通讯的重要见解，加强了联盟沿山脊的防御规划。"}},faq={{q="凯拉·影矛是谁？",a="凯拉·影矛是一位效忠于联盟的暗夜精灵哨兵军官，驻扎在狂风峭壁附近的一个营地。她负责监督针对入侵的部落和山中地精采矿公司破坏性创举的侦察与防御工作。",al={"凯拉·影矛","凯拉是谁","凯拉 石爪"}},{q="加克希姆·尘链是谁？",a="加克希姆·尘链是一位充满活力的侏儒法师，常驻石爪山脉。他利用自己的奥术技能调查并干扰荆棘谷地精的行动，与当地的暗夜精灵哨兵密切合作。",al={"加克希姆","加克希姆·尘链","侏儒法师 石爪"}},{q="荆棘谷地精的信件里写了什么？",a="这些信件包含在针对他们营地的行动中截获的荆棘谷地精内部通讯。它们为凯拉·影矛和哨兵们提供了关于该卡特尔当地后勤、挖掘和资源掠夺的关键情报。",al={"荆棘谷地精信件","信件内容","给凯拉的信"}},{q="为什么哨兵们担心荆棘谷地精？",a="荆棘谷地精滥砍滥伐神圣的森林，并用鲁莽的采矿机械在土地上留下伤痕。对于哨兵来说，这种无情的工业化是对自然的一种冒犯，也是对石爪神圣性的直接威胁。",al={"为什么在意地精","哨兵 荆棘谷地精","荆棘谷地精 石爪"}},{q="这个任务在哪里开始和结束？",a="任务开始于山间小径上的加克希姆·尘链，结束于狂风峭壁附近营地的凯拉·影矛。",al={"任务地点","凯拉的最新情况任务交还","凯拉在哪里"}},{q="这个任务会引出进一步的调查吗？",a="递交这些信件可以让哨兵们随时了解该卡特尔的活动，使凯拉能够计划在整个石爪山脉范围内进行进一步的军事响应和侦察。",al={"后续任务","凯拉的最新情况之后是什么"}}},fp="14,178,28.365.0,21.267.0,25.179.0,24.174.0,39.230.0,58.173.0,36.126.0,47.176.0"}
P.entries["quest:1092"] = {n="格雷苏的要求",s="在击退了挖掘场的巡逻队并成功获取了格伦佐下令开采的那种奇异矿石样本后，匹兹尼克派遣冒险者将样本送交他的接头人——齐兹·菲兹克斯。这次交付行动，终结了一场在狂风峭壁的荆棘谷地精内部作业区深处进行的危险企业间谍活动。",h="在击退了挖掘场的巡逻队并成功获取了格伦佐下令开采的那种奇异矿石样本后，匹兹尼克派遣冒险者将样本送交他的接头人——齐兹·菲兹克斯。这次交付行动，终结了一场在狂风峭壁的荆棘谷地精内部作业区深处进行的危险企业间谍活动。",kw={"格伦佐的订单","匹兹尼克","石爪山脉","安德麦","未经化验的矿石","荆棘谷地精","狂风峭壁","齐兹·菲兹克斯"},ang={["profession:Engineering"]="安德麦的地精工程师们愿意出高价收购未加工的奇异矿石，因为它们可以为不稳定的新型机械和原型机提供动力。",["profession:Mining"]="根据格伦佐的命令开采出的未经化验的矿石表明，荆棘谷地精在狂风峭壁的森林砍伐作业，同样是为了搜寻山脉中未知的地下财富。"},sec={{t="脱身良机",b="由于在挖掘场的战斗中身份暴露，匹兹尼克知道自己在狂风峭壁的荆棘谷地精团队中已待不下去了。位于安德麦的企业管理层绝不会宽容内部破坏行为，这让这名焦躁不安的地精必须设法逃走。在溜走寻找新雇主之前，他将按照格伦佐的命令开采出来的“未经化验的矿石”托付给了一名外来者，以确保这份珍贵的样本能安全送达，同时不会让自己引起怀疑。"},{t="企业奇珍",b="矿石的目标接收人是齐兹·菲兹克斯，他在狂风峭壁西缘建立了一个隐秘的前哨站。齐兹深知这种矿石的战略价值，打算将其南送给安德麦的工程师，同时悄悄私吞一小部分珍贵的矿石以中饱私囊。这种自私的实用主义，凸显了石爪山脉峰峦之下暗流涌动的贸易与工程争端背后那残酷的本质。"}},faq={{q="为什么匹兹尼克需要逃离狂风峭壁？",a="匹兹尼克在为齐兹私下开采矿石样本时被挖掘场的监工抓个正着，导致他作为情报人员的身份暴露。他知道一旦荆棘谷地精的高层得知此事，报复将接踵而至，所以他必须潜逃并寻求新的工作机会。",al={"匹兹尼克为什么要离开","匹兹尼克潜逃","匹兹尼克为何恐惧"}},{q="齐兹·菲兹克斯是谁？",a="齐兹·菲兹克斯是一名驻扎在狂风峭壁西侧山脊上的地精行动者。他在荆棘谷地精内部安插了匹兹尼克，意在窃取企业情报和稀有矿石样本。",al={"齐兹是谁","齐兹·菲兹克斯的角色","齐兹在哪里"}},{q="什么是未经化验的矿石？",a="这是一种神秘的金绿色矿石样本，首席工程师格伦佐曾下令大量开采。齐兹·菲兹克斯打算将其送往安德麦，由那里的研究员和工程师分析其工业用途。",al={"未经化验的矿石背景","这种矿石是什么","格伦佐的矿石"}},{q="在哪里可以找到齐兹·菲兹克斯？",a="齐兹·菲兹克斯藏在石爪山脉狂风峭壁西侧边缘的一个小型营地里。",al={"齐兹·菲兹克斯的位置","寻找齐兹","格伦佐的订单在哪里上交"}},{q="齐兹收到矿石后会发生什么？",a="齐兹计划将大部分矿石样本转发给安德麦的工程师以谋取利益和名声，同时在雇主不知情的情况下私藏一小块矿石。",al={"齐兹如何处理矿石","齐兹私藏矿石"}},{q="匹兹尼克忠于荆棘谷地精吗？",a="匹兹尼克在荆棘谷地精手下工作只是为了达成齐兹的目的。他对这个组织没有任何忠诚可言，而且十分畏惧其高层的报复。",al={"匹兹尼克的阵营","匹兹尼克是荆棘谷地精吗","匹兹尼克为谁工作"}}},fp="16,193,12.397.0,21.313.1,44.228.0,19.176.0,29.210.0,31.112.0,45.114.0,39.146.0"}
P.entries["quest:1093"] = {n="超级收割机6000",s="“超级收割机6000型”是石爪山脉狂风峭壁的那个不满的地精工程师基兹·菲兹克斯提供的一个任务。为了讨好他的新老板斯布特瓦夫，基兹雇佣冒险者潜入当地的荆棘谷地精伐木场，偷取他那竞争对手——侏儒格伦佐·扳牙所设计的一种巨型伐木机器的蓝图。",h="“超级收割机6000型”是石爪山脉狂风峭壁的那个不满的地精工程师基兹·菲兹克斯提供的一个任务。为了讨好他的新老板斯布特瓦夫，基兹雇佣冒险者潜入当地的荆棘谷地精伐木场，偷取他那竞争对手——侏儒格伦佐·扳牙所设计的一种巨型伐...",kw={"蓝图","格伦佐·扳牙","斯布特瓦夫","石爪山脉","超级收割机6000型","荆棘谷地精","狂风峭壁","基兹·菲兹克斯"},ang={["profession:Engineering"]="这个任务突出了地精实用主义——即爆炸性、快速且粗糙的风格——与侏儒设计之间的永恒竞争，后者崇尚过度设计的复杂性和精确度。",["race:Gnome"]="基兹对地精辛迪加竟然会信任一个侏儒来制造他们的旗舰机器表示彻底的不敢相信，结果却发现自己被这名侏儒的技术天赋搞得晕头转向。",["race:NightElf"]="“超级收割机6000型”代表了凡人无视自然的极致，在石爪山脉大肆砍伐古树，只为喂养工业利润的巨口。"},sec={{t="狂风峭壁的工业间谍活动",b="荆棘谷地精在石爪山脉的心脏地带留下了难以磨灭的工业伤痕，无情地砍伐着狂风峭壁的树木。然而，在烟雾和旋转的锯片之下，隐藏着琐碎的企业竞争。基兹·菲兹克斯，一名刚被荆棘谷地精踢出的地精工程师，已经在斯布特瓦夫那里找到了工作。为了巩固自己的地位并证明自己的价值，基兹试图获取荆棘谷地精最宝贵的机械资产：他们那台大型自动伐木引擎“超级收割机6000型”的蓝图。"},{t="地精对决侏儒工程学",b="基兹那灼人的怨恨有一部分源于自尊。荆棘谷地精这个名义上由地精主导的辛迪加，却打破了传统，任命了一名侏儒格伦佐·扳牙来负责当地的工程工作。在从荆棘谷地精机器操作员手中夺取图纸后，基兹感到非常懊恼：对于习惯了蛮力、廉价零件和剧烈燃烧的地精工程师来说，这种侏儒草图设计中那种过度复杂、追求完美的哲学简直令人完全无法理解。"}},faq={{q="基兹·菲兹克斯是谁？",a="基兹·菲兹克斯是居住在石爪山脉的一名地精工程师。他最近被荆棘谷地精解雇，随后很快被该地区颇具影响力的斯布特瓦夫招募，现在正寻求向他以前的雇主报复。",al={"基兹·菲兹克斯","任务发布者是谁","基兹"}},{q="什么是“超级收割机6000型”？",a="“超级收割机6000型”是由格伦佐·扳牙为荆棘谷地精在狂风峭壁的伐木作业而设计的一种巨大的机械伐木机。",al={"超级收割机6000型","什么是超级收割机","这是什么机器"}},{q="谁设计了“超级收割机6000型”？",a="它是由格伦佐·扳牙设计的，这是一名被荆棘谷地精雇佣的侏儒技师。这一事实深深地冒犯了以前负责该工地的地精工程师们。",al={"谁制造了超级收割机","谁建造了这台机器","格伦佐·扳牙"}},{q="为什么斯布特瓦夫想要这些蓝图？",a="斯布特瓦夫想要获得荆棘谷地精开发的尖端重型伐木技术，而基兹·菲兹克斯急于提供这些蓝图，以证明自己对新雇主的用处。",al={"为什么要偷计划","斯布特瓦夫 蓝图"}},{q="在哪里可以找到蓝图？",a="这些图纸由负责监督狂风峭壁伐木机械的荆棘谷地精机器操作员携带。",al={"我在哪里可以找到计划","谁掉落蓝图"}},{q="为什么基兹在拿回蓝图后却难以解读？",a="地精工程学和侏儒工程学在哲学上是众所周知的互不相容。基兹发现格伦佐·扳牙那些细致入微、错综复杂的图纸过于令人困惑，根本无法一眼看懂。",al={"为什么基兹看不懂计划","侏儒蓝图 地精"}}},fp="17,192,38.356.0,31.418.1,19.186.0,30.136.0,35.176.0,42.147.0,31.116.0,60.185.1"}
P.entries["quest:1094"] = {n="新的指示",s="“进一步指示”是一项运送任务，将石爪山脉中混乱的伐木作业与棘齿城的贸易枢纽连接起来。心怀不满的修补匠吉兹·菲兹克斯派遣一名信使，携带偷来的蓝图和内部文件前往他的同行斯布特瓦夫那里，企图将企业间谍活动转化为个人利益。",h="“进一步指示”是一项运送任务，将石爪山脉中混乱的伐木作业与棘齿城的贸易枢纽连接起来。心怀不满的修补匠吉兹·菲兹克斯派遣一名信使，携带偷来的蓝图和内部文件前往他的同行斯布特瓦夫那里，企图将企业间谍活动转化为个人利益。",kw={"贫瘠之地","进一步指示","棘齿城","斯布特瓦夫","石爪山脉","超级收割机6000型","荆棘谷地精","吉兹·菲兹克斯"},ang={["faction:Horde"]="将偷来的荆棘谷地精计划带到棘齿城，有助于加剧那些削弱部落领地附近危险工业扩张的贸易战争。",["profession:Engineering"]="这个信封代表了典型的地精工业运作方式：冷酷的企业间谍活动、专利盗窃，以及对复杂木材收割机的逆向工程。"},sec={{t="企业间谍活动",b="当吉兹·菲兹克斯被踢出荆棘谷地精在狂风峭壁的伐木作业时，他并没有空手离开。因为被解雇而怀恨在心，菲兹克斯顺手牵羊带走了一堆机密文件、内部手册和技术原理图，其中最宝贵的当属实验型超级收割机6000型的蓝图。由于急于寻找买家或盟友来利用这些数据，他将收集到的秘密装入一个密封的信封中，标记为寄往棘齿城。"},{t="棘齿城的联系",b="这些被盗文件的接收者是斯布特瓦夫，一名驻扎在贫瘠之地中立港口棘齿城的工程师。虽然斯布特瓦夫对菲兹克斯没什么私人感情，也不怎么信任他，但与荆棘谷地精的竞争关系让他无法拒绝这份提议。蒸汽火枪手阵营的地精们一直在寻找削弱其无情竞争对手影响力的方法，同时也乐于对他们偶然发现的任何卓越的机械创新进行逆向工程。"}},faq={{q="密封的信封里有什么？",a="信封里装有内部的荆棘谷地精文件、技术手册，以及吉兹·菲兹克斯从他们的伐木作业中被驱逐时窃取的超级收割机6000型的蓝图。",al={"信封内容","菲兹克斯寄出的东西","被盗文件"}},{q="斯布特瓦夫是谁？",a="斯布特瓦夫是居住在贫瘠之地棘齿城的一名地精工程师。虽然他不完全信任吉兹·菲兹克斯，但他渴望削弱荆棘谷地精的力量，并研究他们的机械进步。",al={"斯布特瓦夫身份","接收者是谁","棘齿城工程师"}},{q="为什么吉兹·菲兹克斯要对抗荆棘谷地精？",a="菲兹克斯在石爪山脉被荆棘谷地精无情地踢出了队伍。怀恨在心并寻求报复的他，开始向竞争对手泄露他们的商业机密。",al={"为什么菲兹克斯背叛荆棘谷地精","菲兹克斯的动机"}},{q="在哪里可以找到斯布特瓦夫？",a="斯布特瓦夫驻扎在中立港口城镇棘齿城，位于贫瘠之地的东海岸。",al={"斯布特瓦夫在哪里","斯布特瓦夫位置","寻找斯布特瓦夫"}},{q="斯布特瓦夫信任吉兹·菲兹克斯吗？",a="不，斯布特瓦夫公开承认他不信任菲兹克斯，但那些技术手册和蓝图的价值超过了他对这位信使的戒备。",al={"斯布特瓦夫信任菲兹克斯吗","菲兹克斯和斯布特瓦夫的关系"}},{q="什么是超级收割机6000型？",a="这是一种由荆棘谷地精开发的先进工业粉碎机，用于高速清理森林和加工木材，因此它的蓝图非常抢手。",al={"超级收割机6000型","机器是什么","荆棘谷地精收割机"}}},fp="20,133,19.389.0,22.353.0,35.186.0,20.151.0,55.137.0,32.84.0,36.134.0,30.166.0"}
P.entries["quest:1095"] = {n="新的指示",s="“进一步指令”标志着地精企业政治的升级，下令暗杀一名被莫古尔·拉兹敦克雇佣的侏儒工程师叛徒。斯布特瓦夫传达了来自棘齿城高层的指令，命令兹兹·菲兹克斯在石爪山脉除掉格伦佐·扳手哨。",h="“进一步指令”标志着地精企业政治的升级，下令暗杀一名被莫古尔·拉兹敦克雇佣的侏儒工程师叛徒。斯布特瓦夫传达了来自棘齿城高层的指令，命令兹兹·菲兹克斯在石爪山脉除掉格伦佐·扳手哨。",kw={"进一步指令","格伦佐·扳手哨","诺莫瑞根","拉兹敦克","里德沃克斯","斯布特瓦夫","石爪山脉","棘齿城","荆棘谷地精","兹兹·菲兹克斯"},ang={["profession:Engineering"]="侏儒与地精工程学之间残酷的竞争在这里发生了质变，从设计专利之争演变成了直接的企业暗杀。",["race:Gnome"]="地精特工们提到了格伦佐作为诺莫瑞根高级工程师的过去，他当时的秘密实验在工程师们面前发生了灾难性的爆炸。"},sec={{t="企业不满",b="荆棘谷地精在冷酷的利润动机下运作，但雇佣外部人才会引发激烈的内部摩擦。当莫古尔·拉兹敦克将侏儒工程师格伦佐招致麾下时，消息传到了棘齿城，引起了贸易亲王们的不满。里德沃克斯主管指示斯布特瓦夫进行干预并悄悄处理此事。斯布特瓦夫推断该命令出自最高贸易权威，于是将这份肮脏的工作下派给离现场最近的特工：兹兹·菲兹克斯。"},{t="丹莫罗的秘密",b="在收到暗杀命令后，兹兹·菲兹克斯欣然接受了任务。地精工程师对侏儒竞争对手天生怀有蔑视，但格伦佐的个人经历使他成为了一个特别不稳定的因素。在加入荆棘谷地精之前，格伦佐曾是诺莫瑞根的一名首席工程师，参与了一项连棘齿城间谍都无法完全探明的绝密计划。据称该项目最终以灾难收场，在工程师们的面前发生了剧烈爆炸，而格伦佐现在正将他那危险的专长卖给卡利姆多的荆棘谷地精。"}},faq={{q="斯布特瓦夫是谁？",a="斯布特瓦夫是隶属于里德沃克斯主管旗下的一名地精特工。他根据来自棘齿城的指示行事，负责协调外勤行动，并将合同下派给像兹兹·菲兹克斯这样的地面特工。",al={"斯布特瓦夫","谁发布任务","任务发布者斯布特瓦夫"}},{q="为什么贸易亲王们关心格伦佐？",a="棘齿城的贸易亲王们强烈反对莫古尔·拉兹敦克与外部的侏儒工程师勾结。雇佣知名的非地精人员威胁到了地精内部的工业主导地位，并招致了不必要的审查。",al={"为什么贸易亲王关心","棘齿城愤怒","格伦佐贸易亲王"}},{q="格伦佐参与了什么秘密项目？",a="格伦佐曾是诺莫瑞根的一名首席工程师，负责一个连地精间谍都无法渗透的机密项目。据称他所建造的东西最终导致了灾难性的后果，在参与项目的工程师面前发生了剧烈爆炸。",al={"格伦佐秘密项目","诺莫瑞根爆炸","格伦佐过去"}},{q="兹兹·菲兹克斯在哪里？",a="兹兹·菲兹克斯驻扎在石爪山脉，在执行企业合同的同时，监视当地荆棘谷地精的伐木和采矿工作。",al={"兹兹·菲兹克斯位置","兹兹在哪里","去哪儿下达指令"}},{q="为什么兹兹·菲兹克斯急于杀掉格伦佐？",a="除了地精对侏儒的职业仇恨外，菲兹克斯还将格伦佐视为一个危险的竞争对手，他在丹莫罗所做出的拙劣实验使他成了周围所有人的威胁。",al={"为什么兹兹恨格伦佐","菲兹克斯反应","为什么要杀格伦佐"}},{q="莫古尔·拉兹敦克是谁？",a="莫古尔·拉兹敦克是荆棘谷地精的首席执行官。他雇佣格伦佐的决定直接挑战了棘齿城的传统贸易礼仪，促使贸易亲王们推动除掉格伦佐的计划。",al={"莫古尔·拉兹敦克","谁是拉兹敦克","荆棘谷地精老板"}}},fp="20,174,21.408.0,21.483.1,20.152.0,44.189.0,40.190.0,29.149.0,41.159.0,21.164.0"}
P.entries["quest:1096"] = {n="格雷苏",s="这份赏金任务要求冒险者消灭格雷苏·扳哨，这是一名盘踞在石爪山脉峭壁湖上方高处的流亡侏儒监工。格雷苏用齿轮、发条机械和人造肢体对即将腐烂的血肉之躯进行了大量的改造。地精工程师兹兹·菲兹克斯想要拿到他的机械臂，以此作为他被消灭的无可辩驳的证据，从而从上级那里获得梦寐以求的晋升。",h="这份赏金任务要求冒险者消灭格雷苏·扳哨，这是一名盘踞在石爪山脉峭壁湖上方高处的流亡侏儒监工。格雷苏用齿轮、发条机械和人造肢体对即将腐烂的血肉之躯进行了大量的改造。地精工程师兹兹·菲兹克斯想要拿到他的机械臂，以此作为他被消...",kw={"峭壁湖","生化人","格雷苏","机械臂","斯布特瓦夫","石爪山脉","扳哨","兹兹·菲兹克斯"},ang={["faction:Horde"]="协助石爪山脉的地精承包商有助于确保宝贵的资源和领土，同时干扰峭壁中危险的流亡工程师。",["profession:Engineering"]="格雷苏机械臂那令人毛骨悚然的构造是侏儒仿生工程学中令人不安的极端，与地精的实用设计形成了鲜明对比。",["race:Gnome"]="格雷苏代表了背离标准侏儒天才的古怪而恐怖的道路，他采取了激进的自我改造来维持自己衰败的身体。"},sec={{t="恐怖的混合体",b="格雷苏·扳哨因其令人毛骨悚然的身体改造，即使在经验丰富的技师中也恶名昭彰。据见过他的人所说，他原本的血肉似乎正在腐烂，被植入的齿轮、铁皮和嗡嗡作响的发条假肢所覆盖。这个侏儒栖身于峭壁湖上方高处的大型水车旁，以机械般的精确和对自身肉体凡胎令人不安的漠视，监视着这里的运作。"},{t="地精的野心",b="兹兹·菲兹克斯是一名效力于斯布特瓦夫的地精，他将格雷苏的倒下视为自己离开石爪山脉这个偏远之地的黄金入场券。由于缺乏爬上悬崖或独自击败这个被改造过的监工的身体能力，兹兹招募了一名冒险者来干掉格雷苏并取回他的机械臂。带着这个战利品，兹兹希望证明自己的价值，并确保自己能调往位于加基森或Undermine的著名技师工会车间。"},{t="理念冲突",b="取回格雷苏的机械臂凸显了地精与侏儒工程学传统之间深刻的意识形态分歧。虽然格雷苏采取了极端的侏儒式做法，切除衰败的肉体以整合复杂的假肢，但地精们觉得这种牺牲令人费解。正如兹兹所指出的，真正的地精天才不会舍弃生物肢体——他们只会简单地在另外两条手臂旁边再装上一条爆炸臂。"}},faq={{q="格雷苏·扳哨是谁？",a="格雷苏·扳哨是石爪山脉的一名流亡侏儒监工。他因将自己腐烂的血肉和肢体部分替换为机械假肢和齿轮而臭名昭著，并一直监视着峭壁湖上方高处的工业运作。",al={"格雷苏","格雷苏是谁","格雷苏背景故事"}},{q="在哪里可以找到格雷苏·扳哨？",a="格雷苏位于兹兹·菲兹克斯位置的东北方，在峭壁湖水域上方高处，靠近一个大型工业水车。",al={"格雷苏位置","找到格雷苏","格雷苏在哪里"}},{q="为什么兹兹·菲兹克斯想让格雷苏死？",a="兹兹·菲兹克斯是在执行斯布特瓦夫的命令。消灭格雷苏可以证明兹兹的能力，他希望以此获得调往加基森或Undermine的主要技师工会车间的机会。",al={"为什么要杀格雷苏","兹兹动机","兹兹·菲兹克斯目标"}},{q="兹兹需要什么证据？",a="兹兹需要格雷苏的移植机械臂，作为这个改造人监工已被永久报废的实质性、无可辩驳的证据。",al={"什么证据","格雷苏的证据","任务目标物品"}},{q="为什么格雷苏的身体部分是机械的？",a="格雷苏的有机血肉似乎正在腐烂，促使他将齿轮、铁板和机械肢体直接移植到自己身上，以维持和增强自己的机能。",al={"为什么格雷苏是生化人","格雷苏机器人","格雷苏身体"}},{q="谁是斯布特瓦夫？",a="斯布特瓦夫是一位显赫的地精主管，他在卡利姆多的其他地方监督运作并指挥像兹兹·菲兹克斯这样的下属。",al={"斯布特瓦夫","谁是斯布特瓦夫"}}},fp="21,308,18.294.0,16.341.0,21.287.0,29.201.0,41.98.0,39.179.0,28.72.0,33.131.0,20.127.0"}
P.entries["quest:1097"] = {n="艾尔默的任务",s="“埃尔莫尔的任务”是闪金镇的铁匠阿古斯提供的一项联盟送信任务。在认出你是一位可靠的旅行者后，阿古斯会将你派遣至暴风城的Dwarven District，协助武器大师格里曼·埃尔莫尔。这项任务凸显了艾尔文森林的人类与他们的矮人盟友之间紧密的合作关系和贸易往来。",h="“埃尔莫尔的任务”是闪金镇的铁匠阿古斯提供的一项联盟送信任务。在认出你是一位可靠的旅行者后，阿古斯会将你派遣至暴风城的Dwarven...",kw={"铁匠","货物运输","dwarven district","埃尔莫尔","闪金镇","格里曼·埃尔莫尔","铁匠阿古斯","暴风城"},ang={["faction:Alliance"]="这项任务代表了暴风城人类王国与卡兹莫丹矮人氏族之间至关重要的日常合作，在整个联盟中维护着共同的贸易和信任。",["profession:Blacksmithing"]="虽然对所有冒险者开放，但这项差事连接了两位杰出的工匠——闪金镇的铁匠阿古斯和暴风城的格里曼·埃尔莫尔，他们共享着铁砧上的技艺。",["race:Dwarf"]="矮人旅行者会感到倍感亲切，因为他们的人类同伴认可铁炉堡铁匠的精湛技艺，并协助将补给运回北方的山脉。"},sec={{t="来自熔炉的消息",b="当你在闪金镇休息时，当地的铁匠铁匠阿古斯总是在留意是否有能干的冒险者，能够处理比清理狼群和狗头人更重要的事务。格里曼·埃尔莫尔，一位驻守在暴风城的技艺高超的矮人武器大师，发出了求助讯息，希望能有人协助将一批货物运往他位于卡兹莫丹北部群山的族人那里。阿古斯看你有着适合长途跋涉的坚韧，便指引你前往城门去响应这项号召。"},{t="The Ties That Bind",b="维持暴风城王国与铁炉堡山中堡垒之间的贸易畅通和友好关系，对于联盟至关重要。阿古斯强调，虽然艾尔文森林总是需要当地防御者，但信守对矮人同伴的承诺，能让双方领地都获得补给并保持团结。步入暴风城东北部那烟尘弥漫、繁忙的Dwarven District，你便会直接来到埃尔莫尔的店铺，开启一段远超森林边界的旅程。"}},faq={{q="谁发布了“埃尔莫尔的任务”？",a="这项任务由闪金镇的驻地铁匠铁匠阿古斯提供，他就在暴风城以南的艾尔文森林的这个村庄里经营熔炉。",al={"哪里可以接到埃尔莫尔的任务","谁发布了埃尔莫尔的任务","埃尔莫尔任务发布者"}},{q="在哪里可以找到格里曼·埃尔莫尔？",a="格里曼·埃尔莫尔在暴风城东北部的Dwarven District经营着一家武器店。",al={"格里曼·埃尔莫尔位置","格里曼·埃尔莫尔在哪里","在暴风城寻找埃尔莫尔"}},{q="这项任务的目的是什么？",a="铁匠阿古斯之所以把你派去格里曼·埃尔莫尔那里，是因为这位矮人铁匠需要一名值得信赖的信使将一批货物运往他北部的家乡。这算是对联盟领地更广阔旅行的一次入门引导。",al={"为什么要派我去找埃尔莫尔","埃尔莫尔的任务目的","埃尔莫尔想要什么"}},{q="“埃尔莫尔的任务”后续是什么？",a="与格里曼·埃尔莫尔交谈即可完成这项简短的跑腿任务，并立即开启后续任务“雷矛的货运”，要求你将他打造好的货物运往北方的洛克莫丹。",al={"埃尔莫尔的任务后续","埃尔莫尔的任务后续任务","埃尔莫尔的任务之后是什么"}},{q="为什么铁匠阿古斯关心矮人的货物运输？",a="铁匠阿古斯指出，尽管当地民兵需要艾尔文森林里的每一份战力，但与卡兹莫丹的矮人盟友保持牢固的关系和贸易往来，对于暴风城的安全和补给线至关重要。",al={"为什么阿古斯要帮助矮人","铁匠阿古斯与矮人的关系"}},{q="接受这个任务需要成为铁匠吗？",a="不需要。尽管任务由一位铁匠发起并由另一位铁匠接收，但这只是一项普通的送信任务，任何准备好前往暴风城的联盟冒险者都可以接取。",al={"埃尔莫尔的任务只有铁匠能做吗","埃尔莫尔的任务需要锻造技能吗"}}},fp="13,199,21.337.0,18.308.0,35.75.0,34.88.0,33.165.0,33.139.0,51.144.0,50.113.0"}
P.entries["quest:1098"] = {n="影牙城堡里的亡灵哨兵",s="高级执行官哈德瑞克派遣部落冒险者进入影牙城堡，搜寻两名失踪的侦察探员：亡灵哨兵阿达曼和亡灵哨兵文森特。被遗忘者军队依靠他们收集的情报来协调对大法师阿鲁高及其狼人部队的突袭。潜入这座要塞，揭开了敌后间谍活动残酷的真相。",h="高级执行官哈德瑞克派遣部落冒险者进入影牙城堡，搜寻两名失踪的侦察探员：亡灵哨兵阿达曼和亡灵哨兵文森特。被遗忘者军队依靠他们收集的情报来协调对大法师阿鲁高及其狼人部队的突袭。潜入这座要塞，揭开了敌后间谍活动残酷的真相。",kw={"阿达曼","阿鲁高","亡灵哨兵在影牙城堡","哈德瑞克","瑟伯切尔","影牙城堡","银松森林","文森特"},ang={["class:Rogue"]="亡灵哨兵的失踪证明了在戒备森严的敌后进行侦察所面临的风险。",["faction:Horde"]="当常规部队无法攻破阿鲁高的诅咒要塞时，高级执行官哈德瑞克依靠部落勇士来支持被遗忘者的行动。",["race:Undead"]="对于被遗忘者来说，从阿鲁高的野兽手中收复银松森林对于保卫洛丹伦至关重要。失踪的侦察兵表明了这场斗争的危险性。"},sec={{t="深入狼人巢穴",b="银松森林依然是争夺激烈的土地，大法师阿鲁高的狂暴狼人占据着高耸的影牙城堡。为了打破南部边境的围攻，驻扎在瑟伯切尔的被遗忘者指挥部组织了一次情报行动。高级执行官哈德瑞克派遣了两名经验丰富的亡灵哨兵——阿达曼和文森特——潜入要塞并探明其防御状况。当数日过去仍杳无音讯时，哈德瑞克急需他们的现场报告，于是指派能干的部落勇士进入据点，找回这些探员并挽救任务。"},{t="苦涩的发现",b="在杀出一条血路穿过下层壁垒后，冒险者们发现了渗透行动付出的惨痛代价。虽然亡灵哨兵阿达曼幸存并被囚禁，还协助解开了庭院大门的锁，但文森特却遭遇了悲惨的结局。他破碎的尸体静静地躺在城堡内，他掌握的情报也随之湮灭在黑暗的厅堂中。只有一枚小饰品紧攥在他冰冷的指间，作为一名为黑暗女王的征服大业献出不死之身的间谍，这是他留下的无声见证。"}},faq={{q="为什么要派遣亡灵哨兵前往影牙城堡？",a="高级执行官哈德瑞克下令进行渗透，以便在派遣被遗忘者军队对影牙城堡发动全面突袭之前，收集关于大法师阿鲁高的部队和防御工事的关键战术情报。",al={"为什么要向影牙城堡派遣间谍","哈德瑞克任务的目的","亡灵哨兵在影牙城堡的目标"}},{q="亡灵哨兵阿达曼和文森特是谁？",a="他们是隶属于幽暗城间谍和暗杀分支机构——亡灵哨兵的被遗忘者精英特工。作为先遣侦察兵，他们的任务是绘制影牙城堡地图并观察狼人的防御。",al={"阿达曼和文森特是谁","阿达曼和文森特的背景故事"}},{q="亡灵哨兵文森特发生了什么事？",a="文森特还没有从影牙城堡传回任何报告。哈德瑞克需要有人进入这座要塞，查明他遭遇了什么。",al={"文森特死了吗","文森特在哪里","文森特的命运"}},{q="亡灵哨兵阿达曼在城堡内扮演什么角色？",a="阿达曼是失踪的亡灵哨兵之一，被派往影牙城堡收集情报。在搜寻过程中可以了解到他的处境。",al={"阿达曼做了什么","亡灵哨兵阿达曼的作用"}},{q="这个任务从哪里开始？",a="该任务由驻扎在银松森林瑟伯切尔的被遗忘者军事指挥官高级执行官哈德瑞克发布。",al={"如何领取亡灵哨兵在影牙城堡任务","亡灵哨兵在影牙城堡任务发布者"}},{q="为什么被遗忘者领导层想要清理影牙城堡？",a="大法师阿鲁高盘踞在影牙城堡，不断向银松森林释放凶残的狼人部队，持续威胁着被遗忘者的领地、补给线以及洛丹伦的整体安全。",al={"为什么要攻击影牙城堡","被遗忘者与阿鲁高的冲突"}}},fp="27,264,19.433.0,18.378.1,47.192.0,42.225.0,38.129.1,57.139.1,30.138.0,62.182.0"}
P.entries["quest:1099"] = {n="Goblins Win!",s="在千针石林，当地精胜出时，地精优惠券就会派上用场。持有获胜票根的人可以领回一个奖品盒。",h="在千针石林，当地精胜出时，地精优惠券就会派上用场。持有获胜票根的人可以领回一个奖品盒。",kw={"地精","地精奖品盒","比赛门票","千针石林"},sec={{t="地精优惠券",b="当地精获胜时，地精优惠券就是那张有效的票根。一定要拿好它，比赛结果出来后，你就能得到一个地精奖品盒。侏儒优惠券则有其对应的比赛结果。"}},faq={{q="什么是地精优惠券？",a="这是在千针石林比赛中针对地精一方的票券。当地精获胜时，它就会生效。",al={"比赛门票","什么是地精优惠券"}},{q="地精获胜时能得到什么？",a="当地精胜出时，持有地精优惠券的人就能获得一个地精奖品盒。",al={"地精奖品盒","地精获胜奖励"}},{q="如果侏儒获胜会怎样？",a="那么生效的就是侏儒优惠券了。其结果被称为“侏儒获胜！”，是与此对应的另一个结果。",al={"侏儒获胜","侏儒优惠券"}}},fp="12,140,17.212.0,31.102.0,37.97.0,39.109.0"}
P.entries["quest:11"] = {n="悬赏河爪豺狼人",s="“河爪豺狼人悬赏”是瑞尼尔副队长在西泉要塞发布的一份正式契约，旨在清除威胁艾尔文森林西部边界的入侵豺狼人。暴风城军队悬赏征集从侵扰森林和水道的河爪部族身上夺取的彩绘臂章。",h="“河爪豺狼人悬赏”是瑞尼尔副队长在西泉要塞发布的一份正式契约，旨在清除威胁艾尔文森林西部边界的入侵豺狼人。暴风城军队悬赏征集从侵扰森林和水道的河爪部族身上夺取的彩绘臂章。",kw={"悬赏","瑞尼尔副队长","艾尔文","豺狼人","彩色豺狼人臂章","河爪","石碑湖","西泉要塞"},ang={["faction:Alliance"]="承接边境悬赏既能提升在暴风城军队中的声望，也能确保穿过王国腹地的关键贸易路线的安全。",["race:Human"]="对于王国的人类而言，猎杀河爪部族是保护艾尔文森林边境、支援负担过重的皇家卫兵的直接举措。"},sec={{t="边境威胁",b="西泉要塞守卫着艾尔文森林和西部荒野之间重要的边境地带。然而，守军兵力不足，导致该哨所难以遏制河爪豺狼人的大举入侵。这些野蛮的生物在哨塔正南方以及更东面的石碑湖岸边建立了营地，它们的侵扰已经威胁到了宁静的旅人和当地的家园。"},{t="秩序的代价",b="由于无法抽出正规步兵去清扫森林，瑞尼尔副队长对这些劫掠者发布了悬赏。为了确认战果，瑞尼尔需要武力胜利的证明：从被杀死的野兽身上剥下的彩绘豺狼人臂章。通过雇佣流浪的冒险者和新兵来削减其数量，要塞希望在河爪部族踏平西部边境之前挫败它们的攻势。"}},faq={{q="在艾尔文森林哪里可以找到河爪豺狼人？",a="河爪豺狼人主要聚集在艾尔文森林的两个区域：西泉要塞正南方的茂密森林和河岸附近，以及更东面石碑湖的周边地区。",al={"豺狼人位置","豺狼人在哪里","河爪部族位置"}},{q="为什么要塞要请求冒险者协助对付豺狼人？",a="西泉要塞人手不足，且正面临艾尔文森林边境的压力。由于缺乏足够的守卫同时进行巡逻和进攻性扫荡，瑞尼尔副队长只能求助于独立的勇士来猎杀这些豺狼人。",al={"为什么瑞尼尔副队长需要帮助","为什么要塞要雇佣人手"}},{q="瑞尼尔副队长需要什么证明？",a="瑞尼尔副队长需要八个彩绘豺狼人臂章作为这些入侵野兽已被消灭的实物证明。",al={"悬赏证明","要为瑞尼尔收集什么"}},{q="什么是河爪豺狼人？",a="河爪部族是一个臭名昭著且极其凶残的类鬣狗人形生物部族，它们以侵扰人类领地的河谷和边境而闻名。它们经常袭击定居点、旅人和农田以掠夺食物和财物。",al={"什么是河爪豺狼人","河爪部族背景"}},{q="这个任务与其他艾尔文森林的威胁有关联吗？",a="“河爪豺狼人悬赏”是西泉要塞简短警报任务线的终结，不过瑞尼尔副队长和西泉要塞也在监视该地区其他不法分子，例如臭名昭著的暴徒霍格。",al={"任务后续","河爪豺狼人悬赏之后是什么"}},{q="谁为这些豺狼人的悬赏买单？",a="悬赏由暴风城军队正式批准并支持，该军队授权当地要塞嘉奖并补偿协助平定皇家领土的人员。",al={"谁资助了悬赏","悬赏奖励来源"}}},fx={["139c22ee"]={q="为什么瑞尼尔副队长要剿灭豺狼人？",a="瑞尼尔副队长认为河爪豺狼人是一群粗野的入侵者，根本不该出现在艾尔文森林的边境。大群豺狼人盘踞在哨塔以南，以及石碑湖附近的东侧，直接威胁着西泉要塞的外围防线和周边居民。瑞尼尔想剿灭它们，遏止这场不断蔓延的侵袭，免得哨站彻底沦陷。",al={"为何剿灭豺狼人","瑞尼尔副队长的动机","瑞尼尔为何要杀河爪豺狼人"}}},fp="21,288,22.425.0,18.382.0,52.192.0,60.236.0,38.117.0,28.216.0,55.214.0,37.177.0"}
P.entries["quest:110"] = {n="昆虫研究",s="随着Scrimshank的失踪，高级勘探员菲兹杜瑟开始清点测量装备并整理Scrimshank的个人物品，同时让你去加基森找炼金师匹斯特苏格询问有关虫壳的事情。",h="随着Scrimshank的失踪，高级勘探员菲兹杜瑟开始清点测量装备并整理Scrimshank的个人物品，同时让你去加基森找炼金师匹斯特苏格询问有关虫壳的事情。",kw={"菲兹杜瑟","加基森","虫壳分析","匹斯特苏格","scrimshank","塔纳利斯"},sec={{t="加基森之行",b="菲兹杜瑟打算花些时间整理Scrimshank的测量装备和个人物品，他隐约感觉到这些虫子会带来更多的损失。他让你去加基森找炼金师匹斯特苏格，了解勘探员送来的虫壳是否已经处理完毕。如果处理好了，菲兹杜瑟希望你能把它们带回来。"},{t="匹斯特苏格的发现",b="匹斯特苏格已经有了结果，而且结果令人不安。最初的怀疑，即有一种外部力量在控制这些虫子，现在看来是正确的。这意味着有一股非常强大且邪恶的未知力量。这些虫子已经被改造成了纯粹的杀戮机器，匹斯特苏格还从未见过这样的事情。"}},faq={{q="是谁让你去咨询炼金师匹斯特苏格的？",a="高级勘探员菲兹杜瑟，他正在清点Scrimshank的装备并整理他的个人物品。",al={"任务发布者","谁开启了虫壳分析","菲兹杜瑟的位置"}},{q="炼金师匹斯特苏格在哪里？",a="在加基森，你需要去那里询问有关虫壳的事情。",al={"匹斯特苏格在哪里","匹斯特苏格的位置","匹斯特苏格所在的城镇"}},{q="在这一步之前发生了什么？",a="在此之前是任务“Scrimshank的救赎”。",al={"前置任务","哪个任务是先决条件","上一步"}},{q="你是被派去调查什么的？",a="询问匹斯特苏格是否已经处理完了勘探员送来的虫壳。如果处理好了，就将它们带给菲兹杜瑟。",al={"匹斯特苏格有什么发现"}}},fp="20,225,23.354.0,21.311.1,46.111.0,38.63.0,36.37.0,30.141.0"}
P.entries["quest:1100"] = {n="亨里格·独眉的日记",s="《亨里格·独眉的日记》是一项联盟任务，通过在千针石林的升降梯底部找到一位死去的矮人手中紧握的风化书籍来开启。日记详细记录了他最后的旅程，并指引拾取者将此书向西送往驻扎在菲拉斯边界的一位暗夜精灵德鲁伊手中。",h="《亨里格·独眉的日记》是一项联盟任务，通过在千针石林的升降梯底部找到一位死去的矮人手中紧握的风化书籍来开启。日记详细记录了他最后的旅程，并指引拾取者将此书向西送往驻扎在菲拉斯边界的一位暗夜精灵德鲁伊手中。",kw={"法芬德尔","菲拉斯","升降梯","亨里格","日记","独眉","剃刀沼泽","萨兰纳尔","千针石林"},ang={["class:Druid"]="萨兰纳尔的法芬德尔负责监测当地生态系统的异常变化，因此独眉关于剃刀沼泽野猪人的笔记对塞纳里奥议会来说具有直接的研究价值。",["faction:Alliance"]="由于塞拉摩和萨兰纳尔之间几乎没有其他前哨站，回收独眉的日记可以确保关键情报在被峡谷吞噬前送达联盟盟友手中。",["race:Dwarf"]="亨里格·独眉的死亡是一个沉痛的提醒，警示着矮人探险家在远离铁炉堡的卡利姆多荒野角落所面临的危险。"},sec={{t="倒下的探险家",b="在千针石林连接贫瘠之地和峡谷底部的巨型机械电梯——升降梯的底部附近，躺着亨里格·独眉的尸体。他手中紧紧握着一本私人的日记，详细记录了他在这片崎岖土地上的旅行。他被抛弃在这个由半人马和牛头人统治的敌对沙漠中，他的尸体成为了一个严酷的警告，提醒人们峡谷对于孤身旅行者来说是多么无情。"},{t="垂死之愿",b="阅读亨里格的日记揭示了他原本的路线和最终的心愿。这位探险家不希望他的发现就这样在峡谷中腐烂，而是希望他的记录能够被送到友方手中。沿着千针石林平直向西的道路前行，就能走出干涸的沟壑，抵达守卫着菲拉斯边界的暗夜精灵前哨站萨兰纳尔，德鲁伊法芬德尔在那里等待着这位旅行者的消息。"},{t="发现剃刀沼泽",b="当法芬德尔审阅了独眉的笔记后，这位探险家的命运便与卡利姆多南部的一场更大的威胁交织在了一起。亨里格的观察结果指向了北方的剃刀沼泽中那些布满荆棘的巢穴，揭示了潜伏在里面的野猪人正由一位危险的女巫所领导。"}},faq={{q="我在哪里可以找到亨里格·独眉的尸体？",a="他的尸体躺在千针石林的升降梯脚下。从西侧电梯坡道的底部出发，向前走大约二十五英尺到一块低矮的岩架，他的尸体就躺在那里，手里拿着日记。",al={"亨里格·独眉位置","独眉的日记在哪里","独眉的尸体","寻找独眉"}},{q="我应该把日记交给谁？",a="将日记交给驻扎在萨兰纳尔的暗夜精灵德鲁伊法芬德尔。萨兰纳尔位于千针石林和菲拉斯交界处的西向主路上。",al={"谁接收独眉的日记","独眉任务在哪里交","独眉任务交付","法芬德尔位置"}},{q="亨里格·独眉是谁？",a="亨里格·独眉是一位在卡利姆多中部冒险的矮人旅行者。他死于升降梯底部附近，留下了一本风化的日记，详细记录了他对周围土地和危险野猪人动向的观察。",al={"亨里格·独眉是谁","独眉背景故事","独眉是谁"}},{q="这个任务后续是什么？",a="将日记交给法芬德尔可以解锁任务“剃刀沼泽的女巫”，该任务指引联盟冒险者前往剃刀沼泽地下城探险。",al={"独眉后续任务","独眉的日记之后任务","独眉任务链"}},{q="部落玩家可以拾取这本日记吗？",a="不可以。这本日记及其后续任务链仅供联盟玩家完成，直接引导至联盟的萨兰纳尔边境哨所。",al={"独眉的日记是联盟专属吗","部落可以做独眉的日记吗","部落独眉任务"}},{q="独眉为什么前往萨兰纳尔？",a="萨兰纳尔是该地区最近的联盟前哨站，也是千针石林和菲拉斯荒野之间的一处避难所。独眉打算与驻扎在那里的暗夜精灵分享他的区域观察记录。",al={"为什么是萨兰纳尔","为什么要把书送给德鲁伊","独眉的目的"}}},fx={["0173d93a"]={q="为什么日记要求把它送到萨兰纳尔？",a="亨里格·孤眉知道自己的旅程将在升降梯下方以悲剧告终。他在泛黄的书页中留下最后的愿望：将自己的发现送到萨兰纳尔边境哨站的法芬德尔手中。把日记送达，就能确保无论是什么重要情报或发现让这名矮人丧命，都不会湮没在千针石林的沙海中。",al={"为何送日记","日记的用途","亨里格·孤眉日记的缘由"}}},fp="18,299,17.419.0,15.417.0,20.301.1,39.222.0,32.194.0,24.240.0,29.168.1,38.140.0,42.221.0"}
P.entries["quest:1101"] = {n="卡尔加·刺肋",s="“剃刀沼泽的老巫婆”是一项联盟任务，由位于菲拉斯与千针石林交界处萨兰纳尔的法芬德尔发布。在阅读了牺牲的矮人亨里格·独眉留下的日记后，法芬德尔派遣冒险者潜入剃刀沼泽，除掉野猪人老巫婆卡尔加·刺肋。",h="“剃刀沼泽的老巫婆”是一项联盟任务，由位于菲拉斯与千针石林交界处萨兰纳尔的法芬德尔发布。在阅读了牺牲的矮人亨里格·独眉留下的日记后，法芬德尔派遣冒险者潜入剃刀沼泽，除掉野猪人老巫婆卡尔加·刺肋。",kw={"阿迦玛甘","卡尔加·刺肋","老巫婆","法芬德尔","亨里格·独眉","徽章","剃刀沼泽","萨兰纳尔"},ang={["class:Druid"]="德鲁伊们非常敬重阿迦玛甘这位受人尊崇的自然半神，并试图净化破坏他荆棘遗迹的黑暗腐蚀。",["faction:Alliance"]="这项任务代表了联盟在南贫瘠之地对抗野猪人威胁的主要举措，由萨兰纳尔前哨站发起。",["race:Dwarf"]="为探险家亨里格·独眉复仇，让矮人们有了亲自进攻野猪人据点的理由。",["race:NightElf"]="暗夜精灵对阿迦玛甘安息之地的亵渎感到沮丧，他们视这位野猪半神为上古之战中牺牲的盟友。"},sec={{t="边界的恳求",b="在偏僻的暗夜精灵前哨站萨兰纳尔，法芬德尔为德鲁伊赫拉拉斯和矮人亨里格·独眉的牺牲感到悲痛。独眉是一位被野猪人俘虏的探险者协会旅行者，他从剃刀沼泽逃出后不久便死在了路上，留下了一本破旧的日记，详细记录了剃刀沼泽中日益增长的威胁。法芬德尔意识到，此时已经来不及向达纳苏斯请求军事增援，只能转而寻求过往冒险者的帮助，直接打击这些荆棘巢穴的核心。"},{t="打击酋长",b="这次远征的目标是卡尔加·刺肋，她是一位古老的地卜师，也是冷酷的族长，凭借铁腕统治将四分五裂的剃刀沼泽野猪人统一了起来。她从沼泽深处集结起一支令人生畏的大军，威胁着周边的土地。冒险者必须劈开厚重的荆棘迷宫、越过防御工事，并在蜂拥而至的狂热野猪人战士中杀出一条血路，将卡尔加逼入绝境，从她毫无生气的尸体上夺回徽章，以证明她已被击败。"},{t="更深层的腐化",b="虽然卡尔加的死暂时遏制了野猪人的威胁，但她的战败也引发了暗夜精灵对更深层问题的担忧。剃刀沼泽是由上古之战中野猪半神阿迦玛甘倒下后长出的活体荆棘形成的。当徽章被带回时，法芬德尔指出，除掉卡尔加能让暗夜精灵学者更深入地研究此地的腐化现象，但他感觉到，导致阿迦玛甘圣骸上突然蔓延出腐蚀瘟疫的根源，可能隐藏着某种阴险的背叛。"}},faq={{q="是谁发布了“剃刀沼泽的老巫婆”任务？",a="该任务由驻扎在萨兰纳尔的暗夜精灵法芬德尔发布。萨兰纳尔是位于菲拉斯与千针石林之间高山隘口上的一个联盟前哨站。",al={"剃刀沼泽的老巫婆任务发布者","去哪里接剃刀沼泽的老巫婆任务","法芬德尔任务"}},{q="在开始此任务前需要完成什么先决条件？",a="你必须先完成任务“亨里格·独眉的日记”。该任务要求在千针石林升降梯附近的遗骸处找回亨里格·独眉的日记，并将其交给萨兰纳尔的法芬德尔。",al={"剃刀沼泽的老巫婆先决条件","如何解锁剃刀沼泽的老巫婆","亨里格·独眉的日记先决条件"}},{q="卡尔加·刺肋是谁？",a="卡尔加·刺肋是剃刀沼泽野猪人的最高女巫和族长。她是一位强大的地卜师，统一了剃刀沼泽内交战的部落，并将他们的侵略矛头对准了周边的领土。",al={"老巫婆是谁","卡尔加背景故事","卡尔加·刺肋"}},{q="在哪里可以找到卡尔加·刺肋？",a="她位于剃刀沼泽的最深处，就在贫瘠之地远南角靠近升降梯的地方。她正待在副本深处的一个祭坛之上。",al={"卡尔加在哪里","卡尔加位置","剃刀沼泽的老巫婆在哪里"}},{q="为什么法芬德尔需要冒险者，而不是向达纳苏斯的军队求援？",a="萨兰纳尔是一个远离卡利姆多北部的偏远前哨站。卡尔加正在积极集结她的部队，如果送信去达纳苏斯并等待大军调遣，耗时太长，无法阻止迫在眉睫的危险。",al={"为什么不向达纳苏斯求援","为什么要雇佣冒险者"}},{q="法芬德尔需要什么证据来证明老巫婆已死？",a="法芬德尔需要卡尔加·刺肋的徽章，这是卡尔加亲自佩戴的护身符，可以作为老巫婆已被杀死的无可争辩的证据。",al={"掉落什么物品","证明击杀的物品","卡尔加·刺肋的徽章"}}},fp="22,214,20.491.0,22.400.0,19.467.1,43.167.0,63.187.0,26.219.0,38.171.0,74.210.0,54.102.0"}
P.entries["quest:1103"] = {n="水之召唤",s="这个任务为在银松森林海岸完成精神试炼的萨满祭司提供了第二次机会。如果萨满祭司在与净化的水之魂交流前，精神视界就消退了，提夫·摩杜恩会在一旁协助重新开启交流。通过提供另一份Water Sapta，请求者可以再次见证仪式并完成交流。",h="这个任务为在银松森林海岸完成精神试炼的萨满祭司提供了第二次机会。如果萨满祭司在与净化的水之魂交流前，精神视界就消退了，提夫·摩杜恩会在一旁协助重新开启交流。通过提供另一份Water...",kw={"call of water","水之先知伊斯伦","水之魂","萨满祭司","银松森林","提夫·摩杜恩","water sapta"},ang={["class:Shaman"]="这个仪式代表了萨满祭司在获得水之图腾的艰苦道路上所展现的同伴情谊，确保没有任何试炼者会因为恍惚消退而陷入困境。",["faction:Horde"]="部落的萨满传统非常依赖互助和对自然之灵的尊重，这一点甚至延伸到了洛丹伦那片闹鬼的土地上。"},sec={{t="迷雾中的援“手”",b="掌握水元素之路充满了微妙的精神时机。萨满祭司需要饮用一种名为Water Sapta的强力药剂，才能感知徘徊在元素祭坛周围的灵魂。如果在萨满祭司与水之魂对话前药剂的魔法失效，他们就会被锁在灵界之外，无法完成试炼。幸运的是，同为萨满祭司的提夫·摩杜恩徘徊在银松森林迷雾笼罩的海岸上，为那些幻象过早结束的同伴提供帮助。"},{t="重启仪式",b="提夫·摩杜恩已经战胜了潜伏在海岸附近的腐化水元素，正带着他收集的仪式遗物在此等候。他需要来自贫瘠之地的水之先知伊斯伦提供的最新鲜的Water Sapta作为准备就绪的证明。一旦交出药剂，提夫就会将他收集的护腕和水滴投入祭坛的火盆中，再次召唤出纯净的化身，以便他的萨满同伴能与其对话并封印他们的元素纽带。"}},faq={{q="提夫·摩杜恩是谁？",a="提夫·摩杜恩是一位驻扎在银松森林海岸的部落萨满祭司。他已经完成了与当地腐化元素的战斗，并留在岸边帮助其他在完成交流前失去精神视界的试炼者。",al={"提夫·摩杜恩","提夫是谁","提夫 银松森林"}},{q="为什么我完成这个任务需要Water Sapta？",a="Water Sapta能让萨满祭司的心智跨越通往灵界的门槛。提夫需要从水之先知伊斯伦那里获得一份新鲜的药剂，以确保当你再次召唤出元素时，你拥有感知它的视界。",al={"为什么需要药剂","water sapta 提夫","在哪里获得药剂"}},{q="如果我错过了与水之魂的对话该怎么办？",a="如果在你与水之魂对话前，灵魂药剂失效或水之魂消失，你就无法独自完成试炼。提夫·摩杜恩会介入，使用他自己收集的战利品重新点燃火盆，这样你就能与灵魂进行交流。",al={"错过了水之魂","水之魂试炼失败","水之魂消失"}},{q="这个仪式在哪里进行？",a="试炼在银松森林的西海岸进行，靠近一座面向无尽之海的元素祭坛。",al={"水之祭坛在哪里","银松森林水之祭坛位置"}},{q="是谁派遣萨满祭司进行这次朝圣的？",a="水之先知伊斯伦，一位住在贫瘠之地东海岸渔屋旁的牛头人萨满祭司，指导试炼者完成他们的Call of Water试炼，并酿造必要的药剂。",al={"谁发布了call of water","水之先知伊斯伦"}},{q="什么是水之魂？",a="它是当地水域的腐化被净化后，在祭坛处召唤出的纯净元素之灵。与它交流标志着萨满祭司元素试炼这一阶段的圆满完成。",al={"什么是水之魂","水之魂"}}},fp="13,224,26.319.0,19.379.0,20.219.0,43.160.0,54.232.0,34.104.0,36.172.0,41.216.0"}
P.entries["quest:1104"] = {n="含盐的蝎毒",s="在闪光平原那片耀眼的盐碱地上，侏儒工程师菲兹尔·铜栓正在寻找奇特的配料，来为他的火箭车提供超强动力。他坚信当地蝎毒中含有高浓度的盐分，能够产生超高温的助燃剂，于是委托路过的冒险者去挑战那些蛰人的野兽。",h="在闪光平原那片耀眼的盐碱地上，侏儒工程师菲兹尔·铜栓正在寻找奇特的配料，来为他的火箭车提供超强动力。他坚信当地蝎毒中含有高浓度的盐分，能够产生超高温的助燃剂，于是委托路过的冒险者去挑战那些蛰人的野兽。",kw={"菲兹尔·铜栓","燃料","沙漠赛道","火箭车","含盐的蝎毒","闪光平原","千针石林"},ang={["profession:Engineering"]="利用有机毒素并辅以跳跃自动机之类的催化剂进行处理，凸显了竞争性车辆工程中常见的创造性和不稳定性实验。",["race:Gnome"]="菲兹尔代表了典型的侏儒雄心：锲而不舍的修补、令人质疑的化学安全性、不知所踪的笔记，以及想要在技术上压倒地精机械师的强烈渴望。"},sec={{t="易挥发的配方",b="沙漠赛道是侏儒的精密技术与地精的大胆创新之间的一场永无止境的速度巅峰对决。对菲兹尔·铜栓来说，普通的碳氢化合物和发条零件根本不足以让他超越竞争对手。他构想出一种特制的燃料混合物，燃烧温度远高于常规助燃剂，能让他们的火箭车在干涸的盐湖上以惊人的速度飞驰。"},{t="盐碱地的咸性毒液",b="菲兹尔的突破性进展依赖于闪光平原上危险的本土动物。当地的蝎子已经进化到能够在干旱、盐碱覆盖的荒原中生存，这也导致它们的毒液中含有极高的盐分。菲兹尔不仅不惧怕这种致命的毒性，反而将其视为一种原始的化学燃料。他认为，只要经过煮沸、提炼，并加入特殊的催化剂，这些带有盐分的毒液就能提供所需的爆炸性燃烧动力，让地精维修车队望尘莫及。"}},faq={{q="为什么菲兹尔·铜栓想要蝎毒？",a="菲兹尔正在发明一种燃烧温度极高的新型火箭车燃料。他认为闪光平原本土蝎子毒液中异常高的含盐量，是完成这种爆炸性混合燃料的关键化学成分。",al={"为什么需要蝎毒","毒液有什么用","菲兹尔的燃料配方"}},{q="去哪里找这些蝎子？",a="蝎子出没在闪光平原的广阔区域，特别是在西部平原和远离中央赛道的沙漠沙地中游荡。",al={"蝎子位置","蝎子在哪里","盐碱地毒液怪物"}},{q="收集到毒液后，菲兹尔打算怎么做？",a="菲兹尔打算把毒液煮沸，用一种跳跃自动机进行处理，再混合一种负催化剂，从而制造出他的高辛烷值火箭推进剂——前提是他能找到自己把笔记丢哪儿了。",al={"毒液如何转化为燃料","燃料加工流程"}},{q="联盟和部落的成员都能帮助菲兹尔吗？",a="可以。沙漠赛道是在侏儒和地精之间达成的中立停战协议下管理的，因此任何阵营的冒险者都可以协助维修车队，而不受政治干扰。",al={"这个任务是中立的吗","部落还是联盟"}},{q="为什么侏儒和地精要在千针石林赛车？",a="闪光平原提供了一片广阔、平坦且无障碍的硬化盐碱地，这使其成为测试实验性高速火箭车和直线加速赛车的理想场地。",al={"为什么这里有赛道","为什么选择沙漠赛道"}},{q="这种燃料真的能让车飞起来吗？",a="虽然菲兹尔热情地声称车子会“飞”起来，但盐碱地上的侏儒火箭车设计目标是以极快的速度贴地疾驰，尽管灾难性的起飞和坠毁始终是有可能的。",al={"车能飞吗","菲兹尔的火箭车结果"}}},fp="15,323,17.404.0,30.473.0,46.240.0,42.163.0,50.202.0,55.183.0,54.185.0,40.223.0"}
P.entries["quest:1105"] = {n="硬化龟壳",s="在闪光平原的沙漠赛道，侏儒修补匠维兹尔·铜栓担心他兄弟研发出的强效火箭燃料会由内而外地溶解他们的赛车。为了防止在这片盐碱地上发生灾难，维兹尔招募路人收集当地陆龟的硬壳，用来制作一个坚不可摧的燃料箱。",h="在闪光平原的沙漠赛道，侏儒修补匠维兹尔·铜栓担心他兄弟研发出的强效火箭燃料会由内而外地溶解他们的赛车。为了防止在这片盐碱地上发生灾难，维兹尔招募路人收集当地陆龟的硬壳，用来制作一个坚不可摧的燃料箱。",kw={"硬壳","沙漠赛道","火箭车","闪光平原","千针石林","陆龟","维兹尔·铜栓"},ang={["profession:Engineering"]="使用有机装甲板来容纳挥发性化合物是不寻常的，这也突显了侏儒修补匠在压力下所依赖的古怪试错法。",["race:Gnome"]="兄弟间的独创性和鲁莽的科学野心在这里发生了正面碰撞，捕捉到了侏儒无论遇到何种后勤障碍都要在创新上超越地精对手的驱动力。"},sec={{t="挥发性创新",b="在闪光平原灼人的烈日下，侏儒和地精工程师之间的竞争将机械野心推向了鲁莽的极端。维兹尔·铜栓和他的兄弟决心用他们定制的火箭车称霸沙漠赛道。然而，他兄弟的实验性燃料混合物表现出太强的腐蚀性。维兹尔担心这种腐蚀性混合物会直接熔穿车辆的标准底盘和油箱，于是他急忙寻找一种足够坚硬的容器来经受住比赛的考验。"},{t="沙漠装甲解决方案",b="维兹尔没有依赖那些在化学作用下可能会溶解的精炼金属，而是转向了这片盐碱地上的自然适应产物。千针石林中出没的本地陆龟拥有能抵抗恶劣环境和机械磨损的龟壳。通过收集这些硬质甲壳，维兹尔希望能制造出足够坚韧的定制燃料箱，在不把火箭车炸成碎片的情况下装载这些挥发性燃料。"}},faq={{q="为什么维兹尔需要陆龟壳而不是金属？",a="他的兄弟正在酿造一种实验性火箭燃料，其腐蚀性足以溶解金属。维兹尔认为，当地陆龟天然的超硬外壳比标准油箱更能抵御这种化学磨损。",al={"为什么用龟壳","为什么用陆龟壳","燃料箱外壳"}},{q="维兹尔·铜栓是谁？",a="维兹尔是一名侏儒工程师，驻扎在闪光平原的沙漠赛道。他与兄弟合作制造并调试他们的高速火箭车，以在比赛中胜过地精竞争对手。",al={"维兹尔","维兹尔是谁"}},{q="在哪里可以找到陆龟？",a="陆龟在闪光平原广阔的盐碱地上自由漫步，在东北部的旧船残骸附近尤其聚集着大量陆龟。",al={"陆龟位置","乌龟在哪里","去哪里获取硬壳"}},{q="这是联盟任务还是部落任务？",a="这是一个完全中立的任务。沙漠赛道在阵营战争之外运作，专注于工程学竞赛，允许联盟和部落的冒险者都能协助维兹尔。",al={"硬壳任务是中立的吗","联盟还是部落"}},{q="壳交给维兹尔后会发生什么？",a="维兹尔急切地开始将它们加工成加固燃料箱，但他很快意识到这些龟壳太坚硬了，他可能需要毁掉一整套工具箱才能把它们雕刻成型。",al={"维兹尔处理龟壳的结果","维兹尔用龟壳做什么"}},{q="为什么在平原上燃料箱故障如此令人担忧？",a="火箭车以惊人的速度在盐碱地上飞驰。Wizzle担心他兄弟的新燃料劲头太猛，会直接腐蚀车架，所以他想趁还没发生这种事，先加固燃料箱。",al={"火箭车危险","为什么要担心燃料"}}},fx={["201b3417"]={q="维兹尔·铜栓为什么想让你完成这件事？",a="维兹尔的兄弟正在沙漠赛道设计一种极不稳定的新燃料，用于他们的火箭车。维兹尔虽然钦佩兄弟的才华，却担心这种混合物腐蚀性太强，会在测试时直接熔穿车子现有的底盘。为了避免盐碱滩上发生灾难，维兹尔需要在兄弟完成配方前打造更坚固的替换燃料箱。",al={"维兹尔的动机","为什么帮维兹尔","维兹尔为什么要龟壳"}},["5a3ddfa8"]={q="闪光平原的陆龟是什么？",a="火壳龟在烈日炙烤的闪光平原上四处游荡。经过数代在这片严酷干旱盆地中的生存，它们的甲壳变得格外坚硬而坚韧。它们通常独自在盐壳间活动，因此成了侏儒工匠急需的天然耐用材料，可用来制作不易起反应、耐热的护板。",al={"盐碱滩陆龟","闪光平原陆龟","这里为什么有陆龟"}}},fp="15,330,20.523.0,24.429.0,54.225.0,25.202.0,33.172.0,35.179.0,43.182.1,53.208.0"}
P.entries["quest:1106"] = {n="流放者马特克",s="菲兹尔·铜栓正在为他的赛车制造一台新引擎，但他无法制造出足够坚硬、能够承受巨大压力的活塞。他让你带上一封信去找一位名叫被放逐者玛特克的伟大铁匠，他住在遥远的荒芜之地的一个营地里。",h="菲兹尔·铜栓正在为他的赛车制造一台新引擎，但他无法制造出足够坚硬、能够承受巨大压力的活塞。他让你带上一封信去找一位名叫被放逐者玛特克的伟大铁匠，他住在遥远的荒芜之地的一个营地里。",kw={"荒芜之地","菲兹尔·铜栓","加塞尔佐格","被放逐者玛特克","沙漠赛道","活塞","千针石林"},sec={{t="致铁匠的信",b="在完成“盐平原的毒液”任务后，沙漠赛道的菲兹尔解释说，他的新引擎应该能让赛车跑得飞快，甚至能飞起来。但他所有的尝试都失败了，因为他无法制造出能承受巨大压力的坚硬活塞。他知道有一个人或许有办法：被放逐者玛特克，一位对金属的了解超过任何人的伟大铁匠。玛特克住得很远，在荒芜之地，和一名地精住在营地里，你需要把菲兹尔的信带给他。"},{t="在营地",b="当你找到那个营地时，玛特克并不友好。玛特克问你是不是为了加塞尔佐格的那把斧头而来，还是为了找回帕玛伊公爵夫人的荣誉，并表示如果你想打架的话，现在就可以开始。"},{t="玛特克的回复",b="得知是菲兹尔派你来的，一切都变了。玛特克说菲兹尔和他兄弟是少数几个不想让他死的人，于是同意帮忙制造能承受菲兹尔计划中任何压力的活塞，因为在玛特克听来，这辆新车简直就像是装在轮子上的火山。"}},faq={{q="为什么菲兹尔·铜栓需要玛特克的帮助？",a="菲兹尔的新引擎应该能让赛车跑得飞快，但由于他无法制造出能承受压力的坚硬活塞，所有的尝试都失败了。玛特克是一位伟大的铁匠，他对金属的了解超过任何人。",al={"为什么要拜访玛特克","菲兹尔·铜栓的活塞问题","为什么找被放逐者玛特克"}},{q="被放逐者玛特克在哪里？",a="在荒芜之地，住在一个也有地精居住的营地里。",al={"玛特克在哪里","被放逐者玛特克的位置","如何找到玛特克"}},{q="在这个任务之前发生了什么？",a="是“盐平原的毒液”，它在任务线中位于此任务之前。后续任务是“瑟银制品”。",al={"被放逐者玛特克的前置任务","被放逐者玛特克的前序任务是什么"}}},fp="17,218,22.435.0,11.220.1,14.277.1,46.209.0,35.58.0,30.73.0"}
P.entries["quest:1107"] = {n="坚硬的尾鳍",s="位于沙漠赛道的维兹尔·铜栓担心他的火箭车速度太快，摩擦力会将其撕碎。为了保护车身，他需要从荆棘谷海岸外的暗礁海里的盐鳞鱼人身上获取鳍刺。",h="位于沙漠赛道的维兹尔·铜栓担心他的火箭车速度太快，摩擦力会将其撕碎。为了保护车身，他需要从荆棘谷海岸外的暗礁海里的盐鳞鱼人身上获取鳍刺。",kw={"外壳坚硬的鳍刺","沙漠赛道","火箭车","盐鳞鱼人","闪光平原","荆棘谷","暗礁海","维兹尔·铜栓"},sec={{t="为车身涂层",b="维兹尔称这辆火箭车是闪光平原上最快的东西，但他担心摩擦力会将其撕碎。运动部件需要涂上一层既坚硬又不脆，而且能抗盐腐蚀的复合材料，否则闪光平原的环境会侵蚀掉这辆车。这种材料的关键成分就是栖息在荆棘谷海岸外暗礁海的盐鳞鱼人的鳍刺。他请求你带给他十个鳍刺。"},{t="成品复合材料",b="维兹尔会把你的鳍刺研磨成粉，并混合其他一些成分，制成的成品复合材料应该能保护车身免受自身速度带来的损伤。维兹尔补充说，只要车不撞上任何东西，这层保护就有效。"}},faq={{q="为什么维兹尔·铜栓需要外壳坚硬的鳍刺？",a="火箭车速度太快，维兹尔担心摩擦力会将其撕碎。鳍刺是制造一种能保护车身运动部件的复合材料的关键成分，这种材料既坚硬又不脆，且能抗盐腐蚀。",al={"为什么需要鳍刺","维兹尔鳍刺用途","为什么用鱼人鳍刺"}},{q="盐鳞鱼人在哪里可以找到？",a="在荆棘谷海岸外的暗礁海，位于格罗姆高营地的正西方向。",al={"暗礁海位置","盐鳞鱼人在哪里","哪里寻找外壳坚硬的鳍刺"}},{q="维兹尔之前的任务是什么？",a="该系列任务的前置是“硬化外壳”。",al={"前置任务是什么","维兹尔任务链前置","外壳坚硬的鳍刺前置条件"}},{q="维兹尔·铜栓是谁？",a="维兹尔·铜栓位于沙漠赛道，他因担心火箭车而向你寻求鳍刺。",al={"维兹尔是谁","谁给予外壳坚硬的鳍刺任务"}}},fp="19,221,21.428.0,22.227.1,52.206.0,41.99.0,33.45.0,25.113.0"}
P.entries["quest:1108"] = {n="精铁碎片",s="被放逐者马特克说，荒芜之地蕴藏着丰富的金属，只要有胆量就能拿到。据说Indurium能承受高温和压力，马特克想要一些样本来测试它是否能用于菲兹尔的赛车。荒芜之地的Stonevault穴居人身上携带着这种金属碎片。",h="被放逐者马特克说，荒芜之地蕴藏着丰富的金属，只要有胆量就能拿到。据说Indurium能承受高温和压力，马特克想要一些样本来测试它是否能用于菲兹尔的赛车。荒芜之地的Stonevault穴居人身上携带着这种金属碎片。",kw={"埃格蒙德的营地","荒芜之地","菲兹尔·铜栓","indurium","indurium碎片","被放逐者马特克","沙漠赛道","stonevault穴居人","奥达曼"},sec={{t="一种值得测试的金属",b="被放逐者马特克告诉你，他待在荒芜之地不仅仅是为了躲避人群。这个地区有Indurium，一种据说能承受高温和压力的金属，可能适合菲兹尔的赛车。马特克想要样本进行测试，而且熔炉已经烧热准备好了。"},{t="来自穴居人的碎片",b="真正的矿石在奥达曼深处，但荒芜之地的Stonevault穴居人偶尔会携带一些碎片。马特克要求收集十个。拥有碎片的穴居人游荡在埃格蒙德的营地附近的一处岩石堆东南坡上，就在巨牙谷的正南方。"},{t="熔炉测试",b="马特克把碎片拿到熔炉边，分阶段调高了温度。它们没有熔化，马特克以奥格瑞姆之名发誓，这种Indurium能承受极高的热量。测试成功了，马特克称赞这种金属太神奇了。"}},faq={{q="是谁派你去寻找Indurium的？",a="位于荒芜之地中央的被放逐者马特克要求收集样本。引导你找到他的任务链始于千针石林沙漠赛道的菲兹尔·铜栓。",al={"谁给予indurium任务","如何获得indurium"}},{q="马特克为什么需要Indurium？",a="马特克认为这种据说能承受高温和压力的金属可能适合菲兹尔的赛车，所以想要一些样本放进熔炉测试。",al={"indurium的用途","为什么需要indurium"}},{q="在哪里可以找到Indurium碎片？",a="荒芜之地的Stonevault穴居人偶尔会携带，它们位于埃格蒙德的营地附近的一处岩石堆东南坡，就在巨牙谷的正南方。",al={"indurium碎片在哪里","如何获得碎片","谁掉落indurium碎片"}},{q="真正的Indurium矿石来自哪里？",a="马特克说真正的矿石在奥达曼深处。",al={"indurium矿石在哪里","indurium矿石哪里开采"}},{q="这个任务之前是什么？",a="紧接在“被放逐者马特克”之后，这是任务链的第一步，始于沙漠赛道的菲兹尔·铜栓。",al={"indurium任务的前置任务","如何开始indurium任务"}},{q="交出碎片后接下来是什么？",a="任务链继续进行，接下来是“菲兹尔的消息”。",al={"indurium任务后的后续任务","接下来发生什么"}}},fp="8,292,21.251.0,22.245.0,14.220.1,33.170.0,30.135.0,39.151.0,39.44.0,23.118.0,42.41.0"}
P.entries["quest:111"] = {n="托米的祖母",s="这个任务要求冒险者代表托米·乔·斯通菲尔德去见米莱德·斯通菲尔德。由于斯通菲尔德家族和马科伦家族之间存在着激烈的世仇，托米·乔希望这位年长的女族长能想出办法，让他得以见到梅贝尔·马科伦。",h="这个任务要求冒险者代表托米·乔·斯通菲尔德去见米莱德·斯通菲尔德。由于斯通菲尔德家族和马科伦家族之间存在着激烈的世仇，托米·乔希望这位年长的女族长能想出办法，让他得以见到梅贝尔·马科伦。",kw={"艾尔文森林","米莱德·斯通菲尔德","马科伦农场","梅贝尔·马科伦","与祖母交谈","斯通菲尔德农场","托米·乔·斯通菲尔德","年轻恋人"},ang={["faction:Alliance"]="在暴风城面临迪菲亚兄弟会骚乱和野兽袭击的同时，联盟的旅行者经常发现自己在邻近农民之间微小的家庭纠纷中扮演调解人的角色。",["race:Human"]="对于在艾尔文森林冒险的人类来说，斯通菲尔德与马科伦的冲突提醒着人们，即便是在暴风城广阔领域危机的阴影下，当地积怨在腹地中的影响依然如此深远。"},sec={{t="世仇与禁忌之恋",b="斯通菲尔德家族和马科伦家族多年来一直陷入激烈的农业竞争中，导致他们相邻的农场变成了敌对区域。夹在中间的是年轻的托米·乔·斯通菲尔德和梅贝尔·马科伦，他们的恋情必须完全保密。托米·乔渴望能找到与爱人相见的方法，又不至于引发两个家族之间的暴力冲突，于是他向祖母寻求指导。"},{t="祖母的妙计",b="虽然年事已高使米莱德·斯通菲尔德无法外出，但她比任何人都更了解这场世仇的本质。尽管她意识到，只要积怨仍在，两个家族之间不可能真正和解，但她也不打算让邻里间的恩怨彻底扼杀年轻人的爱情。与其劝阻，她倒不如开始策划一些小小的机会，让他们两人能够相聚。"}},faq={{q="托米·乔为什么要让我去和他祖母谈谈？",a="托米·乔深深爱着梅贝尔·马科伦，但他们两个家族之间的世仇让见面变得不可能。他相信自己的祖母拥有足够的智慧、同情心和谋略，能帮助他们在不引起轩然大波的情况下安排秘密会面。",al={"为什么找祖母","托米·乔的祖母","找祖母的目的"}},{q="去哪里可以找到米莱德·斯通菲尔德？",a="米莱德·斯通菲尔德待在斯通菲尔德主农舍内，该农舍位于闪金镇以南，托米·乔躲藏的河岸以东。",al={"米莱德·斯通菲尔德的位置","祖母在哪里","寻找米莱德·斯通菲尔德"}},{q="斯通菲尔德家族和马科伦家族之间有什么世仇？",a="这两个相邻的农耕家庭长期以来存在着个人恩怨和领土纠纷。关于盗窃的指控、农作物的竞争以及相互的不信任，使两个家庭都处于暴力边缘，迫使他们子女之间的任何互动都只能转入地下。",al={"斯通菲尔德与马科伦的世仇","他们为什么打架","艾尔文森林的家族世仇"}},{q="米莱德·斯通菲尔德反对托米·乔的恋情吗？",a="不反对。虽然她承认世仇使得目前的长期未来难以实现，但她对这对年轻恋人抱有同情，并愿意策划一些计谋来帮助他们见面。",al={"祖母反对梅贝尔吗","祖母支持这对恋人吗"}},{q="与祖母交谈后会发生什么？",a="祖母开始制定一个让托米·乔和梅贝尔偷偷见面的计划，并派遣冒险者去跑腿准备隐形水，以绕过家族中警惕的目光。",al={"找祖母之后的后续","祖母任务后续"}},{q="梅贝尔·马科伦是谁？",a="梅贝尔是敌对的马科伦家族的女儿，住在斯通菲尔德农场马路对面。她正在秘密与托米·乔·斯通菲尔德交往。",al={"梅贝尔是谁","梅贝尔·马科伦"}}},fp="17,213,25.335.0,16.307.0,52.168.0,37.129.0,58.230.0,55.142.0,38.181.1,23.144.0"}
P.entries["quest:1110"] = {n="火箭车零件",s="“火箭车零件”是为闪光平原那刺眼的盐碱地上，那个投机取巧的矮人商人克拉维尔·浓须所进行的一项跑腿任务。克拉维尔·浓须并不想让那些高速赛车撞毁后四散的残骸白白浪费，于是他花钱雇佣流浪者们搜寻沙漠地面，找回这些损毁的机械装置，然后直接转卖给相互竞争的地精和侏儒维修车队。",h="“火箭车零件”是为闪光平原那刺眼的盐碱地上，那个投机取巧的矮人商人克拉维尔·浓须所进行的一项跑腿任务。克拉维尔·浓须并不想让那些高速赛车撞毁后四散的残骸白白浪费，于是他花钱雇佣流浪者们搜寻沙漠地面，找回这些损毁的机械装置...",kw={"撞车事故","侏儒","地精","克拉维尔·浓须","沙漠赛道","火箭车零件","打捞","废料","闪光平原","千针石林"},ang={["profession:Engineering"]="搜寻盐碱地揭示了地精和侏儒设计者们鲁莽的独创性，在那里，不稳定的火箭助推器和临时改装的底盘经常以壮观的结构性故障告终。",["race:Dwarf"]="虽然许多铁炉堡的矮人将目光投向赛道以寻找机械创新或挖掘机会，但克拉维尔·浓须表现出了彻头彻尾的雇佣兵本色，只对打捞行动带来的金币感兴趣。",["race:Gnome"]="回收这些零件突显了侏儒工程师在开阔赛道上试图超越和胜过地精竞争对手的那种锲而不舍，尽管有时会带来灾难性的驱动力。"},sec={{t="盐碱地上的残骸",b="The Shimmering Flats serve as the proving ground for the fierce technological rivalry between goblin and gnomish engineers. High-velocity experimental rocket cars routinely suffer catastrophic malfunctions, leaving twisted gears, cylinders, and jagged sheets of metal scattered wide across the vast white desert. While the pit crews focus solely on building and tuning the next machine, the desert floor has quietly become a scrap yard of experimental engineering."},{t="浓须的打捞生意",b="矮人企业家克拉维尔·浓须没有选择直接在赛道上竞争，而是在沙漠赛道发现了一个有利可图的中间商机会。侏儒和地精技师们消耗零件的速度非常快，他们总是急需备用装置来加装到自己的赛车上。克拉维尔·浓须雇佣旅行者们收集三十捆破碎的残骸，将毁灭性的撞车事故转化为新鲜的库存，并从车手们的不幸中大赚一笔。"}},faq={{q="克拉维尔·浓须是谁？",a="克拉维尔·浓须是驻扎在闪光平原的沙漠赛道的一名精明的矮人商人。他在赛道周围经营着各种投机生意，主要侧重于拾荒、打零工，并将侏儒和地精之间的竞争转化为个人利润。",al={"克拉维尔·浓须","谁给予火箭车零件任务","赛道矮人"}},{q="为什么地上散落着这么多火箭车零件？",a="沙漠赛道是一个活跃的测试和比赛场地，地精和侏儒工程师们会将实验性火箭车推向危险的极限。盐碱地上经常发生剧烈的撞车和突发的爆炸，将结构碎片、齿轮和气缸抛洒在广阔的区域内。",al={"为什么沙漠里有赛车零件","闪光平原残骸","破损的火箭车"}},{q="克拉维尔如何处理这些损毁的零件？",a="克拉维尔·浓须将收集到的废料清理干净，并直接典当回给侏儒和地精赛车队。这些车队不断地消耗材料，渴望买回任何能装配到下一台原型机上的装置和金属废料。",al={"克拉维尔想要这些零件做什么","为什么收集赛车零件"}},{q="这些零件在哪里？",a="这些零件散落在闪光平原开阔的沙漠地面上，环绕着中央的赛车营地。它们看起来像是丢弃的机械废料堆、扭曲的齿轮、气缸和压扁的金属板。",al={"在哪里寻找火箭车零件","零件位置","闪光平原的赛车零件"}},{q="这个任务与其他赛道周围的任务有关联吗？",a="是的。在穿越广阔的盐碱地时，拾荒与清理当地野生生物（如收集毒蝎刺针、采集龟壳，以及清理当地的秃鹫和蛇颈龙）等其他赛道赞助人的任务是自然结合的。",al={"赛道任务","闪光平原狩猎任务","与火箭车零件有关的任务"}},{q="卷入这些事故的车手们结局如何？",a="火箭车比赛的致命性是出了名的。在整理打捞上来的废料时，克拉维尔·浓须漫不经心地注意到金属板之间夹着一只被压碎的耳朵，这突显了一个残酷的现实：许多驾驶员没能在高速试车中幸存下来。",al={"车手在撞车中能幸存吗","被压碎的耳朵","赛道飞行员死亡"}}},fx={["16d6be49"]={q="火箭车零件有什么用？",a="这些都是扭曲变形的回收物——齿轮、汽缸和金属碎片，都是高速碰撞时散落在盐碱滩上的。克拉维尔·浓须不愿让它们在盐水里锈掉，便收集起来，转手卖给焦急万分的侏儒和地精维修队。双方都急着修好撞得粉碎的赛车，并在发明上胜过对手，因此乐意买回这些废金属，焊到下一台鲁莽的玩意儿上。",al={"火箭车零件用途","火箭车零件有什么用","为什么收集火箭车零件"}}},fp="16,378,24.464.0,30.467.0,24.272.0,63.294.0,43.255.0,30.225.0,56.256.0,53.243.0"}
P.entries["quest:1111"] = {n="码头管理员迪兹维格",s="克拉维尔·浓须是沙漠赛道的一名矮人，他的工作是确保人们能拿到他们需要的东西。那里的侏儒正在等待一批一周前就已抵达棘齿城的零件，但克拉维尔无法亲自前往。他指派你去棘齿城，将他的零件订单交给码头管理员迪兹维格。",h="克拉维尔·浓须是沙漠赛道的一名矮人，他的工作是确保人们能拿到他们需要的东西。那里的侏儒正在等待一批一周前就已抵达棘齿城的零件，但克拉维尔无法亲自前往。他指派你去棘齿城，将他的零件订单交给码头管理员迪兹维格。",kw={"克拉维尔·浓须","沙漠赛道","零件订单","棘齿城","千针石林","码头管理员迪兹维格"},sec={{t="为克拉维尔跑腿",b="克拉维尔·浓须负责确保人们能拿到他们需要的东西。沙漠赛道的侏儒们正在等待一批一周前就已抵达棘齿城的零件，但克拉维尔无法亲自前往。他请求你代劳跑腿，并承诺如果你完成任务，未来会有更多利润丰厚的工作。"},{t="棘齿城码头",b="棘齿城位于贫瘠之地。你应该去找地精码头管理员迪兹维格，克拉维尔说迪兹维格通常会在码头。你需要把克拉维尔的零件订单带到那里。"}},faq={{q="是谁让你去找码头管理员迪兹维格的？",a="克拉维尔·浓须，一位身处千针石林沙漠赛道的矮人，他给了你零件订单并让你前往棘齿城。",al={"谁指派码头管理员迪兹维格的任务","克拉维尔·浓须任务"}},{q="在哪里可以找到码头管理员迪兹维格？",a="码头管理员迪兹维格是一名地精，克拉维尔认为在贫瘠之地的棘齿城码头可以找到他。",al={"迪兹维格位置","迪兹维格在哪里","去哪里找迪兹维格"}},{q="克拉维尔的订单有什么用？",a="沙漠赛道的侏儒们正在等待一批一周前就已抵达棘齿城的零件。克拉维尔无法亲自前往，所以他请求你将订单带到那里的码头。",al={"零件是用来做什么的","为什么要去棘齿城"}},{q="完成码头管理员迪兹维格的任务后接下来做什么？",a="任务链的下一步是“给克拉维尔的零件”。",al={"迪兹维格之后的后续任务","what comes next"}}},fp="20,272,18.302.0,20.173.0,38.120.0,40.109.0,38.166.0,38.47.0"}
P.entries["quest:1112"] = {n="给克拉维尔的零件",s="你已经把克拉维尔·浓须的零件订单带给了码头管理员迪兹维格，现在你正带着克拉维尔的包裹返回闪光平原的沙漠赛道。迪兹维格还捎带了一个口信：如果克拉维尔想要更多的特殊订单，他就必须结清他的欠款。",h="你已经把克拉维尔·浓须的零件订单带给了码头管理员迪兹维格，现在你正带着克拉维尔的包裹返回闪光平原的沙漠赛道。迪兹维格还捎带了一个口信：如果克拉维尔想要更多的特殊订单，他就必须结清他的欠款。",kw={"克拉维尔·浓须","沙漠赛道","零件订单","闪光平原","千针石林","码头管理员迪兹维格"},sec={{t="包裹与欠款",b="码头管理员迪兹维格交给你一个包裹，让你转交给身处千针石林闪光平原沙漠赛道的克拉维尔·浓须。迪兹维格让你顺便转告他：如果克拉维尔还想再下特殊订单，他就得先把欠款付清。"},{t="克拉维尔的欢迎",b="克拉维尔很高兴包裹送到了，并说这些零件还需要送到地精手中。不过，他先把板条箱放下，从中拿出一件小东西塞进了口袋。"}},faq={{q="是谁把克拉维尔的包裹交给你的？",a="棘齿城的码头管理员迪兹维格把包裹交给你，并让你把它带回给克拉维尔·浓须。",al={"谁开启零件订单任务","零件来自哪里","零件订单任务发布者"}},{q="克拉维尔·浓须在哪里等待交货？",a="克拉维尔在千针石林的闪光平原上的沙漠赛道。",al={"克拉维尔·浓须的位置","克拉维尔在哪里","去哪里交付零件订单"}},{q="迪兹维格想要连同零件一起传达什么口信？",a="迪兹维格让你转告克拉维尔，如果他想要更多的特殊订单，就必须结清他的欠款。",al={"迪兹维格说了什么","迪兹维格给克拉维尔的口信","克拉维尔的欠款"}},{q="在这次交付之前发生了什么？",a="这是在你把克拉维尔的零件订单送到棘齿城的码头管理员迪兹维格手中之后的后续步骤。",al={"零件订单的前置条件","零件订单的上一个任务"}}},fp="16,266,19.266.0,16.173.1,37.104.0,47.76.0,62.96.0,31.99.0"}
P.entries["quest:1114"] = {n="侏儒的货物",s="克拉维尔·浓须现在得到了他需要的东西，他希望你把精密赛车零件送到闪光平原的菲兹尔·铜栓那里，他已经等了很久了。克拉维尔承认他从菲兹尔的订单里拿走了一个小零件，并建议你不要提起这件事。",h="克拉维尔·浓须现在得到了他需要的东西，他希望你把精密赛车零件送到闪光平原的菲兹尔·铜栓那里，他已经等了很久了。克拉维尔承认他从菲兹尔的订单里拿走了一个小零件，并建议你不要提起这件事。",kw={"精密赛车零件","给地精的快递","菲兹尔·铜栓","液压棘轮","克拉维尔·浓须","沙漠赛道","中继螺栓","闪光平原","千针石林"},sec={{t="留下的零件",b="克拉维尔·浓须告诉你，这些零件是给菲兹尔·铜栓的，他已经等了很久了。克拉维尔承认他从菲兹尔的订单里拿走了一个小零件，但觉得应该不会被发现。他称那个零件又小又不值钱，建议你不要提起它，并让你相信他。"},{t="菲兹尔的评价",b="菲兹尔·铜栓很高兴地收下了包裹：他的液压棘轮和中继螺栓终于到了，这些零件应该足够用了。"}},faq={{q="谁把零件送给菲兹尔·铜栓？",a="沙漠赛道的克拉维尔·浓须。他让你把这些零件送到菲兹尔·铜栓那里。",al={"谁给予给地精的快递任务","给地精的快递任务发放者","谁发送了这些零件"}},{q="克拉维尔·浓须从包裹里拿走了什么？",a="克拉维尔说他从菲兹尔的订单里拿走了一个小零件，他称其又小又不值钱，并希望你不要向菲兹尔提起这件事。",al={"克拉维尔拿走了什么","零件中缺少什么","克拉维尔偷了零件"}},{q="这批货物要送到哪里？",a="送到闪光平原的菲兹尔·铜栓那里，就在沙漠赛道所在的同一片平原上，那里也是克拉维尔·浓须所在的地方。",al={"给地精的快递地点","菲兹尔·铜栓在哪里","闪光平原快递"}},{q="在这批货物之前发生了什么？",a="这是紧接“给克拉维尔的零件”之后的任务，在那个任务中，你把克拉维尔的包裹从棘齿城带回给了他。",al={"给地精的快递的前置任务","什么任务通往给地精的快递"}}},fp="22,263,16.299.0,16.130.1,41.96.0,48.150.0,28.119.0,31.94.0"}
P.entries["quest:1115"] = {n="车手的传闻",s="在为侏儒们提供了一项服务之后，克拉维尔·浓须现在想帮地精们一个忙。他听说地精赛车手Nazz Steamboil曾经用过另一个名字，他想知道这是否是一个有利可图的秘密。他让你去找藏宝海湾的克拉兹克，因为他会知道真相。",h="在为侏儒们提供了一项服务之后，克拉维尔·浓须现在想帮地精们一个忙。他听说地精赛车手Nazz Steamboil曾经用过另一个名字，他想知道这是否是一个有利可图的秘密。他让你去找藏宝海湾的克拉兹克，因为他会知道真相。",kw={"藏宝海湾","克拉维尔·浓须","克拉兹克","沙漠赛道","nazz steamboil","salty sailor tavern","闪光平原","荆棘谷","千针石林"},sec={{t="值得打听的名字",b="克拉维尔·浓须说接下来该轮到地精们接受他的帮助了。他听说地精赛车手Nazz Steamboil曾经用过另一个名字。克拉维尔想知道这个名字为什么要改，它是否隐藏着什么秘密，以及Nazz是否想把这个秘密保守下去。克拉维尔说，知道真相的人是位于荆棘谷南端藏宝海湾的克拉兹克。有用的信息也许能赚上一笔。在Salty Sailor Tavern寻找克拉兹克。"},{t="克拉兹克的回答",b="克拉兹克知道Nazz Steamboil是闪光平原上的一名赛车手。克拉兹克说也许能查出点什么，但他警告说，这既不容易，也不快，更不便宜。"}},faq={{q="是谁让你去找克拉兹克的？",a="位于闪光平原沙漠赛道的矮人克拉维尔·浓须让你去的。",al={"谁给予传言贩子任务","传言贩子任务发布者","谁开始这个任务"}},{q="为什么克拉维尔对Nazz Steamboil感兴趣？",a="克拉维尔听说这位地精赛车手并不总是用那个名字。他想知道这是否是一个秘密，以及Nazz是否足够看重它，以至于能让自己获利。",al={"为什么调查nazz steamboil","克拉维尔调查nazz的动机","传言是什么"}},{q="在哪里可以找到克拉兹克？",a="克拉兹克在荆棘谷南端藏宝海湾的Salty Sailor Tavern里。",al={"克拉兹克位置","克拉兹克在哪里","如何找到克拉兹克"}},{q="这个任务的前置任务是什么？",a="它承接任务“给侏儒的交付”，也就是为侏儒们提供的服务。",al={"传言贩子的前置任务","传言贩子的上一个任务","哪个任务在前"}}},fp="15,277,25.442.0,15.174.1,24.88.0,43.162.0,26.88.0,23.67.0"}
P.entries["quest:1116"] = {n="梦境之尘",s="藏宝海湾的克拉兹克说，打听关于Nazz的消息可是帮了大忙。在克拉兹克联系消息来源的同时，他请你从悲伤沼泽的幼龙身上收集10份梦境之尘，好填满他的鼻烟壶。把这些带回来，克拉兹克就会给你你想要的消息。",h="藏宝海湾的克拉兹克说，打听关于Nazz的消息可是帮了大忙。在克拉兹克联系消息来源的同时，他请你从悲伤沼泽的幼龙身上收集10份梦境之尘，好填满他的鼻烟壶。把这些带回来，克拉兹克就会给你你想要的消息。",kw={"藏宝海湾","梦境之尘","克拉维尔·浓须","克拉兹克","沙漠赛道","nazz","悲伤沼泽","雏龙"},sec={{t="礼尚往来",b="克拉兹克告诉你，打听Nazz的消息可是件大人情，而且你已经为了这件事从闪光平原跑了这么远。在克拉兹克联系消息来源的同时，他需要你收集一些东西。他选中了十份梦境之尘，它们来自悲伤沼泽的幼龙，克拉兹克想要用它们来装他的鼻烟壶。一旦你带回这些东西，你就能得到那些消息。"},{t="梦境之尘的产地",b="悲伤沼泽的绿龙携带梦境之尘。幼年雏龙和梦境雏龙身上都有，它们都生活在沼泽的西南角。"}},faq={{q="谁在要梦境之尘？",a="藏宝海湾的克拉兹克在要这些东西，作为交换，他会提供关于Nazz的消息。",al={"谁给予梦境之尘任务","谁派我去悲伤沼泽","梦境之尘任务发布者"}},{q="为什么克拉兹克想要梦境之尘？",a="克拉兹克说这种粉尘是用来装鼻烟壶的，他在联系关于Nazz的消息来源时提出了这个要求。",al={"梦境之尘有什么用","为什么克拉兹克想要粉尘","梦境之尘鼻烟"}},{q="在哪里可以找到梦境之尘？",a="它们取自悲伤沼泽的幼龙，例如在沼泽西南角的幼年雏龙和梦境雏龙。",al={"哪里可以找到梦境之尘","悲伤沼泽梦境之尘在哪里","梦境之尘位置"}},{q="这件事和克拉维尔·浓须有什么联系？",a="沙漠赛道的克拉维尔·浓须派你去找克拉兹克询问地精赛车手Nazz Steamboil的事，而你是为了这个答案从闪光平原赶来的。",al={"为什么我在藏宝海湾","这与克拉维尔有什么关系","闪光平原的关联"}},{q="接下来要做什么？",a="下一步是“给克拉维尔的谣言”。",al={"梦境之尘任务之后做什么","梦境之尘后续任务","接下来是给克拉维尔的谣言"}}},fp="23,287,19.398.0,23.162.0,33.76.0,32.102.0,30.132.0,47.164.0,16.35.0"}
P.entries["quest:1117"] = {n="地精的谣言",s="克拉兹克找到了你想要的东西。在动用了人情、进行了一番推理并割舍了一瓶珍贵的精灵美酒之后，克拉兹克写了一封关于Nazz Steamboil的信。这封信对克拉兹克来说太危险了，所以他让你把它带给在闪光平原上的克拉维尔·浓须，并且要求你不要透露信的来源。",h="克拉兹克找到了你想要的东西。在动用了人情、进行了一番推理并割舍了一瓶珍贵的精灵美酒之后，克拉兹克写了一封关于Nazz...",kw={"藏宝海湾","地精谣言","克拉维尔·浓须","克拉兹克","沙漠赛道","nazz steamboil","给克拉维尔的谣言","闪光平原","千针石林"},sec={{t="来自克拉兹克的信",b="克拉兹克告诉了你这次搜寻的代价：用掉了一些人情，割舍了一瓶珍贵的精灵美酒，还进行了一番大量的推理。结果就是这封信，里面写着一些关于Nazz Steamboil的非常有意思的信息。克拉兹克觉得这封信太危险了，不想利用它，便交给你由你全权处理，只要不让任何人知道信是从哪儿来的就行。它得送回到在闪光平原上的克拉维尔·浓须那里。"},{t="克拉维尔的定论",b="克拉维尔觉得这封信非常有趣。他寻思着下次见到那位地精飞行员时，也许应该向他鞠个躬，并期待Nazz能拿出一大笔钱来让这个秘密永远沉寂下去。"}},faq={{q="这个任务从哪开始？",a="在你带来梦境之尘后，克拉兹克会在藏宝海湾交给你这封信。",al={"谁发布了给克拉维尔的谣言","给克拉维尔的谣言起始任务","谣言从哪获得"}},{q="这封信应该带给谁？",a="带给在千针石林的闪光平原沙漠赛道上的克拉维尔·浓须。",al={"去哪交还给克拉维尔的谣言","谁接收地精谣言","克拉维尔·浓须在哪"}},{q="克拉兹克的发现对象是谁？",a="地精赛车手Nazz Steamboil。克拉兹克在信中写下了一些关于Nazz的非常有意思的信息。",al={"nazz steamboil是谁","谣言内容是什么","谣言针对谁"}},{q="克拉兹克是如何发现这些信息的？",a="克拉兹克动用了一些人情，进行了一番深度的推理，并割舍了一瓶珍贵的精灵美酒。",al={"克拉兹克怎么得到的信息","克拉兹克的人情"}},{q="接下来要做什么？",a="该任务线的下一步是回到藏宝海湾。",al={"给克拉维尔的谣言后的任务","给克拉维尔的谣言后续"}}},fp="17,326,20.418.0,16.192.1,22.73.0,37.91.0,40.110.0,39.97.0,16.48.0"}
P.entries["quest:1118"] = {n="返回藏宝海湾",s="克拉维尔·浓须相信你能完成任务并守口如瓶。他有一个新计划，虽然有风险，但承诺你们俩都能赚上一大笔。你要把他的信带给藏宝海湾的克兰克·菲兹巴布。此任务紧接在“Rumors for Kravel”之后。",h="克拉维尔·浓须相信你能完成任务并守口如瓶。他有一个新计划，虽然有风险，但承诺你们俩都能赚上一大笔。你要把他的信带给藏宝海湾的克兰克·菲兹巴布。此任务紧接在“Rumors for Kravel”之后。",kw={"藏宝海湾","克兰克·菲兹巴布","克拉维尔·浓须","克拉维尔的设计图","沙漠赛道","salty sailor tavern","闪光平原","千针石林"},sec={{t="给藏宝海湾的信",b="在沙漠赛道的矮人克拉维尔·浓须称你为他可以信任的人，既能完成工作，又能守口如瓶。他的新计划存在风险，但如果成功，你们俩都能赚上一大笔。他为让你再次回到之前任务去过的藏宝海湾表示歉意，并请求你在那里找到克兰克·菲兹巴布并交给他一封信。如果克兰克需要帮助，克拉维尔希望你尽力而为，并说这会是值得的。"},{t="克兰克阅读计划书",b="克兰克·菲兹巴布读了这封信，发现克拉维尔计划了一个宏大的阴谋。克兰克很欣赏克拉维尔邪恶的头脑。这个计划需要某种强大的东西来扰乱心智，克兰克想知道赞吉尔的药剂是否能派上用场。"}},faq={{q="这段旅程从哪里开始，到哪里结束？",a="它始于千针石林沙漠赛道的克拉维尔·浓须。你要把他的信带给在荆棘谷藏宝海湾的Salty Sailor Tavern里的克兰克·菲兹巴布。",al={"我该去哪","谁给予回到藏宝海湾任务","克兰克·菲兹巴布在哪里"}},{q="之前发生了什么？",a="此任务紧接在“Rumors for Kravel”之后，这是之前让你前往藏宝海湾的步骤。",al={"前置任务","上一个任务","哪个任务是第一个"}},{q="什么是克拉维尔的设计图？",a="这就是你带给克兰克·菲兹巴布的信。克拉维尔称他的计划有风险，并说如果成功，你们俩都能赚上一大笔。",al={"什么是克拉维尔的设计图","克拉维尔的设计图信件"}},{q="如果克兰克·菲兹巴布需要帮助，你应该怎么做？",a="克拉维尔请求你尽力帮助他，并说这会是值得的。",al={"帮助克兰克","克兰克需要援助吗"}},{q="接下来是什么？",a="任务线接下来是赞吉尔的药剂和Fool's Stout。",al={"下一个任务","回到藏宝海湾之后是什么"}}},fp="17,233,22.462.0,22.254.1,38.193.0,22.74.0,24.142.0,49.80.0,22.61.0"}
P.entries["quest:1119"] = {n="赞吉尔的药剂和蠢人酒",s="克兰克·菲兹巴布发现，将赞吉尔的药剂掺入黑啤酒中会制成一种烈性饮料，叫做“傻子黑啤”。他认为这正是克拉维尔所需要的。你必须将它带给闪光平原沙漠赛道的克拉维尔·浓须，而且动作要快，因为它无法保持新鲜。",h="克兰克·菲兹巴布发现，将赞吉尔的药剂掺入黑啤酒中会制成一种烈性饮料，叫做“傻子黑啤”。他认为这正是克拉维尔所需要的。你必须将它带给闪光平原沙漠赛道的克拉维尔·浓须，而且动作要快，因为它无法保持新鲜。",kw={"藏宝海湾","菲兹巴布","克拉维尔","药剂","赛道","闪光平原","黑啤","赞吉尔"},sec={{t="给克拉维尔的饮品",b="克兰克·菲兹巴布发现将赞吉尔的药剂掺入黑啤酒中，能制成一种烈性饮料：傻子黑啤。克兰克认为这正是克拉维尔所需要的，并想知道效果如何。你必须把它带回给闪光平原沙漠赛道的克拉维尔·浓须。"},{t="不要让它久放",b="克兰克警告你不要把这桶黑啤拿在手里太久。这种混合物会对黑啤里的酵母产生奇特的影响，使其处于高度活跃状态，所以这种饮料无法长久保持新鲜。"}},faq={{q="谁让你去送这个快递？",a="藏宝海湾的克兰克·菲兹巴布把傻子黑啤交给你，让你带走。",al={"赞吉尔的药剂与傻子黑啤任务发布者","任务发布者"}},{q="谁会收到傻子黑啤？",a="千针石林闪光平原沙漠赛道的克拉维尔·浓须。",al={"谁接收黑啤","哪里交任务","克拉维尔位置"}},{q="为什么这种饮料需要快速送达？",a="因为这种混合物会强烈催化酵母，如果黑啤放置太久就会变质。",al={"傻子黑啤会过期吗","为什么有时间限制","发酵效果"}},{q="在此之前发生了什么？",a="它紧接着“回到藏宝海湾”和“赞吉尔的秘密”任务之后。",al={"前置任务","上一步骤"}},{q="送完黑啤之后要做什么？",a="任务链接下来是“傻子黑啤”、“把侏儒灌醉”和“把地精灌醉”。",al={"下一个任务","接下来发生什么"}}},fp="35,279,21.273.0,17.178.0,31.65.0,30.84.0,48.77.0,22.49.0,38.86.0"}
P.entries["quest:112"] = {n="收集海藻",s="“采集海藻”是闪金镇的药剂师威廉·匹斯特委托的一项差事，旨在帮助一对苦命的年轻情侣。为了给梅贝尔·马科伦酿造一瓶隐形水，匹斯特派遣冒险者从盘踞在水晶湖周围的鱼人手中夺取稀有的海洋植物。",h="“采集海藻”是闪金镇的药剂师威廉·匹斯特委托的一项差事，旨在帮助一对苦命的年轻情侣。为了给梅贝尔·马科伦酿造一瓶隐形水，匹斯特派遣冒险者从盘踞在水晶湖周围的鱼人手中夺取稀有的海洋植物。",kw={"采集海藻","水晶海藻","水晶湖","闪金镇","隐形水","梅贝尔·马科伦","鱼人","托米·乔·斯通菲尔德","威廉·匹斯特"},ang={["faction:Alliance"]="为匹斯特的怪差事清理水晶湖周围的鱼人营地，也有助于平息一个对闪金镇东部道路造成威胁的危险隐患。",["profession:Herbalism"]="对于采集者来说，水晶海藻是一个奇特的异类：这种本应生长在海洋里的草药，不是从土壤或海床中采集，而是直接从淡水鱼人的拾荒袋中抢夺而来。"},sec={{t="禁忌之恋的良药",b="斯通菲尔德家族与马科伦家族之间的积怨，使得年轻的托米·乔·斯通菲尔德和梅贝尔·马科伦无法公开见面。为了能在不引发双方家族武装冲突的前提下见到爱人，梅贝尔寻求了一种非同寻常的解决方案：悄无声息地溜过山谷。威廉·匹斯特，这位在闪金镇Lion's Pride Inn经营的古怪药草师兼药剂师，制定了一个酿造隐形水的计划。然而，调制这种难以捉摸的药剂需要一些在Lion's Pride Inn的储藏室里找不到的稀有试剂。"},{t="水晶湖的拾荒者",b="匹斯特酿造药剂必不可少的催化剂是水晶海藻。虽然这种植物通常生长在遥远的咸水海洋中，但位于闪金镇以东的水晶湖岸边却被部落鱼人所占据。出于某种只有它们自己才懂的古怪本能，这些栖息在岸边的拾荒者将大量海洋水晶海藻拖到了内陆的简陋营地中。想要收集足够的叶片，就必须杀出一条血路，攻破这些两栖怪物的巢穴，从它们的爪牙中抢夺植物，然后再回到闪金镇蒸馏药水。"}},faq={{q="为什么威廉·匹斯特需要水晶海藻？",a="威廉·匹斯特需要水晶海藻作为酿造隐形水的主要试剂。这种药剂旨在让梅贝尔·马科伦能够神不知鬼不觉地溜出她家族的葡萄园，去见托米·乔·斯通菲尔德。",al={"为什么需要水晶海藻","海藻的用途","威廉·匹斯特的材料"}},{q="为什么在淡水湖水晶湖附近会有海洋海藻？",a="水晶海藻自然生长在海洋中，但盘踞在水晶湖的鱼人部落会进行搜寻并将这种植物运往内陆。它们将叶片囤积在湖边的营地里，使其成为闪金镇附近唯一的来源。",al={"为什么水晶湖会有海藻","淡水中的海藻","鱼人海藻传说"}},{q="梅贝尔·马科伦和托米·乔·斯通菲尔德是谁？",a="梅贝尔和托米·乔是来自艾尔文森林南部敌对农场主家庭的年轻恋人。由于他们的家族彼此仇视，这对情侣不得不诉诸秘密手段和炼金诡计才能交谈。",al={"梅贝尔是谁","托米·乔是谁","马科伦与斯通菲尔德的世仇"}},{q="水晶湖在哪里？",a="水晶湖位于艾尔文森林中部，闪金镇的正东方。它的水域和周边地区被充满敌意的鱼人严重侵扰。",al={"水晶湖在哪里","水晶湖位置","寻找水晶湖"}},{q="收集完海藻后会发生什么？",a="一旦你交付了四片水晶海藻，威廉·匹斯特就会将它们蒸馏成隐形水。随后，他会指派你将调制好的药剂送到梅贝尔·马科伦手中，这样她就能完成秘密的私奔。",al={"海藻任务后续","匹斯特制作什么"}},{q="威廉·匹斯特是谁？",a="威廉·匹斯特是一位药剂师和炼金术爱好者，常驻在闪金镇的Lion's Pride Inn。他为当地人提供民间偏方、奇特药剂和保密委托。",al={"威廉·匹斯特是谁","闪金镇匹斯特"}}},fp="15,158,27.434.0,30.410.0,42.183.0,53.210.0,49.211.0,30.112.0,39.178.0,22.170.0"}
P.entries["quest:1120"] = {n="灌醉侏儒",s="克拉维尔·浓须想在沙漠赛道的维修车队上测试一下Fool's Stout。如果你选择侏儒，你就把烈酒带给侏儒车队老板。这种烈酒最终会变质，所以克拉维尔让你别拖太久。",h="克拉维尔·浓须想在沙漠赛道的维修车队上测试一下Fool's Stout。如果你选择侏儒，你就把烈酒带给侏儒车队老板。这种烈酒最终会变质，所以克拉维尔让你别拖太久。",kw={"fool's stout","侏儒车队老板","克拉维尔·浓须","沙漠赛道","千针石林","zanzil"},sec={{t="A Test on the Pit Crews",b="克拉维尔·浓须需要有人在维修车队上试用Fool's Stout。你可以选择在侏儒身上进行测试：他把烈酒交给你，并让你送到附近的沙漠赛道去找侏儒车队老板。选择侏儒会使比赛的天平向地精倾斜。克拉维尔警告你不要磨蹭，因为烈酒最终会变质。"},{t="A Little Drink Before the Race",b="侏儒车队老板对这份礼物感到很高兴，并称其考虑得很周到。车队老板承认，比赛在即，喝酒并不明智，但车队队员们也许能喝一点。毕竟，这酒应该没那么烈。"}},faq={{q="谁让你去送这瓶烈酒的？",a="克拉维尔·浓须，那个位于千针石林沙漠赛道的矮人，他把烈酒交给了你。",al={"谁给予get the gnomes drunk任务","get the gnomes drunk任务给予者","克拉维尔·浓须任务"}},{q="Fool's Stout应该交给谁？",a="交给侏儒车队老板，他在沙漠赛道附近。",al={"我要把烈酒带去哪里","谁会得到fool's stout","侏儒车队老板位置"}},{q="如果送烈酒送得太久会怎么样？",a="烈酒最终会变质，所以克拉维尔让你别等太久。",al={"fool's stout会过期吗","烈酒计时器","fool's stout会变质"}},{q="你可以选择去针对地精吗？",a="可以。克拉维尔让你选择在哪支维修车队上测试烈酒，另一个选择是Get the Goblins Drunk。",al={"get the goblins drunk选项","我可以改让地精喝醉吗","侏儒还是地精沙漠赛道"}},{q="在此之前需要做什么？",a="它紧接在赞吉尔的药剂和Fool's Stout之后。",al={"前置任务","get the gnomes drunk的前置任务"}},{q="烈酒送达后接下来做什么？",a="任务链继续进行，接下来是Report Back to Fizzlebub。",al={"后续任务","get the gnomes drunk之后是什么"}}},fp="20,222,23.338.0,30.214.1,34.91.0,45.59.0,55.75.0,45.108.0,23.47.0,40.50.0"}
P.entries["quest:1121"] = {n="灌醉地精",s="克拉维尔·浓须想要让沙漠赛道的一个维修车队测试一下傻子烈酒。如果你选择了地精，你就必须把烈酒带给地精车队老板。烈酒放久了会变质，所以克拉维尔让你别耽搁太久。",h="克拉维尔·浓须想要让沙漠赛道的一个维修车队测试一下傻子烈酒。如果你选择了地精，你就必须把烈酒带给地精车队老板。烈酒放久了会变质，所以克拉维尔让你别耽搁太久。",kw={"傻子烈酒","侏儒","地精","地精车队老板","克拉维尔·浓须","沙漠赛道","千针石林"},sec={{t="对维修车队的测试",b="克拉维尔·浓须需要让其中一个维修车队试喝一下傻子烈酒。你可以让地精们喝：他会把酒交给你，并让你送到附近的沙漠赛道去找地精车队老板。选择地精会让比赛的天平向侏儒倾斜。克拉维尔警告你不要磨蹭，因为烈酒最后会变质。"},{t="喝一点没关系",b="地精车队老板看到有酒送上门，并不介意喝上一小口。"}},faq={{q="谁提供这个任务？",a="克拉维尔·浓须，位于千针石林沙漠赛道的那个矮人。",al={"任务发布者","谁发布了让地精喝醉","克拉维尔·浓须"}},{q="烈酒必须送到哪里？",a="送到附近沙漠赛道上的地精车队老板那里。",al={"把烈酒带到哪里","地精车队老板位置"}},{q="如果你等得太久会发生什么？",a="烈酒最终会变质，所以克拉维尔让你别耽搁太久。",al={"烈酒会变质吗","傻子烈酒持续时间","烈酒变质"}},{q="这个任务有什么替代方案吗？",a="克拉维尔让你选择让哪个维修车队尝试烈酒。另一个选择是“让侏儒喝醉”，对象是侏儒车队。",al={"选择让侏儒喝醉","赛道上的侏儒还是地精"}},{q="这个任务之前是什么？",a="它紧接在“赞吉尔的药剂”和“傻子烈酒”之后。",al={"前置任务","让地精喝醉的前置条件"}},{q="烈酒送达之后是什么任务？",a="任务链会继续到“向菲兹鲁布报告”。",al={"后续任务","让地精喝醉之后是什么"}}},fp="21,224,23.340.0,19.74.1,16.70.0,30.60.0,34.75.0,32.119.0,23.47.0,40.50.0"}
P.entries["quest:1122"] = {n="向菲兹巴布报告",s="克拉维尔·浓须说“傻子烈酒”非常管用。他在下一场比赛中下了注，希望你灌醉的那支车队会毁掉他们自己的赛车。你带着一张关于测试成功的便条前往藏宝海湾找克兰克·菲兹巴布。这是在你选择灌醉那支维修车队之后发生的。",h="克拉维尔·浓须说“傻子烈酒”非常管用。他在下一场比赛中下了注，希望你灌醉的那支车队会毁掉他们自己的赛车。你带着一张关于测试成功的便条前往藏宝海湾找克兰克·菲兹巴布。这是在你选择灌醉那支维修车队之后发生的。",kw={"藏宝海湾","克兰克·菲兹巴布","傻子烈酒","克拉维尔·浓须","沙漠赛道","闪光平原","千针石林"},sec={{t="给克兰克的便条",b="克拉维尔·浓须说“傻子烈酒”非常管用。他在下一场比赛中下了注，希望你灌醉的那支维修车队会毁掉他们自己的赛车。还剩下一项工作：带着一张关于测试成功的便条前往藏宝海湾交给克兰克·菲兹巴布，他会想知道这个消息的。克拉维尔还希望能在以后的比赛中得到更多的烈酒。"},{t="克兰克的回答",b="克兰克·菲兹巴布读了便条，称测试非常成功，并为这个消息感到高兴。如果你以后还需要更多的烈酒，克兰克说尽管开口，你就可以准备去收集更多的赞吉尔的药剂了。"}},faq={{q="谁开启了这个任务？",a="位于千针石林闪光平原沙漠赛道的矮人克拉维尔·浓须，把便条交给了你。",al={"任务发布者","谁发布向菲兹巴布报告任务"}},{q="克兰克·菲兹巴布在哪里？",a="在藏宝海湾。",al={"菲兹巴布位置","克兰克·菲兹巴布在哪里","任务交付地点"}},{q="这个任务之前有什么任务？",a="它紧接着“灌醉侏儒”或者（如果你选择了另一支车队的话）“灌醉地精”。",al={"前置条件","上一个任务"}},{q="克拉维尔·浓须想让菲兹巴布知道什么？",a="测试非常成功。",al={"报告的内容是什么","报告具体内容"}}},fp="24,268,16.332.0,14.201.1,16.114.0,33.13.0,23.87.0,50.28.0"}
P.entries["quest:1127"] = {n="蠢人酒",s="藏宝海湾的克兰克·菲兹巴布为那些希望回到闪光平原赛道的旅行者们酿造一批批的愚人烈酒。为了调制新的一份，他需要十二瓶赞吉尔的药剂。",h="藏宝海湾的克兰克·菲兹巴布为那些希望回到闪光平原赛道的旅行者们酿造一批批的愚人烈酒。为了调制新的一份，他需要十二瓶赞吉尔的药剂。",kw={"藏宝海湾","克兰克·菲兹巴布","愚人烈酒","赛道","荆棘谷","赞吉尔的药剂"},sec={{t="第二批",b="对于那些初始的愚人烈酒在到达赛道的侏儒那里之前就已经过期的旅行者，克兰克·菲兹巴布提出可以为其补酿。位于藏宝海湾的地精克兰克·菲兹巴布需要十二瓶赞吉尔的药剂来再次调配这种烈酒，他会补偿任何愿意去取原料的人，并会额外给一点报酬以保持交易的隐秘。"}},faq={{q="谁提供愚人烈酒的酿造？",a="位于荆棘谷南部的藏宝海湾里的克兰克·菲兹巴布负责调配这种烈酒。",al={"谁提供愚人烈酒","愚人烈酒任务发放者","克兰克·菲兹巴布"}},{q="克兰克·菲兹巴布需要什么原料？",a="他需要十二瓶赞吉尔的药剂来酿造下一批烈酒。",al={"愚人烈酒需要什么物品","愚人烈酒原料","赞吉尔的药剂需求"}},{q="为什么有人会需要再来一批愚人烈酒？",a="这种合剂在两小时后就会挥发，所以错过这段时间的旅行者必须收集新鲜的原料来进行更换。",al={"为什么要再次获取愚人烈酒","愚人烈酒过期","愚人烈酒持续时间"}},{q="这批酒打算送到哪里去？",a="这批酒是给赛道上的侏儒准备的。",al={"愚人烈酒送到哪里","谁喝愚人烈酒","愚人烈酒目的地"}}},fp="12,198,14.393.0,32.91.0,43.81.0,53.125.0,33.48.0"}
P.entries["quest:113"] = {n="昆虫研究",s="炼金师匹斯特苏格已经完成了关于虫壳的报告，并说高级勘探员菲兹杜瑟必须立即过目。这个威胁正笼罩着塔纳利斯和加基森，如果置之不理，整个卡利姆多南部都将面临危机。",h="炼金师匹斯特苏格已经完成了关于虫壳的报告，并说高级勘探员菲兹杜瑟必须立即过目。这个威胁正笼罩着塔纳利斯和加基森，如果置之不理，整个卡利姆多南部都将面临危机。",kw={"菲兹杜瑟","加基森","加基森水业公司","虫壳分析","匹斯特苏格","报告","塔纳利斯"},sec={{t="严峻的警告",b="匹斯特苏格坚持认为高级勘探员菲兹杜瑟必须立刻看到这份报告，而且每个识字的人也都应该看看。这个威胁对于塔纳利斯和加基森来说是严峻而重大的，如果置之不理，它将危及整个卡利姆多南部。它甚至可能蔓延到整个艾泽拉斯，因为目前没有任何减弱的迹象。你受托将报告送到加基森交给菲兹杜瑟，并制作一份副本，以便与你的盟友自由分享。每个人都必须了解这个威胁。"},{t="金钱问题",b="菲兹杜瑟感谢你的送件，也感谢你为加基森水业公司所做的辛勤工作。菲兹杜瑟并不喜欢把公司有价值的信息分发给所有人，因为人们通常会花重金购买这些信息。但菲兹杜瑟认识匹斯特苏格已久，既然匹斯特苏格建议让大家知情，那就照办吧。他为你制作了一份副本。"}},faq={{q="谁发送了报告，谁又是接收者？",a="炼金师匹斯特苏格把报告交给你，并让你把它送到加基森交给高级勘探员菲兹杜瑟。",al={"谁给予虫壳分析","向谁交付虫壳分析","在哪里递送报告"}},{q="为什么炼金师匹斯特苏格如此惊慌？",a="匹斯特苏格称这对塔纳利斯和加基森构成了严重而重大的威胁，如果置之不理，它将危及整个卡利姆多南部乃至整个艾泽拉斯，而且目前没有任何减弱的迹象。",al={"匹斯特苏格的警告","虫壳报告的内容","为什么虫害威胁严重"}},{q="为什么你需要这份报告的副本？",a="匹斯特苏格希望每个人都知道这个威胁，所以菲兹杜瑟制作了一份副本，你可以把它在你的人民之间自由传阅。",al={"为什么要复制报告","菲兹杜瑟的报告副本","为什么要分享报告"}},{q="在这次递送之前进行了什么？",a="它紧随名为“虫壳分析”的前续步骤之后。",al={"前置任务","之前的任务是什么"}}},fp="20,212,15.495.0,16.367.1,41.109.0,39.185.0,37.145.0,41.59.0"}
P.entries["quest:1130"] = {n="梅洛的关注",s="“梅洛发来的口信”是贫瘠之地的乔恩·天眼代表著名猎人梅洛·石蹄所传达的一份征召令。在卡利姆多各地证明了自己的实力并逐渐崛起的冒险者，会被指引前往雷霆崖的猎人高地，去接受一项难度极高的试炼。",h="“梅洛发来的口信”是贫瘠之地的乔恩·天眼代表著名猎人梅洛·石蹄所传达的一份征召令。在卡利姆多各地证明了自己的实力并逐渐崛起的冒险者，会被指引前往雷霆崖的猎人高地，去接受一项难度极高的试炼。",kw={"贫瘠之地","陶拉祖营地","猎人高地","乔恩·天眼","梅洛发来的口信","梅洛·石蹄","钢牙","雷霆崖"},ang={["class:Hunter"]="梅洛·石蹄是牛头人兽王之道的典范，他要求精准、耐心，并对危险的猎物怀有绝对的敬畏。",["faction:Horde"]="陶拉祖营地和雷霆崖依靠训练有素的野外人员来处理那些侵扰部落补给路线和哨所的危险掠食者。",["race:Tauren"]="对于牛头人来说，回应梅洛的召唤是成年礼和地位提升的传统仪式，这意味着证明自己对狩猎之道的掌握，并为猎人高地带来荣耀。"},sec={{t="雷霆崖的征召",b="消息在平原上流传得很快。当冒险者在贫瘠之地及其周边地区初露锋芒时，一些著名的猎人便会注意到那些展露出真正潜力的后起之秀。时刻关注着各个路口和营地的乔恩·天眼，担任着猎人高地长者们的信使。他会拦截下那些前途无量的猎人和战士，告知他们牛头人中备受尊崇的导师梅洛·石蹄已经为他们指明了一条特殊的道路。"},{t="狩猎之路",b="当冒险者登上雷霆崖的猎人高地时，便会见到梅洛本人。这位长者猎人并不会夸奖他们，而是询问冒险者是否拥有深入危险而遥远的荒野的决心。回应这一征召将开启通往莫高雷安全边界之外的试炼场，让猎人去对抗整个大陆上最凶猛的掠食者。"}},faq={{q="梅洛·石蹄是谁？",a="梅洛·石蹄是一位驻守在雷霆崖猎人高地的老练牛头人猎人。他负责评估部落中崭露头角的追踪者和战士，并派遣合格的候选人前往卡利姆多各地去追踪和狩猎那些臭名昭著的野兽。",al={"梅洛","梅洛是谁","梅洛·石蹄背景故事"}},{q="是谁传达了这份征召令？",a="驻扎在贫瘠之地陶拉祖营地的牛头人兽王乔恩·天眼负责传递这条消息。他负责守望旅行者，并将那些已经证明自己勇气的冒险者送往雷霆崖，直接与梅洛会谈。",al={"谁开启任务","乔恩·天眼","谁派人找我"}},{q="我在哪里可以找到梅洛·石蹄？",a="梅洛位于猎人高地，那是雷霆崖南部专门供牛头人猎人、追踪者和兽王使用的平顶山。",al={"梅洛位置","梅洛在哪里","雷霆崖猎人高地"}},{q="梅洛为我规划了什么样的道路？",a="梅洛会派遣你进行极具挑战性的追踪探险，以此来测试你的耐力和狩猎本能。首先便是前往千针石林，狩猎那头凶残的鬣狗暴君——钢牙。",al={"梅洛想要什么","梅洛发来的口信后的任务","梅洛任务线"}},{q="为什么梅洛要从贫瘠之地招募冒险者？",a="在贫瘠之地残酷的掠食者、野猪人和半人马的威胁下生存下来，足以证明一名冒险者具备了进行精英狩猎所必需的本能。梅洛正在寻找那些能够在陌生的土地上追踪难以捉摸且致命的猎物的人。",al={"为什么是我","为什么梅洛关心"}},{q="这项试炼只限于猎人吗？",a="虽然试炼发源于猎人高地，且旨在考验追踪者的品格，但梅洛也将挑战的对象扩展到了每一位在荒野中证明了自己实力与足智多谋的部落冒险者。",al={"这是猎人任务吗","其他职业能做吗"}}},fp="16,196,26.267.0,20.266.0,23.211.0,26.190.0,33.116.0,35.172.0,52.186.0,36.165.0"}
P.entries["quest:1131"] = {n="钢齿土狼",s="Steelsnap是由雷霆崖猎人高地的梅洛·石蹄发布的一项狩猎任务。这次狩猎背离了牛头人传统的杀戮理由，旨在消灭一只凶残的土狼，它的族群在千针石林残害着野生动物。",h="Steelsnap是由雷霆崖猎人高地的梅洛·石蹄发布的一项狩猎任务。这次狩猎背离了牛头人传统的杀戮理由，旨在消灭一只凶残的土狼，它的族群在千针石林残害着野生动物。",kw={"伊索克营地","大地母亲","猎人高地","土狼","梅洛·石蹄","steelsnap","千针石林","雷霆崖"},ang={["class:Hunter"]="击败Steelsnap能够考验追踪者在峡谷底部一众随行野兽中孤立并击杀残暴的兽群首领的能力。",["faction:Horde"]="在千针石林中开辟一条更安全的路径，可以保护重要的补给线，以及从贫瘠之地前往闪光平原的旅人。",["race:Tauren"]="对于舒哈鲁人来说，夺取野兽的生命是一件关乎精神的事情。狩猎Steelsnap是一堂极具教育意义的课程，教导人们如何清除那些造成无意义残忍、且游离于大地母亲恩典之外的野性元素。"},sec={{t="违背祝福的狩猎",b="牛头人的传统规定，夺取生命必须服务于神圣或实际的目的：为了果腹而狩猎，为了维护荣誉而狩猎，或是为了从大地母亲那里获取智慧而狩猎。梅洛·石蹄将这个猎物视为规则的一个例外。Steelsnap被视为对自然平衡的一种亵渎——它是一个残暴的暴君，散播着无意义的暴力和恐惧，而非维持生命的循环。"},{t="石林的灾星",b="Steelsnap在千针石林北部的峡谷中游荡，徘徊在伊索克营地的半人马聚居地以南。不同于独来独往的食腐动物，这只强大的野兽会带领凶猛的同伴，策划攻击行动，扰乱并残杀峡谷底部温顺的野生动物。杀死它并取回它的肋骨，便能清除它那恶毒影响对石林的侵蚀。"}},faq={{q="梅洛·石蹄为什么要杀死Steelsnap？",a="梅洛·石蹄认为Steelsnap是一个游离于大地母亲祝福之外的畸形存在。与为了果腹、荣誉或自然平衡而进行的狩猎不同，这次狩猎是一种清洗行动，旨在阻止这个残暴的掠食者恐吓温顺的野兽。",al={"为什么要杀死steelsnap","梅洛·石蹄的理由","steelsnap的动机"}},{q="在哪里可以找到Steelsnap？",a="Steelsnap徘徊在千针石林布满尘土的峡谷底部，位于该地区西北角的伊索克营地半人马聚居地以南。",al={"steelsnap的位置","在哪里找到steelsnap","寻找steelsnap"}},{q="需要带什么证据回雷霆崖？",a="你必须从被杀死的野兽身上获取钢齿土狼的肋骨，并将其呈交给位于猎人高地顶端的梅洛·石蹄。",al={"steelsnap的战利品","steelsnap的任务目标","我要拾取什么"}},{q="Steelsnap是独自战斗吗？",a="不。Steelsnap身边总是跟着其他听从它指挥的土狼，因此与它对峙将是一场危险的多目标遭遇战。",al={"steelsnap可以单刷吗","steelsnap的族群","steelsnap的小怪"}},{q="这次狩猎与传统的牛头人狩猎有什么不同？",a="虽然牛头人通常只为了果腹、追求武勇荣誉或获得精神启迪而狩猎，但这次狩猎纯粹是出于预防目的，旨在铲除一只破坏土地自然和谐的残忍野兽。",al={"牛头人的狩猎哲学","大地母亲与狩猎","狩猎的教训"}},{q="梅洛·石蹄住在哪里？",a="梅洛·石蹄居住在雷霆崖的猎人高地，他在那里指导猎人并考验经验丰富的追踪者。",al={"梅洛·石蹄的位置","梅洛在哪里","梅洛的坐标"}}},fp="9,163,27.268.0,26.275.0,47.233.0,29.85.0,49.73.0,27.56.0,56.146.0,33.110.0"}
P.entries["quest:1132"] = {n="菲欧拉·长耳",s="这个差事旨在将东部王国的联盟冒险者引入卡利姆多这片未开化的大陆。在米奈希尔港热情招募者的红衣弗林特指引下，旅行者们乘船穿越无尽之海，前往塞拉摩的旅店，向他的高等精灵联络人菲奥拉·长耳报到。",h="这个差事旨在将东部王国的联盟冒险者引入卡利姆多这片未开化的大陆。在米奈希尔港热情招募者的红衣弗林特指引下，旅行者们乘船穿越无尽之海，前往塞拉摩的旅店，向他的高等精灵联络人菲奥拉·长耳报到。",kw={"塞拉摩","船只","尘泥沼泽","菲奥拉·长耳","卡利姆多","米奈希尔港","红衣弗林特","湿地"},ang={["faction:Alliance"]="这趟旅程架起了东部王国与卡利姆多暗夜精灵领地之间的桥梁，将联盟的东方与西方边境连接在了一起。",["race:NightElf"]="菲奥拉·长耳作为抵达塞拉摩的东方盟友的正式接待代表，为他们进入卡利姆多北部的古老荒野做好准备。"},sec={{t="西行的召唤",b="对许多人类、矮人和侏儒来说，东部王国充斥着旧日的冲突和满目疮痍的土地。在熙熙攘攘的米奈希尔港，水手红衣弗林特每天都在劝说充满冒险精神的旅人们登上前往无尽之海彼岸的船只。弗林特将卡利姆多描述为一片充满财富与机遇的未开拓领域，并指引大胆的流浪者前往塞拉摩，去见见他的合伙人，一位名叫菲奥拉·长耳的精灵。"},{t="抵达塞拉摩",b="穿越大洋将旅行者带到了塞拉摩，这是尘泥沼泽海岸上的一个联盟港口。菲奥拉·长耳在镇上的旅店里等待着，接待弗林特推荐过来的访客。出于对弗林特识人眼光的信任，菲奥拉欢迎刚抵达的联盟英雄，并准备引导他们深入内陆，前往古老的灰谷森林。"}},faq={{q="菲奥拉·长耳是谁？",a="菲奥拉·长耳是一位驻扎在尘泥沼泽塞拉摩旅店里的高等精灵。她作为红衣弗林特的接待伙伴和联络人，迎接从东部王国远道而来的联盟旅行者。",al={"菲奥拉·长耳","菲奥拉是谁"}},{q="谁发布这个任务？",a="该任务由红衣弗林特发布，他是一位精力充沛的人类水手，位于湿地海岸的米奈希尔港。",al={"任务发布者","在哪里接取菲奥拉·长耳的任务","谁给予任务"}},{q="我该如何从米奈希尔港前往菲奥拉·长耳处？",a="登上停靠在米奈希尔港的客船，它将向西横跨无尽之海，直达尘泥沼泽的塞拉摩。",al={"如何到达塞拉摩","去往塞拉摩的船","从米奈希尔出发的船"}},{q="见到菲奥拉·长耳后会发生什么？",a="在塞拉摩见到你之后，菲奥拉会赞许弗林特的推荐，并提供你旅程的下一阶段任务，派遣你深入内陆前往灰谷的阿斯特兰纳。",al={"what comes next","后续任务","前往阿斯特兰纳的任务"}},{q="红衣弗林特和菲奥拉·长耳是什么关系？",a="弗林特称菲奥拉为他在海对岸的合伙人。当弗林特在东部王国物色热心的冒险者时，菲奥拉便在卡利姆多接待他们，以促进联盟的行动和深入内陆的旅程。",al={"弗林特和菲奥拉是合作伙伴吗","红衣弗林特与菲奥拉的关系"}},{q="联盟为什么要招募旅行者前往卡利姆多？",a="卡利姆多不仅代表着联盟广阔的新领土和新资源，也是前线战场，那里的暗夜精灵盟友需要援助，以保护他们的祖居之地免受部落和恶魔残党的威胁。",al={"为什么要前往卡利姆多","为什么是塞拉摩"}}},fx={["869cd7aa"]={q="红衣弗林特为什么想派你去卡利姆多？",a="红衣弗林特自视为机遇的引路人，负责鼓励米奈希尔港那些前途无量的冒险者横渡无尽之海。他自己被困在码头，满心渴望出海远航，因此肩负的职责便是寻找坚韧可靠的人，并指引他们去找高等精灵伙伴菲欧拉·长耳。她会帮助新来者站稳脚跟，投身联盟在卡利姆多日益扩大的行动。",al={"红衣弗林特的动机","为什么派我去找菲欧拉","弗林特为什么想让你完成这件事"}}},fp="14,298,18.431.0,20.337.0,22.211.0,22.125.0,51.136.0,42.156.0,67.199.0,53.213.0"}
P.entries["quest:1133"] = {n="通往阿斯特兰纳的旅途",s="“前往阿斯特兰纳”是一项联盟入门任务，引导刚抵达卡利姆多海岸的新手前往灰谷的腹地。在塞拉摩的菲奥拉·长耳的指引下，旅行者向北前往灰谷，向阿斯特兰纳的辛德瑞尔·速火报到。这标志着冒险者开始接触围绕着暗夜精灵祖传森林不断升级的冲突。",h="“前往阿斯特兰纳”是一项联盟入门任务，引导刚抵达卡利姆多海岸的新手前往灰谷的腹地。在塞拉摩的菲奥拉·长耳的指引下，旅行者向北前往灰谷，向阿斯特兰纳的辛德瑞尔·速火报到。这标志着冒险者开始接触围绕着暗夜精灵祖传森林不断升级...",kw={"灰谷","阿斯特兰纳","塞拉摩","尘泥沼泽","菲奥拉·长耳","前往阿斯特兰纳","米奈希尔港","辛德瑞尔·速火"},ang={["faction:Alliance"]="这段旅程代表着一名联盟新兵从相对安全的尘泥沼泽港口直接部署到灰谷充满争议的荒野中。",["race:Human"]="人类旅行者刚从米奈希尔港的船上下来，就迈出了深入卡利姆多内陆的第一步，履行联盟援助暗夜精灵的誓言。",["race:NightElf"]="对于暗夜精灵来说，这段旅程是回归他们被围困的腹地，与外来的盟友一起保卫灰谷的神圣枝叶。"},sec={{t="从海岸到丛林",b="乘坐渡轮从米奈希尔港抵达尘泥沼泽的联盟旅行者，往往在卡利姆多北部寻找自己的目标。在塞拉摩，菲奥拉·长耳会指引有能力的人深入内陆，前往阿斯特兰纳，这是灰谷内主要的暗夜精灵定居点。旅途沿着蜿蜒的小径，穿过古老而阴暗的树冠，直达这片饱受战争和动荡蹂躏的森林。"},{t="无需言明的推荐",b="有趣的是，菲奥拉告诉旅行者在抵达阿斯特兰纳时不必提她的名字，直言辛德瑞尔·速火并不认识她。她的职责仅仅是将新鲜的联盟人才输送到最需要的地方。抵达后，辛德瑞尔会欣然欢迎任何有能力的保卫者，并承认虽然灰谷依然令人叹为观止，但它已不再是曾经那个宁静的避难所了。"}},faq={{q="“前往阿斯特兰纳”任务在哪里开始？",a="该任务由位于尘泥沼泽海岸的塞拉摩的菲奥拉·长耳发布。她将此任务提供给从东部王国抵达并希望在卡利姆多提供帮助的联盟旅行者。",al={"前往阿斯特兰纳的任务发布者","前往阿斯特兰纳任务起始","在哪里接取前往阿斯特兰纳"}},{q="我需要在阿斯特兰纳找谁谈话？",a="你必须与驻扎在阿斯特兰纳（灰谷的联盟中心城镇）的暗夜精灵辛德瑞尔·速火交谈。",al={"在哪里交付前往阿斯特兰纳","前往阿斯特兰纳任务交付npc","辛德瑞尔·速火是谁"}},{q="为什么菲奥拉说不要提她的名字？",a="菲奥拉·长耳明确告诉冒险者不要提及是谁派他们来的，原因很简单，辛德瑞尔并不认识她。她只是在引导渴望有所作为的新手前往急需援助的前哨站。",al={"为什么不要提及菲奥拉","菲奥拉·长耳与辛德瑞尔的关系"}},{q="这个任务的目的是什么？",a="它起到了引导作用，将联盟角色从尘泥沼泽引向灰谷，并向他们介绍阿斯特兰纳，使其成为他们在森林中的主要行动基地。",al={"为什么要做前往阿斯特兰纳任务","前往阿斯特兰纳任务的背景意义"}},{q="灰谷发生了什么样的动乱？",a="正如辛德瑞尔·速火在你抵达时所指出的，灰谷已不再是曾经那片宁静的丛林。这片森林面临着来自部落的入侵、第三次战争遗留的恶魔腐蚀，以及因近期冲突而变得躁动的当地野生生物。",al={"阿斯特兰纳为什么需要帮助","灰谷的动乱背景"}},{q="什么任务引导至“前往阿斯特兰纳”？",a="在此之前有一个简短的入门引导任务，名为“菲奥拉·长耳”，该任务指示抵达尘泥沼泽的旅行者在塞拉摩与她交谈。",al={"前往阿斯特兰纳的前置任务","菲奥拉·长耳任务链"}}},fp="20,173,29.348.0,26.320.0,48.178.0,38.97.0,43.147.0,34.129.0,47.166.0,43.148.0"}
P.entries["quest:1134"] = {n="石爪山的双足飞龙",s="辛德瑞尔·速火报告了一条未经证实的消息：由于担心部落的秘密袭击，阿斯特兰纳的哨兵们试图在致命武器伤及人民之前将其拦截。来自塞拉摩的情报显示，兽人刺客正在从石爪山脉的双足飞龙身上采集剧毒，以用于秘密突袭。为了保护脆弱的边界，联盟侦察兵被派往南方，抢先采集毒囊，剥夺敌人获取这种致命毒药的机会。",h="辛德瑞尔·速火报告了一条未经证实的消息：由于担心部落的秘密袭击，阿斯特兰纳的哨兵们试图在致命武器伤及人民之前将其拦截。来自塞拉摩的情报显示，兽人刺客正在从石爪山脉的双足飞龙身上采集剧毒，以用于秘密突袭。为了保护脆弱的边界...",kw={"刺客","阿斯特兰纳","暗色湖","傲翼兽","辛德瑞尔·速火","石爪山脉","塞拉摩","毒液"},ang={["class:Druid"]="德鲁伊们经常为自然生命的损耗而哀悼，感叹无辜的生物仅仅因为要防止好战者获得它们的毒液而遭到猎杀。",["class:Rogue"]="潜行者们能够理解傲翼兽毒液的致命效用，深知在荒野的秘密伏击中，涂毒的刀刃能造成多么毁灭性的打击。",["faction:Alliance"]="这项任务展示了连接吉安娜在塞拉摩的定居点与灰谷哨兵据点之间的隐秘情报网，旨在挫败部落的侵略企图。",["race:NightElf"]="暗夜精灵们在猎杀野生傲翼兽的残酷必要性中挣扎，试图在对自然的精神守护与边境战争的严峻现实之间寻找平衡。"},sec={{t="脆弱的休战",b="虽然卡利姆多北部尚未宣布联盟与部落之间的全面战争，但两者之间的和平却如履薄冰。茂密的树冠下不断爆发小规模冲突，悄无声息的暗中打击取代了全面战争。阿斯特兰纳的哨兵指挥官们时刻警惕着敌人的秘密行动，深知一旦掉以轻心，他们所守护的避难所就可能失守。"},{t="峭壁之毒",b="辛德瑞尔·速火报告了一条未经证实的消息：从塞拉摩秘密联络人处传来的情报显示，石爪山脉的峭壁之上正在进行一场邪恶的勾当。兽人潜行者一直在暗色湖周边猎杀野生的傲翼兽，并采集这种强效生物毒剂涂抹在武器上，以便对联盟人员发动致命的伏击。为了消除这一威胁，辛德瑞尔·速火派遣勇士们去猎杀这些野兽，并在部落特工采集毒囊之前将其夺走。"},{t="痛苦的职责",b="命令消灭本土野兽让暗夜精灵们倍感沉重，他们对卡利姆多的荒野怀有深深的敬畏。辛德瑞尔本人也对无辜的生物必须为一场它们并未选择的战争而受苦感到惋惜。然而，在残酷的边境防御权衡中，阻止敌人获得致命武器要比保护生态环境更为重要。"}},faq={{q="什么是傲翼兽？",a="傲翼兽是一种危险的带毒飞行野兽，与双足飞龙有亲缘关系，它们栖息在高耸的峭壁上，尤其是在石爪山脉的暗色湖周围。它们强效的毒液使其成为致命的掠食者，也是投毒者梦寐以求的资源。",al={"什么是傲翼兽","傲翼兽背景","石爪山脉的傲翼兽"}},{q="联盟为什么要猎杀它们？",a="辛德瑞尔·速火报告了一条未经证实的消息：联盟情报显示，部落刺客正在积极采集傲翼兽毒液，用来涂抹武器，对联盟据点发动秘密袭击。通过猎杀这些野兽并抢先夺取它们的毒囊，联盟成功剥夺了部落获取这种致命毒药的机会。",al={"为什么要猎杀傲翼兽","任务目的","联盟采集傲翼兽毒液"}},{q="是谁提供了关于兽人刺客的情报？",a="该警告源自驻扎在塞拉摩的隐蔽联盟线人，他们密切监视着南贫瘠之地和石爪山脉全境的部落动向与补给网络。",al={"谁向联盟发出了警告","塞拉摩间谍情报","辛德瑞尔的情报来源"}},{q="暗色湖位于哪里？",a="暗色湖位于石爪山脉的北部，就在通往灰谷的边界小径以南。",al={"暗色湖位置","傲翼兽在哪里","寻找傲翼兽"}},{q="联盟和部落在灰谷处于全面战争状态吗？",a="从官方层面上讲，这两个阵营维持着脆弱的和平，避免宣布全面开战。但实际上，在茂密的树冠下，秘密暗杀、资源争夺和边境冲突从未停歇。",al={"部落和联盟在交战吗","灰谷战争状态","灰谷和平条约"}},{q="辛德瑞尔·速火对猎杀这些野兽有何感受？",a="辛德瑞尔为不得不下令屠杀这些并未自愿卷入冲突的野兽感到悲伤。然而，作为一名负责保卫阿斯特兰纳的军官，她认为这是为了保护她的人民而不得不做的悲剧性抉择。",al={"辛德瑞尔的反应","德鲁伊的内疚","暗夜精灵猎杀野兽"}}},fp="24,265,15.321.0,21.378.0,14.278.0,20.227.0,33.234.0,54.153.0,33.105.0,52.159.0,59.203.0"}
P.entries["quest:1135"] = {n="风巢双足飞龙的毒囊",s="塞拉摩的Fiora Longears委派联盟冒险者前往西方的千针石林峡谷。在那里，在风巢高耸的悬崖之上，栖息着危险的双足飞龙，它们因其极其强效的毒液而备受觊觎。",h="塞拉摩的Fiora Longears委派联盟冒险者前往西方的千针石林峡谷。在那里，在风巢高耸的悬崖之上，栖息着危险的双足飞龙，它们因其极其强效的毒液而备受觊觎。",kw={"尘泥沼泽","fiora","风巢","longears","塞拉摩","千针石林","毒液","双足飞龙"},ang={["class:Rogue"]="潜行者天生就明白奇异毒素所带来的黑暗诱惑。寻获纯净、未精炼的双足飞龙毒液，能让人深入了解卡利姆多最致命的生物制剂。",["faction:Alliance"]="进入千针石林会将联盟冒险者置于敌后深处，直接暴露在部落牛头人和兽人巡逻队的注视之下。",["race:NightElf"]="对于卡多雷而言，派遣猎人深入千针石林那干旱的荒原，凸显了贸易利益和珍奇试剂在灰谷和黑海岸之外的触角延伸得有多远。"},sec={{t="一次有利可图的远征",b="在塞拉摩这座岛屿港口休息时，旅行者可能会偶遇Fiora Longears。虽然兽人通常会捕捉并驯化双足飞龙作为飞行坐骑，但Fiora指出了一项更隐秘的交易：这种生物致命的毒液。卡利姆多各地的某些买家对新鲜毒囊的重视程度远超野兽本身，促使Fiora招募愿意冒着长途跋涉和攀登险峰风险的猎人。"},{t="风巢峭壁",b="猎物筑巢于尘泥沼泽以西，千针石林高耸的砂岩台地之中。在一个被称为风巢的栖息地，当地的双足飞龙体内有着浓度异常高的毒素。抵达它们的巢穴需要穿过敌对的部落领地并攀登险峻的地形，猎人们必须在此杀死双足飞龙并提取完整的毒囊，然后将战利品运回塞拉摩。"}},faq={{q="我在哪里可以找到这个任务所需的双足飞龙？",a="双足飞龙栖息在风巢，那是一座坐落于千针石林西侧、塞拉摩以西的高大台地。",al={"风巢位置","风巢在哪里","双足飞龙位置"}},{q="Fiora Longears是谁？",a="Fiora Longears是一名驻扎在尘泥沼泽海岸外塞拉摩的联盟联络人。她招募勇敢的冒险者从卡利姆多各地采购稀有且珍贵的天然试剂。",al={"fiora longears","谁提供风巢毒液任务"}},{q="为什么双足飞龙毒液如此珍贵？",a="双足飞龙毒液极其强效，在某些地下圈子、药剂师和贸易网络中备受追捧。虽然部落主要将双足飞龙视为飞行坐骑，但它们的毒腺在炼金术士和制毒师中能卖出高价。",al={"为什么需要双足飞龙毒液","双足飞龙毒液用途"}},{q="为什么塞拉摩的任务会派我到这么远的西方去？",a="Fiora是一位富有进取心的商人，正在寻找塞拉摩周边沼泽中找不到的珍稀样本。千针石林的风巢栖息着一种独特的、高浓度的双足飞龙，在尘泥沼泽中是找不到的。",al={"为什么要前往千针石林","为什么要派往千针石林"}},{q="当你交还毒囊时会发生什么？",a="Fiora检查毒囊后指出它们内含毒液充足，并评论说这种品质通常只来自幼年双足飞龙或繁殖期的雌性，同时祝贺你的狩猎成功。",al={"fiora的反应","风巢毒液任务完成"}},{q="风巢对联盟旅行者安全吗？",a="不安全。千针石林驻扎着大量部落势力，并以附近的乱风岗等定居点为中心。攀登风巢意味着要同时应对野生捕食者和敌对的部落侦察兵。",al={"风巢危险吗","千针石林的联盟"}}},fx={["9e43b6cb"]={q="菲欧拉·长耳为什么想让你完成这件事？",a="菲欧拉善于发现有利可图的交易和稀有试剂。大多数人只知道双足飞龙是部落驯养的坐骑，她却知道有些人愿意为强效毒液付出高价。采集风巢的毒囊能让她在这些专门的市场上大赚一笔。",al={"菲欧拉为什么要毒液","菲欧拉·长耳的动机","为什么采集双足飞龙毒液"}},ef763353={q="风巢双足飞龙的毒囊有什么用？",a="毒囊里装着栖息在千针石林高处的野生双足飞龙所拥有的致命强效毒液。精选的炼金师、施毒者和异域货商都极为看重这些毒囊，因此在经营稀有危险生物的市场上，它们能卖出天价。",al={"风巢双足飞龙毒囊有什么用","毒囊用途","为什么收集毒囊"}},f9186ab4={q="栖息在风巢的是什么生物？",a="风巢是千针石林中一座高耸的台地，也是当地双足飞龙野生栖息的巢穴。这些长着翅膀的掠食者桀骜不驯，领地意识极强，会在沙漠峡谷间滑翔，用带毒的尾刺击倒猎物，再把猎物拖回岩石巢穴。",al={"风巢双足飞龙是什么","在风巢要猎杀什么","风巢有什么生物"}}},fp="15,226,22.421.0,22.392.0,43.115.0,22.195.0,32.245.0,48.220.0,44.181.0,41.193.0"}
P.entries["quest:1136"] = {n="霜喉雪人",s="梅洛·石蹄派你前往奥特兰克山脉猎杀霜噬，一只难得一见的雪人。一卷卷轴说明了如何引诱它，梅洛正在雷霆崖等候霜噬的鬃毛。",h="梅洛·石蹄派你前往奥特兰克山脉猎杀霜噬，一只难得一见的雪人。一卷卷轴说明了如何引诱它，梅洛正在雷霆崖等候霜噬的鬃毛。",kw={"奥特兰克山脉","霜噬","鬃毛","梅洛·石蹄","卷轴","雷霆崖","雪人"},sec={{t="遥远的狩猎",b="梅洛·石蹄说，你已准备好远离家乡，前往奥特兰克山脉猎杀霜噬。雪人的白色皮毛与山间积雪融为一体，它很少现身。梅洛给了你一卷卷轴，上面写着如何引诱霜噬。把它的鬃毛带回雷霆崖交给梅洛；在此之前，你的旅程还未结束。"}},faq={{q="霜噬是谁？",a="霜噬是奥特兰克山脉的一只雪人。它的白色皮毛与积雪融为一体，而且很少现身。",al={"霜噬是谁","霜噬是什么"}},{q="我在哪里能找到霜噬？",a="霜噬栖居在奥特兰克山脉，它的白色皮毛与积雪融为一体。",al={"霜噬位置","霜噬在哪里"}},{q="我该如何引诱霜噬？",a="梅洛·石蹄给了你一卷卷轴，上面写着引诱霜噬的方法。",al={"引诱霜噬","霜噬卷轴"}},{q="梅洛想从霜噬那里得到什么？",a="梅洛·石蹄让你把霜噬的鬃毛带到雷霆崖交给他。",al={"梅洛霜噬","霜噬鬃毛"}}},fp="8,176,14.336.0,16.104.0,26.83.0,23.73.0,35.76.0"}
P.entries["quest:1137"] = {n="回复菲兹尔",s="荒芜之地的被流放者玛尔特有关于氪金的消息要传达给菲兹尔·铜栓。你需要把玛尔特的口信带回千针石林闪光平原的沙漠赛道。",h="荒芜之地的被流放者玛尔特有关于氪金的消息要传达给菲兹尔·铜栓。你需要把玛尔特的口信带回千针石林闪光平原的沙漠赛道。",kw={"荒芜之地","菲兹尔·铜栓","氪金","氪金矿石","被流放者玛尔特","沙漠赛道","闪光平原","千针石林","奥达曼"},sec={{t="玛尔特关于氪金的消息",b="玛尔特报告说，氪金在耐热性方面表现得非常出色，他认为这很适合菲兹尔的活塞。不过，碎片是没用的：菲兹尔需要的是真正的氪金矿石，必须从位于荒芜之地北缘的奥达曼深处挖掘出来，玛尔特称那里才是氪金的真正来源。玛尔特让你向菲兹尔·铜栓转达问候，并将这一切告诉他。"},{t="菲兹尔听到了消息",b="菲兹尔·铜栓急切地想知道玛尔特说了什么，以及玛尔特是否能提供帮助。当你告诉他你在荒芜之地的旅行经历时，菲兹尔断言氪金就是关键所在。"}},faq={{q="这段旅程始于何处，又终于何处？",a="荒芜之地的被流放者玛尔特给了你一条口信，你将其带给了位于千针石林闪光平原沙漠赛道的菲兹尔·铜栓。",al={"谁给菲兹尔消息","在哪里上交菲兹尔的消息","玛尔特传达给菲兹尔"}},{q="玛尔特给菲兹尔发了什么消息？",a="玛尔特说氪金在耐热性方面表现得非常出色，应该能用在菲兹尔的活塞上。菲兹尔需要的是真正的矿石，而不是碎片，而且必须是从奥达曼深处开采出来的。",al={"玛尔特说了什么","氪金消息","玛尔特的口信"}},{q="氪金矿石来自哪里？",a="玛尔特说它是从荒芜之地北缘的奥达曼深处挖掘出来的，玛尔特称那里是氪金的真正来源。",al={"氪金矿石在哪里","氪金矿石来源"}},{q="这一步在故事线中处于什么位置？",a="它紧接在“氪金”任务之后，属于菲兹尔·铜栓指引你去找被流放者玛尔特的那条任务线。",al={"菲兹尔的消息任务线","前置任务菲兹尔的消息"}}},fp="15,157,25.365.0,21.173.1,38.159.0,37.184.0,34.137.0,42.98.0"}
P.entries["quest:1138"] = {n="海中的水果",s="“海洋之果”是一个联盟任务，由渔夫古博·布拉普在奥伯丁的码头上提供。古博对甲壳类菜肴充满热情，他请求路过的旅人们搜寻黑海岸的海岸线，为他收集优质蟹肉，而他自己则要坚守在钓位上。",h="“海洋之果”是一个联盟任务，由渔夫古博·布拉普在奥伯丁的码头上提供。古博对甲壳类菜肴充满热情，他请求路过的旅人们搜寻黑海岸的海岸线，为他收集优质蟹肉，而他自己则要坚守在钓位上。",kw={"奥伯丁","黑海岸","硬壳潮汐爬行者","优质蟹肉","海洋之果","古博·布拉普","礁石爬行者"},ang={["faction:Alliance"]="奥伯丁是联盟探险者抵达卡利姆多的重要登陆枢纽，经常会提供一些如帮助当地渔夫安顿生活之类的小委托。",["profession:Cooking"]="古博对蟹肉食谱那充满激情的剖析，对于任何想要充分利用当地海岸收获的厨师来说，都是一种启发。",["race:Dwarf"]="在卡利姆多北部听到一个外乡人梦想着烹饪“铁炉堡惊喜蟹肉”，对旅行中的卡兹莫丹登山者来说，是一种别有风味的家乡慰藉。"},sec={{t="对甲壳类动物的热爱",b="古博·布拉普是一位在奥伯丁长长的木质码头上垂钓的渔夫，他对蟹肉有着一种近乎痴迷的烹饪追求。在古博眼中，螃蟹是海洋最慷慨的馈赠。他构想了一系列无穷无尽的食谱，从烘烤、烧烤、水煮，到鞭根草蟹肉和“铁炉堡惊喜蟹肉”等当地精心制作的特色菜，应有尽有。"},{t="搜寻潮汐池",b="由于古博无法离开他的鱼竿，他只能寄希望于路过的冒险者在黑海岸迷雾缭绕的海滩上帮忙收集食材。海岸线上到处都是在碎浪间爬行的礁石爬行者和硬壳潮汐爬行者，对于想成为海岸厨师的人来说，它们是获取蟹肉的绝佳来源，虽然偶尔会被夹到。"}},faq={{q="谁发布了“海洋之果”任务？",a="该任务由联盟渔夫古博·布拉普发布，他驻扎在黑海岸的奥伯丁码头上。",al={"海洋之果任务发布者","谁发布海洋之果","古博·布拉普任务"}},{q="哪些生物掉落优质蟹肉？",a="优质蟹肉可以从在黑海岸沿岸的沙滩和浅水区游荡的礁石爬行者和硬壳潮汐爬行者身上采集到。",al={"优质蟹肉哪里掉落","什么怪掉落蟹肉","哪些螃蟹掉落优质蟹肉"}},{q="为什么古博不自己去收集蟹肉？",a="古博需要一直守在奥伯丁的码头上钓鱼，无法离开鱼竿去海滩上猎捕螃蟹。",al={"为什么古博不自己去抓螃蟹","为什么古博需要帮助"}},{q="古博想做哪些菜？",a="古博吹嘘他掌握着各种各样的烹饪方式，包括蟹肉沙拉、蟹肉汤、炖蟹肉、胡椒蟹、柠檬蟹、鞭根草蟹肉，以及一种他称之为“铁炉堡惊喜蟹肉”的地区特色食谱。",al={"古博的螃蟹食谱","古博提到了什么食谱","螃蟹菜肴"}},{q="古博·布拉普的话是在引用什么吗？",a="是的。他那段如数家珍般列举各种螃蟹烹饪方法的独白，显然是在向电影《阿甘正传》中的本杰明·布福德·“布巴”·布鲁致敬，他在片中也曾发表过一段关于虾的经典演讲。",al={"古博·布拉普流行文化彩蛋","阿甘正传布巴彩蛋"}},{q="这个任务发生在哪里？",a="任务在奥伯丁港口村开始并交还，狩猎过程则在卡利姆多北部的黑海岸沿岸进行。",al={"海洋之果在哪里","海洋之果在哪个地图"}}},fx={cf4b2535={q="优质蟹肉有什么用？",a="古博·布拉普打算用它们制作种类繁多的菜肴。在他看来，螃蟹就是海中的珍果，适合烘烤、烧烤、水煮、焙烤、油炸，也可以加入汤、炖菜和沙拉。",al={"优质蟹肉用途","为什么要优质蟹肉","古博拿蟹肉做什么"}},["82492fa1"]={q="黑海岸沿岸的爬行者是什么？",a="礁石爬行者和硬壳潮汐爬行者是当地的甲壳类生物，在黑海岸漫长而雾气弥漫的海岸线和浅滩潮池中觅食。它们会伤害粗心的海滩漫步者，但渔夫和古博·布拉普这样的厨师很看重它们的肉，常用来烹制丰盛的海岸佳肴。",al={"礁石爬行者是什么","黑海岸硬壳潮汐爬行者","黑海岸螃蟹"}}},fp="16,260,25.370.0,21.355.0,37.107.0,41.150.0,48.128.0,37.196.0,47.202.0,33.145.0"}
P.entries["quest:114"] = {n="梅贝尔的隐形水",s="“逃离”是发生在艾尔文森林中，梅贝尔·马科伦与托米·乔·斯通菲尔德之间禁忌之恋的高潮。在搜集了整个地区的材料后，你将威廉·匹斯特酿造的隐形水交给了梅贝尔，让她能悄悄溜出家门，避开家人的视线。这标志着年青一代的爱情在根深蒂固的乡村世仇面前，获得了一次短暂而隐秘的胜利。",h="“逃离”是发生在艾尔文森林中，梅贝尔·马科伦与托米·乔·斯通菲尔德之间禁忌之恋的高潮。在搜集了整个地区的材料后，你将威廉·匹斯特酿造的隐形水交给了梅贝尔，让她能悄悄溜出家门，避开家人的视线。这标志着年青一代的爱情在根深蒂...",kw={"艾尔文森林","隐形水","马科伦农场","梅贝尔·马科伦","斯通菲尔德农场","逃离","托米·乔·斯通菲尔德","威廉·匹斯特"},ang={["faction:Alliance"]="对于在艾尔文森林开启冒险的年轻探险者来说，帮助托米·乔和梅贝尔提供了一种对抗迪菲亚强盗和豺狼人之外的轻松调剂，也展现了即便是暴风城门口，日常的乡村矛盾依然存在。",["race:Human"]="生活在艾尔文的人类定居者都很清楚，固执的家庭积怨根深蒂固，因此一些小小的秘密邻里互助对于维持和平至关重要。"},sec={{t="真爱的药剂",b="马科伦家族和斯通菲尔德家族之间世代的积怨使得双方毫无和解的余地，更不用说让他们认同这段恋情了。由于两个家庭都极力护短且彼此敌视，米莱德·斯通菲尔德只好求助于闪金镇Lion's Pride Inn里的炼金师威廉·匹斯特。匹斯特利用从附近湖泊采集的水晶海藻，调制出了一瓶强效的隐形水，足以掩护梅贝尔逃离马科伦的家园。"},{t="隐入森林",b="将药瓶交给梅贝尔·马科伦后，她便能溜进树林，去寻找托米·乔。尽管因为欺骗亲人而备受愧疚煎熬，但她对爱情的执着战胜了对被发现的恐惧。喝下药水后，她便在你的眼前凭空消失，让这对年轻的恋人在他们那敌对的长辈的监视之外，获得了一段珍贵的独处时光。"}},faq={{q="谁发布了“逃离”这个任务？",a="威廉·匹斯特，也就是住在闪金镇Lion's Pride Inn里的药剂师兼炼金助手，在你为他提供了水晶海藻后，会将隐形水交给你。",al={"逃离任务发布者","谁开启了逃离任务","去哪里接取逃离"}},{q="隐形水有什么用？",a="这种药水能让梅贝尔·马科伦长时间保持完全隐形，从而溜出她家人的农场，在不激怒亲属的情况下私会托米·乔·斯通菲尔德。",al={"为什么要用隐形水","药水有什么作用","隐形水的用途"}},{q="为什么梅贝尔和托米·乔必须隐瞒他们的恋情？",a="马科伦家族和斯通菲尔德家族是深陷长期积怨的死敌。由于两个家庭之间存在着深刻的敌意，他们子女之间任何公开的交往都是严格禁止的。",al={"为什么他们要躲藏","斯通菲尔德与马科伦的世仇","为什么梅贝尔和托米·乔不能在一起"}},{q="当你把药水交给梅贝尔时会发生什么？",a="梅贝尔会感谢你，表达出既愧疚又兴奋的复杂心情，然后立即喝下药水。她在你眼前立刻隐形，溜向托米·乔那边。",al={"最后发生了什么","梅贝尔消失了吗","逃离任务完成"}},{q="哪个任务可以直接引出“逃离”？",a="“逃离”紧接在“收集海藻”任务之后，在该任务中，你需要从水晶湖的鱼人手中夺回水晶海藻，以便让威廉·匹斯特酿造隐形药水。",al={"逃离任务的前置条件","逃离之前的任务","什么任务引出逃离"}},{q="这个任务能解决两家之间的世仇吗？",a="不能。这种药水仅仅为恋人们提供了一次短暂的秘密会面。米莱德·斯通菲尔德和马科伦家族之间更广泛的世仇依然如故，并未得到解决。",al={"两个家庭和解了吗","世仇结束了吗","世仇是否终结"}}},fp="10,196,26.319.0,24.307.1,31.156.0,41.162.0,61.129.0,52.137.1,42.146.0,54.144.1"}
P.entries["quest:1140"] = {n="奥萨拉克斯之塔",s="这个任务是针对奥萨拉克斯之塔邪教徒的十字军征讨的第六章，由迈斯特拉岗哨的净化者德尔格伦指挥。德尔格伦破译了从邪教信使身上缴获的兽人语笔记，揭示了术士阿斯瑞克斯·纳拉辛将两颗受到禁锢的上层精灵灵魂石隐藏在灰谷深处的恶魔萨特据点中。勇士们被派遣前往夜道谷和萨提纳尔粉碎这些容器，解放那些备受折磨的古代灵魂，并摧毁阿斯瑞克斯邪恶的Source of Power。",h="这个任务是针对奥萨拉克斯之塔邪教徒的十字军征讨的第六章，由迈斯特拉岗哨的净化者德尔格伦指挥。德尔格伦破译了从邪教信使身上缴获的兽人语笔记，揭示了术士阿斯瑞克斯·纳拉辛将两颗受到禁锢的上层精灵灵魂石隐藏在灰谷深处的恶魔萨特...",kw={"奥萨拉克斯","灰谷","阿斯瑞克斯","德尔格伦","上层精灵","迈斯特拉岗哨","夜道谷","萨提纳尔","灵魂石"},ang={["class:Paladin"]="净化者德尔格伦体现了一种务实的神圣十字军精神，他利用敌人的语言来挖掘恶魔腐蚀并净化饱受折磨的亡灵。",["class:Priest"]="击碎禁锢圆阵能为那些遭受数百年恶魔折磨的痛苦灵魂带来安宁。",["race:NightElf"]="将上层精灵祖先从萨特的亵渎中解放出来是一项庄严的职责，这也让你直面了你族人古代历史中悲剧的一面。"},sec={{t="解读潦草的笔记",b="在斩杀了兽人信使伊尔库德·玛格瑟尔之后，净化者德尔格伦将他那备受争议的兽人语研究付诸实践。尽管圣光的同僚们常常嘲笑学习敌人的语言，但德尔格伦务实的洞察力揭开了邪教秘密交易的面纱。笔记显示，阿斯瑞克斯·纳拉辛获得了两颗蕴含着古代上层精灵精华的强力灵魂石，并将它们隐藏在东北方遥远之处，位于夜道谷和萨提纳尔那被亵渎的树林里。"},{t="邪恶的盟友",b="上层精灵灵魂石出现在萨特营地中，揭示了阿斯瑞克斯的黑暗阴谋集团与燃烧军团的恶魔爪牙之间肮脏的勾结。这些古代灵魂被束缚在禁锢仪式圆阵之上，承受着无尽的折磨，以助长黑暗的法术。深入萨特那充满血腥的祭坛，不仅需要面对狂暴的恶魔腐蚀，还要提防隐藏在暗处、誓死守卫这些奥术导体的萨特潜行者那致命的匕首。"},{t="削弱阿斯瑞克斯",b="通过击碎这些深红色的石头并将上层精灵的灵魂从痛苦的圆阵中解放出来，冒险者们对阿斯瑞克斯的神秘力量源泉给予了沉重的打击。德尔格伦指出，随着这些灵魂石被毁，奥萨拉克斯邪教的首领被严重削弱了。这一行径也让这位神圣的十字军战士对暗夜精灵们面对萨特时表现出的不安感到困惑，促使他决心将这些挥之不去的恶魔枯萎病引起奥伯丁领袖们的注意。"}},faq={{q="为什么德尔格伦会读兽人语？",a="德尔格伦主动学习了兽人的语言，尽管他在神圣教团中因此受到嘲笑。他认为理解敌人的语言对于获得战术洞察力至关重要，这也直接使他能够翻译从伊尔库德·玛格瑟尔那里缴获的笔记。",al={"德尔格伦读兽人语","德尔格伦为何懂兽人语","德尔格伦翻译"}},{q="灵魂石是什么，为什么它们被萨特持有？",a="灵魂石是深红色的聚焦石，束缚着古代上层精灵的灵魂，悬浮在禁锢仪式的圆阵上方。阿斯瑞克斯·纳拉辛通过交易获得了它们，或者将它们放置在如夜道谷和萨提纳尔这样的萨特圣地中，利用它们的痛苦来为邪教的奥术力量提供源泉。",al={"奥萨拉克斯灵魂石","为何萨特持有宝石","受困的上层精灵灵魂"}},{q="夜道谷和萨提纳尔位于何处？",a="这两个地点都是恶魔萨特据点，坐落在灰谷东北部的森林高地，位于迈斯特拉岗哨以东。",al={"夜道谷在哪","萨提纳尔在哪","萨特营地位置"}},{q="为什么暗夜精灵不愿谈论萨特？",a="德尔格伦注意到他的精灵主人回避讨论萨特，因为这些生物曾经也是暗夜精灵。在上古之战中，萨特在屈服于恶魔腐蚀后，被扭曲成了长着山羊腿的恶魔，这使得它们的存在成为了卡多雷心中挥之不去的悲伤和耻辱的源头。",al={"为何对萨特避而不谈","暗夜精灵与萨特的联系","萨特的精灵历史"}},{q="解放这些灵魂如何帮助阻止奥萨拉克斯之塔的邪教？",a="阿斯瑞克斯·纳拉辛严重依赖上层精灵灵魂石中窃取的精神能量。击碎这些悬浮的宝石并释放被囚禁的鬼魂，会使他的能量仪祭失去来源，从而使他在塔内受到直接攻击时变得脆弱不堪。",al={"为何要击碎灵魂石","阿斯瑞克斯的力量之源","如何削弱阿斯瑞克斯"}},{q="德尔格伦提到的埃莉萨是谁？",a="埃莉萨·星风是一位驻扎在奥伯丁的杰出暗夜精灵哨兵，负责协调黑海岸的当地防御。德尔格伦计划与她商讨有关威胁卡利姆多北部的萨特入侵问题。",al={"埃莉萨 奥伯丁","埃莉萨是谁","德尔格伦 埃莉萨"}}},fp="22,403,27.448.0,16.373.1,18.420.1,41.231.0,54.271.0,42.115.0,59.276.0,67.231.0,48.215.0"}
P.entries["quest:1141"] = {n="钓鱼世家",s="居住在奥伯丁码头上的矮人古博·布拉普正在寻求帮助，想要捕捉当地的黑海岸石斑鱼。在海岸边徘徊的敌对鱼人破坏了镇上的小型渔船，使得古博被困在岸上，并愿意将一根传家鱼竿赠送给任何愿意挥杆垂钓的人。",h="居住在奥伯丁码头上的矮人古博·布拉普正在寻求帮助，想要捕捉当地的黑海岸石斑鱼。在海岸边徘徊的敌对鱼人破坏了镇上的小型渔船，使得古博被困在岸上，并愿意将一根传家鱼竿赠送给任何愿意挥杆垂钓的人。",kw={"奥伯丁","布拉普家族鱼竿","黑海岸石斑鱼","钓鱼","格劳恩·布拉普","古博·布拉普","鱼人","永望海"},ang={["faction:Alliance"]="奥伯丁是卡利姆多重要的联盟港口，来自大陆的种族和暗夜精灵每天都在这里携手合作，共同抵御鱼人等沿海威胁。",["profession:Cooking"]="黑海岸石斑鱼是卡利姆多北部海岸一种可靠且营养丰富的渔获，是前哨营地餐食的主要原料。",["race:Dwarf"]="发现一位同样热爱垂钓而非从事地下锻造或酿酒的同族矮人，这提醒了人们，你们的种族有着丰富多彩的追求。"},sec={{t="远离铁炉堡的矮人",b="古博·布拉普对自己的血统深感自豪，他声称“布拉普”这个姓氏长期以来一直是钓鱼艺术的代名词。虽然奥伯丁大部分地区居住着暗夜精灵，但矮人和侏儒也在其码头和繁忙的港口设施中定居了下来。古博并没有忙于挖掘岩石，而是整日凝视着薄雾笼罩的永望海，渴望能钓到当地的渔获。"},{t="鱼人侵扰与黑海岸石斑鱼",b="黑海岸石斑鱼是一种珍贵的沿海鱼类，烹饪方式多样，而且以咬钩时活力十足而闻名。通常，当地渔民会划着小船前往深水区捕捞它们。然而，具有侵略性的沿海鱼人的到来使平民的船只交通陷入了停顿。由于担心这些生物会吃光当地所有的鱼类资源，古博招募愿意在岸边垂钓的旅行者。"},{t="布拉普的传承",b="为了奖励那些带给他丰厚渔获的人，古博会拿出一根布拉普家族鱼竿作为报酬。在他看来，任何能够钓上一批活力十足的石斑鱼的人，其水平都足以媲美他血统中的传奇垂钓者——包括他那长着胡须、气味刺鼻的表亲格劳恩·布拉普。对于像他这样品味古怪的矮人来说，交出一根家族鱼竿是表达尊重的最高形式。"}},faq={{q="古博·布拉普是谁？",a="古博·布拉普是一名驻扎在黑海岸奥伯丁码头的矮人渔夫。他出身于一个引以为傲的垂钓家族，他会教授基础的垂钓技巧，并将家族标志性的鱼竿传给有潜力的垂钓者。",al={"古博其人","古博·布拉普背景故事","奥伯丁矮人渔夫"}},{q="为什么奥伯丁不再有船只出海捕鱼？",a="敌对的鱼人已经占领了黑海岸漫长的海岸线。它们充满侵略性的存在使得下水使用小型个人渔船变得极其危险，导致当地的垂钓者只能被困在码头和浅滩上。",al={"为什么没有船只","黑海岸渔船","奥伯丁的船只问题"}},{q="什么是黑海岸石斑鱼？",a="这是一种在黑海岸多雾的海岸外发现的本地咸水鱼。垂钓者们珍视这种石斑鱼，不仅是因为钓上它极具挑战性，还因为它在各种丰盛的沿海菜肴中用途广泛。",al={"黑海岸石斑鱼"}},{q="格劳恩·布拉普是谁？",a="格劳恩是古博·布拉普的表亲。据古博所说，她留着满脸胡须，气味相当刺鼻，是他们家族有史以来最优秀的垂钓者之一。",al={"格劳恩·布拉普","古博的表亲"}},{q="为什么像奥伯丁这样的暗夜精灵城镇会有矮人？",a="在第三次战争结束并组建联盟之后，铁炉堡的矮人和侏儒远渡重洋来到卡利姆多，进行贸易、建立海上航线，并协助他们新的暗夜精灵盟友建设港口基础设施。",al={"为什么奥伯丁有矮人","黑海岸的矮人"}},{q="什么是布拉普家族鱼竿？",a="这是布拉普家族制作并使用的一根坚固的鱼竿。古博会将这些珍贵的鱼竿赠予那些证明了自己在黑海岸水域拥有真正垂钓天赋的旅行者。",al={"布拉普家族鱼竿","古博的奖励鱼竿"}}},fp="31,209,26.299.0,41.356.0,16.289.0,20.210.0,50.162.0,28.156.0,19.155.0,57.221.0,38.170.0"}
P.entries["quest:1142"] = {n="临终遗言",s="在剃刀沼泽危险的荆棘丛深处，一位垂死的暗夜精灵赫尔拉斯·静水向路过的联盟冒险者低声诉说着他最后的请求。他的生命与力量即将耗尽，他只求能找回妻子被抢走的定情坠饰，并将坠饰和他的死讯一起带回达纳苏斯。",h="在剃刀沼泽危险的荆棘丛深处，一位垂死的暗夜精灵赫尔拉斯·静水向路过的联盟冒险者低声诉说着他最后的请求。他的生命与力量即将耗尽，他只求能找回妻子被抢走的定情坠饰，并将坠饰和他的死讯一起带回达纳苏斯。",kw={"达纳苏斯","falfindel","赫尔拉斯·静水","lonebrow","凋零的生命","定情坠饰","剃刀沼泽","塔莎拉·静水"},ang={["faction:Alliance"]="对于前往部落控制的贫瘠之地腹地的联盟勇士来说，将赫尔拉斯最后的信物带回达纳苏斯是一项庄严的荣誉职责。",["race:Dwarf"]="赫尔拉斯的临终遗言赞扬了矮人Lonebrow的勇敢，他冒着生命危险，将紧急的警告带离了野猪人的据点。",["race:NightElf"]="看到同族在南贫瘠之地野蛮的荆棘丛中孤独地死去并被人遗忘，暗夜精灵们感到深深的刺痛。"},sec={{t="荆棘丛中的临终遗言",b="剃刀沼泽是一座险恶的堡垒，到处都是野蛮的野猪人和黑暗魔法，远离联盟的领地。在这些充满危险的荆棘丛中，赫尔拉斯·静水受了致命伤，生命正在迅速流逝。他用尽最后的力气低声呢喃，透露了一名勇敢的矮人Lonebrow曾被派往前方去向Falfindel发出警告。然而，赫尔拉斯深知自己无法活着离开这片沼泽。"},{t="定情坠饰",b="在伤重不治之前，赫尔拉斯心中只剩下一个最后的愿望：找回他婚姻的信物。那是一枚象征着他与妻子塔莎拉·静水永恒羁绊的坠饰，被巢穴中凶恶的掠夺者抢走了。他恳求任何在他身边停留的旅行者找回这枚坠饰，并将其带回远在卡利姆多的达纳苏斯，好让塔莎拉得知他孤独离世的真相，而不是在徒劳地等待。"},{t="达纳苏斯的悲伤",b="当塔莎拉·静水在达纳苏斯收到找回来的传家宝时，确认丈夫离世的消息让她悲痛欲绝。面对这个世界的残酷现实，她发誓赫尔拉斯的事业不会随他而去。她在静谧的孤独中哀悼，一边忍受着突如其来的悲伤，一边挑起了他遗志的重担。"}},faq={{q="赫尔拉斯·静水是谁？",a="赫尔拉斯·静水是一位联盟暗夜精灵，被发现时已在剃刀沼泽身受致命伤。由于伤势过重，生命垂危，他委托路过的冒险者找回他妻子被盗的定情坠饰，并将他的死讯带回达纳苏斯。",al={"赫尔拉斯·静水","赫尔拉斯是谁","剃刀沼泽的临终精灵"}},{q="赫尔拉斯·静水在哪里？",a="赫尔拉斯位于剃刀沼泽内部，那是一座被荆棘覆盖的野猪人堡垒，坐落在贫瘠之地的南部地区。",al={"赫尔拉斯的位置","赫尔拉斯在哪里","去哪里找赫尔拉斯"}},{q="Lonebrow是谁？",a="Lonebrow是赫尔拉斯在临终时刻提到的勇敢矮人。显然，Lonebrow被派去执行一项紧急任务，离开荆棘丛去向Falfindel警告发生在剃刀沼泽的危险。",al={"矮人lonebrow","lonebrow是谁","lonebrow的警告"}},{q="塔莎拉·静水是谁？",a="塔莎拉是赫尔拉斯的妻子，居住在暗夜精灵的主城达纳苏斯。她收到了找回的坠饰，并不得不承受丈夫去世的悲剧消息。",al={"塔莎拉·静水","塔莎拉是谁","赫尔拉斯的妻子"}},{q="什么是定情坠饰？",a="定情坠饰是象征赫尔拉斯与塔莎拉·静水之间婚姻的珍贵纪念物。它在赫尔拉斯去世前被剃刀沼泽的野猪人抢走。",al={"塔莎拉的坠饰","坠饰是什么","定情坠饰"}},{q="塔莎拉对这个消息有什么反应？",a="塔莎拉因这场悲剧而心碎，并感叹世界的残酷。尽管悲痛欲绝，但她下定决心要让赫尔拉斯的事业通过自己延续下去，并请求让她独自哀悼。",al={"塔莎拉的反应","交付坠饰会发生什么"}}},fp="15,171,28.357.0,22.286.0,18.245.1,28.236.0,38.110.0,17.165.0,28.133.0,31.179.0,36.168.1"}
P.entries["quest:1143"] = {n="奥萨拉克斯之塔",s="这项任务标志着对盘踞在奥萨拉克斯之塔顶端的古老黑暗法师——Athrikus Narassin的直接进攻。在巴苏尔·影击的指挥下，一名联盟勇士必须攻入这座破败的要塞，并铲除这群邪教徒的首领。消灭Athrikus将给予腐蚀着黑海岸北部的恶魔崇拜以沉重打击。",h="这项任务标志着对盘踞在奥萨拉克斯之塔顶端的古老黑暗法师——Athrikus...",kw={"奥萨拉克斯","athrikus","巴苏尔","黑海岸","恶魔","纳拉辛","影击","术士"},ang={["class:Warlock"]="Athrikus在奥萨拉克斯之塔顶端掌控着强大的恶魔魔法，是一个关于不受约束的邪能崇拜如何招致致命后果的惨痛例证。",["faction:Alliance"]="将黑海岸北部从恶魔邪教徒手中解放出来，对于保护奥伯丁与其他地区之间的联盟交通枢纽至关重要。",["race:NightElf"]="对抗Athrikus Narassin，让人痛苦地回想起曾经摧毁了暗夜精灵文明的奥术与恶魔腐化。"},sec={{t="攻占塔顶",b="奥萨拉克斯之塔矗立在黑海岸北部破败的高地上，已成为一个邪恶的恶魔召唤中心。巴苏尔·影击在附近监视着这座废墟，认为时机已到，必须立即行动。在塔顶居住着Athrikus Narassin，一位古老而强大的暗夜精灵术士，他策划了在那破碎石顶下进行的所有黑暗仪式。"},{t="决定性的一击",b="Athrikus身边簇拥着忠诚的术士和远比山坡下巡逻的邪教徒更致命的黑暗魔法。要击倒这位邪教头目，必须突破他的核心圈子，并取回他的人头作为证明。虽然巴苏尔指出恶魔势力有朝一日可能会试图重组，但Athrikus的死剥夺了该邪教的主心骨，也为黑海岸争取到了宝贵的安全。"}},faq={{q="Athrikus Narassin是谁？",a="Athrikus Narassin是一位古老的暗夜精灵术士，指挥着驻扎在奥萨拉克斯之塔的邪教徒。他策划了那些在黑海岸北部废墟中肆虐的黑暗召唤和恶魔仪式。",al={"athrikus","athrikus是谁","奥萨拉克斯的首领"}},{q="在哪里可以找到Athrikus Narassin？",a="Athrikus居住在奥萨拉克斯之塔的最顶端，由一群经验丰富的术士和召唤出来的爪牙守护着。",al={"athrikus在哪里","athrikus的位置","奥萨拉克斯之塔顶端"}},{q="谁会发布这个任务？",a="巴苏尔·影击是一位在奥萨拉克斯之塔基座附近扎营的联盟斥候，他发布了刺杀Athrikus的任务。",al={"任务发布者","巴苏尔","巴苏尔·影击"}},{q="任务中提到的Delgren是谁？",a="净化者德尔格伦是一位驻扎在附近的联盟盟友，他派遣你去与巴苏尔协调，以消灭这个恶魔邪教。",al={"德尔格伦","净化者德尔格伦"}},{q="Athrikus被打败后会发生什么？",a="巴苏尔确认Athrikus的死对该地区的恶魔行动造成了致命打击，尽管他警告说黑暗势力终将重新集结。",al={"athrikus死后","奥萨拉克斯之塔的终局"}},{q="奥萨拉克斯之塔对黑海岸为何构成威胁？",a="居住在塔内的邪教徒和术士练习邪能法术，并将恶魔召唤到暗夜精灵的土地上，威胁着荒野和附近的定居点。",al={"为什么要清理高塔","奥萨拉克斯的威胁"}}},fp="22,209,20.302.0,17.346.1,25.180.0,37.116.0,21.115.0,38.115.0,40.140.1,53.148.0"}
P.entries["quest:1147"] = {n="疯狂的虫群",s="铁石营地的摩克塔·克林说，贝尔格罗姆想要把异种虫赶回它们爬出来的深渊里去。摩克塔自己的作战小队已经半死不活，无法完成任务，所以他请求你去南边的锈锤挖掘场对付那些异种虫。",h="铁石营地的摩克塔·克林说，贝尔格罗姆想要把异种虫赶回它们爬出来的深渊里去。摩克塔自己的作战小队已经半死不活，无法完成任务，所以他请求你去南边的锈锤挖掘场对付那些异种虫。",kw={"贝尔格罗姆","探险者协会","铁石营地","摩克塔·克林","锈锤挖掘场","闪光平原","异种虫","千针石林"},sec={{t="半死不活的作战小队",b="在完成“虫群的增长（2）”之后，摩克塔·克林说，贝尔格罗姆认为异种虫是一个威胁，并希望将它们赶回它们所来自的深渊。在杀死了探险者协会派来的矮人之后，摩克塔的作战小队已经无法再次战斗，没有帮助就无法完成任务。锈锤挖掘场位于南面，摩克塔认为那里已经没有矮人了。你需要击杀搜寻者、巢穴工蜂和入侵者这些异种虫，在任务完成之前，摩克塔的小队无法离开。"},{t="摩克塔的感谢",b="摩克塔开玩笑说，你身上沾满的体液实际上让你看起来顺眼多了，虽然你身上确实臭气熏天。摩克塔警告你离科多兽远点，并说这股臭味足以证明你为对抗异种虫做出了贡献。"}},faq={{q="异种虫的巢穴在哪里？",a="在铁石营地南边的锈锤挖掘场。",al={"异种虫位置","虫子在哪里","挖掘场在哪里"}},{q="为什么摩克塔·克林的队伍自己无法处理这些虫子？",a="摩克塔的作战小队在杀死了探险者协会派来的矮人后已经半死不活了，在这种状态下他们无法进行下一场战斗。",al={"为什么要帮助摩克塔","作战小队为什么受伤","摩克塔小队的状态"}},{q="是谁想要把异种虫赶回去？",a="贝尔格罗姆认为异种虫是威胁，想要把它们赶回它们爬出来的深渊里。",al={"谁想消灭异种虫","贝尔格罗姆关于异种虫的命令"}},{q="必须击败哪种异种虫？",a="异种虫搜寻者、异种虫巢穴工蜂和异种虫入侵者，每种各五个。",al={"要击杀哪种异种虫","异种虫目标"}},{q="挖掘场里还有矮人吗？",a="摩克塔说那里应该没有需要对付的矮人了。",al={"锈锤挖掘场还有矮人吗","探险者协会在挖掘场"}}},fp="15,230,21.486.0,15.216.1,42.50.0,60.141.0,35.107.0,40.77.0,40.63.0"}
P.entries["quest:1148"] = {n="虫群的样本",s="你在千针石林翻看一片碎裂的异种虫甲壳时发现，它的外壳组织得如此紧密，坚硬得令人惊叹，这种生物似乎非常强大且高度进化。在十字路口的科兰可能会想要研究更多这种生物。",h="你在千针石林翻看一片碎裂的异种虫甲壳时发现，它的外壳组织得如此紧密，坚硬得令人惊叹，这种生物似乎非常强大且高度进化。在十字路口的科兰可能会想要研究更多这种生物。",kw={"甲壳","十字路口","巨人旷野","心脏","科兰","异种虫","利爪","千针石林"},ang={["faction:Horde"]="这是部落的事物：这些样本必须交予十字路口的科兰。"},sec={{t="好奇的甲壳",b="仔细观察后你会发现，这些几丁质的构造如此致密，是你从未见过的。身体的其他部位也展现出同样的强大力量和高度进化的特征。你意识到，在十字路口的科兰一定会很高兴能研究更多这种生物，以了解它们的本性和起源。所需的样本包括：一颗异种虫心脏、五只异种虫利爪和三片完整的异种虫甲壳。"},{t="科兰的样本",b="科兰很高兴，他说这些样本，连同在巨人旷野发现的虫卵，为理解这些昆虫究竟是什么，以及它们在寻求什么，开了个好头。"}},faq={{q="谁想要这些异种虫部件？",a="十字路口的科兰，他想要研究更多这种生物。",al={"科兰是谁","虫群的碎片任务交付","谁在研究异种虫"}},{q="任务从哪里开始？",a="当你查看千针石林里的碎裂的异种虫甲壳时，任务就开始了。",al={"如何开始虫群的碎片","碎裂的异种虫甲壳开启任务","在哪里找到甲壳"}},{q="科兰需要哪些样本？",a="一颗异种虫心脏、五只异种虫利爪和三片完整的异种虫甲壳。",al={"需要什么物品","异种虫部件列表","我需要收集什么"}},{q="为什么科兰要研究异种虫？",a="研究更多这种生物或许能揭示它们的本性和起源。",al={"为什么要研究异种虫","科兰了解到了什么"}}},fp="18,256,18.418.0,20.200.1,31.74.0,22.75.0,32.77.0,40.66.0"}
P.entries["quest:1149"] = {n="信仰的试炼",s="信仰试炼是由隐士多恩·平原行者在千针石林的峡谷深渊上方主持的一种精神仪式。它挑战部落的冒险者，要求他们从一块危险的木板上踏入下方的开阔深渊，以证明他们的决心。",h="信仰试炼是由隐士多恩·平原行者在千针石林的峡谷深渊上方主持的一种精神仪式。它挑战部落的冒险者，要求他们从一块危险的木板上踏入下方的开阔深渊，以证明他们的决心。",kw={"多恩·平原行者","部落","信仰之跃","木板","耐力试炼","信仰试炼","千针石林"},ang={["class:Priest"]="那些终日致力于培养对更高力量信仰的牧师们，发现自己面临着将理论上的信念转化为实际身体行动的挑战。",["faction:Horde"]="这些试炼反映了将初生的部落在卡利姆多团结在一起的核心价值观：绝对的信念、对抗恶劣环境的韧性以及不屈的意志。",["race:Tauren"]="对于舒哈鲁来说，在卡利姆多神圣的土地上进行成人礼是一种古老的传统，而多恩的试炼则要求人们对不可见的事物展现出源自本能的信任。"},sec={{t="精神的衡量",b="多恩·平原行者居住在千针石林一处偏僻的瞭望点，俯瞰着那些被风雕琢的尖塔，思考着构成生命体的各个方面：心智、身体和精神。多恩并没有依赖简单的部落传统，而是通过他自己的试炼来衡量冒险者内心真正的特质。他认为，虽然信念可以有多种形式，但最核心的品质仅仅是拥有足够的毅力去相信某件事，甚至不惜为此赌上自己的性命。"},{t="跃入虚空",b="这项试炼看似直截了当。祈求者会被传送到一座高耸石针的顶端，站在悬于虚空之上的风化木板上。要通过试炼，就必须克服自我保护的本能，在没有任何生存保证的情况下踏入深渊。跳下去的人会发现自己在下落过程中被奥术或精神力量托住，并被瞬间传送回安全地带，从而证明他们的精神已经磨练得足以面对未来未知的挑战。"}},faq={{q="谁是多恩·平原行者？",a="多恩·平原行者是一位隐居在千针石林上方偏远悬崖营地的牛头人。他担任着精神导师的角色，寻找部落的冒险者来测试他们凡人本质的各个方面：信仰、耐力和力量。",al={"多恩·平原行者背景故事","信仰试炼发布者","千针石林任务发布者"}},{q="从木板上跳下去会死吗？",a="不会。虽然从石针尖塔上坠落看起来必死无疑，但这项试炼本质上是一种信任的考验。当你踏出木板的那一刻，魔法结界会在你下落的过程中接住你，并将你完好无损地传送回多恩·平原行者的洞穴。",al={"跳下去会死吗","信仰试炼摔落伤害","信仰试炼危险吗"}},{q="通过信仰试炼后会发生什么？",a="证明你的信仰仅仅是多恩这一系列试炼的开端仪式。一旦你的精神被认定为能够接受挑战，多恩便会立即在“耐力试炼”中考验你的身体韧性。",al={"信仰试炼之后是什么","信仰试炼任务链","多恩·平原行者的后续任务"}},{q="为什么多恩说失败意味着意识到虚空的广袤？",a="这是多恩对死亡的一种残酷哲学提醒。在他看来，那些缺乏内在火焰去全力以赴投入挑战的人，可能会失去他们的生命——以及灵魂——坠入活人世界之外那无尽的虚空之中。",al={"虚空的广袤含义","多恩·平原行者关于虚空的语录"}},{q="联盟的冒险者可以参加这个试炼吗？",a="不可以。多恩·平原行者只会将他的智慧和精神指引传授给那些在卡利姆多南部危险峡谷中穿行的部落勇士。",al={"信仰试炼是部落专属吗","联盟可以做信仰试炼吗"}},{q="信仰试炼在哪里进行？",a="试炼始于多恩在千针石林峡谷壁上的营地，该处通过魔法连接到耸立在峡谷底部的孤立石针上那令人目眩的悬崖边缘。",al={"信仰试炼位置","千针石林的木板在哪里"}}},fx={f9bf32d9={q="多恩·平原行者为什么要考验你的信念？",a="多恩·平原行者认为，每个生命都由精神、身体和心智塑造。有些品质受文化传统影响，有些则只能从内心深处发掘。多恩设下这些试炼，旨在衡量你的内在力量，并让你的精神为艰难险阻做好准备。他要求你盲目跃入峡谷的狂风之中，以证明你拥有信念与信任，即使无法保证生还也敢于一跃，从而确保你的心智已准备好迎接更大的挑战。",al={"多恩为什么要你完成这件事","多恩·平原行者的动机","为什么要进行信念飞跃试炼"}}},fp="13,255,23.490.0,22.488.1,25.251.0,35.246.1,45.190.1,69.219.0,40.159.0,40.181.0"}
P.entries["quest:115"] = {n="暗影魔法",s="“暗影魔法”是治安官马瑞斯发布的一项绝望任务，旨在瓦解黑石兽人入侵赤脊山的黑暗势力。黑石暗影施法者们将受到恶魔污染的午夜宝珠带到了战场，利用黑暗能量对苦苦支撑的湖畔镇守军发动攻击。夺取并摧毁这些被诅咒的圣物，对于守住小镇的防线至关重要。",h="“暗影魔法”是治安官马瑞斯发布的一项绝望任务，旨在瓦解黑石兽人入侵赤脊山的黑暗势力。黑石暗影施法者们将受到恶魔污染的午夜宝珠带到了战场，利用黑暗能量对苦苦支撑的湖畔镇守军发动攻击。夺取并摧毁这些被诅咒的圣物，对于守住小镇...",kw={"黑石兽人","受恶魔污染","湖畔镇","治安官马瑞斯","午夜宝珠","赤脊山","暗影魔法","暗影施法者"},ang={["class:Paladin"]="对抗暗影施法者并夺取受恶魔污染的圣物，直接履行了清除凡人领域恶魔腐化的神圣职责。",["class:Warlock"]="午夜宝珠证明了黑石氏族挥之不去的邪能根源，也让术士得以窥见兽人施法者所掌握的原始恶魔能量。",["faction:Alliance"]="湖畔镇已处于被攻陷的边缘，几乎没有任何来自暴风城的增援；剥夺黑石氏族的黑暗火力对于该地区的生存至关重要。"},sec={{t="邪恶军火库",b="虽然蛮力一直是黑石氏族的标志，但他们最近对赤脊山的入侵却展现出了一种更加阴险的威胁。入侵者用擅长黑暗力量的暗影施法者充实了自己的队伍。这些施法者不仅仅依靠法术，他们还通过被称为“午夜宝珠”的恶魔污染圣物来引导邪能和暗影能量。这些圣物给当地的民兵造成了惨重的损失，使得本就绝望的战争天平进一步向入侵者倾斜。"},{t="遏制污染",b="治安官马瑞斯在镇中心统筹着湖畔镇捉襟见肘的防御，他明白凡铁很难轻易摧毁这些黑暗圣物。如果让黑石兽人保留他们的午夜宝珠，赤脊山的东部防线很可能会彻底崩溃。通过命令冒险者击杀暗影施法者并夺取宝珠，马瑞斯并不是想利用这种危险的魔法，而是为了彻底摧毁这些恶魔圣物。"}},faq={{q="什么是午夜宝珠？",a="午夜宝珠是黑石暗影施法者携带的、受到恶魔污染的能量导管。他们利用这些宝珠聚焦黑暗魔法，对赤脊山的凡人守军造成毁灭性的打击。",al={"午夜宝珠","什么是午夜宝珠","午夜宝珠有什么用"}},{q="为什么治安官马瑞斯想要这些宝珠？",a="治安官马瑞斯希望将这些宝珠彻底从战场上清除，以削弱黑石暗影施法者的进攻力量。他打算安全地处理并摧毁这些恶魔圣物。",al={"为什么要收集午夜宝珠","马瑞斯 宝珠","马瑞斯对宝珠的计划"}},{q="谁是黑石暗影施法者？",a="他们是黑石兽人中的施法者，修炼暗影和邪能污染魔法，为该氏族的蛮力战士提供魔法火力和诅咒支援。",al={"黑石暗影施法者","谁使用暗影魔法","黑石施法者"}},{q="在哪里可以找到暗影施法者？",a="黑石暗影施法者部署在赤脊山东北部各处的黑石氏族营地和防御工事中。",al={"暗影施法者在哪里","暗影施法者位置","黑石暗影施法者营地"}},{q="湖畔镇会研究或使用这些宝珠吗？",a="不会。治安官马瑞斯认为它们非常危险且受到恶魔污染，并坚定地表示，没有这些东西世界会更美好。他明确的目标就是将其立即销毁。",al={"湖畔镇会使用宝珠吗","联盟可以使用宝珠吗","宝珠有用吗"}},{q="为什么赤脊山会出现恶魔魔法？",a="黑石氏族有着与黑暗和邪能实体勾结的悠久历史，其源头可以追溯到旧部落时期。他们的施法者至今仍在利用恶魔圣物和暗影魔法来支持他们的征服行动。",al={"为什么赤脊山有恶魔","黑石恶魔污染","赤脊山邪能"}}},fp="12,253,18.351.0,20.340.0,23.158.0,40.183.0,36.161.0,34.106.0,37.152.0,43.184.0"}
P.entries["quest:1150"] = {n="耐力的试炼",s="耐力试炼是千针石林中由多恩·平原行者主持的一系列精神考验中的第二项仪式。在已经证明了自己的精神勇气之后，部落冒险者们需要深入飞羽洞穴，引出凶猛的鹰身人首领——葛恩卡·血啸，以将自己的肉体耐力推向极限。",h="耐力试炼是千针石林中由多恩·平原行者主持的一系列精神考验中的第二项仪式。在已经证明了自己的精神勇气之后，部落冒险者们需要深入飞羽洞穴，引出凶猛的鹰身人首领——葛恩卡·血啸，以将自己的肉体耐力推向极限。",kw={"多恩·平原行者","乱风岗","葛恩卡·血啸","飞羽洞穴","尖啸峡谷","耐力试炼","千针石林","老屋"},ang={["faction:Horde"]="多恩向所有部落种族提供这些挑战，因为他相信每个部落的年轻战士在面对卡利姆多的危险之前，都必须经受住苦难的磨砺。",["race:Tauren"]="对于牛头人旅行者来说，多恩·平原行者的试炼反映了传统的成人礼，旨在测试受训者的肉体耐力是否能与大地母亲的精神指引相匹配。"},sec={{t="身体的试炼",b="居住在老屋的多恩·平原行者承担起了在年轻战士闯荡更广阔、更残酷的世界之前磨砺他们的责任。如果说初次仪式证明了旅行者拥有坚定的信仰和沉稳的意志，那么这项试炼则考验的是肉体的坚韧。在多恩的哲学中，真正的准备工作需要在精神奉献、心理纪律和在持续残酷环境中生存所需的纯粹耐力之间达成和谐。"},{t="突入飞羽洞穴",b="这项试炼选择的场地是飞羽洞穴，这是一个隐藏在乱风岗以西的尖啸峡谷中的危险洞穴。这里聚集着充满敌意的鹰身人，对于独自旅行的人来说，洞穴潜藏着巨大的危险。为了完成试炼，挑战者必须杀入地下的巢穴深处，破坏鹰身人囤积的物资，并抵御鹰身人族群凶猛的反击，直到她们的族长葛恩卡·血啸亲自现身。"}},faq={{q="谁发布了耐力试炼？",a="该任务由多恩·平原行者发布，他是一位驻扎在千针石林峡谷峭壁上的老屋的年长牛头人。",al={"耐力试炼任务发布者","谁开启耐力试炼","多恩·平原行者任务"}},{q="飞羽洞穴位于哪里？",a="飞羽洞穴位于千针石林南侧峡谷峭壁的高处，在乱风岗的西边。旅行者必须沿着尖啸峡谷中的蜿蜒小径攀爬，才能到达通往洞穴入口的斜坡。",al={"飞羽洞穴位置","鹰身人洞穴在哪里","尖啸峡谷斜坡"}},{q="如何召唤葛恩卡·血啸？",a="在你杀入飞羽洞穴最深处的房间并破坏鹰身人存放在那里的食物和补给品后，葛恩卡·血啸就会出现，从而迫使她不得不现身保卫自己的巢穴。",al={"召唤葛恩卡","如何刷新葛恩卡·血啸","找到葛恩卡"}},{q="耐力试炼之后是什么？",a="将葛恩卡被斩断的爪子交给多恩·平原行者将证明你的肉体耐力，这会促使他指派你进行他后续考验中的下一项任务：力量试炼。",al={"耐力试炼后的任务","耐力试炼之后的内容","多恩·平原行者的下一项试炼"}},{q="为什么多恩要考验非牛头人的冒险者？",a="多恩认为他的使命是指导部落的所有年轻人，无论其种族或部落如何。他认为未经考验的骄傲在更广阔的世界中等同于死刑，因此坚持要求每位战士都要展示出在身体、心灵和精神上的准备就绪。",al={"为什么多恩帮助部落","多恩·平原行者的哲学","面向其他种族的牛头人试炼"}},{q="在此之前的试炼是什么？",a="在考验身体的耐力之前，多恩要求挑战者进行信仰试炼，这是一次充满危险的虔诚之跃，旨在测试冒险者的精神是否会在恐惧面前动摇。",al={"前置任务","耐力试炼之前的试炼","第一次试炼"}}},fx={["8999be4f"]={q="多恩·平原行者为什么想要你完成这件事？",a="多恩·平原行者认为，让年轻的冒险者为广阔世界中的致命危险做好准备，是他的神圣职责。在确认你的精神与信念无虞后，他坚持要考验你的肉体。让你深入鹰身人的领地，顶住一波又一波狂暴的鹰身人，是为了确认你拥有离开家园庇护后生存所需的耐力和毅力。",al={"多恩为什么要考验耐力","多恩·平原行者的动机","耐力试炼的目的"}},b2efd71b={q="格林卡的爪子有什么用？",a="这只爪子是确凿的证据，证明你曾在飞羽洞穴的中心坚守阵地，挺过鹰身人持续不断的猛攻，并击倒了它们凶悍的族母格林卡·血啸。多恩需要它来确认你在无情的攻击下仍坚持了下来，然后才会交给你下一项试炼。",al={"格林卡的爪子有什么用","为什么我需要格林卡的爪子","格林卡的爪子有什么用处"}},["28ecd26a"]={q="格林卡·血啸是谁？",a="格林卡·血啸是盘踞在乱风岗以西峡谷洞窟中的飞羽鹰身人首领之一。她凶残且极具领地意识，统治着鹰身人巢群的内层圣所。当你闯入飞羽洞穴深处，砸毁它们囤积的补给时，她会怒不可遏地从栖身处飞下，亲自将你杀死。",al={"格林卡是谁","格林卡·血啸的背景","飞羽鹰身人首领"}}},fp="17,345,16.431.0,31.455.0,32.132.0,34.208.0,38.210.0,39.169.0,49.240.0,35.197.0"}
P.entries["quest:1151"] = {n="力量的试炼",s="力量试炼是由千针石林的多恩·平原行者监督的第三项试炼。为了证明他们的体能，部落的勇士们受命去猎杀重击者罗克·阿利姆，这是一个古老的、自由游荡的岩石元素生物，并带回他破碎身躯的残骸作为证明。",h="力量试炼是由千针石林的多恩·平原行者监督的第三项试炼。为了证明他们的体能，部落的勇士们受命去猎杀重击者罗克·阿利姆，这是一个古老的、自由游荡的岩石元素生物，并带回他破碎身躯的残骸作为证明。",kw={"多恩·平原行者","上古之神","岩石元素","罗克·阿利姆","力量试炼","重击者","千针石林","老屋"},ang={["class:Shaman"]="萨满祭司不仅将罗克·阿利姆视为一种障碍，还将其视为一种危险、不受束缚的大地显现，其拒绝屈服的特性扰乱了当地灵魂的平衡。",["faction:Horde"]="完成老屋的仪式可以赢得雷霆崖长者们的尊重，并巩固冒险者在整个卡利姆多的名声。",["race:Tauren"]="对于牛头人朝圣者来说，面对一个未被驯服的岩石之灵是一种传统的和谐与身体意志的考验，展示了猎人忍受并克服大地母亲最严酷力量的能力。"},sec={{t="上古之神时代的残骸",b="很久以前，在上古之神统治时期，原始元素生物遍布世界表面，服侍着它们黑暗的主人。当这些古老的实体被推翻并封印在地下后，元素之灵便失去了与这个位面的羁绊，除非通过现代的法术绑定和召唤，否则大多已从物质界消失。然而，有少数实体顽固且强大到足以无限期地留在艾泽拉斯，而无需魔法锚点。重击者罗克·阿利姆就是这样的一件遗物，他作为那个原始时代的活体回声，徘徊在千针石林的干旱峡谷中。"},{t="千针石林的重击者",b="当地的半人马部族给罗克·阿利姆起了这个绰号，因为当他的石拳击中峡谷地面时，会产生震耳欲聋、如同地震般的撞击声。任何愚蠢或大胆到误入他游荡路径的人都会被砸成尘土。因为罗克·阿利姆代表了原始、未受约束的物理质量，多恩·平原行者指示试炼者击败这头野兽，作为衡量他们勇士精神的直接标准，并要求获得元素生物石之心的碎片作为胜利的证明。"}},faq={{q="这项任务在哪里开始和结束？",a="这项任务由多恩·平原行者提供和完成，他是一位驻扎在老屋的牛头人长者，那是一个坐落在千针石林尖塔高处的一处隐蔽峡谷营地。",al={"任务发布者","交还任务地点","多恩位置"}},{q="重击者罗克·阿利姆是什么？",a="罗克·阿利姆是一位古老的岩石元素生物，自上古之神时代起就一直存在于卡利姆多。与现代召唤的元素生物不同，他拥有足够的内在力量，可以完全凭自己保持在艾泽拉斯的物质形态。",al={"罗克·阿利姆是谁","罗克·阿利姆是什么类型的怪物","元素生物传说"}},{q="为什么半人马称他为“重击者”？",a="峡谷里的半人马部族称他为重击者，是因为当他的石拳砸向路径上的任何东西时，会释放出雷鸣般、翻滚的冲击波。",al={"重击者绰号","半人马对罗克·阿利姆的称呼"}},{q="在峡谷的什么地方可以找到罗克·阿利姆？",a="罗克·阿利姆徘徊在千针石林的西北部，通常巡逻在穿过峡谷底部的干道以南的开阔地带。",al={"罗克·阿利姆刷新点","罗克·阿利姆在哪里"}},{q="这项任务在整个试炼链中处于什么位置？",a="力量试炼是该试炼链中的第三项试炼。它紧随信仰试炼和耐力试炼之后，并且直接位于最终试炼——传说试炼之前。",al={"任务链顺序","what comes next","之前是什么任务"}},{q="为什么多恩要求杀死一个元素生物，而不是野兽或敌人？",a="多恩选择罗克·阿利姆是因为该元素生物是活体岩石和坚不可摧的原始力量的纯粹体现。征服这样的对手证明了对于原始、不可弯曲的大地本身的身体优势。",al={"为什么要杀元素生物","力量试炼的目的"}}},fx={d3b1c16f={q="多恩·平原行者为什么想要你完成这件事？",a="多恩·平原行者要让你接受古老的牛头人仪式，以证明你的实力，然后才能进入最后的试炼。对付普通野兽或士兵无法真正衡量你的力量，因此他要求你挑战古老原始石灵的残存力量。击败罗卡里姆，才能证明你的内在与肉体力量足以战胜古老的元素之力。",al={"多恩·平原行者的动机","多恩为什么要杀死罗卡里姆","为什么要进行力量试炼"}},["67dd1d0a"]={q="罗卡里姆的碎片有什么用？",a="这些碎片是无可辩驳的证据，证明你曾直面重锤者罗卡里姆，并将这位古老元素生物打成碎石。多恩·平原行者需要你胜利的实物证据，才能认可你完成了力量试炼，并获准进入下一项试炼。",al={"罗卡里姆的碎片有什么用","这些碎片有什么用","为什么收集罗卡里姆的碎片"}}},fp="16,300,29.589.0,31.471.0,36.178.0,29.226.0,42.161.0,42.156.0,59.162.0,75.211.0"}
P.entries["quest:1152"] = {n="知识试炼",s="在千针石林经历了关于信仰、耐力和力量的试炼后，多恩·平原行者将部落勇士引向北方的石爪山脉。在那里，一位名叫布劳格·幽魂的睿智萨满正在等待着，准备主持学识试炼。这次试炼将重点从身体的坚韧转向了对这个世界深厚历史和普遍苦难的理解。",h="在千针石林经历了关于信仰、耐力和力量的试炼后，多恩·平原行者将部落勇士引向北方的石爪山脉。在那里，一位名叫布劳格·幽魂的睿智萨满正在等待着，准备主持学识试炼。这次试炼将重点从身体的坚韧转向了对这个世界深厚历史和普遍苦难的...",kw={"布劳格·幽魂","多恩·平原行者","石爪山脉","石爪小径","学识试炼","千针石林","老屋","狂风峭壁"},ang={["class:Shaman"]="布劳格·幽魂代表了一种萨满的世界观，即通过凡人的鲁莽行为，从地精的剥削到古老精灵的孤立，来解读这片土地所遭受的苦难。",["faction:Horde"]="布劳格的试炼迫使部落勇士坦诚地反思他们盟友的声誉，提醒他们兽人和被遗忘者并非这片土地所有麻烦的唯一责任方。",["race:Tauren"]="这些试炼体现了传统的牛头人哲学，即比起原始的嗜血，更看重精神和谐与对历史的理解。"},sec={{t="从信仰到学识",b="在老屋的避难所里，多恩·平原行者督促新兵们完成旨在考验其精神信念、身体耐力和战斗技巧的严苛试炼。然而，仅凭蛮力和盲目的信仰并不能成就一名真正的部落勇士。多恩认识到自己作为导师的能力有限，于是将那些已经证明了自己的勇士送往石爪山脉，在那里，一位年长的萨满可以考验他们的智慧与阅历。"},{t="通往石爪之路",b="旅途将指引旅行者向北穿过贫瘠之地的干旱灌木丛，进入石爪山脉的峭壁之中。在高山之上，靠近通往灰谷的岩石洞穴——石爪小径的入口处，坐落着布劳格·幽魂的隐居所。他注视着这片交战中的前线，那里地精的伐木作业正在破坏森林，而怀有敌意的暗夜精灵正在拼死守卫着他们的祖传疆界。"},{t="更广阔的视角",b="当见到布劳格时，这次试炼的真正目的便显现出来了。布劳格并没有要求盲目的阵营自豪感，而是对艾泽拉斯悲惨的现状进行了反思。他指出，虽然兽人和被遗忘者因战争和腐败而不断受到指责，但几乎每个文明都要对这片土地的困境负责。地精砍伐古木，暗夜精灵对年轻种族怀有深深的不信任。学识试炼要求勇士超越眼前的仇恨，去理解这个伤痕累累的世界更宏大的历史。"}},faq={{q="什么是学识试炼？",a="这是牛头人长者设计的成年仪式中包含的一项指导性试炼。新兵不仅要证明自己拥有身体上的力量和信仰，还必须证明自己具备历史意识，并了解艾泽拉斯共同的过去。",al={"学识试炼的含义","这是什么任务"}},{q="我在哪里可以找到布劳格·幽魂？",a="布劳格·幽魂居住在石爪山脉，位于狂风峭壁附近，就在连接石爪山脉和灰谷的石爪小径洞穴入口处。",al={"布劳格·幽魂的位置","布劳格在哪里"}},{q="多恩·平原行者为什么要让你离开？",a="多恩负责监管千针石林的信仰、耐力和力量试炼，但他承认自己并不擅长教授这个世界的学识。他将合格的新兵引荐给布劳格，一位拥有足够智慧来考验心灵的萨满。",al={"为什么去石爪山脉","多恩为什么要引荐你"}},{q="旅途中有哪些威胁需要注意？",a="多恩特别警告说，暗夜精灵在灰谷和石爪山脉附近的边境地带巡逻，将部落的存在视为入侵。狂风峭壁周边地区也充斥着动荡的地精伐木作业。",al={"布劳格面临的危险","石爪小径的危险"}},{q="布劳格·幽魂对世界冲突的看法是什么？",a="布劳格认为所有凡人种族都要为世界的苦难负责。虽然兽人和被遗忘者经常被对手妖魔化，但他指出，地精的贪婪和暗夜精灵的傲慢在卡利姆多和洛丹伦造成了同样的伤害。",al={"布劳格·幽魂的哲学","布劳格的信仰"}},{q="什么是石爪小径？",a="石爪小径是一条连接石爪山脉的狂风峭壁与南部灰谷古老林地边缘的重要山间隧道系统。",al={"什么是石爪小径","石爪小径洞穴"}}},fp="12,353,18.452.0,22.411.0,21.539.1,25.238.0,33.169.0,41.239.0,54.226.0,56.254.0,27.160.0"}
P.entries["quest:1153"] = {n="新的矿石样本",s="陶拉祖营地的塔特纳克·钢炉听闻了一些传言，说遥远的南方有狗头人携带着一种不同寻常的矿床。为了满足大酋长萨尔对更强力武器的需求，他派遣部落的冒险者前往千针石林，去获取一份未精炼的矿石样本进行测试。",h="陶拉祖营地的塔特纳克·钢炉听闻了一些传言，说遥远的南方有狗头人携带着一种不同寻常的矿床。为了满足大酋长萨尔对更强力武器的需求，他派遣部落的冒险者前往千针石林，去获取一份未精炼的矿石样本进行测试。",kw={"陶拉祖营地","狗头人","塔特纳克·钢炉","千针石林","萨尔","未精炼的矿石样本","选择武器"},ang={["faction:Horde"]="陶拉祖营地是重要的南部堡垒，贡献物资直接有助于大酋长的军事准备。",["profession:Blacksmithing"]="对于部落的铁匠来说，确保获得新的外来金属矿床对于保持边境武装以抵御周围的威胁至关重要。",["profession:Mining"]="勘探者们明白在未开发的南部峡谷中，由穴居生物挖掘出的原始、未精炼的矿脉所蕴含的价值。"},sec={{t="铁匠的雄心",b="铁匠塔特纳克·钢炉在尘土飞扬的陶拉祖营地前哨站工作，直接接受奥格瑞玛的监督。在已经供应了由当地半人马武器改造而成的装备后，塔特纳克依然渴望向大酋长萨尔证明自己的手艺。当路过的旅行者拒绝将他们从南方的狗头人身上掠夺来的一块奇怪矿石卖给他时，塔特纳克将这种拒绝视为对自己手艺和部落的侮辱。"},{t="前往千针石林",b="任务将部落的侦察兵从南贫瘠之地平坦的平原引向千针石林高耸的峡谷迷宫。在那里，地下害虫在岩架和悬崖间挖掘。通过直接从当地的狗头人挖掘工手中撬下未精炼的矿石块，冒险者们带回了塔特纳克所需的原材料，以评估这种新石头是否能被锻造成足以支持萨尔战争大业的武器。"}},faq={{q="塔特纳克·钢炉是谁？",a="塔特纳克·钢炉是一位驻扎在南贫瘠之地陶拉祖营地的兽人武器匠。他致力于锻造武器以供应部落的边境防御，并经常寻找新材料来让大酋长萨尔刮目相看。",al={"塔特纳克","陶拉祖营地铁匠","塔特纳克是谁"}},{q="这个矿石样本来自哪里？",a="这种未精炼的矿石样本是由栖息在千针石林蜿蜒峡谷中的狗头人携带的，该地区位于贫瘠之地边缘升降梯的正南方。",al={"矿石在哪里","矿石位置","千针石林矿石"}},{q="塔特纳克为什么对那些路过的旅行者感到愤怒？",a="一群从南方抵达的旅行者向塔特纳克展示了一块从被杀死的狗头人身上取下的奇怪矿石，但拒绝卖给他。塔特纳克将他们囤积重要材料的行为视为对大酋长的不爱国侮辱，并咒骂他们是懦夫。",al={"为什么塔特纳克生气","旅行者的矿石","塔特纳克与旅行者"}},{q="塔特纳克会用这些矿石做什么？",a="他打算分析其冶金特性并测试其强度。如果这种金属被证明足够耐用，他计划用它锻造一件原型武器，并直接呈献给奥格瑞玛的大酋长萨尔。",al={"矿石会有什么用途","他为什么想要矿石"}},{q="在执行此任务前必须完成什么前置条件？",a="在接受此任务之前，你必须完成“选择武器”，在该任务中，你需要从威胁陶拉祖营地的各个半人马部落那里收集特定的武器，以证明当地的军械可以重新利用。",al={"前置任务","之前的任务","选择武器"}},{q="为什么千针石林的狗头人会携带这种矿石？",a="狗头人是强迫性的掘洞者和矿工，它们在岩架和悬崖中无休止地挖掘。在千针石林，它们的挖掘活动发现了一些地表居民极少触及的异常地下矿床。",al={"狗头人采矿","千针石林的狗头人"}}},fp="16,172,18.414.0,29.315.0,29.199.0,37.130.0,49.228.0,37.212.0,53.173.0,54.194.0"}
P.entries["quest:1154"] = {n="知识试炼",s="知识试炼是布劳格·幽魂在石爪小径入口处设立的一项试炼，它考验的是部落冒险者的头脑，而非体能。要通过试炼，寻求者必须深入灰谷闹鬼的兽穴，找回一本记载龙族历史的古籍，并在接受测验前研读其中的内容。",h="知识试炼是布劳格·幽魂在石爪小径入口处设立的一项试炼，它考验的是部落冒险者的头脑，而非体能。要通过试炼，寻求者必须深入灰谷闹鬼的兽穴，找回一本记载龙族历史的古籍，并在接受测验前研读其中的内容。",kw={"灰谷","布劳格·幽魂","陶拉祖营地","deathwing","朵丹尼尔兽穴","多恩·平原行者","巨龙的遗产","石爪小径","知识试炼"},ang={["class:Druid"]="进入朵丹尼尔兽穴的德鲁伊旅者将直面那些曾与翡翠梦境合而为一，却最终被腐化并杀害的暗夜精灵同胞的悲剧。",["faction:Horde"]="这项试炼反映了部落需要既能理解卡利姆多深厚历史，又能在灰谷危险的精灵废墟中穿行而不会陷入无知的战士。"},sec={{t="试炼的转变",b="在千针石林的盐原和高原上证明了自己的体能和坚定信念后，参加多恩·平原行者系列试炼的候选者会被派往北方的石爪山脉，寻找布劳格·幽魂。布劳格驻扎在石爪小径入口附近，他不屑地认为之前的挑战不过是简单的体力锻炼。为了真正出色地为部落效力，冒险者需要具备敏锐且严谨的智慧，并做好了解古老历史的准备，而不是仅仅依靠击杀野兽。"},{t="朵丹尼尔的阴影",b="布劳格指引申请者穿过石爪小径，进入灰谷南部的森林地带。在那里，隐藏在碎木岗哨南面树冠下的是朵丹尼尔兽穴。这座地下圣所是一处险恶的废墟，闹鬼的暗夜精灵德鲁伊和屠杀他们的凶残生物在此徘徊。在下层洞穴深处的石制讲台上，放着试炼的奖励：《巨龙的遗产》，这是一本详细记录了伟大的巨龙军团的起源和腐化过程的珍稀手稿。"},{t="学习或受苦",b="拿到书只是布劳格试炼的一半。在交出书卷之前，寻求者必须将其中的教诲铭记于心。布劳格在收到书后会立即拿走，并测试寻求者对泰坦赋予力量的守护者以及导致Deathwing诞生的灾难性背叛的记忆。如果没能研读或回答错误，寻求者会被瞬间传送至横跨卡利姆多的南贫瘠之地的陶拉祖营地，只能蒙羞跋涉回石爪山脉。"}},faq={{q="布劳格·幽魂是谁？",a="布劳格·幽魂是一位驻扎在石爪山脉石爪小径入口附近的长者牛头人萨满。他是继多恩·平原行者之前的试炼后的考官，负责测试部落勇士是否具备与之原始的战斗技巧相辅相成的智慧和知识。",al={"布劳格·幽魂","谁发布了知识试炼","石爪山脉任务发布者"}},{q="《巨龙的遗产》这本书在哪里？",a="这本书位于灰谷南部的朵丹尼尔兽穴内，就在碎木岗哨的正南方。它被放置在兽穴深处中央平台上的一个石制讲台上。",al={"巨龙的遗产位置","书在哪里","朵丹尼尔书籍地点"}},{q="朵丹尼尔兽穴里潜伏着什么？",a="这处兽穴曾是暗夜精灵德鲁伊的圣所，但悲剧降临于此。现在这里到处都是死去德鲁伊的亡魂以及屠杀他们的致命入侵者，对任何闯入者来说都是一座致命的迷宫。",al={"朵丹尼尔的敌人","谁守护着这本书","灰谷兽穴"}},{q="为什么布劳格要求我在上交之前阅读这本书？",a="布劳格在书归还时会拿走它并测试你的记忆。他希望你提前研读，因为这项试炼考察的是知识，而不是单纯地取回一件物品。",al={"为什么要阅读巨龙的遗产","知识试炼测验","回答错误会怎样"}},{q="这个任务如何融入更宏大的试炼系列？",a="这项试炼紧随多恩·平原行者在千针石林老屋发起的“信仰试炼”之后。如果说多恩是在考验你在致命困境中的勇气与生存能力，那么布劳格就是在评估你的知识储备和历史意识。",al={"信仰试炼任务线","知识试炼之前是什么","多恩·平原行者试炼"}},{q="《巨龙的遗产》的主题是什么？",a="这份手稿记载了泰坦赋予五大巨龙守护者力量以保卫艾泽拉斯的神话历史。最重要的是，它触及了大地守护者耐萨里奥的堕落，以及他转变为被称为Deathwing的怪物毁灭者的过程。",al={"巨龙的遗产故事","书籍知识","这本书是关于什么的"}}},fx={["0efda427"]={q="布劳格·幽魂为什么要我寻找巨龙的遗产？",a="布劳格·幽魂考验的是你的头脑，而不是力量。你已经经受了多恩·平原行者的体能试炼，现在要接受对智力、应变能力和求知意愿的考验。布劳格派你独自前往危险之地，取回并领悟古老知识，以此判断你是否具备完成这一系列试炼所需的智慧。",al={"布劳格为什么考验我","为什么要找巨龙的遗产","布劳格·幽魂为什么要考验我"}}},fp="12,326,21.528.0,24.518.0,15.477.1,23.306.0,48.223.0,39.236.0,58.180.1,54.232.0,56.260.0"}
P.entries["quest:1159"] = {n="知识试炼",s="“博学试炼”的这一阶段会将部落冒险者送往无尽之海，前往洛丹伦废墟。在石爪山脉解开布劳格·幽魂最初的谜题后，你将受命去幽暗城中寻找一位亡灵族的前人类学者。",h="“博学试炼”的这一阶段会将部落冒险者送往无尽之海，前往洛丹伦废墟。在石爪山脉解开布劳格·幽魂最初的谜题后，你将受命去幽暗城中寻找一位亡灵族的前人类学者。",kw={"apothecarium","布劳格·幽魂","多恩·平原行者","洛丹伦","帕科瓦·芬塔拉斯","博学试炼","千针石林","幽暗城","老屋"},ang={["faction:Horde"]="该任务展现了将新生的部落紧密联系在一起的跨大陆合作，将牛头人的求知者与洛丹伦冷酷的档案管理员联结了起来。",["race:Tauren"]="对于一名牛头人初试者来说，离开卡利姆多广阔的平原和高耸的台地，去探索幽暗城中毒气弥漫、幽闭压抑的下水道，使得这段旅程不仅是一次历史试炼，更是一次文化试炼。",["race:Undead"]="会见帕科瓦突显了这一点：尽管腐朽且已成亡灵，像他这样的被遗忘者学者依然保留了陷落的洛丹伦王国中浩瀚的学术传统与文献记录。"},sec={{t="学术联盟",b="在证明了自己的勇气并理清了记录在《巨龙的遗产》中的巨龙军团历史后，布劳格·幽魂承认自己的知识也有局限。布劳格没有将试炼局限在卡利姆多，而是指引你前往洛丹伦废墟之下的亡灵首都，以此展现部落联结那广阔且令人惊讶的触角。"},{t="怀疑主义历史学家",b="在Apothecarium潮湿的走廊里居住着帕科瓦·芬塔拉斯。作为曾经北方王国受人尊敬的人类编年史家，帕科瓦对知识的追求在天灾军团的入侵和他转变为被遗忘者后得以幸存。面对一个声称已经完成了千针石林精神与肉体试炼的外来者，在帕科瓦直接确认你的价值之前，他拒绝相信你不仅仅是一个投机取巧的雇佣兵。"}},faq={{q="为什么牛头人的试炼会把我送到幽暗城这么远的地方？",a="布劳格·幽魂承认，对博学的真正掌握不仅仅在于卡利姆多的历史。他将你引荐给帕科瓦·芬塔拉斯——一位在洛丹伦沦为亡灵后依然保有知识的著名人类学者，以此来测试你对更广阔世界历史的理解。",al={"为什么要去幽暗城","为什么是洛丹伦","布劳格派我去亡灵处"}},{q="帕科瓦·芬塔拉斯究竟在哪里？",a="帕科瓦·芬塔拉斯居住在幽暗城，具体来说，他站在Apothecarium区的南侧桥梁上。",al={"帕科瓦在哪里","帕科瓦位置","寻找芬塔拉斯"}},{q="帕科瓦·芬塔拉斯生前是谁？",a="生前，帕科瓦·芬塔拉斯是洛丹伦王国一位颇有成就的人类历史学家。在屈服于亡灵瘟疫并加入希尔瓦娜斯的被遗忘者后，他坚持了自己的学术追求，将智慧转向了不同且更为黑暗的研究课题。",al={"帕科瓦·芬塔拉斯背景故事","谁是帕科瓦","芬塔拉斯背景"}},{q="为什么帕科瓦不相信是布劳格派我来的？",a="帕科瓦对外来者深表怀疑。他觉得一个普通的冒险者能从千针石林的尖塔上一跃而下、击败原始元素并找回古代遗物是不可思议的，因此他认为你只是在酒馆里听到了传言。",al={"为什么帕科瓦很粗鲁","帕科瓦的反应","帕科瓦不相信我"}},{q="这个任务是哪项更大试炼的一部分？",a="该任务是“博学试炼”任务线的中间环节，该任务线本身源于多恩·平原行者在老屋发起的试炼。它旨在评估一名初试者是否不仅拥有战斗技巧和勇气，还具备足以匹配部落勇士的智慧与历史认知。",al={"这是什么任务线","信仰试炼任务线","什么是博学试炼"}},{q="在找到帕科瓦之后接下来要做什么？",a="在帕科瓦屈尊向你提出他自己的历史谜题之前，他要求你代表他在东部王国完成一件差事，以验证你是否真的是布劳格所宣称的那位有能力的英雄。",al={"找到帕科瓦之后接下来做什么","幽暗城之后的下一个任务","与芬塔拉斯交谈后"}}},fx={["670eb265"]={q="布劳格·幽魂为什么派你去幽暗城？",a="布劳格·幽魂已经考验了你的初步知识，但他的职责只是引导你通过知识试炼的第一阶段。为了真正考验你对世界的理解，他明白下一个问题需要更广阔的视角。于是他派你去找帕科瓦·芬塔拉斯——这位洛丹伦的著名历史学家如今已加入被遗忘者——让一位追求不同形式启迪的学者来评判你对历史与真相的求索。",al={"布劳格为什么派我去","布劳格·幽魂的动机","布劳格为什么让我去幽暗城"}}},fp="12,263,20.359.0,23.461.0,57.270.0,43.120.0,34.266.0,42.255.0,40.295.0,39.206.0"}
P.entries["quest:116"] = {n="旱季",s="“干涸的时光”是湖畔镇的酒吧老板丹尼尔委托的一项任务，旨在城镇遭围困期间为旅店补充酒水。由于黑石兽人的入侵切断了贸易路线，丹尼尔不得不依赖勇敢的信使从暴风城的各个领地寻回特产酒精饮料。",h="“干涸的时光”是湖畔镇的酒吧老板丹尼尔委托的一项任务，旨在城镇遭围困期间为旅店补充酒水。由于黑石兽人的入侵切断了贸易路线，丹尼尔不得不依赖勇敢的信使从暴风城的各个领地寻回特产酒精饮料。",kw={"酒吧老板丹尼尔","干涸的时光","葛瑞姆·雷酒","湖畔镇","葡萄酒","月光酒","赤脊山","甜朗姆酒","雷酒"},ang={["faction:Alliance"]="这项跑腿任务展示了赤脊山道路安全状况的恶化如何影响日常生活，并要求联盟信使将暴风城、艾尔文森林、西部荒野、暮色森林和赤脊山之间被切断的贸易路线重新连接起来。",["race:Dwarf"]="即使在兽人入侵期间，人类的旅店依然依赖矮人的酿酒技术，甚至派信使远赴西部荒野来获取葛瑞姆·雷酒那著名的雷酒。"},sec={{t="围困中的城镇",b="湖畔镇正处于前线，面临着从石堡要塞涌下的黑石氏族兽人的猛烈进攻。由于常规补给线被切断，道路变得不再安全，当地旅店老板酒吧老板丹尼尔面临着酒桶即将告罄的燃眉之急。为了让受惊的村民和受困的城镇卫兵保持士气，他转而求助于外来的旅行者，希望能绕过路障补充库存。"},{t="王国大巡游",b="补充丹尼尔的酒窖绝非简单的配送工作，这需要穿越整个暴风城王国进行长途跋涉。信使必须从王都获取一桶葡萄酒，从闪金镇的Lion's Pride Inn获取甜朗姆酒，从暮色森林阴沉的夜色镇获取烈性月光酒，并从西部荒野的山丘上获取葛瑞姆·雷酒酿造的一桶特制雷酒。"}},faq={{q="为什么湖畔镇的酒水快要耗尽了？",a="黑石兽人对赤脊山的入侵完全破坏了正常的贸易和补给车队。酒吧老板丹尼尔的常规货运早已逾期，在城镇承受巨大战争压力的同时，他的旅店面临着断酒的威胁。",al={"为什么叫干涸的时光","为什么湖畔镇没有酒","酒吧老板丹尼尔的难题"}},{q="我该去哪里寻找酒吧老板丹尼尔需要的酒？",a="你必须从王国各地收集四样物品：从暴风城的酒馆里获取葡萄酒，从艾尔文森林闪金镇获取甜朗姆酒，从暮色森林的夜色镇获取月光酒，以及从西部荒野山丘上的葛瑞姆·雷酒那里获取一桶雷酒。",al={"干涸的时光任务酒水地点","去哪里买葡萄酒月光酒和朗姆酒","去哪里给丹尼尔找酒"}},{q="葛瑞姆·雷酒是谁？",a="葛瑞姆·雷酒是一位居住在西部荒野山丘上的矮人酿酒师。酒吧老板丹尼尔认为他的雷酒是不可或缺的库存，但想要得到它，必须先完成葛瑞姆交付的一项额外跑腿任务，才能确保获得新鲜的一桶酒。",al={"葛瑞姆·雷酒的位置","葛瑞姆·雷酒在哪里","西部荒野的雷酒"}},{q="酒吧老板丹尼尔是谁？",a="丹尼尔是湖畔镇旅店的酒吧老板。为了在黑石兽人的迫近威胁下维持旅店的存货并安抚顾客，他雇佣旅行者亲自前去取回补给。",al={"酒吧老板丹尼尔","湖畔镇旅店老板","谁发布了干涸的时光"}},{q="为什么丹尼尔需要从这么多不同的地区获取酒水？",a="丹尼尔服务的对象包括难民、当地民兵以及过往的冒险者，这需要种类繁多的存货，从矮人拉格啤酒到王都的高档葡萄酒，再到来自暮色森林和艾尔文森林的烈性地方特产。",al={"为什么需要这么多酒","为什么要访问暮色森林和西部荒野"}},{q="完成这趟跑腿任务，酒吧老板丹尼尔会给予什么奖励？",a="除了用一袋钱币报销你的差旅费外，丹尼尔还会赠送一件由他妻子亲手缝制的披风，以感谢你勇闯该地区混乱道路的义举。",al={"干涸的时光任务奖励","丹尼尔给什么奖励"}}},fp="9,161,18.279.0,27.245.0,40.186.0,53.190.0,29.148.0,23.148.0,60.157.0,57.135.0"}
P.entries["quest:1166"] = {n="莫格穆洛克的任务",s="石槌氏族的莫格穆洛克大王现身处蕨墙村，他想要回自己的烈酒、鼻烟和保险箱。他当初离开氏族旧址时走得太匆忙，把这些东西落在了那里，因此他差遣你去南方将它们找回来。",h="石槌氏族的莫格穆洛克大王现身处蕨墙村，他想要回自己的烈酒、鼻烟和保险箱。他当初离开氏族旧址时走得太匆忙，把这些东西落在了那里，因此他差遣你去南方将它们找回来。",kw={"蕨墙村","火焰洞穴","尘泥沼泽","烈酒","莫格穆洛克","雷克萨","鼻烟","石槌","保险箱"},sec={{t="大王的故事",b="莫格穆洛克声称是雷克萨让他成为了石槌氏族伟大的领袖，他还说自己在保护族人。据他所言，巨龙曾袭击过旧址并带来了烈火，因此他在尘泥沼泽为氏族找到了新的家园。"},{t="遗落之物",b="他离开旧址时太过仓促，以至于遗忘了自己的财物：烈酒、鼻烟和保险箱。他指引你去南方的火焰洞穴和石槌废墟，并确信东西就在那里。他说自己忙于领导食人魔，无法亲自前往。"}},faq={{q="莫格穆洛克大王是谁？",a="莫格穆洛克大王在蕨墙村领导着石槌氏族。据他自己所说，是雷克萨让他成为了氏族伟大的领袖。",al={"莫格穆洛克","食人魔领袖","大王是谁"}},{q="石槌氏族的旧址发生了什么？",a="莫格穆洛克说巨龙袭击了旧址并带来了烈火，所以他在蕨墙村为氏族找到了新的家园。",al={"食人魔为何离开","石槌氏族被毁","巨龙袭击食人魔"}},{q="莫格穆洛克想要回什么？",a="他想要回自己的烈酒、鼻烟和保险箱，这些都是他在匆忙离开旧址时落下的。",al={"莫格穆洛克的物品","他想要什么东西","烈酒、鼻烟、保险箱"}},{q="莫格穆洛克的财物在哪里？",a="他派你去南方，并确信这些财物就在火焰洞穴和石槌废墟中。",al={"物品在哪里","物品位置","寻找烈酒和鼻烟"}},{q="为什么莫格穆洛克不亲自去取回他的东西？",a="他说自己忙于领导食人魔，没空去取。",al={"为什么莫格穆洛克不去","为何派我去"}}},fp="29,205,20.226.0,18.248.0,27.132.0,47.122.0,31.101.0,34.94.0,48.60.0"}
P.entries["quest:1167"] = {n="奥萨拉克斯之塔",s="这个任务标志着在前往奥萨拉克斯之塔面对阿斯瑞克斯·纳拉辛之前的紧张时刻。净化者德尔格伦派遣冒险者向北进发，与侦察兵巴苏尔·影击重新汇合，以收集关于那座尖塔中发生的离奇黑暗事件的情报。",h="这个任务标志着在前往奥萨拉克斯之塔面对阿斯瑞克斯·纳拉辛之前的紧张时刻。净化者德尔格伦派遣冒险者向北进发，与侦察兵巴苏尔·影击重新汇合，以收集关于那座尖塔中发生的离奇黑暗事件的情报。",kw={"奥萨拉克斯","阿斯瑞克斯","巴苏尔","邪教徒","黑海岸","德尔格伦","塔"},ang={["class:Paladin"]="德尔格伦深思熟虑的方案展现了圣光勇士应有的纪律性，即在冲进邪恶圣所前，先获取关键情报。",["faction:Alliance"]="德尔格伦与巴苏尔之间的协调，代表了人类圣骑士与暗夜精灵侦察兵之间为保卫卡利姆多北部安全而建立的务实战时伙伴关系。",["race:NightElf"]="巴苏尔·影击保卫着祖先的土地，抵御那些重蹈一万年前毁灭了暗夜精灵文明的鲁莽奥术覆辙的法术。"},sec={{t="侦察兵的报告",b="在净化了被腐蚀的圣物并瓦解了邪教在黑海岸边缘的势力后，净化者德尔格伦再次将你派遣到北方，去咨询他的哨兵同伴巴苏尔·影击。在直接突袭术士阿斯瑞克斯之前，德尔格伦认为有必要进行最新的战场侦察，并信任巴苏尔在俯瞰高塔的废墟中进行的不懈监视。"},{t="尖塔中的骚动",b="在到达巴苏尔的哨位后，这位侦察兵描述了上层圣所内令人不安的升级局势。耀眼的光芒突然闪现，痛苦的尖叫声划破了迷雾，不规则的闪电开始疯狂地肆虐这座古老的暗夜精灵之塔，预示着阿斯瑞克斯的黑暗行径正走向一个不稳定且危险的顶点。"}},faq={{q="为什么德尔格伦要让我去找巴苏尔？",a="德尔格伦知道盲目冲进阿斯瑞克斯的巢穴是鲁莽的行为。巴苏尔一直在持续监视奥萨拉克斯之塔，他是唯一了解阿斯瑞克斯及其邪教徒最近举动的人。",al={"为什么要见巴苏尔","与巴苏尔交谈","德尔格伦的命令"}},{q="巴苏尔·影击在哪里？",a="巴苏尔在奥萨拉克斯之塔以西的山丘上设有一个观察营地，监视着黑海岸北部的废墟。",al={"巴苏尔的位置","找到巴苏尔","巴苏尔在哪里"}},{q="巴苏尔在塔里目击到了什么近期事件？",a="巴苏尔目击到从塔的最顶层房间喷涌出一道刺眼的光芒，随后是传遍海岸的凄厉尖叫声，以及劈向地面的不规则闪电。",al={"塔里发生了什么","巴苏尔的尖叫","塔中闪光"}},{q="阿斯瑞克斯是谁？",a="阿斯瑞克斯·纳拉辛是领导奥萨拉克斯之塔邪教徒的黑暗术士，德尔格伦和巴苏尔决心阻止他那邪恶的仪式。",al={"阿斯瑞克斯是谁","阿斯瑞克斯·纳拉辛","塔中首领"}},{q="净化者德尔格伦是当地的暗夜精灵吗？",a="不，德尔格伦是一位人类圣骑士，也是驻扎在黑海岸与灰谷交界处的圣光勇士，他与暗夜精灵侦察兵结盟以清除恶魔的腐化。",al={"德尔格伦是谁","德尔格伦的种族","德尔格伦是精灵吗"}},{q="奥萨拉克斯之塔是什么样的废墟？",a="它是一座位于黑海岸崎岖北崖上的上层精灵或古老的暗夜精灵尖塔，在堕落的奥术师和恶魔邪教徒占据它进行禁忌仪式之前，这里早已被废弃。",al={"奥萨拉克斯之塔背景","这座塔是什么","塔的传说"}}},fp="22,178,16.333.0,25.258.1,42.177.0,39.143.0,53.165.0,16.148.0,42.178.0,44.188.0"}
P.entries["quest:1168"] = {n="黑龙军团",s="在蕨墙村，食人魔萨尔格想要向黑龙军团复仇。萨尔格对莫格穆洛克大王心怀不满，因为后者命令食人魔逃跑而非战斗，他请求你去打击火鬃龙人。",h="在蕨墙村，食人魔萨尔格想要向黑龙军团复仇。萨尔格对莫格穆洛克大王心怀不满，因为后者命令食人魔逃跑而非战斗，他请求你去打击火鬃龙人。",kw={"蕨墙村","尘泥沼泽","火鬃","莫格穆洛克","雷克萨","石槌","萨尔格"},sec={{t="血之怨恨",b="黑龙杀死了许多食人魔，萨尔格的妻子也死于其中。雷克萨任命莫格穆洛克为大王，他却让幸存者们逃跑，他们这才来到了蕨墙村。萨尔格说食人魔不擅长逃跑，应该去战斗；他认为莫格穆洛克只关心他自己。萨尔格还说，莫格穆洛克命令所有食人魔待在原地，以保卫这个地方的安全。"},{t="南方的家园",b="萨尔格把石槌废墟称为家，他喜欢南方的生活。蕨墙村对他来说并不是家。他想要向黑龙军团复仇并夺回旧家园，所以他请求你去消灭其中的火鬃斥候和火鬃灰尾。"}},faq={{q="谁是萨尔格？",a="萨尔格是居住在蕨墙村的一名食人魔。他的妻子被黑龙杀害了，他想要复仇并回到石槌废墟。",al={"萨尔格背景故事","谁是萨尔格","萨尔格 尘泥沼泽"}},{q="为什么萨尔格不喜欢莫格穆洛克大王？",a="雷克萨任命莫格穆洛克为大王，但萨尔格说他更关心权力，而不是食人魔的安危。当黑龙屠杀食人魔时，莫格穆洛克命令其他人逃跑，而萨尔格认为食人魔应该战斗。",al={"萨尔格为什么讨厌莫格穆洛克","莫格穆洛克 懦夫","萨尔格与莫格穆洛克"}},{q="萨尔格的妻子发生了什么事？",a="她被黑龙杀害了，一同遇难的还有许多其他食人魔。这就是萨尔格复仇之心的根源。",al={"萨尔格的妻子","萨尔格的妻子遭遇了什么","萨尔格的妻子之死"}},{q="食人魔的旧家园在哪里？",a="萨尔格把石槌废墟称为家，他喜欢南方的生活。他说蕨墙村并不是家，他想要回到那里。",al={"石槌食人魔的家园","食人魔来自哪里","石槌废墟历史"}},{q="哪些敌人组成了黑龙军团？",a="萨尔格指出了火鬃龙人，其中包括火鬃斥候和火鬃灰尾。",al={"火鬃龙人","如何对付黑龙军团","火鬃龙人敌人"}}},fp="24,209,20.382.0,17.261.0,13.143.0,43.199.0,30.98.0,29.129.0,51.84.0"}
P.entries["quest:1169"] = {n="群龙之首",s="在蕨墙村，德拉兹辛比称莫克莫洛克是一个沉溺于权力的懦弱蠢货，并说萨尔格正陷于悲伤和复仇的挣扎中，同时还在争夺部落的领导权。德拉兹辛比认为没有其他人关心是谁袭击了他们的旧家园，并要求你收集十五个炽热之舌和十五个炽热之心。",h="在蕨墙村，德拉兹辛比称莫克莫洛克是一个沉溺于权力的懦弱蠢货，并说萨尔格正陷于悲伤和复仇的挣扎中，同时还在争夺部落的领导权。德拉兹辛比认为没有其他人关心是谁袭击了他们的旧家园，并要求你收集十五个炽热之舌和十五个炽热之心。",kw={"黑龙","蕨墙村","德拉兹辛比","尘泥沼泽","莫克莫洛克","炽热之心","炽热之舌","石槌","萨尔格"},sec={{t="理性的声音",b="德拉兹辛比说莫克莫洛克沉溺于权力，而萨尔格则在悲伤和复仇的渴望中挣扎，所以依德拉兹辛比看来，没人在意是谁在背后主使了针对旧家园的侵略。德拉兹辛比指出，你可能原本以为食人魔只会像野兽一样说话。"},{t="心脏与舌头",b="德拉兹辛比需要从幼龙和雏龙身上获取舌头和心脏，每样十五个，以追踪这种邪恶的来源。通过黑龙军团被烧焦的幼崽，德拉兹辛比希望能找出到底是哪只可恶的野兽将她的后代放进了食人魔的家园。更了解敌人的话，食人魔或许就能彻底消灭它们，并让石槌村从废墟中恢复。德拉兹辛比补充说，让莫克莫洛克离开这片沼泽本身就是一项巨大的工程。"}},faq={{q="谁是德拉兹辛比？",a="德拉兹辛比是蕨墙村的一名食人魔，他的谈吐文质彬彬，而非像野兽一般，他想找出到底是谁在背后策划了针对部落旧家园的袭击。",al={"德拉兹辛比","蕨墙村食人魔术士","聪明的食人魔"}},{q="德拉兹辛比想从幼龙和雏龙那里得到什么？",a="德拉兹辛比需要十五个炽热之舌和十五个炽热之心。它们将被用于追踪是哪只野兽把她的后代放进了旧家园。",al={"炽热之心的用途","为什么要收集舌头和心脏","识别龙群的目的"}},{q="德拉兹辛比如何看待部落的领袖们？",a="德拉兹辛比对莫克莫洛克并无多少敬意，称那个食人魔是一个沉溺于权力的懦弱蠢货，并说萨尔格是一个深陷悲伤与复仇渴望的人。",al={"莫克莫洛克的问题","萨尔格与莫克莫洛克","石槌氏族领袖"}}},fp="21,323,17.284.0,18.461.0,17.171.0,56.145.0,48.186.0"}
P.entries["quest:117"] = {n="雷霆啤酒",s="雷酒酿造是一项直接的任务，由漫游在西部荒野的矮人葛瑞姆·雷酒发起。为了不让他新酿的酒喝起来像炖菜而不是浓郁的矮人拉格啤酒，葛瑞姆需要从周围的乡村采集新鲜啤酒花。帮助他的冒险者将获得一桶新鲜、泡沫丰富的烈性招牌佳酿。",h="雷酒酿造是一项直接的任务，由漫游在西部荒野的矮人葛瑞姆·雷酒发起。为了不让他新酿的酒喝起来像炖菜而不是浓郁的矮人拉格啤酒，葛瑞姆需要从周围的乡村采集新鲜啤酒花。帮助他的冒险者将获得一桶新鲜、泡沫丰富的烈性招牌佳酿。",kw={"啤酒","酿造","矮人","葛瑞姆","啤酒花","酒桶","拉格啤酒","雷酒","西部荒野"},ang={["profession:Cooking"]="对于任何欣赏烹饪艺术和经典矮人发酵工艺的人来说，理解大麦、麦芽和啤酒花之间的平衡是第二天性。",["race:Dwarf"]="在西部荒野的崎岖前线看到一位族人依然坚守着卡拉诺斯的自豪传统，总是一件令人欣慰的事，尤其是当还有酒桶的时候。"},sec={{t="西部荒野里的矮人热情",b="即使是在动荡不安的西部荒野，矮人的酿造技艺依然存在——尤其是在酿酒这方面。葛瑞姆·雷酒是赫赫有名的雷酒酿造氏族的一员，即使远离丹莫罗冰冷的厅堂，他依然延续着家族传统。酿造优质的黑啤和拉格啤酒需要精确的原料，葛瑞姆坚持认为如果没有合适的啤酒花，他现在的这锅东西就有可能变成浓稠的炖菜，而不是清爽的麦芽酒。"},{t="酒桶的艺术",b="葛瑞姆总是带着富有节奏韵律的热情进行工作，赞美着啤酒花、大麦、酵母和麦芽这些基础原料。当冒险者为他提供新鲜的啤酒花时，他会当场完成发酵过程。为他提供补给的冒险者将会获得一整桶雷酒拉格，这种酒以对味蕾的强烈冲击而闻名。"}},faq={{q="葛瑞姆·雷酒是谁？",a="葛瑞姆·雷酒是一位漫游在西部荒野各地的矮人酿酒师。他忠于他著名氏族的传承，无论在何处扎营都热衷于调配烈性拉格啤酒，而且经常用欢快的韵律说话和吟唱。",al={"葛瑞姆","葛瑞姆是谁","葛瑞姆背景故事"}},{q="为什么葛瑞姆需要啤酒花？",a="如果没有新鲜的啤酒花，葛瑞姆最新的一批酒可能会像炖菜一样浓稠厚重，而不是清爽烈性的拉格啤酒。啤酒花提供了矮人酿酒所必需的苦味和风味平衡。",al={"为什么需要啤酒花","葛瑞姆的啤酒花","啤酒花的作用"}},{q="什么是雷酒拉格？",a="雷酒拉格是由雷酒家族酿造的一种厚重、著名的矮人饮料。葛瑞姆以桶为单位进行分发，保证这种烈酒能带来极具冲击力的味觉体验。",al={"雷酒啤酒","雷酒酒桶","什么是雷酒"}},{q="你能多次给葛瑞姆带来啤酒花吗？",a="是的。葛瑞姆对酿酒的渴望永不满足，他很乐意接受后续的啤酒花补给，并以此换取更多桶他的特制啤酒。",al={"可重复任务","雷酒任务可以重复吗","更多酒桶"}},{q="这项任务在哪里进行？",a="这项任务完全是在西部荒野进行的，葛瑞姆就在那里的农田间扎营并收集补给。",al={"雷酒位置","葛瑞姆在哪里","任务区域"}},{q="葛瑞姆和丹莫罗的雷酒家族有关系吗？",a="是的，葛瑞姆与丹莫罗卡拉诺斯著名的雷酒酿造家族同姓且同行，将他们对发酵的热情带到了更广阔的王国之中。",al={"雷酒酿制厂","葛瑞姆氏族","雷酒家族"}}},fp="11,173,29.253.0,18.228.0,29.165.0,29.151.0,26.150.0,44.83.0,32.97.0,55.106.0"}
P.entries["quest:1170"] = {n="奥妮克希亚的血脉",s="德拉兹辛比讲述了奥妮克希亚的龙族入侵石槌村的事情，并疑惑Deathwing的女儿为何会来到这片土地。你被派往蕨墙村，将消息告知莫格穆洛克大王。",h="德拉兹辛比讲述了奥妮克希亚的龙族入侵石槌村的事情，并疑惑Deathwing的女儿为何会来到这片土地。你被派往蕨墙村，将消息告知莫格穆洛克大王。",kw={"蕨墙村","deathwing","德拉兹辛比","尘泥沼泽","莫格穆洛克","奥妮克希亚","石槌"},sec={{t="令人不安的迹象",b="石槌村遭到了奥妮克希亚龙族的入侵，德拉兹辛比觉得Deathwing的女儿会降临这片土地实在令人不安。德拉兹辛比确信奥妮克希亚此行绝不仅仅是为了围攻几个食人魔，他希望能立刻将此事告知蕨墙村的莫格穆洛克大王，以便采取行动。"},{t="蕨墙村的消息",b="莫格穆洛克并不欢迎这个消息。这位大王讨厌龙，他喜欢蕨墙村，并声称这里根本没有龙。"}},faq={{q="是谁派你去和莫格穆洛克大王谈话的？",a="是德拉兹辛比派你去的，此前奥妮克希亚的龙族入侵了石槌村。",al={"谁开启了奥妮克希亚的龙族任务","奥妮克希亚的龙族任务发布者"}},{q="在什么地方可以找到莫格穆洛克大王？",a="你可以在蕨墙村找到莫格穆洛克大王。",al={"莫格穆洛克位置","莫格穆洛克在哪里","莫格穆洛克大王 尘泥沼泽"}},{q="为什么德拉兹辛比会对奥妮克希亚的龙族感到担忧？",a="德拉兹辛比疑惑为何Deathwing的女儿会来到这片土地，并确信她此行不仅仅是为了围攻一小群食人魔。",al={"为什么德拉兹辛比在意龙类","德拉兹辛比 奥妮克希亚的担忧"}}},fp="19,204,20.308.0,19.136.1,48.77.0,39.57.0,48.142.0"}
P.entries["quest:1171"] = {n="奥妮克希亚的血脉",s="莫格穆洛克大王不想听关于巨龙的事。他说这里没有黑龙，并让你带着食人魔会留下的消息回到蕨墙村的德拉兹辛比那里。",h="莫格穆洛克大王不想听关于巨龙的事。他说这里没有黑龙，并让你带着食人魔会留下的消息回到蕨墙村的德拉兹辛比那里。",kw={"蕨墙村","奥妮克希亚的巢群","德拉兹辛比","尘泥沼泽","莫格穆洛克","雷克萨"},sec={{t="离我远点",b="在德拉兹辛比传达了关于奥妮克希亚的巢群的消息后，莫格穆洛克大王只希望能清静一下。莫格穆洛克说食人魔会待在原地，这里没有黑龙，并让你去告诉蕨墙村的德拉兹辛比。"},{t="德拉兹辛比怎么说",b="德拉兹辛比对这个回答很不满，称这位大王是个懒惰的懦夫。德拉兹辛比说，当雷克萨还是他们的领袖时，莫格穆洛克展现出了力量，但在雷克萨离开后，权力的诱惑占据了上风。莫格穆洛克现在要求食人魔服侍他，而不是领导他们，德拉兹辛比认为必须采取行动。"}},faq={{q="为什么莫格穆洛克大王拒绝采取行动？",a="莫格穆洛克说这里没有黑龙，并希望不要被打扰。你被告知要将食人魔留下的消息带给德拉兹辛比。",al={"为什么莫格穆洛克不帮忙","莫格穆洛克的反应","为什么没有黑龙"}},{q="在此任务之前的故事线是什么？",a="这紧接在“奥妮克希亚的巢群”之后，在那项任务中，德拉兹辛比派你去向莫格穆洛克传达有关巢群的消息。",al={"此任务前置","任务链顺序"}},{q="这发生在哪里？",a="莫格穆洛克和德拉兹辛比都在蕨墙村。",al={"此任务在哪里","地点"}}},fp="19,191,14.249.0,19.322.1,43.136.0,40.103.0,27.57.0"}
P.entries["quest:1172"] = {n="奥妮克希亚的血脉",s="蕨墙村的德拉兹辛比不希望再有一只奥妮克希亚的幼龙孵化出来。你被派去寻找并摧毁巨龙沼泽附近，沼泽南部的黑龙蛋。",h="蕨墙村的德拉兹辛比不希望再有一只奥妮克希亚的幼龙孵化出来。你被派去寻找并摧毁巨龙沼泽附近，沼泽南部的黑龙蛋。",kw={"蕨墙村","奥妮克希亚的后代","黑龙谷","德拉兹辛比","莫克莫罗克","奥妮克希亚","石槌","巨龙沼泽"},sec={{t="巨龙沼泽中的龙蛋",b="奥妮克希亚的后代已经分散在黑龙谷各处。德拉兹辛比催促你赶快行动：巨龙沼泽位于沼泽南部，德拉兹辛比确信那条巨龙在那里筑了巢，周围布满了龙蛋。只要石槌村周围的土地还是巨龙的巢穴，食人魔就永远无法收复那里，所以你被派去追踪并摧毁这些龙蛋。"},{t="最后一次效劳",b="随着龙蛋被摧毁，德拉兹辛比说奥妮克希亚还需要一段时间才能产下更多的蛋，并代表石槌氏族向你表示感谢。接着德拉兹辛比请求你再帮最后一个忙。德拉兹辛比认为莫克莫罗克不适合担任首领，而萨尔格虽然是个出色的首领人选，却受年龄和伤病所困。你被要求武力驱逐莫克莫罗克，这样新的首领才能带领氏族回到南方的家园。"}},faq={{q="谁发布了这个任务？",a="蕨墙村的德拉兹辛比派你去对付奥妮克希亚的龙蛋。",al={"奥妮克希亚的后代发布者","奥妮克希亚的后代任务发布者","德拉兹辛比任务"}},{q="为什么要摧毁龙蛋？",a="德拉兹辛比不希望再有奥妮克希亚的幼龙孵化出来。只要石槌村周围的土地还是巨龙的巢穴，食人魔就永远无法收复那里。",al={"为什么要摧毁奥妮克希亚的龙蛋","为什么要击碎龙蛋","石槌村的龙蛋"}},{q="龙蛋在哪里？",a="在巨龙沼泽附近，也就是沼泽的南部。德拉兹辛比确信奥妮克希亚在那里筑了巢。",al={"奥妮克希亚的龙蛋在哪里","奥妮克希亚之卵的位置","巨龙沼泽在哪里"}},{q="这一步在整个任务链中处于什么位置？",a="它发生在莫克莫罗克拒绝针对龙群的消息采取行动，而你将他的回答带回给德拉兹辛比之后。",al={"奥妮克希亚的后代任务链","奥妮克希亚的后代前置任务","奥妮克希亚的后代3的前置任务"}}},fp="19,188,23.384.0,16.428.1,21.71.0,38.159.0,27.96.0,46.113.0"}
P.entries["quest:1173"] = {n="挑战莫格穆洛克",s="莫格穆洛克大王对你的挑战嗤之以鼻，发誓要碾碎你，并让你随时准备好接受他的痛殴。蕨墙村的德拉兹辛比曾希望看到莫格穆洛克被赶出村子。",h="莫格穆洛克大王对你的挑战嗤之以鼻，发誓要碾碎你，并让你随时准备好接受他的痛殴。蕨墙村的德拉兹辛比曾希望看到莫格穆洛克被赶出村子。",kw={"蕨墙村","挑战莫格穆洛克大王","德拉兹辛比","尘泥沼泽","莫格穆洛克","石槌"},sec={{t="向大王挑战",b="你走向莫格穆洛克大王，他嘲笑你的胆量，发誓要碾碎你，并告诉你准备好挨揍时尽管开口。此任务承接自“奥妮克希亚的巢穴”。蕨墙村的德拉兹辛比期待看到莫格穆洛克被逐出村庄，并对你为何回来仅仅是想谈话感到不解。"},{t="给德拉兹辛比的消息",b="战斗胜利后，德拉兹辛比说莫格穆洛克像个懦夫一样逃跑了，并感谢你做出的巨大贡献。随着莫格穆洛克的离去，食人魔们可以选出一位新领袖，带领他们彻底夺回旧家园。"}},faq={{q="你要挑战谁？",a="你在蕨墙村向莫格穆洛克大王发起了挑战。大王回应以一阵嘲笑，并吹嘘要碾碎你。",al={"我该和谁战斗","挑战目标","莫格穆洛克是谁"}},{q="这个挑战之前有什么任务？",a="它承接自“奥妮克希亚的巢穴”。",al={"此任务前置是什么","前置任务","上一个任务"}},{q="战斗结束后你向谁汇报？",a="你应该向蕨墙村的德拉兹辛比汇报。",al={"我该向谁交任务","交任务npc","打败莫格穆洛克后去哪"}},{q="德拉兹辛比对你有什么期望？",a="德拉兹辛比期待看到莫格穆洛克被逐出村庄，并对你为何回来仅仅是想谈话感到不解。",al={"为什么要打莫格穆洛克","为什么要挑战大王","战斗原因"}}},fp="29,213,27.314.0,18.219.1,21.120.0,33.31.0,37.57.0,34.110.0"}
P.entries["quest:1174"] = {n="Gnomes Win!",s="在千针石林，当侏儒获得胜利时，侏儒优惠券就会产生价值。持有获胜存根的人可以获得一个奖品盒。",h="在千针石林，当侏儒获得胜利时，侏儒优惠券就会产生价值。持有获胜存根的人可以获得一个奖品盒。",kw={"侏儒优惠券","侏儒奖品盒","侏儒获胜","比赛","千针石林"},sec={{t="侏儒优惠券",b="当侏儒获胜时，侏儒优惠券就是有效的存根。拿好它，一旦结果揭晓，侏儒奖品盒就是你的了。地精优惠券则有其对应的结果，那是比赛的另一方。"}},faq={{q="什么是侏儒优惠券？",a="它是千针石林比赛中侏儒一方的票据。当侏儒获胜时，它就有了用处。",al={"侏儒优惠券","什么是侏儒优惠券","优惠券用途"}},{q="侏儒获胜时会得到什么？",a="当侏儒获得胜利时，任何持有侏儒优惠券的人都会获得一个侏儒奖品盒。",al={"侏儒奖品盒","侏儒获胜奖励"}},{q="谁可以参与这个赌注？",a="它不属于任何阵营，所以联盟和部落的旅行者处于平等的地位。",al={"部落可以下注吗","联盟可以下注吗","中立优惠券"}},{q="如果地精获胜了会怎样？",a="那么地精优惠券就是有效的了。它的结果被称为“地精赢了！”，与这一项相对。",al={"地精获胜","地精优惠券"}}},fp="11,138,16.210.0,30.100.0,36.94.0,32.87.0,40.111.0"}
P.entries["quest:1175"] = {n="安全隐患",s="赛道管理员泽尔林负责照看沙漠赛道的赛道，而闪光平原上的野兽已经长得太大了，必须在它们游荡到赛道上之前控制它们的数量。你被要求清理盐石蜥蜴、水晶壳蜥蜴和凝视者。",h="赛道管理员泽尔林负责照看沙漠赛道的赛道，而闪光平原上的野兽已经长得太大了，必须在它们游荡到赛道上之前控制它们的数量。你被要求清理盐石蜥蜴、水晶壳蜥蜴和凝视者。",kw={"水晶壳蜥蜴","凝视者","沙漠赛道","红雷号","盐石蜥蜴","闪光平原","塔霍达废墟","赛道管理员泽尔林","维吉尔之坑"},sec={{t="保持赛道畅通",b="曾经有一只蜥蜴撞上了地精的赛车“红雷号”，事后克隆克雷德雇佣了泽尔林来负责看管赛道。泽尔林说不清闪光平原上的动物吃了什么变得这么大，只知道必须控制它们的数量，否则在比赛中会有一只跑到赛道上。清理残骸已经够麻烦的了，泽尔林可不想还得从烧焦的动物残骸里把它挑出来。"}},faq={{q="赛道管理员泽尔林是谁？",a="闪光平原上沙漠赛道的赛道管理员，受克隆克雷德雇佣来负责照看赛道。",al={"泽尔林是谁","赛道管理员泽尔林","泽尔林背景故事"}},{q="为什么要猎杀这些蜥蜴？",a="平原上的野兽长得太大了，如果有一只在比赛时跑到赛道上可能会导致撞车，就像之前那只蜥蜴撞上地精的“红雷号”那样。",al={"为什么要杀蜥蜴","为什么必须杀死蜥蜴","蜥蜴问题"}},{q="什么是“红雷号”？",a="地精的一辆赛车，在与一只蜥蜴的碰撞中报废了。",al={"红雷号","红雷号撞车","地精红雷号"}},{q="蜥蜴通常在平原的什么地方出没？",a="它们在整个闪光平原上游荡，但在维吉尔之坑附近和塔霍达废墟中更为密集。",al={"蜥蜴位置","蜥蜴在哪里","哪里可以找到盐石蜥蜴"}}},fp="18,266,23.435.0,26.109.0,35.167.0,24.73.0,51.114.0"}
P.entries["quest:1176"] = {n="减轻负重",s="驻扎在沙漠赛道的首席地精工程师普兹克需要一些材料，来为他的火箭赛车底盘减掉哪怕一点点重量。地精们不打算单纯依赖沉重的金属板，而是从当地的沙漠秃鹫身上回收空心骨骼，用来制造坚固且极轻的转向和结构装置。",h="驻扎在沙漠赛道的首席地精工程师普兹克需要一些材料，来为他的火箭赛车底盘减掉哪怕一点点重量。地精们不打算单纯依赖沉重的金属板，而是从当地的沙漠秃鹫身上回收空心骨骼，用来制造坚固且极轻的转向和结构装置。",kw={"骨头","减轻负荷","沙漠赛道","普兹克","火箭赛车","闪光平原","千针石林","秃鹫"},ang={["profession:Engineering"]="普兹克对禽类骨架的依赖展示了典型的地精智慧：实用、即兴，且在减轻整备质量方面出奇地有效。",["race:Gnome"]="看着地精把拾来的鸟类尸体硬生生捆绑进机械转向装置里，肯定会让任何受过正统训练的Tinker Town工程师感到震惊。"},sec={{t="点滴必争",b="在闪光平原那白得刺眼的广袤大地上，地精工程师与侏儒工程师之间的竞争往往是以零点几秒来决胜负的。如果赛车因过重而变得笨拙，那么再强劲的引擎推力也无济于事。当侏儒团队沉迷于复杂的齿轮和黄铜配件时，普兹克领导的地精团队追求的是无情的务实效率：拆掉厚重的铁质框架，并在车架允许的地方换上更轻、中空的结构组件。"},{t="为了速度而搜寻沙漠",b="普兹克没有将昂贵的特制复合材料运往千针石林，而是把目光投向了周围的盐碱荒地。闪光平原上的秃鹫随处可见，它们为了飞行而进化出的骨骼拥有中空的蜂窝状核心，在几乎没有重量的同时提供了极强的抗拉强度。通过将加工过的秃鹫骨头用作赛车的转向装置和小型支架，普兹克的机械师们旨在让他们的机器保持足够的灵活性，以便在全速行驶时不至于散架，从而超越侏儒。"}},faq={{q="普兹克为什么要用秃鹫的骨头来造赛车？",a="地精工程学推崇巧妙的构思和就地取材。秃鹫的骨头是中空的，天生轻盈，能以理想的强度重量比来加固像转向装置这样的精密部件，同时又不会增加赛车的重量。",al={"秃鹫骨头的用途","为什么要用骨头","普兹克 骨头"}},{q="普兹克是谁？",a="普兹克是驻扎在闪光平原沙漠赛道的首席地精赛车技师兼团队领袖。他指挥着地精维修站，对抗他们的死对头——侏儒。",al={"普兹克","普兹克 背景故事","地精工程师是谁"}},{q="这些秃鹫在哪里可以找到？",a="拾荒者和秃鹫盘旋在闪光平原开阔的平地上，特别是在盐盆东北部散布的巨型残骸周围。",al={"秃鹫位置","去哪里找中空骨头","闪光平原的拾荒者"}},{q="什么是沙漠赛道？",a="沙漠赛道是建立在千针石林广阔干涸盐湖上的中立赛车场。地精和侏儒在那里进行高速、危险的实验性火箭赛车比赛。",al={"赛道背景故事","什么是沙漠赛道","闪光平原赛道"}},{q="侏儒也在做同样的事情吗？",a="虽然侏儒也在寻找精简赛车的方法，但他们的工程学传统倾向于精密发条装置和复杂的金属结构，而不是像地精那样基于回收利用的修补式改装。",al={"侏儒赛车手","侏儒对地精","侏儒也用骨头吗"}},{q="这项工作对普兹克更大的赛车计划有帮助吗？",a="是的。通过减轻赛车重量来证明你的可靠性可以赢得普兹克的信任，从而获得更多涉及赛道竞争和闪光平原官方地精赞助的任务。",al={"任务后续","what comes next","地精赞助"}}},fx={a8fc0189={q="普兹克为什么如此执着于减轻赛车的重量？",a="在沙漠赛道，速度决定一切，比赛往往只差微乎其微的优势。普兹克正与侏儒工程师直接较量，任何多余的重量都可能让他在盐滩上痛失胜利。尽可能减轻车架和转向装置的重量，可以让他的火箭赛车达到最大加速度，同时不牺牲结构强度。",al={"普兹克的动机","为什么要减轻赛车重量","普兹克为什么需要轻型零件"}},["8208273d"]={q="闪光平原为什么有这么多秃鹫？",a="闪光平原是一片严酷、被烈日炙烤的荒地，遍布巨型古兽和倒下的旅人留下的遗骸。以盐滩为生的食腐动物在这里繁衍，它们盘旋在空中，啄食恶劣沙漠气候以及平原上凶猛的石化蜥蜴和蝎子留下的腐肉。",al={"闪光平原为什么有秃鹫","盐滩秃鹫的背景","千针石林的秃鹫"}}},fp="15,297,18.473.0,27.492.0,50.239.0,14.182.0,31.185.0,27.198.0,36.206.0,55.175.0"}
P.entries["quest:1177"] = {n="饿！",s="马德克拉什是一位住在尘泥沼泽北部的食人魔，他饿了。马德克拉什要你去教训那些鱼人泥鳍部族，并带回他们的头颅，否则马德克拉什就会把你当点心。",h="马德克拉什是一位住在尘泥沼泽北部的食人魔，他饿了。马德克拉什要你去教训那些鱼人泥鳍部族，并带回他们的头颅，否则马德克拉什就会把你当点心。",kw={"尘泥沼泽","鱼人","饥饿！","泥鳍部族的头颅","马德克拉什","食人魔"},sec={{t="饥饿的食人魔",b="马德克拉什是一个大块头食人魔，他毫不掩饰自己的想法。马德克拉什饿了，他提出了一个简单的交易：去教训那些鱼人泥鳍部族，把他们的头颅作为食物带给马德克拉什。喂饱马德克拉什，否则他就会吃了你。"}},faq={{q="马德克拉什是谁？",a="马德克拉什是住在尘泥沼泽北部的一名大块头食人魔，自称马德。他饿了，想要食物。",al={"马德克拉什","马德克拉什是谁","尘泥沼泽的食人魔"}},{q="马德克拉什想吃什么？",a="马德想要泥鳍部族的头颅，这些头颅来自你要去教训的那些鱼人泥鳍部族。",al={"马德克拉什的食物","食人魔想要什么","饥饿任务食物"}},{q="如果拒绝喂食，会发生什么？",a="马德说得很清楚：喂饱马德，否则马德就会吃了你。",al={"马德克拉什的威胁","马德克拉什会吃掉我吗"}}},fp="7,167,13.184.0,25.107.0,40.82.0,39.49.0"}
P.entries["quest:1178"] = {n="地精赞助商",s="地精赛车队的普兹克正在等待几周前加兹鲁维承诺送来的原型燃油调节器，但东西一直没到。加兹鲁维通常都很准时，所以普兹克让你去棘齿城问问发生了什么事，因为侏儒们正在追赶车队。",h="地精赛车队的普兹克正在等待几周前加兹鲁维承诺送来的原型燃油调节器，但东西一直没到。加兹鲁维通常都很准时，所以普兹克让你去棘齿城问问发生了什么事，因为侏儒们正在追赶车队。",kw={"燃油调节器","加兹鲁维","沙漠赛道","普兹克","棘齿城","闪光平原","技师工会","安德麦"},sec={{t="承诺的部件",b="普兹克称赛车队是地精的骄傲，并说许多人都以各种方式帮助过车队。加兹鲁维为车队搜寻世界各地的零件，甚至有一次亲自来维修过他们的赛车。几周前加兹鲁维说会寄来一个新的原型燃油调节器，但至今杳无音信，这不像他的作风。随着侏儒们的追赶，普兹克让你去棘齿城问问加兹鲁维情况。"},{t="关于普兹克的话",b="当加兹鲁维听说普兹克派你来时，他评论说普兹克在退休去研究赛车手之前，曾是安德麦最受尊敬的技师之一。普兹克加入车队后的第一项举措就是设计了双引擎模型赛车。加兹鲁维承认如果没有普兹克与技师工会的合作，生意可能会受损，但他表示没有什么比比赛更重要的了。"}},faq={{q="为什么普兹克需要你去棘齿城？",a="加兹鲁维几周前说他会寄来一个原型燃油调节器，但一直没到。普兹克让你去棘齿城问问他。",al={"为什么去棘齿城","普兹克的差事","地精赞助任务目标"}},{q="加兹鲁维为赛车队做了什么？",a="他为车队搜寻世界各地的零件，甚至有一次亲自来维修过他们的赛车。",al={"加兹鲁维的参与","加兹鲁维赛道赞助商","加兹鲁维是赞助商吗"}},{q="这个任务的前置任务是什么？",a="它紧接在“减负”之后，也是由普兹克提供的。",al={"地精赞助前置任务","地精赞助之前的任务是什么"}},{q="为什么地精车队这么着急？",a="普兹克说侏儒们正在追赶他们。",al={"为什么要催促燃油调节器","地精与侏儒的比赛"}}},fp="18,266,15.419.0,18.361.1,42.143.0,41.106.0,23.49.0,34.43.0"}
P.entries["quest:1179"] = {n="防撞头盔",s="身处铁炉堡的飞行员比罗·长须需要一名信使将一箱加固过的攻城机头盔送过大海，运往卡利姆多。他的朋友——铜栓兄弟，正在闪光平原测试高速火箭车，他们那些经常出事故的试车手急需头部防护。",h="身处铁炉堡的飞行员比罗·长须需要一名信使将一箱加固过的攻城机头盔送过大海，运往卡利姆多。他的朋友——铜栓兄弟，正在闪光平原测试高速火箭车，他们那些经常出事故的试车手急需头部防护。",kw={"铜栓","铁炉堡","沙漠赛道","飞行员比罗·长须","火箭车","闪光平原","千针石林","维兹尔·铜栓"},ang={["profession:Engineering"]="这是一次典型的工程补给任务，连接了矮人重甲工艺与侏儒高速推进实验。",["race:Dwarf"]="只有坚固的矮人攻城机护甲才能厚实到足以在盐碱滩上发生的侏儒火箭全速碰撞中幸存下来。",["race:Gnome"]="铜栓兄弟对极致速度的追求展现了典型的侏儒野心，在这种野心中，机械创新被置于绝对优先地位，而刹车和驾驶员寿命等细枝末节则被忽略不计。"},sec={{t="远距离的援手",b="当矮人飞行员比罗·长须驻扎在铁炉堡的飞行机械旁时，收到了来自卡利姆多南部闪光平原的紧急请求。他的朋友，一对名为铜栓兄弟的侏儒发明家，在那片广袤的盐碱地上定居下来，以测试实验性机械。长须因军事和飞行任务脱不开身，无法亲自运送补给。"},{t="高速下的安全",b="铜栓兄弟的火箭车速度快得惊人，快到他们的试车手不断在盐碱地上翻车，并遭受严重的脑震荡。长须弄到了一箱重型矮人攻城机头盔来保护他们的颅骨。运送这箱头盔为这些侏儒提供了急需的筹码，能说服那些不情愿的飞行员重新坐回他们那不稳定的高速机器驾驶座上。"}},faq={{q="谁是飞行员比罗·长须？",a="飞行员比罗·长须是一位位于铁炉堡的矮人飞行员。作为铜栓兄弟的熟人，他充当了他们在东部王国的补给联系人，为他们采购在野外难以制造的重型矮人装备。",al={"飞行员比罗·长须","任务发布者","谁发布任务"}},{q="谁是铜栓兄弟？",a="铜栓兄弟，包括维兹尔·铜栓在内，都是雄心勃勃的侏儒工程师，他们在闪光平原的沙漠赛道建立了基地。他们终日致力于设计和调试尖端的火箭车，以在竞速中击败地精竞争对手。",al={"铜栓兄弟","维兹尔·铜栓","侏儒兄弟"}},{q="闪光平原在哪里？",a="闪光平原是一片位于卡利姆多南部、穿过千针石林高耸峡谷柱后的广阔盐碱平原。其平坦且无障碍的广袤地形，使其成为测试实验性高速载具的理想试验场。",al={"闪光平原位置","送往何处","赛道在哪里"}},{q="为什么侏儒需要攻城机头盔？",a="铜栓兄弟的火箭车能达到极高的速度，但其转向和稳定性却令人不敢恭维。驾驶员撞车和脑震荡的频率太高，以至于没有试飞员愿意在没有厚实矮人头部防护的情况下坐进驾驶座。",al={"为什么需要头盔","防撞头盔","火箭车撞车"}},{q="为什么长须不亲自运送？",a="飞行员比罗·长须受限于他在铁炉堡的军事义务和职责。因为跨越无尽之海前往卡利姆多南部的长途旅行意味着擅离职守，所以他只能依靠来往的冒险者来运送这箱沉重的货物。",al={"为什么不是长须","长须的职责"}},{q="部落玩家能完成这个任务吗？",a="不能。这个任务由联盟主城铁炉堡的飞行员比罗·长须发布，仅限联盟信使完成，尽管沙漠赛道本身欢迎两个阵营的玩家。",al={"这是联盟专属吗","部落版本","阵营"}}},fp="23,296,21.426.0,23.411.0,23.242.0,32.258.0,30.242.0,44.260.0,43.238.0,37.181.0"}
P.entries["quest:118"] = {n="马掌",s="湖畔镇的铁匠弗纳·奥斯古因为要为疲于奔命的城镇卫兵修补装备，已经耗尽了他的铁矿库存。由于没有金属来为当地的马匹钉马掌，他派出一名信使穿越艾尔文森林，向闪金镇的铁匠阿古斯求助。",h="湖畔镇的铁匠弗纳·奥斯古因为要为疲于奔命的城镇卫兵修补装备，已经耗尽了他的铁矿库存。由于没有金属来为当地的马匹钉马掌，他派出一名信使穿越艾尔文森林，向闪金镇的铁匠阿古斯求助。",kw={"艾尔文","闪金镇","马掌","铁矿","湖畔镇","赤脊山","铁匠阿古斯","弗纳·奥斯古"},ang={["faction:Alliance"]="湖畔镇对闪金镇的依赖，凸显了在暴风城摄政统治下，王国后勤补给是多么的匮乏。",["profession:Blacksmithing"]="这一请求突显了边境锻造业残酷的物质现实，工匠的锻造炉必须优先满足前线士兵的需求，而非普通的农舍。"},sec={{t="捉襟见肘的边境",b="湖畔镇正处于豺狼人、兽人和鱼人的枪口之下，然而暴风城提供的支援却少得可怜。当地驻军必须每日奋战才能守住城镇，而无休止的战斗让装备损耗极快。弗纳·奥斯古几乎每时每刻都在修理凹陷的胸甲、重铸变钝的刀剑，让镇上的卫兵始终有铁甲护身，这让他耗尽了所有的原材料。"},{t="通往艾尔文的补给线",b="当边境定居点完全用尽铁矿时，即使是普通的任务也会陷入停滞。如果没有马掌，信使就无法骑马快速传递消息，驮兽也无法拉着补给穿越赤脊山的崎岖山路。弗纳必须放下尊严向腹地求援，派遣旅行者沿着三角路口向西前往闪金镇，在那里的铁匠阿古斯仍然可以定期获得王国深处的矿产补给。"}},faq={{q="为什么弗纳的铁矿用完了？",a="湖畔镇的当地卫兵面临着赤脊山敌对生物、豺狼人和黑石兽人的持续攻击。弗纳将所有的铁矿库存都投入到了修理他们破损的盔甲和武器上，导致没有任何存货留给平民使用。",al={"为什么没有铁矿","弗纳缺乏金属","湖畔镇铁矿短缺"}},{q="铁匠阿古斯是谁？",a="铁匠阿古斯是艾尔文森林中闪金镇的驻地铁匠。他的锻造炉位于王国繁华的中心地带附近，相比湖畔镇这样的边境城镇，他更容易获得矿锭和补给。",al={"闪金镇阿古斯","阿古斯是谁","闪金镇的铁匠"}},{q="为什么湖畔镇得不到暴风城的补给？",a="暴风城的统治者们深陷政治僵局，而瓦里安·乌瑞恩国王至今下落不明。由于贵族议会扣留了军队和资金，像湖畔镇这样的边境城镇大多只能依靠他们所能凑到的区域贸易来勉强维持生存。",al={"为什么没有暴风城的援助","湖畔镇被忽视","暴风城的疏忽"}},{q="为什么马掌在赤脊山如此重要？",a="赤脊山崎岖且残酷的地形会迅速摧毁未钉马掌的野兽蹄部。没有马掌，信使、补给车队和巡逻坐骑就会跛行，从而切断湖畔镇与王国其他地区的联系。",al={"为什么需要马掌","马掌的重要性"}},{q="找到铁匠阿古斯之后会发生什么？",a="阿古斯会收下弗纳的便笺，并提供一批马掌供你带回湖畔镇，从而开启后续的任务来帮助保障这个饱受战火的定居点的安全。",al={"后续任务","找阿古斯之后做什么"}},{q="铁匠阿古斯在闪金镇的什么位置？",a="他在闪金镇Lion's Pride Inn旁边的露天锻造炉工作，就在穿越艾尔文森林的主路旁。",al={"阿古斯在哪里","阿古斯的位置"}}},fp="18,180,32.368.0,22.325.0,26.194.0,19.149.0,48.244.0,43.186.0,40.123.0,42.114.0"}
P.entries["quest:1180"] = {n="地精赞助商",s="加兹鲁维回到了你此行的目的：答应给普兹克的燃油调节器还没有送到棘齿城。藏宝海湾的里维加兹曾说会把它运过来，但可能在哪个环节出了岔子。加兹鲁维让你去找那里的码头管理员罗兹基尔，他可以查询货物记录。",h="加兹鲁维回到了你此行的目的：答应给普兹克的燃油调节器还没有送到棘齿城。藏宝海湾的里维加兹曾说会把它运过来，但可能在哪个环节出了岔子。加兹鲁维让你去找那里的码头管理员罗兹基尔，他可以查询货物记录。",kw={"藏宝海湾","燃油调节器","加兹鲁维","地精赞助","沙漠赛道","普兹克","棘齿城","里维加兹","码头管理员罗兹基尔"},sec={{t="未送达的零件",b="加兹鲁维承认他答应给普兹克一个新的燃油调节器，但至今尚未收到。藏宝海湾的里维加兹曾说会把它运过来，但可能被遗漏了。如果真是这样，那也没什么好办法，但你至少可以查清楚它是否离开了藏宝海湾。位于藏宝海湾码头最西北端的码头管理员罗兹基尔可以帮你查看货物记录。"},{t="码头管理员的记录",b="罗兹基尔查询了运往棘齿城的货运日志。最近的一批货是来自崔斯里克的靴子，除此之外就只有建筑材料和工具了。并没有什么比赛零件。"}},faq={{q="什么零件丢失了？",a="加兹鲁维答应给普兹克一个新的燃油调节器，但加兹鲁维目前还没有收到它。",al={"普兹克的零件","为什么是燃油调节器","普兹克的货物"}},{q="是谁说要把调节器送到棘齿城的？",a="藏宝海湾的里维加兹说他会把它运给棘齿城的加兹鲁维。",al={"谁寄送了这个零件","里维加兹的零件","谁有燃油调节器"}},{q="谁在藏宝海湾保管航运记录？",a="码头管理员罗兹基尔，他可以查看货物记录。他就位于藏宝海湾码头最西北端。",al={"藏宝海湾货物管理员","谁是码头管理员罗兹基尔","罗兹基尔在哪里"}},{q="这一步在任务链中处于什么位置？",a="它紧随第一个地精赞助任务之后，在该任务中普兹克把你打发去找加兹鲁维，而下一步是地精赞助（3）。",al={"地精赞助任务链","任务进度","这一步之前是什么"}}},fp="18,290,22.386.0,25.183.1,21.82.0,50.79.0,44.117.0,38.122.0"}
P.entries["quest:1181"] = {n="地精赞助商",s="码头管理员罗兹基尔对于丢失的燃料调节器无法提供进一步的帮助，他建议你亲自去询问大财主里维加兹。你可以在藏宝海湾港口对面的旅店顶层找到这位大财主。",h="码头管理员罗兹基尔对于丢失的燃料调节器无法提供进一步的帮助，他建议你亲自去询问大财主里维加兹。你可以在藏宝海湾港口对面的旅店顶层找到这位大财主。",kw={"大财主里维加兹","藏宝海湾","燃料调节器","地精赞助","沙漠赛道","棘齿城","码头管理员罗兹基尔"},sec={{t="询问大财主",b="码头管理员罗兹基尔告诉你，在追踪运往棘齿城的失踪货物方面，他已经帮不上什么忙了。如果你想继续调查，他建议你直接去找大财主本人，毕竟要说谁最了解里维加兹的生意，那肯定就是里维加兹自己。他就在港口对面的旅店顶层等你。"},{t="大财主的答复",b="大财主里维加兹知道你在说什么，但他帮不上忙。他派去寻找燃料调节器蓝图的人手已经回来了，却一无所获。"}},faq={{q="我能在哪里找到大财主里维加兹？",a="在藏宝海湾港口对面的旅店顶层。",al={"大财主里维加兹位置","里维加兹在哪里","寻找藏宝海湾的里维加兹"}},{q="为什么码头管理员罗兹基尔要让你去找里维加兹？",a="罗兹基尔已经无法提供更多帮助，他说如果有人了解里维加兹的生意，那一定是里维加兹本人。",al={"为什么要和里维加兹谈话","罗兹基尔指引去大财主处","为什么要见大财主里维加兹"}},{q="正在追踪的是什么货物？",a="一个新的燃料调节器，原本应该运往棘齿城，供沙漠赛道的地精赛车手使用。",al={"丢失了什么货物","我们在寻找什么","丢失的棘齿城货物"}},{q="这一步在任务链中处于什么位置？",a="它紧接在与码头管理员罗兹基尔交谈的“地精赞助（2）”之后，下一步是“地精赞助（4）”。",al={"地精赞助3之前是什么","地精赞助任务链进度"}}},fp="18,208,16.299.0,18.163.1,32.63.0,49.110.0,36.101.0,38.114.0"}
P.entries["quest:1182"] = {n="地精赞助商",s="大财主里维加兹告诉你，在北荆棘谷纳菲瑞提湖的荆棘谷地精伐木机使用了一种新型的燃料调节器，普兹克可能用得上。工头考兹尔比大财主预想的要聪明，所以里维加兹派你去寻找燃料调节器的蓝图。",h="大财主里维加兹告诉你，在北荆棘谷纳菲瑞提湖的荆棘谷地精伐木机使用了一种新型的燃料调节器，普兹克可能用得上。工头考兹尔比大财主预想的要聪明，所以里维加兹派你去寻找燃料调节器的蓝图。",kw={"大财主里维加兹","蓝图","工头考兹尔","燃料调节器","地精的赞助","纳菲瑞提湖","沙漠赛道","普兹克","荆棘谷地精"},ang={["class:Rogue"]="潜行者可以在不需要工头钥匙的情况下直接开锁打开装着蓝图的盒子。"},sec={{t="工头的蓝图",b="大财主里维加兹解释说，北荆棘谷纳菲瑞提湖的荆棘谷地精伐木机携带了一种新型的燃料调节器。如果普兹克能得到详细资料，就能从中获益，但那里的工头考兹尔比里维加兹想象的要聪明。你或许能更幸运一些。里维加兹知道蓝图就保存在考兹尔的房子里，几乎肯定锁了起来。荆棘谷地精的基地位于纳菲瑞提湖，在山谷的东北角。钥匙就在油塔顶部的船舱里，由工头考兹尔保管，而装着蓝图的盒子则在那座塔底附近的小屋里。里维加兹承认那里的侏儒小组相当出色，并表示他的小组需要一切能找到的优势。"},{t="给大财主的一份拷贝",b="拿到蓝图后，里维加兹想要一份留作自己的记录，然后派你去普兹克那里，以免普兹克认为他的赞助人之一抛弃了他。"}},faq={{q="为什么大财主里维加兹想要燃料调节器的蓝图？",a="纳菲瑞提湖的荆棘谷地精伐木机拥有一个新型的燃料调节器，里维加兹认为如果普兹克能得到详细资料，就能从中获益。",al={"为什么偷蓝图","为什么需要燃料调节器","里维加兹的动机"}},{q="蓝图保存在哪里？",a="在北荆棘谷纳菲瑞提湖的荆棘谷地精基地，油塔脚下一间小屋里的盒子里。",al={"蓝图在哪里","燃料调节器的蓝图位置","考兹尔的房子"}},{q="谁拿着钥匙？",a="工头考兹尔带着钥匙，他在油塔顶部的船舱里工作。",al={"考兹尔的钥匙","钥匙在哪里","如何打开箱子"}},{q="这一步在任务链中处于什么位置？",a="它紧随地精的赞助（3）之后，在该任务中码头管理员罗兹基尔派你去找大财主。下一步是地精的赞助（5）。",al={"之前是什么任务","下一个任务是什么","地精的赞助任务链"}}},fp="18,259,24.743.0,20.166.1,55.159.0,30.135.0,18.69.0,38.126.0"}
P.entries["quest:1183"] = {n="地精赞助商",s="大财主里维加兹已经准备好了燃料调节器的蓝图，并将其发往闪光平原的普兹克。他致以问候，并补充说，如果普兹克需要任何帮助，尽管开口。",h="大财主里维加兹已经准备好了燃料调节器的蓝图，并将其发往闪光平原的普兹克。他致以问候，并补充说，如果普兹克需要任何帮助，尽管开口。",kw={"大财主里维加兹","燃料调节器的蓝图","地精赞助","沙漠赛道","普兹克","闪光平原","千针石林"},sec={{t="对普兹克的问候",b="大财主里维加兹说一切都准备就绪了。你带着蓝图前往闪光平原寻找普兹克，并传达了大财主的问候和一条口信：如果普兹克需要任何帮助，尽管开口。里维加兹说他会等着普兹克打破赛道纪录的好消息。"},{t="改进设计",b="普兹克本以为调节器已经组装好了。不过，他看到了从头改进设计的机会。他计划绘制更完善的草图，制造出零件并尽快安装。"}},faq={{q="是谁派你送蓝图的？",a="大财主里维加兹从藏宝海湾派你出发，并向普兹克致以问候。",al={"谁给予地精赞助5","任务发布者","里维加兹任务"}},{q="谁接收燃料调节器的蓝图？",a="闪光平原上的普兹克。",al={"我该把蓝图带到哪里","谁拿到蓝图","普兹克位置"}},{q="大财主里维加兹希望能听到什么消息？",a="他说他会等着普兹克打破赛道纪录的好消息。",al={"里维加兹的动机","大财主里维加兹赞助"}},{q="在此次运送任务之前发生了什么？",a="这紧接在“地精赞助（4）”之后，在那项任务中你为里维加兹取回了蓝图。下一步是“第十八位飞行员”。",al={"前置任务","导致此任务的原因","地精赞助系列任务"}}},fp="18,200,18.282.0,20.207.1,34.69.0,43.32.0,38.72.0,32.123.0"}
P.entries["quest:1184"] = {n="虫群的消息",s="科兰有一条消息要带给奥格瑞玛的贝尔戈洛姆·石槌。你要带话回去，说莫克塔尔在千针石林表现良好，而且科兰的研究进展顺利。",h="科兰有一条消息要带给奥格瑞玛的贝尔戈洛姆·石槌。你要带话回去，说莫克塔尔在千针石林表现良好，而且科兰的研究进展顺利。",kw={"贝尔戈洛姆·石槌","科兰","莫克塔尔","奥格瑞玛","虫群之部分","锈槌挖掘场","其拉虫人","千针石林"},sec={{t="带给奥格瑞玛的消息",b="在从锈槌挖掘场的其拉虫人身上取回破碎的甲壳之后，科兰让你回到奥格瑞玛找贝尔戈洛姆·石槌。告诉贝尔戈洛姆，莫克塔尔在千针石林很好地执行了他的命令。还要告诉他，科兰的研究正在取得进展，他希望能尽快学到更多东西。"},{t="贝尔戈洛姆的回复",b="贝尔戈洛姆·石槌对你的努力表示感谢，并说大酋长听到你如此坚韧不拔一定会很高兴。他答应会提你的名字，说萨尔经常与他交谈并重视他的意见。如果科兰有关于其拉虫人的消息，贝尔戈洛姆想知道，因为他认为这些生物是一个严重的威胁。"}},faq={{q="是谁让你去奥格瑞玛的？",a="一直在研究其拉虫人的科兰，请你带话给奥格瑞玛的贝尔戈洛姆·石槌。",al={"任务发布者","谁开启了任务","谁发布了虫群之部分"}},{q="你要把消息交给谁？",a="奥格瑞玛的贝尔戈洛姆·石槌。",al={"我该去找谁","任务要去哪里","贝尔戈洛姆·石槌位置"}},{q="科兰想传达什么消息？",a="莫克塔尔在千针石林很好地执行了贝尔戈洛姆的命令，科兰的研究正在取得进展，很快就会有更多的发现。",al={"消息内容是什么","科兰的报告"}},{q="科兰在研究什么生物？",a="是其拉虫人。这项工作的开端是来自于千针石林锈槌挖掘场的其拉虫人身上发现的破碎甲壳。",al={"是什么生物","为什么要研究虫群"}}},fp="18,179,18.297.0,15.317.1,27.105.0,47.31.0,40.141.0,42.132.0"}
P.entries["quest:1186"] = {n="第十八个驾驶员",s="普兹克将会忙于将新的燃料调节器的蓝图安装到赛车设计中，但他建议你通过与在闪光平原的拉泽瑞克交谈来进一步帮助团队。拉泽瑞克是车队的飞行员，也是第十八位飞行员，他喜欢给赛车增加改装。",h="普兹克将会忙于将新的燃料调节器的蓝图安装到赛车设计中，但他建议你通过与在闪光平原的拉泽瑞克交谈来进一步帮助团队。拉泽瑞克是车队的飞行员，也是第十八位飞行员，他喜欢给赛车增加改装。",kw={"地精","飞行员","普兹克","赛道","拉泽瑞克","闪光平原","千针石林"},sec={{t="会见飞行员",b="普兹克说燃料调节器让他忙得不可开交，但如果你和闪光平原上的拉泽瑞克谈谈，还能帮团队更多忙。拉泽瑞克是车队的飞行员，实际上是第十八位飞行员，他喜欢在赛车上做点自己的小改装。普兹克补充说，拉泽瑞克有点疯疯癫癫的，所以你尽量不要表现得太惊讶。"},{t="飞行员的回忆",b="拉泽瑞克知道你一直在帮助普兹克，他说他曾经也像你一样，在维修区跑来跑去，做着机械师们让他做的任何杂活。现在，他是地精赛车队的王牌飞行员。"}},faq={{q="谁是拉泽瑞克？",a="拉泽瑞克是一个地精，是闪光平原上地精赛车队的飞行员。普兹克称他是车队的第十八位飞行员。",al={"谁是第十八位飞行员","拉泽瑞克背景故事","地精飞行员"}},{q="为什么普兹克要让你去找拉泽瑞克？",a="普兹克忙于将新的燃料调节器整合到赛车设计中，并建议你通过与拉泽瑞克交谈来进一步帮助团队。",al={"为什么要找拉泽瑞克","普兹克第十八位飞行员"}},{q="拉泽瑞克是个什么样的人？",a="普兹克说，拉泽瑞克喜欢在赛车上做一些自己的小改动，而且他有点疯疯癫癫的。",al={"拉泽瑞克性格","拉泽瑞克疯了吗"}},{q="在此之前发生了什么？",a="这是“地精赞助（5）”的后续任务，在该任务中你将燃料调节器的蓝图交给了普兹克。",al={"第十八位飞行员任务前置","拉泽瑞克之前的任务链"}}},fp="20,261,14.352.0,17.215.1,16.128.0,37.144.0,22.106.0,22.100.0"}
P.entries["quest:1187"] = {n="拉泽瑞克的调整",s="在闪光平原，拉泽瑞克会在普兹克改装完赛车之后再进行个人化的改装。他从加基森的史瑞夫那里订购了一个瑟里姆助推器，但据拉泽瑞克所知，运送助推器的飞艇在尘泥沼泽坠毁了，他希望能找回那个助推器。",h="在闪光平原，拉泽瑞克会在普兹克改装完赛车之后再进行个人化的改装。他从加基森的史瑞夫那里订购了一个瑟里姆助推器，但据拉泽瑞克所知，运送助推器的飞艇在尘泥沼泽坠毁了，他希望能找回那个助推器。",kw={"尘泥沼泽","加基森","gizmorium","普兹克","拉泽瑞克","瑟里姆助推器","闪光平原","史瑞夫","千针石林"},sec={{t="更多动力",b="拉泽瑞克承认普兹克是个很棒的技师，但他觉得普兹克太保守，不敢在车上装太多火力。等普兹克改装完赛车后，拉泽瑞克会花时间进行个人化改动：调松操纵装置，拆掉一些框架，并加上更强的动力。他曾在加基森Gizmorium的史瑞夫那里订购了一个瑟里姆助推器，但据拉泽瑞克所说，运送它的飞艇在尘泥沼泽坠毁了。他需要找回这个助推器带回闪光平原，因为如果不加装那个额外的助推装置就去参加比赛，简直是场灾难。"},{t="装在赛车上",b="拉泽瑞克对这个助推器赞不绝口：整整十五磅的瑟里姆。把它绑在赛车侧面，应该能让他在赛道上跑出惊人的速度，把那些侏儒远远地甩在身后。"}},faq={{q="拉泽瑞克是谁？",a="拉泽瑞克是闪光平原的一名车手，他会在普兹克改装完赛车后，再进行个人化的改装。",al={"拉泽瑞克","拉泽瑞克的改装任务给予者","拉泽瑞克 闪光平原"}},{q="助推器是从哪里来的？",a="拉泽瑞克是从加基森Gizmorium的史瑞夫那里订购的。",al={"助推器来源","谁制造了瑟里姆助推器","加基森 gizmorium"}},{q="瑟里姆助推器现在在哪里？",a="拉泽瑞克说运送它的飞艇在尘泥沼泽坠毁了。",al={"瑟里姆助推器在哪里","助推器位置","坠毁的飞艇位置"}},{q="拉泽瑞克为什么要这个助推器？",a="拉泽瑞克想要比普兹克肯提供的动力更强的动力，而且他认为如果不加装那个额外的助推装置去参加比赛，简直是场灾难。",al={"他为什么需要瑟里姆","为什么需要瑟里姆助推器"}},{q="在这之前要做什么？",a="首先要完成“第十八位飞行员”。",al={"上一个任务","前置任务","开启拉泽瑞克的改装的前置任务"}}},fp="19,263,10.560.0,21.199.1,16.113.0,32.57.0,35.67.0,35.133.0,27.32.0"}
P.entries["quest:1188"] = {n="安全第一",s="拉泽瑞克发现史瑞夫把瑟银炸药助推器的保险装置留在了上面。这限制了助推器能产生的功率，而拉泽瑞克之前要求把它拆掉。你被派往塔纳利斯的加基森找史瑞夫。",h="拉泽瑞克发现史瑞夫把瑟银炸药助推器的保险装置留在了上面。这限制了助推器能产生的功率，而拉泽瑞克之前要求把它拆掉。你被派往塔纳利斯的加基森找史瑞夫。",kw={"加基森机械修理店","拉泽瑞克","安全第一","瑟银炸药助推器","闪光平原","史瑞夫","塔纳利斯"},sec={{t="谁都不想要的保险",b="拉泽瑞克检查了瑟银炸药助推器，发现保险还在上面。这限制了助推器能提供的功率，而拉泽瑞克之前告诉过史瑞夫应该把它关掉。拉泽瑞克把助推器交给你，并让你前往闪光平原南部的塔纳利斯沙漠，去加基森的机械修理店找史瑞夫拆掉保险。"},{t="史瑞夫的回答",b="机械修理店提供你所需的所有修补服务。当你把助推器交给史瑞夫时，他否认在上面加装了任何保险锁。按照史瑞夫的说法，这个助推器几乎全部都是瑟银炸药，而且已经经过改造，在使用时可以释放出更多的威力。史瑞夫说，拉泽瑞克如果不是把事情做得过火，他就永远不会满足。"}},faq={{q="谁派你前往加基森的？",a="地精飞行员拉泽瑞克派你带着他的瑟银炸药助推器前往加基森。",al={"任务发布者","谁开启了安全第一","拉泽瑞克任务"}},{q="为什么拉泽瑞克对助推器不满意？",a="史瑞夫留下了保险装置。这限制了拉泽瑞克能从助推器中获得的功率，而拉泽瑞克之前要求将其拆除。",al={"为什么拉泽瑞克抱怨","助推器问题","助推器出了什么问题"}},{q="在哪里可以找到史瑞夫？",a="史瑞夫在加基森，位于闪光平原以南的塔纳利斯沙漠中的机械修理店里。",al={"史瑞夫位置","史瑞夫在哪里","加基森机械修理店位置"}},{q="你要带什么物品去加基森？",a="你携带着拉泽瑞克的瑟银炸药助推器，这是拉泽瑞克交给你带给史瑞夫的。",al={"什么物品","助推器物品","你带什么给史瑞夫"}},{q="这次交付之后还有什么？",a="这个任务链还有第二部分，也叫作“安全第一”。",al={"下一个任务","安全第一之后是什么","安全第一后续"}}},fp="12,220,22.321.0,15.350.1,27.78.0,41.123.0,26.98.0,40.84.0,31.65.0"}
P.entries["quest:1189"] = {n="安全第一",s="史瑞夫已经按照拉泽瑞克的要求完成了瑟银燃料助推器，你带着改造过的助推器回到了闪光平原交给拉泽瑞克。史瑞夫给出的警告是：引爆时要小心，因为一旦失手，拉泽瑞克就会变成赛道上的一个焦痕。这是第一个“安全第一”任务的后续。",h="史瑞夫已经按照拉泽瑞克的要求完成了瑟银燃料助推器，你带着改造过的助推器回到了闪光平原交给拉泽瑞克。史瑞夫给出的警告是：引爆时要小心，因为一旦失手，拉泽瑞克就会变成赛道上的一个焦痕。这是第一个“安全第一”任务的后续。",kw={"加基森","普兹克","拉泽瑞克","安全第一","瑟银燃料助推器","闪光平原","史瑞夫","千针石林"},sec={{t="史瑞夫的警告",b="史瑞夫交出了按拉泽瑞克要求改造好的助推器。史瑞夫给出的警告是：拉泽瑞克引爆它时必须小心。稍有差池，他将无法领先比赛；而是会变成赛道上的一个焦痕。史瑞夫还补充说那真是太可惜了，不知道第十九位车手是否会更有水平。"},{t="座椅下的沙子",b="回到闪光平原，拉泽瑞克正在抱怨普兹克，因为普兹克往他的赛车里倒了一桶沙子。拉泽瑞克质问道，座位底下全是沙子，他该怎么达到最高速度？"},{t="归还助推器",b="拉泽瑞克对改造后的助推器很满意。他希望自己能在引爆时亲眼看到那些侏儒们的表情，不过他估计自己会忙着创造新的赛道纪录，无暇顾及。"}},faq={{q="是谁把改造好的助推器送回闪光平原的？",a="史瑞夫在加基森完成了瑟银燃料助推器的工作，并把它交给你带回闪光平原给拉泽瑞克。",al={"谁给予安全第一2任务","史瑞夫任务发布者","谁改造了助推器"}},{q="史瑞夫警告了什么？",a="史瑞夫说拉泽瑞克在引爆助推器时应该小心。只要稍有差池，他就无法领先比赛，而是会变成赛道上的一个焦痕。",al={"助推器危险吗","史瑞夫的警告","助推器风险"}},{q="为什么拉泽瑞克对他的车感到不满？",a="普兹克往赛车里倒了一桶沙子，拉泽瑞克问在座位底下全是沙子的情况下，他怎么可能达到最高速度。",al={"拉泽瑞克为什么生气","普兹克的沙桶","拉泽瑞克的抱怨"}}},fp="12,302,21.329.0,19.188.0,20.176.1,49.133.0,28.149.0,40.119.0"}
P.entries["quest:119"] = {n="回复弗纳",s="“回到弗纳身边”是一个联盟跑腿任务，需要将一箱刚打制好的五十个马掌运回湖畔镇。你受闪金镇的铁匠铁匠阿古斯之托，必须穿过边界回到赤脊山，将这箱货物交给急不可耐的弗纳·奥斯古。",h="“回到弗纳身边”是一个联盟跑腿任务，需要将一箱刚打制好的五十个马掌运回湖畔镇。你受闪金镇的铁匠铁匠阿古斯之托，必须穿过边界回到赤脊山，将这箱货物交给急不可耐的弗纳·奥斯古。",kw={"一箱马掌","艾尔文森林","闪金镇","湖畔镇","赤脊山","铁匠阿古斯","马掌的价格","弗纳·奥斯古"},ang={["faction:Alliance"]="在艾尔文森林和赤脊山之间运营补给线，对于将湖畔镇这样受困的边缘定居点与王国核心联系起来至关重要。",["profession:Blacksmithing"]="运送五十个马掌凸显了后勤工作的艰辛，因为当本地热火朝天的铁砧被战争拖累时，维持边境坐骑的足具供应就变得十分困难。"},sec={{t="跨越边境的信使",b="为了给当地坐骑寻找必备的足具，你从湖畔镇一路跋涉来到艾尔文森林，现在你必须将这箱打好的五十个马掌运回东方，任务才算完成。赤脊山一直受困于物资短缺和豺狼人的劫掠，每一件铁器对于维持马匹和驮兽在崎岖山路上行走都至关重要。"},{t="板条箱上的便条",b="虽然弗纳·奥斯古看到马掌送达感到如释重负，但铁匠阿古斯并非出于兄弟情谊才打制这些马掌。货物上附有一张索款单。弗纳发现闪金镇的铁匠竟然要求支付报酬时，明显感到恼火，尽管赤脊山面临的紧迫危险让他没时间为这笔账争执，只能转而处理更危险的问题。"}},faq={{q="我该把一箱马掌带到哪里去？",a="把这箱货物带回湖畔镇交给弗纳·奥斯古，他就在赤脊山，位于桥梁和湖边码头的东侧。",al={"弗纳在哪里","任务交还地点","谁需要马掌"}},{q="是谁把这批货送回赤脊山的？",a="铁匠阿古斯，也就是驻扎在闪金镇Lion's Pride Inn外的常驻铁匠，在打制工作完成后提供了这箱货物。",al={"谁发布了任务","铁匠阿古斯","任务发布者"}},{q="弗纳收到货物时为什么不高兴？",a="阿古斯在货物上附了一张发票，要求支付五十个马掌的全额费用，这让弗纳非常生气，因为他显然希望对方能免费帮忙或提供更优惠的条件。",al={"为什么弗纳很生气","阿古斯的便条","弗纳的反应"}},{q="完成这次运送后会开启哪些任务？",a="完成这次运送直接导向弗纳针对当地威胁签署的战斗合约：猎杀赤脊山豺狼人的“豺狼人的咆哮”，以及一个名为“腹部鳞片”的跑腿任务。",al={"后续任务","后续任务链","解锁什么"}},{q="为什么湖畔镇需要从闪金镇进口物资？",a="湖畔镇正遭受豺狼人和黑石兽人的围攻，当地工匠人手严重不足。诸如大宗铁质马掌之类的日常必需品，往往不得不从像闪金镇这样更安稳的定居点运来。",al={"为什么艾尔文森林的马掌","为什么进口马掌","赤脊山补给"}},{q="铁匠阿古斯会随你一起回赤脊山吗？",a="不。铁匠阿古斯仍留在闪金镇的熔炉前，将跨区域的运送职责完全留给了来往的冒险者。",al={"阿古斯会来吗","护送铁匠阿古斯"}}},fp="16,171,27.233.0,21.242.0,40.115.0,40.118.0,47.154.0,51.142.0,57.178.0,48.86.0"}
P.entries["quest:1190"] = {n="跟上节奏",s="普兹克确信黄铜螺栓兄弟找到了一种新的建筑材料。他们的赛车跑得比以前快多了，但他们的设计图和比赛数据却没有任何变化。里泽尔·黄铜螺栓几乎一直盯着这项发现的计划书，扎米克可以制造一场骚乱，让你趁机把它们偷出来。此任务紧接在“菲兹尔的消息”之后。",h="普兹克确信黄铜螺栓兄弟找到了一种新的建筑材料。他们的赛车跑得比以前快多了，但他们的设计图和比赛数据却没有任何变化。里泽尔·黄铜螺栓几乎一直盯着这项发现的计划书，扎米克可以制造一场骚乱，让你趁机把它们偷出来。此任务紧接在“...",kw={"黄铜螺栓","骚乱","普兹克","赛车","里泽尔·黄铜螺栓","图纸","闪光平原","千针石林","扎米克"},sec={{t="快得不合常理",b="普兹克只能想到一种解释来解释黄铜螺栓兄弟的赛车为何变得如此之快：一种新的建筑材料。他们的设计图和从比赛中收集的一切数据看起来都和以前一样。目前已知的是，里泽尔·黄铜螺栓几乎一直专注于这项发现的计划书。"},{t="扎米克的调虎离山计",b="扎米克可以制造一场骚乱，趁着骚乱持续期间，你得把里泽尔的计划书偷走。闪光平原上的普兹克想要这些东西。"},{t="被偷走的卷轴",b="这些计划书原来是一卷匆忙写就的笔记和设计图，内容是关于某种原材料的提炼方法。"}},faq={{q="普兹克为什么要里泽尔的计划书？",a="黄铜螺栓兄弟的赛车速度变快了，而他们的设计图和数据却没有变化。普兹克断定他们找到了一种新的建筑材料，因此想要里泽尔一直全神贯注研究的那份计划书。",al={"普兹克的动机","为什么要偷黄铜螺栓的计划书","跟上节奏的原因"}},{q="谁来帮忙引开里泽尔·黄铜螺栓？",a="扎米克可以制造一场骚乱，让你有机会偷走里泽尔的计划书。",al={"谁来制造骚乱","扎米克的作用","如何引开里泽尔"}},{q="计划书是为谁偷的？",a="为了普兹克，他就在千针石林的闪光平原上。",al={"跟上节奏在哪里","跟上节奏的位置"}},{q="这一步之前是什么？",a="此任务紧接在“菲兹尔的消息”之后。",al={"跟上节奏的前置条件","跟上节奏之前的任务是什么"}},{q="拿到计划书后接下来做什么？",a="任务链接下来是“里泽尔的图纸”。",al={"下一个任务是什么","完成跟上节奏之后"}}},fp="12,355,27.304.0,22.126.0,17.108.1,36.196.0,37.76.0,29.63.0,28.27.0,38.45.0"}
P.entries["quest:1191"] = {n="扎米克的困扰",s="扎米克可以制造“保持步调”所需要的调虎离山之计。这个任务会在你执行“保持步调”的过程中出现，如果没有这个步骤，任务就无法完成。",h="扎米克可以制造“保持步调”所需要的调虎离山之计。这个任务会在你执行“保持步调”的过程中出现，如果没有这个步骤，任务就无法完成。",kw={"调虎离山","保持步调","千针石林","扎米克"},sec={{t="及时的调虎离山",b="当你正在进行“保持步调”时，扎米克可以制造一场骚乱。当骚乱发生时，里兹尔会离开他的小屋，因杜雷姆计划就会被遗弃在那里。"}},faq={{q="谁给予“扎米克的调虎离山”任务？",a="千针石林的扎米克。",al={"谁开启扎米克的调虎离山","扎米克任务给予者","在哪里接到扎米克的调虎离山"}},{q="这与“保持步调”有什么关联？",a="它会在你执行“保持步调”的过程中出现，如果没有这个步骤，任务就无法完成。",al={"这是完成保持步调所必需的吗","保持步调与扎米克","与保持步调的联系"}},{q="这场骚乱有什么作用？",a="里兹尔会离开他的小屋，而他的计划会被遗弃在那里。",al={"扎米克制造骚乱会发生什么","里兹尔离开小屋"}},{q="联盟和部落的冒险者都能与扎米克合作吗？",a="是的。这是一个中立任务，对两个阵营都开放。",al={"扎米克是中立的吗","联盟还是部落的扎米克","谁能做扎米克的调虎离山"}}},fp="19,158,18.153.0,30.27.0,37.98.0,27.53.0,56.43.0"}
P.entries["quest:1192"] = {n="精铁矿石",s="普兹克计划用瑟银矿石来打造赛车的零部件，这需要大量的原始矿石。这些矿石可以在卡兹莫丹海对面的荒芜之地奥达曼挖掘场中找到。侏儒们已经在开采他们自己的矿石了，普兹克也不想落后于他们。",h="普兹克计划用瑟银矿石来打造赛车的零部件，这需要大量的原始矿石。这些矿石可以在卡兹莫丹海对面的荒芜之地奥达曼挖掘场中找到。侏儒们已经在开采他们自己的矿石了，普兹克也不想落后于他们。",kw={"荒芜之地","瑟银","瑟银矿石","普兹克","赛车","千针石林","奥达曼"},sec={{t="来自奥达曼的矿石",b="普兹克需要四块原始瑟银矿石。可以在卡兹莫丹海对面的荒芜之地奥达曼挖掘场中找到。侏儒们已经在开采他们自己的矿石了，所以普兹克也想弄到一些。这任务源自瑞兹尔的图纸。"}},faq={{q="为什么普兹克需要瑟银矿石？",a="他想用瑟银来制造赛车的几个部件，这需要大量的原始矿石。",al={"瑟银的用途","为什么需要瑟银矿石","普兹克需要瑟银的目的"}},{q="哪里可以找到瑟银矿石？",a="在卡兹莫丹海对面的荒芜之地奥达曼挖掘场。",al={"哪里能找到瑟银矿石","瑟银的位置","我该去哪里获取瑟银矿石"}},{q="为什么获取这种矿石很重要？",a="侏儒们已经在开采他们自己的瑟银了，普兹克不想落后于他们。",al={"为什么要急着获取瑟银","侏儒的瑟银竞争"}},{q="这个任务的前置任务是什么？",a="它源自瑞兹尔的图纸，而那又源自保持进度。",al={"瑟银矿石的前置条件","瑟银任务线的前一个任务"}}},fp="12,280,16.242.0,34.99.0,32.65.0,34.97.0,22.66.0"}
P.entries["quest:1194"] = {n="瑞兹尔的图表",s="瑞兹的蓝图上无人看管，上面描述了瑟银矿的提炼方法。这些潦草的字迹指向了位于荒芜之地的奥达曼，那是矮人的挖掘场，也是矿石的产地，笔记中还有许多关于耐热性的内容。一张蓝图上压着一块原矿作为镇纸，你带着那个样本去闪光平原找普兹克。这是“保持节奏”任务的后续。",h="瑞兹的蓝图上无人看管，上面描述了瑟银矿的提炼方法。这些潦草的字迹指向了位于荒芜之地的奥达曼，那是矮人的挖掘场，也是矿石的产地，笔记中还有许多关于耐热性的内容。一张蓝图上压着一块原矿作为镇纸，你带着那个样本去闪光平原找普兹...",kw={"荒芜之地","瑟银","普兹克","瑞兹","蓝图","闪光平原","奥达曼"},sec={{t="关于瑟银的笔记",b="瑞兹的蓝图描述了瑟银矿的提炼方法。瑞兹潦草的字迹指向了位于荒芜之地的奥达曼，那是矮人的挖掘场，也是矿石的产地。其他许多笔记则写着它有多么耐热。一块原瑟银矿石压在蓝图上作为镇纸，你就是带着那个样本去找普兹克的。"},{t="普兹克的结论",b="普兹克觉得瑟银很有意思。如果它真的像你所说的那样耐热，那就解释了为什么侏儒近来有了这么大的改进。这个样本对于测试来说是无价之宝，不过普兹克需要更多样本才能真正派上用场。"}},faq={{q="瑞兹从哪里弄到的瑟银矿？",a="瑞兹潦草的字迹指向了位于荒芜之地的奥达曼，那是矮人的挖掘场。",al={"瑟银产自哪里","瑟银矿来源","瑞兹瑟银位置"}},{q="瑞兹的笔记里关于瑟银说了些什么？",a="瑞兹的笔记描述了矿石的提炼方法，其他许多笔记则是关于它的耐热性。",al={"瑟银有什么用","为什么要用瑟银","瑟银的属性"}},{q="谁负责接收瑟银样本？",a="你把样本带给闪光平原的普兹克。",al={"我该把它交给谁","谁想要瑟银样本","普兹克任务交付"}},{q="这个样本是从哪里来的？",a="一块原瑟银矿石压在瑞兹的蓝图上作为镇纸。",al={"样本在哪里发现的","瑞兹的镇纸"}}},fp="19,356,17.329.0,16.242.1,39.71.0,42.110.0,33.55.0,32.76.0"}
P.entries["quest:1195"] = {n="神圣之火",s="“神圣之火”是一项由雷霆崖的赞金·石蹄发起的部落任务。为了夺回千针石林中由加拉克半人马守护的一件古老圣物，赞金派遣冒险者深入灰谷，从当地树妖手中获取一个神圣的月亮井瓶。",h="“神圣之火”是一项由雷霆崖的赞金·石蹄发起的部落任务。为了夺回千针石林中由加拉克半人马守护的一件古老圣物，赞金派遣冒险者深入灰谷，从当地树妖手中获取一个神圣的月亮井瓶。",kw={"灰谷","蚀刻瓶","弗伦河","加拉克半人马","欢笑姐妹","月亮井","劳恩·峭壁行者","林中树居","神圣之火","千针石林","赞金·石蹄"},ang={["class:Druid"]="牛头人德鲁伊在执行这项任务时面临着一个令人不安的悖论：为了获得能用来打击半人马元素之火的圣水，他们不得不杀害自然的女儿——树妖。",["faction:Horde"]="在林中树居附近挑起事端可能会加剧灰谷中暗夜精灵的紧张局势，但夺取千针石林中的半人马圣物却能巩固部落的南部边境。",["race:Tauren"]="半人马的敌意困扰了牛头人几代人。从这一种族的起源中获得圣物，能为莫高雷的部落提供宝贵的见解，并使他们有筹码对抗这些最凶恶的敌人。"},sec={{t="半人马圣物与精灵之水",b="栖息在千针石林峡谷底部的加拉克半人马部族，严密守护着一件追溯至他们种族起源的古老文物。为了突破他们的防御并熄灭他们那神圣的火焰，赞金·石蹄需要受到月之神力洗礼的水，这便将牛头人的目光引向了北方，即灰谷那充满先祖气息的森林。"},{t="擅闯灰谷",b="获取纯净的月亮井水并非易事。未受祝福的器皿无法盛放这种神圣液体而不使其纯洁性受损，因此部落的使者必须在林中树居附近猎杀欢笑姐妹，以获取一个蚀刻瓶。瓶子取到手后，必须将其浸入弗伦河西岸的一口月亮井中，然后再带回莫高雷。"}},faq={{q="赞金·石蹄为什么需要月亮井水？",a="这些水是为赞金在千针石林的同僚劳恩·峭壁行者准备的。劳恩计划利用月亮井水强大的魔法属性，来熄灭由敌对的加拉克半人马守护的神圣之火，从而使部落能够回收这件古老的圣物。",al={"为什么需要月亮井水","月亮井水的用途","为什么要从灰谷取水"}},{q="蚀刻瓶在哪里可以找到？",a="蚀刻瓶由被称为欢笑姐妹的树妖携带，她们徘徊在灰谷中部林中树居周围的森林里，就在从碎木岗哨向西延伸的北侧道路旁。",al={"蚀刻瓶在哪里","如何获得蚀刻瓶","瓶子位置"}},{q="应该使用哪口月亮井来装水？",a="所需的月亮井位于弗伦河西岸附近，在横贯灰谷中部的主路以南。",al={"哪口月亮井","月亮井位置","在哪里装瓶"}},{q="加拉克半人马是什么人？",a="加拉克是一个好战的半人马部族，居住在千针石林尘土飞扬的广袤大地上。他们拥有一件来自其种族初创时代的古老圣物，圣物周围环绕着神圣的篝火，赞金和劳恩正打算将其扑灭。",al={"加拉克部族","加拉克半人马","加拉克是谁"}},{q="赞金之后，谁会收到装满水的瓶子？",a="当赞金在雷霆崖检查完装满水的瓶子后，他会指示冒险者前往南方的千针石林，并将瓶子直接交给提出要求的劳恩·峭壁行者。",al={"劳恩是谁","水下一步送到哪里","赞金之后的步骤"}},{q="为什么要杀死树妖夺取瓶子？",a="树妖的器皿经过特殊打造，可以盛放纯净的附魔液体而不受污染。普通的瓶子无法安全地运输灌注了暗夜精灵月亮井天界能量的水。",al={"为什么攻击树妖","为什么是欢笑姐妹","树妖器皿"}}},fp="16,159,31.331.0,24.262.0,46.228.0,36.191.0,48.112.0,26.212.0,43.147.0,33.190.0"}
P.entries["quest:1196"] = {n="神圣之火",s="在一次前往灰谷月井的危险旅程之后，必须将一瓶圣水护送至南方的乱风岗。牛头人秘术师劳恩·峭壁行者需要这股月亮精华来打破笼罩在千针石林一件古老半人马圣物上的永恒之火。",h="在一次前往灰谷月井的危险旅程之后，必须将一瓶圣水护送至南方的乱风岗。牛头人秘术师劳恩·峭壁行者需要这股月亮精华来打破笼罩在千针石林一件古老半人马圣物上的永恒之火。",kw={"半人马圣物","蚀刻瓶","乱风岗","升降梯","劳恩·峭壁行者","神圣之火","千针石林","赞金·石蹄"},ang={["class:Druid"]="劳恩·峭壁行者依靠对塞纳留斯血统的深刻了解，来解开树妖与半人马之间那层魔法共鸣。",["faction:Horde"]="运送这个瓶子可以巩固乱风岗，这是部落在千针石林险峻峡谷通道中的重要前哨站。",["race:Tauren"]="每一次对半人马的打击，都是在保护莫高雷以及你家园新近稳固的边境。"},sec={{t="南方的漫漫长路",b="赞金·石蹄的任务要求必须快速穿过卡利姆多中部。既然蚀刻瓶中已经装满了纯净的月井水，你需要穿越贫瘠之地那片被太阳炙烤的大地，走下高耸的升降梯，抵达位于高台之上的乱风岗定居点。劳恩·峭壁行者正伫立在峡谷之上，监视着下方那些凶残的半人马部族。"},{t="共有的血脉与古老的守卫",b="在收到瓶子后，劳恩·峭壁行者揭示了为何暗夜精灵的圣水对于牛头人对抗半人马的行动至关重要。由于树妖和半人马有着共同的祖先——半神塞纳留斯，而塞纳留斯的儿子扎尔塔又是半人马的始祖，因此月井的圣水带有一种奥术共鸣。正是这种联系，使其成为唯一能够穿透守护着半人马圣物的永恒之火的要素。"}},faq={{q="劳恩·峭壁行者在哪里？",a="劳恩·峭壁行者位于千针石林的乱风岗顶端。要找到他，先穿过贫瘠之地向南走，乘坐升降梯进入峡谷，然后沿东南方向的小路前往那座高耸于岩柱之上的升降梯。",al={"劳恩在哪里","劳恩·峭壁行者位置","寻找劳恩·峭壁行者","乱风岗交任务"}},{q="为什么劳恩需要月井水来对抗半人马？",a="半人马和树妖有着共同的血统，追溯起来都是塞纳留斯的后代。正因为这种祖先血缘关系，暗夜精灵月井的圣水拥有一种特殊的魔法协调性，能够用来瓦解保护半人马圣物的永恒之火。",al={"为什么需要月井水","月井与半人马的关系","树妖与半人马的联系"}},{q="是谁派我运送这个瓶子的？",a="赞金·石蹄指派你运送装满水的蚀刻瓶，这些水是在灰谷的受保护月井中取来的。",al={"谁发布了这个任务","赞金·石蹄","神圣之火2任务发布者"}},{q="把瓶子交给劳恩之后会发生什么？",a="一旦劳恩确认圣水完好无损，他会让你直接使用瓶中的力量去熄灭火焰，并从附近的峡谷中取回半人马圣物。",al={"后续任务","劳恩之后的任务","神圣之火第3部分"}},{q="我该怎么下到千针石林？",a="沿贫瘠之地的主路向南走，直到悬崖边缘。在那里你会找到升降梯，这是一对由牛头人利用滑轮操作的木制升降梯，可以将旅行者运送到下方的峡谷底部。",al={"如何到达千针石林","越过贫瘠之地悬崖","升降梯方向"}},{q="为什么牛头人要寻找半人马圣物？",a="牛头人和半人马在卡利姆多进行了数代人的残酷战争。破坏他们的仪式并夺取他们的圣物，可以削弱盘踞在整个千针石林峡谷中的好战部族。",al={"牛头人与半人马的战争","为什么偷取半人马圣物"}}},fp="16,180,20.320.0,30.328.1,33.221.0,51.181.0,27.119.0,43.145.1,40.191.0,43.215.0"}
P.entries["quest:1197"] = {n="神圣之火",s="“神圣之火”是劳恩·峭壁行者针对千针石林加拉克半人马调查任务的最终环节。部落的冒险者必须携带圣水深入裂蹄堡，扑灭部落崇拜的火盆，并夺取古代遗物裂开的蹄子。",h="“神圣之火”是劳恩·峭壁行者针对千针石林加拉克半人马调查任务的最终环节。部落的冒险者必须携带圣水深入裂蹄堡，扑灭部落崇拜的火盆，并夺取古代遗物裂开的蹄子。",kw={"半人马","裂开的蹄子","乱风岗","加拉克","劳恩·峭壁行者","神圣之火","裂蹄峭壁","裂蹄堡","千针石林"},ang={["class:Shaman"]="处理裂开的蹄子的萨满祭司可以轻易地察觉到从护身符中散发出的奇异能量，这证明了半人马所利用的神秘力量远非单纯的蛮力野蛮行径。",["race:Tauren"]="对于牛头人来说，深入半人马巢穴并夺走他们神圣的图腾，既是对几代掠夺的报复，也是乱风岗的一项无价的学术奖赏。"},sec={{t="打击炉火",b="在乱风岗以北坐落着裂蹄峭壁，那是千针石林加拉克半人马领地的中心。在它那如同洞穴般的巢穴——裂蹄堡深处，燃烧着一团半人马视为神圣的火焰。在准备好一个装满水的蚀刻瓶后，劳恩·峭壁行者指派他的盟友潜入这个地下要塞，用水暂时浇灭火焰，并夺取守护在其中的战利品：一件被称为裂开的蹄子的遗物。"},{t="蹄子的秘密",b="裂开的蹄子不仅仅是战争的饰物；当它被呈到劳恩·峭壁行者面前时，它所散发出的奇异而强大的能量立刻引起了他的神秘感应。牛头人学者长期以来一直在卡利姆多与四处劫掠的半人马部落作战，但像这样的遗物暗示着更深层、更难理解的力量在支撑着他们的狂热和部落团结。"}},faq={{q="神圣之火在哪里？",a="火焰燃烧在裂蹄堡的最深处。裂蹄堡位于千针石林乱风岗正北方的裂蹄峭壁内，是一处半人马营地中的洞穴。",al={"裂蹄堡位置","神圣之火在哪里","千针石林火焰洞穴"}},{q="是谁让你去扑灭火焰的？",a="劳恩·峭壁行者，一位驻扎在乱风岗高处的一位长者，他发起了这项任务，作为他研究加拉克半人马工作的总结。",al={"神圣之火任务发放者","劳恩·峭壁行者位置","谁给的任务"}},{q="你如何扑灭火焰？",a="你必须使用劳恩·峭壁行者提供的装满水的蚀刻瓶，其中装有在任务链早期收集的水，用来暂时浇灭火盆。",al={"如何获得裂开的蹄子","熄灭火焰的物品","浇灭神圣之火"}},{q="裂开的蹄子是什么？",a="裂开的蹄子是加拉克半人马供奉在火焰中的神圣部落遗物。劳恩·峭壁行者从中感应到了不同寻常的魔法能量，他希望这件物品能揭示有关半人马文化和力量的秘密。",al={"裂开的蹄子背景","半人马遗物","我们偷走了什么"}},{q="为什么牛头人想要这个遗物？",a="数代以来，半人马部落一直将牛头人驱逐出他们祖先的猎场。通过夺取这件神圣的传家宝，牛头人不仅能破坏加拉克的行动，还能借此探寻敌人野蛮行径背后的奥术或精神本质。",al={"为什么要偷裂开的蹄子","牛头人半人马战争"}},{q="哪个半人马氏族守卫着裂蹄堡？",a="裂蹄峭壁及其内部洞穴由加拉克部落控制，他们是居住在千针石林峡谷底部的最主要半人马氏族。",al={"千针石林半人马部落","加拉克半人马"}}},fp="16,178,19.363.0,19.272.1,34.135.0,32.127.0,29.133.0,24.191.0,34.237.0,41.133.0"}
P.entries["quest:1198"] = {n="寻找塞尔瑞德",s="“寻找塞尔瑞德”是一项由达纳苏斯发出，并代表银色黎明的联盟侦察任务。哨兵山德拉斯指派冒险者进入黑暗深渊的沉没废墟，寻找一名在调查纳迦与邪教徒之间危险联盟时失踪的侦察兵。它代表了银色黎明在其典型的北部警戒之外，与势力范围的早期接触。",h="“寻找塞尔瑞德”是一项由达纳苏斯发出，并代表银色黎明的联盟侦察任务。哨兵山德拉斯指派冒险者进入黑暗深渊的沉没废墟，寻找一名在调查纳迦与邪教徒之间危险联盟时失踪的侦察兵。它代表了银色黎明在其典型的北部警戒之外，与势力范围的...",kw={"银色黎明","灰谷","黑暗深渊","达纳苏斯","纳迦","山德拉斯","塞尔瑞德","暮光之锤"},ang={["class:Paladin"]="隶属于银色黎明的圣骑士们认为，塞尔瑞德独自一人的守望是保护世界免受蔓延的阴影与腐化侵害的神圣职责。",["faction:Alliance"]="这项任务标志着联盟冒险者与银色黎明建立友好关系并为其效力的最早机会之一。",["race:NightElf"]="黑暗深渊内对古老艾露恩神殿的亵渎，使得协助银色黎明成为恢复暗夜精灵神圣遗产的一项紧迫之事。"},sec={{t="达纳苏斯的注视",b="虽然银色黎明因在瘟疫肆虐的洛丹伦废墟中抵御天灾军团而闻名，但其警惕范围也延伸到了整个卡利姆多。哨兵山德拉斯驻扎在达纳苏斯，收集关于在世界各地出现的不自然威胁的低语和情报。当有令人不安的报告称，在灰谷海岸的黑暗深渊淹没的密室中，水生的纳迦和暮光之锤的末日狂热者达成了某种契约时，该组织意识到了潜在的灾难。"},{t="失踪的侦察兵",b="为了评估这些沿海流言的真实性，山德拉斯派遣银月守卫塞尔瑞德悄悄潜入地下洞穴。数周过去了，仍然没有任何消息，这让山德拉斯陷入了困境，因为他的其他侦察兵都各有任务。他担心塞尔瑞德要么在战斗中牺牲，要么被潜伏在波涛之下的黑暗势力俘虏，于是他招募了足够勇敢的旅行者，让他们闯入黑暗深渊，并将他活着带回来。"}},faq={{q="为什么银色黎明对黑暗深渊感兴趣？",a="银色黎明不仅监视东部王国的亡灵，还监控整个艾泽拉斯所有存在的、腐化的威胁。在卡利姆多，古代纳迦与暮光之锤的狂热邪教徒勾结的前景，代表了一种需要他们关注的破坏性邪恶。",al={"为什么银色黎明在这里","银色黎明黑暗深渊","银色黎明纳迦"}},{q="谁是哨兵山德拉斯？",a="哨兵山德拉斯是一位驻扎在暗夜精灵主城达纳苏斯的银色黎明特工。他的主要职责是收集情报，确定在何处迫切需要该组织的援助，并派遣调查员去评估区域性的危机。",al={"谁是山德拉斯","任务发布者山德拉斯","哨兵山德拉斯的角色"}},{q="谁是银月守卫塞尔瑞德？",a="银月守卫塞尔瑞德是银色黎明的一名特工，被派往黑暗深渊进行侦察。他的任务是确定潜伏在溺水洞穴中的邪教徒和纳迦的真实实力与意图。",al={"谁是塞尔瑞德","塞尔瑞德背景故事","失踪的侦察兵塞尔瑞德"}},{q="在哪里可以找到塞尔瑞德？",a="银月守卫塞尔瑞德已经成功潜入了位于灰谷佐拉姆海岸的黑暗深渊的地下深处，但他目前仍被困在洞穴深处等待增援。",al={"塞尔瑞德位置","塞尔瑞德在哪里","在黑暗深渊找到塞尔瑞德"}},{q="找到塞尔瑞德之后会发生什么？",a="在被找到后，塞尔瑞德会揭露废墟中正在进行的仪式的阴险本质，并立即引导冒险者在任务“黑暗深渊的邪恶”中对邪教领袖发动打击。",al={"what comes next","塞尔瑞德的后续","塞尔瑞德之后的下一个任务"}},{q="部落玩家可以接受这个任务吗？",a="该任务由达纳苏斯的哨兵山德拉斯发布，主要面向联盟冒险者。如果部落冒险者能找到他，也可以接受该任务。",al={"部落寻找塞尔瑞德","部落可以做这个任务吗","部落塞尔瑞德"}}},fp="21,195,17.375.0,17.337.0,55.207.0,29.200.0,29.182.0,28.165.0,36.143.1,36.148.0"}
P.entries["quest:1199"] = {n="暮光之锤的末日",s="达纳苏斯的银月守卫玛纳杜斯号召联盟勇士们向聚集在黑暗深渊内的暮光之锤教徒发起进攻。这个邪恶的教派已与蛇形纳迦结盟，占据了这座位于灰谷海岸的沉没的暗夜精灵神庙。勇士们通过从被击败的教徒身上收集坠饰，将能重创他们唤醒远古邪恶的阴险计划。",h="达纳苏斯的银月守卫玛纳杜斯号召联盟勇士们向聚集在黑暗深渊内的暮光之锤教徒发起进攻。这个邪恶的教派已与蛇形纳迦结盟，占据了这座位于灰谷海岸的沉没的暗夜精灵神庙。勇士们通过从被击败的教徒身上收集坠饰，将能重创他们唤醒远古邪恶...",kw={"银色黎明","银月守卫玛纳杜斯","灰谷","黑暗深渊","达纳苏斯","玛纳杜斯","纳迦","古神","暮光坠饰","暮光之锤"},ang={["class:Paladin"]="作为效忠于银色黎明等组织的圣光勇士，圣骑士们认为暮光之锤那堕落的古神崇拜是一种需要通过正义来净化的邪恶。",["class:Priest"]="牧师们能够敏锐地感知到神庙中那曾经神圣的月井所遭受的亵渎，以及驱使教徒陷入更深疯狂的那种令人发狂的阴暗低语。",["faction:Alliance"]="暮光之锤在黑海岸南部的威胁日益严重，因此铲除黑暗深渊对于保卫卡利姆多北部至关重要。",["race:NightElf"]="古神教徒和纳迦对神圣神庙和月井的亵渎，是对艾露恩和灰谷先祖之地的直接侮辱。"},sec={{t="玷污的圣殿",b="在灰谷佐拉姆海岸崎岖的悬崖之下，沉睡着黑暗深渊的遗迹。它曾是一座供奉艾露恩的宏伟暗夜精灵神庙，也是一座强大月井的所在地，但在大分裂时期，神庙崩塌并沉入了深海。如今，神圣的泉水已变得腐臭不堪，这里到处都是嗜血的纳迦和狂热的教徒，他们崇拜着比海洋更加黑暗的力量。"},{t="古神的低语",b="暮光之锤是一个崇拜混乱古神的末日教派，他们企图迎回自己那原始的主人，让世界陷入疯狂与毁灭。传回达纳苏斯的消息证实，这些疯子已经与盘踞在黑暗深渊的纳迦联手。在淹没的大厅深处，他们举行着亵渎的仪式，利用沉没神庙中被腐蚀的泉水来滋养他们黑暗主人的复苏。"},{t="银色黎明的警戒",b="驻扎在达纳苏斯的银月守卫玛纳杜斯代表了银色黎明对威胁艾泽拉斯的所有天灾的警惕。该组织认识到，黑暗深渊中的堕落可能会给所有文明种族带来恐怖的灾难，因此向任何愿意深入这座淹没的迷宫、铲除教徒并夺取暮光坠饰作为击杀证明的英雄们提供认可与援助。"}},faq={{q="银月守卫玛纳杜斯是谁？",a="银月守卫玛纳杜斯是驻扎在达纳苏斯的银色黎明特使。作为其组织在卡利姆多的耳目，他时刻监视着威胁该地区的邪恶教派与黑暗力量，并招募冒险者将其铲除。",al={"玛纳杜斯","暮光坠饰任务发布者","银月守卫玛纳杜斯位置"}},{q="为什么银色黎明关心黑暗深渊？",a="虽然银色黎明因在洛丹伦对抗天灾军团而闻名，但其宗旨包括对抗任何存在性的、非自然的邪恶。在卡利姆多，如果放任古神崇拜的复苏以及教徒与纳迦之间的结盟，将会导致一场全球性的灾难。",al={"为什么银色黎明在达纳苏斯","银色黎明黑暗深渊"}},{q="什么是暮光之锤？",a="暮光之锤是一个狂热的末日教派，他们崇拜古神——那些很久以前被囚禁在地底深处的混乱的原始实体。教徒们坚信，通过加速末日的到来，他们那阴暗的主人将会重返世间，用恐怖与疯狂重塑世界。",al={"暮光之锤教派","暮光之锤是谁","暮光之锤"}},{q="暮光坠饰有什么用？",a="暮光坠饰是暮光之锤成员佩戴的黑暗护符。它象征着他们对所崇拜的混乱实体的效忠，银色黎明收集这些坠饰作为教徒已被击杀并清除的可靠证明。",al={"暮光坠饰背景","暮光坠饰是什么"}},{q="黑暗深渊最初是什么？",a="在遭到腐蚀之前，黑暗深渊曾是一座供奉月亮女神艾露恩的宏伟暗夜精灵神庙。在大分裂导致地壳断裂、神庙沉入海底之前，它曾因拥有一口效力强大的月井而闻名。",al={"黑暗深渊历史","黑暗深渊神庙历史","黑暗深渊月井"}},{q="为什么暮光之锤要与纳迦合作？",a="他们结合的原因尚不完全清楚，但双方都被沉没神庙中涌动的黑暗力量所吸引。在黑暗深渊内部，他们的合作使教徒能够安全地进入古老的淹没密室，而纳迦则从该教派邪恶的法术和献祭仪式中获益。",al={"纳迦与教徒结盟","黑暗深渊纳迦结盟"}}},fp="14,246,17.326.0,24.330.0,28.363.0,28.170.0,57.231.0,30.242.0,41.210.0,38.170.0,52.245.0"}
P.entries["quest:12"] = {n="西部荒野人民军",s="这个任务标志着你在哨兵岭格里安·斯托曼麾下进行的第一次正式考验，以证明你有资格加入人民民兵。随着暴风城的王座陷入混乱且军队缺席，当地志愿者们拿起了武器，保卫西部荒野抵御肆无忌惮的迪菲亚潜行者。你最初的任务是前往北部的田野和矿洞，剿灭那些扼杀当地农场的法外之徒。",h="这个任务标志着你在哨兵岭格里安·斯托曼麾下进行的第一次正式考验，以证明你有资格加入人民民兵。随着暴风城的王座陷入混乱且军队缺席，当地志愿者们拿起了武器，保卫西部荒野抵御肆无忌惮的迪菲亚潜行者。你最初的任务是前往北部的田野...",kw={"迪菲亚走私者","迪菲亚捕猎者","法布隆","格里安·斯托曼","詹戈洛德","摩尔森农场","人民民兵","哨兵岭","西部荒野"},ang={["class:Paladin"]="服务于人民民兵体现了圣骑士的核心使命：为手无寸铁之人提供保护，并对那些剥削弱者的不法之徒施以正义的审判。",["faction:Alliance"]="这项任务揭示了王国内部鲜明的割裂：当暴风城的贵族们依然躲在首都的高墙内安享太平时，联盟的冒险者们必须与普通定居者并肩作战，以保护西部荒野免于毁灭。",["race:Human"]="对于王国的人类来说，西部荒野的困境令人感同身受，因为工薪家庭和世代相传的农场正沦为强盗的受害者，而皇家权威却对此视而不见。"},sec={{t="和平的代价",b="西部荒野曾是暴风城肥沃的粮仓，但如今却被法外之徒、流浪汉和窃贼所占据。由于首都拒绝派遣皇家士兵前往乡村巡逻，格里安·斯托曼组建了人民民兵，作为一支基于哨兵岭的、绝望的本土防御力量。在斯托曼看来，收复该地区需要采取果断行动，任何希望佩戴民兵徽章的人都必须证明自己既具备战斗素养，又对保护无辜定居者有着绝对的忠诚。"},{t="清理粮仓",b="在新兵获得信任去执行更深入的战术行动之前，他们会被派去打击侵犯北部家园的迪菲亚势力。迪菲亚捕猎者和走私者在詹戈洛德矿洞、摩尔森农场和法布隆南瓜农场附近公开活动，掠夺物资并伏击过往旅客。通过铲除这些不法之徒，未来的民兵战士不仅干扰了窃贼前线的掠夺行为，同时也向斯托曼的侦察兵证明，他们拥有进行长期打击犯罪斗争所需的勇气。"}},faq={{q="什么是人民民兵？",a="人民民兵是由格里安·斯托曼组织并驻扎在哨兵岭的一支志愿军。他们由当地的农民、退伍军人和普通百姓组成，保卫西部荒野免受迪菲亚潜行者的侵害，因为暴风城的皇家军队拒绝或未能派遣驻军前往该地区。",al={"人民民兵","谁是民兵","什么是人民民兵"}},{q="为什么暴风城不派遣皇家军队？",a="随着瓦里安·乌瑞恩国王失踪，暴风城的贵族议会和领袖层将王国资源集中在其他地方，使得像西部荒野这样的偏远农村地区只能独自面对日益猖獗的强盗团伙。",al={"军队在哪里","为什么西部荒野没有卫兵","暴风城驻军"}},{q="我在哪里可以找到迪菲亚捕猎者和走私者？",a="他们在西部荒野北部活动频繁，特别是在法布隆南瓜农场、摩尔森农场周围，以及詹戈洛德矿洞入口附近。",al={"捕猎者位置","走私者位置","捕猎者在哪里"}},{q="谁是格里安·斯托曼？",a="格里安·斯托曼是一位经验丰富的退伍军人，也是驻扎在哨兵岭的人民民兵的指挥官。他致力于保卫西部荒野的定居者，召集志愿者驱逐迪菲亚潜行者，恢复乡村的秩序。",al={"谁是斯托曼","格里安·斯托曼背景故事","民兵领袖"}},{q="这个任务会带来更多民兵指派任务吗？",a="是的。这项任务仅仅是入门试炼。成功的志愿者将被指派后续任务，目标是散布在西部荒野平原上、等级越来越危险的迪菲亚潜行者骨干。",al={"这是一个系列任务吗","下一个任务","民兵任务线"}},{q="法布隆南瓜农场发生了什么？",a="当迪菲亚潜行者控制了农田后，法布隆一家被迫离开了他们的家园，任由不法之徒和拾荒者掠夺田地并恐吓北部道路。",al={"法布隆农场","法布隆一家怎么了","南瓜农场"}}},fp="20,267,18.396.0,24.414.0,29.278.0,43.238.0,47.152.0,25.216.0,49.167.0,45.179.0"}
P.entries["quest:120"] = {n="送往暴风城的信",s="湖畔镇的所罗门镇长急需军事援助，因为豺狼人和黑石兽人已经包围了小镇。由于无法抽出守卫部队，他派遣一名冒险者将“湖畔镇的现状”直接送交暴风城的马库斯·乔纳森将军。",h="湖畔镇的所罗门镇长急需军事援助，因为豺狼人和黑石兽人已经包围了小镇。由于无法抽出守卫部队，他派遣一名冒险者将“湖畔镇的现状”直接送交暴风城的马库斯·乔纳森将军。",kw={"马库斯·乔纳森将军","湖畔镇","所罗门镇长","前往暴风城的信使","赤脊山","援军","暴风城军队","湖畔镇的现状"},ang={["class:Paladin"]="将绝望者的呼声传达给被宫廷政治所束缚的领导者，是对责任、保护和正义行动等核心美德的考验。",["faction:Alliance"]="这项任务揭示了繁荣的首都与在王国边缘为生存而战、却被忽视的边境定居点之间日益紧张的关系。",["race:Human"]="赤脊山是暴风城的祖传领地；看到同胞因官僚主义的繁文缛节而被遗弃，这令王国的所有爱国者都感到心痛。"},sec={{t="跨越群山的呼声",b="湖畔镇正处于崩溃的边缘。成群的豺狼人封锁了每一条道路，黑石兽人从北方发动突袭，当地守卫已疲于奔命。所罗门镇长无法抽调战斗人员进行长达数日的长途跋涉前往首都，只能委托一名独立旅行者将他请求正规军援助的正式文书送到城门口。"},{t="官僚主义与High Seat",b="递交镇长的报告让冒险者得以面对面见到暴风城防卫指挥官马库斯·乔纳森将军。虽然乔纳森尊重所罗门的领导能力并认可形势的紧迫性，但军队章程禁止他在没有王室指令的情况下擅自调动部队。赤脊山的防卫必须等待与年轻的安度因国王和摄政议会进行正式商议后才能决定。"}},faq={{q="为什么所罗门镇长需要信使？",a="湖畔镇正遭受黑石兽人和豺狼人的持续围攻。每一名当地守卫都被需要用来保卫城镇和坚守大桥，因此所罗门只能委托路过的冒险者代为传递他急需援助的请求。",al={"为什么派我去","为什么要用信使","所罗门的信使"}},{q="“湖畔镇的现状”报告里写了什么？",a="这是一份关于赤脊山所面临危机的正式报告，详细列出了不断增加的敌军数量、伤亡情况，以及如果首都再不派遣正规军，小镇即将陷落的事实。",al={"湖畔镇的现状","所罗门的报告","信里写了什么"}},{q="马库斯·乔纳森将军是谁？",a="马库斯·乔纳森将军是暴风城卫队的指挥官，也是暴风城军队内的高级将领。他负责监督城门防务，并直接向伯瓦尔·弗塔根公爵和王室汇报。",al={"马库斯·乔纳森","将军是谁","暴风城将军"}},{q="为什么乔纳森将军不立刻派遣士兵？",a="乔纳森将军无权自行调动军队。他必须将所罗门的报告呈交给国王和摄政议会，获得正式的王室授权后，部队才能开拔。",al={"为什么没有部队","援军在哪里","乔纳森的回复"}},{q="湖畔镇和暴风城之间的道路安全吗？",a="不安全。穿过赤脊山前往艾尔文森林的道路上，充斥着极具攻击性的豺狼人部落和迪菲亚强盗，对于孤身一人的信使来说，这段旅程非常危险。",al={"前往暴风城的道路","安全旅行","赤脊山道路"}},{q="暴风城最终派出了援军吗？",a="首都内部的政治惰性和动荡延误了军队的任何实质性响应，使得湖畔镇及其镇长几乎只能完全依靠雇佣兵和志愿者。",al={"援军会来吗","给湖畔镇的援助"}}},fp="22,279,26.301.0,29.331.0,45.192.0,43.203.0,31.201.0,54.183.0,49.148.0,35.173.1"}
P.entries["quest:1200"] = {n="黑暗深渊中的恶魔",s="“黑暗深渊的罪行”是一项由银月守卫塞尔瑞德在黑暗深渊的地下遗迹深处指派给联盟的任务。为了阻止助长远古恐惧的恐怖祭祀，英雄们受命除掉邪教领袖梦游者克尔里斯，并将证明带回达纳苏斯的银色黎明。",h="“黑暗深渊的罪行”是一项由银月守卫塞尔瑞德在黑暗深渊的地下遗迹深处指派给联盟的任务。为了阻止助长远古恐惧的恐怖祭祀，英雄们受命除掉邪教领袖梦游者克尔里斯，并将证明带回达纳苏斯的银色黎明。",kw={"阿库麦尔","银色黎明","黑暗深渊","达纳苏斯","深渊","艾露恩","克尔里斯","月亮井","塞尔高姆","塞尔瑞德","暮光之锤"},ang={["class:Paladin"]="响应银色黎明的号召，去消灭一个将无辜者献祭给原始恐惧的邪教徒，这正是神圣复仇的定义。",["class:Priest"]="阻止克尔里斯，终结了对那些曾经因敬神而神圣的水域所进行的亵渎行径。",["faction:Alliance"]="通过协助银色黎明对抗克尔里斯，联盟有助于保护灰谷脆弱的边界免受阴险的邪教渗透。",["race:NightElf"]="为亵渎古老的艾露恩神庙复仇，并净化其受毒害的月亮井，是对卡多雷遗产的直接捍卫。"},sec={{t="污秽的圣所",b="如今被称为黑暗深渊的被淹没洞穴，曾是一座祭祀艾露恩的原始地下神庙。当古神腐化的力量渗入岩石，污染了神庙的月亮井，并释放出原始黑暗的贪婪仆从——阿库麦尔，那神圣的过去便支离破碎了。在这场亵渎发生后，暮光之锤教派与当地的娜迦结成了邪恶的同盟，将神圣的大厅变成了进行祭祀谋杀的巢穴。"},{t="阵亡守卫的恳求",b="银月守卫塞尔瑞德代表他的组织冒险深入黑暗深渊，却身受重伤，力量流失殆尽。困在敌人包围中的塞尔瑞德意识到他无法独自完成任务。他恳求任何到达此地的勇敢联盟旅者，去击杀梦游者克尔里斯。这个阴险的邪教徒为了获得黑暗力量，正在策划将无辜者献祭给阿库麦尔。"},{t="达纳苏斯的正义",b="将克尔里斯的头颅交给达纳苏斯工匠区的哨兵塞尔高姆，终于结束了一场漫长而令人不安的搜捕。银色黎明曾担心克尔里斯已经死亡或迷失在阴影中，因为每当卡利姆多有黑暗势力蠢蠢欲动，总能发现他的身影。除掉他对于挫败邪教在灰谷的图谋是一场至关重要的胜利。"}},faq={{q="银月守卫塞尔瑞德是谁？",a="塞尔瑞德是银色黎明的一名特工，被派往调查黑暗深渊中日益增长的阴影。他在深处受了重伤，力量耗尽，迫使他招募路过的冒险者去阻止克尔里斯。",al={"塞尔瑞德是谁","塞尔瑞德背景故事","银月守卫"}},{q="为什么要针对梦游者克尔里斯？",a="克尔里斯是居住在黑暗深渊中的暮光之锤邪教徒的首领。他一直在系统地将无辜的俘虏献祭给阿库麦尔，这是一种与古神有关的邪恶野兽，以此来换取邪恶的力量。",al={"克尔里斯是谁","为什么要杀克尔里斯","梦游者克尔里斯"}},{q="哨兵塞尔高姆是谁？",a="哨兵塞尔高姆是驻扎在达纳苏斯工匠区的银色黎明代表。他负责监督该组织在整个卡利姆多北部阻止腐化蔓延的行动。",al={"塞尔高姆 达纳苏斯","塞尔高姆是谁","银色黎明 达纳苏斯"}},{q="黑暗深渊的历史是什么？",a="在成为怪物和邪教徒的巢穴之前，这些洞穴曾是一座祭祀女神艾露恩的宏伟暗夜精灵神庙。在一位古神的恶意渗入并污染了其神圣的月亮井之后，它便沦为了废墟。",al={"黑暗深渊历史","黑暗深渊以前是什么","黑暗深渊艾露恩神庙"}},{q="阿库麦尔是谁？",a="阿库麦尔是一头怪物般的九头蛇状古神仆从，从黑暗深渊下方的污秽水域中爬出。暮光之锤尊崇这种生物，通过向它献祭俘虏来获取黑暗的祝福。",al={"什么是阿库麦尔","阿库麦尔背景故事","阿库麦尔野兽"}},{q="暮光之锤和娜迦为什么要合作？",a="他们结盟的具体原因尚不完全清楚，但在黑暗深渊中，他们联合起来占据了神庙遗址，而邪教徒则向阿库麦尔提供祭品。",al={"娜迦邪教徒联盟","为什么娜迦在黑暗深渊","暮光之锤和娜迦"}}},fp="20,239,19.327.0,23.358.0,20.366.1,29.209.0,43.180.0,27.192.0,41.201.0,15.200.0,56.215.0"}
P.entries["quest:1201"] = {n="塞拉摩间谍",s="部落与联盟之间的停战协定十分脆弱，双方都在进行着小规模冲突和秘密行动。蕨墙村的纳泽尔·血矛想要彻底铲除村庄东面的联盟渗透者。",h="部落与联盟之间的停战协定十分脆弱，双方都在进行着小规模冲突和秘密行动。蕨墙村的纳泽尔·血矛想要彻底铲除村庄东面的联盟渗透者。",kw={"蕨墙村","尘泥沼泽","渗透者","纳泽尔·血矛","间谍","塞拉摩"},sec={{t="村庄东面的间谍",b="联盟的渗透者已经在蕨墙村东面扎下了根，监视着这里并将部落的动向报告给塞拉摩。当地的间谍大师纳泽尔·血矛绝不容忍这种行为。你被派去找到这些渗透者并将他们除掉，让他们的上司知道这里不欢迎这样的间谍。"}},faq={{q="是谁下令杀死塞拉摩的渗透者的？",a="蕨墙村的当地间谍大师纳泽尔·血矛。",al={"谁发布了塞拉摩间谍任务","纳泽尔·血矛间谍任务","谁发起了塞拉摩间谍任务"}},{q="渗透者藏在哪里？",a="在蕨墙村东面的岛屿上。",al={"塞拉摩渗透者位置","在哪里寻找塞拉摩间谍","尘泥沼泽的渗透者位置"}},{q="为什么间谍要监视蕨墙村？",a="他们监视这个村庄并将部落的动向传回塞拉摩。",al={"为什么人类在监视蕨墙村","蕨墙村间谍动机"}},{q="处理完这些间谍后接下来要做什么？",a="故事的下一步是“塞拉摩码头”。",al={"塞拉摩间谍任务后续","塞拉摩间谍任务之后是什么任务"}}},fp="15,217,25.298.0,51.61.0,34.44.0,47.74.0,40.50.0"}
P.entries["quest:1202"] = {n="塞拉摩码头",s="两名间谍被派往塞拉摩的一艘船上窃取文件，但被发现后不得不将文件扔进海里。现在，纳泽尔·血矛委托你去找到它们。",h="两名间谍被派往塞拉摩的一艘船上窃取文件，但被发现后不得不将文件扔进海里。现在，纳泽尔·血矛委托你去找到它们。",kw={"蕨墙村","指挥官的文件","码头","尘泥沼泽","搁脚箱","纳泽尔·血矛","间谍","塞拉摩"},sec={{t="水中的文件",b="在你处理了那些塞拉摩间谍之后，纳泽尔·血矛又有事情要交给你。两名间谍被派往塞拉摩码头，从一艘船上窃取文件。他们得手后被发现，不得不将战利品扔进了海里。其中一人逃脱了，但没能找回文件，只能回来报告这次失败的任务。"},{t="码头之下",b="这些文件被装在一个搁脚箱里，就在塞拉摩码头附近的水下。你被派去找到指挥官的文件，并将其带给蕨墙村的纳泽尔·血矛。纳泽尔说，这些文件对联盟的稳定至关重要，因此也关系到部落的安全。"}},faq={{q="谁派你去塞拉摩岛？",a="蕨墙村的纳泽尔·血矛。",al={"任务发布者","任务起始地点"}},{q="你在码头下面找什么？",a="一个位于塞拉摩码头水下的搁脚箱，里面装着指挥官的文件。",al={"寻找目标","水中的物品","码头任务目标"}},{q="为什么文件被扔进了水里？",a="两名间谍从码头的一艘船上窃取了这些文件，但被发现后不得不将它们扔进海里。其中一人在没拿到文件的情况下逃脱了。",al={"文件为何在海里","搁脚箱为何在此","间谍为何丢弃它"}},{q="为什么部落想要这些文件？",a="纳泽尔·血矛说，这些文件对联盟的稳定至关重要，因此也关系到部落的安全。",al={"文件为何重要","文件内容","血矛为何需要文件"}},{q="剧情故事中这之前发生了什么？",a="这是在《塞拉摩间谍》之后发生的，在那个任务中，你在蕨墙村以东搜寻渗透者。",al={"前置任务","前序任务","任务线索"}}},fp="19,173,19.316.0,17.282.0,32.41.0,43.88.0,45.138.0,40.107.0,40.93.0"}
P.entries["quest:1203"] = {n="加尔的剑",s="“沼泽之眼”加尔在尘泥沼泽有些东西要砍，却不肯说是什么。加尔想要一把特定的利刃，一把月钢阔剑，并且警告你不要拖延。",h="“沼泽之眼”加尔在尘泥沼泽有些东西要砍，却不肯说是什么。加尔想要一把特定的利刃，一把月钢阔剑，并且警告你不要拖延。",kw={"尘泥沼泽","加尔","月钢阔剑","沼泽之眼加尔","挥砍之刃"},sec={{t="一把特定的利刃",b="“沼泽之眼”加尔有些东西要砍，但不能说要砍什么。加尔需要一把特别的利刃，有些人称之为月钢阔剑，而加尔称之为挥砍之刃。你也许能在镇上找到一把，或者找个铁匠专门打造一把。加尔警告你不要拖延，因为要砍的东西不会永远留着。"}},faq={{q="是谁在索要这把利刃？",a="“沼泽之眼”加尔，他在尘泥沼泽。",al={"谁发布了加尔的利刃任务","加尔是谁","沼泽之眼加尔"}},{q="加尔需要什么武器？",a="一把月钢阔剑，加尔称之为挥砍之刃。",al={"加尔想要什么剑","加尔的武器","加尔需要哪种利刃"}},{q="为什么加尔如此急需一把利刃？",a="加尔有些东西要砍，不能透露要砍什么，并警告说那东西不会永远留着。",al={"为什么加尔需要利刃","加尔要砍什么","加尔的目的"}},{q="加尔建议在哪里找到这把剑？",a="加尔说你也许能在镇上找到，或者找个能为你专门打造的铁匠。",al={"如何为加尔获取月钢阔剑","在哪里为加尔寻找利刃"}}},fp="18,164,15.319.0,28.51.0,30.55.0,39.94.0,42.86.0"}
P.entries["quest:1204"] = {n="泥石龟蟹汤",s="在塞拉摩，摩根·斯特恩正在研究一道名为“泥石汤与虫子”的菜肴，这道菜或许会成为暴风城各大旅店里的招牌菜。摩根·斯特恩担心自己无法活着穿过尘泥沼泽，因此请求你帮他收集泥石龟的舌头。",h="在塞拉摩，摩根·斯特恩正在研究一道名为“泥石汤与虫子”的菜肴，这道菜或许会成为暴风城各大旅店里的招牌菜。摩根·斯特恩担心自己无法活着穿过尘泥沼泽，因此请求你帮他收集泥石龟的舌头。",kw={"蓝隐士旅店","虫子","尘泥沼泽","分叉的舌头","摩根·斯特恩","泥石龟","汤","塞拉摩"},sec={{t="烹饪中的菜肴",b="摩根·斯特恩正在研制一道名为“泥石汤与虫子”的菜，但还缺少主要的配料。穿越尘泥沼泽的长途跋涉对他来说太危险了，所以他请求你帮忙去打猎。首先需要的是泥石龟的舌头。"},{t="分叉的舌头",b="泥石龟在海岸附近徘徊，主要是在海湾周围。摩根·斯特恩想要的不是普通的舌头。有传言说，有些泥石龟长着分叉的舌头，那种舌头有一种独特的风味，正是这道菜所需要的。"},{t="端上餐桌",b="摩根·斯特恩将尝试不同的烹饪方法，寻找最能发挥这些舌头美味的做法。他希望这道菜能最终在暴风城的蓝隐士旅店端上餐桌。"}},faq={{q="谁想要这些海龟舌头？",a="塞拉摩的摩根·斯特恩，他正在研究一道名为“泥石汤与虫子”的菜。",al={"谁发布了泥石汤与虫子任务","塞拉摩的摩根·斯特恩"}},{q="哪里可以找到泥石龟？",a="在尘泥沼泽的海岸边，主要是在海湾附近。",al={"泥石龟位置","泥石龟在哪里"}},{q="为什么摩根·斯特恩特别想要分叉的舌头？",a="摩根·斯特恩听说那种舌头带有独特的风味，他想把这种风味用到菜里。",al={"为什么要分叉的舌头","泥石龟分叉舌头的原因"}},{q="为什么摩根·斯特恩不亲自去收集食材？",a="摩根·斯特恩觉得他无法活着走完穿越尘泥沼泽的长途跋涉。",al={"为什么摩根·斯特恩不去打猎","摩根·斯特恩沼泽"}},{q="这个任务之后是什么？",a="下一步的任务叫做……与虫子。",al={"泥石汤之后的任务","泥石汤后续任务"}}},fp="21,279,20.265.0,14.216.0,16.178.1,37.82.0,39.59.0,55.87.0,56.84.0,28.37.0"}
P.entries["quest:1205"] = {n="死沼巨鳄",s="Deadmire是雷霆崖猎人高地的牛头人猎人梅洛·石蹄所提供的一项狩猎试炼。该任务派遣猎人前往东方的尘泥沼泽，追踪并击杀一只饱受折磨的古老鳄鱼Deadmire，并带回它的牙齿作为证明。这是一项既具挑战性，又考验猎人仁慈之道的练习。",h="Deadmire是雷霆崖猎人高地的牛头人猎人梅洛·石蹄所提供的一项狩猎试炼。该任务派遣猎人前往东方的尘泥沼泽，追踪并击杀一只饱受折磨的古老鳄鱼Deadmire，并带回它的牙齿作为证明。这是一项既具挑战性，又考验猎人仁慈之...",kw={"鳄鱼","deadmire","尘泥沼泽","猎人高地","梅洛·石蹄","石槌废墟","雷霆崖"},ang={["class:Hunter"]="对猎人而言，追踪Deadmire体现了武力与精神责任之间的平衡，强调了一次光荣的击杀也可以是一种恩典的行为。",["faction:Horde"]="为雷霆崖的长者进行狩猎，有助于将部落的旅行者与这片土地以及他们牛头人盟友的精神传统联系起来。",["race:Tauren"]="这次狩猎反映了牛头人与大地母亲的生物和谐相处的核心价值观，教导人们真正的猎人应尊重猎物，并敬畏自然的生命轮回。"},sec={{t="仁慈的狩猎",b="在雷霆崖的猎人高地，梅洛·石蹄教导有前途的追踪者狩猎中更深层的精神传统。与盲目的屠杀或搜集战利品不同，牛头人的狩猎哲学教导人们要敬畏自然世界并与其建立联系。梅洛指派猎人们远赴东方的尘泥沼泽阴暗湿地，寻找Deadmire，那是一只体型巨大的古老鳄鱼，它漫长的生命已成为一种痛苦的负担。"},{t="沼泽古兽",b="Deadmire并非寻常野兽；它是一只巨大的苍白鳄鱼，游荡在石槌废墟北部的水道中。虽然它年轻时的狂怒和体能偶尔会爆发出来，但它衰老的躯体已因磨损的骨骼和持续不断的痛苦而疲惫不堪。梅洛要求猎人们赐予这头野兽光荣而迅速的解脱，使其灵魂得到安息，并取下一颗牙齿作为野兽获得解脱的凭证。"}},faq={{q="谁是Deadmire？",a="Deadmire是一只生活在尘泥沼泽湿地中的巨大古老白鳄。尽管它仍然具有危险的力量，但由于衰老和虚弱的身体，它正遭受着剧烈的生理痛苦。",al={"什么是deadmire","deadmire背景故事","这只鳄鱼是谁"}},{q="为什么梅洛·石蹄想要杀死Deadmire？",a="梅洛将这次狩猎视为一种仁慈的行为，而非征服。Deadmire衰老的骨骼带给它疯狂的痛苦，这位牛头人猎人相信，释放这头高贵野兽的灵魂并让它获得安宁是一项神圣的职责。",al={"为什么要杀死deadmire","梅洛·石蹄的动机","deadmire狩猎的目的"}},{q="在哪里可以找到Deadmire？",a="Deadmire出没于尘泥沼泽的阴暗水域和岛屿中，通常能在石槌废墟以北的河道附近找到它。",al={"deadmire在哪里","deadmire位置","寻找deadmire"}},{q="梅洛要求狩猎提供什么证明？",a="梅洛要求你带回死沼巨鳄的牙齿，以证明这头强大生物的苦难终于结束了。",al={"deadmire任务物品","梅洛想要什么","deadmire证明"}},{q="这次狩猎教会了有抱负的猎人什么？",a="狩猎教会了人们，猎人之道并非盲目的杀戮，而是与自然的精神交流。这一使命的一部分在于识别生物的生命何时已转化为痛苦，并给予其仁慈、光荣的死亡。",al={"猎人哲学","牛头人狩猎课程","狩猎的意义"}},{q="谁发布了这个任务？",a="该任务由梅洛·石蹄发布，他是一位牛头人猎人，位于俯瞰雷霆崖城市的猎人高地。",al={"deadmire任务发布者","谁开启了deadmire任务","梅洛·石蹄的位置"}}},fp="8,249,15.322.0,24.316.0,16.157.0,46.173.0,28.79.0,44.74.0,43.152.0,21.82.0"}
P.entries["quest:1206"] = {n="加尔和蜘蛛眼",s="位于水光庄园的“沼泽之眼”加尔需要40颗未破损的黑雾之眼，因为黑雾之眼的汁液口感顺滑且咸鲜。这种蜘蛛生活在庄园西边的黑雾洞穴中。",h="位于水光庄园的“沼泽之眼”加尔需要40颗未破损的黑雾之眼，因为黑雾之眼的汁液口感顺滑且咸鲜。这种蜘蛛生活在庄园西边的黑雾洞穴中。",kw={"黑雾","黑雾洞穴","尘泥沼泽","加尔","蜘蛛眼","沼泽之眼加尔","水光庄园"},sec={{t="对蜘蛛眼的嗜好",b="继“舒缓香料”之后，加尔转而追求眼球汁液，这是一种适合饮用的饮品。大多数生物只有一双眼睛，而蜘蛛却拥有许多只，加尔觉得黑雾蜘蛛的眼球汁液非常美味。黑雾蜘蛛生活在庄园西边的黑雾洞穴中，加尔还琢磨着到底是洞穴的名字源自这些蜘蛛，还是反过来。"},{t="加尔的盛宴",b="加尔为眼睛的到来欢呼雀跃，称赞它们非常美味。加尔建议把那些当你盯着它看时也会回盯着你的眼睛留到最后吃，因为在沼泽里它们可以作为陪伴。随后，加尔向这些小眼睛问好，尝了一口，宣布它们吃起来就像粘糊糊的咸味鸡肉。"}},faq={{q="是谁要蜘蛛眼？",a="位于尘泥沼泽水光庄园的“沼泽之眼”加尔要这些眼睛。",al={"谁发布了这个任务","加尔任务发布者","沼泽之眼加尔"}},{q="为什么加尔想要蜘蛛眼？",a="加尔喜欢喝眼球汁液，觉得黑雾之眼的汁液口感顺滑且咸鲜。大多数生物只有两只眼睛，而蜘蛛却有很多只。",al={"为什么需要蜘蛛眼","加尔用眼睛做什么","眼球汁液"}},{q="黑雾蜘蛛在哪里？",a="加尔说黑雾蜘蛛在水光庄园以西的黑雾洞穴里。",al={"黑雾洞穴位置","黑雾蜘蛛在哪里","去哪里找眼睛"}},{q="加尔要多少只眼睛？",a="加尔要40颗未破损的黑雾之眼。",al={"需要多少眼睛","眼睛数量"}},{q="这个任务的前置是什么？",a="前置任务是“舒缓香料”。",al={"前置任务","先决条件","什么任务开启这个任务"}}},fp="15,173,23.343.0,16.276.1,29.72.0,31.147.0,31.85.0,29.37.0,23.27.0"}
P.entries["quest:121"] = {n="送往暴风城的信",s="“前往暴风城的信使”这一任务见证了你带着马库斯·乔纳森将军的初步回复返回湖畔镇，交给所罗门镇长。该镇正饱受黑石兽人袭击和豺狼人入侵的蹂躏，但首都的回应并没有带来军队，反而让人感到心寒。这凸显了王国中心日益严重的政治瘫痪。",h="“前往暴风城的信使”这一任务见证了你带着马库斯·乔纳森将军的初步回复返回湖畔镇，交给所罗门镇长。该镇正饱受黑石兽人袭击和豺狼人入侵的蹂躏，但首都的回应并没有带来军队，反而让人感到心寒。这凸显了王国中心日益严重的政治瘫痪。",kw={"黑石兽人","伯瓦尔","湖畔镇","所罗门镇长","马库斯·乔纳森","前往暴风城的信使","赤脊山","暴风城"},ang={["faction:Alliance"]="这次通讯的停滞说明了联盟核心王国的脆弱性，内部的政治僵局导致人类领地在面对区域威胁时缺乏防卫。",["race:Human"]="对于王国的人类来说，传递这些信件揭示了暴风城受保护的安逸与艾尔文森林周边地区日益崩塌的边界之间那令人痛苦的隔阂。"},sec={{t="寄往湖畔镇的快报",b="你已将所罗门镇长那份迫切的增援请求直接送到了暴风城的马库斯·乔纳森将军手中，随后又立即被派回赤脊山。将军在没有获得王室批准的情况下无法调动军队，因此他让你带着一封初步的回信先行返回，而他自己则在等待王座厅的消息。对于湖畔镇饱受煎熬的居民来说，每一天没有城市卫兵的到来，他们的定居点就向着彻底沦陷在黑石氏族的铁蹄之下更近了一步。"},{t="王国中的不安",b="当所罗门镇长读到乔纳森的回复时，他所期待的慰藉并没有出现。信中没有提到承诺的营队会沿着艾尔文森林边界向东行进，取而代之的是推诿的官僚辞令。所罗门立刻感觉到王室内部出了大问题。随着瓦里安·乌瑞恩国王离奇失踪，摄政会议陷入僵局，像湖畔镇这样的边远城镇正越来越多地被迫自生自灭。"}},faq={{q="马库斯·乔纳森将军的回复中说了什么？",a="马库斯·乔纳森将军的信中解释说，没有国王或王室的正式授权，他无法部署暴风城军队。他没有提供增援，只是保证此事已上报给王室，同时湖畔镇只能被迫等待。",al={"信中说了什么","将军的回复","马库斯·乔纳森的信"}},{q="为什么暴风城不能直接派士兵去赤脊山？",a="由于瓦里安·乌瑞恩国王失踪，执政决策由年轻的安度因国王、摄政王伯瓦尔·弗塔根和贵族议会共同掌握。首都内部的政治分歧和拖延束缚了军队的手脚，使得指挥官马库斯·乔纳森将军在没有王室批准的情况下无法出兵。",al={"为什么没有暴风城的帮助","为什么暴风城不帮湖畔镇","暴风城在赤脊山的军队"}},{q="谁是所罗门镇长？",a="所罗门镇长是湖畔镇和赤脊山的市政领袖。他负责管理该定居点，并协调其微薄的防御力量，以抵御黑石兽人、豺狼人和当地的匪徒。",al={"所罗门镇长","谁是所罗门","湖畔镇镇长"}},{q="谁是马库斯·乔纳森将军？",a="马库斯·乔纳森将军是暴风城卫队及首都常备武装力量的最高指挥官。他驻扎在暴风城正门内的英雄谷。",al={"谁是马库斯·乔纳森","乔纳森将军","暴风城将军"}},{q="读完信后，所罗门接下来做了什么？",a="意识到暴风城无法或不愿提供直接帮助后，所罗门试图从周边地区寻求援助，并派你去调查西部荒野的状况。",al={"接下来会发生什么","前往暴风城的信使之后的任务","接下来去哪里"}},{q="为什么所罗门说“我们的王国出了点问题”？",a="所罗门认识到，对于一个正处于围攻之下的关键边境城镇，完全拒绝或拖延提供援助在军事上毫无道理。这让他警觉到暴风城的政治管理层正在内部受到操控或瘫痪。",al={"出了点问题","为什么所罗门很担心","暴风城阴谋"}}},fp="22,222,23.388.0,21.344.1,46.208.0,51.229.0,26.175.0,31.180.0,51.115.1,57.192.0"}
P.entries["quest:1218"] = {n="舒心草",s="“沼泽之眼”加尔热爱沼泽风味的烹饪，他需要一些舒缓香料来炖汤。位于尘泥沼泽的加尔请求你带去三份舒缓香料。",h="“沼泽之眼”加尔热爱沼泽风味的烹饪，他需要一些舒缓香料来炖汤。位于尘泥沼泽的加尔请求你带去三份舒缓香料。",kw={"尘泥沼泽","蛙腿","舒缓香料","炖汤","沼泽之眼加尔"},sec={{t="锅里的香料",b="“沼泽之眼”加尔酷爱沼泽风格的烹饪，炸绿蛙腿就是其中的一道菜。他正计划炖一锅汤，并为此需要一些舒缓香料。无论谁带去香料，都会分到一份汤。加尔想要三份舒缓香料，并想知道你是否喜欢炖汤。"}},faq={{q="谁需要舒缓香料？",a="“沼泽之眼”加尔，他位于尘泥沼泽。",al={"谁提供舒缓香料","舒缓香料任务提供者","沼泽之眼加尔香料"}},{q="“沼泽之眼”加尔打算用这些香料做什么菜？",a="炖汤。加尔很喜欢沼泽烹饪，比如炸绿蛙腿，他打算和你分享这锅炖汤。",al={"加尔制作什么","加尔制作什么炖汤","加尔食物"}},{q="加尔需要多少份香料？",a="加尔需要三份舒缓香料。",al={"多少份舒缓香料","舒缓香料数量","舒缓香料需求"}}},fp="15,147,17.268.0,30.51.0,56.107.0,31.36.0"}
P.entries["quest:1219"] = {n="兽人的报告",s="你在尘泥沼泽松软的泥土中翻找时，发现了一只兽人的断手，手中紧握着一根用骨头雕刻而成的管子。管子里装着一张沾满泥土的羊皮纸，上面写着兽人语，看起来很重要。这东西似乎是给塞拉摩海军上尉的。",h="你在尘泥沼泽松软的泥土中翻找时，发现了一只兽人的断手，手中紧握着一根用骨头雕刻而成的管子。管子里装着一张沾满泥土的羊皮纸，上面写着兽人语，看起来很重要。这东西似乎是给塞拉摩海军上尉的。",kw={"骨头管子","尘泥沼泽","松软泥土","兽人报告","塞拉摩海军上尉"},sec={{t="泥土中的断手",b="在松软的泥土里躺着一只兽人的断手，手里紧抓着一根用骨头雕刻的管子。里面是一张沾满尘土的羊皮纸，上面写着兽人语，这看起来很重要。应该把这东西交给一名塞拉摩海军上尉。"},{t="海军上尉的判断",b="海军上尉承认自己兽人语读得不好，但他还是认定这张羊皮纸是兽人间谍的报告。"}},faq={{q="松软的泥土里藏着什么？",a="翻找泥土会发现一只兽人的断手，手里紧抓着一根用骨头雕刻的管子，里面装着一张沾满泥土的羊皮纸。",al={"在松软泥土中发现什么","松软泥土物品","尘泥沼泽兽人断手"}},{q="谁应该得到这张羊皮纸？",a="一名塞拉摩海军上尉。",al={"把报告交给谁","谁接收间谍报告","塞拉摩海军上尉位置"}},{q="羊皮纸是用什么语言写的？",a="上面写的是兽人语，而且看起来很重要。",al={"羊皮纸语言","我能读懂羊皮纸吗"}}},fp="14,236,18.220.0,24.96.1,33.122.0,29.23.0,42.48.0"}
P.entries["quest:122"] = {n="雏龙的鳞片",s="弗纳·奥斯古需要黑龙幼龙的腹鳞来偿还他欠闪金镇铁匠阿古斯的贸易债务。收集这些材料需要猎杀游荡在湖畔镇南面岩壁上的幼龙。获得这些鳞片不仅能还清弗纳的账目，还能提供足够的生皮来制造一件装备。",h="弗纳·奥斯古需要黑龙幼龙的腹鳞来偿还他欠闪金镇铁匠阿古斯的贸易债务。收集这些材料需要猎杀游荡在湖畔镇南面岩壁上的幼龙。获得这些鳞片不仅能还清弗纳的账目，还能提供足够的生皮来制造一件装备。",kw={"黑龙幼龙","龙军团","闪金镇","湖畔镇","赤脊山","铁匠阿古斯","腹鳞","弗纳·奥斯古"},ang={["faction:Alliance"]="黑龙军团在湖畔镇南面的威胁不断蔓延，这对于已经在赤脊山苦苦支撑、兵力不足的守军来说，无疑是雪上加霜。",["profession:Blacksmithing"]="铁匠阿古斯的要求突显了在常规货币稀缺时，龙鳞这类稀有材料是如何被铁匠们当作高价值的易货工具来使用的。",["race:Human"]="艾尔文森林和赤脊山之间的贸易路线保证了像湖畔镇这样的城镇的物资供应，但边境的工匠往往必须向城里的商人支付高昂的价格。"},sec={{t="边境债务",b="在湖畔镇郊外经营铁匠铺需要稀缺的物资，因此弗纳·奥斯古经常与赤脊山以外的工匠进行贸易。在收到闪金镇铁匠阿古斯寄来的一批马蹄铁后，弗纳发现自己手头的常规货币不足。于是，阿古斯要求用珍贵的龙皮来支付：具体来说，就是该地区筑巢的黑龙幼龙腹部那些柔软且备受推崇的鳞片。如果拿不出这些鳞片，弗纳就要面临艾尔文森林派来的讨债人上门索债的风险。"},{t="黑龙军团的族群",b="黑龙幼龙在赤脊山出没，这对当地的守军来说是一个令人担忧的信号。虽然豺狼人和兽人公开在道路上肆虐，但黑龙军团的族群却在高峰上筑巢，并在止水湖南面的天空中徘徊。这些幼年掠食者的腹鳞坚韧而柔韧，对于王国各地敢于收集它们的护甲商、铁匠和制皮师来说，是珍贵的制作材料。"}},faq={{q="弗纳·奥斯古为什么需要龙鳞？",a="弗纳欠了闪金镇铁匠阿古斯一批马蹄铁的钱。阿古斯要求用黑龙幼龙的腹鳞，而不是常规货币来支付。弗纳需要尽快交付这些鳞片，以免阿古斯派人来强行索债。",al={"为什么需要龙鳞","弗纳的债务","阿古斯的鳞片要求"}},{q="在赤脊山哪里可以找到黑龙幼龙？",a="黑龙幼龙通常在湖畔镇南面的岩石峭壁和山谷中游荡。它们往往在南部的山脚下自由活动，这意味着猎人通常必须在小径和山脊上巡逻才能发现它们飞行的踪迹。",al={"幼龙位置","幼龙在哪里","赤脊山黑龙幼龙位置"}},{q="铁匠阿古斯是谁？",a="铁匠阿古斯是驻扎在艾尔文森林闪金镇的铁匠。他为周边的定居点提供金属制品和锻造品，包括为赤脊山的弗纳·奥斯古提供马蹄铁。",al={"闪金镇阿古斯","阿古斯是谁","铁匠阿古斯"}},{q="为什么黑龙幼龙会出现在赤脊山？",a="黑龙军团在整个燃烧平原和赤脊山周边山峰都有活动。它们的幼龙会穿过山口向南狩猎并游荡到赤脊山脚下。",al={"为什么赤脊山有龙","赤脊山黑龙","赤脊山黑龙军团"}},{q="腹鳞有什么特别之处？",a="虽然幼龙的背鳞又厚又硬，但腹鳞却柔软而有弹性，同时保持了极高的耐热性和抗穿刺性。这使它们成为专业制皮、定制加固和异域贸易商品的理想材料。",al={"为什么是腹鳞","鳞片价值","龙皮品质"}},{q="偿还这笔债务会引出弗纳的其他任务吗？",a="在你将马蹄铁货物交给弗纳·奥斯古后，这项任务是他后续请求的一部分。除了这项可选的收集工作外，弗纳还会指引冒险者通过猎杀赤脊山豺狼人的斥候和首领来应对日益严重的威胁。",al={"what comes next","弗纳任务线","奥斯古后续任务"}}},fp="17,275,15.420.0,25.379.0,42.236.0,52.194.0,19.184.0,50.199.0,37.247.0,55.208.0"}
P.entries["quest:1220"] = {n="维米斯队长",s="阿登中尉让你把发现的兽人报告交给盖兰·维米斯队长，他比大多数人更精通兽人语。关于塞拉摩附近有部落间谍的消息也一并带去。",h="阿登中尉让你把发现的兽人报告交给盖兰·维米斯队长，他比大多数人更精通兽人语。关于塞拉摩附近有部落间谍的消息也一并带去。",kw={"维米斯队长","尘泥沼泽","盖兰·维米斯","阿登中尉","兽人报告","间谍报告","塞拉摩","塞拉摩岛"},sec={{t="给队长的报告",b="阿登中尉认为你发现的这份兽人报告应该交到盖兰·维米斯队长手中，他比大多数人更精通兽人语。阿登还想让队长知道，部落间谍正在塞拉摩附近潜伏。你可以在塞拉摩岛东北部的军营找到维米斯。"}},faq={{q="是谁派你去找维米斯队长的？",a="阿登中尉，他想让队长看看你发现的那份兽人报告。",al={"谁派出的维米斯队长","如何找到维米斯队长"}},{q="盖兰·维米斯队长在哪里？",a="在塞拉摩岛东北部的军营里。",al={"维米斯队长在哪里","维米斯队长位置","维米斯的军营"}},{q="为什么维米斯队长需要看这份报告？",a="阿登说维米斯比大多数人更精通兽人语，而且应该让他知道部落间谍就在塞拉摩附近。",al={"为什么找维米斯队长","为什么维米斯需要报告"}}},fp="13,168,24.285.0,31.71.0,38.55.0,46.103.0"}
P.entries["quest:1221"] = {n="蓝叶薯",s="“蓝叶薯”是由棘齿城的哥布林商人麦伯克·米希瑞克斯委托的一项回收契约。为了从一种稀有的地下美食中获利，米希瑞克斯为冒险者们配备了经过训练的地鼠，让他们前往剃刀沼泽那荆棘丛生的深处寻找并挖掘埋藏其中的薯块。",h="“蓝叶薯”是由棘齿城的哥布林商人麦伯克·米希瑞克斯委托的一项回收契约。为了从一种稀有的地下美食中获利，米希瑞克斯为冒险者们配备了经过训练的地鼠，让他们前往剃刀沼泽那荆棘丛生的深处寻找并挖掘埋藏其中的薯块。",kw={"蓝叶薯","指挥棒","美食","麦伯克·米希瑞克斯","野猪人","棘齿城","剃刀沼泽","地鼠","贫瘠之地"},ang={["faction:Alliance"]="进入中立港口棘齿城的联盟远征队可以利用米希瑞克斯的贸易契约，为深入敌对的部落周边领地寻找理由。",["faction:Horde"]="部落战士在保卫贫瘠之地免受野猪人入侵的同时，也能通过带着米希瑞克斯训练的地鼠深入剃刀沼泽，轻松赚取外快。",["profession:Cooking"]="烹饪大师们都知道，蓝叶薯被认为是艾泽拉斯最稀有的美味之一，受到那些青睐其独特泥土风味的精英买家的追捧。",["profession:Herbalism"]="与普通的地面植物不同，蓝叶薯严格生长在剃刀沼泽的荆棘根系之间，不受阳光照射，完全处于地下环境。"},sec={{t="一种珍贵的地下美食",b="蓝叶薯作为一种稀有而奢华的烹饪食材，在全世界都备受追捧。尽管它们价值连城，但采摘工作却极度困难，因为它们既不生长在开阔的田野，也不见于普通的野生树丛中。事实上，它们几乎只生长在南贫瘠之地地底深处那不见天日的泥土中，缠绕在剃刀沼泽那迷宫般的根系之间。"},{t="米希瑞克斯的巧思",b="由于这种薯块完全埋在地下，普通类人生物根本无法察觉，于是棘齿城的商人麦伯克·米希瑞克斯想出了一种不同寻常的解决方案。他训练了当地的地鼠——这种生物能在五十步之外就闻到埋在地下的薯块气味——将这些害虫变成了采集工具。他为拾荒者提供了一根指挥棒、一个开孔的箱子，以及一本指导手册，指引他们带着这些生物穿过野猪人的领地。"},{t="在荆棘丛中采摘",b="想要回收这些薯块，就必须深入敌对的死头野猪人部族领地。采集者必须保护他们训练有素的地鼠免受剃刀沼泽中凶猛野兽和荆棘丛的伤害，指挥这些啮齿动物挖出隐藏的球茎，然后将其打包带回棘齿城，那里正有米希瑞克斯高价聘请的海外买家等待着。"}},faq={{q="蓝叶薯有什么用？",a="它们被认为是世界各地罕见且备受推崇的烹饪美食。富有的买家愿意为新鲜的薯块支付巨款，这使它们成为了像麦伯克·米希瑞克斯这样的哥布林手中有利可图的贸易商品。",al={"蓝叶薯用途","什么是蓝叶薯","为何采集蓝叶薯"}},{q="在哪里可以找到蓝叶薯？",a="它们生长在南贫瘠之地地底的泥土和荆棘根系中，具体来说，就在野猪人的据点剃刀沼泽内部。",al={"哪里可以找到蓝叶薯","蓝叶薯位置","它们在哪里生长"}},{q="为什么要用地鼠来寻找它们？",a="薯块完全隐藏在地下，仅靠普通人的视力无法发现。地鼠拥有敏锐的嗅觉，能在五十步外探测到埋藏的薯块，并将其从泥土中挖掘出来。",al={"为什么要用地鼠","地鼠的作用","地鼠如何寻找薯块"}},{q="麦伯克·米希瑞克斯是谁？",a="麦伯克·米希瑞克斯是一位在贫瘠之地的中立港口城市棘齿城经营的创业型哥布林商人。他专门从事训练当地野生动物和收购用于对外贸易的奇异商品。",al={"谁发布蓝叶薯任务","麦伯克·米希瑞克斯背景故事","棘齿城哥布林任务发布者"}},{q="米希瑞克斯为这项工作提供了什么装备？",a="米希瑞克斯给了冒险者一个装有训练好的地鼠的开孔的箱子、一根用于指挥动物挖掘的地鼠指挥棒，以及一本概述如何操控这种野兽的地鼠训练手册。",al={"薯块任务物品","地鼠指挥棒","开孔的箱子"}},{q="为什么麦伯克不亲自去采集薯块？",a="剃刀沼泽由好战的野猪人部族、荆棘藤蔓和危险的地下掠食者严密把守。米希瑞克斯宁愿让雇佣兵冒生命危险，也不愿自己冒险进入那些危险的洞穴。",al={"为什么麦伯克不自己去拿","为什么要雇佣冒险者"}}},fp="15,170,30.266.0,20.311.0,24.305.0,34.183.0,32.129.0,50.158.0,22.166.0,49.185.0,42.184.0"}
P.entries["quest:1222"] = {n="伊格纳兹的逃亡",s="“臭脚”伊格纳兹身处沼泽之中，塞拉摩的厨师摩根·斯特恩派他去采集沼泽豆叶。他被野兽团团包围，请求你协助他脱困，并在他寻找沼泽豆植株时保护他的安全。事成之后，请去塞拉摩找摩根·斯特恩。",h="“臭脚”伊格纳兹身处沼泽之中，塞拉摩的厨师摩根·斯特恩派他去采集沼泽豆叶。他被野兽团团包围，请求你协助他脱困，并在他寻找沼泽豆植株时保护他的安全。事成之后，请去塞拉摩找摩根·斯特恩。",kw={"蓝色隐士","沼泽豆","尘泥沼泽","摩根·斯特恩","臭脚伊格纳兹","塞拉摩"},sec={{t="陷入重围",b="伊格纳兹见到一个不把他当成盘中餐的人，顿时松了一口气。他说厨师摩根·斯特恩正在研制一道新菜，派他出来采集沼泽豆叶，伊格纳兹猜斯特恩觉得那东西很好吃。在寻找植株时，伊格纳兹遭到了围困，他请求你协助他脱困，并在他寻找时保护他的后方。"},{t="等待的厨师",b="塞拉摩的摩根·斯特恩很焦急：伊格纳兹出发去沼泽已经有一段时间了，至今未归。"},{t="厨师的谢意",b="斯特恩说伊格纳兹带回了沼泽豆叶，并讲述了你是如何帮他脱离困境的。为了表示感谢，斯特恩会请求他的一位叔叔在你下次访问暴风城的蓝色隐士旅店时为你准备一顿大餐。"}},faq={{q="“臭脚”伊格纳兹是谁？",a="“臭脚”伊格纳兹被厨师摩根·斯特恩派往沼泽去采集沼泽豆叶。",al={"臭脚伊格纳兹","谁是臭脚","伊格纳兹 尘泥沼泽"}},{q="伊格纳兹为什么会陷入困境？",a="当他在寻找沼泽豆植株时，周围的野兽围拢过来，将他团团困住。",al={"为什么臭脚被困","伊格纳兹 受困","为什么臭脚在尘泥沼泽"}},{q="沼泽豆叶有什么用？",a="摩根·斯特恩正在研制一道新菜，派伊格纳兹去采集这些叶子。伊格纳兹猜斯特恩觉得它们味道不错。",al={"沼泽豆叶","什么是沼泽豆","沼泽豆植株"}},{q="摩根·斯特恩是谁？",a="摩根·斯特恩是塞拉摩的一名厨师，正在研制一道新菜。",al={"摩根·斯特恩 塞拉摩","谁是摩根·斯特恩","厨师摩根·斯特恩"}}},fp="15,285,10.324.0,14.101.0,20.204.1,23.90.0,25.90.0,28.110.0,20.67.0"}
P.entries["quest:123"] = {n="收货人",s="这份被截获的派遣函是从潜伏在树林里的豺狼人劫掠者身上缴获的，它勾勒出了一份精确的采金日程表，记录着金矿石如何离开艾尔文森林那些废弃的矿井。这份日程表是写给一个被称为“收藏家”的神秘人物的，暗示着一个精心策划的组织正在暴风城卫兵的眼皮底下大肆敛财。",h="这份被截获的派遣函是从潜伏在树林里的豺狼人劫掠者身上缴获的，它勾勒出了一份精确的采金日程表，记录着金矿石如何离开艾尔文森林那些废弃的矿井。这份日程表是写给一个被称为“收藏家”的神秘人物的，暗示着一个精心策划的组织正在暴风...",kw={"布莱克威尔南瓜田","艾尔文森林","采金日程表","闪金镇","搜捕","治安官杜汉","矿井","收藏家"},ang={["class:Rogue"]="截获日程表并追踪有组织的走私活动是典型的反情报手段，揭示了犯罪集团在艾尔文荒野中的根基有多深。",["faction:Alliance"]="每一盎司从艾尔文偷运出去的黄金，都在这个王国竭力保卫边境的时代，剥夺了王室重要的税收和原材料。",["profession:Mining"]="艾尔文那些废弃的矿井中依然蕴藏着丰富的铜矿和贵金属矿脉——当诚实的矿工因恐惧而居家避难时，有人正在非法开采这些矿脉。"},sec={{t="豺狼人爪中的纸条",b="在清剿潜伏于艾尔文森林西部的河爪豺狼人时，冒险者在粗糙的皮毛和简陋的武器之间发现了一张奇怪的羊皮纸：采金日程表。这绝非野兽的乱涂乱画，纸条上详细记录了从当地矿井中开采出的贵重金属的交付日期和时间。收货人显然有着极强的纪律性和后勤预见能力，指挥着货物运往一个仅被称为“收藏家”的监管者手中。"},{t="闪金镇的不安消息",b="当这份发现被送到闪金镇Lion's Pride Inn的治安官杜汉面前时，他大为震惊。由于豺狼人的侵扰、狗头人的泛滥以及流窜的强盗，艾尔文森林各地的官方采矿作业已经停工数月。矿石依然在被有组织地开采和运输，而且豺狼人竟然携带着发货清单，这一事实证实了一个有组织的犯罪网络正在暗中掠夺王国的自然财富。"},{t="聚焦布莱克威尔南瓜田",b="这份日程表将收藏家的嫌疑地点锁定在艾尔文森林东部的布莱克威尔南瓜田附近。虽然杜汉以前听说过这个名号，但他缺乏确凿的证据来查明是谁在指挥这个团伙，也不知道非法金矿最终流向何处。上交这份日程表，为卫兵追踪幕后主使提供了第一条有力的线索。"}},faq={{q="什么是采金日程表？",a="这是从艾尔文森林的豺狼人身上缴获的一本账目。它列出了开采出的黄金被移交给一个被称为“收藏家”的神秘人物的具体日期和时间。",al={"采金日程表","收藏家的字条","艾尔文采金日程"}},{q="“收藏家”是谁？",a="收藏家是一个潜伏在艾尔文森林东部的狡猾罪犯，据信他躲在布莱克威尔南瓜田附近，同时策划着非法的黄金交易。",al={"收藏家的身份","谁是收藏家","布莱克威尔收藏家"}},{q="为什么治安官杜汉对这份日程表感到震惊？",a="由于怪物活动的加剧，暴风城的官方矿工已经废弃当地矿井数月之久。发现有人仍在开采并运输黄金，揭露了一个正在从内部瓦解王国的秘密行动。",al={"为什么杜汉感到惊讶","杜汉的反应","艾尔文矿井关闭"}},{q="为什么豺狼人会有这张纸条？",a="艾尔文西部的河爪豺狼人似乎在黄金走私链条中充当信使、守卫或共犯，负责携带用于安排交接的命令。",al={"豺狼人与黄金","为什么豺狼人会携带日程表","豺狼人的牵连"}},{q="这项调查接下来会引向何处？",a="将日程表交给治安官杜汉会开启任务“搜捕”，引导你前往布莱克威尔南瓜田附近追踪并消灭收藏家。",al={"收藏家后续","搜捕任务","追踪收藏家"}},{q="布莱克威尔南瓜田位于何处？",a="布莱克威尔南瓜田位于艾尔文森林的东部边缘，河流以北，马科伦农场和斯通菲尔德农场以东。",al={"布莱克威尔位置","布莱克威尔在哪里","艾尔文南瓜田"}}},fp="13,230,35.293.0,29.336.0,27.318.1,33.177.0,23.146.0,46.268.0,29.159.0,40.141.0,45.127.0"}
P.entries["quest:1238"] = {n="遗失的报告",s="你在尘泥沼泽松软的泥土中翻找时，发现一只断掉的兽人手臂正紧紧抓着一根用骨头雕刻而成的管子，里面装着一张沾满泥土的羊皮纸。这是一份兽人写下的报告，他作为间谍监视塞拉摩已经有数周了。这份报告是写给蕨墙村的兽人情报头子纳泽尔·血矛的。",h="你在尘泥沼泽松软的泥土中翻找时，发现一只断掉的兽人手臂正紧紧抓着一根用骨头雕刻而成的管子，里面装着一张沾满泥土的羊皮纸。这是一份兽人写下的报告，他作为间谍监视塞拉摩已经有数周了。这份报告是写给蕨墙村的兽人情报头子纳泽尔·...",kw={"蕨墙村","尘泥沼泽","松软的泥土","纳泽尔·血矛","间谍报告","遗失的报告","塞拉摩"},sec={{t="泥土中的手",b="在松软的泥土里躺着一只断掉的兽人手臂，紧握着一根骨制管子。里面的羊皮纸是一个兽人写下的报告，他作为间谍监视塞拉摩已经有数周了。阅读之后，你发现它应该交给蕨墙村的兽人情报头子纳泽尔·血矛。"},{t="来自情报头子的消息",b="纳泽尔·血矛说这名作者是玛格·夜眼，一名驻扎在塞拉摩外监视这座城市的特工。这是玛格最新的报告，或许也是最后一份：根据你的描述，血矛担心玛格已经在沼泽中丧命了。"}},faq={{q="在哪里可以找到这份报告？",a="它位于尘泥沼泽的松软泥土中，被一只断掉的兽人手臂紧紧抓着。",al={"报告在哪里","遗失报告位置","如何开始遗失报告任务"}},{q="这份报告的内容是什么？",a="一个兽人在监视塞拉摩数周后写下的报告。",al={"报告里有什么","间谍报告说了什么","羊皮纸内容"}},{q="谁应该收到这份报告？",a="位于蕨墙村的兽人情报头子，纳泽尔·血矛。",al={"我应该把报告交给谁","遗失报告交付","把间谍报告带到哪里"}}},fp="15,308,18.276.0,23.232.1,26.77.0,25.51.0,20.62.0"}
P.entries["quest:1239"] = {n="被斩下的头颅",s="经过一番卖力的挖掘，你挖出了一颗男性兽人的头颅，脖颈处的切口参差不齐。你应该把它交给蕨墙村的纳泽尔·血矛。",h="经过一番卖力的挖掘，你挖出了一颗男性兽人的头颅，脖颈处的切口参差不齐。你应该把它交给蕨墙村的纳泽尔·血矛。",kw={"蕨墙村","挑衅的兽人头颅","尘泥沼泽","松软的泥土","玛格·夜眼","纳泽尔·血矛","断头"},sec={{t="可怕的发现",b="在松软的泥土中用力挖掘，你挖出了一颗男性兽人的头颅，脖颈处的切口参差不齐。他的嘴唇紧绷成狰狞的姿态，深色的双眼充满挑衅地怒视着。你应该把它交给蕨墙村的纳泽尔·血矛。"},{t="纳泽尔的审视",b="纳泽尔·血矛一眼就认出这颗头颅属于玛格·夜眼，他一直担心玛格已经遇难了。纳泽尔仔细研究了脖颈上参差不齐的伤口，怀疑这是武器留下的，还是什么野兽杀死了这名特工。这是一个需要解开的谜团，纳泽尔想知道玛格之死是否与联盟有关。"}},faq={{q="你应该把这颗断头交给谁？",a="交给蕨墙村的纳泽尔·血矛。",al={"断头交还地点","断头任务提交","谁接收断头"}},{q="这颗头颅看起来是什么样的？",a="这是一颗男性兽人的头颅，脖颈处的切口参差不齐，嘴唇紧绷，深色的双眼充满挑衅地怒视着。",al={"松软的泥土里有什么","挑衅的兽人头颅","断头外观描述"}},{q="上交断头后接下来要做什么？",a="下一步是The Troll Witchdoctor。",al={"断头任务后续","断头后续任务"}}},fp="16,155,11.236.0,19.306.1,36.43.0,29.119.0,34.39.0"}
P.entries["quest:124"] = {n="豺狼人的乱吠",s="湖畔镇的马厩管理员弗纳·奥斯古发现他的生意正受到从赤脊山山麓南下突袭的豺狼人的围攻。由于已经饱受黑石兽人的侵扰，他请求旅行者清理威胁到他牲畜的这些残暴生物和神秘者。",h="湖畔镇的马厩管理员弗纳·奥斯古发现他的生意正受到从赤脊山山麓南下突袭的豺狼人的围攻。由于已经饱受黑石兽人的侵扰，他请求旅行者清理威胁到他牲畜的这些残暴生物和神秘者。",kw={"豺狼人","马匹","湖畔镇","赤脊山残暴生物","赤脊山","赤脊山神秘者","马厩","弗纳·奥斯古"},ang={["class:Hunter"]="由于缺乏有组织的扑杀，赤脊山的野生野兽和野性部族变得愈发嚣张，这对家畜和旅行者构成了不稳定的威胁。",["faction:Alliance"]="南方王国的每一个小社区都感受到了暴风城忽视所带来的压力，这使得像弗纳这样的卑微商人不得不雇佣私人帮助来保护重要的补给线。"},sec={{t="山脊上的马匹",b="在湖畔镇经营马厩变得越来越危险。黑石兽人占据了该地区的高地，而一群群豺狼人在周围的山脊上徘徊。对弗纳·奥斯古来说，当具有攻击性的豺狼人劫掠小队悄悄靠近他围场的北侧边界，并捕食那些走得太近峭壁的马匹时，局势已经到了崩溃的边缘。"},{t="协同威胁",b="这些不仅仅是散乱的拾荒者。在镇子正北面活动的豺狼人部族将野蛮的武力与原始的法术结合在一起，利用强悍的残暴生物来压制猎物，同时配合挥舞着狂野魔法的神秘者。减少它们的数量可以给这个定居点带来短暂的喘息，尽管很快就能看出，它们的攻击是由潜伏在山丘更高处的更大势力所驱动的。"}},faq={{q="为什么弗纳·奥斯古需要帮助来对付豺狼人？",a="来自北部山脊的豺狼人开始侵扰弗纳的马厩，每当马匹从围场走失时，它们就会把马抢走。在那个威胁和黑石兽人的入侵之间，如果没有外界的帮助，他无法保护他的牲畜。",al={"弗纳的问题","为什么弗纳想要消灭豺狼人","湖畔镇马厩豺狼人"}},{q="这些豺狼人在哪里？",a="赤脊山残暴生物和神秘者在湖畔镇正北和正东方向的隆起山脊和山麓上游荡，俯瞰着镇子和通往止水桥的道路。",al={"赤脊山残暴生物在哪里","赤脊山神秘者位置","马厩北面的豺狼人"}},{q="为什么豺狼人会和黑石兽人一起成为问题？",a="虽然黑石氏族是威胁赤脊山的主要军事力量，但当地的豺狼人部族却利用了这种分散注意力的机会。由于湖畔镇的防御力量捉襟见肘，而暴风城提供的增援又微乎其微，这些本土掠食者已经肆无忌惮地扩张到了村庄的边缘。",al={"赤脊山的兽人和豺狼人","为什么豺狼人和兽人同时存在"}},{q="处理完这些豺狼人后接下来会发生什么？",a="在清理了残暴生物和神秘者之后，弗纳注意到山丘上的嚎叫声仍在继续，这指向了一个更大的领导层威胁，必须在周围的高地解决这一问题。",al={"豺狼人的嚎叫后续","豺狼人的嚎叫之后做什么"}},{q="为什么神秘者特别危险？",a="赤脊山神秘者修习着粗浅的自然和元素魔法，将不稳定的野性咒语用于对抗入侵者。它们在残暴生物中的存在表明这是有组织的部族结构，而不是零散的野外食腐者。",al={"赤脊山神秘者背景","赤脊山豺狼人萨满"}},{q="暴风城是否派士兵来保护湖畔镇的马厩？",a="没有。由于持续的政治动荡和军队短缺，暴风城皇室已基本让赤脊山自生自灭，迫使所罗门镇长和像弗纳·奥斯古这样的市民去招募流浪的冒险者。",al={"暴风城守卫赤脊山","为什么没有守卫帮助弗纳"}}},fp="18,208,19.268.0,20.268.1,45.205.0,31.168.0,53.259.0,43.146.1,39.205.0,61.203.0"}
P.entries["quest:1240"] = {n="巨魔巫医",s="纳泽尔·血矛想要查明玛格·夜眼之死背后的真相，他说只有巨魔的巫术才能告知这一切。你必须带着玛格的头颅前往荆棘谷的格罗姆高营地，去找肯维雷。",h="纳泽尔·血矛想要查明玛格·夜眼之死背后的真相，他说只有巨魔的巫术才能告知这一切。你必须带着玛格的头颅前往荆棘谷的格罗姆高营地，去找肯维雷。",kw={"暗矛巫医","不屈的兽人头颅","格罗姆高营地","肯维雷","玛格·夜眼","纳泽尔·血矛","荆棘谷"},sec={{t="巨魔的巫术",b="在那个被割下的头颅出现后，纳泽尔·血矛坚持认为必须查明玛格死因的真相，而且只有巨魔的巫术才能揭示它们。玛格的头颅必须送到荆棘谷格罗姆高营地的肯维雷那里。在暗矛巨魔中，没有比肯维雷更强大的巫医了，纳泽尔认为如果有什么人能联系到玛格的灵魂，那一定就是肯维雷。"},{t="格罗姆高的交谈",b="当你抵达时，肯维雷感觉到你身上带着一个愤怒的灵魂。看着那个头颅，这位巫医看出这名兽人的灵魂被禁锢在这个世界上，因未竟的职责而怒火中烧，他提议与这个灵魂谈谈。"}},faq={{q="为什么必须把玛格·夜眼的头颅带到荆棘谷？",a="纳泽尔·血矛说，了解玛格死因的唯一方法是使用巨魔的巫术，而肯维雷就在格罗姆高营地。",al={"为什么要去荆棘谷","为什么要去格罗姆高","为什么要找肯维雷"}},{q="肯维雷是谁？",a="暗矛巨魔中最强大的巫医，位于荆棘谷的格罗姆高营地。",al={"巫医是谁","巫医肯维雷"}},{q="下一步做什么？",a="下一步是“玛格开口”。",al={"下一个任务是什么","在巨魔巫医之后"}}},fp="21,206,25.377.0,17.225.1,61.141.0,18.104.0,27.29.0"}
P.entries["quest:1241"] = {n="失踪的使节",s="当一位联盟外交官未能抵达塞拉摩岛后，一场紧急且隐秘的调查在暴风城内悄然展开。德拉维主教怀疑是迪菲亚潜行者所为，于是派遣了值得信赖的特工去咨询乔贞，一个驻扎在英雄谷的沉默联络人。",h="当一位联盟外交官未能抵达塞拉摩岛后，一场紧急且隐秘的调查在暴风城内悄然展开。德拉维主教怀疑是迪菲亚潜行者所为，于是派遣了值得信赖的特工去咨询乔贞，一个驻扎在英雄谷的沉默联络人。",kw={"迪菲亚","德拉维","吉安娜","乔贞","失踪的外交官","暴风城","塞拉摩","英雄谷"},ang={["class:Priest"]="当传统的皇家渠道可能受到威胁时，德拉维主教利用教会关系秘密调查国家罪行。",["class:Rogue"]="通过像乔贞这样低调的线人追踪失踪特使，凸显了在暴风城光鲜街道下运行的地下间谍活动。",["faction:Alliance"]="一位皇家外交官的失踪威胁到了暴风城王国与吉安娜·普罗德摩尔在塞拉摩的据点之间脆弱的谈判。",["race:Human"]="迪菲亚潜行者持续的威胁直接打击了人类王国的稳定，其触角从西部荒野延伸到了首都中心。"},sec={{t="消失在阴影中",b="一位高阶外交官从东部王国出发，前往塞拉摩岛与吉安娜·普罗德摩尔进行敏感会谈。这位特使在抵达前就失踪了。虽然皇家调查员在暴风城内四处搜寻线索，但为了避免引起广泛恐慌，或惊动那些可能监视着王室一举一动的阴谋家，此次失踪事件被严密封锁了消息。"},{t="私人调查",b="德拉维主教认为迪菲亚潜行者参与了外交官的绑架案，他决定不完全依赖国王的正式卫队。相反，主教联系了一些非官方且谨慎的渠道，找到了乔贞。这是一个老相识，他以在英雄谷城门内钓鱼为掩护，保持着极低的行事作风。"},{t="不情愿的线人",b="乔贞在城市水边保持着粗鲁的举止和一个不起眼的伪装，但他遵守过去对德拉维的承诺。意识到这一谜团背后潜藏的危险，乔贞明确表示追踪外交官的下落伴随着致命风险，并要求所有被卷入调查的人必须绝对保密。"}},faq={{q="失踪的外交官是谁？",a="圣光教会和暴风城王室对这位特使的身份严加保密，官方仅称其为派往塞拉摩穿越无尽之海的关键外交官。",al={"失踪外交官身份","谁失踪了","谁消失了","外交官身份"}},{q="外交官为何前往塞拉摩？",a="这位外交官受命会见吉安娜·普罗德摩尔，就东部王国与卡利姆多之间联盟的安全和现状进行关键会谈。",al={"为何前往塞拉摩","外交官目的","外交官在做什么"}},{q="德拉维主教怀疑谁？",a="德拉维主教怀疑是迪菲亚潜行者策划了绑架案，尽管他们在城内的确切手段和同伙尚不为人知。",al={"谁带走了外交官","德拉维怀疑对象","谁绑架了外交官"}},{q="乔贞是谁？",a="乔贞是德拉维主教的特工及长期私人联络人，他在暴风城的英雄谷水边守着一个不起眼的钓鱼位置。",al={"乔贞在哪里","乔贞身份","那个渔夫是谁"}},{q="为什么此事对公众保密？",a="如果透露出一位重要特使在王室眼皮底下被绑架，将会引发混乱，并警示阴谋家们皇家特工正在积极搜捕他们。",al={"为何保密","为何要保密","为何不告诉全城"}},{q="这项调查指向何处？",a="乔贞提供了进一步的指示，要求深入挖掘暴风城周边的地下世界和隐藏网络，以查明外交官是在何处被拦截的。",al={"接下来会发生什么","找完乔贞去哪里"}}},fp="20,211,26.306.0,17.272.0,21.223.1,28.162.0,44.158.0,32.134.0,14.144.0,46.194.0,35.125.0"}
P.entries["quest:1242"] = {n="失踪的使节",s="这项任务指引调查员从英雄谷的乔贞那里前往暴风城贸易区的提亚斯奶酪店，寻找店主埃林·提亚斯。通过携带一封谨慎的给埃林的密信，它将宫廷对失踪外交官的担忧与这家低调奶酪店柜台后保持的秘密联络渠道联系了起来。",h="这项任务指引调查员从英雄谷的乔贞那里前往暴风城贸易区的提亚斯奶酪店，寻找店主埃林·提亚斯。通过携带一封谨慎的给埃林的密信，它将宫廷对失踪外交官的担忧与这家低调奶酪店柜台后保持的秘密联络渠道联系了起来。",kw={"埃林·提亚斯","乔贞","失踪外交官","给埃林的密信","暴风城","trade district","提亚斯奶酪店"},ang={["class:Rogue"]="潜行者可能会怀疑提亚斯奶酪店不仅仅是一家乳制品店；店主在贸易区之外保持着隐秘的联络。",["faction:Alliance"]="对失踪使节的秘密搜寻揭示了暴风城领导层中细微的弱点。"},sec={{t="一次谨慎的递送",b="在对一名未具名外交官的失踪进行初步调查后，乔贞指示受信任的特工们严守秘密，并将一封密信送往城中。目的地并非正式的兵营或治安官办公室，而是坐落在繁忙的贸易区的提亚斯奶酪店。这种移交方式的隐秘性暗示了事态已经变得多么敏感，他们绕过了普通的守卫渠道，转而利用非正式的情报网。"},{t="店面背后",b="对于浏览达纳苏斯蓝干酪或切达干酪的普通顾客来说，奶酪大师埃林·提亚斯看起来只不过是一个快乐、勤恳的商人。实际上，提亚斯与乔贞有些交情，他在店外也有着自己的联络人。递送乔贞的信件，标志着对失踪外交官的搜寻工作已悄然移交到他的手中。"}},faq={{q="埃林·提亚斯是谁？",a="表面上，埃林·提亚斯是一位受人尊敬的商人，在暴风城的贸易区经营着提亚斯奶酪店。在他的奶酪生意之下，他与乔贞有着一定的交情，并拥有可以在敏感事件中动用的个人关系网。",al={"提亚斯是谁","奶酪商贩","埃林·提亚斯的身份"}},{q="为什么乔贞让我保持沉默？",a="外交官的失踪属于国家机密，可能会引发恐慌或惊动绑架事件的幕后黑手。乔贞坚持要求绝对的谨慎，以免泄露调查正在进行的事实。",al={"为什么要沉默","乔贞的警告","闭紧你的嘴"}},{q="我在哪里可以找到提亚斯奶酪店？",a="这家店位于暴风城的贸易区，隐藏在通往各处普通商人和工匠聚集地的主干道旁。",al={"提亚斯的位置","奶酪店位置","埃林·提亚斯在哪里"}},{q="给埃林的密信里写了什么？",a="信中包含了乔贞关于失踪外交官的谨慎简报，要求提亚斯利用他专业的关系网和地下的眼线，去寻找常规当局无法追踪到的线索。",al={"信件内容","信里说了什么","给埃林的密信"}},{q="任务中提到的失踪外交官是谁？",a="在调查的这个阶段，皇室对具体身份严加保密，尽管极端严密的保密措施和高层的忧虑表明，此人对暴风城王国具有极高的政治重要性。",al={"谁失踪了","外交官是谁","失踪者的身份"}},{q="为什么调查要利用一个奶酪商而不是城市卫兵？",a="官方城市卫兵受到规章制度、管辖范围和潜在政治牵连的束缚。埃林·提亚斯能够接触到街头巷尾的耳语和正式士兵无法触及的秘密渠道。",al={"为什么找奶酪商","为什么提亚斯而不是卫兵","卫兵与提亚斯"}}},fp="20,208,19.354.0,20.259.1,20.174.0,38.190.0,31.106.0,37.179.0,51.165.0,73.156.0"}
P.entries["quest:1243"] = {n="失踪的使节",s="在这项调查暴风城失踪特使的任务中，你将被派往南方那片阴郁的土地——暮色森林。根据在首都获取的线索，奶酪大师埃林·提亚斯指派你前往夜色镇附近联系守夜人巴库斯，以发掘迪菲亚潜行者的活动踪迹。",h="在这项调查暴风城失踪特使的任务中，你将被派往南方那片阴郁的土地——暮色森林。根据在首都获取的线索，奶酪大师埃林·提亚斯指派你前往夜色镇附近联系守夜人巴库斯，以发掘迪菲亚潜行者的活动踪迹。",kw={"夜色镇","迪菲亚潜行者","暮色森林","埃林·提亚斯","乔贞","失踪特使","守夜人","守夜人巴库斯"},ang={["class:Rogue"]="埃林·提亚斯展示了资深特工是如何运作情报网的，他们依靠独立的基层人员来收集侦察情报，同时让自己置身事外。",["faction:Alliance"]="特使的失踪触及了暴风城皇室利益的核心，迫使英雄们在皇家情报官、独立的罪犯以及区域民兵之间进行协调。"},sec={{t="阴影中的奔波",b="在与乔贞进行了一次令人沮丧的交谈后，奶酪商埃林·提亚斯决定动用他更广泛的情报网络。与其浪费自己的金币雇佣专业特工，他决定让你亲自去跑腿。你被委派将一封密封的信件带过边境，送入暮色森林，那是一片饱受野兽、亡灵以及更恐怖事物蹂躏的阴影之地。"},{t="守夜人的倾听者",b="你的目标是守夜人巴库斯，他是夜色镇守夜人的一员，负责巡逻城镇北部的入口。尽管暮色森林对普通旅行者来说危机四伏，但提亚斯仍将巴库斯视为可靠的非法活动情报来源。出示这封密封的信件，你就能查阅市政警卫记录，并获知有关迪菲亚潜行者在南方活动的当地传闻。"}},faq={{q="埃林·提亚斯为什么要派我去暮色森林？",a="埃林·提亚斯正在追查有关失踪特使和可疑的迪菲亚潜行者活动的每一条潜在线索。为了节省开支并充分利用他的人脉，他派你前往暮色森林去采访守夜人巴库斯，以获取当地的第一手消息。",al={"为什么要去暮色森林","提亚斯的暮色森林任务","为什么是夜色镇"}},{q="我在哪里可以找到守夜人巴库斯？",a="守夜人巴库斯在暮色森林夜色镇外北部的土路上巡逻，守卫着通往赤脊山和艾尔文森林的道路。",al={"守夜人巴库斯位置","巴库斯在哪里","寻找巴库斯"}},{q="守夜人巴库斯是谁？",a="守夜人巴库斯是夜色镇民兵组织——守夜人的一名士兵。他也是埃林·提亚斯的私人盟友，愿意分享对该地区可疑旅行者和犯罪活动的观察。",al={"巴库斯背景资料","巴库斯是谁"}},{q="给巴库斯的密封信件里写了什么？",a="信中包含埃林·提亚斯的机密询问，要求情报以获悉是否有任何关于迪菲亚潜行者穿过暮色森林的目击记录或活动踪迹。",al={"密封信件的内容","信上写了什么","给守夜人巴库斯的密信"}},{q="暮色森林和迪菲亚潜行者有什么关系？",a="虽然迪菲亚潜行者的大本营位于西部荒野的死亡矿井之下，但他们在南方的人类省份中仍保留着多个据点、信使和藏身处，其中包括暮色森林的阴影边缘。",al={"暮色森林里的迪菲亚潜行者","暮色森林里有迪菲亚潜行者吗"}},{q="为什么提亚斯要抱怨乔贞？",a="乔贞在之前的调查中设置障碍或者漫天要价，这让提亚斯非常恼火，以至于他在求助于其他外勤联络人之前，诅咒乔贞去扭曲虚空。",al={"乔贞是谁","提亚斯和乔贞"}}},fp="20,185,21.300.0,33.316.0,43.217.0,32.131.0,22.179.0,43.142.0,58.201.0,37.189.0"}
P.entries["quest:1244"] = {n="失踪的使节",s="调查的这一阶段指引联盟特工深入暮色森林的阴影之中，追踪暴风城失踪特使的线索。根据守夜人巴库斯的情报，调查员们必须搜查被废弃的腐草农场，以发现迪菲亚兄弟会的文书。",h="调查的这一阶段指引联盟特工深入暮色森林的阴影之中，追踪暴风城失踪特使的线索。根据守夜人巴库斯的情报，调查员们必须搜查被废弃的腐草农场，以发现迪菲亚兄弟会的文书。",kw={"腐草农场","迪菲亚记事本","暮色森林","脚箱","守夜人","失踪的外交官","守夜人巴库斯"},ang={["class:Rogue"]="在犯罪网络中穿梭并破译埋下的纸质线索，需要从巧妙的迪菲亚误导中辨别出真实的情报。",["faction:Alliance"]="王国特使的失踪直击暴风城安全的核心，这证明了迪菲亚的阴谋早已超出了西部荒野那种轻微的拦路抢劫。"},sec={{t="阴影中的线索",b="在追踪了暴风城城墙外关于阴谋的传言后，针对失踪外交官的搜寻工作延伸到了暮色森林的守夜人那里。守夜人巴库斯指出，虽然迪菲亚强盗通常都待在边境的另一侧，但在几周前，有大量人员异常聚集在腐草农场。对于一个主要在西部荒野活动的组织来说，在黑暗森林中如此集中的活动表明在那片废弃农场上发生了一些至关重要的事。"},{t="迪菲亚记事本",b="搜查那片被占领的农场，找到了一只锁着的脚箱，里面装着一份迪菲亚记事本。虽然这些文件证实了兄弟会的参与，但巴库斯警告说，与这些阴谋分子打交道是极其危险的——这些文件可能只是为了将爱管闲事的调查员引向死胡同而伪造的误导信息。"}},faq={{q="腐草农场在哪里？",a="腐草农场位于暮色森林西部，就在从西部荒野进入该地区的主路以南。那是一处破旧的农舍，目前被敌对的迪菲亚特工占据。",al={"腐草农场位置","腐草农场在哪里","寻找腐草农场"}},{q="什么是迪菲亚记事本？",a="迪菲亚记事本是一份存放在腐草农场农舍内脚箱里的文件，看起来像是官方文件。它详细记录了兄弟会最近在该地区进行的秘密行动的一些方面。",al={"迪菲亚记事本","什么是迪菲亚记事本","腐草农场文件"}},{q="谁是守夜人巴库斯？",a="守夜人巴库斯是驻扎在暮色森林的守夜人成员。他在镇上有联络人，并密切关注边境威胁，他协助追踪西部荒野边境沿线异常的迪菲亚动向。",al={"守夜人巴库斯","谁是巴库斯","巴库斯 暮色森林"}},{q="为什么迪菲亚会在暮色森林内活动？",a="虽然他们的大本营位于边境另一侧的西部荒野，但迪菲亚特工经常悄悄潜入暮色森林西部。腐草农场作为一个与世隔绝的隐秘据点，避开了暴风城的巡逻。",al={"迪菲亚在暮色森林的原因","腐草农场的迪菲亚"}},{q="迪菲亚记事本的内容可信吗？",a="守夜人巴库斯本人在检查时表示谨慎。虽然文件看起来很真实，但迪菲亚是狡猾的阴谋家，有能力制造虚假的线索来诱导调查员偏离踪迹。",al={"记事本是真的吗","伪造的记事本","是骗局吗"}},{q="是谁最初指引调查员去找守夜人巴库斯的？",a="守夜人巴库斯指出，暴风城的奶酪商人兼秘密情报掮客埃林·提亚斯，就是指引调查工作前往暮色森林守夜人那里的人。",al={"谁指引我找巴库斯","提亚斯的关系"}}},fp="20,126,19.362.0,17.231.1,31.135.0,26.168.0,22.186.0,41.189.0,49.171.0,59.154.0"}
P.entries["quest:1245"] = {n="失踪的使节",s="在这项错综复杂的调查任务中，你带着找回的迪菲亚记事本赶回暴风城。最初仅仅是针对一名失踪外交官的调查，如今却揭开了一个远比当地守夜人所能触及的范围更广、更危险的阴谋。",h="在这项错综复杂的调查任务中，你带着找回的迪菲亚记事本赶回暴风城。最初仅仅是针对一名失踪外交官的调查，如今却揭开了一个远比当地守夜人所能触及的范围更广、更危险的阴谋。",kw={"迪菲亚记事本","暮色森林","埃林·提亚斯","拳头","失踪的外交官","暴风城","守夜人巴库斯"},ang={["class:Rogue"]="埃林·提亚斯代表了潜行者中用匕首换取情报网络的那一面。观看一位情报头子破译迪菲亚的原始密码，展现了王国的影子战争是如何真正进行的。",["faction:Alliance"]="迪菲亚高级计划的发现突显了暴风城王国的安全自第三次战争以来遭到了多大的侵蚀，从内部威胁着政权的稳定。"},sec={{t="对守夜人来说过于沉重",b="在暮色森林的阴影丛林中找回迪菲亚记事本后，守夜人巴库斯不愿再与它有任何瓜葛。文件详细记录的计划太过错综复杂，绝非普通的土匪行径或牵制战术。巴库斯害怕王室的报复，也提防着他在守夜人中的上级，因此极力要求你对他的参与守口如瓶。这些文件所提到的阴谋足以毁掉一个人的职业生涯甚至夺走生命，调查员别无选择，只能将这份危险的战利品直接送回首都。"},{t="奶酪商人的真实行当",b="回到暴风城的贸易区，当你返回时，奶酪大师埃林·提亚斯立刻卸下了他售卖乳制品的伪装。作为王国秘密情报网的关键联络人，提亚斯仔细研读了记事本的内容。这绝非简单的强盗通讯，文件揭示了迪菲亚潜行者精心策划、协调一致的行动，以及一个不祥的代号：“拳头”。这位失踪的外交官显然是被一个细致入微、关系网深厚，且触角深入王国腹地的组织作为了目标。"}},faq={{q="什么是迪菲亚记事本？",a="迪菲亚记事本是在暮色森林中找回的一份复杂且敏感的文件，概述了迪菲亚潜行者的计划。其内容错综复杂，足以令当地守夜人感到恐惧，并为提亚斯大师寻找失踪王室外交官的下落提供了新的线索。",al={"迪菲亚记事本","这些文件是什么","记事本内容"}},{q="为什么守夜人巴库斯如此害怕保留这份记事本？",a="巴库斯意识到，记事本中的信息远远超出了暮色森林守夜人的职权范围或能力范畴。他担心，如果他的指挥官或暴风城的高层发现他隐瞒或接触过国家级的阴谋情报，他可能会因叛国罪被绞死。",al={"巴库斯为什么害怕","守夜人巴库斯的恐惧"}},{q="为什么要将文件带给暴风城的一名奶酪店老板？",a="埃林·提亚斯表面上是一名普通的奶酪商人，但实际上他是暴风城最能干的情报头子之一，也是王国地下情报网中的关键人物。他拥有解读迪菲亚计划所需的密码破译技能、人脉和政治觉悟。",al={"为什么是埃林·提亚斯","为什么提亚斯卖奶酪"}},{q="记事本中提到的“拳头”是谁？",a="在仔细阅读记事本后，埃林·提亚斯立刻认出了“拳头”这个名字。它是一个行动代号或别名，直接指向一个与迪菲亚潜行者和绑架阴谋有直接关联的个人。",al={"拳头是谁","迪菲亚的拳头","拳头代号"}},{q="这项调查接下来会指向哪里？",a="提亚斯利用从记事本中揭露的新细节进一步追踪阴谋者，并派你去询问联络人并追查神秘的“拳头”，以找出被绑架的外交官被带往了何处。",al={"下一步","记事本之后该做什么","我接下来去哪"}},{q="这与瓦里安·乌瑞恩国王有什么关系？",a="记事本中没有任何地方提到过国王。在官方记录中，你是在寻找一名从未抵达塞拉摩的无名外交官，而提亚斯所阅读的文件也没有揭示目标究竟是谁。",al={"瓦里安是那位外交官吗","瓦里安国王的关联"}}},fp="20,114,29.375.0,27.406.1,26.238.0,51.235.0,56.198.0,38.139.0,40.153.0,49.190.1"}
P.entries["quest:1246"] = {n="失踪的使节",s="这项任务指引调查者深入Old Town，去对付一名与可疑文件有关的街头恶霸。在奶酪商人埃林·提亚斯的指引下，你必须找到达舍尔·石拳，并用尽一切手段从他口中撬出答案。关于失踪外交官的线索正在迅速从宫廷阴谋转变为暴风城的地下势力。",h="这项任务指引调查者深入Old...",kw={"达舍尔·石拳","埃林·提亚斯","拳头","失踪的外交官","old town","暴风城"},ang={["class:Rogue"]="在Old Town活动，并与像提亚斯这样的线人和像石拳这样的暴徒打交道，让潜行者在暴风城的阴影之下感觉如鱼得水。",["faction:Alliance"]="揭开失踪外交官背后的阴谋对于稳定联盟以及作为其核心的王国至关重要。",["race:Human"]="对于暴风城的人类来说，这条线索是一个令人不安的证据，证明当地的街头渣滓正在积极参与针对王国领导层的叛国阴谋。"},sec={{t="Old Town的线索",b="在检查了与失踪外交官有关的加密笔记和线索后，提亚斯大师回想起了一个与此行动有关的关键人物：一名粗野的街头斗士，名叫达舍尔·石拳，俗称“拳头”。石拳并不在Cathedral Square与贵族们混在一起，而是经常出没于Old Town狭窄的小巷中。追踪他代表了调查工作首次从Stormwind Keep的宏伟殿堂转向城市犯罪圈的实际线索。"},{t="拳头之下的说服",b="埃林·提亚斯很清楚，像达舍尔这样的人是不会轻易对好奇的陌生人开口的，尤其是在涉及叛国和绑架的情况下。他的指示很直接：如果礼貌的盘问行不通，那就得用暴力来解决问题。石拳认为小巷是他的领地，他不欢迎外人插手那些可能让他丢掉饭碗甚至性命的事情。"}},faq={{q="达舍尔·石拳是谁？",a="达舍尔·石拳是一个臭名昭著的斗士，经常在暴风城Old Town的中心小巷里游荡。提亚斯认定他是与在搜寻失踪外交官期间发现的罪证文件有关的中间人。",al={"达舍尔·石拳","谁是“拳头”","达舍尔"}},{q="我在哪里可以找到达舍尔·石拳？",a="达舍尔·石拳徘徊在Old Town，位于该区中心附近的户外，经常在远离主街道的小巷里游荡。",al={"达舍尔·石拳的位置","达舍尔在哪里","石拳在哪里"}},{q="埃林·提亚斯为什么要派我去对付他？",a="提亚斯将达舍尔的名字直接与有关国王特使失踪的文件联系起来。达舍尔卷入得很深，他一定知道有关是谁策划了这次绑架的名字、地点或命令。",al={"为什么要与达舍尔战斗","提亚斯的原因"}},{q="达舍尔会主动配合吗？",a="不会。石拳对插手他私人事务的陌生人表现出直接的敌意。提亚斯预料到了这种顽固，建议你使用武器或重拳来强迫他开口。",al={"达舍尔会开口吗","石拳友好吗"}},{q="找到达舍尔之后会发生什么？",a="与达舍尔对峙必然会导致一场斗殴。一旦被制服，他会透露有关外交官绑架案幕后运作网络的进一步线索，并将你引向王国内的其他阴谋者。",al={"失踪外交官的下一步","对付达舍尔之后"}},{q="任务中提到的失踪外交官是谁？",a="官方说法是，暴风城当局只提到了一位在前往塞拉摩会见Jaina Proudmoore途中失踪的无名外交官。在调查的这个阶段，这位特使的真实身份仍然是一个严守的秘密。",al={"谁是失踪的外交官","哪位外交官"}}},fp="20,224,18.321.0,22.325.1,24.187.0,34.104.0,41.157.0,32.155.0,34.173.1,51.213.2"}
P.entries["quest:1247"] = {n="失踪的使节",s="调查暴风城失踪特使的这一环节，紧随你在Old Town对达舍尔·石拳的审讯之后。在从这名暴徒口中逼出供词后，你将劫持计划的备用方案告知了伪装成奶酪大师的间谍首领，埃林·提亚斯。",h="调查暴风城失踪特使的这一环节，紧随你在Old Town对达舍尔·石拳的审讯之后。在从这名暴徒口中逼出供词后，你将劫持计划的备用方案告知了伪装成奶酪大师的间谍首领，埃林·提亚斯。",kw={"腐草农场","达舍尔·石拳","埃林·提亚斯","米奈希尔港","失踪的外交官","瘦子","暴风城"},ang={["class:Rogue"]="对于一名暗影特工来说，在达舍尔这类巷弄打手和提亚斯这样的间谍首领之间进行协调，凸显了普通街头犯罪与高风险国家机密之间的界限。",["faction:Alliance"]="查明特使失踪真相对于整个联盟的稳定至关重要，因为高层的蓄意破坏威胁到了暴风城的领导层。",["race:Human"]="这场阴谋直接在首都境内展开，证明了当幼王坐在王座上时，叛乱已经在暴风王国内部滋生。"},sec={{t="墙上的裂痕",b="达舍尔·石拳不是那种会把秘密带进坟墓的特工，尤其是当他意识到自己的性命受到威胁时。在Old Town的一条小巷里被逼入绝境后，达舍尔屈服了，并承认他在绑架案中的角色随着阴谋者最初计划的失败而土崩瓦解。为了推卸责任，他指出了几周前在暮色森林的腐草农场举行的一次秘密会议，并为他们的备用行动提供了一条线索：一个在米奈希尔港活动的内部人员，只知道叫“瘦子”。"},{t="向奶酪商汇报",b="埃林·提亚斯在Trade District的提亚斯奶酪店柜台后保持着低调的形象，但他的真正职业是为皇室收集秘密。当你从达舍尔口中逼问出细节时，提亚斯正在查阅有关该阴谋的截获通讯。达舍尔的供词与书面情报相吻合：目标是一位未具名的外交官，最初的伏击行动失败了，随后启动了经由湿地的应急方案。掌握了“瘦子”这个名字后，搜索行动从暴风城的阴暗小巷向北移向了沼泽。"}},faq={{q="谁是达舍尔·石拳？",a="达舍尔·石拳是一名在暴风城Old Town活动的当地打手和中间人。他卷入了与迪菲亚兄弟会有关的地下势力，曾是最初绑架暴风城特使计划中的底层爪牙，在遭到质询时转而成为告密者。",al={"达舍尔·石拳","谁是达舍尔","石拳 暴风城"}},{q="为什么埃林·提亚斯会参与这项调查？",a="虽然公开身份是精品奶酪大师，但埃林·提亚斯其实是暴风城的一名资深情报特工。他利用在Trade District的店铺作为掩护，协调那些需要超出官方城市卫队保密权限的秘密调查。",al={"为什么 埃林·提亚斯","奶酪商 间谍","提亚斯 情报"}},{q="腐草农场发生了什么？",a="腐草农场是暮色森林西部的一处废弃农场，阴谋者在最初的计划受阻后，于几周前在那里集会以协调他们的绑架方案。",al={"腐草农场 会议","腐草农场","西部荒野 会议"}},{q="他们试图绑架的外交官是谁？",a="官方文件和街头暴徒只将目标称为一名前往塞拉摩的未具名外交官。在调查的现阶段，这位特使的真实身份仍然是一个严守的秘密。",al={"谁是失踪的外交官","谁被绑架了","外交官身份"}},{q="谁是“瘦子”？",a="“瘦子”是达舍尔·石拳指认的联络人，负责在湿地的米奈希尔港执行“B计划”，代表了阴谋者的第二物流路线。",al={"谁是瘦子","瘦子 米奈希尔港","米奈希尔港 联络人"}},{q="之后线索指向何处？",a="有了“瘦子”这个名字和埃林·提亚斯的证实，调查转向北方的湿地港口城镇米奈希尔港，以追捕这名联络人。",al={"失踪外交官 下一步","达舍尔之后去哪","接下来做什么"}}},fp="20,159,19.362.0,25.420.1,24.204.0,51.178.0,31.154.0,47.196.2,12.204.0,37.127.0"}
P.entries["quest:1248"] = {n="失踪的使节",s="“失踪的外交官”是一项旨在追查暴风城一名无名特使被绑架案的调查任务。顺着一份截获的卷宗提供的线索，特工们前往湿地的米奈希尔港，拜访一位退休的联络人并追踪一名叫Slim的嫌疑人。",h="“失踪的外交官”是一项旨在追查暴风城一名无名特使被绑架案的调查任务。顺着一份截获的卷宗提供的线索，特工们前往湿地的米奈希尔港，拜访一位退休的联络人并追踪一名叫Slim的嫌疑人。",kw={"卷宗","米奈希尔港","mikhail","slim","暴风城","失踪的外交官","提亚斯","湿地"},ang={["class:Rogue"]="解密秘密卷宗、追踪退休联络人、在拥挤的酒馆里秘密审讯嫌疑人，这些都是隐秘行动的专业手段。",["faction:Alliance"]="对被绑架外交官的调查直接触及了暴风城内部的高层安全事务，以及阴谋者在联盟领土各处的影响力。"},sec={{t="通往湿地的线索",b="对这位被绑架外交官的调查将视线从暴风城的大门引向了湿地迷雾笼罩的米奈希尔港码头。一份截获的卷宗证实了一名外交官确实遭到了针对并被带走，但其中留下了关键的空白：在这份找回的文件中，既没有详细说明外交官的真实身份，也没有说明阴谋者最终的目的地。为了打破沉默，调查人员必须深入港口那变幻莫测的人群和隐秘的交易中进行探查。"},{t="米奈希尔的秘密联络人",b="为了在米奈希尔寻得线索，特工们被派去寻找Mikhail，他是埃林·提亚斯的一位前同事，几年前从暴风城退休，现在经营着当地酒馆的酒水生意。Mikhail是找到一个只被称为Slim的人物的关键桥梁，此人可能知道人质被带去了哪里，或是谁策划了这次绑架。在拥挤的酒馆里，谨慎至关重要——提到提亚斯的名字足以引起立即的安静，以免阴谋者察觉到这次调查。"}},faq={{q="Mikhail是谁？",a="Mikhail是埃林·提亚斯的一位前同事，几年前离开暴风城并在米奈希尔港退休，现在是一名酒保。提亚斯将他推荐给调查人员，认为他是一位值得信赖的联络人，能够帮助确定一位名叫Slim的嫌疑人。",al={"mikhail是谁","mikhail 湿地","米奈希尔酒保"}},{q="Slim是谁？为什么要找他？",a="Slim是米奈希尔港的一位人物，据信掌握着关于被绑架外交官的关键信息。特工们专门联系Mikhail，就是为了追踪Slim并确定他掌握的情况。",al={"slim是谁","寻找slim","失踪的外交官 slim"}},{q="被绑架的外交官是谁？",a="这位外交官的身份仍然严加保密，即使对调查人员来说也是个谜。那份截获的卷宗描述了绑架事件，但既没有说明外交官的真实身份，也没有说明阴谋者在得手后的后续计划。",al={"谁被绑架了","被绑架的外交官身份","失踪的外交官是谁"}},{q="为什么线索会指向米奈希尔港？",a="米奈希尔港是位于湿地海岸的一个主要港口城镇。调查人员被指引到那里，是因为提亚斯退休的联络人Mikhail在该镇经营酒馆，且有关此次绑架案的关键线索都指向了该港口。",al={"米奈希尔港在哪","为什么去湿地","为什么去米奈希尔"}},{q="卷宗揭示了什么阴谋？",a="这份卷宗是一份概述外交官绑架案的截获文件。虽然它证实了绑架事件，但其中有明显的漏洞，没有提及人质被带往何处，以及绑架者下一步打算做什么。",al={"什么卷宗","提亚斯的卷宗","卷宗里说了什么"}},{q="提亚斯在这项任务中扮演了什么角色？",a="埃林·提亚斯是负责指导此次调查的暴风城联络人。他派特工去寻找Mikhail，因为Mikhail曾是他的老同事，曾承诺会仅凭他的信誉提供协助，且不会引起公众注意。",al={"谁派我们去找mikhail","提亚斯的关系","为什么提到提亚斯"}}},fp="20,269,23.454.0,29.468.1,15.250.0,45.197.0,30.232.0,43.237.0,43.215.0,44.214.0"}
P.entries["quest:1249"] = {n="失踪的使节",s="“失踪的外交官”是对一位重要暴风城特使失踪事件的详尽调查，线索从首都一路追踪至遥远的港口。在米奈希尔港，调查涉及了地下世界的各类人物，以及与暴风城情报网络有关的旧日特工。",h="“失踪的外交官”是对一位重要暴风城特使失踪事件的详尽调查，线索从首都一路追踪至遥远的港口。在米奈希尔港，调查涉及了地下世界的各类人物，以及与暴风城情报网络有关的旧日特工。",kw={"埃林·提亚斯","米奈希尔港","失踪的外交官","斯林","暴风城","湿地"},ang={["class:Rogue"]="像埃林·提亚斯这样的地下特工和操盘手依靠安静的跑腿工作和街头联络人来追踪那些漏网之鱼。",["faction:Alliance"]="对失踪外交官的调查将联盟冒险者卷入了连接暴风城政治圈与湿地码头的黑暗地下世界。"},sec={{t="米奈希尔港的暗流",b="对暴风城失踪特使的搜寻将调查者带到了首都以北遥远的湿地，抵达了阴冷潮湿的米奈希尔港。在小镇繁忙的码头和饱经风霜的旅店背后，隐藏着一股暗流，许多行径可疑的商人和秘密走私者就在当地卫兵的眼皮底下活动。要沿着这条沿海枢纽追踪线索，就必须直接与那些了解联盟领地黑暗面的人打交道。"},{t="熟悉的潜行者",b="抓住斯林（Slim）使搜寻工作取得了惊人的突破，当地线人完全没想到他会直接卷入这起事件。虽然这次抓捕提供了关键答案，但也勾起了那些在湿地隐居的退役特工的回忆，他们必须在协助王室与被卷回暴风城复杂的地下世界之间做出权衡。"}},faq={{q="斯林是谁？",a="斯林是米奈希尔港的一名可疑联络人，在调查失踪外交官期间被捕，这让没料到他会卷入其中的当地联络人大吃一惊。",al={"斯林是谁","斯林 失踪的外交官","抓住斯林"}},{q="埃林是谁？",a="埃林·提亚斯是暴风城内的一位影响力人物，在联盟各地经营着一个由前潜行者和线人组成的地下网络。",al={"埃林·提亚斯","埃林是谁","埃林 暴风城"}},{q="这段调查发生在什么地方？",a="这段调查发生在米奈希尔港，这是湿地的一个港口城镇，连接着铁炉堡王国与远方的海岸以及暴风城的贸易路线。",al={"发生在哪里","米奈希尔港 失踪的外交官","湿地 外交官"}},{q="“失踪的外交官”任务链讲的是什么？",a="“失踪的外交官”是对一位重要暴风城特使失踪事件的调查，追踪范围涵盖了整个王国及更远地区的秘密特工、阴谋分子和地下世界联络人。",al={"什么是失踪的外交官","失踪的外交官任务","谁失踪了"}},{q="为什么联络人警告不要向埃林提及此事？",a="米奈希尔港的联络人曾与埃林·提亚斯在暴风城的地下圈子里共事过，他不想让埃林知道他怀念过去的生活，以免被召回首都。",al={"为什么提到埃林","提亚斯奶酪","埃林·提亚斯关联"}},{q="米奈希尔港的调查发生了什么？",a="在将线索追踪至湿地的米奈希尔港后，调查者成功将斯林抓获，证实了当地关于镇内存在非法地下活动的猜疑。",al={"米奈希尔港发生了什么","米奈希尔线索","抓获斯林"}}},fp="20,289,32.416.0,16.383.1,12.174.0,14.161.0,53.170.0,47.197.0,60.197.0,56.180.0"}
P.entries["quest:125"] = {n="丢失的工具",s="随着湖畔镇在敌对势力的压力下苦苦支撑，城镇的维护和防御工作完全依赖当地劳动力。工头奥斯洛从闪金镇运来的必需工具，在黑石兽人的投石车击沉了他的运输船后，掉进了止水湖。从湖底找回沉没的宝箱，对于修复这座城镇断裂的桥梁至关重要。",h="随着湖畔镇在敌对势力的压力下苦苦支撑，城镇的维护和防御工作完全依赖当地劳动力。工头奥斯洛从闪金镇运来的必需工具，在黑石兽人的投石车击沉了他的运输船后，掉进了止水湖。从湖底找回沉没的宝箱，对于修复这座城镇断裂的桥梁至关重要...",kw={"投石车","工头奥斯洛","闪金镇","止水湖","湖畔镇","鱼人","赤脊山","淡水猛鱼","工具箱"},ang={["faction:Alliance"]="湖畔镇是联盟抵御黑石氏族的东部堡垒；确保平民建筑工人拥有必要的装备，对于维持暴风城王国的边境至关重要。",["profession:Blacksmithing"]="在被围困的条件下，打造高质量的工具难上加难，因此找回从闪金镇运来的专业锻造和建筑工具对该镇来说不可或缺。"},sec={{t="出岔子的运输",b="由于大桥被毁，湖畔镇与艾尔文森林的生命线已被切断。当一船从闪金镇运来的替换石匠和木工工具经由陆路运抵时，它们无法直接穿过进入城镇。工人们将物资转运到小船上，试图横渡止水湖，结果却直接遭到了黑石兽人投石车的袭击。船只被炸得粉碎，奥斯洛沉重的铁皮工具箱直接沉入了深邃的湖底。"},{t="深水区的危险",b="打捞工具箱比普通的潜水要危险得多。止水湖的浅滩上盘踞着好战的鱼人部落，而凶猛的淡水猛鱼则在浑浊的深水中四处游弋。尽管危机四伏，如果工头奥斯洛想要恢复桥梁修复工作并防止湖畔镇彻底沦为废墟，找回这些工具是必不可少的。"}},faq={{q="为什么这些工具一开始要通过船只运输？",a="通往湖畔镇的主干道需要跨过一座横跨止水湖的石桥，但黑石兽人炸毁了桥梁的一大段。由于来自闪金镇的补给马车无法通行，工人们不得不卸下工具，试图通过水路运送过去。",al={"为什么要用船","工具是怎么沉没的","为什么要水路运输"}},{q="船是怎么沉没的？",a="在横渡湖泊时，运输船遭到了黑石兽人的炮火攻击，一发从周围高地上发射的投石车炮弹直接击中了船只，导致船只和货物瞬间沉入湖底。",al={"是谁摧毁了船","船是怎么被击中的"}},{q="工头奥斯洛是谁？",a="工头奥斯洛是湖畔镇的总建筑师和监工。他负责城镇的公共工程和民用设施维护，目前最紧迫的任务就是重建那座被毁的桥梁。",al={"工头奥斯洛","奥斯洛的角色"}},{q="止水湖里有什么威胁？",a="湖中到处是盘踞在岸边和废墟附近的敌对鱼人部落，还有在开阔水域和深水区捕食的凶残肉食性淡水猛鱼。",al={"湖里有什么","湖中怪物","止水湖的危险"}},{q="为什么湖畔镇如此急需这些工具？",a="湖畔镇实际上正处于被围困的状态，与及时的援军和定期的补给彻底断绝了联系。没有趁手的工具，奥斯洛就无法重建桥梁，也无法修复抵御兽人和豺狼人进攻所需的防御工事。",al={"为什么工具很重要","桥梁修复工具"}},{q="任务接下来会引导去哪里？",a="一旦工具箱被找回，工头奥斯洛会招募冒险者去收集修复大桥所需的原材料，任务会接续到下一个任务：止水桥。",al={"下一个任务","失落的工具之后"}}},fp="14,216,20.377.0,19.257.0,51.207.0,22.156.0,21.162.0,35.134.0,45.204.0,31.158.1"}
P.entries["quest:1250"] = {n="The Missing Diplomat",s="迪菲亚同谋 Jahn 称，暴风城国王在船上失踪。寻找绑架国王的人的行动仍在继续，你被派往湿地找 Mikhail。",h="迪菲亚同谋 Jahn 称，暴风城国王在船上失踪。寻找绑架国王的人的行动仍在继续，你被派往湿地找 Mikhail。",kw={"迪菲亚","hendel","jahn","jaina proudmoore","mikhail","暴风城国王","失踪的外交官","塞拉摩","湿地"},sec={{t="证人开口",b="Jahn 称，船停泊时，迪菲亚让一个名叫 Hendel 的人登上了国王的船。国王原本要前往塞拉摩会见 Jaina Proudmoore，而 Jahn 认为迪菲亚还与其他人勾结。寻找 Hendel 的行动就此开始，你受命前往湿地与 Mikhail 谈谈。"},{t="Mikhail 的回应",b="Mikhail 得知国王失踪后大吃一惊，并派人通知 Elling。他说自己从未料到 Jahn 会为了钱背叛暴风城，并表示愿意帮忙寻找 Hendel。"}},faq={{q="Jahn 是谁？",a="Jahn 是一名迪菲亚同谋，曾帮忙让 Hendel 登上国王的船。",al={"jahn 是谁","谁是 jahn","迪菲亚 jahn"}},{q="Hendel 是谁？",a="Hendel 就是 Jahn 所说被他安排登上国王船只的人。",al={"hendel 是什么人","hendel 是谁","国王船上的人"}},{q="国王遭遇了什么？",a="Jahn 称，船停泊时，迪菲亚把国王从船上带走了。",al={"国王在哪","暴风城国王失踪","国王被绑架"}},{q="国王为何要前往塞拉摩？",a="国王正前往塞拉摩会见 Jaina Proudmoore。",al={"国王 塞拉摩","会见 jaina","为何去塞拉摩"}},{q="Jahn 称除了迪菲亚，还有谁参与其中？",a="Jahn 认为迪菲亚与其他人勾结，但他说自己不知道那人是谁。",al={"谁与迪菲亚勾结","迪菲亚同伙","还有谁参与"}},{q="Mikhail 是谁？",a="Mikhail 是受命让你前往湿地会见的人；他愿意帮忙寻找 Hendel。",al={"湿地 mikhail","mikhail 是谁","找 mikhail 谈话"}}},fp="20,170,16.286.0,18.167.1,12.74.0,14.61.0,26.69.0,36.62.0,49.87.0,15.97.0"}
P.entries["quest:1251"] = {n="黑色盾牌",s="树荫旅店已被烧毁，仅存的部分中包括一座摇摇欲坠的烟囱。一面被火焰熏黑的盾牌嵌在砖墙上。你应该把这面盾牌拿去给蕨墙村的克罗格看看。",h="树荫旅店已被烧毁，仅存的部分中包括一座摇摇欲坠的烟囱。一面被火焰熏黑的盾牌嵌在砖墙上。你应该把这面盾牌拿去给蕨墙村的克罗格看看。",kw={"黑色盾牌","被熏黑的铁盾牌","蕨墙村","尘泥沼泽","克罗格","树荫旅店"},sec={{t="烟囱上的盾牌",b="大火吞噬了树荫旅店，几乎没有留下什么东西。在摇摇欲坠的烟囱上嵌着一面被烧得漆黑的铁盾，你可以把它从砖块里撬出来。你应该把它带给蕨墙村的克罗格，他会问这算不算旅店废墟里的证据。"},{t="克罗格的看法",b="克罗格承认人类的装饰品味确实古怪，但他怀疑没人会把一面普通的铁盾挂在壁炉上方。克罗格怀疑放火烧毁旅店的人留下了它，或许是一种警告或威胁。"}},faq={{q="黑色盾牌在哪里可以找到？",a="它嵌在烧毁的树荫旅店的烟囱上，那是该建筑为数不多的残留物之一。",al={"黑色盾牌位置","盾牌在哪里","树荫旅店盾牌"}},{q="谁需要这面盾牌？",a="蕨墙村的克罗格，你应该把它带给他。",al={"谁想要黑色盾牌","盾牌交还地点","克罗格位置"}},{q="这面盾牌可以从烟囱上取下来吗？",a="是的，可以从烟囱的砖块里把它撬下来。",al={"可以取下盾牌吗","从烟囱取下盾牌"}}},fp="16,209,23.289.0,21.211.1,32.97.0,20.56.0,41.53.0"}
P.entries["quest:1252"] = {n="帕瓦尔·雷瑟上尉",s="废墟下有什么东西在闪光：一枚带有塞拉摩标志的徽章，上面是一个金色的锚，背景是白色珐琅，锚下方刻着Lieutenant Paval Reethe的名字。应该把它带给塞拉摩的盖兰·维米斯队长。",h="废墟下有什么东西在闪光：一枚带有塞拉摩标志的徽章，上面是一个金色的锚，背景是白色珐琅，锚下方刻着Lieutenant Paval Reethe的名字。应该把它带给塞拉摩的盖兰·维米斯队长。",kw={"尘泥沼泽","盖兰·维米斯","paval reethe","树荫旅店","塞拉摩卫兵徽章"},sec={{t="废墟中的闪光",b="废墟下有什么东西在闪光。拂去灰烬和碎片，露出一枚徽章，上面显示着塞拉摩的标志，下方刻着Lieutenant Paval Reethe的名字。塞拉摩的盖兰·维米斯队长应该看看这个，他会问在树荫旅店的废墟里发现了什么。"},{t="队长的回复",b="维米斯说，送来卫兵的徽章从来都不是什么好消息。有些卫兵战死沙场，维米斯必须把消息带给他们悲伤的家人。而对另一些人来说，没人知道他们经历了什么，有时真相甚至更加残酷。"}},faq={{q="徽章是在哪里发现的？",a="它躺在废墟下，被灰烬和碎片覆盖。盖兰·维米斯队长会问在树荫旅店的废墟里发现了什么。",al={"徽章位置","哪里找到reethe的徽章","树荫旅店徽章"}},{q="徽章上写着谁的名字？",a="刻在锚下方的名字是Lieutenant Paval Reethe。",al={"paval reethe是谁","徽章上的名字","谁丢失了徽章"}},{q="谁来接收这枚徽章？",a="塞拉摩的盖兰·维米斯队长应该看看它。",al={"我该把徽章交给谁","哪里上交徽章","盖兰·维米斯队长的位置"}},{q="这枚徽章是什么样子的？",a="白色珐琅上的金色锚，那是塞拉摩的标志。",al={"塞拉摩标志","卫兵徽章外观","徽章长什么样"}}},fp="23,231,21.283.0,19.235.1,25.129.0,27.64.0,19.57.0,30.64.0"}
P.entries["quest:1253"] = {n="黑色盾牌",s="一面被火焰熏黑的铁盾牌被固定在烧毁的树荫旅店那摇摇欲坠的烟囱上。塞拉摩的盖兰·维米斯队长正在等待来自旅店遗址的证据。",h="一面被火焰熏黑的铁盾牌被固定在烧毁的树荫旅店那摇摇欲坠的烟囱上。塞拉摩的盖兰·维米斯队长正在等待来自旅店遗址的证据。",kw={"黑色盾牌","烟囱","尘泥沼泽","盖兰·维米斯","铁盾牌","树荫旅店","塞拉摩"},sec={{t="烟囱上的盾牌",b="树荫旅店被烧毁了，仅存的几处残垣断壁中就包括一座摇摇欲坠的烟囱。一面被火焰熏黑的铁盾牌嵌在砖墙上，可以将其取下。塞拉摩的盖兰·维米斯队长需要来自旅店遗址的证据。"},{t="队长的结论",b="维米斯说他并不是制造武器盔甲的专家，他只了解如何使用它们。在队长看来，除了火烧留下的痕迹之外，这面盾牌和普通的盾牌没什么两样。"}},faq={{q="黑色盾牌在哪里？",a="固定在烧毁的树荫旅店仅存的残垣断壁中，那座摇摇欲坠的烟囱的砖墙上。",al={"盾牌在哪里","黑色盾牌位置","寻找黑色盾牌"}},{q="谁想要树荫旅店的证据？",a="塞拉摩的盖兰·维米斯队长，他正在等待来自旅店废墟的证据。",al={"谁想要盾牌","树荫旅店调查员","盖兰·维米斯是谁"}}},fp="16,176,23.234.0,21.178.1,34.109.0,43.86.0"}
P.entries["quest:1258"] = {n="还有螃蟹！",s="塞拉摩的摩根·斯登正在研究一种食谱，这种菜肴有望成为暴风城下一道风靡一时的美食。他已经弄到了泥石舌头，接下来这道菜需要用到巨型蟹的甲壳腿，而且必须是完好无损、没有任何疤痕的。",h="塞拉摩的摩根·斯登正在研究一种食谱，这种菜肴有望成为暴风城下一道风靡一时的美食。他已经弄到了泥石舌头，接下来这道菜需要用到巨型蟹的甲壳腿，而且必须是完好无损、没有任何疤痕的。",kw={"蟹腿","尘泥沼泽","摩根·斯登","泥石汤和虫子","无瑕的蟹腿","暴风城","塞拉摩","悲伤沼泽"},sec={{t="无暇的蟹腿",b="摩根·斯登希望蟹腿的甲壳能成为这道菜外观的关键部分，因此每一条蟹腿都必须完美无瑕。一只成年蟹身上可能只有一两条这样的腿，而研究工作需要大量的蟹腿。尘泥沼泽的泥壳蟹并不适合。只有远在悲伤沼泽的螃蟹才能符合要求，所以你得出发去一趟了。"}},faq={{q="谁是摩根·斯登？",a="摩根·斯登正在塞拉摩研究一种新食谱，这道菜有望成为暴风城下一道风靡一时的美食。",al={"谁是摩根·斯登","摩根·斯登 塞拉摩","谁发布了虫子任务"}},{q="蟹腿从哪儿来？",a="不是来自尘泥沼泽，那里的泥壳蟹不适合做这道菜。摩根·斯登指出，远在悲伤沼泽的螃蟹才符合他的要求。",al={"哪里找蟹腿","多刺岩蟹在哪里","蟹腿位置"}},{q="为什么蟹腿必须完好无损？",a="甲壳是菜肴摆盘的关键部分，所以摩根·斯登要求蟹腿上不能有疤痕。",al={"为什么需要无瑕的蟹腿","为什么需要无疤痕的腿","蟹腿摆盘"}},{q="这个任务的前置任务是什么？",a="这是继“泥石汤和虫子”之后的任务，那是你为摩根·斯登的新食谱所做的第一部分工作。",al={"前置任务 虫子","泥石汤和虫子 前置任务"}}},fp="12,255,22.357.0,20.104.0,33.152.0,41.103.0,29.99.0"}
P.entries["quest:1259"] = {n="帕瓦尔·雷瑟上尉",s="盖兰·维米斯队长没听说过帕瓦尔·雷斯中尉这个名字，他让你去找塞拉摩的泰索兰副官，此人负责保管塞拉摩卫队的记录。",h="盖兰·维米斯队长没听说过帕瓦尔·雷斯中尉这个名字，他让你去找塞拉摩的泰索兰副官，此人负责保管塞拉摩卫队的记录。",kw={"泰索兰副官","盖兰·维米斯队长","尘泥沼泽","帕瓦尔·雷斯","塞拉摩"},sec={{t="谁是雷斯？",b="盖兰·维米斯队长对帕瓦尔·雷斯中尉这个名字毫无印象。泰索兰副官保管着塞拉摩卫队的记录，包括人员和装备信息，维米斯认为查阅这些记录就能查明雷斯的身份。"}},faq={{q="是谁派你去调查雷斯的？",a="盖兰·维米斯队长，他没听说过帕瓦尔·雷斯中尉这个名字。",al={"谁开启了帕瓦尔·雷斯任务","雷斯任务发布者","谁发布了雷斯任务"}},{q="谁保管着塞拉摩卫队的记录？",a="塞拉摩的泰索兰副官，他保管着卫队的人员和装备记录。",al={"泰索兰副官在哪里","塞拉摩记录官","谁有卫队记录"}},{q="泰索兰副官能告诉你什么？",a="维米斯认为泰索兰的记录能查明雷斯的身份。",al={"泰索兰知道什么","泰索兰记录"}}},fp="23,173,14.240.0,39.78.0,40.88.0,35.52.0"}
P.entries["quest:126"] = {n="群山中的嚎叫",s="“山中哀嚎”是一个联盟悬赏任务，由湖畔镇的弗纳·奥斯古发布，要求玩家猎杀犹勒——那个率领赤脊山豺狼人的凶残首领。由于暴风城的军队忙于对抗黑石兽人，无暇顾及本地边境，湖畔镇只能依靠路过的冒险者来瓦解豺狼人部落的指挥系统。",h="“山中哀嚎”是一个联盟悬赏任务，由湖畔镇的弗纳·奥斯古发布，要求玩家猎杀犹勒——那个率领赤脊山豺狼人的凶残首领。由于暴风城的军队忙于对抗黑石兽人，无暇顾及本地边境，湖畔镇只能依靠路过的冒险者来瓦解豺狼人部落的指挥系统。",kw={"黑石","豺狼人","湖畔镇","爪子","赤脊山","暴风城军队","弗纳·奥斯古","犹勒"},ang={["class:Hunter"]="在山中巢穴追踪像犹勒这样的强大首领，需要对领地标记和部落习性有敏锐的观察力。",["class:Warrior"]="挑战犹勒意味着要面对一个仅凭纯粹的肉体力量统治其残暴部族的对手，这需要与蛮力进行直接的碰撞。",["faction:Alliance"]="湖畔镇依赖雇佣兵而非皇家士兵，揭示了当前削弱暴风城王国的行政压力。"},sec={{t="高地之声",b="即使清理了袭击湖畔镇周围道路的低级豺狼人，它们不祥的叫声依然在赤脊山的山脊间回荡。作为湖畔镇勤勉的马蹄铁匠，弗纳·奥斯古明白，只要首领还活着，杀掉再多的斥候和拾荒者也无济于事。凌驾于这群乌合之众之上的是犹勒，一只格外狡猾且体型巨大的豺狼人，正是它的号叫指挥着整个部落穿行在山丘之间。弗纳委托冒险者去猎杀这头野兽，并带回它的爪子，以确保哀嚎声能够彻底平息。"},{t="被军队遗弃的城镇",b="这份契约突显了暴风城王国东部边境所面临的严峻现实。随着国王瓦里安·乌瑞恩的失踪以及摄政王位的争端使最高指挥部陷入瘫痪，皇家士兵几乎把全部精力都集中在北方的黑石兽人氏族身上。像湖畔镇这样的普通定居点在面对豺狼人等本土威胁时完全处于无人防守的状态，迫使像弗纳·奥斯古这样的镇民不得不自己发布悬赏，以防家园被侵占。"}},faq={{q="犹勒是谁？",a="犹勒是盘踞在湖畔镇外山丘上的赤脊山豺狼人的凶猛首领。弗纳·奥斯古指出，犹勒比普通的杂种豺狼人更强壮、更危险，它作为统一的阿尔法首领，指挥着部落袭击过往的旅客和当地的农庄。",al={"犹勒","豺狼人首领是谁","犹勒背景故事","犹勒豺狼人"}},{q="为什么是弗纳·奥斯古而不是镇长发布悬赏？",a="湖畔镇的官方领导层和当地民兵已被不断逼近的黑石兽人完全压制。弗纳·奥斯古是一位当地的工匠和马厩管理员，他的生计依赖于道路的畅通，因此他经常挺身而出，雇佣流浪的雇佣兵来消除紧迫的局部威胁。",al={"为什么是弗纳","为什么不是所罗门镇长","为什么奥斯古在雇人"}},{q="本应保护湖畔镇的暴风城士兵在哪里？",a="暴风城的常备军被调往他处。军队在赤脊山的兵力被限制在监视和遏制山中更深处的黑石氏族兽人，这使得镇民在面对当地的野生动物、鱼人和豺狼人时得不到任何支持。",al={"军队在哪里","为什么没有暴风城卫兵","暴风城军队湖畔镇"}},{q="犹勒死后，赤脊山的豺狼人会怎样？",a="击杀犹勒会打散豺狼人部落的指挥结构，减弱它们对城镇边境协同袭击的能力。然而，豺狼人依然是赤脊山崎岖高地上一群顽固且持续存在的麻烦。",al={"豺狼人离开了吗","犹勒死后会发生什么"}},{q="这个契约有哪些前置任务？",a="该任务链始于弗纳·奥斯古派你去完成杂务，以在“鞋子的代价”和“回到弗纳处”中获得马具。在处理了腹部鳞片并在“豺狼人的嚎叫”中削减了它们的数量后，弗纳会交给你直接猎杀犹勒的悬赏。",al={"犹勒任务前置","解锁山中哀嚎","山中哀嚎任务链"}},{q="为什么弗纳需要犹勒的爪子作为证据？",a="针对危险野兽的悬赏在发放报酬前需要确凿的实物证据。带回犹勒被切下的爪子，可以向弗纳以及湖畔镇惶惶不安的居民证明，那头在山中回荡着恐怖嚎叫的野兽确实已经被除掉了。",al={"为什么要犹勒的爪子","犹勒的爪子证明"}}},fp="20,217,24.377.0,28.394.0,14.189.0,67.253.0,68.223.0,56.168.0,50.204.0,43.185.0"}
P.entries["quest:1260"] = {n="摩根·斯特恩",s="暴风城的蓝隐士旅店的安古斯·斯特恩正在筹备一份带有沼泽风味的全新乡村菜谱。安古斯的侄子摩根被派往塞拉摩收集当地人的食谱，安古斯希望能得到关于摩根目前发现的消息。",h="暴风城的蓝隐士旅店的安古斯·斯特恩正在筹备一份带有沼泽风味的全新乡村菜谱。安古斯的侄子摩根被派往塞拉摩收集当地人的食谱，安古斯希望能得到关于摩根目前发现的消息。",kw={"安古斯·斯特恩","沼泽","蓝隐士旅店","尘泥沼泽","摩根·斯特恩","暴风城","塞拉摩"},sec={{t="沼泽菜谱",b="安古斯·斯特恩相信蓝隐士旅店的顾客一定会喜欢带有沼泽风格的乡村菜肴。为了完成这份菜谱，安古斯把他的侄子摩根派往尘泥沼泽旁的城市塞拉摩，去收集当地人的食谱。这趟旅程对安古斯来说太远了，所以他需要像你这样的年轻旅者去和摩根谈谈。"},{t="摩根说了什么",b="当你找到塞拉摩的摩根·斯特恩时，听说他对食谱的研究已经有了一些眉目，但还需要人手去进行后续调查。这个帮手必须是个愿意弄湿双脚的人。"}},faq={{q="摩根·斯特恩是谁？",a="摩根·斯特恩是蓝隐士旅店的安古斯·斯特恩的侄子。摩根被派往塞拉摩去收集当地人的食谱。",al={"摩根·斯特恩是谁","摩根·斯特恩背景故事","安古斯·斯特恩的侄子"}},{q="为什么安古斯·斯特恩想联系摩根？",a="安古斯正在为蓝隐士旅店开发一份带有沼泽风味的全新乡村菜谱，他想知道摩根目前有什么发现。",al={"为什么要派往塞拉摩","蓝隐士旅店菜谱","安古斯·斯特恩任务"}},{q="在哪里可以找到摩根·斯特恩？",a="摩根就在塞拉摩，也就是尘泥沼泽旁的那座城市。",al={"摩根·斯特恩在哪里","摩根·斯特恩位置","塞拉摩厨师位置"}}},fp="12,248,12.334.0,22.195.1,20.126.0,42.135.0,32.57.0"}
P.entries["quest:1261"] = {n="玛尔格的嘱托",s="来自死后的玛格讲述了杀死它的泥壳蟹，以及一件尚未完成的职责。玛格请求你找到那只泥壳蟹，找回从联盟士兵那里偷来的珠宝吊坠，并将其交给蕨墙村的纳泽尔·血矛。",h="来自死后的玛格讲述了杀死它的泥壳蟹，以及一件尚未完成的职责。玛格请求你找到那只泥壳蟹，找回从联盟士兵那里偷来的珠宝吊坠，并将其交给蕨墙村的纳泽尔·血矛。",kw={"血矛","蕨墙","玛格","泥壳蟹","纳泽尔","吊坠","暴风城","塞拉摩"},sec={{t="玛格在塞拉摩附近看到了什么",b="在塞拉摩附近，玛格发现了在海滩上扎营的联盟士兵。其中一人戴着一枚镶满宝石的吊坠，其价值远超一个士兵所能承受的范围。那天晚上，玛格潜入营地偷走了它，但在返回基地的路上，被一个泥壳蟹人杀死了。现在，玛格请求你找到那只泥壳蟹，找回吊坠，并把它带给蕨墙村的纳泽尔。"},{t="纳泽尔对此事的看法",b="得知暴风城的士兵戴着这枚吊坠，纳泽尔感到十分震惊。你揭开了玛格死亡的秘密，但吊坠本身却成了一个新的谜团，纳泽尔警告说这可能会给联盟和部落双方都带来可怕的影响。"}},faq={{q="玛格是谁？它是怎么死的？",a="玛格从塞拉摩附近扎营的联盟士兵那里偷走了一枚珠宝吊坠，然后在返回基地的路上被一个泥壳蟹人杀死了。",al={"玛格是怎么死的","玛格是谁","玛格的故事"}},{q="这枚珠宝吊坠是从哪里来的？",a="它是由塞拉摩附近海滩上一个联盟营地里的士兵佩戴的，上面镶嵌的宝石远超一个士兵所能支付的价值。玛格在那天晚上潜入营地偷走了它。",al={"吊坠来自哪里","谁拥有这个吊坠","玛格吊坠的起源"}},{q="谁会接收找回来的吊坠？",a="蕨墙村的纳泽尔·血矛。",al={"谁来接收吊坠","我该把吊坠带到哪里","纳泽尔·血矛 吊坠"}},{q="这个任务之前是什么任务？",a="它紧接在“巨魔巫医”之后。",al={"前置任务","玛格的讲述之前是什么任务"}}},fp="11,244,28.373.0,23.234.1,33.139.0,40.162.0,35.41.0,38.33.0"}
P.entries["quest:1262"] = {n="向佐尔报告",s="纳泽尔·血矛觉得普通士兵带着玛格偷来的那条珠宝坠饰很奇怪。他认为这是贵族的饰品，于是让你带着它前往奥格瑞玛，把它交给精通联盟政治的佐尔·孤树。",h="纳泽尔·血矛觉得普通士兵带着玛格偷来的那条珠宝坠饰很奇怪。他认为这是贵族的饰品，于是让你带着它前往奥格瑞玛，把它交给精通联盟政治的佐尔·孤树。",kw={"蕨墙村","珠宝坠饰","玛格的讲述","纳泽尔·血矛","奥格瑞玛","向佐尔报告","暴风城","佐尔·孤树"},sec={{t="贵族的坠饰",b="纳泽尔·血矛觉得普通士兵持有这样的坠饰很奇怪。坠饰的主人可能当时经过伪装，或者这坠饰本身就是士兵偷来的。不管怎样，纳泽尔判定这是一条贵族的坠饰，如果想要解开这个谜团，就必须找到它真正的主人。在奥格瑞玛的佐尔·孤树对联盟的政治了解颇深，他应该能看出这枚坠饰是否属于暴风城的贵族。"},{t="佐尔的判断",b="佐尔·孤树赞叹着这枚坠饰所展现出的精湛工艺。佐尔说，兽人根本用不着这种珠宝，但很多人类却趋之若鹜。佐尔会找人研究它，并希望随着时间的推移，它的秘密终会水落石出。"}},faq={{q="为什么要将坠饰带到奥格瑞玛？",a="纳泽尔·血矛判断这是一条贵族的坠饰。在奥格瑞玛的佐尔·孤树对联盟的政治了解颇深，能够判断它是否在暴风城的贵族中有着一段历史。",al={"为什么把坠饰送到奥格瑞玛","为什么去奥格瑞玛","为什么找佐尔·孤树"}},{q="谁之前持有这枚珠宝坠饰？",a="玛格从塞拉摩附近一个联盟营地的士兵手中偷走了它。纳泽尔觉得普通士兵持有它很奇怪，并怀疑坠饰的主人当时经过了伪装，或者这些士兵本身就是小偷。",al={"谁持有坠饰","坠饰从哪来"}},{q="这个任务之前发生了什么？",a="它衔接在“玛格的讲述”之后，在该任务中，玛格讲述了从塞拉摩附近的驻扎士兵那里偷走坠饰的经过。",al={"前序任务","之前的任务是什么"}},{q="佐尔·孤树在哪里？",a="佐尔·孤树在奥格瑞玛。",al={"佐尔·孤树位置","佐尔·孤树在哪"}}},fp="13,227,17.410.0,13.218.1,44.177.0,39.189.0,28.100.0,22.29.0"}
P.entries["quest:1264"] = {n="The Missing Diplomat",s="酒馆里的常客指引你去塞拉摩找Samaul指挥官。他或许能帮你找到库尔提拉斯海军陆战队员Hendel。",h="酒馆里的常客指引你去塞拉摩找Samaul指挥官。他或许能帮你找到库尔提拉斯海军陆战队员Hendel。",kw={"黑龙","samaul指挥官","尘泥沼泽","elling","hendel","库尔提拉斯海军陆战队员","普罗德摩尔小姐","塞拉摩"},sec={{t="塞拉摩的线索",b="酒馆老板认为，Hendel就在常来此地的库尔提拉斯海军陆战队员之中。他们通常在每月初领到报酬后离开塞拉摩。Samaul指挥官或许知道Hendel是否仍驻扎在那里。和他说话时提起Elling的名字，他或许会暗中相助。"},{t="Samaul的警告",b="Samaul指挥官自称负责指挥普罗德摩尔小姐在塞拉摩的部队。他虽然事务繁忙，仍愿意回答问题。他警告说，城外的沼泽里有食人魔、兽人和鱼人，南部还有黑龙。"}},faq={{q="Hendel是谁？",a="Hendel是库尔提拉斯的一名海军陆战队员，可能是常来某家酒馆的人之一。酒馆老板认为，塞拉摩的Samaul指挥官或许知道他是否仍驻扎在那里。",al={"hendel","海军陆战队员hendel","hendel是谁"}},{q="Samaul指挥官是谁？",a="Samaul指挥官负责指挥普罗德摩尔小姐在塞拉摩的部队。",al={"samaul","指挥官","塞拉摩指挥官"}},{q="我为什么要找Samaul？",a="酒馆老板认为，如果Hendel仍驻扎在塞拉摩，Samaul或许能帮你找到他。",al={"找samaul","为何找samaul","失踪的外交官任务"}},{q="Elling是谁？",a="酒馆老板建议你询问Hendel时，向Samaul指挥官提起Elling的名字。",al={"elling","提起elling的名字","elling的名字"}},{q="库尔提拉斯海军陆战队员何时离开塞拉摩？",a="库尔提拉斯海军陆战队员在每月初领取报酬，通常之后就会离开塞拉摩。",al={"海军陆战队员离开","发薪日","他们何时离开"}},{q="Samaul提到了哪些危险？",a="Samaul警告说，城外有食人魔、兽人和鱼人，沼泽南部还有黑龙。",al={"塞拉摩的危险","沼泽里有什么","沼泽威胁"}}},fp="20,116,19.309.0,16.257.0,14.180.0,24.71.0,28.101.0,14.100.0,46.100.0,33.111.0"}
P.entries["quest:1265"] = {n="The Missing Diplomat",s="Elling派你去寻找Private Hendel，一名当地军官听说此事后觉得情况不太对劲。Hendel曾驻扎在塞拉摩城外的第一座塔楼，你受托前去寻找他的踪迹。",h="Elling派你去寻找Private Hendel，一名当地军官听说此事后觉得情况不太对劲。Hendel曾驻扎在塞拉摩城外的第一座塔楼，你受托前去寻找他的踪迹。",kw={"elling","hendel","军官","private hendel","警戒哨岗","塞拉摩","塔楼"},sec={{t="塔楼",b="这名军官认识Hendel，并说他曾驻扎在警戒哨岗，也就是塞拉摩城外的第一座塔楼。军官担心Elling让你先去那里，说明你的事可能不太寻常，并请你告知能透露的情况。军官有职责守护这片土地，因此任何异动都与当地哨卫息息相关。"}},faq={{q="Private Hendel是谁？",a="Private Hendel是Elling派你去寻找的人。一名当地军官说，Hendel曾驻扎在塞拉摩城外的第一座塔楼。",al={"private hendel","hendel是谁","hendel的来历"}},{q="我该去哪里找Hendel？",a="去警戒哨岗寻找Private Hendel的踪迹，那里是塞拉摩城外的第一座塔楼。",al={"hendel的位置","hendel在哪里","警戒哨岗 hendel"}},{q="是谁派我去找Hendel？",a="Elling派你去寻找Private Hendel。",al={"谁派我去","elling hendel","寻找hendel"}},{q="军官为何忧心？",a="军官认为，除非你的事非同寻常，否则Elling不会让你先去那里；他想知道你能透露什么，好守护这片土地。",al={"为何忧心","军官担忧","何事不寻常"}}},fp="20,202,12.327.0,22.130.0,31.84.0,27.39.0,29.156.0"}
P.entries["quest:1268"] = {n="可疑的蹄印",s="蹄印从树荫旅店蜿蜒而出，那里的空骨架依然冒着烟。几处蹄印清晰可见，更多的行列则几乎淹没在沼泽松软的土地中。你应该把这些报告给蕨墙村的克罗格。",h="蹄印从树荫旅店蜿蜒而出，那里的空骨架依然冒着烟。几处蹄印清晰可见，更多的行列则几乎淹没在沼泽松软的土地中。你应该把这些报告给蕨墙村的克罗格。",kw={"蕨墙村","半人马","尘泥沼泽","蹄印","卡戈罗","克罗格","野猪人","树荫旅店","可疑的蹄印"},sec={{t="泥地里的印记",b="树荫旅店现在只剩下一副空骨架，依然冒着烟，蹄印从那里延伸开来。有些印记很容易辨认；其他的在松软的土地上则几乎无法分辨。蕨墙村的克罗格应该知道这件事。"},{t="克罗格的回应",b="克罗格认为可能是野猪人干的，也可能是半人马，因为这两者在贫瘠之地都有相当大的势力，而且这种行为对他们来说并不令人意外。克罗格补充说，旅店不仅被烧毁了，店主还失去了一名女子和一只幼崽，他们都被杀害了。克罗格会派卡戈罗去查明这些足迹通向哪里。"}},faq={{q="蹄印在哪里？",a="它们从树荫旅店延伸出来，那里的空骨架依然冒着烟，横穿过沼泽松软的地面。",al={"蹄印位置","足迹在哪里","树荫旅店的印记"}},{q="谁应该知道这些蹄印的事？",a="你应该把这些报告给蕨墙村的克罗格。",al={"我该告诉谁","克罗格的位置","哪里报告蹄印"}},{q="这里有多少蹄印？",a="几处清晰可见，而更多的蹄印在泥地里几乎无法辨认。",al={"有多少蹄印","有多少足迹"}}},fp="21,229,17.236.0,12.326.1,25.100.0,37.59.0,26.84.0"}
P.entries["quest:1269"] = {n="帕瓦尔·雷瑟上尉",s="在这堆瓦砾下是一枚带有塞拉摩标志的徽章，上面是一个白珐琅底上的金色船锚，船锚下方印着帕瓦尔·里思中尉的名字。应该把它交给蕨墙村的克罗格。",h="在这堆瓦砾下是一枚带有塞拉摩标志的徽章，上面是一个白珐琅底上的金色船锚，船锚下方印着帕瓦尔·里思中尉的名字。应该把它交给蕨墙村的克罗格。",kw={"徽章","蕨墙村","徽记","克罗格","奥格隆","帕瓦尔","里思","塞拉摩"},sec={{t="瓦砾中的闪光",b="瓦砾下有什么东西在闪光。拂去灰烬和碎石，可以看到一枚印有塞拉摩标志的徽章，下方印着帕瓦尔·里思中尉的名字。蕨墙村的克罗格在等着它，他会问你是否有了关于树荫旅店遭遇的线索。"},{t="克罗格所知的情报",b="克罗格认识这个名叫帕瓦尔·里思的人类，并称他是个可怜虫。据克罗格所说，里思抛弃了与他并肩作战的士兵，现在正躲在树林里。克罗格派奥格隆去追踪他，因为其他人怀疑里思偷了补给品。克罗格认为有人看到奥格隆往东南方向去了。"}},faq={{q="徽章上写着什么？",a="塞拉摩的标志，白珐琅底上的金色船锚，下方印着帕瓦尔·里思中尉的名字。",al={"徽章上写了什么","塞拉摩守卫徽章标记","徽章的主人是谁"}},{q="这枚徽章要交给谁？",a="应该给蕨墙村的克罗格看看。",al={"我该把徽章带给谁","里思的徽章该交给谁","徽章上交"}},{q="这枚徽章是在哪里找到的？",a="在瓦砾下，上面覆盖着灰烬和碎石。克罗格问你是否有了关于树荫旅店遭遇的线索。",al={"徽章位置","里思的徽章在哪里找到的"}}},fp="23,212,21.276.0,15.285.1,21.116.0,19.51.0,26.104.0"}
P.entries["quest:127"] = {n="卖鱼",s="码头管理员巴伦管理着湖畔镇那座熙熙攘攘的码头，但他发现要筹集贸易所需的新鲜货源变得日益艰难。他出钱雇佣旅行者捕捞斑点太阳鱼，这种珍贵的止水湖特产如今因为鱼人的入侵而变得难以采集。",h="码头管理员巴伦管理着湖畔镇那座熙熙攘攘的码头，但他发现要筹集贸易所需的新鲜货源变得日益艰难。他出钱雇佣旅行者捕捞斑点太阳鱼，这种珍贵的止水湖特产如今因为鱼人的入侵而变得难以采集。",kw={"码头管理员巴伦","止水湖","湖畔镇","鱼人","赤脊山","出售鱼类","斑点太阳鱼"},ang={["faction:Alliance"]="由于暴风王国未能向赤脊山提供多少军事援助，就连维持当地的食物供应，也需要依靠独立的联盟旅行者伸出援手。",["profession:Cooking"]="湖畔镇因斑点太阳鱼等优质淡水美食而闻名，这使得当地水域成为了有志向的厨师们经久不衰的关注点。"},sec={{t="止水湖的主食",b="止水湖因其盛产的斑点太阳鱼而闻名周边地区，这种鲜美的鱼类始终是镇民和过往商人的抢手货。尽管湖底资源丰富，但镇上的供应却经常告急。由于湖畔镇在各种当地威胁下已自顾不暇，即使是基本的贸易也需要自由冒险者的帮助。"},{t="浅滩之困",b="平常情况下，当地的垂钓者要满足码头管理员巴伦的订单并不困难。然而，随着沿岸浅滩处侵略性鱼人部落的兴起，普通镇民已经被驱离了水域。想要完成巴伦请求的旅行者，要么得在提心吊胆的同时亲自垂钓，要么就得从那些祸害岸边的鱼人手中直接抢夺渔获。"}},faq={{q="码头管理员巴伦是谁？",a="码头管理员巴伦负责监管湖畔镇止水湖上的码头和船只往来。他管理着该镇的水产贸易，并依靠有能力的旅行者来协助确保新鲜鱼类的供应，并清除水域周边的威胁。",al={"巴伦","谁是码头管理员","码头管理员巴伦"}},{q="为什么斑点太阳鱼需求量这么大？",a="止水湖以斑点太阳鱼而闻名，这使得它们成为了湖畔镇重要的贸易商品和美味佳肴。码头管理员巴伦的存货之所以告急，是因为湖中满是敌对生物，普通的镇上垂钓者无法安全地进行捕鱼作业。",al={"为什么需要太阳鱼","斑点太阳鱼背景故事","为什么湖畔镇需要鱼"}},{q="鱼人是怎么得到斑点太阳鱼的？",a="止水湖沿岸的鱼人部落会在浅滩积极觅食和狩猎。当他们杀死或驱赶当地渔民时，就会把鱼收集到自己的营地中，这让那些宁愿战斗也不愿挥杆垂钓的冒险者有了可乘之机，去抢夺他们的囤货。",al={"鱼人鱼类","为什么鱼人会掉落鱼","鱼人偷鱼"}},{q="哪里可以找到斑点太阳鱼？",a="斑点太阳鱼栖息在赤脊山的止水湖水域中。你可以使用鱼竿直接钓起它们，或者从盘踞在湖岸和浅滩的鱼人身上拾取。",al={"太阳鱼在哪里","止水湖鱼类位置","如何获取斑点太阳鱼"}},{q="这个任务和“鱼人偷猎者”任务有什么关联？",a="码头管理员巴伦会同时提供这两个任务。由于鱼人在湖中徘徊并掠夺资源，对付这些偷猎者自然也就包含了夺回他们从水中捕获的斑点太阳鱼。",al={"鱼人偷猎者关联","巴伦的其他任务","码头管理员的任务"}},{q="帮助码头管理员巴伦需要垂钓技能吗？",a="不需要，你不需要任何垂钓装备或技能。虽然钓鱼是一种采集斑点太阳鱼的平和方式，但码头管理员巴伦明确建议，也可以从那些在湖中狩猎的鱼人部落手中强行夺取。",al={"需要钓鱼吗","不用鱼竿可以完成吗","需要垂钓"}}},fp="12,172,26.305.0,23.278.0,24.213.0,44.237.0,39.204.0,35.155.0,45.202.0,45.182.0"}
P.entries["quest:1270"] = {n="伊格纳兹的逃亡",s="“臭味”伊格纳兹被沼泽生物团团围住，还没找到他要找的沼泽豆。棘齿城的侏儒麦伯克·米希瑞克斯需要沼泽豆叶来酿造药剂，伊格纳兹请求你带他脱离困境，并在他寻找草药时保护他。事后，你可以在棘齿城找到麦伯克·米希瑞克斯。",h="“臭味”伊格纳兹被沼泽生物团团围住，还没找到他要找的沼泽豆。棘齿城的侏儒麦伯克·米希瑞克斯需要沼泽豆叶来酿造药剂，伊格纳兹请求你带他脱离困境，并在他寻找草药时保护他。事后，你可以在棘齿城找到麦伯克·米希瑞克斯。",kw={"沼泽豆","尘泥沼泽","护送","麦伯克·米希瑞克斯","棘齿城","臭味伊格纳兹"},sec={{t="沼泽中的困境",b="看到来的人不是为了吃掉他，伊格纳兹松了一口气。他说棘齿城的侏儒麦伯克·米希瑞克斯需要沼泽豆叶来配制某种药剂。伊格纳兹声称他不在乎原因，因为酬劳很丰厚，而且他很了解这片沼泽。他在找到植物之前就被包围了，所以请求你帮助他脱身，并护送他找到草药。"},{t="来自麦伯克的消息",b="麦伯克说伊格纳兹带着草药回来了，并讲述了你是如何把他从困境中救出来的。麦伯克声称，臭味的朋友就是他的朋友。在前往南方的沼泽之前，伊格纳兹曾拜托麦伯克，如果你们两人见面，就把东西交给你。"}},faq={{q="谁是“臭味”伊格纳兹？",a="“臭味”伊格纳兹正在沼泽中为麦伯克·米希瑞克斯寻找沼泽豆叶。他说他很了解这里，但在找到植物之前就被生物包围了。",al={"谁是臭味","臭味伊格纳兹","护送任务的目标是谁"}},{q="为什么伊格纳兹要收集沼泽豆叶？",a="来自棘齿城的侏儒麦伯克·米希瑞克斯需要它们来酿造药剂。伊格纳兹说他不在乎原因，因为酬劳很丰厚。",al={"为什么要沼泽豆","沼泽豆的用途","麦伯克 沼泽豆"}},{q="谁是麦伯克·米希瑞克斯？",a="麦伯克·米希瑞克斯是棘齿城的一名侏儒，他需要沼泽豆叶来酿造药剂。",al={"麦伯克","谁是麦伯克·米希瑞克斯","棘齿城的侏儒"}},{q="事后你应该去找谁？",a="护送伊格纳兹离开后，去棘齿城寻找麦伯克·米希瑞克斯。",al={"臭味去了哪里","去哪里交臭味的逃亡任务"}}},fp="15,299,23.362.0,15.256.1,23.166.0,39.125.0,22.82.0,34.60.0"}
P.entries["quest:1271"] = {n="盛筵",s="你在尘泥沼泽为安古斯·斯特恩的侄子所做的工作，以《……与虫子》为终点，现在指引你回到蓝色隐士旅店找安古斯·斯特恩。",h="你在尘泥沼泽为安古斯·斯特恩的侄子所做的工作，以《……与虫子》为终点，现在指引你回到蓝色隐士旅店找安古斯·斯特恩。",kw={"安古斯·斯特恩","尘泥沼泽","蓝色隐士旅店的宴会","斯特恩家族","蓝色隐士旅店","摩根·斯特恩"},sec={{t="回到蓝色隐士旅店",b="安古斯·斯特恩是摩根·斯特恩的叔叔，你在尘泥沼泽曾协助他进行配方研究。现在，这条道路指引你回到蓝色隐士旅店找安古斯。"},{t="安古斯听到的消息",b="安古斯从他侄子那里听说你协助了他的研究，并且还帮助他的一位同事摆脱了困境。斯特恩家族向来关照自己的朋友，一场为你举办的宴会即将开始。"}},faq={{q="谁是安古斯·斯特恩？",a="安古斯·斯特恩是摩根·斯特恩的叔叔，摩根在塞拉摩搜集配方，而他本人则与蓝色隐士旅店有关联。",al={"安古斯·斯特恩","蓝色隐士旅店主人","谁举办宴会"}},{q="安古斯·斯特恩和摩根·斯特恩是什么关系？",a="安古斯是摩根的叔叔。安古斯派摩根去塞拉摩，为蓝色隐士旅店的新沼泽主题菜单搜集配方。",al={"安古斯摩根关系","斯特恩家族","摩根是安古斯的侄子吗"}},{q="这个任务之前是什么？",a="它紧随《……与虫子》之后，那是你在塞拉摩为摩根·斯特恩所做工作的最后一项。",al={"前置任务","宴会之前的任务"}}},fp="25,124,24.155.0,20.209.1,19.113.0,45.119.0,29.84.0"}
P.entries["quest:1273"] = {n="盘问雷瑟",s="奥格隆受克罗格之托追踪人类里瑟，经过长时间的搜寻终于发现了他的踪迹，并表示以人类的标准来看，这家伙藏得还不错。奥格隆担心他在沼泽里待了太久可能已经疯了，并请求你随他一同前往，从里瑟口中问出答案。之后你需要回到蕨墙村向克罗格复命。",h="奥格隆受克罗格之托追踪人类里瑟，经过长时间的搜寻终于发现了他的踪迹，并表示以人类的标准来看，这家伙藏得还不错。奥格隆担心他在沼泽里待了太久可能已经疯了，并请求你随他一同前往，从里瑟口中问出答案。之后你需要回到蕨墙村向克罗...",kw={"蕨墙村","尘泥沼泽","审讯","克罗格","沼泽","奥格隆","里瑟"},sec={{t="奥格隆的搜寻",b="经过长时间的搜寻，奥格隆终于找到了里瑟，据奥格隆判断，以人类的标准来看他藏得还不错。奥格隆担心在沼泽中度过的这些时日可能已经让里瑟发疯了，因此希望有你在场，一同从他口中获取答案。事后，蕨墙村的克罗格在等待你的归来。"},{t="回到克罗格身边",b="克罗格很高兴里瑟离开了沼泽，并嘲笑人类太过脆弱，连一点小箭伤都挺不过来。克罗格断定这条线索到此为止，别无所获，搜寻工作必须转向别处。"}},faq={{q="谁找到了里瑟？",a="奥格隆在长时间搜寻后找到了里瑟，并希望你能随他一同前往获取答案。",al={"谁发布审问里瑟的任务","审问里瑟任务发布者","奥格隆里瑟"}},{q="为什么奥格隆需要同伴？",a="奥格隆担心里瑟在沼泽中待了太久，可能已经神志不清了。",al={"为什么要帮助奥格隆","里瑟疯了吗","为什么要审问里瑟"}},{q="事后你要向谁汇报？",a="蕨墙村的克罗格。",al={"审问里瑟在哪里交任务","审问里瑟之后找谁对话","里瑟任务交接"}}},fp="18,310,14.266.0,14.230.1,17.84.0,28.71.0,31.29.0"}
P.entries["quest:1274"] = {n="失踪的使节",s="“失踪的外交官”是暴风城最关键、最敏感的调查任务的入门步骤。你会在城市街道上隐秘地接到这一任务，这件事直接指向了位于Stormwind Keep的德拉维主教。教会和王室需要可靠的人手来处理这一问题，因为此事太过危险，无法通过公开渠道解决。",h="“失踪的外交官”是暴风城最关键、最敏感的调查任务的入门步骤。你会在城市街道上隐秘地接到这一任务，这件事直接指向了位于Stormwind...",kw={"德拉维主教","外交官","调查","stormwind keep","失踪的外交官","托马斯"},ang={["faction:Alliance"]="解开失踪外交官之谜对于联盟的完整和防御至关重要，它揭露了扎根于暴风城朝廷内部的深层威胁。",["race:Human"]="对于暴风城的人类来说，这项任务关系到你们在脆弱的摄政时期家园的稳定。"},sec={{t="悄然的召唤",b="当你在暴风城旅行时，一个不起眼的男童托马斯会接近值得信赖的冒险者，并提出一个安静的请求。德拉维主教是圣光教会中备受尊敬的人物，驻扎在Stormwind Keep，他需要一个外人的帮助。此事被严格描述为敏感且紧急，需要绝对保密，以避免在民众中引发恐慌。"},{t="Stormwind Keep里的低语",b="在Stormwind Keep响应召唤后，德拉维主教揭示了如此保密的原因。王国的一位高级官员在神秘的情况下失踪了。在这样一个国内动荡酝酿、瓦里安·乌瑞恩国王神秘失踪的时代，任何关于高层勾当的暗示都可能威胁到王国脆弱的和平。"}},faq={{q="托马斯是谁？",a="托马斯是Cathedral of Light的一名年轻男童，为德拉维主教跑腿。他在城市街道上留意着有能力的冒险者，每当敏感的教会或国家事务需要能干的中间人时，他就会悄悄地指引他们前往Stormwind Keep。",al={"托马斯是谁","托马斯 暴风城","托马斯 任务发布者"}},{q="德拉维主教是谁？",a="德拉维主教是驻扎在Stormwind Keep内的一名圣光教会高级教士。他与皇家法院合作，处理隐秘的王国安全问题和敏感调查，这些事情是普通城市卫兵无法公开进行的。",al={"德拉维主教是谁","德拉维","德拉维主教"}},{q="为什么这件事要秘密处理？",a="随着瓦里安·乌瑞恩国王的失踪和迪菲亚潜行者在西部荒野煽动叛乱，暴风城已经处于紧张状态。如果消息传出又有显赫的外交官或官员失踪，可能会引发广泛的恐慌，或者将朝廷的弱点暴露给敌人。",al={"为什么隐秘","为什么要保密","为什么秘密"}},{q="这项调查会引向何处？",a="在Stormwind Keep会见德拉维主教，开启了一项广泛的调查，它将带你深入王国政治的核心，遍布暴风城的街道，向外延伸到周边的人类领土，并进一步深入海外的危险土地。",al={"失踪的外交官任务去向","失踪的外交官后续"}},{q="失踪的外交官是谁？",a="在调查开始时，外交官的确切身份被德拉维主教严密保密。公开披露会威胁到正在进行的调查，并危及失踪官员和王国的安全。",al={"外交官是谁","失踪外交官的身份"}}},fp="20,154,15.290.0,20.306.1,14.221.0,22.207.0,37.236.0,35.165.0,28.177.0"}
P.entries["quest:1275"] = {n="研究堕落",s="奥伯丁的戈沙拉·夜语正在寻找潜伏在黑暗深渊的生物身上被腐蚀的脑干。由于海外传来的血精灵沉迷于恶魔魔法的报告令他感到不安，他希望通过研究纳迦和萨特生理上的退化，来预见——甚至可能阻止——又一场灾难性的精灵突变。",h="奥伯丁的戈沙拉·夜语正在寻找潜伏在黑暗深渊的生物身上被腐蚀的脑干。由于海外传来的血精灵沉迷于恶魔魔法的报告令他感到不安，他希望通过研究纳迦和萨特生理上的退化，来预见——甚至可能阻止——又一场灾难性的精灵突变。",kw={"灰谷","奥伯丁","黑暗深渊","血精灵","堕落者的脑干","国外的腐蚀","戈沙拉·夜语","纳迦","萨特"},ang={["class:Druid"]="德鲁伊对萨特有着天生的反感，萨特的邪能腐蚀亵渎了自然之梦，并扭曲了大地本身。",["class:Mage"]="戈沙拉的严峻调查是一个鲜明的提醒，警示着鲁莽、不受控制的魔法依赖在身体和精神上所付出的代价。",["faction:Alliance"]="联盟对海外传来的血精灵沉迷于黑暗艺术的报告保持警惕，唯恐新的恶魔威胁出现。",["race:NightElf"]="对于暗夜精灵来说，这项研究触及了他们历史上最鲜血淋漓的伤口：他们的同胞灾难性地退化成了困扰卡利姆多的萨特和纳迦。"},sec={{t="来自历史的警告",b="对于卡利姆多的暗夜精灵来说，他们古老族人的毁灭是一段刻在怪物身上的鲜活记忆。一万年前，上层精灵屈服于恶魔能量的诱惑，将自己扭曲成长角的萨特，或是沉沦为蛇形的纳迦。看着高等精灵改称自己为血精灵并拥抱黑暗魔法，戈沙拉·夜语并不认为这只是一个遥远的好奇心，而是注定要重演的历史。"},{t="进入深渊",b="黑暗深渊是戈沙拉进行这项严峻调查的理想样本产地。这座隐藏在灰谷佐拉姆海岸下的地下神庙遗迹中，爬满了萨特邪教徒和盘曲的纳迦。通过派遣冒险者从这两种怪物身上采集脑干，他希望剖析奥术成瘾、恶魔腐蚀和灾难性身体变形之间的生物学联系。"},{t="孤注一掷的治疗",b="虽然戈沙拉的方法在解剖学上令人毛骨悚然，但他声称的意图是预防性的。他相信，破译萨特和纳迦共有的精确生理突变，可能会带来将血精灵从彻底毁灭中拉回所需的知识。在黑海岸进行的任何研究是否真的能动摇绝望的奎尔萨拉斯精灵，仍是一个未决的问题。"}},faq={{q="为什么戈沙拉·夜语关心血精灵？",a="戈沙拉担心血精灵对恶魔力量的触碰会产生另一个扭曲的怪物种族来威胁艾泽拉斯，正如过去精灵的傲慢导致了萨特和纳迦的出现一样。",al={"为什么帮助血精灵","戈沙拉与血精灵的联系","奥伯丁的血精灵"}},{q="你在哪里收集被腐蚀的脑干？",a="它们收集自居住在黑暗深渊的萨特和纳迦，那是一个埋藏在灰谷西北海岸佐拉姆海岸边的古老神庙群。",al={"脑干在哪里","脑干位置","被腐蚀的脑干掉落"}},{q="他为什么特别想要萨特和纳迦的样本？",a="萨特和纳迦都起源于被非自然力量扭曲的精灵——萨特源于恶魔交易，而纳迦源于大分裂。戈沙拉想要比较他们的大脑突变，以绘制出精灵生理机能在黑暗力量下如何恶化的图谱。",al={"为什么选择萨特和纳迦","萨特与纳迦的联系"}},{q="是谁引导你执行这项任务的？",a="你可以通过引导任务“国外的腐蚀”被指引到奥伯丁的戈沙拉·夜语那里，不过他也会直接提供这项调查任务。",al={"前置任务","国外的腐蚀任务相关"}},{q="戈沙拉打算如何处理这些样本？",a="他计划研究这两种腐蚀形式之间的生理相关性，希望由此产生的知识能有助于阻止血精灵进一步陷入怪物的深渊。",al={"脑干研究","戈沙拉的研究目标"}},{q="奥伯丁受到黑暗深渊的直接威胁吗？",a="虽然黑暗深渊位于南部边境的灰谷，但奥伯丁的暗夜精灵一直在监视整个沿海地区，以寻找恶魔和暮光腐蚀升级的迹象。",al={"为什么奥伯丁关心此事","黑暗深渊对黑海岸的威胁"}}},fp="26,233,22.331.0,14.305.0,16.273.1,58.152.0,46.148.0,53.212.0,27.148.0,49.142.0,54.164.0"}
P.entries["quest:1276"] = {n="黑色盾牌",s="克罗格现在想起来“莫萨恩”这个名字的出处了：他是雷霆崖一位备受推崇的铁匠，大地之环曾经赠予克罗格一套由他打造的盔甲。克罗格希望莫萨恩能提供关于那面被熏黑的铁盾牌的更多信息，毕竟从瑞斯那里什么有用的线索都没得到。你可以在雷霆崖找到莫萨恩。",h="克罗格现在想起来“莫萨恩”这个名字的出处了：他是雷霆崖一位备受推崇的铁匠，大地之环曾经赠予克罗格一套由他打造的盔甲。克罗格希望莫萨恩能提供关于那面被熏黑的铁盾牌的更多信息，毕竟从瑞斯那里什么有用的线索都没得到。你可以在雷...",kw={"被熏黑的铁盾牌","铁匠","尘泥沼泽","大地之环","克罗格","莫萨恩","瑞斯","雷霆崖"},sec={{t="铁匠之名",b="克罗格回想起了他在哪里听过莫萨恩这个名字：他是雷霆崖一位备受推崇的铁匠。大地之环曾经为了答谢克罗格，赠予了他一套莫萨恩打造的盔甲，克罗格对那套装备的评价很高。克罗格说这面盾牌也是莫萨恩打造的，也许他能提供更多信息。克罗格承认这只是一个微不足道的线索，但既然从瑞斯那里一无所获，这也只能死马当活马医了。你需要带着这面被熏黑的铁盾牌去找位于雷霆崖的莫萨恩。"},{t="莫萨恩的答复",b="莫萨恩承认这面盾牌确实出自他手，但也仅此而已。他打造过太多的盾牌和盔甲套装，已经无法一一记起了。"}},faq={{q="莫萨恩是谁？",a="莫萨恩是雷霆崖一位备受推崇的铁匠，他曾打造过一套大地之环赠予克罗格的盔甲。",al={"莫萨恩是谁","莫萨恩在哪里","雷霆崖的莫萨恩"}},{q="为什么要带着盾牌去找莫萨恩？",a="克罗格说这面盾牌是莫萨恩打造的，也许他能提供更多信息。克罗格承认这是一条微弱的线索，但在瑞斯那里没有学到任何有用的东西的情况下，这已经是唯一的希望了。",al={"为什么要把盾牌给莫萨恩看","被熏黑的盾牌线索","莫萨恩知道什么"}},{q="克罗格是怎么认识莫萨恩的？",a="作为答谢，大地之环赠予了克罗格一套莫萨恩打造的盔甲。",al={"克罗格与莫萨恩的关系","克罗格如何认识这位铁匠"}}},fp="16,300,14.436.0,13.161.1,14.112.0,30.163.0,26.71.0"}
P.entries["quest:128"] = {n="悬赏：黑石氏族",s="“黑石赏金”是由湖畔镇的卫兵豪维代表所罗门镇长发布的一项防御契约。由于暴风城未能派遣增援部队，镇上只得雇佣独立的冒险者来清理聚集在北部山区中的精锐黑石勇士。击杀这些战场部队指挥官的目的是为了瓦解兽人氏族对赤脊山的协同攻击。",h="“黑石赏金”是由湖畔镇的卫兵豪维代表所罗门镇长发布的一项防御契约。由于暴风城未能派遣增援部队，镇上只得雇佣独立的冒险者来清理聚集在北部山区中的精锐黑石勇士。击杀这些战场部队指挥官的目的是为了瓦解兽人氏族对赤脊山的协同攻击...",kw={"黑石","赏金","燃烧平原","勇士","卫兵豪维","湖畔镇","所罗门镇长","赤脊山","暴风城"},ang={["class:Warrior"]="黑石勇士是装备精良、经验丰富的强硬老兵，在实战中会考验战士的纪律和耐力。",["faction:Alliance"]="湖畔镇是暴风城的东部防线；如果黑石兽人突破了这些山区营地，联盟的核心农田将直接暴露在入侵之下。",["race:Human"]="黑石氏族在第一次战争中摧毁了最初的暴风城王国。对于人类守军而言，阻止他们向南返回是一项痛苦但必须执行的先祖职责。"},sec={{t="坚守主权防线",b="赤脊山长期处于暴风城王国的主权统治之下，但黑石氏族并不尊重人类的边界。兽人们从燃烧平原通往山区的山口涌入，在赤脊山北部建立了戒备森严的营地。随着瓦里安·乌瑞恩国王的失踪，加上暴风城的摄政王拒绝派出皇家士兵，所罗门镇长等地方领袖只能被迫动用镇上日渐枯竭的金库悬赏招募，以保护湖畔镇。"},{t="目标：勇士",b="卫兵豪维认为黑石勇士是入侵先头部队的骨干。作为作战小队的队长和身经百战的退伍军人，这些勇士负责协调部队行动并驱使低级的步兵发起进攻。通过悬赏他们的首级，湖畔镇的守军希望能摧毁该氏族的战术指挥核心，在城镇外围防线崩溃之前拖延他们向南发起的全面攻势。"}},faq={{q="为什么卫兵豪维提供赏金而不是派遣城镇卫兵？",a="湖畔镇的当地驻军已经捉襟见肘。他们不仅要巡逻止水湖、守卫桥梁，还要抵御豺狼人和兽人袭击者的入侵，因此无法抽调出足够的力量在不让城镇陷入无防备状态的情况下，直接进攻戒备森严的兽人作战营地。",al={"为何悬赏","城镇卫兵在哪里","卫兵豪维的悬赏"}},{q="黑石勇士位于何处？",a="他们驻扎在赤脊山北部大片的黑石营地中，就在通往燃烧平原的高路以西。",al={"勇士在哪里","勇士位置","黑石勇士营地"}},{q="为什么黑石兽人要入侵赤脊山？",a="以北方的黑石山为据点，黑石氏族将周边的丘陵视为他们征服和劫掠的战略领土。在暴风城的防御体系四分五裂的情况下，他们试图驱逐人类定居点并夺取对这些山口的控制权。",al={"为何黑石在赤脊山","为何兽人攻击湖畔镇","黑石入侵"}},{q="为什么暴风城不派遣皇家士兵来清除他们？",a="瓦里安·乌瑞恩国王失踪了，而由摄政王Bolvar Fordragon和普瑞斯托女伯爵领导的皇家朝廷坚称无法抽调王国的军队。湖畔镇曾多次向首都请求援助，却遭到拒绝，只能被迫雇佣路过的雇佣兵。",al={"为何没有暴风城军队","暴风城的援助在哪里","所罗门镇长的增援"}},{q="勇士在黑石氏族中担任什么职务？",a="勇士是前线的战术指挥官。每一个黑石作战小队都依赖勇士来指挥攻击、执行残酷的纪律，并带领部队冲入联盟的领土。",al={"什么是黑石勇士","勇士军衔","黑石领导单位"}},{q="是谁授权了这个赏金契约？",a="湖畔镇的市政领袖所罗门镇长授权了这笔赏金，并指派卫兵豪维负责招募有能力的战士来执行清理任务。",al={"谁支付赏金","谁想要勇士死","所罗门镇长的悬赏"}}},fp="16,263,26.397.0,23.372.0,70.249.0,42.169.0,45.234.0,60.275.0,55.141.0,36.150.0"}
P.entries["quest:1282"] = {n="微笑的吉姆",s="卫兵拜伦对一个名叫“笑面吉姆”的人感到同情，并暗示他过去并非现在这副模样。拜伦不愿多谈此事，建议你去找塞拉摩的盖兰·维米斯队长。",h="卫兵拜伦对一个名叫“笑面吉姆”的人感到同情，并暗示他过去并非现在这副模样。拜伦不愿多谈此事，建议你去找塞拉摩的盖兰·维米斯队长。",kw={"盖兰·维米斯队长","尘泥沼泽","卫兵拜伦","詹姆斯·海亚尔","树荫旅店","笑面吉姆","塞拉摩"},sec={{t="悲伤的故事",b="拜伦很同情吉姆，并表示他过去并非总是如此：吉姆曾经在沼泽里经营着一家旅店，而且是一家很棒的旅店。拜伦不愿深谈此事。如果有人真想了解这段往事，他建议去找塞拉摩的盖兰·维米斯队长。"},{t="维米斯的陈述",b="维米斯指出此人的真名叫詹姆斯·海亚尔。海亚尔在贫瘠之地的边缘开了一家旅店，本意是为旅客提供一个舒适的落脚点，而且一度经营得不错。后来，塞拉摩失去了对沼泽道路的控制，食人魔便占领了那里。海亚尔非常固执，不愿放弃自己的梦想而躲进塞拉摩的城墙内寻求庇护，最终大火吞噬了树荫旅店。维米斯表示，目前的调查进展甚微，并建议想帮忙的人去废墟中搜寻线索。"}},faq={{q="笑面吉姆是谁？",a="卫兵拜伦对他感到同情，并说他过去并非现在这副模样。拜伦记得吉姆曾经在沼泽里经营着一家旅店，而且是一家很棒的旅店。",al={"吉姆是谁","笑面吉姆的身份","笑面人是谁"}},{q="为什么卫兵拜伦让你去找维米斯队长？",a="拜伦不愿讨论吉姆的过去，而是指引你去找盖兰·维米斯队长。",al={"为什么要找维米斯谈话","拜伦的任务","卫兵拜伦的理由"}},{q="我在哪里可以找到盖兰·维米斯队长？",a="盖兰·维米斯队长在塞拉摩。",al={"维米斯队长是谁","泥潭沼泽的维米斯队长"}}},fp="25,194,11.246.0,15.479.1,19.146.0,47.90.0,37.37.0"}
P.entries["quest:1284"] = {n="可疑的蹄印",s="蹄印从尚在冒烟的树荫旅店废墟处向外延伸。有几处蹄印清晰可见，而其他的则几乎没入柔软的沼泽泥土中不见踪影。你应该向塞拉摩的盖兰·维米斯队长汇报这些发现。",h="蹄印从尚在冒烟的树荫旅店废墟处向外延伸。有几处蹄印清晰可见，而其他的则几乎没入柔软的沼泽泥土中不见踪影。你应该向塞拉摩的盖兰·维米斯队长汇报这些发现。",kw={"贫瘠之地","盖兰·维米斯队长","半人马","尘泥沼泽","法尔格伦·哈斯提尔","蹄印","树荫旅店","塞拉摩"},sec={{t="泥土中的蹄印",b="一连串蹄印从尚在冒烟的树荫旅店废墟延伸开来。其中一些印记清晰可辨，而更多的蹄印则几乎消失在沼泽柔软的泥地里。塞拉摩的盖兰·维米斯队长应该知道这些事情。"},{t="维米斯的看法",b="维米斯指出，尘泥沼泽附近的土地上有大量的半人马活动迹象。几次前往贫瘠之地的短途侦察已经发现了他们散落在该地区的营地和据点。维米斯打算派追踪者法尔格伦·哈斯提尔去查明这些蹄印通向何处。"}},faq={{q="在哪里发现了蹄印？",a="它们从仍在冒烟的树荫旅店延伸出来，横穿过柔软的沼泽泥地。",al={"蹄印在哪里","蹄印位置","树荫旅店蹄印"}},{q="谁负责接收关于蹄印的报告？",a="塞拉摩的盖兰·维米斯队长。",al={"关于蹄印该告诉谁","谁负责接收蹄印报告","盖兰·维米斯蹄印"}},{q="这些蹄印容易追踪吗？",a="有几处蹄印很清晰，但更多印记在泥地里几乎无法辨认。",al={"蹄印难以辨认吗","沼泽中模糊的踪迹"}}},fp="21,208,17.246.0,22.272.1,31.91.0,41.35.0,34.68.0"}
P.entries["quest:1285"] = {n="戴林的下属",s="泰索兰副官在卫兵记录中找到了帕瓦尔·里瑟中尉的信息。记录显示，他在十六岁时加入了库尔提拉斯海军陆战队，因服役表现卓越而获得晋升，并随普罗德摩尔女士一同远航，成为了塞拉摩卫队的新兵。记录的最后一项显示里瑟失踪，而盖兰·维米斯队长必须获知此事。",h="泰索兰副官在卫兵记录中找到了帕瓦尔·里瑟中尉的信息。记录显示，他在十六岁时加入了库尔提拉斯海军陆战队，因服役表现卓越而获得晋升，并随普罗德摩尔女士一同远航，成为了塞拉摩卫队的新兵。记录的最后一项显示里瑟失踪，而盖兰·维米...",kw={"泰索兰副官","戴林的部下","逃兵","尘泥沼泽","盖兰·维米斯","库尔提拉斯","帕瓦尔·里瑟","塞拉摩"},sec={{t="记录中的内容",b="盖兰·维米斯队长派你去找泰索兰副官，他查阅了档案并找到了帕瓦尔·里瑟中尉。里瑟十六岁时加入库尔提拉斯海军陆战队，因服役出色而获得晋升。里瑟随后加入了塞拉摩卫队，就像大多数随普罗德摩尔女士远航而来的新兵一样。记录的最后显示里瑟失踪了。这个消息需要传达给在塞拉摩的维米斯。"},{t="队长的反应",b="维米斯认为“失踪”只是泰索兰用来称呼叛徒的委婉说法。维米斯坚信里瑟也是那些对戴林上将盲目忠诚、以至于不惜背叛的蠢货之一，他觉得这很讽刺，因为这些逃兵竟指责塞拉摩背叛了联盟。"}},faq={{q="泰索兰副官是谁？",a="泰索兰副官负责在卫兵记录中查询帕瓦尔·里瑟中尉的信息并宣读记录内容。",al={"泰索兰","谁发布了戴林的部下任务"}},{q="关于帕瓦尔·里瑟，记录上怎么说？",a="里瑟十六岁时加入了库尔提拉斯海军陆战队，因服役出色而获得晋升，随后随普罗德摩尔女士一同远航，成为了塞拉摩卫队的新兵。记录最后显示里瑟处于失踪状态。",al={"里瑟背景故事","里瑟记录","帕瓦尔·里瑟历史"}},{q="谁会收到关于里瑟的消息？",a="位于塞拉摩的盖兰·维米斯队长。",al={"为什么要回到维米斯那里","盖兰·维米斯与里瑟"}}},fp="12,352,20.404.0,22.272.1,24.116.0,43.244.0,31.35.0"}
P.entries["quest:1286"] = {n="背叛者",s="盖兰·维米斯队长说逃兵们在塞拉摩废弃的一座哨塔里定居了。这座塔位于废弃哨塔，就在旅店的东南方。一个名叫加科因的男人领导着这群逃兵，维米斯想从他那里得到关于里斯的线索。",h="盖兰·维米斯队长说逃兵们在塞拉摩废弃的一座哨塔里定居了。这座塔位于废弃哨塔，就在旅店的东南方。一个名叫加科因的男人领导着这群逃兵，维米斯想从他那里得到关于里斯的线索。",kw={"巴鲁斯·加科因","盖兰·维米斯队长","逃兵","尘泥沼泽","废弃哨塔","里斯","哨塔"},sec={{t="被占领的哨塔",b="维米斯承认在沼泽中坚守十分艰难，尽管他的人民意志坚定，保住了几座防御哨塔。侦察报告称，逃兵们已经搬进了废弃哨塔里的一座废弃的哨塔，该地点位于旅店的东南方。一个叫加科因的人领导着他们。维米斯要求你去看看加科因能透露什么关于里斯的消息，并警告说加科因可能不会轻易开口。"}},faq={{q="是谁派你去处理这些逃兵的？",a="盖兰·维米斯队长，他的侦察报告显示逃兵们已经在塞拉摩废弃的一座哨塔里定居了。",al={"谁开启了逃兵任务","谁给予逃兵任务"}},{q="逃兵们藏在哪里？",a="在尘泥沼泽的废弃哨塔，位于旅店的东南方。",al={"逃兵位置","废弃哨塔在哪里"}},{q="谁领导着废弃哨塔的逃兵？",a="一个叫加科因的男人，即巴鲁斯·加科因，领导着他们。维米斯警告说，加科因可能不会轻易透露信息。",al={"谁是巴鲁斯·加科因","逃兵领袖"}},{q="维米斯队长想从巴鲁斯·加科因那里得到什么？",a="关于里斯的信息，来自加科因和那些逃兵。",al={"为什么要找到加科因","维米斯想要什么"}}},fp="13,248,13.415.0,41.115.0,31.90.0,38.109.0,47.56.0"}
P.entries["quest:1287"] = {n="背叛者",s="当被问及Reethe时，废弃哨塔逃兵的首领巴鲁斯·加科因称他是个懦夫，并说逃兵们已经把他赶出了营地。巴鲁斯·加科因随后要求你忘记曾经遇到过他们。你应该把有关Reethe的消息告诉塞拉摩的盖兰·维米斯队长。",h="当被问及Reethe时，废弃哨塔逃兵的首领巴鲁斯·加科因称他是个懦夫，并说逃兵们已经把他赶出了营地。巴鲁斯·加科因随后要求你忘记曾经遇到过他们。你应该把有关Reethe的消息告诉塞拉摩的盖兰·维米斯队长。",kw={"巴鲁斯·加科因","蕨墙村","卡德威尔","逃兵","盖兰·维米斯","废弃哨塔","reethe","塞拉摩"},sec={{t="被驱逐",b="巴鲁斯·加科因说，逃兵们驱逐Reethe是因为他一再劫掠蕨墙村食人魔的补给。据巴鲁斯·加科因所说，逃兵们人数太少，无法与那些食人魔对抗，而Reethe越界次数太多，所以他们把Reethe留在那自生自灭。作为回答的回报，巴鲁斯·加科因要求你忘记这次会面。"},{t="回到塞拉摩",b="盖兰·维米斯队长说，卡德威尔中尉将会被派去对付废弃哨塔的逃兵，并会被告知寻找Reethe。盖兰·维米斯队长断定沼泽并没有大到或复杂到让卡德威尔找不到Reethe的程度。"}},faq={{q="为什么Reethe被逐出了逃兵营地？",a="巴鲁斯·加科因说，Reethe不断劫掠蕨墙村食人魔的补给。逃兵们人数太少，无法与他们对抗，所以他们抛下Reethe让他独自面对。",al={"为什么逃兵放逐了reethe","reethe 蕨墙村","为什么巴鲁斯赶走了reethe"}},{q="巴鲁斯·加科因是谁？",a="巴鲁斯·加科因领导着废弃哨塔的逃兵。当被问及Reethe时，他称他为懦夫。",al={"巴鲁斯·加科因是谁","巴鲁斯·加科因背景故事","巴鲁斯·加科因 尘泥沼泽"}},{q="谁想知道关于Reethe的消息？",a="塞拉摩的盖兰·维米斯队长，尽管巴鲁斯·加科因本人希望你忘记曾经见过这些逃兵。",al={"逃兵任务在哪里交付","谁想要reethe的情报"}}},fp="13,260,10.335.0,17.214.1,47.162.0,20.81.0,31.106.0"}
P.entries["quest:1288"] = {n="维米斯的报告*",s="盖兰·维米斯队长认为你的工作是他所见过业余人士中最棒的。吉安娜·普罗德摩尔女士曾要求维米斯随时向她通报一个棘手的情况，现在维米斯把这份报告交给你，让你带去塞拉摩交给她。",h="盖兰·维米斯队长认为你的工作是他所见过业余人士中最棒的。吉安娜·普罗德摩尔女士曾要求维米斯随时向她通报一个棘手的情况，现在维米斯把这份报告交给你，让你带去塞拉摩交给她。",kw={"尘泥沼泽","盖兰·维米斯","jaina proudmoore","报告","塞拉摩","维米斯"},sec={{t="普罗德摩尔女士的报告",b="吉安娜·普罗德摩尔女士曾要求盖兰·维米斯队长随时向她通报一个棘手的情况，但维米斯已经有一段时间没有和她联络了。维米斯原本打算迟些再提交报告，但现在觉得由你去和她谈谈更为合适，因为相比维米斯，你或许能更好地回答她的问题。"}},faq={{q="是谁把报告交给你，让你带给吉安娜·普罗德摩尔？",a="盖兰·维米斯队长将他的报告交给你，让你带给塞拉摩的吉安娜·普罗德摩尔女士。",al={"谁开启维米的报告","谁给出了报告","谁写了维米的报告"}},{q="为什么盖兰·维米斯队长派你去，而不是他自己去？",a="维米斯已经有一段时间没和吉安娜·普罗德摩尔女士谈话了，他认为由你去更合适。维米斯相信你可能对她的问题有更好的答案。",al={"为什么派我","为什么维米不去递交","为什么吉安娜需要报告"}},{q="这份报告需要送到哪里？",a="送到塞拉摩交给吉安娜·普罗德摩尔女士。",al={"在哪里上交维米的报告","吉安娜·普罗德摩尔在哪里","报告目的地"}}},fp="14,221,28.313.0,53.93.0,57.166.0,33.38.0"}
P.entries["quest:1289"] = {n="维米斯的报告*",s="吉安娜·普罗德摩尔已经阅读了盖兰·维米斯队长的报告，并感谢你在调查中提供的帮助。她希望你能回到维米斯身边，协助他彻底查清这个谜团。",h="吉安娜·普罗德摩尔已经阅读了盖兰·维米斯队长的报告，并感谢你在调查中提供的帮助。她希望你能回到维米斯身边，协助他彻底查清这个谜团。",kw={"盖兰·维米斯队长","尘泥沼泽","调查","吉安娜·普罗德摩尔","塞拉摩","维米斯的报告"},sec={{t="回到队长身边",b="根据盖兰·维米斯队长的报告，普罗德摩尔女士认为你在他的调查中提供了巨大的帮助，并对此表示感谢。得知此事由如此能干的人负责，她感到安心了不少。她希望你能回到塞拉摩的盖兰·维米斯队长身边，协助他彻底查清这个谜团。"}},faq={{q="是谁让你回去找盖兰·维米斯队长的？",a="在塞拉摩阅读了维米斯的报告后，吉安娜·普罗德摩尔。",al={"谁给了维米斯报告","吉安娜任务发布者","谁派我去找维米斯"}},{q="吉安娜对这份报告怎么看？",a="她说你在调查中提供了巨大的帮助，并对此表示感谢。得知此事由能干的人负责，她感到安心了不少。",al={"吉安娜的反应","吉安娜怎么评价维米斯的报告"}},{q="你在哪里可以找到盖兰·维米斯队长？",a="盖兰·维米斯队长在塞拉摩。",al={"盖兰·维米斯队长在哪里","盖兰·维米斯队长位置","在哪里上交维米斯报告"}}},fp="14,188,19.309.0,36.69.0,41.140.0,39.37.0"}
P.entries["quest:129"] = {n="免费的午餐",s="“免费午餐”是湖畔镇的一项联盟差事，旅店厨师达希会请一位The Adventurer把一份备好的餐点送给卫兵帕克。帕克在通往暮色森林的危险南路上巡逻，负责清理湖畔镇周边充满敌意的豺狼人和黑石兽人。",h="“免费午餐”是湖畔镇的一项联盟差事，旅店厨师达希会请一位The Adventurer把一份备好的餐点送给卫兵帕克。帕克在通往暮色森林的危险南路上巡逻，负责清理湖畔镇周边充满敌意的豺狼人和黑石兽人。",kw={"黑石兽人","达希","夜色镇","免费午餐","豺狼人","卫兵帕克","湖畔镇","帕克的午餐","赤脊山"},ang={["faction:Alliance"]="运送达希的食物突显了那些被遗弃在边远联盟定居点的普通百姓和前线哨兵所面临的巨大压力，他们大多只能自谋生路。",["profession:Cooking"]="在野外，一份热腾腾、精心准备的口粮，往往就是孤守在充满敌意的十字路口的哨兵所能得到的全部支撑。"},sec={{t="路上的餐点",b="赤脊山的日常生活充满了紧张气氛，但作为湖畔镇本地人的达希，正试图以自己的方式支持那些守卫城镇的人。她为卫兵帕克准备了一份丰盛的餐点，却发现自己无法亲自送去。镇门外的荒野中到处都是好斗的赤脊山豺狼人和游荡的兽人战团，对于一个没有武装的平民来说，走出城镇范围实在太危险了。因此，她只能依靠路过的旅人把口粮沿着通往夜色镇的道路送过去。"},{t="守卫边境",b="卫兵帕克驻扎在湖畔镇南边的路上，看守着连接赤脊山和暮色森林的通道。赤脊山的守卫力量已捉襟见肘，暴风城军队未能提供足够的增援来抵御日益增多的赤脊山豺狼人部族，以及盘踞在山中的黑石氏族。在如此充满敌意的地区独自站岗，让像帕克这样的哨兵感到极其疲惫，因此平民给予的简单关怀和热腾腾的食物，成了提振部队士气的关键。"}},faq={{q="在哪里可以找到卫兵帕克？",a="卫兵帕克在从湖畔镇通往暮色森林和夜色镇边界的南边土路上巡逻。",al={"卫兵帕克位置","帕克在哪里","寻找卫兵帕克"}},{q="为什么达希不亲自去送午餐？",a="达希只是个普通平民，她认为湖畔镇郊外对于独自行动来说太过危险了。充满敌意的豺狼人和黑石兽人就在镇外路边徘徊。",al={"为什么达希不能去","达希 赤脊山"}},{q="卫兵帕克正在应对哪些威胁？",a="帕克必须守住南边的道路，抵御赤脊山土生土长的游荡豺狼人部族以及好斗的黑石兽人战团。",al={"帕克的敌人","赤脊山威胁"}},{q="卫兵帕克收到午餐后会发生什么？",a="收到达希的餐点让帕克心怀感激，最终促使他请The Adventurer在守卫和镇民之间跑腿，完成进一步的差事，首先就是去拜访当地的草药师。",al={"免费午餐后续任务","帕克后续"}},{q="为什么暴风城的守卫难以保障赤脊山的安全？",a="由于瓦里安·乌瑞恩国王失踪，王国的政治领导层又忙于处理暴风城内的事务，像湖畔镇这样的边远定居点几乎没有得到任何军事支援，这使得这里的城镇守卫处于孤立无援的境地。",al={"为什么湖畔镇缺乏防御","暴风城忽视赤脊山"}},{q="达希承诺的奖励是什么？",a="作为携带帕克的餐点穿过危险荒野的交换，达希承诺在送餐者回到镇上后，会为他们准备并提供一份免费午餐。",al={"什么是免费午餐","达希的奖励"}}},fp="12,185,19.312.0,19.332.0,32.89.0,44.147.0,42.85.0,47.158.1,58.146.0,32.96.0"}
P.entries["quest:13"] = {n="西部荒野人民军",s="这项任务标志着格里安·斯托曼的志愿军发起的战役正在升级，旨在将迪菲亚潜行者赶出西部荒野。随着这些盗贼的行径从轻微的公路抢劫转变为对月溪镇和金海岸矿洞等关键据点的有组织洗劫，人民民兵组织要求进行更严厉的报复。",h="这项任务标志着格里安·斯托曼的志愿军发起的战役正在升级，旨在将迪菲亚潜行者赶出西部荒野。随着这些盗贼的行径从轻微的公路抢劫转变为对月溪镇和金海岸矿洞等关键据点的有组织洗劫，人民民兵组织要求进行更严厉的报复。",kw={"阿历克斯顿农场","迪菲亚掠夺者","迪菲亚劫掠者","金海岸矿洞","格里安·斯托曼","月溪镇","人民民兵组织","哨兵岭","西部荒野"},ang={["class:Paladin"]="格里安·斯托曼明确呼吁圣光净化西部荒野的犯罪腐败，这使得这场战役成为圣骑士直接执行的正义使命。",["faction:Alliance"]="这场斗争凸显了舒适的暴风城围墙内与饥寒交迫的边境地区之间令人痛苦的隔阂，这些边境地区被完全抛弃，只能自生自灭。",["race:Human"]="对于王国的人类来说，在这里战斗是一场悲剧性的对抗，对手是曾经的石匠和邻居，而现在他们已暴力反抗自己的人民。"},sec={{t="不断升级的暴力冲突",b="虽然早期与迪菲亚的冲突仅涉及在道路上骚扰行人的小股强盗，但威胁正在迅速加深。迪菲亚掠夺者和投掷火把的劫掠者已经席卷了西部荒野各地的关键经济中心，彻底占据了月溪镇，洗劫了阿历克斯顿农场，并强占了金海岸矿洞。格里安·斯托曼意识到，如果这些歹徒巩固了他们对这些枢纽的控制，那么在没有正规皇家军队的情况下，收复该地区将变得不可能。"},{t="民兵组织的理念",b="由于缺乏来自暴风城的正规士兵或资源，格里安·斯托曼援引圣光的力量以及西部荒野幸存农民的道德勇气。民兵组织的消耗战完全依赖于志愿者直接深入迪菲亚的据点进行战斗。驱逐掠夺者旨在切断兄弟会的资源，同时向恐惧的居民表明，仍有捍卫者愿意为西部荒野的和平与繁荣而战。"}},faq={{q="什么是人民民兵组织？",a="人民民兵组织是由格里安·斯托曼组织的一支武装志愿者防御部队。他们主要由流离失所的西部荒野农民和富有同情心的旅行者组成，在暴风城的王室拒绝部署城市卫兵后，他们组建起来以保卫该省，抵御迪菲亚潜行者。",al={"人民民兵组织","谁是民兵","西部荒野民兵"}},{q="格里安·斯托曼是谁？",a="格里安·斯托曼是一位人类老兵指挥官，负责在哨兵岭顶部的堡垒指挥西部荒野的防御。他忠于圣光和家园，协调人民民兵组织进行殊死抵抗，以应对不法之徒的控制。",al={"格里安","谁是斯托曼","斯托曼背景故事"}},{q="迪菲亚为什么洗劫农场和矿洞？",a="迪菲亚潜行者的目的是削弱西部荒野的食物供应并掠夺原材料。占领金海岸矿洞使他们能够控制石料和矿产，而夺取月溪镇和农场则可以驱逐诚实的平民，并为其犯罪事业提供行动基地。",al={"为什么迪菲亚在掠夺","月溪镇的迪菲亚","为什么矿洞有劫掠者"}},{q="为什么暴风城没有派兵到西部荒野？",a="瓦里安·乌瑞恩国王离奇失踪，留下年幼的安度因国王在伯瓦尔·弗塔根公爵的摄政下统治。暴风城的贵族议会内部严重僵持，导致王室资源紧张，西部荒野等边境领土被彻底遗弃，只能依靠当地的防御者。",al={"暴风城卫兵在哪里","为什么暴风城不提供援助","瓦里安国王西部荒野"}},{q="在哪里可以找到迪菲亚劫掠者和掠夺者？",a="他们主要聚集在西部荒野南部和西部被占领的定居点周围，特别是荒废的月溪镇、西侧峭壁沿线的金海岸矿洞以及废弃的阿历克斯顿农场。",al={"劫掠者位置","掠夺者在哪里","迪菲亚地点"}}},fp="20,253,19.409.0,24.388.0,29.282.0,25.223.0,46.263.0,47.317.0,45.231.0"}
P.entries["quest:130"] = {n="寻访草药师",s="在为卫兵帕克送去一顿美餐后，他在你返回Lakeshire Inn之前拜托你帮个忙。他希望能向达希表达自己的心意，于是派你去当地的草药师那里买些花。帕克坚持要求不要告诉草药师是谁订的花，也不要告诉她是送给谁的。",h="在为卫兵帕克送去一顿美餐后，他在你返回Lakeshire Inn之前拜托你帮个忙。他希望能向达希表达自己的心意，于是派你去当地的草药师那里买些花。帕克坚持要求不要告诉草药师是谁订的花，也不要告诉她是送给谁的。",kw={"水仙花","达希","花","卫兵帕克","湖畔镇","玛蒂·詹罗斯","赤脊山","拜访草药师"},ang={["faction:Alliance"]="即使在豺狼人部族和黑石兽人不断侵入赤脊山的威胁下，湖畔镇的守卫们之间依然上演着平民百姓的小浪漫。",["profession:Herbalism"]="拜访玛蒂·詹罗斯会将采集者引向湖畔镇西侧的主要草药和炼金商人。"},sec={{t="卫兵的秘密请求",b="卫兵帕克驻守在通往湖畔镇的偏僻南路上，他的职责是留意黑石兽人和豺狼人。当你从Lakeshire Inn的达希那里为他带来热气腾腾的午餐时，他抓住了这个机会来回报她的好意。他没有让你直接回去，而是请求你顺道去镇西头的草药店，为她买一束花。"},{t="城镇流言与秘密求爱",b="湖畔镇的小镇生活让秘密几乎无处遁形，这就是为什么帕克明确警告你，不要向草药师玛蒂·詹罗斯透露花是谁送的，或者它是送给谁的。当你到达她的店里时，玛蒂忍不住打趣你，以为你在镇上迅速找到了自己的心上人。在这样一个饱受兽人入侵和强盗骚扰的地区，哪怕是如此微不足道的浪漫举动，也是一种令人欣慰的消遣。"}},faq={{q="是谁让你去拜访草药师的？",a="卫兵帕克交给你这个任务。他驻守在通往赤脊山的南部道路上，就在与暮色森林交界的北边。",al={"谁发布了这个任务","任务发布者","卫兵帕克"}},{q="湖畔镇的草药师是谁？",a="玛蒂·詹罗斯是湖畔镇当地的草药师和花商。她的商店位于镇子的西头。",al={"玛蒂·詹罗斯是谁","草药师在哪里","湖畔镇草药师"}},{q="卫兵帕克为什么要买花？",a="帕克想给达希送花，表达浪漫的兴趣和感激之情，因为这位Lakeshire Inn的女招待曾送给他一份免费的午餐。",al={"为什么买花","花是送给谁的","帕克的动机"}},{q="为什么帕克希望保密这次购买？",a="湖畔镇是一个关系紧密的小镇，消息传得很快。帕克对于追求达希感到害羞，想要避免来自玛蒂·詹罗斯和其他镇民的流言蜚语。",al={"为什么要保密","为什么要隐藏花是送给谁的","不要告诉玛蒂"}},{q="和玛蒂·詹罗斯交谈后会发生什么？",a="玛蒂准备了一束水仙花，随后引导你执行将花直接送给Lakeshire Inn的达希的任务。",al={"what comes next","送水仙花","拜访草药师之后"}},{q="这个任务在任务链中处于什么位置？",a="这个任务是“免费的午餐”（你为卫兵帕克送去午餐）和“送花”（你把花带回给达希）之间的桥梁。",al={"任务链","前置任务","免费午餐任务链"}}},fp="19,121,24.278.0,31.392.0,37.124.0,34.93.0,35.127.0,46.118.0,46.85.1,39.155.1"}
P.entries["quest:1302"] = {n="詹姆斯·海厄尔",s="“James Hyal”是一个联盟任务，讲述了一位跟随吉安娜·普罗德摩尔的远征队航行至卡利姆多的人类定居者的故事。在他动身前往边境开设旅店后，他在东部王国的家人与他失去了联系，并试图通过塞拉摩的行政记录来寻找他的下落。",h="“James Hyal”是一个联盟任务，讲述了一位跟随吉安娜·普罗德摩尔的远征队航行至卡利姆多的人类定居者的故事。在他动身前往边境开设旅店后，他在东部王国的家人与他失去了联系，并试图通过塞拉摩的行政记录来寻找他的下落。",kw={"书记员伦德里","厨师","旅店老板","jaina proudmoore","詹姆斯·海亚尔","卡利姆多","塞拉摩"},ang={["faction:Alliance"]="詹姆斯在第三次战争期间跟随吉安娜·普罗德摩尔向西航行，这反映了许多东部王国联盟家庭与塞拉摩岛之间紧密的个人纽带。",["profession:Cooking"]="詹姆斯在家乡以厨艺精湛而闻名，他冒险前往卡利姆多，希望能通过经营旅店、为旅行者提供食物来维持生计。"},sec={{t="横跨无尽之海",b="在第三次战争期间，无数的灵魂离开了他们在东部王国的祖居之地，追随吉安娜·普罗德摩尔横跨无尽之海。詹姆斯·海亚尔（James Hyal）就是其中之一，他的亲人们亲切地记得他是一位富有天赋的厨师。在战斗平息、塞拉摩岛建立之后，詹姆斯选择在卡利姆多这片崎岖的大陆上开辟自己的生活，开设了一家旅店，为旅行者和其他定居者提供服务。"},{t="寻找兄弟",b="在遥远的东部王国，詹姆斯的兄弟因为许久没有收到来自海那边的信件而感到担忧。他希望詹姆斯只是因为忙于经营一家热闹的路边酒馆而无暇顾及其他，便请求路过的旅行者去打探他的消息。找到他的第一步在于塞拉摩，书记员伦德里（Clerk Lendry）负责管理当地的记录，并追踪那些冒险进入荒野的远征队成员。"}},faq={{q="詹姆斯·海亚尔是谁？",a="詹姆斯·海亚尔是一位人类定居者和才华横溢的厨师，他跟随吉安娜·普罗德摩尔的舰队横跨了无尽之海。在战斗平息后，为了在卡利姆多寻求新的生计，他动身前往该大陆建立一家旅店。",al={"詹姆斯·海亚尔是谁","詹姆斯·海亚尔背景故事","詹姆斯是谁"}},{q="我在哪里可以找到詹姆斯·海亚尔？",a="詹姆斯随普罗德摩尔的远征队抵达卡利姆多后，动身前往大陆某处建立旅店。他的家人最近没有收到他的消息，但塞拉摩岛的书记员伦德里保存着记录，或许知道他的确切下落。",al={"詹姆斯·海亚尔在哪里","寻找詹姆斯·海亚尔","詹姆斯·海亚尔位置"}},{q="书记员伦德里是谁？",a="书记员伦德里是一位驻扎在塞拉摩岛的联盟官员，负责处理当地城镇的行政事务和市民咨询。寻找像詹姆斯·海亚尔这样的定居者的旅行者通常会被引荐给伦德里，以查阅塞拉摩的记录。",al={"书记员伦德里是谁","书记员伦德里位置","塞拉摩书记员"}},{q="詹姆斯为什么要去卡利姆多？",a="詹姆斯在第三次战争期间跟随吉安娜·普罗德摩尔的舰队航行，作为人类从东部王国大迁徙的一部分。主要冲突平息后，他选择留下，为旅行者和定居者建造一家旅店。",al={"詹姆斯为什么去卡利姆多","詹姆斯·海亚尔远征队"}},{q="是谁在寻找詹姆斯·海亚尔？",a="这项查询来自詹姆斯在东部王国的兄弟，他已经有一段时间没有收到他的消息了。他记得詹姆斯是一位出色的厨师，因此推测他只是忙于建立自己的新旅店。",al={"谁给予詹姆斯·海亚尔任务","詹姆斯的兄弟是谁"}},{q="詹姆斯·海亚尔有危险吗？",a="他的兄弟认为他只是忙于经营自己的新生意，并假设大陆上的和平生活让他得以安居乐业。然而，他的家人确实已经有一段时间没有收到他的直接消息了。",al={"詹姆斯·海亚尔安全吗","詹姆斯·海亚尔发生了什么"}}},fp="10,300,20.416.0,22.438.0,18.233.0,28.252.0,20.226.0,33.225.0,30.217.0,28.210.0"}
P.entries["quest:131"] = {n="水仙诉衷情",s="“送交水仙花”任务内容包含在湖畔镇的卫兵岗哨与城镇广场之间的一次小型日常跑腿任务。在为卫兵帕克取来午餐，并从草药师玛蒂·詹罗斯那里拿到一束花后，你将花束交给了Lakeshire Inn的达希，却意外撞进了一场尴尬的当地恩怨中。",h="“送交水仙花”任务内容包含在湖畔镇的卫兵岗哨与城镇广场之间的一次小型日常跑腿任务。在为卫兵帕克取来午餐，并从草药师玛蒂·詹罗斯那里拿到一束花后，你将花束交给了Lakeshire...",kw={"水仙花","达希","送交水仙花","卫兵帕克","湖畔镇","玛蒂·詹罗斯","赤脊山","清炒太阳鱼"},ang={["faction:Alliance"]="在湖畔镇协助城镇卫兵和旅店老板有助于维持平民的士气，因为该镇正处于黑石兽人和豺狼人的侵扰之中。",["profession:Cooking"]="达希用调味清炒太阳鱼来奖励你的送递，这也展示了赤脊山湖畔简单的家常烹饪。",["profession:Herbalism"]="这项跑腿任务依赖于玛蒂·詹罗斯的植物学知识和她对新鲜湖畔花卉的眼光，展现了草药采集的宁静一面。"},sec={{t="芬芳的差事",b="原本只是为卫兵帕克送上一顿热餐的简单任务，却演变成了一种微妙的浪漫举动。帕克为了感谢他的午餐，请求你从玛蒂·詹罗斯那里取来鲜花，作为给厨师达希的惊喜礼物，因为是她准备了他的食物。玛蒂精心搭配了一束她自己最喜欢的花——水仙花，她并不知道这些花是送给谁的。"},{t="城镇纷争",b="当你把花束带回Lakeshire Inn时，达希最初的喜悦迅速转为猜疑。达希一眼就认出水仙花是玛蒂的最爱，她立即怀疑帕克是与那个她眼中的妒妇扯上了关系。虽然达希担心如果玛蒂知道收花人是她，可能会怀恨在心地给花茎下毒，但她还是免除了对你的责怪，并给了你一份清炒太阳鱼作为补偿。"}},faq={{q="达希是谁？",a="达希在赤脊山的Lakeshire Inn工作，为当地居民和城镇卫兵准备餐点。她就是那位送午餐给卫兵帕克的厨师，这促使帕克为了表示感谢而回赠了她一束鲜花。",al={"达希","湖畔镇达希是谁","湖畔镇厨师达希"}},{q="玛蒂·詹罗斯是谁？",a="玛蒂·詹罗斯是湖畔镇当地的草药师和爱花之人。卫兵帕克指引你去她那里购买一束漂亮的花，玛蒂很高兴地采集了水仙花并束成一束，并提到这恰好是她自己最喜欢的花。",al={"玛蒂·詹罗斯","湖畔镇草药师","谁送的花"}},{q="为什么达希对水仙花感到生气？",a="达希一眼就认出水仙花是玛蒂最喜欢的花。她视玛蒂为嫉妒的竞争对手，并担心如果玛蒂知道这束花是送给达希的，她会在花茎上下毒。",al={"为什么达希生气","达希与玛蒂的恩怨","为什么花有毒"}},{q="玛蒂真的在花束里下毒了吗？",a="没有。玛蒂根本不知道这些花是送给达希的，因为帕克只是请你顺便取一束花，而玛蒂只是随手选了她自己最喜欢的花束装在一起。",al={"水仙花有毒吗","花束有毒吗"}},{q="有哪些任务引导至这次送花任务？",a="该任务链始于“免费的午餐”，你需要将达希的餐点送到卫兵帕克那里。接着帕克会给你“拜访草药师”任务，让你从玛蒂·詹罗斯那里购买礼物，最后以“送交水仙花”结束。",al={"任务链","水仙花前置任务","送交水仙花任务链"}},{q="送花的奖励是什么？",a="达希感谢你并送给你一份丰盛的清炒太阳鱼、一些铜币和经验值，同时你还会获得暴风城的声望。",al={"任务奖励","水仙花奖励"}}},fp="20,207,17.245.0,14.330.1,13.186.0,23.163.0,39.194.1,39.130.1,37.199.0,50.123.0"}
P.entries["quest:1319"] = {n="黑色盾牌",s="盖兰·维米斯队长很抱歉没能就这面被熏黑的铁盾牌提供太多帮助，但他知道谁能帮忙：卡兹·双链，这附近最好的铁匠之一，他负责照看塞拉摩铁匠铺的熔炉。",h="盖兰·维米斯队长很抱歉没能就这面被熏黑的铁盾牌提供太多帮助，但他知道谁能帮忙：卡兹·双链，这附近最好的铁匠之一，他负责照看塞拉摩铁匠铺的熔炉。",kw={"被熏黑的铁盾牌","盖兰·维米斯队长","卡兹·双链","尘泥沼泽","黑盾","塞拉摩"},sec={{t="能说出个所以然的铁匠",b="维米斯很抱歉自己无法为这面盾牌提供更多帮助，但他指出了一个可以帮忙的人。你带着它去找了卡兹·双链，他是最好的铁匠之一，负责照看塞拉摩铁匠铺的熔炉。也许卡兹能告诉你关于它的一些事情。"},{t="铁匠的见解",b="卡兹检查了一番这块铁，称其为一件有趣的物品。这不是卡兹自己的作品，也绝不是卡兹所知的任何这一带的铁匠的作品。"}},faq={{q="是谁让你去检查这面盾牌的？",a="塞拉摩的盖兰·维米斯队长，他很抱歉自己对此无能为力，并建议你去找更专业的人。",al={"谁给了黑盾","黑盾任务起始","谁开启黑盾任务"}},{q="卡兹·双链是谁？",a="一位负责照看塞拉摩铁匠铺熔炉的铁匠。维米斯认为他是最好的铁匠之一。",al={"卡兹·双链","塞拉摩的铁匠是谁"}},{q="展示给卡兹看的是什么盾牌？",a="被熏黑的铁盾牌。",al={"被熏黑的铁盾牌","我应该给卡兹看什么盾牌"}}},fp="16,207,19.248.0,19.161.1,36.110.0,23.88.0,28.26.0"}
P.entries["quest:132"] = {n="迪菲亚兄弟会",s="这项任务将黑衣威利掌握的关键地下情报传回给位于哨兵岭的格里安·斯托曼。黑衣威利的快报揭示了迪菲亚潜行者不仅仅是一群四散的强盗，而是一股勾结了当地豺狼人、狗头人和地精的有组织势力。斯托曼依靠这份情报来衡量困扰西部荒野的阴谋的全部规模。",h="这项任务将黑衣威利掌握的关键地下情报传回给位于哨兵岭的格里安·斯托曼。黑衣威利的快报揭示了迪菲亚潜行者不仅仅是一群四散的强盗，而是一股勾结了当地豺狼人、狗头人和地精的有组织势力。斯托曼依靠这份情报来衡量困扰西部荒野的阴谋...",kw={"迪菲亚潜行者","豺狼人","地精","格里安·斯托曼","狗头人","哨兵岭","西部荒野","黑衣威利","威利的便笺"},ang={["class:Rogue"]="黑衣威利是一个游走在歹徒与有用情报来源之间的人员范例，说明了地下关系网是如何推动战时情报工作的。",["faction:Alliance"]="发现人类歹徒、豺狼人和地精之间的跨种族协调，突显了暴风城西部边界留下的严重安全真空。",["race:Human"]="对于西部荒野和赤脊山的人民来说，这封便笺证实了洗劫他们家庭农场的强盗正在执行一项蓄意且协调一致的行动。"},sec={{t="危险的快报",b="黑衣威利声称，泄露他所知的关于迪菲亚潜行者的消息可能会让他丢掉性命。威利在赤脊山和西部荒野的边缘地带活动，他听闻了一个远比拦路抢劫宏大得多的行动。他那封密封的便笺详细描述了兄弟会是如何设法协调各地通常敌对的群体进行联合行动的。"},{t="匪夷所思的结盟",b="威利的警告核心在于迪菲亚潜行者所建立的令人震惊的网络。这些戴着红色面具的歹徒并没有孤军奋战，而是招募了豺狼人部族、狗头人挖掘者和投机取巧的地精工程师。这种野蛮武力、穴居劳工和机械狡诈的结合，标志着一项远超人民军最初预想的行动。"},{t="斯托曼的不安依靠",b="格里安·斯托曼对威利没什么好感，公开感叹当初有机会时没让这个流氓自生自灭。尽管如此，西部荒野付不起自尊的代价。由于暴风城无视军事援助的请求，人民军必须在任何能找到的地方获取可付诸行动的情报。"}},faq={{q="威利的便笺内容是什么？",a="这封便笺包含了黑衣威利的警告，即迪菲亚潜行者正在与豺狼人、狗头人和地精工程师进行协调。它告知人民军，这些歹徒正在准备一项远超小打小闹的巨大行动。",al={"威利的便笺","便笺的内容","黑衣威利的便笺"}},{q="黑衣威利是谁？",a="黑衣威利是驻扎在赤脊山湖畔镇的一个阴暗联系人。尽管格里安·斯托曼认为他是个不可信的恶棍，但威利与地下犯罪世界有着广泛的联系，并掌握着有关迪菲亚潜行者活动的关键信息。",al={"威利是谁","黑衣威利背景故事","湖畔镇的威利"}},{q="迪菲亚潜行者为什么要与豺狼人和狗头人结盟？",a="迪菲亚潜行者利用当地生物来控制领土并获取廉价劳动力。豺狼人提供野蛮的散兵来分散当地防御者的注意力，而狗头人在区域矿井中充当挖掘者，地精修补匠则提供重型机械和爆破工具。",al={"迪菲亚为何使用豺狼人","狗头人与迪菲亚","迪菲亚的盟友"}},{q="格里安·斯托曼为什么不喜欢威利？",a="格里安·斯托曼是一位纪律严明的退伍军人，他将威利视为一个普通的窃贼和罪犯。斯托曼后悔过去没有让他坐牢，尽管他承认威利在地下世界的眼线是不可或缺的。",al={"斯托曼与威利","为什么讨厌威利"}},{q="这条消息在人民军的调查中起到什么作用？",a="这次投递是连接当地侦察与揭开迪菲亚潜行者更深层阴谋的桥梁。将威利的消息带回，促使斯托曼进一步深入调查该阴谋的领导层和集结地。",al={"迪菲亚任务线步骤","这是什么任务"}},{q="为什么暴风城不处理这个威胁？",a="由于瓦里安·乌瑞恩国王失踪，暴风城贵族议会拒绝调拨皇家士兵或资金来保卫西部荒野。该地区只能依靠斯托曼领导的乌合之众——人民军——来保卫自己。",al={"暴风城援助西部荒野","守卫在哪里"}}},fp="22,250,20.328.0,18.328.0,29.283.0,27.217.0,23.229.0,50.238.0,41.187.0,61.203.0,41.193.0"}
P.entries["quest:1320"] = {n="黑色盾牌",s="卡兹·双链检查了那面与树荫旅店谜团有关的黑盾，差点漏掉最后一个细节。卡兹让你带着发现去塞拉摩找盖兰·维米斯队长。",h="卡兹·双链检查了那面与树荫旅店谜团有关的黑盾，差点漏掉最后一个细节。卡兹让你带着发现去塞拉摩找盖兰·维米斯队长。",kw={"黑盾","卡兹·双链","尘泥沼泽","盖兰·维米斯","树荫旅店","牛头人","塞拉摩"},sec={{t="烧断的皮带",b="在检查那面黑盾时，卡兹·双链差点漏掉最后一个细节：盾牌背面的皮带烧断了，但这根皮带似乎是为大块头量身定做的。卡兹推测是个牛头人。卡兹只能告诉你这些，他让你带着消息去塞拉摩找盖兰·维米斯队长，并为无法提供更多帮助表示歉意。"},{t="维米斯的看法",b="维米斯觉得这些线索微不足道，但他表示会记在心上。他希望谜团的其他碎片能拼凑起来，从而更清晰地揭示事情的真相。"}},faq={{q="卡兹·双链关于盾牌发现了什么？",a="盾牌背面的皮带烧断了，但它似乎是为大块头量身定做的。卡兹推测是个牛头人。",al={"卡兹的发现","盾牌线索","黑盾线索"}},{q="谁应该听听卡兹的发现？",a="塞拉摩的盖兰·维米斯队长。",al={"我该把盾牌的事告诉谁","上交黑盾","在哪里汇报盾牌"}}},fp="16,181,19.350.0,22.165.1,52.122.0,31.34.0"}
P.entries["quest:1321"] = {n="黑色盾牌",s="克罗格检查了被熏黑的铁盾牌，没有发现什么异常。克罗格建议让铁匠杜高尔鉴定一下，尽管他对此不抱太大希望，并让你前往蕨墙村。",h="克罗格检查了被熏黑的铁盾牌，没有发现什么异常。克罗格建议让铁匠杜高尔鉴定一下，尽管他对此不抱太大希望，并让你前往蕨墙村。",kw={"黑盾","被熏黑的铁盾牌","蕨墙村","杜高尔","尘泥沼泽","克罗格"},sec={{t="第二意见",b="克罗格没能看出这面盾牌有什么特别之处。克罗格说，铁匠杜高尔或许能提供更多信息，但他提醒不要抱太大期望。杜高尔就在蕨墙村。"},{t="杜高尔的回答",b="杜高尔称这面盾牌不错，既结实又沉重。但杜高尔不需要它，因为他是造盾的而不是买盾的，他认为你应该明白这一点。"}},faq={{q="是谁让你带着盾牌去找杜高尔的？",a="克罗格，他检查了被熏黑的铁盾牌，并认为它没有什么异常。",al={"谁发布了黑盾任务","在哪里开始黑盾任务","黑盾任务发布者"}},{q="在哪里可以找到杜高尔？",a="杜高尔是蕨墙村的铁匠。",al={"杜高尔位置","杜高尔在哪里","寻找杜高尔"}},{q="为什么克罗格让你去找杜高尔？",a="克罗格希望这位铁匠能提供更多关于这面盾牌的信息，尽管他认为可能也查不出什么。",al={"为什么要拜访杜高尔","为什么要给铁匠看这面盾牌"}}},fp="16,193,16.183.0,15.155.1,40.83.0,26.48.0,33.105.0"}
P.entries["quest:1322"] = {n="黑色盾牌",s="在蕨墙村，杜高尔注意到了盾牌边缘的刻字，但上面覆盖着烧焦的残留物。清除这些残留物需要酸液，杜高尔请求你从沼泽的暗牙蜘蛛身上获取六个毒囊。",h="在蕨墙村，杜高尔注意到了盾牌边缘的刻字，但上面覆盖着烧焦的残留物。清除这些残留物需要酸液，杜高尔请求你从沼泽的暗牙蜘蛛身上获取六个毒囊。",kw={"酸性毒囊","蕨墙村","暗牙","杜高尔","尘泥沼泽","黑色之盾"},sec={{t="清理边缘",b="杜高尔可以看到盾牌边缘的刻字，但烧焦的污垢让它难以辨认。酸液可以将其清除，而沼泽里的暗牙蜘蛛所携带的毒液效果很好。杜高尔需要六个它们的酸性毒囊来清理这面盾牌。"},{t="毒囊送达之后",b="杜高尔不喜欢那些大到没法直接坐上去压死的蜘蛛，随即感谢你带来的毒囊。杜高尔撕开它们，将里面的液体倒在盾牌上。"}},faq={{q="谁需要蜘蛛毒液？",a="蕨墙村的杜高尔。",al={"谁提供黑色之盾","杜高尔任务","谁开启黑色之盾"}},{q="杜高尔为什么要毒囊？",a="杜高尔需要酸液来清除覆盖在盾牌边缘刻字上的烧焦残留物，暗牙蜘蛛的毒液正好可以派上用场。",al={"为什么要蜘蛛酸液","酸性毒囊的用途","为什么要清洁盾牌"}},{q="酸性毒囊从哪里获得？",a="从生活在蕨墙村附近沼泽里的暗牙蜘蛛身上。",al={"哪种蜘蛛有毒囊","暗牙蜘蛛位置","哪里获取酸性毒液"}},{q="杜高尔需要多少个毒囊？",a="六个酸性毒囊。",al={"多少个毒囊"}}},fp="16,209,16.249.0,20.149.1,30.31.0,32.120.0,41.74.0,31.22.0"}
P.entries["quest:1323"] = {n="黑色盾牌",s="杜高尔把盾牌擦得足够干净，上面露出了一个名字，似乎是莫萨恩。这个名字对杜高尔来说毫无意义。蕨墙村的克罗格认识很多人，所以杜高尔让你去那里问问。",h="杜高尔把盾牌擦得足够干净，上面露出了一个名字，似乎是莫萨恩。这个名字对杜高尔来说毫无意义。蕨墙村的克罗格认识很多人，所以杜高尔让你去那里问问。",kw={"酸液","黑色盾牌","蕨墙村","杜高尔","尘泥沼泽","克罗格","莫萨恩"},sec={{t="边缘上的名字",b="杜高尔用的酸液稍微多了点，但在擦拭之后，上面显现出了一行字。虽然还是很难辨认，但看起来写着莫萨恩。这个名字对杜高尔来说毫无意义。蕨墙村的克罗格认识很多人，所以杜高尔让你去和克罗格谈谈。"},{t="克罗格的回答",b="克罗格觉得莫萨恩这个名字很耳熟，但想不起来是谁，他希望以后能想起来。克罗格补充说，这可能并不重要，因为盾牌来自各种地方，并没有什么特别的含义。"}},faq={{q="杜高尔是谁？",a="那个在蕨墙村用酸液清洗盾牌以辨认上面文字的人。",al={"杜高尔","谁给了黑色盾牌"}},{q="盾牌上写着什么名字？",a="杜高尔认为上面写的是莫萨恩，尽管很难辨认，而且他从未听说过这个名字的人。",al={"盾牌上的名字是什么","莫萨恩是谁","盾牌铭文名字"}},{q="为什么要找克罗格谈论盾牌？",a="杜高尔不知道莫萨恩是谁，但他说克罗格认识很多人。",al={"为什么要找克罗格","克罗格是谁"}},{q="克罗格在哪里？",a="克罗格在蕨墙村。",al={"克罗格的位置","我在哪里能找到克罗格"}}},fp="16,196,17.249.0,13.204.1,14.94.0,27.111.0,34.68.0,22.31.0"}
P.entries["quest:133"] = {n="食尸鬼假人",s="在暮色森林阴郁的荒野深处，古怪的隐士亚伯克隆比声称他那与世隔绝的小屋正遭受行尸走肉的围攻。为了保卫家园，他委托过路的冒险者收集食尸鬼的肋骨，用来拼凑一个诡异的防护稻草人。",h="在暮色森林阴郁的荒野深处，古怪的隐士亚伯克隆比声称他那与世隔绝的小屋正遭受行尸走肉的围攻。为了保卫家园，他委托过路的冒险者收集食尸鬼的肋骨，用来拼凑一个诡异的防护稻草人。",kw={"亚伯克隆比","嚼骨者","夜色镇","暮色森林","雕像","肉食者","食尸鬼的肋骨","隐士"},ang={["class:Paladin"]="猎杀肉食者和嚼骨者能净化暮色森林土地上的枯萎病，即使把它们的残骸交给一个隐士让人感到非常不安。",["class:Priest"]="帮助被困在黑暗灵魂之中的惊恐隐士是一项高尚的工作，尽管用收集来的残骸组装雕像确实考验人的胃口。",["faction:Alliance"]="夜色守卫难以保护好道路，使得像亚伯克隆比这样与世隔绝的森林居民只能依靠路过的联盟旅行者来抵御The Restless Dead。"},sec={{t="隐士的困境",b="亚伯克隆比居住在夜色镇的防御边界之外，孤零零地守在暮色森林那阴森的树林里。在这里，肉食者和嚼骨者之类的食尸鬼四处游荡，无人阻拦。这位惊慌失措的隐士声称最近有贪婪的尸体砸坏了他的墙壁，因此请求冒险者带来这些恐怖生物的肋骨来制作威慑物，希望这个令人毛骨悚然的雕像能让那些饥饿的死者退避三舍。"},{t="奇特的防御",b="尽管常识告诉人们应该逃向夜色守卫的安全庇护所或加固他的木屋，但亚伯克隆比却坚持采用这种可怕的方法。他相信竖立一个由食尸鬼残骸制成的雕像能吓跑其他游荡的死者。虽然用被屠杀的亡灵制作稻草人听起来令人不安，但在暮色森林旅行的人往往还是会听从这位古怪隐士的话，以此赚取一些急需的金币。"}},faq={{q="亚伯克隆比住在哪里？",a="亚伯克隆比住在暮色森林西部一间孤零零的小屋里，就在乌鸦岭墓地的东北方，远离夜色镇的保护范围。",al={"亚伯克隆比位置","亚伯克隆比的小屋在哪里","暮色森林隐士小屋"}},{q="为什么亚伯克隆比需要食尸鬼的肋骨？",a="亚伯克隆比声称有一群食尸鬼正在撞击他小屋的墙壁。他打算用这些骨头制作一个令人毛骨悚然的稻草人雕像，以吓跑四处游荡的亡灵。",al={"食尸鬼的肋骨用途","为什么需要食尸鬼的肋骨","雕像是用来做什么的"}},{q="哪些生物会掉落食尸鬼的肋骨？",a="肋骨可以从暮色森林道路和墓地中游荡的任何当地亡灵身上收集到，特别是肉食者、嚼骨者、食脑者、腐烂者和瘟疫散布者。",al={"哪里可以获得肋骨","食尸鬼的肋骨掉落","哪些食尸鬼掉落肋骨"}},{q="用亡灵做成的稻草人真的能驱赶食尸鬼吗？",a="亡灵几乎从不知道恐惧为何物，这让经验丰富的怪物猎人对亚伯克隆比的计划深表怀疑。不过，这位隐士坚持要搞他那奇怪的工程，在这种绝望的森林里，很少有人会质疑雇主的意图。",al={"雕像对食尸鬼有效吗","食尸鬼稻草人逻辑"}},{q="为什么亚伯克隆比不干脆搬到夜色镇去？",a="亚伯克隆比选择远离夜色守卫和城镇管理，过着与世隔绝的生活。尽管暮色森林的荒野中危机四伏，他还是更喜欢独自管理自己的小屋，并使用自己那套奇特的防御手段。",al={"为什么要住在树林里","为什么亚伯克隆比不搬走","夜色镇安全"}},{q="收集到肋骨之后接下来要做什么？",a="收到食尸鬼的肋骨后，亚伯克隆比又遇到了另一个奇怪的难题需要解决，他会派遣冒险者进一步深入荒野，去对付那些偷了他财物的食人魔。",al={"后续任务","食尸鬼的雕像之后"}}},fp="15,150,17.329.0,17.300.0,28.133.0,37.158.0,36.153.0,56.163.0,53.180.0,41.161.0"}
P.entries["quest:1338"] = {n="卡尔·雷矛的订单",s="驻扎在洛克莫丹雪山之巅的巡山人卡尔·雷矛，渴望得到由著名护甲匠弗伦·长须打造的一面盾牌。由于弗伦在遥远的南方暴风城安家立业，这位巡山人便委托一名四处旅行的冒险者去递送这份订单。",h="驻扎在洛克莫丹雪山之巅的巡山人卡尔·雷矛，渴望得到由著名护甲匠弗伦·长须打造的一面盾牌。由于弗伦在遥远的南方暴风城安家立业，这位巡山人便委托一名四处旅行的冒险者去递送这份订单。",kw={"铁匠","dwarven district","弗伦·长须","铁炉堡","洛克莫丹","盾牌","雷矛","暴风城"},ang={["faction:Alliance"]="这次交付展示了卡兹莫丹的矮人据点与人类首都暴风城之间通过矿道地铁建立的紧密贸易和文化联系。",["profession:Blacksmithing"]="弗伦·长须即使在各个王国中都被公认为卓越的护甲匠，这使得他成为在暴风城旅行的准铁匠们值得一去的地方。",["race:Dwarf"]="对于矮人来说，这次交付突显了雷矛这样的氏族名望的影响力，同时也戏谑地质疑为何一位大师级护甲匠会选择人类的岩石而非铁炉堡。"},sec={{t="值得长途跋涉的盾牌",b="即使是在洛克莫丹这样的偏远哨所，矮人巡山人对工艺也有着强烈的看法。巡山人卡尔·雷矛坚持认为只有一位铁匠能打造他的下一面盾牌，那就是弗伦·长须。深信长须的才华首屈一指，雷矛愿意支付丰厚的报酬，哪怕相隔千山万水，也要将这份委托送到这位大师手中。"},{t="从铁炉堡到Dwarven District",b="最让雷矛困惑的是弗伦的所在地。长须并没有像他的同胞一样留在铁炉堡的Great Forge附近，而是在遥远南方的暴风城Dwarven District靠打铁为生。雷矛猜测人类一定付出了天价报酬，才诱使这样一位工匠离开了他的祖居地。当信件最终传达到铁砧旁的弗伦手中时，这位铁匠因为收到了久负盛名的雷矛氏族的来信而感到自豪，并急切地准备开始打造这面盾牌。"}},faq={{q="巡山人卡尔·雷矛是谁？",a="他是驻扎在洛克莫丹的一名联盟哨兵，隶属于保护山口和山谷的矮人巡山人部队。他属于引以为傲且势力强大的雷矛氏族。",al={"巡山人卡尔·雷矛","谁给予任务","任务发布者"}},{q="弗伦·长须是谁？",a="弗伦·长须是一位成就卓著的矮人护甲匠，居住在暴风城的Dwarven District。他打造精良盾牌和护甲的名声甚至传到了遥北的卡兹莫丹。",al={"弗伦·长须","弗伦是谁","护甲匠"}},{q="为什么弗伦住在暴风城而不是铁炉堡？",a="虽然像巡山人卡尔·雷矛这样的传统主义者会疑惑为何大师级矮人要抛弃铁炉堡，但弗伦在暴风城的Dwarven District经营自己的生意是为了迎合人类贵族、城市卫兵和旅行冒险者的需求，这很可能让他赚取了丰厚的人类钱币。",al={"为什么弗伦在暴风城","为什么在dwarven district","弗伦离开铁炉堡"}},{q="矿道地铁在交付订单中扮演什么角色？",a="携带雷矛信件的旅行者通常从洛克莫丹向西前往铁炉堡，然后搭乘地下的矿道地铁直接前往弗伦的铁匠铺所在的暴风城Dwarven District。",al={"前往暴风城","如何到达暴风城","矿道地铁"}},{q="这个任务之前有什么任务？",a="在将前往暴风城的快递任务交给你之前，巡山人卡尔·雷矛会在洛克莫丹通过“巡山人卡尔·雷矛的任务”来考验你的勇气和可靠性。",al={"前置条件","前序任务","巡山人卡尔·雷矛的任务"}},{q="弗伦·长须会立刻打造盾牌吗？",a="在收到信件并意识到雷矛之名带来的声望后，弗伦欣然接受了委托，并承诺在当天结束前就开始打造这面盾牌。",al={"接下来发生什么","后续任务","弗伦的反应"}}},fp="17,185,26.228.0,38.337.0,29.210.0,23.184.0,54.258.0,57.195.0,29.160.0,50.191.0"}
P.entries["quest:1339"] = {n="巡山人卡尔·雷矛的任务",s="“巡山人卡尔·雷矛的任务”是洛克莫丹的一项简短的联盟信使差事。巡山人卡德雷尔指引漫游的冒险者前往北方的岗哨塔，在那儿巡山人卡尔·雷矛需要一位可靠的跑腿者去执行一项山谷之外的委派。这可以看作是一项更长远差事的开端，其影响延伸到了邻近的土地。",h="“巡山人卡尔·雷矛的任务”是洛克莫丹的一项简短的联盟信使差事。巡山人卡德雷尔指引漫游的冒险者前往北方的岗哨塔，在那儿巡山人卡尔·雷矛需要一位可靠的跑腿者去执行一项山谷之外的委派。这可以看作是一项更长远差事的开端，其影响延...",kw={"岗哨塔","铁炉堡","洛克莫丹","巡山人卡德雷尔","巡山人卡尔·雷矛","跑腿者","雷矛的订单","塞尔萨玛"},ang={["faction:Alliance"]="为区域巡山人承担信使派遣工作，能确保铁炉堡的驻军在东部各领地之间获得持续的补给与协调。",["race:Dwarf"]="协助闻名遐迩的雷矛氏族的矮人同胞，对于任何尊重卡兹莫丹氏族关系的漫游者来说都是一种自然的职责。"},sec={{t="需要一名跑腿者的岗哨",b="巡逻洛克莫丹的道路和哨所让巡山人们疲于应付穴居人的入侵和横行的野生动物。巡山人卡德雷尔经常会将有能力的旅人指引给那些无法擅离职守的卫兵。身处北方岗哨塔高处的巡山人卡尔·雷矛正被守卫职责所困，而此时他急需一名信使将一份重要的私人事务带往该区域边界之外。"},{t="从岗哨塔到远方之路",b="要找到卡尔·雷矛，需要攀登俯瞰山谷的北方岗哨塔。作为显赫的雷矛氏族的一员，他的事务往往超出了塞尔萨玛日常的边境防务。接受他的任务意味着同意代他将口信和补给送到区域边界之外，这也为初出茅庐的冒险者提供了迈出洛克湖、踏上卡兹莫丹更宽广公路的重要一步。"}},faq={{q="我在哪里可以找到巡山人卡尔·雷矛？",a="巡山人卡尔·雷矛驻扎在洛克莫丹的北方岗哨塔顶端，监视着周围的小径。",al={"雷矛位置","雷矛在哪里","寻找雷矛岗哨塔"}},{q="谁发布这个任务？",a="巡山人卡德雷尔，他在洛克莫丹的塞尔萨玛附近巡逻，会指引你前往卡尔·雷矛的塔楼，从而开启此任务。",al={"谁发布巡山人卡尔·雷矛的任务","任务发布者","卡德雷尔位置"}},{q="为什么卡尔·雷矛需要一名冒险者？",a="作为一名现役巡山人，卡尔·雷矛无法擅离他在塔楼的岗哨。他的私人差事需要前往洛克莫丹区域之外，因此一位无拘无束的冒险者是理想的信使人选。",al={"为何需要跑腿者","雷矛的问题","雷矛想要什么"}},{q="向卡尔·雷矛报到后会发生什么？",a="与卡尔·雷矛交谈即可完成这个入门步骤，并解锁他的后续差事“雷矛的订单”，该任务会派你去往另一个地区进行投递。",al={"后续任务","巡山人卡尔·雷矛的任务之后是什么","雷矛后续"}},{q="这和奥特兰克山谷的雷矛卫队有关吗？",a="巡山人卡尔·雷矛与以雷矛卫队和采矿探险闻名的雷矛氏族同名且血脉相连，尽管这项具体的委派只是一个普通的地方性差事。",al={"雷矛氏族渊源","奥特兰克山谷雷矛","这是奥特兰克山谷的雷矛吗"}},{q="部落玩家有对应的任务吗？",a="没有。洛克莫丹是完全由联盟控制的矮人领土，巡山人会对部落旅行者视而不见地发起攻击。",al={"部落版本","部落可以做这个吗"}}},fp="28,223,30.401.0,27.314.0,38.125.0,22.97.0,38.146.0,42.134.0,50.174.0,47.116.0"}
P.entries["quest:134"] = {n="食人魔潜行者",s="住在暮色森林西部的古怪隐士亚伯克隆比，请求旅行者冒险进入沃古尔食人魔山这个食人魔据点。他声称在他觅食时，食人魔伏击了他，并抢走了一个装满了他无法替代的草药和工具的箱子。",h="住在暮色森林西部的古怪隐士亚伯克隆比，请求旅行者冒险进入沃古尔食人魔山这个食人魔据点。他声称在他觅食时，食人魔伏击了他，并抢走了一个装满了他无法替代的草药和工具的箱子。",kw={"亚伯克隆比","箱子","暮色森林","隐士","食人魔","沃古尔"},ang={["class:Paladin"]="亚伯克隆比在找回箱子时那急切、隐秘的喜悦，应该让任何圣光的仆从对盲目帮助这位隐居者保持警惕。",["class:Warlock"]="熟悉禁忌艺术的术士会很容易认出亚伯克隆比的口误是对黑暗法术的颂歌，而不是单纯的植物学热情。",["profession:Herbalism"]="虽然亚伯克隆比声称他的箱子里只装有普通的草药，但一位草药师可能会好奇，什么样的奇异植物需要如此不顾一切地从食人魔山岗中取回。"},sec={{t="隐士丢失的货物",b="亚伯克隆比这位年迈的隐士孤零零地住在暮色森林西部潮湿的道路旁，他声称自己在荒野收集补给时遭到了袭击。据他所说，来自南部食人魔山岗的蛮兵将他赶走，迫使他丢下了一个装满珍贵草药和Delicate Instruments的坚固木箱。"},{t="沃古尔的威胁",b="位于暮色森林南部的沃古尔食人魔山，是一个敌对食人魔的堡垒，他们经常骚扰毫无防备的游荡者。那个箱子就放在他们洞穴状山岗的入口附近，向外人挑衅，要他们闯过咆哮的蛮兵和编织法术的法师，将其带回给隐士。"},{t="口误",b="当取回丢失的货物时，亚伯克隆比那古怪的神态中流露出了疯狂的兴奋。他差点就喊出对“亡灵……”的赞美，随后急忙改口感谢冒险者，迫不及待地想把自己锁起来，在黑暗中使用取回的补给。"}},faq={{q="亚伯克隆比是谁？",a="亚伯克隆比是一位古怪、孤僻的隐士，住在一间位于暮色森林西部的破旧小屋里。虽然他表现得虚弱、无助，似乎需要援助，但他那狂乱的行为和奇怪的要求暗示着更黑暗、更令人不安的动机。",al={"亚伯克隆比背景故事","谁给了我这个任务","隐士是谁"}},{q="食人魔把亚伯克隆比的箱子带到哪里去了？",a="箱子被带到了暮色森林南部的沃古尔食人魔山。它被直接放在食人魔洞穴口外面的泥地上，清晰可见。",al={"箱子在哪里","箱子位置","沃古尔箱子"}},{q="为什么暮色森林里会有食人魔？",a="沃古尔氏族的食人魔在暮色森林崎岖的南部丘陵建立了一个立足点。他们充满侵略性和机会主义，经常抢劫过路人，伏击落单的游荡者，并将偷来的战利品囤积在他们的山岗周围。",al={"暮色森林食人魔","沃古尔食人魔起源","为什么食人魔在这里"}},{q="箱子里到底装的是什么？",a="亚伯克隆比声称箱子里装的是他在袭击中遗弃的稀有草药和专门的采集工具，能找回它们让他欣喜若狂。",al={"亚伯克隆比丢了什么","箱子内容物"}},{q="亚伯克隆比在收到箱子时差点说了什么？",a="在取回箱子后，亚伯克隆比刚开始想要感谢别人，却突然打住，转而感谢冒险者，随后他欢欣地期待着接下来的夜晚。",al={"感谢亡灵","亚伯克隆比在说什么","亚伯克隆比引言"}},{q="这个任务和其他食人魔山岗的任务有关联吗？",a="前往沃古尔食人魔山的冒险者可能同时也在为维克托·安特拉斯收集食人魔单片眼镜。",al={"食人魔山岗任务","沃古尔附近任务"}}},fp="12,193,21.258.0,18.190.0,20.264.1,19.202.0,45.143.0,32.211.0,34.145.1,57.170.1,57.100.0"}
P.entries["quest:135"] = {n="迪菲亚兄弟会",s="这个任务标志着西部荒野反抗肆虐乡间匪徒战役的一个关键转折点。格里安·斯托曼将你派往暴风城，去给马迪亚斯·肖尔大师送一封意味深长的信，因为他怀疑迪菲亚潜行者与昔日的石匠工会有关。",h="这个任务标志着西部荒野反抗肆虐乡间匪徒战役的一个关键转折点。格里安·斯托曼将你派往暴风城，去给马迪亚斯·肖尔大师送一封意味深长的信，因为他怀疑迪菲亚潜行者与昔日的石匠工会有关。",kw={"兄弟会","迪菲亚","格里安·斯托曼","mathias shaw","old town","军情七处","石匠","西部荒野","威利的便笺"},ang={["class:Rogue"]="访问军情七处总部让你与马迪亚斯·肖尔——暴风城潜行者和间谍大师——面对面，将西部荒野的当地动乱与更宏大的阴谋联系在了一起。",["faction:Alliance"]="该任务揭示了联盟主要王国内部的裂痕，表明并非所有的威胁都来自邪恶的外部势力，还有来自被背叛的公民。",["race:Human"]="对于暴风城的人类来说，这个任务将西部荒野的无法无天与首都重建后那些苦涩、未解决的政治丑闻联系了起来。"},sec={{t="口误",b="在调查西部荒野的混乱时，格里安·斯托曼在黑衣威利的通信中发现了一个奇怪的细节：提到了石匠。那个在第一次战争后重建了暴风城的建筑工会，人们一直以为他们已经四散或解散了。如果迪菲亚潜行者与他们有联系，那么这场乡村叛乱就远不止是一群乌合之众的非法暴动了。"},{t="Old Town的秘密",b="斯托曼无法在哨兵岭核实这些怀疑。为了获得真正的王国情报，他指示你去找马迪亚斯·肖尔大师，他是暴风城秘密情报组织军情七处的首领。肖尔在Old Town的兵营里运作，收集来自王国各地的风声和秘密，这使他成为唯一有能力揭开迪菲亚起源之谜的人。"},{t="王冠之影",b="当看到威利的便笺时，肖尔立刻意识到了事态的严重性。他证实，西部荒野的叛乱比像斯托曼这样的民兵指挥官所理解的要深刻得多，也复杂得多，直接指向了暴风城自身动荡的过去。"}},faq={{q="为什么格里安·斯托曼要把你派往暴风城？",a="斯托曼在威利的便笺中发现了一个关于石匠的线索。他意识到这指向的是潜在的政治阴谋，而非简单的盗匪行径，因此他派你去找暴风城的间谍头目马迪亚斯·肖尔大师，以核实这种联系。",al={"为什么要前往暴风城","为什么要接暴风城任务","斯托曼的暴风城差事"}},{q="马迪亚斯·肖尔是谁？",a="马迪亚斯·肖尔大师是军情七处的首领，这是暴风城王国的秘密情报和间谍分支机构。他的总部设在隐藏于Old Town兵营内的地方。",al={"肖尔是谁","马迪亚斯·肖尔的职责","军情七处首领"}},{q="我在哪里能找到马迪亚斯·肖尔？",a="肖尔位于暴风城Old Town兵营内军情七处总部的二楼。",al={"肖尔在哪里","肖尔的位置","寻找马迪亚斯·肖尔"}},{q="迪菲亚潜行者和石匠之间有什么联系？",a="石匠工会在第一次战争摧毁暴风城后将其重建。斯托曼怀疑威利提到的工会是一个口误，这将其与迪菲亚潜行者联系在了一起，而马迪亚斯·肖尔是唯一能证实或否认这一点的人。",al={"迪菲亚与石匠","迪菲亚是石匠吗","石匠的联系"}},{q="什么是威利的便笺？",a="这是一封来自黑衣威利的便笺，他是一个格里安·斯托曼曾打过交道的恶棍。便笺警告说迪菲亚潜行者正在与豺狼人、狗头人和地精勾结。其中一个口误无意中将迪菲亚潜行者的行动与前石匠工会联系了起来。",al={"威利的便笺","便笺的内容","送给肖尔的信"}},{q="伯瓦尔·弗塔根公爵或小国王知道这件事吗？",a="关于国家安全的机密事务在传达给伯瓦尔·弗塔根公爵和王座之前，都会先经过马迪亚斯·肖尔和军情七处的过滤。肖尔对此的回应只是说，事情可能比斯托曼所意识到的更为复杂。",al={"国王知道吗","伯瓦尔知道吗","暴风城政府的情报"}}},fp="22,207,20.332.0,16.314.0,25.215.1,49.179.0,20.125.0,29.118.0,62.212.1,21.255.0,53.181.0"}
P.entries["quest:1358"] = {n="给赫布瑞姆的样本",s="“赫布瑞姆的样本”是一项部落的信使任务，旨在将幽暗城的炼金实验与卡利姆多中部的被遗忘者哨所联系起来。该任务由药剂师金格委派，要求信使跨越海洋，将一颗被瘟疫感染的狼心送到十字路口的药剂师赫布瑞姆手中。",h="“赫布瑞姆的样本”是一项部落的信使任务，旨在将幽暗城的炼金实验与卡利姆多中部的被遗忘者哨所联系起来。该任务由药剂师金格委派，要求信使跨越海洋，将一颗被瘟疫感染的狼心送到十字路口的药剂师赫布瑞姆手中。",kw={"药剂师赫布瑞姆","药剂师金格","十字路口","皇家药剂师学会","赫布瑞姆的样本","贫瘠之地","幽暗城","狼心样本"},ang={["faction:Horde"]="虽然兽人和牛头人欢迎被遗忘者在保卫十字路口时提供的援助，但药剂师们对染疫遗骸的秘密解剖，却给宁静的贫瘠之地带来了一种阴暗且令人不安的气息。",["race:Undead"]="将受污染的样本运送到世界各地，凸显了皇家药剂师学会深远的野心，即通过化学统治力来确保被遗忘者的霸权。"},sec={{t="跨越重洋的瘟疫",b="皇家药剂师学会很少将他们令人毛骨悚然的实验局限在洛丹伦废墟之中。在从银松森林的药剂师伦弗利尔处收到受污染的器官后，幽暗城的药剂师金格试图将其研究扩展至全球。她委托一名冒险者携带一份狼心样本，将其运送到位于贫瘠之地干旱大草原上的炼金术士——药剂师赫布瑞姆手中。"},{t="赫布瑞姆的野心",b="药剂师赫布瑞姆驻扎在十字路口的塔顶，研究卡利姆多本土野兽对源自瘟疫之地的剧毒化合物有何反应。送达的狼心为极端毒性研究提供了宝贵的见解。赫布瑞姆相信，将该样本与当地生物进行解剖和测试，将极大地提升被遗忘者对毒药和非自然疾病的掌握能力。"}},faq={{q="送给赫布瑞姆的包裹里是什么？",a="包裹里装的是狼心样本，最初由药剂师伦弗利尔从银松森林的堕落狼群身上获取，并由幽暗城的药剂师金格进行过分析。",al={"样本是什么","狼心包裹","金格给了什么"}},{q="为什么药剂师赫布瑞姆需要一颗受污染的狼心？",a="赫布瑞姆正在研究源自洛丹伦的毒素如何影响卡利姆多的野生动物。他打算研究这种狼心的极端毒性，从而为皇家药剂师学会研制出更强力的药剂和毒药。",al={"赫布瑞姆为何需要狼心","赫布瑞姆的研究","赫布瑞姆的目的"}},{q="药剂师赫布瑞姆在哪里？",a="赫布瑞姆驻扎在贫瘠之地的十字路口。你可以在俯瞰整个营地的中央哨塔上层外甲板上找到他。",al={"赫布瑞姆在哪","赫布瑞姆的位置","寻找赫布瑞姆"}},{q="旅行者如何从幽暗城前往十字路口？",a="旅行者需在幽暗城外的飞艇塔搭乘飞艇前往杜隆塔尔的奥格瑞玛。从奥格瑞玛出发，向南穿过杜隆塔尔，跨过怒水河进入贫瘠之地，然后沿主路向西行进即可到达十字路口。",al={"前往十字路口","如何到达赫布瑞姆处","从幽暗城到贫瘠之地"}},{q="药剂师伦弗利尔和药剂师金格是谁？",a="他们都是皇家药剂师学会的研究员。伦弗利尔在银松森林的瑟伯切尔开展工作，而金格则在幽暗城的Apothecarium内进行研究。",al={"谁是伦弗利尔","谁是金格","金格与伦弗利尔的背景"}},{q="这项研究为哪个阵营服务？",a="这项研究直接服务于Sylvanas Windrunner麾下的被遗忘者和皇家药剂师学会，旨在推进他们制造致命化学和生物武器的总体计划。",al={"谁受益","这是为了sylvanas吗","药剂师的目标"}}},fp="18,179,26.403.0,18.310.0,47.165.0,54.192.0,36.146.0,57.199.0,50.205.0,38.172.0"}
P.entries["quest:1359"] = {n="给金格的货物",s="“金格的货物”是一项由银松森林瑟伯切尔的药剂师伦弗利尔派发的信使任务。它负责将一种异常有毒的狼心组织运回幽暗城的药剂师金格处，供皇家药剂师协会进行正式研究。",h="“金格的货物”是一项由银松森林瑟伯切尔的药剂师伦弗利尔派发的信使任务。它负责将一种异常有毒的狼心组织运回幽暗城的药剂师金格处，供皇家药剂师协会进行正式研究。",kw={"apothecarium","药剂师伦弗利尔","药剂师金格","瑟伯切尔","银松森林","幽暗城","狼心样本","金格的货物"},ang={["faction:Horde"]="携带生物试剂的信使们将瑟伯切尔等偏远哨点与幽暗城的领导层和研究中心紧密联系在了一起。",["race:Undead"]="在洛丹伦采集的实地样本直接汇入首都废墟下的中央炼金实验室，推动了被遗忘者科学力量的发展。"},sec={{t="毒性异常",b="药剂师伦弗利尔在检查银松森林周边的当地野生动物时，观察到那些在荒废森林中游荡的狼体内存在一种令人不安的生理特征。它们心脏所携带的毒性极其强烈，按常理来说，这本应杀死这些宿主野兽。伦弗利尔没有丢弃这些组织，而是将其打包，分发给幽暗城Apothecarium的同事们。"},{t="药剂师之眼",b="这些保存完好的器官被直接送往药剂师金格手中，她是一位在皇家药剂师协会地下总部工作的研究员。对于以研制强力瘟疫和新型炼金化合物为主要目标的协会来说，这种维持生命而非夺取生命的天然毒素具有极高的研究价值。金格欢迎这项交付，并将其作为在被遗忘者炼金网络中进行进一步实验室试验的基础。"}},faq={{q="什么是狼心样本？",a="它们是从银松森林的狼身上收集的保存完好的生物组织。药剂师伦弗利尔发现，这些心脏中含有极其致命的天然毒素，按理说，这些动物携带它们是不可能存活下来的。",al={"狼心","什么是狼心样本","伦弗利尔样本"}},{q="药剂师伦弗利尔是谁？",a="药剂师伦弗利尔是皇家药剂师协会的一员，驻扎在银松森林的瑟伯切尔。他负责监督该地区的动植物实地研究，为被遗忘者的炼金术采集原料并获取生物学见解。",al={"伦弗利尔是谁","伦弗利尔 银松森林"}},{q="药剂师金格是谁？",a="药剂师金格是一位常驻于幽暗城Apothecarium区的炼金研究员。她负责对送来的生物标本进行实验，从而为被遗忘者发掘新的毒素和炼金药剂。",al={"金格是谁","金格 幽暗城","药剂师金格背景"}},{q="这项交付后续会流向哪里？",a="一旦金格收到并检查了这些奇怪的心脏组织，研究工作便会继续，样本会被分发到其他的炼金据点，例如驻扎在海对岸贫瘠之地的药剂师赫布瑞姆处。",al={"后续任务","金格的货物之后发生了什么"}},{q="为什么皇家药剂师协会对狼心感兴趣？",a="皇家药剂师协会一直在寻找异域毒素、疾病和生物异常现象。一种能抵抗致命自身毒性存活下来的野兽，展示了独特的化学路径，这可能有助于他们开发新的瘟疫和化合物。",al={"为什么药剂师需要狼心","皇家药剂师协会 狼心"}},{q="幽暗城的Apothecarium在哪里？",a="Apothecarium位于幽暗城的西南翼。它是皇家药剂师协会的主要实验室综合体和管理总部。",al={"幽暗城药剂师位置","金格在哪里","apothecarium地图"}}},fp="16,255,15.290.0,28.351.0,32.186.0,28.226.0,24.187.0,35.183.1,62.196.0,39.144.0"}
P.entries["quest:136"] = {n="杉德尔船长的宝藏",s="“桑德斯船长的藏宝图”是西部荒野海岸线上多阶段寻宝任务的第一步。这张破旧的羊皮纸地图触发了任务，指引寻宝者在海岸边搜寻这位已故船长的个人脚箱。找到埋藏的脚箱后，便会在该地区展开寻找他隐藏战利品的冒险。",h="“桑德斯船长的藏宝图”是西部荒野海岸线上多阶段寻宝任务的第一步。这张破旧的羊皮纸地图触发了任务，指引寻宝者在海岸边搜寻这位已故船长的个人脚箱。找到埋藏的脚箱后，便会在该地区展开寻找他隐藏战利品的冒险。",kw={"桑德斯船长","脚箱","隐藏的财宝","锈蚀的铁锚","沉船","藏宝图","西部荒野海岸"},ang={["class:Rogue"]="对于那些深谙沿法外之地的海岸线追寻死者地图价值的无赖和私掠者来说，海盗寻宝早已是家常便饭。",["faction:Alliance"]="西部荒野的海岸上充满了沿海鱼人和残骸，在这片王国的边境动荡之中，任何对海中财富的打捞都算得上是一场小小的胜利。"},sec={{t="水手的遗愿",b="西部荒野西海岸的海面上遍布着沉船、残破的船体，以及溺水水手们不得安息的亡魂。桑德斯船长也是这些深海亡魂中的一员，这位老水手最终葬身鱼腹。他不愿让自己辛苦积攒的财富被无尽之海吞没，也不愿被拾荒者洗劫一空，于是写下了一系列晦涩难懂的指示，留下了一条只有坚定的冒险者才能追寻的线索。"},{t="锈蚀的铁锚",b="寻宝的第一步引导寻找者前往西海岸冲刷处的一只锈蚀铁锚。船长那个老旧的脚箱半掩在沉船附近的沙子里，幸免于惊涛骇浪的冲刷。箱子里装的不是金币，而是海水、沙子和一个意想不到的守卫：一只紧紧抓着桑德斯谜题下一部分的螃蟹。"}},faq={{q="桑德斯船长是谁？",a="桑德斯船长是一位老海员，他的地图上写着，如果有人读到这份地图，那么他本人已经葬身鱼腹了。他留下了这张地图和一系列线索，引导人们去寻找他隐藏的财宝。",al={"桑德斯船长背景故事","桑德斯是谁","桑德斯生平"}},{q="脚箱在哪里？",a="脚箱半掩在西部荒野西海岸的沙滩里。虽然海滩上散落着许多沉船，但桑德斯特别提到，它位于海岸线附近一只醒目的、孤独的锈蚀铁锚旁边。",al={"脚箱位置","锈蚀的铁锚在哪里","寻找桑德斯的脚箱"}},{q="脚箱里有船长的财宝吗？",a="地图会将你指引向一个脚箱，以及这场漫长寻宝之旅的下一条线索。",al={"箱子里有财宝吗","脚箱里有什么","金子在哪里"}},{q="桑德斯船长的寻宝任务一共有多少条线索？",a="这项寻宝任务跨越了西部荒野的海岸和乡村，共分为四个步骤，从这张地图开始，最终在海岸外的一座岛屿上找到桑德斯船长真正的藏宝箱。",al={"桑德斯任务有多长","一共多少部分","桑德斯任务链"}},{q="为什么桑德斯船长把财宝埋在西部荒野？",a="他的地图从未说明为什么要选择西部荒野。它只透露出他预料到自己最终会葬身水底，并希望跟随他线索的人能得到他的财宝。这些线索被他散布在西部荒野海岸和其上方峭壁的各个地标之间。",al={"为什么要藏宝","为什么是西部荒野海岸"}},{q="部落玩家可以完成这个寻宝任务吗？",a="可以。桑德斯船长的地图和后续线索都是阵营中立的，任何冲上岸边或勇敢探索西部荒野海岸的冒险者都可以追寻他的足迹。",al={"部落可以做这个任务吗","部落桑德斯任务","阵营中立财宝"}}},fp="32,243,23.319.0,16.278.1,24.149.0,32.122.0,51.80.1,53.170.0,54.217.0,43.117.0"}
P.entries["quest:1361"] = {n="雷戈萨·死门",s="这份指令旨在从各大主城派遣经验丰富的部落勇士，以增援贫瘠之地西部的一处前哨站。老练的战士雷格萨·死门正在招募有能力的志愿者，为即将展开的横跨山脉、进入凄凉之地荒漠的战役做准备。他正在寻找愿意挥舞部落钢铁，对抗那些蹂躏边境的半人马部族的勇士。",h="这份指令旨在从各大主城派遣经验丰富的部落勇士，以增援贫瘠之地西部的一处前哨站。老练的战士雷格萨·死门正在招募有能力的志愿者，为即将展开的横跨山脉、进入凄凉之地荒漠的战役做准备。他正在寻找愿意挥舞部落钢铁，对抗那些蹂躏边境...",kw={"贝尔戈洛姆·石槌","十字路口","凄凉之地","科卡尔","克鲁斯克","纳兹格勒","雷格萨·死门","贫瘠之地","沃金"},ang={["class:Warrior"]="雷格萨看重直截了当的战斗能力和坚定不移的纪律，这使得他的征召令成为渴望在险恶荒原中磨练自己实力的前线战士的天然试炼。",["faction:Horde"]="这项任务代表了部落主动出击的边境防御，确保邻近的凄凉之地中好战的半人马种群在能够深入劫掠贫瘠之地前就被镇压。",["race:Tauren"]="在经历了数代人与横跨卡利姆多中部的半人马进行的残酷冲突后，牛头人战士对于协助雷格萨打击科卡尔半人马有着个人的利益诉求。"},sec={{t="大酋长副官的召唤",b="在整个卡利姆多，部落极具影响力的人物——包括暗影猎手沃金、纳兹格勒，以及像贝尔戈洛姆·石槌这样的老练指挥官——始终密切关注着边境沿线的潜在威胁。在贫瘠之地，一位经验丰富的战士雷格萨·死门在西部山口建立了一个防御哨所。部落军官们意识到，区域性的冲突需要久经沙场的战士而非新兵，因此引导那些久经考验的冒险者前往十字路口以西，响应雷格萨的召唤。"},{t="通往凄凉之路",b="雷格萨·死门驻扎在十字路口以西山脊上的防御工事中。从这个有利位置，他监视着蜿蜒通往凄凉之地荒芜之地的西部山路。他的任务直接且坚定：组建一支远征先遣队，能够不畏险阻，在那些好战的半人马部族的暴力扩张威胁到部落领土之前，直接打击科卡尔半人马及其他交战部族的心脏。"}},faq={{q="雷格萨·死门是谁？",a="雷格萨·死门是一位兽人战士，也是驻扎在贫瘠之地的部落指挥官。他的任务是负责边境安全，负责协调侦察行动以及对危险的、尘土飞扬的凄凉之地进行军事打击。",al={"雷格萨是谁","雷格萨·死门背景故事","谁是任务发布者"}},{q="雷格萨·死门在哪里？",a="他位于贫瘠之地，驻扎在十字路口以西山路上的部落防御工事内，俯瞰着西部山口。",al={"雷格萨在哪里","雷格萨位置","寻找雷格萨·死门"}},{q="谁发布了寻找雷格萨的任务？",a="几位著名的部落领袖和军事人物提供此任务，包括暗影猎手沃金、奥格瑞玛的纳兹格勒和贝尔戈洛姆·石槌，以及塔伦米尔的克鲁斯克。",al={"谁开启雷格萨·死门任务","在哪里领取雷格萨任务"}},{q="雷格萨任务的主要目标是什么？",a="雷格萨正在招募有能力的战士翻越山脉进入凄凉之地，并对敌对的半人马部族发动攻势，特别是针对科卡尔半人马。",al={"雷格萨想要什么","雷格萨·死门的目标"}},{q="为什么部落关心凄凉之地？",a="凄凉之地是一片饱受战争蹂躏的荒野，到处都是好战的半人马部族。如果对他们放任不管，他们的劫掠行为可能会蔓延到山隘，波及贫瘠之地和邻近的部落定居点。",al={"为什么要前往凄凉之地","部落对凄凉之地的关注"}},{q="与雷格萨·死门交谈后接下来要做什么？",a="一旦你向雷格萨报到，他会立即向你简要说明西部山脉之外的情况，并指派你完成“凄凉之地的科卡尔”任务，作为你越境后的第一次打击。",al={"雷格萨之后的下一个任务","雷格萨后续任务"}}},fp="17,208,34.239.0,20.300.0,25.135.0,35.141.0,40.173.0,51.127.0,41.146.0,54.157.0"}
P.entries["quest:1362"] = {n="凄凉之地的科卡尔部族",s="此任务连接了部落在贫瘠之地与凄凉之地荒芜广袤地区之间的军事行动。在兽人战士Regthar Deathgate的指挥下，部落勇士们穿越群山向西进发，以支援驻守在幽灵岗哨的侦察兵费古尔·双刃。",h="此任务连接了部落在贫瘠之地与凄凉之地荒芜广袤地区之间的军事行动。在兽人战士Regthar Deathgate的指挥下，部落勇士们穿越群山向西进发，以支援驻守在幽灵岗哨的侦察兵费古尔·双刃。",kw={"半人马","凄凉之地","费古尔·双刃","幽灵岗哨","部落","kolkar","regthar deathgate","贫瘠之地"},ang={["faction:Horde"]="此任务标志着部落的一个重要战略转折，从保护杜隆塔尔和贫瘠之地初建的定居点，转变为向敌对的外部边境地带深处发起主动的军事战役。",["race:Orc"]="在巩固了东卡利姆多的据点后，兽人将未被驯服的半人马氏族视为一种必须压制的长期威胁，以确保部落补给线的安全。",["race:Tauren"]="在与萨尔结盟之前，半人马的侵略曾将游牧的牛头人部族推向灭绝的边缘。对于任何牛头人战士来说，将战火直接带到他们位于凄凉之地的家园，都具有极其深刻的个人意义。"},sec={{t="翻越群山的威胁",b="虽然部落在贫瘠之地与四处掠夺的半人马部族进行周旋，但像Regthar Deathgate这样的指挥官深知，修剪枝叶永远无法从根本上消灭树木。Kolkar氏族的力量源头直接追溯至卡利姆多西海岸那些荒凉的岩壁之上。只要他们祖辈的要塞一日未被征服，无尽的劫掠者浪潮就会穿过山口，涌入部落领地。要消灭Kolkar，必须从源头给予打击。"},{t="幽灵岗哨",b="为了对抗半人马的心脏地带，部落在此处维护着一个名为幽灵岗哨的坚固前哨站。深入凄凉之地，侦察兵费古尔·双刃正在收集关于那些争吵不休的半人马氏族的情报。Regthar派遣在贫瘠之地历练过的老兵西进，将他们的利刃交给费古尔指挥，使部落的立场从被动防御转变为主动破坏的攻势。"}},faq={{q="谁派遣我执行这个任务？",a="Regthar Deathgate，一位驻扎在贫瘠之地十字路口以西地堡中的兽人战士，指引你将战火直接烧到Kolkar的祖居之地。",al={"任务发布者","谁发布任务","regthar"}},{q="幽灵岗哨位于何处？",a="幽灵岗哨是一座孤立的部落营地，隐匿在凄凉之地的崎岖小径旁，位于卡利姆多山脊的西侧。",al={"幽灵岗哨在哪里","费古尔·双刃位置","凄凉之地营地"}},{q="为什么部落要将重心放在凄凉之地？",a="在贫瘠之地进行劫掠的Kolkar出自深扎于凄凉之地的大型半人马部族。Regthar意识到，在Kolkar位于凄凉之地的要塞被摧毁之前，贫瘠之地的防御措施永远无法永久阻止这些入侵。",al={"为什么要前往凄凉之地","为什么要在凄凉之地对抗kolkar","半人马关联"}},{q="谁是费古尔·双刃？",a="费古尔·双刃是驻扎在幽灵岗哨的一名部落侦察兵，其任务是观察凄凉之地内互相交战的半人马氏族，并组织针对他们的战术打击。",al={"费古尔·双刃","谁是费古尔"}},{q="此任务包含战斗吗？",a="不包含。这是一个过渡性的跑腿任务，引导升级中的部落冒险者从贫瘠之地的中等级冲突，进入凄凉之地更高等级的挑战中。",al={"任务中是否包含战斗","战斗任务"}},{q="此任务的目标是哪个半人马氏族？",a="它明确针对Kolkar氏族，这是起源于凄凉之地的主要半人马派系之一，该派系已经大举扩张至贫瘠之地和杜隆塔尔。",al={"哪个半人马","什么氏族","kolkar氏族"}}},fp="22,188,29.380.0,17.271.0,29.152.0,35.116.0,38.184.0,22.136.0,31.104.0,42.115.0"}
P.entries["quest:1365"] = {n="戴兹帕可汗",s="在完成了凄凉之地的科尔卡任务后，费古尔·双刃会派你去对付科尔卡的首领，可汗德兹'赫帕。许多半人马氏族在凄凉之地互相征战，费古尔希望在这些氏族联合起来之前先瓦解科尔卡部族。",h="在完成了凄凉之地的科尔卡任务后，费古尔·双刃会派你去对付科尔卡的首领，可汗德兹'赫帕。许多半人马氏族在凄凉之地互相征战，费古尔希望在这些氏族联合起来之前先瓦解科尔卡部族。",kw={"半人马","凄凉之地","德兹'赫帕","费古尔·双刃","可汗德兹'赫帕","科尔卡","科尔卡村"},sec={{t="分裂的氏族",b="科尔卡只是凄凉之地众多半人马氏族中的一支。许多半人马在干旱的平原上游荡，在彼此的杀戮中死去。费古尔·双刃并不介意这一点，因为半人马既强壮又残暴，联合起来的半人马部族将成为部落的一大劲敌。必须在这种情况发生之前解决他们。"},{t="科尔卡领袖",b="费古尔的第一步行动是通过杀死他们的领袖，可汗德兹'赫帕，来瓦解科尔卡。科尔卡村位于费古尔所处位置的东北方，费古尔要求你带回这位可汗的首级。"}},faq={{q="费古尔·双刃为什么要杀死可汗德兹'赫帕？",a="费古尔担心半人马氏族会联合起来对抗部落。杀死可汗德兹'赫帕是为了先瓦解科尔卡氏族。",al={"为什么杀死德兹赫帕","可汗德兹赫帕的目的","杀死德兹赫帕的原因"}},{q="可汗德兹'赫帕在哪里？",a="在凄凉之地，费古尔·双刃东北方的科尔卡村里。",al={"可汗德兹赫帕的位置","德兹赫帕在哪里","科尔卡村位置"}},{q="费古尔要求带回什么？",a="可汗德兹'赫帕的首级，带回给费古尔·双刃。",al={"可汗德兹赫帕的证明","带给费古尔什么"}},{q="在可汗德兹'赫帕任务之前是什么？",a="凄凉之地的科尔卡。在那之后，费古尔·双刃会派你去对付科尔卡领袖，可汗德兹'赫帕。",al={"之前的任务德兹赫帕","可汗德兹赫帕的前置条件"}}},fp="14,214,13.309.0,17.190.0,49.132.0,32.63.0,35.54.0,33.101.0"}
P.entries["quest:1366"] = {n="悬赏半人马",s="在可汗德兹赫帕倒下后，费古尔·双刃说，现在必须让那些受惊的半人马氏族血流成河。在凄凉之地各地猎杀任何氏族的半人马，并带给费古尔十五只他们的耳朵。",h="在可汗德兹赫帕倒下后，费古尔·双刃说，现在必须让那些受惊的半人马氏族血流成河。在凄凉之地各地猎杀任何氏族的半人马，并带给费古尔十五只他们的耳朵。",kw={"半人马","半人马赏金","半人马的耳朵","凄凉之地","费古尔·双刃","可汗德兹赫帕"},sec={{t="放血时刻",b="费古尔·双刃说，既然半人马氏族已经被吓坏了，现在就是让他们血流成河的时候。无论你何时前往凄凉之地，都要猎杀半人马。费古尔不在乎你猎杀的是哪个氏族，他只在乎你能收集到耳朵，一共十五只。削减他们的数量会动摇他们的意志，并彻底打消他们扩张的念头。"},{t="费古尔的判决",b="当你返回时，费古尔说半人马现在一定已经记住了你的名字，并对你感到敬畏。他们也知道你所效忠的旗帜：部落。"}},faq={{q="是谁下达了针对半人马的赏金令？",a="位于凄凉之地的费古尔·双刃。必须带回十五只半人马的耳朵交给费古尔。",al={"谁发布了半人马赏金","半人马赏金任务发布者"}},{q="需要猎杀哪些半人马氏族？",a="随便哪个氏族。费古尔不在乎你猎杀的是哪个氏族，他只在乎你能收集到耳朵。",al={"我该杀哪些半人马","半人马赏金要杀哪个氏族"}},{q="为什么费古尔想要这么多半人马的耳朵？",a="为了削减半人马的数量。半人马越少，他们的意志就越薄弱，这也能彻底打消他们扩张的念头。",al={"为什么要杀凄凉之地的半人马","半人马赏金的原因"}},{q="在这个赏金任务之前发生了什么？",a="它是紧随“可汗德兹赫帕”任务之后的。费古尔说半人马氏族已经被吓坏了，现在是让他们血流成河的时候了。",al={"半人马赏金前置任务","半人马赏金的上一个任务"}}},fp="14,165,18.314.0,16.151.1,38.83.0,38.81.0,42.111.0,29.108.0"}
P.entries["quest:1367"] = {n="玛格拉姆部族",s="古尔达·蛮鬃提议将半人马氏族彼此间的仇恨转化为对付他们的武器：与其中一个氏族结盟，并通过它了解如何击败所有的半人马。选择站在玛格拉姆氏族这一边意味着要屠杀他们的敌人吉尔吉斯半人马，然后与位于凄凉之地东南部的玛格拉姆村边缘的玛格拉姆发言人瓦鲁格交谈。",h="古尔达·蛮鬃提议将半人马氏族彼此间的仇恨转化为对付他们的武器：与其中一个氏族结盟，并通过它了解如何击败所有的半人马。选择站在玛格拉姆氏族这一边意味着要屠杀他们的敌人吉尔吉斯半人马，然后与位于凄凉之地东南部的玛格拉姆村边缘...",kw={"半人马","凄凉之地","吉尔吉斯","古尔达·蛮鬃","玛格拉姆","玛格拉姆村","瓦鲁格"},sec={{t="仇恨作为武器",b="古尔达·蛮鬃的计划是利用半人马之间彼此的仇恨。选择一个氏族作为盟友，它所传授的知识将展示如何击败每一个氏族。选择玛格拉姆，你就必须铲除他们的死敌吉尔吉斯半人马，这会让你在玛格拉姆中赢得尊重。"},{t="发言人",b="一旦你赢得了足够的尊重，玛格拉姆发言人瓦鲁格就会在凄凉之地东南部的玛格拉姆村外围等你。在此之前，他无话可说。玛格拉姆人不会对弱者多费口舌，只会杀了他们，所以他会把你打发走，去对抗许多吉尔吉斯半人马以证明你的实力。"},{t="瓦鲁格的审判",b="瓦鲁格告诉你，吉尔吉斯人听到你的名字就会哭泣，他们害怕你，并且像憎恨玛格拉姆人一样憎恨你。他承认，或许你和玛格拉姆人一样强大。他会拭目以待。"}},faq={{q="是谁提议与玛格拉姆结盟的？",a="古尔达·蛮鬃，她想通过与一个氏族结盟并学习如何击败所有氏族的方法，来让半人马氏族间的仇恨反过来对付他们自己。",al={"谁提供玛格拉姆结盟任务","玛格拉姆任务给予者","古尔达·蛮鬃任务"}},{q="如何赢得玛格拉姆的尊重？",a="通过屠杀他们的敌人：吉尔吉斯半人马。",al={"如何获得玛格拉姆的友善度","玛格拉姆声望","使玛格拉姆达到友善"}},{q="瓦鲁格在哪里？",a="在凄凉之地东南部的玛格拉姆村外围。他是玛格拉姆的发言人。",al={"瓦鲁格在哪里","寻找瓦鲁格","瓦鲁格位置"}},{q="为什么瓦鲁格起初拒绝交谈？",a="他说玛格拉姆人不与弱者交谈，只会杀了他们。首先，通过屠杀许多吉尔吉斯半人马来证明你的力量。",al={"为什么瓦鲁格不说话","瓦鲁格生气","瓦鲁格对话"}}},fp="15,310,18.256.0,13.301.0,16.176.1,41.142.0,42.34.0,15.86.0,40.110.0"}
P.entries["quest:1368"] = {n="吉尔吉斯部族",s="古尔达·蛮鬃提议利用半人马氏族之间的仇恨来对付他们：与一个氏族结盟，并从中学会如何击败所有的半人马。站在吉尔吉斯这边意味着要消灭他们最大的敌人——玛格拉姆，然后前往位于凄凉之地西南部的吉尔吉斯村边缘，去见吉尔吉斯的萨满：智者乌泰克。",h="古尔达·蛮鬃提议利用半人马氏族之间的仇恨来对付他们：与一个氏族结盟，并从中学会如何击败所有的半人马。站在吉尔吉斯这边意味着要消灭他们最大的敌人——玛格拉姆，然后前往位于凄凉之地西南部的吉尔吉斯村边缘，去见吉尔吉斯的萨满：...",kw={"半人马","凄凉之地","吉尔吉斯","吉尔吉斯村","古尔达·蛮鬃","玛格拉姆","智者乌泰克"},sec={{t="以仇恨为武器",b="古尔达·蛮鬃的计划是利用半人马之间的仇恨。选择一个氏族作为盟友，并从中学到击败其他所有氏族的方法。选择吉尔吉斯人，你就要杀死吉尔吉斯人最痛恨的玛格拉姆人，从而赢得他们的尊重。"},{t="萨满",b="一旦你赢得了他们的尊重，就可以在凄凉之地西南部的吉尔吉斯村郊外见到吉尔吉斯的萨满智者乌泰克。在此之前，他们不欢迎你：乌泰克说你踏上了吉尔吉斯的土地，必须通过杀死玛格拉姆半人马来证明友谊。等到玛格拉姆人的血浸透了大地再回来吧。"},{t="乌泰克的话",b="乌泰克说大地诉说着你杀死了多少玛格拉姆人，这是好事。作为吉尔吉斯的朋友，乌泰克还有更多工作交给你。"}},faq={{q="是谁提议与吉尔吉斯结盟的？",a="古尔达·蛮鬃，他想通过与一个半人马氏族结盟，并从中学习如何击败所有半人马的方法，来利用各氏族之间的仇恨。",al={"谁给予吉尔吉斯结盟任务","吉尔吉斯结盟任务发布者"}},{q="如何赢得吉尔吉斯人的好感？",a="通过杀死吉尔吉斯人最痛恨的玛格拉姆人。",al={"如何与吉尔吉斯建立友好关系","吉尔吉斯声望"}},{q="你应该在吉尔吉斯人中找谁谈话？",a="智者乌泰克，一位吉尔吉斯萨满，位于凄凉之地西南部的吉尔吉斯村郊外。",al={"乌泰克在哪里","智者乌泰克位置"}},{q="乌泰克在欢迎你之前需要什么？",a="乌泰克说在你通过杀死玛格拉姆半人马证明友谊之前，你在吉尔吉斯的土地上是不受欢迎的。",al={"为什么乌泰克拒绝我","吉尔吉斯村敌对"}}},fp="15,321,18.248.0,10.326.0,12.141.1,41.142.0,40.49.0,37.90.0,45.100.0"}
P.entries["quest:1369"] = {n="破碎之泪",s="瓦鲁格说，吉尔吉斯人愚蠢地相信半人马之母瑟莱德丝会保护他们。他让你潜入他们村庄的洞穴，摧毁他们积攒在那里的水晶——即瑟莱德丝之泪——并带给他三块破碎的碎片。",h="瓦鲁格说，吉尔吉斯人愚蠢地相信半人马之母瑟莱德丝会保护他们。他让你潜入他们村庄的洞穴，摧毁他们积攒在那里的水晶——即瑟莱德丝之泪——并带给他三块破碎的碎片。",kw={"破碎的泪水晶","半人马","凄凉之地","吉尔吉斯","玛格拉姆","瑟莱德丝","瓦鲁格"},sec={{t="洞穴中的水晶",b="瓦鲁格鄙视吉尔吉斯人，认为他们不该相信半人马之母瑟莱德丝的庇护。在他看来，没有人会保护半人马，而玛格拉姆部族既然是最强大的，就不需要任何保护。他让你前往吉尔吉斯村的洞穴，那里藏有一堆被称为“瑟莱德丝之泪”的水晶。打碎它们并带给瓦鲁格三块碎片。只有当你不是玛格拉姆部族的敌人时，他才会把这件事交给你。"},{t="瓦鲁格的夸耀",b="瓦鲁格很高兴：随着泪水晶被毁，吉尔吉斯人会明白瑟莱德丝根本无法保护他们，当玛格拉姆人碾碎他们时，瑟莱德丝也不会掉下一滴眼泪。他宣称玛格拉姆部族终将统治一切，并夸奖你站在强者一边是明智之举。"}},faq={{q="谁是瓦鲁格？",a="凄凉之地玛格拉姆村的一名玛格拉姆半人马。他要求你摧毁吉尔吉斯洞穴中的瑟莱德丝之泪。",al={"瓦鲁格","谁发布破碎的泪水晶任务","破碎的泪水晶任务发布者"}},{q="瑟莱德丝之泪是什么？",a="吉尔吉斯人在他们村庄的洞穴里积攒的水晶。",al={"瑟莱德丝之泪","破碎的泪水晶背景","吉尔吉斯水晶"}},{q="为什么瓦鲁格要摧毁这些泪水晶？",a="吉尔吉斯人认为半人马之母瑟莱德丝会保护他们。瓦鲁格认为他们很愚蠢，声称玛格拉姆人不需要庇护，并想让吉尔吉斯人认清事实。",al={"为什么要摧毁泪水晶","玛格拉姆部族动机","为什么要打碎水晶"}},{q="水晶在哪里可以找到？",a="在吉尔吉斯村的洞穴里。瓦鲁格想要三块破碎的碎片。",al={"哪里有破碎的泪水晶","吉尔吉斯洞穴位置","泪水晶在哪里"}}},fp="12,237,20.411.0,13.235.1,13.113.0,32.53.0,40.168.0,29.87.0"}
P.entries["quest:1370"] = {n="偷取物资",s="智者乌泰克说肉食给予了吉尔吉斯人力量，而玛格拉姆人储存了多余的食物，好让他们在狩猎间隙也能维持战斗。你被派往东部的玛格拉姆村进行袭击，并带回六袋风干肉。",h="智者乌泰克说肉食给予了吉尔吉斯人力量，而玛格拉姆人储存了多余的食物，好让他们在狩猎间隙也能维持战斗。你被派往东部的玛格拉姆村进行袭击，并带回六袋风干肉。",kw={"半人马","凄凉之地","吉尔吉斯","玛格拉姆","肉","补给品","乌泰克"},sec={{t="肉食与力量",b="在战争间隙，吉尔吉斯人会进行狩猎，因为肉食意味着力量，而饱腹之人比饥饿之人更能战斗。智者乌泰克说，玛格拉姆人储存了备用粮，以维持他们在两次狩猎之间的消耗。去袭击东部的村庄，夺走这些物资，他们的力量就会枯竭。你需要收集六袋粗糙的风干肉，并将其带给吉尔吉斯村的乌泰克。"}},faq={{q="是谁派你去夺取这些补给品的？",a="凄凉之地的吉尔吉斯人的智者乌泰克。",al={"任务发布者","谁发布了窃取补给任务","智者乌泰克"}},{q="乌泰克为什么要夺取玛格拉姆人的肉食？",a="对吉尔吉斯人来说，肉食就是力量。玛格拉姆人留有储备，好在狩猎间隙也能继续战斗，乌泰克认为夺走这些食物能削弱他们。",al={"为什么要偷肉","玛格拉姆食物","抢夺肉食的原因"}},{q="玛格拉姆人的补给品存放在哪里？",a="在东部的玛格拉姆村里。",al={"玛格拉姆村在哪里","补给品在哪里","玛格拉姆位置"}},{q="乌泰克想要多少肉？",a="六袋粗糙的风干肉，由智者乌泰克在吉尔吉斯村收集。",al={"需要多少肉","我需要带什么给乌泰克"}}},fp="17,226,17.353.0,37.42.0,42.140.0,35.35.0,30.84.0"}
P.entries["quest:1371"] = {n="瓦鲁格的玩具",s="身处玛格拉姆村的瓦鲁格记得，曾经有一个侏儒带着一车奇怪的东西来到过凄凉之地。他当时留下了那个车上的一具木制人类，直到被他弄坏为止，现在他想要一个新的：高级假人。",h="身处玛格拉姆村的瓦鲁格记得，曾经有一个侏儒带着一车奇怪的东西来到过凄凉之地。他当时留下了那个车上的一具木制人类，直到被他弄坏为止，现在他想要一个新的：高级假人。",kw={"半人马","凄凉之地","侏儒","玛格拉姆","假人","瓦鲁格"},sec={{t="侏儒的货车",b="很久以前，一个小侏儒带着马和货车来到过凄凉之地。车上装着一些奇奇怪怪的东西：有些会燃烧出不同的颜色，有些明明没有生命却会动。瓦鲁格杀死了那个侏儒，但在此之前，侏儒让他笑过。瓦鲁格留下了货车里他最喜欢的一件东西——一个木制的人类玩偶，它曾向他挥手，直到他用力打它并弄坏了它。现在他想要一个新的，一个高级假人，并希望非玛格拉姆之敌的人能给他带来。"}},faq={{q="瓦鲁格是谁？",a="瓦鲁格是一名玛格拉姆半人马，位于玛格拉姆村。他要求与他打交道的人必须保持与玛格拉姆氏族的良好关系。",al={"瓦鲁格","谁发布了给瓦鲁格的装置"}},{q="瓦鲁格想要什么？",a="一个高级假人，用来替换他弄坏的那个来自侏儒货车的木制人类玩偶。",al={"瓦鲁格需要什么物品","瓦鲁格的装置物品"}},{q="为什么瓦鲁格想要一个假人？",a="很久以前，他杀了一个带着一车奇怪、有趣东西来到凄凉之地的侏儒。那个侏儒让他笑过，瓦鲁格最喜欢的东西是一个木制的人类玩偶，它曾向他挥手，直到他用力打它并弄坏了它。他想要一个新的。",al={"为什么瓦鲁格想要假人","瓦鲁格要假人的原因"}},{q="在玛格拉姆的故事线中，这一步之前是什么？",a="它紧随“破碎的泪水”之后，那是你与玛格拉姆氏族交往的早期任务。",al={"给瓦鲁格的装置任务线","给瓦鲁格的装置前置任务"}}},fp="15,215,16.457.0,13.121.0,21.90.0,35.231.0,43.66.0"}
P.entries["quest:1373"] = {n="盎格库尔",s="吉尔吉斯氏族的智者乌泰克说你还有更多需要证明的地方，目前吉尔吉斯氏族将会在没有你帮助的情况下对抗玛格拉姆氏族。大地向智者乌泰克低语了德莱尼水晶的事，你被派往遥远的悲伤沼泽去寻找迷失者翁格库手中掌握的一块碎片。",h="吉尔吉斯氏族的智者乌泰克说你还有更多需要证明的地方，目前吉尔吉斯氏族将会在没有你帮助的情况下对抗玛格拉姆氏族。大地向智者乌泰克低语了德莱尼水晶的事，你被派往遥远的悲伤沼泽去寻找迷失者翁格库手中掌握的一块碎片。",kw={"凄凉之地","德莱尼水晶","吉尔吉斯","迷失者","玛格拉姆","翁格库","悲伤沼泽","智者乌泰克"},sec={{t="远方的水晶",b="在窃取补给任务之后，智者乌泰克告诉你，你的下一个任务在很远的地方。那些倾听大地的人会听到许多秘密，乌泰克听到的秘密之一就是关于一种叫做德莱尼水晶的红色晶体，它刚刚来到这片土地，是从一个有着浮空山脉和恶魔统治的地方带来的。乌泰克说，它的一块碎片会让魔法变得强大。迷失者翁格库在东部王国的悲伤沼泽中持有这种碎片。当你回来时，乌泰克会寻找证据来证明吉尔吉斯氏族仍然可以称你为朋友。"}},faq={{q="智者乌泰克是谁？",a="位于凄凉之地吉尔吉斯村的一位吉尔吉斯半人马，他说大地会向那些倾听它的人低语秘密。",al={"乌泰克","吉尔吉斯长老","半人马任务发放者"}},{q="什么是德莱尼水晶？",a="一块红色水晶，尤塞克称它是新近来到我们世界的。尤塞克说，它来自一片飞翔山脉遍布、由恶魔统治的土地。",al={"德莱尼水晶碎片","红色水晶","什么是德莱尼水晶"}},{q="翁格库是谁？",a="一位迷失者，在东部王国的悲伤沼泽中部持有一块德莱尼水晶碎片。",al={"翁格库在哪里","翁格库位置","寻找翁格库"}},{q="为什么乌泰克想要德莱尼水晶碎片？",a="乌泰克说一块碎片会让魔法变得强大。",al={"为什么要获取德莱尼水晶","乌泰克魔法"}},{q="在此之前发生了什么？",a="之前乌泰克交给你的任务：窃取补给。",al={"前置任务","前置条件"}}},fp="6,274,23.525.0,22.107.0,20.119.0,14.101.0,40.46.0,22.48.0"}
P.entries["quest:1374"] = {n="杰恩可汗",s="继昂格库之后，智者乌泰克告诉你大地在低语，玛格拉姆半人马正在变得虚弱，是时候除掉他们的可汗了。乌泰克希望你将汗·杰恩的头颅带到吉尔吉斯村。",h="继昂格库之后，智者乌泰克告诉你大地在低语，玛格拉姆半人马正在变得虚弱，是时候除掉他们的可汗了。乌泰克希望你将汗·杰恩的头颅带到吉尔吉斯村。",kw={"半人马","凄凉之地","吉尔吉斯","吉尔吉斯村","杰恩的头颅","汗·杰恩","玛格拉姆","智者乌泰克"},sec={{t="玛格拉姆可汗",b="位于吉尔吉斯村的智者乌泰克说大地对他倾诉，预示着玛格拉姆正日渐虚弱。乌泰克指名要你除掉他们的可汗——杰恩，并带回玛格拉姆可汗的头颅。乌泰克希望你回来时仍是吉尔吉斯的朋友。"}},faq={{q="汗·杰恩是谁？",a="玛格拉姆半人马的可汗。",al={"汗·杰恩","杰恩是谁","玛格拉姆领袖"}},{q="为什么智者乌泰克要置汗·杰恩于死地？",a="乌泰克说大地告诉他玛格拉姆人正在变弱，所以现在是除掉他们可汗的时机。",al={"为什么要杀杰恩","乌泰克的动机","为什么要杀玛格拉姆可汗"}},{q="这之前发生了什么？",a="这发生在昂格库任务之后。",al={"汗·杰恩任务的前置","任务链顺序","前置任务"}},{q="智者乌泰克在哪里？",a="在凄凉之地的吉尔吉斯村。",al={"乌泰克位置","乌泰克在哪"}}},fp="9,194,15.282.0,17.31.0,44.91.0,22.22.0,24.30.0"}
P.entries["quest:1375"] = {n="沙卡可汗",s="在完成“给瓦鲁格的小玩意”任务后，玛格拉姆半人马瓦鲁格对你的帮助感到很满意。现在他想要吉尔吉斯半人马的可汗沙卡的首级。他打算盯着这颗头颅，嘲笑他的敌人。",h="在完成“给瓦鲁格的小玩意”任务后，玛格拉姆半人马瓦鲁格对你的帮助感到很满意。现在他想要吉尔吉斯半人马的可汗沙卡的首级。他打算盯着这颗头颅，嘲笑他的敌人。",kw={"半人马","凄凉之地","吉尔吉斯","可汗沙卡的首级","可汗沙卡","玛格拉姆","瓦鲁格"},sec={{t="竞争对手的可汗",b="在玛格拉姆村，瓦鲁格告诉你你已经帮助了玛格拉姆部族，他很欣赏你。现在他要你去杀死吉尔吉斯半人马的可汗沙卡，并把他的头颅带回来。他说他想盯着那颗头颅嘲笑他。他希望你继续和玛格拉姆部族保持良好的关系。"}},faq={{q="可汗沙卡是谁？",a="凄凉之地吉尔吉斯半人马氏族的可汗，玛格拉姆的瓦鲁格想要他的首级。",al={"可汗沙卡背景故事","沙卡是谁","半人马沙卡"}},{q="为什么瓦鲁格想要可汗沙卡死？",a="他想要沙卡的首级，这样他就可以盯着它嘲笑他。",al={"为什么要杀沙卡","瓦鲁格与沙卡的恩怨"}},{q="瓦鲁格在哪里？",a="在凄凉之地的玛格拉姆村。",al={"可汗沙卡位置","瓦鲁格在哪里"}},{q="是什么导致了这一切？",a="在完成“给瓦鲁格的小玩意”后，瓦鲁格表示因为你帮助了玛格拉姆部族，所以他很欣赏你。",al={"可汗沙卡前置条件","沙卡的前置任务"}}},fp="10,172,12.273.0,18.86.0,36.61.0,15.30.0,20.76.0"}
P.entries["quest:138"] = {n="杉德尔船长的宝藏",s="这个任务是谜一般的海盗桑德斯船长在西部荒野各处设计的寻宝游戏的第二环。寻宝者需要根据从废弃的海边储物箱中找到的指示，离开海岸向东行进，在一处废墟石墙旁的老旧木桶里寻找下一条线索。",h="这个任务是谜一般的海盗桑德斯船长在西部荒野各处设计的寻宝游戏的第二环。寻宝者需要根据从废弃的海边储物箱中找到的指示，离开海岸向东行进，在一处废墟石墙旁的老旧木桶里寻找下一条线索。",kw={"破损的木桶","桑德斯船长","烟囱","海盗","桑德斯的宝藏","寻宝游戏","西部荒野"},ang={["class:Rogue"]="对于那些偏爱潜行、狡诈和快速获利的人来说，破解海盗密码和在废弃的废墟中穿行以寻找被遗忘的战利品是第二天性。",["faction:Alliance"]="虽然西部荒野的当地民兵正在与有组织的法外之徒作斗争，但追寻桑德斯的踪迹提供了一种罕见的消遣，穿越了无法无天的海岸线和无人照料的内陆道路。"},sec={{t="内陆谜题之路",b="桑德斯船长并没有将他的战利品埋在沙滩上某个标有十字记号的地方，而是将谜题散布在整个乡村。那些成功破解他在岸边留下的第一道密码的人，会被告知离开汹涌的潮水，攀登内陆的岩石峭壁，沿着一条稳步向上的路线前往西部荒野的主要道路。"},{t="路边的废墟",b="这条线索指引寻宝者直接前往路边废墟中矗立的一个旧烟囱，在那里，一个废弃的风化木桶隐藏着下一条信息。这位海盗显然非常了解西部荒野的地标，利用废弃农庄的残垣断壁来作为他精心设计的寻宝游戏的里程碑。"}},faq={{q="桑德斯船长是谁？",a="桑德斯船长是一位在西部荒野海岸沿线活动的海盗船长。他并没有把战利品藏在一个普通的储藏处，而是将一连串的线索和谜题散布在这一地区，以挑战任何渴望获得他隐藏财富的人。",al={"桑德斯船长背景故事","谁是桑德斯","海盗桑德斯"}},{q="这条线索指引你去哪里？",a="线索指引寻宝者从西海沿峭壁向正东方向前进，直到到达大路。在那里，在一处古老的废墟石烟囱旁边，放着一个破损的木桶，里面藏着谜题的下一部分。",al={"我该去哪里","线索位置","烟囱位置"}},{q="桑德斯为什么要分段隐藏他的宝藏？",a="海盗通常会隐藏他们不义之财，以防被竞争对手和当局夺走。桑德斯采取了额外的预防措施，将他的指示分成多步骤的谜题，确保只有执着且足智多谋的人才能顺着踪迹找到最终的宝藏。",al={"为什么设置线索","为什么要进行寻宝游戏"}},{q="这个寻宝游戏危险吗？",a="虽然线索本身只是羊皮纸和旧容器，但在西部荒野穿行会让寻宝者遇到游荡的野兽、潜行的豺狼人，以及控制着周边田野和废弃农庄的敌对迪菲亚潜行者。",al={"安全吗","西部荒野的危险"}},{q="木桶藏在什么样的废墟旁边？",a="木桶坐落在路边一栋废弃建筑摇摇欲坠的石烟囱旁边，这是西部荒野中在近年来动荡局势下被废弃或拆毁的众多农庄之一。",al={"烟囱废墟","哪座建筑"}},{q="这个任务会揭示宝藏本身吗？",a="不会。这一步只会提供另一条线索。桑德斯设计的寻宝游戏会指引寻宝者在发现真正的奖品之前，先通过该地区的几个阶段。",al={"这是最后一个宝箱吗","我现在能拿到战利品吗"}}},fp="32,170,25.157.0,20.170.0,24.159.0,30.174.0,44.197.0,41.227.0,45.174.0,43.123.0"}
P.entries["quest:1380"] = {n="赫鲁萨可汗",s="智者乌泰克回想起你曾如何帮助吉尔吉斯半人马对抗玛格拉姆，现在他请求你击杀玛洛迪部族的首领可汗赫拉萨，以此来打击玛洛迪。赫拉萨持有一块钥匙碎片，乌泰克要你把它带回来。",h="智者乌泰克回想起你曾如何帮助吉尔吉斯半人马对抗玛格拉姆，现在他请求你击杀玛洛迪部族的首领可汗赫拉萨，以此来打击玛洛迪。赫拉萨持有一块钥匙碎片，乌泰克要你把它带回来。",kw={"半人马","凄凉之地","吉尔吉斯村","可汗赫拉萨","玛洛迪","玛洛迪战号","智者乌泰克","长矛谷"},sec={{t="挑战玛洛迪",b="智者乌泰克说，吉尔吉斯现在需要帮助来对抗玛洛迪。玛洛迪战号矗立在长矛谷的一处高地上，吹响它就能引出可汗赫拉萨。然而没有战号吹嘴的话，战号就毫无用处，这种吹嘴非常稀有，只有受信任的玛洛迪半人马才会携带。当战号吹响时，更多的半人马会赶来，而赫拉萨会最后出现。"},{t="钥匙碎片",b="可汗赫拉萨持有一块钥匙碎片，乌泰克要你把它带回吉尔吉斯村。"},{t="当你归来时",b="当你归来时，乌泰克欢呼雀跃，庆祝赫拉萨已死，玛洛迪末日将至。他发誓说，当吉尔吉斯统治这片土地时，他们会永远铭记你，大地的灵魂也会永远传唱你的名字。"}},faq={{q="是谁派你去对抗可汗赫拉萨的？",a="凄凉之地的吉尔吉斯村的智者乌泰克，他会向那些曾经帮助过吉尔吉斯的人提出请求。",al={"谁给予可汗赫拉萨任务","可汗赫拉萨任务发布者","如何获得可汗赫拉萨任务"}},{q="如何引出可汗赫拉萨进行战斗？",a="乌泰克指引你去长矛谷的玛洛迪战号那里，你需要吹响它。半人马会回应号角，赫拉萨随后就会出现。",al={"可汗赫拉萨位置","可汗赫拉萨在哪里","寻找可汗赫拉萨"}},{q="如何吹响玛洛迪战号？",a="没有战号吹嘴，战号就毫无用处，而只有受信任的玛洛迪半人马才可能携带这种稀有物品。",al={"战号吹嘴","如何使用玛洛迪战号","吹响玛洛迪战号"}},{q="在此之前发生了什么？",a="这是可汗杰恩任务的后续。乌泰克提醒你，你曾帮助过吉尔吉斯对抗玛格拉姆。",al={"可汗赫拉萨前置条件","可汗赫拉萨之前的任务","可汗赫拉萨任务链"}},{q="可汗赫拉萨持有什么？",a="可汗赫拉萨持有一块钥匙碎片，乌泰克让你把它带到吉尔吉斯村给他。",al={"可汗赫拉萨任务物品","玛洛迪钥匙碎片","赫拉萨掉落什么"}}},fp="11,223,25.369.0,16.81.0,14.204.1,35.91.0,40.131.0,39.105.0,23.86.0,27.91.0"}
P.entries["quest:1381"] = {n="赫鲁萨可汗",s="瓦鲁格宣布了Gelkis Khan的死讯，并称玛洛迪人就是下一个目标。瓦鲁格派你去对付他们的可汗，Hratha，并想要Hratha携带的那块钥匙碎片。",h="瓦鲁格宣布了Gelkis Khan的死讯，并称玛洛迪人就是下一个目标。瓦鲁格派你去对付他们的可汗，Hratha，并想要Hratha携带的那块钥匙碎片。",kw={"凄凉之地","钥匙碎片","可汗hratha","玛格拉姆","玛洛迪","长矛谷","战争号角","瓦鲁格"},sec={{t="悬崖上的号角",b="瓦鲁格想要玛洛迪可汗，Hratha，的命。长矛谷的一处悬崖上有一支号角可以把他召唤出来，但没有号嘴就吹不响，而号嘴可以通过击杀玛洛迪半人马获得。吹响号角后，玛洛迪半人马会聚集在塔楼处，最终Hratha便会现身。"},{t="钥匙碎片",b="Hratha持有一部分钥匙，瓦鲁格想要你把它带到玛格拉姆村交给它。瓦鲁格希望你证明自己是玛格拉姆部族的盟友。"},{t="半人马的主人",b="Hratha死后，瓦鲁格宣称玛格拉姆部族是半人马中最强大的，注定要粉碎他们的对手并统治凄凉之地。瓦鲁格说，当其他部族被践踏时，你会因为你的贡献而被铭记并幸免于难。"}},faq={{q="是谁派你去打败可汗Hratha？",a="在Gelkis Khan死后，位于凄凉之地玛格拉姆村的瓦鲁格。",al={"谁给予可汗hratha任务","可汗hratha任务发布者"}},{q="如何才能找到可汗Hratha？",a="瓦鲁格说，面对Hratha的方法是吹响长矛谷悬崖上的号角。这需要一个号嘴，可以通过击杀玛洛迪半人马获得，然后半人马会聚集在塔楼，之后Hratha就会出现。",al={"如何召唤hratha","寻找可汗hratha","吹响长矛谷的号角"}},{q="可汗Hratha会在哪里出现？",a="一旦号角被吹响，且聚集在长矛谷塔楼处的玛洛迪半人马被消灭，Hratha就会现身。",al={"可汗hratha位置","hratha在哪里"}},{q="可汗Hratha持有的是什么？",a="Hratha持有一块钥匙碎片，瓦鲁格要求你把那块碎片带给它。",al={"hratha掉落什么","玛洛迪钥匙碎片"}}},fp="11,169,19.295.0,16.141.0,22.197.1,36.68.0,29.215.0,30.137.0,27.76.0"}
P.entries["quest:1382"] = {n="奇怪的联盟",s="本迪加斯上尉认为，凄凉之地的半人马部族之间互相征战是一件幸事，因为如果它们联合起来，将无人能挡。吉尔吉斯部族正与玛格拉姆部族陷入残酷的战争，因此本迪加斯派遣你去寻找位于凄凉之地西南部的智者乌泰克，以寻求结盟。",h="本迪加斯上尉认为，凄凉之地的半人马部族之间互相征战是一件幸事，因为如果它们联合起来，将无人能挡。吉尔吉斯部族正与玛格拉姆部族陷入残酷的战争，因此本迪加斯派遣你去寻找位于凄凉之地西南部的智者乌泰克，以寻求结盟。",kw={"半人马","凄凉之地","吉尔吉斯","玛格拉姆","本迪加斯","奇怪的联盟","乌泰克"},sec={{t="分裂的部族",b="本迪加斯上尉认为半人马部族之间的战争是件好事，因为如果它们联合起来，将无人能挡。本迪加斯想要利用这一优势。吉尔吉斯部族和玛格拉姆部族正陷入残酷的战争，因此打击玛格拉姆部族或许能赢得吉尔吉斯部族的青睐。"},{t="寻找乌泰克",b="智者乌泰克位于吉尔吉斯营地的入口处，即凄凉之地的西南部。通过她，或许能达成某种盟约。起初她会拒绝你，让你离开，并要求你在杀掉足够多的玛格拉姆部族成员后再回来。"},{t="乌泰克的回答",b="当你杀掉足够多的玛格拉姆部族成员后，乌泰克会告诉你，吉尔吉斯部族的人现在已经在谈论你的名字了，她也表示认可。她愿意和你谈谈你能为该部族提供什么，以及它们能为你提供什么。"}},faq={{q="是谁派你去联系吉尔吉斯部族的？",a="本迪加斯上尉，他希望能够与吉尔吉斯部族达成结盟。",al={"谁发布奇怪的联盟任务","奇怪的联盟任务发布者","谁开启奇怪的联盟任务"}},{q="智者乌泰克在哪里？",a="位于吉尔吉斯营地的入口处，即凄凉之地的西南部。",al={"乌泰克位置","寻找智者乌泰克","乌泰克在哪里"}},{q="为什么智者乌泰克不直接与新人交谈？",a="她让你离开，并要求你在杀掉足够多的玛格拉姆部族成员后再回来。",al={"为什么乌泰克不友好","乌泰克不理人","如何与乌泰克对话"}},{q="联盟为什么要与吉尔吉斯部族结盟？",a="本迪加斯上尉认为，如果半人马部族联合起来将无人能挡，因此它们之间的争斗是一件幸事。吉尔吉斯部族正与玛格拉姆部族交战，因此攻击玛格拉姆部族或许能赢得吉尔吉斯部族的友谊。",al={"为什么要与吉尔吉斯结盟","联盟半人马结盟原因","为什么选择吉尔吉斯部族"}}},fp="16,272,13.266.0,13.223.0,14.185.1,36.76.0,32.59.0,57.63.0,50.210.0"}
P.entries["quest:1384"] = {n="突袭科卡尔",s="在“奇怪的联盟”任务之后，智者乌泰克派你去对付东北方的库卡隆半人马。击败他们，拿走他们的护身符，并将十个护身符带回给乌泰克。",h="在“奇怪的联盟”任务之后，智者乌泰克派你去对付东北方的库卡隆半人马。击败他们，拿走他们的护身符，并将十个护身符带回给乌泰克。",kw={"半人马","粗糙的护身符","凄凉之地","吉尔吉斯","库卡隆","乌泰克"},sec={{t="对库卡隆魔法的蔑视",b="乌泰克嘲笑库卡隆半人马认为自己的魔法很强大；在乌泰克看来，他们对魔法一窍不通。你需要向东北方进发，消灭库卡隆人，并夺取他们的护身符。乌泰克想要十个粗糙的护身符丢进火里，看着它们燃烧并以此取乐。"},{t="乌泰克的判决",b="乌泰克称赞这一行为对吉尔吉斯部族来说是件好事。乌泰克说，库卡隆人虚弱且注定灭亡，他们的魔法救不了他们。见过你的手段后，他们会更加恐惧，而恐惧只会让他们变得更虚弱。在吉尔吉斯领地，弱者很快就会死去。"}},faq={{q="智者乌泰克是谁？",a="智者乌泰克在凄凉之地的吉尔吉斯村等待着。乌泰克想要库卡隆人的护身符。",al={"突袭库卡隆的发起者","乌泰克","智者乌泰克背景故事"}},{q="库卡隆人在哪里？",a="根据乌泰克所说，在东北方。",al={"哪里可以找到库卡隆","凄凉之地库卡隆位置"}},{q="什么是粗糙的护身符？",a="从库卡隆人身上获得的护身符。乌泰克想要十个来丢进火里，并以此取乐。",al={"粗糙的护身符","库卡隆护身符"}},{q="这如何融入吉尔吉斯任务线？",a="它是“奇怪的联盟”的后续任务。",al={"吉尔吉斯任务线","突袭库卡隆的前置任务"}}},fp="18,169,25.252.0,15.253.1,22.84.0,29.37.0,26.85.0,40.28.0"}
P.entries["quest:1385"] = {n="野蛮外交",s="本迪加斯上尉认为，无论哪个半人马氏族在凄凉之地的战争中获胜，都会向外扩张并威胁到联盟的据点。为了了解如何击败他们，本迪加斯希望与其中一个氏族结盟：对抗吉尔吉斯，赢得玛格拉姆的青睐，并与瓦鲁格交谈。",h="本迪加斯上尉认为，无论哪个半人马氏族在凄凉之地的战争中获胜，都会向外扩张并威胁到联盟的据点。为了了解如何击败他们，本迪加斯希望与其中一个氏族结盟：对抗吉尔吉斯，赢得玛格拉姆的青睐，并与瓦鲁格交谈。",kw={"残酷的政治","半人马","凄凉之地","吉尔吉斯","玛格拉姆","本迪加斯","瓦鲁格"},sec={{t="战火之地",b="凄凉之地战火纷飞，半人马各氏族之间互相攻伐。联盟认为，胜利者将会向外扩张并威胁到其据点。这是绝对不允许的。本迪加斯上尉认为，为了了解如何击败半人马，联盟需要让其中一个氏族成为盟友。"},{t="玛格拉姆氏族",b="玛格拉姆氏族正在与吉尔吉斯交战，因此打击吉尔吉斯也许能促使玛格拉姆考虑结盟。赢取他们的好感，然后前往位于凄凉之地东南部的玛格拉姆村寻找瓦鲁格。瓦鲁格警告说，想要成为玛格拉姆的朋友，你必须杀掉吉尔吉斯人。"}},faq={{q="为什么联盟想要与半人马氏族结盟？",a="本迪加斯上尉认为，半人马战争的胜利者将会向外扩张并威胁到联盟的据点。为了了解如何击败他们，联盟需要让其中一个氏族成为盟友。",al={"为什么要与玛格拉姆结盟","本迪加斯的计划","半人马结盟原因"}},{q="如何赢得玛格拉姆的青睐？",a="玛格拉姆氏族正在与吉尔吉斯交战，对抗吉尔吉斯也许能促使他们考虑结盟。瓦鲁格说，想要成为玛格拉姆的朋友，你必须杀掉吉尔吉斯人。",al={"如何获得玛格拉姆声望","玛格拉姆友善","击杀吉尔吉斯"}},{q="瓦鲁格在哪里？",a="位于凄凉之地东南部的玛格拉姆村。",al={"瓦鲁格位置","瓦鲁格在哪里","玛格拉姆联系人"}}},fp="15,260,13.260.0,10.247.0,59.183.0,40.166.0,15.47.0"}
P.entries["quest:1386"] = {n="突袭科卡尔部族",s="在“残酷的政治”之后，玛格拉姆村的瓦鲁格想要证明你有能力像玛格拉姆人一样杀戮考尔克。前往北方，杀掉考尔克半人马、斥候和殴打者。",h="在“残酷的政治”之后，玛格拉姆村的瓦鲁格想要证明你有能力像玛格拉姆人一样杀戮考尔克。前往北方，杀掉考尔克半人马、斥候和殴打者。",kw={"残酷的政治","半人马","凄凉之地","考尔克","玛格拉姆","玛格拉姆村","瓦鲁格"},sec={{t="我们欢笑，我们杀戮",b="瓦鲁格嘲笑着说，考尔克人自以为强大，而玛格拉姆人在杀戮他们时会放声大笑。瓦鲁格希望你证明自己能像玛格拉姆人一样杀戮考尔克人，所以你要向北进发：杀死十二个考尔克半人马，十二个斥候和六个殴打者。"},{t="瓦鲁格的认可",b="当你回来时，瓦鲁格说考尔克人现在已经怕你了。瓦鲁格希望你在杀戮他们时也能欢笑，因为在杀戮时大笑能让敌人看到他们自己的软弱。"}},faq={{q="是谁派你去攻击考尔克人的？",a="凄凉之地玛格拉姆村的玛格拉姆人瓦鲁格。",al={"谁给予“攻击考尔克”任务","“攻击考尔克”任务发布者","在哪里获取“攻击考尔克”"}},{q="这一步之前发生了什么？",a="它是“残酷的政治”的后续任务。",al={"前置任务","“攻击考尔克”前置条件","“攻击考尔克”先决条件"}},{q="考尔克人在哪里？",a="瓦鲁格让你向北走去寻找他们。",al={"考尔克位置","考尔克半人马在哪里","在哪里找到考尔克"}},{q="为什么瓦鲁格想要杀掉考尔克人？",a="瓦鲁格嘲笑考尔克人自以为强大，并希望你展示出你能像玛格拉姆人一样杀戮他们。",al={"为什么要杀考尔克","玛格拉姆与考尔克的敌对关系","为什么瓦鲁格憎恨考尔克"}}},fp="21,163,20.253.0,16.165.1,35.52.0,27.27.0,29.43.0,38.112.0"}
P.entries["quest:1387"] = {n="悬赏半人马",s="位于尼耶尔前哨站的麦尔金斯下士说，凄凉之地的每一个半人马氏族都有一个共同的特点：残忍，只要半人马还存在，和平就不会到来。麦尔金斯要求你在这片土地上狩猎他们，并带回十五只耳朵。",h="位于尼耶尔前哨站的麦尔金斯下士说，凄凉之地的每一个半人马氏族都有一个共同的特点：残忍，只要半人马还存在，和平就不会到来。麦尔金斯要求你在这片土地上狩猎他们，并带回十五只耳朵。",kw={"联盟","悬赏","半人马","半人马耳朵","麦尔金斯下士","凄凉之地","耳朵","尼耶尔前哨站"},sec={{t="共同点",b="在尼耶尔前哨站，麦尔金斯下士描述了一个分裂成许多氏族的半人马种族，每个氏族都有自己的领袖和计划，但都同样残忍。麦尔金斯说，只有消灭了半人马，和平才会到来。"},{t="联盟的耳朵",b="你在凄凉之地游荡，狩猎半人马并割下他们的耳朵。麦尔金斯想要很多，总共十五只，并称这项工作是对联盟的一种贡献，使战争的终结更近了一步。"}},faq={{q="谁发布了半人马的悬赏任务？",a="麦尔金斯下士，驻扎在凄凉之地的尼耶尔前哨站。",al={"半人马悬赏任务发布者","谁提供半人马悬赏","麦尔金斯悬赏"}},{q="为什么麦尔金斯下士要杀死半人马？",a="麦尔金斯说，这些氏族在领袖和目标上各不相同，但都很残忍，只要半人马还存在，和平就不可能实现。",al={"为什么要杀半人马","麦尔金斯的动机","为什么要半人马耳朵"}},{q="麦尔金斯下士让你带回什么？",a="十五只半人马耳朵，取自你在凄凉之地游荡时狩猎的半人马。",al={"收集什么","半人马悬赏物品","半人马悬赏战利品"}},{q="需要狩猎哪些半人马氏族？",a="麦尔金斯没有提到具体的氏族，他说所有的氏族都同样残忍，只是要求你在凄凉之地狩猎半人马。",al={"哪些半人马","半人马氏族目标","耳朵属于哪个氏族"}}},fp="14,230,19.211.0,21.180.0,37.57.0,50.123.0,44.75.0,38.114.0"}
P.entries["quest:1389"] = {n="德莱尼水晶",s="避难营的玛格图尔要求找回六块德莱尼水晶，这些水晶对玛格图尔的族人来说十分神圣，却被农田避难所的失落者偷走了。没有了这些水晶，玛格图尔的族人担心他们也会迷失自我。",h="避难营的玛格图尔要求找回六块德莱尼水晶，这些水晶对玛格图尔的族人来说十分神圣，却被农田避难所的失落者偷走了。没有了这些水晶，玛格图尔的族人担心他们也会迷失自我。",kw={"德莱尼水晶","农田避难所","避难营","失落者","玛格图尔","悲伤沼泽"},sec={{t="失落者",b="农田避难所的失落者外表看起来与玛格图尔的族人无异，但前往艾泽拉斯的艰苦旅程使他们陷入了疯狂。他们曾经是兄弟，如今却盘踞在东边的避难所里，抓住并杀害任何靠近的人。他们还偷走了一件神圣的东西：德莱尼水晶。"},{t="失去水晶的后果",b="玛格图尔的族人没有足够的力量进入农田避难所，从那些棚屋和营火之间夺回德莱尼水晶。没有了水晶，他们担心自己也会迷失自我。玛格图尔请求你带回六块水晶。"}},faq={{q="是谁在索要德莱尼水晶？",a="玛格图尔，他在避难营。",al={"谁需要德莱尼水晶","玛格图尔任务","谁想要德莱尼水晶"}},{q="为什么德莱尼水晶对玛格图尔很重要？",a="它们对玛格图尔的族人来说十分神圣。没有了它们，玛格图尔担心他们也会迷失自我。",al={"为什么需要德莱尼水晶","德莱尼水晶有什么用","德莱尼水晶的用途"}},{q="是谁偷走了水晶？",a="位于东边的农田避难所的失落者。他们曾经是玛格图尔的兄弟，直到前往艾泽拉斯的艰苦旅程使他们陷入了疯狂。",al={"谁偷了德莱尼水晶","谁拥有水晶","农田避难所的敌人"}},{q="在哪里可以找到这些水晶？",a="在位于东边的农田避难所的棚屋和营火之间。",al={"德莱尼水晶位置","德莱尼水晶在哪里","寻找德莱尼水晶"}},{q="为什么玛格图尔的族人不能自己取回它们？",a="他们没有足够的力量进入避难所并夺回水晶。",al={"为什么玛格图尔不战斗","为什么要帮助玛格图尔"}}},fp="20,206,13.294.0,20.233.0,43.39.0,54.93.0,22.145.0,32.77.0,52.80.0"}
P.entries["quest:139"] = {n="杉德尔船长的宝藏",s="这个任务是桑德斯船长的寻宝任务在西部荒野海岸线上的第三阶段。这张羊皮纸被发现于一个破损的木桶中，指引着寻宝者向北前往海岸风车旁的一个旧罐子。跟随这些隐晦的指示，冒险者们将沿着这位已故海盗的足迹，进一步接近他那传说中的宝藏。",h="这个任务是桑德斯船长的寻宝任务在西部荒野海岸线上的第三阶段。这张羊皮纸被发现于一个破损的木桶中，指引着寻宝者向北前往海岸风车旁的一个旧罐子。跟随这些隐晦的指示，冒险者们将沿着这位已故海盗的足迹，进一步接近他那传说中的宝藏...",kw={"峭壁","破损的木桶","桑德斯船长","隐藏宝藏","旧罐子","海盗线索","西部荒野","风车"},ang={["class:Rogue"]="对于任何欣赏沿海违禁品的潜行者来说，沿着峭壁追踪恶棍留下的死信箱和隐藏信息，就像第二天性一样自然。",["faction:Alliance"]="尽管西部荒野正处于饥荒和迪菲亚暴徒的重压之下，但找到桑德斯遗失的海盗掠夺品对独立的冒险者来说却是一笔受欢迎的横财。"},sec={{t="海盗的线索踪迹",b="桑德斯船长非常小心，他从不把财宝的下落写在一张羊皮纸上。相反，他将指示拆分成了一系列环环相扣的寻宝线索，散落在西部荒野的西海岸线上。每一条发现的线索只指向下一个中间容器，这确保了任何投机的掠夺者都必须亲自跋涉在被海盗出没的峭壁之上，才能最终获得奖赏。"},{t="向北前往峭壁",b="从破损木桶中找到的线索指示寻宝者直接向北，笔直地前往海边的峭壁。在这些峭壁上矗立着一座孤零零的风车，旁边的一个废弃罐子隐藏着海盗谜题的下一个环节。对于在西部荒野沿海地区旅行的冒险者来说，跟随桑德斯的线索意味着必须穿越鱼人和迪菲亚拾荒者出没的区域。"}},faq={{q="桑德斯船长的隐藏宝藏是什么？",a="桑德斯船长是一名海盗，他将自己的财宝藏在了西部荒野的海岸线上。他没有绘制传统的地图，而是留下一连串书写的谜题，散落在乡村各处的木桶、箱子和罐子里。",al={"桑德斯宝藏","这个任务是什么","桑德斯是谁"}},{q="这第三条线索指向哪里？",a="羊皮纸指示你从破损的木桶处径直向北，前往俯瞰大海的峭壁。在那里，靠近一座孤零零的风车，放着一个旧罐子，里面装着最后一条线索。",al={"我该去哪里","罐子位置","风车在哪里"}},{q="为什么桑德斯要将指示分段隐藏？",a="无尽之海沿岸的海盗通常会采取精心设计的预防措施，以保护他们的赃物不被哗变的船员和竞争对手掠夺。通过将路线拆分成多个隐藏的标记，桑德斯确保了即使有人发现了一条线索，也不会自动让他失去全部财宝。",al={"为什么有线索","为什么没有完整的地图"}},{q="部落玩家可以完成这个任务线吗？",a="与桑德斯船长的藏宝相关的线索和物品是中立的，任何找到它们的冒险者都可以进行交互，尽管西部荒野位于联盟控制的领地深处。",al={"这是联盟专属的吗","部落桑德斯宝藏"}},{q="这条线索是否直接揭示了宝箱的位置？",a="不。海岸风车附近的罐子里装着另一条线索，它指向桑德斯宝箱的最终安放地，因此这是寻宝过程中的倒数第二步。",al={"宝藏在罐子里吗","最后一步"}},{q="去往风车的路上有什么危险？",a="西部荒野的西部峭壁和海滩上有大量的河爪豺狼人、沿海鱼人和四处游荡的迪菲亚强盗，对于不加防备的人来说，径直向北前进是非常危险的。",al={"峭壁上的危险","那里有什么怪物"}}},fp="32,217,27.256.0,23.244.0,41.170.0,32.128.0,46.154.0,38.140.0,41.130.0,48.147.0"}
P.entries["quest:1392"] = {n="木棒诺博鲁",s="数月以来，Noboru the Cudgel一直都在折磨着避难营的德莱尼人。他的棍棒象征着失落者对他们施加的残暴行径，你需要将它带给避难营的领袖。",h="数月以来，Noboru the Cudgel一直都在折磨着避难营的德莱尼人。他的棍棒象征着失落者对他们施加的残暴行径，你需要将它带给避难营的领袖。",kw={"棍棒","德莱尼","避难营","失落者","玛格图尔","noboru","悲伤沼泽"},sec={{t="残暴的象征",b="Noboru the Cudgel数月以来一直都在折磨着避难营的德莱尼人。这根棍棒已经成为了失落者带给他们残暴行径的象征。既然你已经拿到了它，就把它带给避难营的领袖吧。"},{t="玛格图尔的欢迎",b="玛格图尔询问这件武器是否意味着Noboru the Cudgel已经死了，并称这一天是当地值得欢庆的日子。Noboru the Cudgel和他的团伙经常在沼泽中游荡，残杀任何挡路的人，以此恐吓德莱尼人。Noboru the Cudgel威胁到了他们的生存，而他们却无力反抗。"}},faq={{q="谁是Noboru the Cudgel？",a="一个失落者，数月以来一直在折磨避难营的德莱尼人。",al={"谁是noboru","noboru背景故事","拥有棍棒的noboru"}},{q="为什么避难营想要Noboru the Cudgel的棍棒？",a="这根棍棒象征着失落者对避难营德莱尼人所施加的残暴行径。",al={"为什么要上交棍棒","noboru棍棒的用途","为什么要将棍棒交给玛格图尔"}},{q="谁来接收这根棍棒？",a="玛格图尔，他是避难营的领袖。",al={"谁是玛格图尔","棍棒的去向"}},{q="避难营位于何处？",a="位于悲伤沼泽，那是避难营德莱尼人居住的地方。",al={"避难营在哪里","避难营位置"}}},fp="17,203,21.194.0,17.274.1,14.75.0,44.93.0,24.33.0,31.65.0"}
P.entries["quest:1393"] = {n="加林的逃亡",s="加林·古瓦德被困在农田避难所，苦苦哀求救他脱离那里的生物，并承诺给任何救他的人一大笔财宝。财宝就放在斯通纳德以北他营地里的一个锁住的强力保险箱中。",h="加林·古瓦德被困在农田避难所，苦苦哀求救他脱离那里的生物，并承诺给任何救他的人一大笔财宝。财宝就放在斯通纳德以北他营地里的一个锁住的强力保险箱中。",kw={"黑色树脂","农田避难所","加林·古瓦德","加林的逃生","斯通纳德","强力保险箱","悲伤沼泽"},sec={{t="救援请求",b="加林·古瓦德大喊着周围的生物要把他吃掉。任何将他从危险中救出来的人都将得到一大笔财宝作为回报。财宝存放在他位于斯通纳德以北沼泽地里的营地中，锁在一个强力保险箱里，只有掌握加林独自知道的诀窍才能打开。如果你能帮他逃脱，他就会把这个诀窍传授给你。"},{t="在强力保险箱处",b="在营地，你发现强力保险箱的锁孔被黑色树脂填满了，因此无法以正常方式打开。但加林曾告诉你保险箱底部有一个隐藏的插销。快速搜索后你找到了它，拨动插销便打开了强力保险箱。"}},faq={{q="加林·古瓦德是谁？",a="一个被困在农田避难所的人，他害怕那里的生物会吃掉他，并承诺给任何帮助他逃脱的人一大笔财宝。",al={"加林是谁","加林·古瓦德背景故事","加林的逃生任务npc"}},{q="加林的营地在哪里？",a="在斯通纳德以北的沼泽里，位于悲伤沼泽。",al={"加林的营地在哪里","加林的强力保险箱位置","强力保险箱在哪里"}},{q="为什么强力保险箱不能用通常的方式打开？",a="加林的财宝锁在一个强力保险箱中，只有通过加林独有的窍门才能打开，而加林会把这个窍门传授给任何帮助他逃脱的人。",al={"如何打开强力保险箱","加林的箱子钥匙"}}},fp="14,206,17.322.0,16.227.1,22.146.0,30.55.0,51.149.0"}
P.entries["quest:1394"] = {n="通过试炼",s="帕科瓦·芬塔拉斯告诉你，你已经通过了这次考验以及之前的那些。你被派回千针石林的多恩·平原行者那里，他会察觉到你的变化，看看你的思想、身体和精神是否已经足够强大，足以因为你的努力而获得嘉奖。",h="帕科瓦·芬塔拉斯告诉你，你已经通过了这次考验以及之前的那些。你被派回千针石林的多恩·平原行者那里，他会察觉到你的变化，看看你的思想、身体和精神是否已经足够强大，足以因为你的努力而获得嘉奖。",kw={"多恩·平原行者","最终通道","乱风岗","帕科瓦·芬塔拉斯","信仰试炼","知识试炼","千针石林","老屋"},ang={["faction:Horde"]="这一系列试炼是为部落设定的，并以多恩·平原行者作为终点。"},sec={{t="回到老屋",b="这是信仰试炼的最后一步，这是一系列由多恩·平原行者发起的挑战。多恩在老屋等待，那是一个位于乱风岗以北、通过一条坡道才能到达的洞穴。帕科瓦·芬塔拉斯敦促你在这些试炼中保持你所展现出的平衡。"},{t="多恩的欢迎",b="多恩评论说你已经离开他的家很长时间了，从你第一次跳跃踏上这条道路以来，已经过去了许多个夜晚。他发现你比以前更强大、更开明，这让他感到欣慰，并表示你理应因为坚持完成他的测试而获得嘉奖。"}},faq={{q="是谁派你进行这最后一步的？",a="帕科瓦·芬塔拉斯，他告诉你，你已经通过了他的测试，以及在他之前的那些测试。",al={"任务发布者","谁开启最终通道","帕科瓦·芬塔拉斯"}},{q="我接下来要去哪里？",a="回到千针石林的多恩·平原行者那里。他在老屋等待，那是一个位于乱风岗以北、通过一条坡道才能到达的洞穴。",al={"多恩在哪里","去哪里交任务","多恩·平原行者位置","老屋位置"}},{q="在这之前发生了什么？",a="它紧随知识试炼之后，这是同一系列任务中的一个早期挑战。",al={"上一个任务","前置条件","什么引导至最终通道"}},{q="这段旅程的第一步是什么？",a="信仰试炼，由老屋的多恩·平原行者发起。这是该系列任务的最后一步。",al={"第一个任务","这从哪里开始","信仰试炼系列"}},{q="为什么帕科瓦让你回到多恩那里？",a="帕科瓦说多恩会注意到你的变化，并发现你的思想、身体和精神足够强大，值得获得嘉奖。",al={"为什么是多恩","帕科瓦的原因"}}},fp="13,279,26.276.0,14.279.1,33.88.0,19.131.0,23.60.0,45.102.0,39.116.0"}
P.entries["quest:1396"] = {n="逼近的野兽",s="卫兵比格斯在前往东海岸的一支商队中遇袭，袭击者是失落者。比格斯是唯一的幸存者，现在营地附近徘徊着各种野生生物。比格斯请求你协助他进行防御。此任务紧随“帮助卫兵比格斯”。",h="卫兵比格斯在前往东海岸的一支商队中遇袭，袭击者是失落者。比格斯是唯一的幸存者，现在营地附近徘徊着各种野生生物。比格斯请求你协助他进行防御。此任务紧随“帮助卫兵比格斯”。",kw={"商队","失落者","锯齿鳄鱼","悲伤织网者","补给品","沼泽猎豹","悲伤沼泽","卫兵比格斯"},sec={{t="监视下的营地",b="卫兵比格斯的商队原本计划前往东海岸，但从未抵达。失落者发起了袭击，杀死了守卫并摧毁了补给品，只有比格斯一人幸存。比格斯发誓要保护剩下的补给品，但营地周围却徘徊着许多野生生物。比格斯希望你能帮他保卫营地。"},{t="附近的生物",b="比格斯提到了三种在营地附近逼近的生物：幼年锯齿鳄鱼、悲伤织网者和沼泽猎豹。需要击杀八只鳄鱼、十只织网者和十只猎豹。"}},faq={{q="卫兵比格斯的商队要去哪里？",a="去东海岸，但商队没能到达目的地。",al={"比格斯要去哪里","商队目的地","比格斯的商队路线"}},{q="谁袭击了卫兵比格斯的商队？",a="失落者。他们杀死了守卫并摧毁了补给品，比格斯是唯一的幸存者。",al={"谁袭击了比格斯","谁摧毁了商队","商队伏击"}},{q="什么野兽威胁着营地？",a="幼年锯齿鳄鱼、悲伤织网者和沼泽猎豹在营地附近徘徊。",al={"哪些野兽在逼近","什么动物袭击了比格斯","沼泽野兽"}},{q="为什么卫兵比格斯留在营地？",a="比格斯发誓要保护商队剩下的补给品。",al={"为什么比格斯留下来","为什么不逃走","比格斯的补给品"}}},fp="20,227,18.303.0,20.185.0,44.61.0,37.85.0,30.75.0,42.69.0"}
P.entries["quest:1398"] = {n="晒干的流木",s="在“失踪的商队”任务之后，卫兵比格斯在抵达守望堡之前还需要修理一辆马车。比格斯需要坚固、干燥的木材，于是派你前往东边的海岸，去寻找被太阳晒干的漂流木。",h="在“失踪的商队”任务之后，卫兵比格斯在抵达守望堡之前还需要修理一辆马车。比格斯需要坚固、干燥的木材，于是派你前往东边的海岸，去寻找被太阳晒干的漂流木。",kw={"漂流木","守望堡","晒干的漂流木","悲伤沼泽","马车","卫兵比格斯"},sec={{t="修理马车的木材",b="卫兵比格斯说他非常感谢你，并再次请求你的帮助。如果比格斯想要抵达守望堡，就必须修好马车，而这需要坚固、干燥的木材。沼泽里的树木木质松软且盘根错节，根本用不了。"},{t="海岸的漂流木",b="比格斯派你前往东边的海岸，去寻找被太阳晒干的漂流木。你需要带八块漂流木回到悲伤沼泽的卫兵比格斯那里。"}},faq={{q="为什么卫兵比格斯需要木材？",a="如果比格斯想要抵达守望堡，就必须修好马车，而沼泽里树木的木材太松软、太杂乱了。",al={"漂流木的用途","为什么比格斯需要漂流木","为什么要漂流木"}},{q="卫兵比格斯让你去哪里寻找木材？",a="前往东边的海岸，去寻找被太阳晒干的漂流木。",al={"漂流木的位置","去哪寻找漂流木","木材在哪里"}},{q="这个任务的前置任务是什么？",a="首先是“失踪的商队”，在那之后比格斯才会寻求进一步的帮助。",al={"漂流木的前置任务","什么任务开启漂流木","漂流木之前是什么任务"}},{q="需要多少漂流木？",a="八块晒干的漂流木。",al={"漂流木数量","需要多少漂流木"}},{q="收集完漂流木之后有什么后续任务？",a="接下来是“运送货物”任务。",al={"漂流木的后续","漂流木之后是什么","漂流木的下一个任务"}}},fp="9,196,18.244.0,24.152.0,33.121.0,47.66.0,22.64.0,29.35.0,41.29.0"}
P.entries["quest:14"] = {n="西部荒野人民军",s="这项任务标志着格里安·斯托曼清除西部荒野道路和农田里的迪菲亚潜行者的战役达到了高潮。通过猎杀盘踞在南部匕首岭的老练强盗，志愿者们证明了自己的奉献精神，并正式加入了哨兵岭的人民民兵组织。",h="这项任务标志着格里安·斯托曼清除西部荒野道路和农田里的迪菲亚潜行者的战役达到了高潮。通过猎杀盘踞在南部匕首岭的老练强盗，志愿者们证明了自己的奉献精神，并正式加入了哨兵岭的人民民兵组织。",kw={"匕首岭","迪菲亚强盗","迪菲亚拳手","迪菲亚寻路者","格里安·斯托曼","人民民兵组织","哨兵岭","西部荒野"},ang={["class:Paladin"]="斯托曼向新兵祈求圣光的祝福，反映了正义和保护弱小免受掠夺性歹徒侵害的神圣理想。",["faction:Alliance"]="暴风城未能保护西部荒野，迫使联盟的平民不得不流血来维持家园的秩序。",["race:Human"]="对于暴风城的人类来说，这项任务代表着为那些被首都政治精英所抛弃的乡亲们挺身而出，维护他们的生计。"},sec={{t="肃清匕首岭",b="西部荒野北部的农田在迪菲亚潜行者的蹂躏下损失惨重，但从斯托曼早期扫荡中逃脱的歹徒撤退到了南部的匕首岭岩石峭壁中。迪菲亚强盗、寻路者和拳手们利用复杂的地形，不断袭击乡村宅地并拦截路人。为了打破他们对该地区南部半区的控制，人民民兵组织派遣经验丰富的招募人员进入山岭，直接瓦解这些强盗团伙。"},{t="斯托曼的十字军",b="格里安·斯托曼在结束了洛丹伦抗击天灾军团的战斗回到家乡后，发现西部荒野被暴风城的皇家卫队完全抛弃，于是组建了人民民兵组织。面对猖獗的犯罪集团和被赶出土地、流离失所的农民，他组织当地志愿者拿起了武器。完成这一最终阶段的巡逻任务，冒险者将正式加入民兵组织，并得到斯托曼在圣光之中的祝福，进一步深入对兄弟会的打击。"}},faq={{q="匕首岭在哪里？",a="匕首岭位于西部荒野南部，哨兵岭的西南方。那里崎岖的山脊和废弃的矿口是迪菲亚潜行者中精锐战士的集结地和堡垒。",al={"匕首岭位置","在哪里找到匕首岭","在哪里可以找到强盗"}},{q="为什么人民民兵组织要独自对抗迪菲亚潜行者？",a="由于瓦里安·乌瑞恩国王失踪，资源匮乏，暴风城的贵族议会拒绝部署皇家军队来保护西部荒野的农村地区。格里安·斯托曼和当地农民别无选择，只能组建自己的志愿者武装来保卫家园。",al={"为什么没有暴风城卫兵","暴风城军队在哪里","为什么西部荒野被遗弃"}},{q="完成这项任务能达成什么目标？",a="消灭强盗、寻路者和拳手能够打破迪菲亚潜行者对西部荒野南部道路的控制，并使你正式加入格里安·斯托曼指挥下的人民民兵组织。",al={"人民民兵组织任务完成","民兵入伍","完成任务后的奖励"}},{q="格里安·斯托曼是谁？",a="格里安·斯托曼是一名曾在第三次战争中于洛丹伦作战的资深士兵。在回到家乡西部荒野，目睹暴风城王国抛弃农村平民后，他在哨兵岭建立了人民民兵组织以对抗迪菲亚潜行者。",al={"格里安背景","斯托曼是谁","哨兵岭领袖"}},{q="匕首岭里潜伏着什么样的迪菲亚成员？",a="匕首岭窝藏着经验丰富的迪菲亚强盗、致命的寻路者以及残暴的拳手，他们策划针对西部荒野南部的突袭，并守卫着兄弟会更深处的据点。",al={"西部荒野南部的迪菲亚怪物","什么是迪菲亚寻路者和拳手","谁在匕首岭"}},{q="这与洛丹伦有什么联系？",a="格里安·斯托曼提到他刚从“被污染的洛丹伦大地”归来，联盟曾在那里对抗天灾军团。在那个残酷战场的幸存经历，让他拥有了在地方当局无作为时组织西部荒野防线的决心。",al={"斯托曼洛丹伦经历","被污染的洛丹伦大地","格里安战争历史"}}},fx={["12e61ece"]={q="格里安·斯托曼为什么想杀掉这些迪菲亚潜行者？",a="迪菲亚劫掠者已经深入西部荒野南部，洗劫农场并躲避民兵巡逻。格里安的侦察兵追踪他们到了匕首岭，发现他们正在那里集结，谋划下一次袭击。如果现在不把他们连根拔起并击溃，南部剩余的农庄就会彻底落入他们掌控。",al={"为什么在匕首岭杀迪菲亚潜行者","格里安的动机","格里安为什么要杀掉他们"}}},fp="20,306,24.514.0,21.516.0,27.203.0,54.268.0,39.204.0,25.272.0,45.198.0,35.250.0"}
P.entries["quest:140"] = {n="杉德尔船长的宝藏",s="这标志着桑德斯船长的寻宝游戏在西部荒野的终结。根据在一个旧酒罐里发现的浸透威士忌的字条，寻宝者被指引前往西海岸，去领取一份隐藏已久的财宝。这次探险将引领人们进入公海，远离大陆的纷扰，抵达一座偏远的海岸小岛。",h="这标志着桑德斯船长的寻宝游戏在西部荒野的终结。根据在一个旧酒罐里发现的浸透威士忌的字条，寻宝者被指引前往西海岸，去领取一份隐藏已久的财宝。这次探险将引领人们进入公海，远离大陆的纷扰，抵达一座偏远的海岸小岛。",kw={"桑德斯船长","最终线索","隐藏的财宝","岛屿","上锁的宝箱","旧酒罐","寻宝游戏","西部荒野"},ang={["class:Rogue"]="对于任何欣赏海盗违禁品的潜行者来说，沿着恶棍留下的踪迹穿越荒凉的海滩并深入大海，就像本能一样自然。",["race:Human"]="对于那些保护西部荒野免受迪菲亚兄弟会强盗和豺狼人侵扰的人类来说，追踪被遗忘的当地海盗宝藏能让他们从农场巡逻中获得难得的放松。"},sec={{t="水手的踪迹",b="桑德斯船长在西部荒野的海岸线上留下一连串线索，敢于冒险的人可以将它们拼凑起来。最后一张羊皮纸是从他最爱的威士忌酒罐残渣中取出的，指明了最终的方向。墨迹模糊，散发着浓烈的酒味，船长的指示非常直接：径直向西前往水边，然后跃入波涛之中。"},{t="孤寂的小岛",b="在西部荒野的海岸外，几处岩石礁岛从波涛汹涌的无尽之海中凸显出来。向正西方向游去，直达其中一座孤岛，那便是桑德斯船长藏匿财宝之处。这只上了锁的箱子半掩在沙中，历经多年海水的冲刷，只要你有足够的毅力将这位海盗的游戏进行到底，那些锈迹斑斑的铰链最终会屈服。"}},faq={{q="最后的线索指向哪里？",a="旧酒罐里那张浸透威士忌的字条指引寻宝者径直向西前往西部荒野的海岸，并继续游向大海。箱子就在海中的一个小岛上等待着。",al={"宝箱在哪里","桑德斯财宝位置","最终线索目的地"}},{q="桑德斯船长是谁？",a="桑德斯船长是一位在西部荒野沿海航行的海盗。他没有将战利品存放在银行或据点，而是在海岸线上创造了一连串充满谜题的线索，并将他的箱子留在了海岸外的一座偏远岛屿上。",al={"桑德斯船长是谁","桑德斯背景故事","桑德斯船长背景"}},{q="为什么最后的线索有威士忌的味道？",a="最后的指示被塞在桑德斯船长丢弃在海岸附近的威士忌酒罐里。潮湿和酒精导致墨水随时间推移而晕染，但指示内容依然清晰可辨。",al={"威士忌字条","旧酒罐线索"}},{q="这次寻宝游戏一共有多少步？",a="这次寻宝活动总共有四个阶段。它始于在海岸边发现的一张饱经风霜的藏宝图，并蜿蜒经过几个隐藏的容器——包括一个步兵箱、一个木桶和一个威士忌酒罐——最后在岛上的箱子处结束。",al={"桑德斯任务链有多长","桑德斯任务部分","桑德斯船长任务线"}},{q="前往那座岛屿危险吗？",a="主要的挑战是游向远离海岸的无尽之海。虽然西部荒野的近海水域经常受到好斗的鱼人和海兽的骚扰，但那座小岛主要只是桑德斯的私人藏宝点。",al={"游向桑德斯宝箱","岛屿危险度","宝箱附近的鱼人"}},{q="宝箱的状态如何？",a="暴露在潮湿的海风和汹涌的海浪中，这个箱子饱受风雨侵蚀。它的铰链已经严重生锈，但只要稍微用力，就能将其撬开，取出里面留下的财宝。",al={"宝箱状况","宝箱是否上锁","生锈的宝箱"}}},fp="32,189,16.289.0,16.295.1,31.123.0,24.212.0,44.180.0,41.169.0,33.176.0,36.139.0"}
P.entries["quest:141"] = {n="迪菲亚兄弟会",s="将暴风城的机密报告从马迪亚斯·肖尔处转交给哨兵岭的格里安·斯托曼。肖尔已经对前石匠工会进行了调查，以帮助斯托曼揭开迪菲亚潜行者的起源。",h="将暴风城的机密报告从马迪亚斯·肖尔处转交给哨兵岭的格里安·斯托曼。肖尔已经对前石匠工会进行了调查，以帮助斯托曼揭开迪菲亚潜行者的起源。",kw={"迪菲亚","哨兵岭","肖尔","石匠","暴风城","斯托曼","范克里夫","西部荒野"},ang={["class:Rogue"]="对暴风城前工匠的调查表明，王国内部的纠纷是如何困扰其偏远定居点的。",["faction:Alliance"]="石匠的叛乱揭示了王国内部深刻的裂痕：正是那些重建了暴风城坚固石墙的工人们，现在却威胁要将其摧毁。",["race:Human"]="对于暴风城的人类来说，这一揭露触及了他们的切身利益。他们家园的墙壁，甚至是教堂本身，都是由现在正在劫掠西部荒野乡村的那些人建造的。"},sec={{t="工匠变强盗",b="数月以来，格里安·斯托曼和人民民兵一直在西部荒野对抗着一群似乎没有组织头目的拦路强盗、窃贼和割喉者。当军情七处的马迪亚斯·肖尔大师查阅了威利的便笺后，他拼凑出了一个令人震惊的事实：那个重建了暴风城白色城墙的建筑师与石匠工会从未解散。相反，他们的首领艾德温·范克里夫带领他们转入了地下。"},{t="苦涩与背叛",b="第一次战争造成了毁灭性的破坏，暴风城沦为一片废墟。范克里夫的石匠工会承担了重建王国首都这一艰巨的任务，使它再次成为人类的明珠。然而，当工作结束时，双方就报酬问题产生了激烈的纠纷。由于对王室和贵族议会对待他们的方式感到不满，范克里夫和他的工匠们拿起了匕首，戴上了红色面巾，从市政建设转向了对王权的暴力反叛。"},{t="斯托曼的质疑",b="当肖尔的报告传到哨兵岭时，格里安·斯托曼感到这些消息难以接受。在斯托曼的记忆中，范克里夫并非那种在乡间阴影中潜行的割喉者，而是一位勤劳且富有天赋的工匠，他的工作为成千上万回归的公民提供了安身之所。面对如此令人震惊的指控，这位民兵指挥官在完全接受暴风城的首席建筑师正在策划西部荒野的毁灭这一事实之前，要求获得确凿的证据。"}},faq={{q="什么是肖尔的报告？",a="其中包含了马迪亚斯·肖尔关于前石匠工会和迪菲亚潜行者的调查结果。将这份机密报告交给格里安·斯托曼。",al={"肖尔的报告","马迪亚斯·肖尔的文档","交给斯托曼的报告"}},{q="艾德温·范克里夫是谁？",a="艾德温·范克里夫是重建暴风城的石匠工会的首领。这份报告调查了该工会后来的历史。",al={"范克里夫的身份","艾德温·范克里夫是谁","艾德温·范克里夫背景故事"}},{q="为什么格里安·斯托曼对报告持怀疑态度？",a="斯托曼觉得肖尔的指控难以置信，需要进一步的证据。具体细节在他阅读报告后会揭晓。",al={"为什么格里安不相信","斯托曼的反应","为什么格里安需要证据"}},{q="为什么石匠们会背叛暴风城？",a="石匠们重建了暴风城，但后来因为报酬问题与贵族发生了激烈的纠纷。肖尔的报告调查了随后发生的事情。",al={"迪菲亚为什么愤怒","石匠纠纷","范克里夫的动机"}},{q="军情七处在这个任务中扮演什么角色？",a="肖尔调查了前工会与法外之徒之间可能存在的联系，并将他的调查结果发送给了斯托曼。",al={"为什么是马迪亚斯·肖尔","军情七处的参与","暴风城盗贼公会"}},{q="这次调查接下来会引向何处？",a="递交报告，然后帮助斯托曼在持续进行的迪菲亚潜行者调查中寻找进一步的证据。",al={"what comes next","下一个迪菲亚任务","肖尔的报告之后"}}},fp="22,212,23.416.1,23.458.1,23.423.1,22.141.0,22.118.0,49.167.0,47.167.0,39.129.0,40.106.1"}
P.entries["quest:1418"] = {n="尼卡·血痕",s="赫格拉姆让你从斯通纳德前往荒芜之地的卡加斯哨所，去和那里的首席斥候尼卡·血疤谈谈。斯通纳德和卡加斯之间的消息经常中断。",h="赫格拉姆让你从斯通纳德前往荒芜之地的卡加斯哨所，去和那里的首席斥候尼卡·血疤谈谈。斯通纳德和卡加斯之间的消息经常中断。",kw={"荒芜之地","首席斥候","赫格拉姆","卡加斯","洛克莫丹","尼卡·血疤","斯通纳德","悲伤沼泽"},sec={{t="中断的联络",b="荒芜之地环境恶劣，且毗邻联盟控制的洛克莫丹。正因如此，斯通纳德和卡加斯之间的消息经常中断。赫格拉姆让你前往荒芜之地并与那里的首席斥候尼卡·血疤交谈，以此证明你的实力。之后，你需要将尼卡的报告送回给赫格拉姆。"},{t="尼卡的答复",b="尼卡告诉你，就在三天前，她才刚刚派出一名信使前往斯通纳德。如果斯通纳德没有收到尼卡的消息，那名信使一定是出事了。尼卡希望下一位信使能更有技巧，或者更好运。"}},faq={{q="赫格拉姆让你去哪里？",a="从斯通纳德前往荒芜之地的卡加斯哨所，去见尼卡·血疤。",al={"我该去哪里","尼卡·血疤的位置","尼卡在哪里"}},{q="为什么斯通纳德和卡加斯之间的通信会中断？",a="荒芜之地环境恶劣，且毗邻联盟控制的洛克莫丹，因此斯通纳德和卡加斯之间的消息经常中断。",al={"为什么通信中断","荒芜之地通信问题","为什么从斯通纳德去卡加斯"}},{q="尼卡·血疤是谁？",a="尼卡·血疤是荒芜之地卡加斯哨所的首席斥候。",al={"尼卡是谁","尼卡的职责","尼卡·血疤背景故事"}},{q="和尼卡·血疤谈过之后接下来要做什么？",a="接下来要向赫格拉姆报告。",al={"接下来做什么","后续任务","在尼卡·血疤之后"}}},fp="15,170,10.325.0,14.199.1,38.86.0,57.128.0,23.73.0,47.26.0"}
P.entries["quest:1419"] = {n="捕猎山狗",s="在卡加斯哨所，妮卡·血痕希望你去狩猎荒芜之地的峭壁郊狼。这些顽强的野兽竟敢潜入卡加斯偷取食物。妮卡需要三十块下颚骨。",h="在卡加斯哨所，妮卡·血痕希望你去狩猎荒芜之地的峭壁郊狼。这些顽强的野兽竟敢潜入卡加斯偷取食物。妮卡需要三十块下颚骨。",kw={"荒芜之地","郊狼窃贼","峭壁郊狼","下颚骨","卡加斯","妮卡·血痕"},sec={{t="卡加斯的窃贼",b="妮卡·血痕询问你是否在荒芜之地待过很久，是否感受过那里的炎热，并遭遇过尘土平原上的野兽。峭壁郊狼是一种凶猛的物种，它们溜进卡加斯偷窃了哨所的食物。妮卡想要猎杀它们，并带回它们的下颚骨。带回足够的数量，妮卡或许才会相信你了解荒芜之地。"}},faq={{q="为什么妮卡·血痕想要郊狼下颚骨？",a="峭壁郊狼溜进了卡加斯并偷窃了那里的食物储备。妮卡想要猎杀它们，并要求提供下颚骨作为你了解荒芜之地的证明。",al={"为什么需要郊狼下颚骨","妮卡·血痕的动机","收集下颚骨的原因"}},{q="郊狼在哪里制造麻烦？",a="峭壁郊狼在荒芜之地的尘土平原上游荡，它们已经潜入了卡加斯哨所偷取食物。",al={"郊狼位置","哪里能找到峭壁郊狼","郊狼在哪里"}},{q="妮卡·血痕需要多少块下颚骨？",a="三十块郊狼下颚骨，交给位于卡加斯的妮卡·血痕。",al={"需要多少块下颚骨","郊狼下颚骨数量"}},{q="妮卡·血痕是谁？",a="妮卡·血痕位于荒芜之地的卡加斯哨所，她在此发布这项狩猎任务。",al={"妮卡是谁","妮卡·血痕"}}},fp="14,206,18.339.0,46.154.0,38.116.0,44.62.0,23.94.0"}
P.entries["quest:142"] = {n="迪菲亚兄弟会",s="这项关键任务派遣冒险者沿着西部荒野尘土飞扬的道路，去追捕一名行踪不定的迪菲亚信使。截获他的公文可以让格里安·斯托曼和人民军发现有关强盗起义的重要情报。",h="这项关键任务派遣冒险者沿着西部荒野尘土飞扬的道路，去追捕一名行踪不定的迪菲亚信使。截获他的公文可以让格里安·斯托曼和人民军发现有关强盗起义的重要情报。",kw={"迪菲亚","詹戈洛德","信使","月溪镇","矿洞","萨丁","斯托曼","范克里夫","西部荒野"},ang={["class:Rogue"]="追踪迪菲亚信使突显了熟练的侦察兵和扒手是如何在民兵眼皮底下协调一个庞大的阴影网络的。",["faction:Alliance"]="暴风城的沉默迫使西部荒野的人民军不得不独自处理区域情报，在没有皇家卫戍部队支持的情况下，沿着荒凉的土路追踪信使。",["race:Human"]="对于王国的平民来说，追查这些发往艾德温·范克里夫的公文，揭示了暴风城政治和劳工纠纷所遗留的痛苦后果。"},sec={{t="截获信使",b="格里安·斯托曼的侦察兵注意到一名行踪诡秘的迪菲亚信使往返于月溪镇、金海岸矿洞和詹戈洛德矿洞这些重要的歹徒据点之间。与在乡间肆虐的普通暴徒不同，这名信使携带着该地区的重要书面命令。斯托曼下令将其俘获或击杀，以便人民军能够阅读他挎包里的内容，从而推断出兄弟会指挥其部队的所在位置。"},{t="墨迹线索",b="从信使身上找回的信息提供了无可辩驳的证据，证明艾德温·范克里夫——这位传奇的石匠工会前任首领——正在亲自策划迪菲亚暴乱。虽然截获的便条证实了范克里夫对当地各据点的指挥权，但仍不足以精确定位他秘密行动基地的位置。"},{t="转机",b="就在信使的命令证实了范克里夫的领导地位时，人民军得到了一个重大突破。一名试图偷窃农夫萨丁的马车而被抓获的绝望强盗同意以出卖同伙换取自己的性命。手握书面证据，斯托曼将重心转移到了这个叛徒身上，希望他能带领一支护送队深入迪菲亚隐秘基地的腹地。"}},faq={{q="迪菲亚信使的移动路线是怎样的？",a="迪菲亚信使的巡逻始于月溪镇铁匠铺外。从那里出发，他沿着北面的道路检查金海岸矿洞和詹戈洛德矿洞，在进入这两个地下挖掘点后，会沿原路返回月溪镇。",al={"信使路线","迪菲亚信使在哪里","寻找信使"}},{q="截获的信息揭示了什么？",a="斯托曼希望信使的书面命令能够揭示兄弟会的指挥结构，并帮助找到其据点。当信息被追回时，其内容便会被发现。",al={"信里写了什么","神秘信件内容","范克里夫便条"}},{q="格里安·斯托曼是谁？",a="格里安·斯托曼是人民军的战地指挥官，总部设在哨兵岭。由于缺乏来自暴风城的皇家守卫，他组织了志愿者和冒险者来保卫西部荒野，抵御迪菲亚掠夺者。",al={"斯托曼的职责","谁提供这个任务"}},{q="为什么信使要前往这些矿洞？",a="兄弟会已经占据了西部荒野的矿产资源，利用詹戈洛德矿洞和金海岸矿洞等地点作为原材料来源、避难所和集结地。信使负责保持这些分散的行动与兄弟会领导层之间的联络。",al={"为什么去金海岸矿洞","为什么去詹戈洛德矿洞"}},{q="抓住信使能揭示迪菲亚的据点吗？",a="斯托曼打算利用截获的命令来推进他对据点的搜索。当你回去找他时，就能了解到下一步的线索。",al={"我们找到据点了吗","据点在哪里"}},{q="艾德温·范克里夫是谁？",a="艾德温·范克里夫是曾重建暴风城的石匠工会的大工匠。斯托曼的调查旨在审视他与兄弟会之间可能存在的联系。",al={"范克里夫是谁","迪菲亚领袖"}}},fp="22,116,24.376.0,14.251.1,17.347.1,39.213.0,41.173.1,25.204.0,40.235.0,54.134.0,22.171.1"}
P.entries["quest:1420"] = {n="向赫格拉姆报到",s="尼卡·血痕为斯通纳德的赫格拉姆写了一份新的报告，并请求你把它带过去。这发生在你拜访卡加斯的尼卡之后。",h="尼卡·血痕为斯通纳德的赫格拉姆写了一份新的报告，并请求你把它带过去。这发生在你拜访卡加斯的尼卡之后。",kw={"荒芜之地","赫格拉姆","部落情报","尼卡·血痕","前哨跑手","报告","斯通纳德"},sec={{t="一份送往斯通纳德的报告",b="尼卡·血痕为斯通纳德的赫格拉姆写了一份新报告，并把它交给你。尼卡补充说，任何自称为前哨跑手的人，都绝不能迷路，也不能倒在敌人面前。"},{t="赫格拉姆阅读报告",b="阅读了尼卡的报告后，赫格拉姆看出联盟正面临自己的麻烦。赫格拉姆还认为部落和联盟或许会发现他们拥有共同的敌人。"}},faq={{q="是谁派你带着报告去的？",a="尼卡·血痕，她为赫格拉姆写了一份新的报告。",al={"谁把报告交给赫格拉姆","报告交给赫格拉姆的任务给予者","谁开启了这个任务"}},{q="这份报告需要送到哪里？",a="送到斯通纳德的赫格拉姆手中。",al={"在哪里上交报告给赫格拉姆","赫格拉姆位置","赫格拉姆在哪里"}},{q="在这之前发生了什么？",a="在此之前，赫格拉姆曾派你去卡加斯与尼卡·血痕交谈。",al={"前置任务","报告交给赫格拉姆的前提条件","哪个任务在前"}}},fp="17,153,20.185.0,24.162.1,30.60.0,43.32.0,23.95.0"}
P.entries["quest:1421"] = {n="丢失的货物",s="继“入侵的野生动物”之后，卫兵比格斯还有别的事需要拜托你。在失落者袭击商队时，比格斯虽然被打晕了，但还是看到一辆货车被拖向了北边的失落者村落——农田避难所。车上装有一箱珍贵的试剂，比格斯希望你能把那些试剂带回来。",h="继“入侵的野生动物”之后，卫兵比格斯还有别的事需要拜托你。在失落者袭击商队时，比格斯虽然被打晕了，但还是看到一辆货车被拖向了北边的失落者村落——农田避难所。车上装有一箱珍贵的试剂，比格斯希望你能把那些试剂带回来。",kw={"黑暗之门","农田避难所","失落者","守望堡","悲伤沼泽","卫兵比格斯","法师试剂"},sec={{t="失窃的货车",b="比格斯在袭击中被打昏了头，但他瞥见商队的一辆货车被拖往北边的失落者村落——农田避难所。那辆车上有一箱守望堡的法师们进行研究所需的贵重试剂。比格斯希望你能找到那个箱子，并将里面的东西带回来。"},{t="比格斯的消息",b="当你带回试剂后，比格斯感到很高兴，因为守望堡的法师们现在可以继续他们的工作了。比格斯不知道那项工作具体是什么，只知道它与诅咒之地的黑暗之门有关，并且对维护联盟的安全至关重要。"}},faq={{q="卫兵比格斯是谁？",a="卫兵比格斯在失落者的袭击中丢了一辆商队货车，他希望找回车上运载的试剂。",al={"卫兵比格斯","谁发布了失落的商队任务"}},{q="失落者把商队的箱子带到哪去了？",a="比格斯看到货车被拖往北边的失落者村落——农田避难所，那个箱子就在车上。",al={"商队箱子位置","农田避难所在哪","试剂在哪里"}},{q="为什么这些试剂很重要？",a="守望堡的法师们依赖这些试剂来进行他们的研究。",al={"为什么试剂很重要","守望堡试剂用途"}},{q="找回箱子后接下来要做什么？",a="当比格斯拿到试剂后，任务“浮木”就会开启。",al={"失落的商队后续任务","失落的商队任务线"}}},fp="16,303,16.322.0,15.274.1,21.103.0,47.116.0,31.65.0,38.46.0"}
P.entries["quest:1422"] = {n="海中的威胁",s="在完成“缺乏盈余”后，托克卡尔开始着手制作你的武器，并让你去悲伤沼泽找卡塔尔谈谈。卡塔尔说海滩上的巡逻队需要一些援助。",h="在完成“缺乏盈余”后，托克卡尔开始着手制作你的武器，并让你去悲伤沼泽找卡塔尔谈谈。卡塔尔说海滩上的巡逻队需要一些援助。",kw={"海滩","卡塔尔","巡逻","海岸","悲伤沼泽","来自海洋的威胁","托克卡尔"},sec={{t="与卡塔尔交谈",b="在制作你的武器时，托克卡尔建议你去和卡塔尔谈谈，因为卡塔尔提到海滩上的巡逻队需要一些帮助。托克卡尔和一些整天酗酒的懒汉住在同一个营地里，他宁愿你保持清醒和警惕，时刻准备好武器，也不想让你和他们同流合污。"},{t="海浪的咆哮",b="卡塔尔请求你保持片刻的安静。在沉闷的海浪声之上，依然可以听到鱼人那令人作呕的咕噜声。"}},faq={{q="为什么托克卡尔要让你去找卡塔尔？",a="托克卡尔正忙着处理你的武器，而且他宁愿你保持清醒和警惕，也不愿你和营地里那些懒汉一起酗酒。",al={"为什么要找卡塔尔谈话","托克卡尔的理由","为什么要拜访卡塔尔"}},{q="卡塔尔需要什么样的协助？",a="卡塔尔曾提到海滩上的巡逻队需要一些援助，那正是卡塔尔所求之事。",al={"卡塔尔的问题","卡塔尔想要什么","卡塔尔的巡逻"}},{q="这一步之前发生了什么？",a="这一步紧随“缺乏盈余”之后，在那之后托克卡尔便开始制作你的武器。",al={"前置任务","前置条件","来自海洋的威胁任务链"}}},fp="19,176,17.260.0,24.126.1,35.133.0,37.105.0,27.75.0"}
P.entries["quest:1423"] = {n="遗失的补给品",s="这个坚固的小桶接缝处封着刺鼻的黄色蜡。桶底的印戳标明了军需官朗格尔斯和守望堡，这正是它该去的地方。",h="这个坚固的小桶接缝处封着刺鼻的黄色蜡。桶底的印戳标明了军需官朗格尔斯和守望堡，这正是它该去的地方。",kw={"木桶","夜色镇","遗失的货物","守望堡","军需官朗格尔斯","悲伤沼泽"},sec={{t="印戳木桶",b="这个结实小巧的木桶接缝处用刺鼻的黄色蜡封着。桶底的印戳写着“军需官朗格尔斯，守望堡”，说明这个桶是给那里的军需官的。"},{t="来自军需官的消息",b="军需官朗格尔斯感谢你的帮助。货物从夜色镇运往守望堡的途中经常丢失，能找回一些货物真是太好了。"}},faq={{q="谁应该收到这些遗失的货物？",a="这个木桶上标记着要送往守望堡的军需官朗格尔斯处。",al={"谁会收到木桶","遗失货物的收件人","木桶应该送到哪里"}},{q="你怎么知道木桶的主人是谁？",a="木桶底部有一个印戳，上面写着军需官朗格尔斯和守望堡的名字。",al={"木桶上的标记","如何辨认木桶","军需官朗格尔斯的印戳"}},{q="木桶看起来是什么样的？",a="这是一个坚固的小木桶，接缝处涂有刺鼻的黄色蜡。",al={"遗失货物的木桶","木桶外观描述"}}},fp="17,169,16.185.0,27.134.1,42.68.0,37.90.0,31.69.0"}
P.entries["quest:1424"] = {n="泪水之池",s="在斯通纳德，费泽鲁尔要求你在泪水之池周围搜寻阿塔莱遗物。大酋长派遣费泽鲁尔的族人去调查阿塔哈卡神庙中发生的奇异事件，而当他们抵达时，发现神庙已经沉没了。",h="在斯通纳德，费泽鲁尔要求你在泪水之池周围搜寻阿塔莱遗物。大酋长派遣费泽鲁尔的族人去调查阿塔哈卡神庙中发生的奇异事件，而当他们抵达时，发现神庙已经沉没了。",kw={"遗物","阿塔莱","费泽鲁尔","绿龙","泪水之池","斯通纳德","悲伤沼泽","阿塔哈卡神庙","大酋长"},sec={{t="沉没的神庙",b="阿塔莱巨魔是邪恶的施法者，这是一个因禁忌魔法而臭名昭著的部族。当费泽鲁尔一行人到达阿塔哈卡神庙时，他们惊讶地发现神庙已经沉没。绿龙现在正看守着那个地方，并自称是艾泽拉斯的守护者。"},{t="拼图的碎片",b="费泽鲁尔想要了解发生了什么事，他请求你在泪水之池周围搜寻阿塔莱遗物，希望能借此拼凑出事情的真相。没有人知道神庙里曾进行过什么黑暗仪式，只知道那里使用了强大的魔法力量。费泽鲁尔希望阿塔莱的咒语能对部落有所帮助，并想弄清楚巨魔们希望达到什么目的，以及究竟是什么出了可怕的差错。"}},faq={{q="谁是费泽鲁尔？",a="费泽鲁尔身处斯通纳德，他是大酋长派遣去调查阿塔哈卡神庙异常事件的人员之一。",al={"费泽鲁尔","谁发布泪水之池任务"}},{q="为什么部落对阿塔莱巨魔感兴趣？",a="费泽鲁尔指出那里曾使用了强大的魔法力量，并认为阿塔莱的咒语可能对部落有用。",al={"为什么部落想要阿塔莱","阿塔莱魔法部落"}},{q="阿塔莱遗物位于何处？",a="它们散落在神庙附近的泪水之池湖底。",al={"阿塔莱遗物位置","去哪里寻找遗物","泪水之池遗物"}},{q="现在是谁在守护这座沉没的神庙？",a="绿龙正在守护那里，并自称是艾泽拉斯的守护者。",al={"为什么绿龙在这里","阿塔哈卡神庙绿龙","悲伤沼泽绿龙"}},{q="交付遗物后接下来会发生什么？",a="接下来是“阿塔莱流放者”。",al={"泪水之池后续任务","泪水之池下一步","泪水之池之后做什么"}}},fp="13,217,17.253.0,18.423.0,17.114.0,50.126.0,40.58.0,33.77.0,50.26.0"}
P.entries["quest:1425"] = {n="运送货物",s="在“漂流木”之后，当马车正在修理时，卫兵比格斯还有最后一项工作要交给你。比格斯已经打包好从食人魔袭击中抢救出来的关键物资，并希望你把它们送到守望堡的军需官朗格尔斯那里。",h="在“漂流木”之后，当马车正在修理时，卫兵比格斯还有最后一项工作要交给你。比格斯已经打包好从食人魔袭击中抢救出来的关键物资，并希望你把它们送到守望堡的军需官朗格尔斯那里。",kw={"奥扎兰水晶","诅咒之地","黑暗之门","守望堡","军需官朗格尔斯","货物","悲伤沼泽","卫兵比格斯"},sec={{t="给比格斯的最后一次运送",b="当比格斯修理马车时，从食人魔袭击中抢救出来的关键物资已被打包好，供你运送到守望堡。这座堡垒矗立在诅咒之地的北山中，守望着黑暗之门。比格斯给出了路线：沿路向东走，在道路分叉处向南进入诅咒之地，然后在下一个岔路口向左转，并警告你要多加小心。"},{t="在守望堡",b="军需官朗格尔斯收到来自比格斯商队的包裹感到很惊讶，因为堡垒这边已经认为商队和比格斯失踪了。朗格尔斯感谢了你，并希望物资里有奥扎兰水晶，这是一种急需的试剂，堡垒的库存已经不多了。"}},faq={{q="是谁把货物送往守望堡的？",a="卫兵比格斯，他留下来修理马车，并打包了从食人魔袭击中抢救出来的关键物资。",al={"谁发布运送货物任务","运送货物任务发布者","卫兵比格斯的运送"}},{q="这批货物需要送到哪里？",a="它要送到诅咒之地北山中的守望堡，交给军需官朗格尔斯。",al={"守望堡在哪里","如何前往守望堡","军需官朗格尔斯的位置"}},{q="这个任务之前是什么？",a="紧接在“漂流木”之后。",al={"运送货物前置任务","运送货物之前的任务"}},{q="从沼泽去往堡垒的路线是什么？",a="沿路向东，在道路分叉处向南进入诅咒之地，然后在下一个岔路口向左转。",al={"前往守望堡的路线","前往诅咒之地的路径"}},{q="守望堡在守望着什么？",a="它在守望着黑暗之门。",al={"守望堡的目的","为什么守望堡在诅咒之地"}}},fp="20,232,25.377.0,14.263.1,38.99.0,36.92.0,41.21.0,44.117.0,39.36.0"}
P.entries["quest:1426"] = {n="海中的威胁",s="在托克卡尔把你引荐给卡塔尔之后，卡塔尔直言不讳地表达了对大海的厌恶。看到鱼人死在那些为部落效力的人手中，能让卡塔尔感到一丝快意。卡塔尔问你能杀掉多少，并想看看你是否敢去挑战它们当中最强大的存在。",h="在托克卡尔把你引荐给卡塔尔之后，卡塔尔直言不讳地表达了对大海的厌恶。看到鱼人死在那些为部落效力的人手中，能让卡塔尔感到一丝快意。卡塔尔问你能杀掉多少，并想看看你是否敢去挑战它们当中最强大的存在。",kw={"卡塔尔","沼泽食肉怪","沼泽墨浆怪","沼泽鱼人","鱼人","悲伤沼泽","来自大海的威胁"},sec={{t="对大海的积怨",b="卡塔尔对大海以及任何从海里爬出来的生物毫无感情，称大海是一位强大但盲目、冷酷而残忍的女主人。如果可能的话，卡塔尔乐于见到成百上千的鱼人被杀，看到它们倒在为部落效力的人手中，更是让卡塔尔感到一丝满足。身处悲伤沼泽的卡塔尔要求你去猎杀沼泽鱼人、沼泽墨浆怪和沼泽食肉怪。"},{t="卡塔尔的裁决",b="当你回来时，卡塔尔说大海看起来或许广阔无垠且冷酷无情，但它的子嗣现在也留下了你的血色印记。鱼人们现在尝到了痛苦，必须重整旗鼓，卡塔尔觉得这很好，每当有一个鱼人被消灭，卡塔尔都会露出微笑。卡塔尔欢迎你回来继续猎杀。"}},faq={{q="为什么卡塔尔想要消灭鱼人？",a="卡塔尔对大海以及其中的生物毫无爱意，很乐意看到成百上千的鱼人被杀。看到它们死在那些为部落效力的人手中，让卡塔尔感到一丝快意。",al={"为什么要杀鱼人","卡塔尔 鱼人","为什么仇恨大海"}},{q="这次狩猎发生在什么地方？",a="在悲伤沼泽，对象是沼泽鱼人、沼泽墨浆怪和沼泽食肉怪。",al={"沼泽鱼人在哪里","来自大海的威胁地点"}},{q="谁发起的这次狩猎？",a="卡塔尔，托克卡尔把你引荐给他在悲伤沼泽见面的那个人。",al={"谁发布来自大海的威胁","来自大海的威胁任务发布者"}},{q="在这次狩猎之前发生了什么？",a="这紧接在第一个“来自大海的威胁”任务之后，在那个任务中，托克卡尔把你引荐给了卡塔尔。",al={"来自大海的威胁前置要求","来自大海的威胁前序任务"}}},fp="19,288,24.401.0,15.279.1,42.185.0,32.85.0,20.67.0,28.88.0"}
P.entries["quest:1427"] = {n="海中的威胁",s="在你为卡塔尔工作之后，有人告诉你去休息之前再见一次托克卡尔。卡塔尔相信托克卡尔在你离开期间打造了几件武器，并会因为你的帮助而赠予你一件。",h="在你为卡塔尔工作之后，有人告诉你去休息之前再见一次托克卡尔。卡塔尔相信托克卡尔在你离开期间打造了几件武器，并会因为你的帮助而赠予你一件。",kw={"卡塔尔","鱼人","锯齿肉","悲伤沼泽","来自大海的威胁","托克卡尔"},sec={{t="回到托克卡尔身边",b="卡塔尔认为托克卡尔在你离开期间打造了几件武器，并且会因为你的帮助而赠予你一件。卡塔尔补充说，如果你准备好了，最好在鱼人身上试试武器的威力，尽管这只是为了让卡塔尔更开心。"},{t="托克卡尔的谢意",b="托克卡尔很高兴见到你回来，并说为了对抗鱼人，他又打造了一些武器。作为你带来新鲜锯齿肉的感谢，也是为了让卡塔尔露出一丝微笑，他送给了你一件。"}},faq={{q="是谁让你去和托克卡尔谈谈的？",a="是卡塔尔，他让你在悲伤沼泽休息之前再见一次托克卡尔。",al={"谁发布了这个任务","我在哪里接到来自大海的威胁","谁开启了这个任务"}},{q="为什么托克卡尔要赠予武器？",a="卡塔尔相信托克卡尔在你离开期间打造了几件武器，并会因为你的帮助而赠予你一件作为感谢。",al={"为什么托克卡尔会给武器","托克卡尔打造了什么","托克卡尔奖励的原因"}},{q="和托克卡尔谈完后接下来做什么？",a="接下来是“持续的威胁”。",al={"下一个任务是什么","之后去哪里","来自大海的威胁之后是什么"}}},fp="19,199,15.236.0,16.208.1,36.89.0,33.127.0,44.25.0"}
P.entries["quest:1428"] = {n="海中的威胁",s="卡塔尔很高兴看到你对鱼人的仇恨与日俱增，并派你前往悲伤沼泽的海岸去猎杀更多的鱼人。",h="卡塔尔很高兴看到你对鱼人的仇恨与日俱增，并派你前往悲伤沼泽的海岸去猎杀更多的鱼人。",kw={"持续的威胁","鱼人","卡塔尔","沼泽食肉鱼人","沼泽喷墨鱼人","沼泽神谕者","悲伤沼泽"},sec={{t="沿着海滩继续前进",b="卡塔尔让你沿着海滩寻找更多的鱼人，当你杀得尽兴后再回来复命。目标是沼泽喷墨鱼人、沼泽食肉鱼人和沼泽神谕者。在海洋和她的每一个孩子，尤其是那些令人作呕的鱼人被肃清之前，卡塔尔绝不会感到快慰。"}},faq={{q="谁发布了这个任务？",a="悲伤沼泽的卡塔尔。",al={"谁发布了持续的威胁","持续的威胁任务发布者","悲伤沼泽的卡塔尔"}},{q="需要猎杀哪些生物？",a="卡塔尔想要你猎杀海滩沿岸的沼泽喷墨鱼人、沼泽食肉鱼人和沼泽神谕者。",al={"持续的威胁击杀目标","持续的威胁目标","哪些鱼人"}},{q="为什么卡塔尔要屠杀鱼人？",a="在海洋和她的族群被肃清之前，卡塔尔绝不会感到快慰，尤其是那些鱼人。",al={"为什么要杀鱼人","卡塔尔的动机","为什么要憎恨鱼人"}},{q="这一步之前发生了什么？",a="这是继之前的“来自海洋的威胁”之后的后续任务，在那之后托克卡尔奖励了你一件武器。",al={"持续的威胁前置任务","持续的威胁之前的任务"}}},fp="16,160,20.310.0,21.31.0,33.82.0,39.95.0,27.86.0"}
P.entries["quest:1429"] = {n="阿塔莱流放者",s="当你在泪水之池时，费泽鲁尔的一名侦察兵带回了一张用鲜血写在干枯皮肉上的卷轴。费泽鲁尔现在将你收集到的神器打包，并派你前往遥远的北方，去辛特兰寻找一位被流放的阿塔莱祭司。",h="当你在泪水之池时，费泽鲁尔的一名侦察兵带回了一张用鲜血写在干枯皮肉上的卷轴。费泽鲁尔现在将你收集到的神器打包，并派你前往遥远的北方，去辛特兰寻找一位被流放的阿塔莱祭司。",kw={"阿塔莱流放者","费泽鲁尔","哈卡","辛特兰","迦玛兰","泪水之池","沙德拉洛","悲伤沼泽","枯木巨魔"},sec={{t="血之判决",b="卷轴的内容是对一位阿塔莱祭司的司法判决，这在他的族人中比死亡还可怕。他被流放到遥远的北方辛特兰，生活在枯木巨魔中间。费泽鲁尔将这些神器打包，并派你去寻找这位流放者，查明它们的真实用途，然后返回。"},{t="流放者的话",b="在看过包裹后，流放者指出这些神器是阿塔莱的召唤工具。他评论说，血之密室的信徒们正在预言者迦玛兰的带领下走向他们选择的命运，并疑惑哈卡是否已经回到了神庙。"}},faq={{q="谁派你去寻找阿塔莱流放者？",a="位于斯通纳德的费泽鲁尔，他将你收集的神器打包，并派你前往北方的辛特兰。",al={"谁给予阿塔莱流放者任务","阿塔莱流放者任务发布者","谁开启此任务"}},{q="阿塔莱流放者在哪里？",a="在辛特兰，生活在沙德拉洛神庙的枯木巨魔中间。",al={"流放者在哪里","阿塔莱流放者位置","去哪里寻找阿塔莱流放者"}},{q="这位祭司受到了什么判决？",a="一张用鲜血写在干枯皮肉上的卷轴判处这位祭司一种在阿塔莱人看来比死亡还可怕的命运：流放到辛特兰的枯木巨魔中间。",al={"他为何被流放","判决是什么","阿塔莱流放者背景故事"}},{q="你带给流放者什么东西？",a="一捆在泪水之池收集的阿塔莱神器，费泽鲁尔希望流放者能揭示它们的真实用途。",al={"你带来了什么包裹","神器是什么","阿塔莱神器用途"}},{q="这次旅程之前直接关联的是什么任务？",a="接续在“泪水之池”任务之后，在该任务中，费泽鲁尔让你收集了阿塔莱神器。",al={"前置任务","先决条件","什么导致了阿塔莱流放者任务"}}},fp="17,242,19.310.0,17.256.1,40.100.0,35.83.0,39.158.0,35.116.0,40.75.0"}
P.entries["quest:143"] = {n="送往西部荒野的信",s="“前往西部荒野的信使”是一个联盟任务，需要将所罗门镇长从赤脊山发出的紧急求援信跨过艾尔文森林送到西部荒野。由于暴风城军队彻底放弃了湖畔镇，当地的领导层寻求格里安·斯托曼新组建的人民民兵部队提供互助。",h="“前往西部荒野的信使”是一个联盟任务，需要将所罗门镇长从赤脊山发出的紧急求援信跨过艾尔文森林送到西部荒野。由于暴风城军队彻底放弃了湖畔镇，当地的领导层寻求格里安·斯托曼新组建的人民民兵部队提供互助。",kw={"格里安·斯托曼","湖畔镇","所罗门镇长","人民民兵","赤脊山","哨兵岭","所罗门的求援","西部荒野"},ang={["faction:Alliance"]="这封急件突显了暴风王国中央防御体系的彻底崩溃，迫使边境城镇不得不商定私下的共同防御协议。",["race:Human"]="这封信揭示了赤脊山和西部荒野的人类定居者共同的困境，当首都无所作为时，他们只能依靠志愿者和雇佣兵。"},sec={{t="一份绝望的请求",b="所罗门镇长发现湖畔镇处于绝境之中。赤脊山正受到黑石兽人和豺狼人的围攻，但暴风城军队却迟迟未能派出援军。所罗门意识到单靠镇卫队和非正规军无法保住湖畔镇，于是写下了一份正式的求援信。由于始终不见正规皇家预备役的踪影，他将目光转向了西方，听说艾尔文森林外正在组建一支市民防御部队。"},{t="跨越边境的求援",b="这封急件的收件人是格里安·斯托曼，一位老练的指挥官，他已经开始在人民民兵的旗帜下集结志愿者战士。通过直接派遣信使横穿王国，所罗门希望西部荒野的组织志愿者能腾出兵力来增援湖畔镇的边境，直到王国的军队最终集结完毕。然而，信使很快就会发现，西部荒野正深陷于与迪菲亚潜行者之间灾难性的斗争中。"}},faq={{q="为什么所罗门镇长要向西部荒野求助？",a="暴风城未能派出湖畔镇对抗兽人和豺狼人所急需的军事增援。在听到西部荒野有武装市民力量集结的消息后，所罗门希望格里安·斯托曼能腾出兵力来增援赤脊山。",al={"为什么是西部荒野","所罗门的求援","为什么要找格里安"}},{q="格里安·斯托曼是谁？",a="格里安·斯托曼是一位驻扎在西部荒野哨兵岭的退伍老兵。在缺乏王权和保护的情况下，他组织并领导了人民民兵，保护当地农场免受强盗和迪菲亚潜行者的侵扰。",al={"格里安是谁","斯托曼的职责","谁在领导西部荒野"}},{q="这位信使的旅程终点在哪里？",a="这封信必须从湖畔镇的镇政厅出发，一路向西穿过赤脊山和艾尔文森林，最终抵达西部荒野中央的哨兵岭。",al={"我该送到哪里","斯托曼在哪里","从赤脊山到西部荒野"}},{q="为什么暴风城军队没有解救湖畔镇？",a="所罗门镇长注意到军队那边有些蹊跷，因为承诺的援军始终没有出现。由于国王不在，而伯瓦尔·弗塔根公爵正在摄政，预期的预备役部队从未到来，使得边远地区只能自生自灭。",al={"为什么没有暴风城军队","皇家卫队在哪里","暴风城军队去哪了"}},{q="西部荒野真的能腾出兵力去赤脊山吗？",a="不能。当你抵达哨兵岭时，你会发现西部荒野在迪菲亚潜行者的重压下几乎无法支撑。人民民兵根本没有多余的兵力，还在为保卫自己的边界而挣扎。",al={"西部荒野会帮忙吗","民兵会来吗","格里安能帮忙吗"}},{q="送信之后会发生什么？",a="格里安·斯托曼收到信后，立即起草了一份回复，解释了西部荒野的严峻局势，并让你带着给所罗门镇长的回信踏上返程。",al={"接下来做什么","后续任务","完成“前往西部荒野的信使”之后"}}},fp="21,198,18.367.0,23.332.0,51.217.0,25.222.0,37.125.0,49.253.0,52.187.1,39.154.1"}
P.entries["quest:1430"] = {n="新鲜的螃蟹腿",s="在悲伤沼泽，达尔说奥格瑞玛的顾客对爬行者肉的需求量很大，尤其是巨型爬行者的肉。达尔让你从海岸带回一些它们的腿。",h="在悲伤沼泽，达尔说奥格瑞玛的顾客对爬行者肉的需求量很大，尤其是巨型爬行者的肉。达尔让你从海岸带回一些它们的腿。",kw={"爬行者腿","达尔","鲜肉","巨型爬行者","奥格瑞玛","悲伤沼泽"},sec={{t="运往奥格瑞玛的爬行者腿",b="达尔的顾客非常喜欢鲜嫩的爬行者肉，尤其是那种巨型爬行者身上的。达尔承诺，如果你能带回一些腿运往奥格瑞玛，这趟海岸之行绝对值得。海岸就在东边，那些生物在海滩上和浪花里四处爬行。成功后有一桶酒作为奖励，达尔打算在货物运走之前先尝尝鲜。"},{t="路上的美味",b="达尔对这些腿感到很满意，想象着它们在明火上烤得恰到好处的样子。达尔力劝你在旅途中带上一份熟肉尝尝，并保证这绝对是真正的美味。"}},faq={{q="在悲伤沼泽里，谁想要爬行者肉？",a="达尔，他在奥格瑞玛的顾客对这种肉有很高的需求。",al={"谁发布鲜肉任务","达尔任务","达尔是谁"}},{q="巨型爬行者在哪里？",a="在东边的海岸上，它们在海滩和海浪中四处爬行。",al={"爬行者位置","爬行者在哪里","巨型爬行者海岸"}},{q="达尔为什么需要这些特定的腿？",a="达尔的顾客喜欢爬行者肉，尤其是巨型爬行者的肉，这些腿是要运回奥格瑞玛的。",al={"为什么需要爬行者肉","肉是用来做什么的","奥格瑞玛爬行者肉"}}},fp="10,198,26.401.0,20.174.1,47.60.0,41.71.0,38.130.0"}
P.entries["quest:1431"] = {n="联盟关系",s="“联盟关系”是奥格瑞玛的克拉文·德洛克提供的一个入门任务。它引导经验丰富的部落冒险者去寻找科尔丹，一位在城市西出口附近静默行事的神秘人物。该任务开启了一段关于幕后外交与情报工作的对话，这些工作对于维持萨尔与联盟之间脆弱的和平至关重要。",h="“联盟关系”是奥格瑞玛的克拉文·德洛克提供的一个入门任务。它引导经验丰富的部落冒险者去寻找科尔丹，一位在城市西出口附近静默行事的神秘人物。该任务开启了一段关于幕后外交与情报工作的对话，这些工作对于维持萨尔与联盟之间脆弱的...",kw={"联盟关系","克拉文·德洛克","外交","部落","科尔丹","奥格瑞玛","萨尔"},ang={["class:Rogue"]="科尔丹对隐秘和表象的关注，使得他的任务特别适合那些行走于阴影之中的人。",["faction:Horde"]="这项任务突显了部落内部在传统蛮力与萨尔那微妙的外交治国之道之间的意识形态对比。",["race:Orc"]="对于习惯于用斧头解决冲突的兽人来说，科尔丹的方法要求一种陌生的纪律：耐心与战术上的细腻。"},sec={{t="外交困境",b="虽然许多兽人推崇蛮力和直截了当的征服，但萨尔大酋长明白，与联盟无休止的战争会摧毁他年轻的国家。萨尔在人类的囚禁中长大，深谙人类治国之道和军事战略的微妙之处。克拉文·德洛克会留意那些可能具备耐心、能以更微妙方式处理问题的战士和勇士，并引导他们超越单纯的武力。"},{t="科尔丹的棚屋",b="在奥格瑞玛的西门附近，坐落着科尔丹简陋的居所，他是一位精通魔法与隐秘技艺的实践者。与力量谷中那些喧闹饮酒的战士不同，科尔丹更看重表象、洞察力与治国之道。他正在寻找能够代表大酋长行事谨慎的特工，以应对部落与其宿敌之间紧张的对峙局面。"}},faq={{q="谁发布了“联盟关系”任务？",a="克拉文·德洛克在奥格瑞玛向达到三十级的部落冒险者提供此任务。",al={"任务给予者 联盟关系","谁开启联盟关系","在哪里接联盟关系"}},{q="我在哪里可以找到科尔丹？",a="科尔丹住在奥格瑞玛西出口附近的一个小棚屋里，远离熙熙攘攘的市中心。",al={"科尔丹位置","科尔丹在哪里","科尔丹 奥格瑞玛"}},{q="科尔丹在奥格瑞玛扮演什么角色？",a="科尔丹是一位魔法和神秘学学者，协助萨尔大酋长处理审慎事务，特别是那些涉及外交、情报以及部落公众形象的事宜。",al={"谁是科尔丹","科尔丹背景故事"}},{q="为什么萨尔关心与联盟的外交关系？",a="萨尔是在人类社会中长大的，非常了解他们的政治和军事力量。他知道公开的战争可能会毁灭他初生的民族，因此他选择审慎和有节制的外交手段来保护部落的未来。",al={"萨尔 外交","为什么部落要与联盟和平","萨尔与人类"}},{q="这个任务会引出后续任务吗？",a="是的，将此任务交付给科尔丹将开启关于部落与其他阵营关系的深入对话，并直接引导至后续处理区域外交和间谍活动的任务。",al={"联盟关系后续","联盟关系之后是什么"}},{q="为什么这项任务如此强调谨慎？",a="与联盟的公开冲突有导致重大伤亡并破坏卡利姆多局势的风险。萨尔依靠隐秘的特工在敏感的外交摩擦演变成公开战争之前将其化解。",al={"为什么需要隐秘","科尔丹的谨慎"}}},fp="18,251,20.265.0,15.271.0,39.117.0,25.90.0,36.148.0,55.210.0,41.172.0,45.189.0"}
P.entries["quest:1432"] = {n="联盟关系",s="“联盟关系”是一项由奥格瑞玛派往凄凉之地的部落任务，旨在防止危险的政治后果。随着联盟深入卡利姆多中部，部落采取主动行动清除该地区的燃烧军团势力，以免对手指责萨尔的子民再次受到恶魔腐蚀。",h="“联盟关系”是一项由奥格瑞玛派往凄凉之地的部落任务，旨在防止危险的政治后果。随着联盟深入卡利姆多中部，部落采取主动行动清除该地区的燃烧军团势力，以免对手指责萨尔的子民再次受到恶魔腐蚀。",kw={"联盟关系","燃烧军团","焦炭谷","凄凉之地","幽灵岗哨","科尔丹","科多兽坟场","塔卡塔·钢刃"},ang={["class:Warlock"]="虽然像塔卡塔·钢刃这样的普通士兵对黑暗力量持怀疑态度，但针对野生恶魔的行动经常与部落对术士修行者的务实使用产生交集。",["faction:Horde"]="这项任务反映了酋长萨尔为使新部落合法化，并埋葬恶魔奴役的遗产，以免被敌对邻居利用而进行的持续斗争。",["race:Orc"]="对于努力践行萨尔救赎愿景的兽人来说，卡利姆多任何残留的恶魔污秽迹象都是对他们来之不易的自由的痛苦威胁。"},sec={{t="观念问题",b="随着联盟的侦察兵和探险队深入卡利姆多，部落领导层面临着微妙的外交威胁。分散在卡利姆多中部的恶魔残党有可能会证实那些老旧的偏见，即兽人及其盟友依然与燃烧军团勾结。在酋长萨尔的许可下，奥格瑞玛的科尔丹负责监督各项针对性行动，确保在敌对的联盟势力将其存在曲解为战争借口之前，彻底清除这些恶魔残党。"},{t="荒野中的岗哨",b="执行向南的命令需要穿过石爪山脉的焦炭谷，一直进入凄凉之地的荒凉旷野。在那里，就在巨大的科多兽坟场以北，坐落着幽灵岗哨。像塔卡塔·钢刃这样的部落特工监视着这片荒芜的野外，既要应对猖獗的半人马部族，又要面对威胁要吞没该地区的普遍恶魔腐蚀。"},{t="务实的联盟",b="塔卡塔·钢刃以冷峻的务实态度对待这项任务。尽管消灭当地的恶魔不可避免地减轻了凶残的本土半人马部族的压力，甚至为部落的术士提供了帮助，但职责依然是第一位的。消除燃烧军团的立足点是为了部落的整体安全，无论还有谁能从这次清理中获益。"}},faq={{q="为什么部落在这里担心联盟？",a="随着联盟军队在卡利姆多推进，部落领导层担心活跃的恶魔感染可能会被用作证明部落依然与燃烧军团勾结的证据。通过积极清除当地的恶魔，部落试图瓦解这些指控。",al={"为什么要担心联盟","部落与联盟在凄凉之地的关系","联盟的指控"}},{q="科尔丹是谁？",a="科尔丹是一名常驻奥格瑞玛的部落特工，他在酋长的批准下负责监督专项任务，专注于消除危及部落地位的恶魔因素。",al={"科尔丹","科尔丹是谁","科尔丹 奥格瑞玛"}},{q="幽灵岗哨位于何处？",a="幽灵岗哨是位于凄凉之地中部的一处营地，坐落在石爪山脉焦炭谷山口的正南方，科多兽坟场的正北方。",al={"幽灵岗哨的位置","塔卡塔·钢刃在哪里","寻找幽灵岗哨"}},{q="塔卡塔·钢刃是谁？",a="塔卡塔·钢刃是一名驻扎在凄凉之地幽灵岗哨的部落士兵，受命代表酋长抑制恶魔和敌对半人马等区域性威胁。",al={"塔卡塔·钢刃","钢刃是谁","钢刃 凄凉之地"}},{q="为什么塔卡塔会提到援助半人马？",a="半人马宣称凄凉之地是他们的领土，但却缺乏遏制日益增长的恶魔威胁的力量。通过清理当地的恶魔，部落无意中帮助半人马得以生存，这是一个塔卡塔纯粹为了部落更宏大的安全利益而接受的妥协。",al={"援助半人马","半人马 凄凉之地","为什么要援助半人马"}},{q="术士与这项任务有何关联？",a="虽然这项任务旨在根除野生恶魔，但塔卡塔略带厌恶地指出，清除恶魔试剂和影响不可避免地会与部落内部活动的争议性术士产生交集并为他们提供帮助。",al={"术士的关联","为什么要帮助术士","部落中的术士"}}},fp="18,228,22.382.0,21.298.0,19.298.1,51.210.0,15.147.0,35.158.0,25.172.0,43.195.0,38.139.0"}
P.entries["quest:1437"] = {n="瓦拉里尔的搜寻",s="瓦拉里尔·屠魔者来到凄凉之地，想要查明失踪的玛雷姆家族的两名贵族——一个达纳苏斯商人家庭的成员——的下落。他们的父亲担心最坏的情况发生，而且据最后的消息，这两人几周前曾出现在石爪山脉。瓦拉里尔请求你找到他们的马车。",h="瓦拉里尔·屠魔者来到凄凉之地，想要查明失踪的玛雷姆家族的两名贵族——一个达纳苏斯商人家庭的成员——的下落。他们的父亲担心最坏的情况发生，而且据最后的消息，这两人几周前曾出现在石爪山脉。瓦拉里尔请求你找到他们的马车。",kw={"箱子","黛琳达","达纳苏斯","凄凉之地","玛雷姆","石爪","泰拉尼斯","瓦拉里尔"},sec={{t="两名失踪的贵族",b="瓦拉里尔·屠魔者正在寻找泰拉尼斯和黛琳达·玛雷姆，他们的父亲担心最坏的情况发生，并已委托瓦拉里尔竭尽全力寻找他们。搜寻工作才刚刚开始，瓦拉里尔希望这不会让他们在凄凉之地耽搁太久。据最后的消息，这两人几周前曾穿过石爪山脉。瓦拉里尔请求你在凄凉之地找到他们的马车，一旦找到就立刻通知他。那里只剩下马车烧焦的残骸，还有一个箱子混在其中。"},{t="残骸之中",b="翻找着残骸，你可以看出这辆马车既遭到了法术攻击，也受到了武器的破坏。战斗看起来很短暂且呈一边倒之势，现场没有血迹，也没有留下尸体。袭击者手法高效且迅速。"}},faq={{q="瓦拉里尔在找谁？",a="泰拉尼斯和黛琳达·玛雷姆，玛雷姆家族的两名贵族，属于一个达纳苏斯商人家庭。",al={"谁失踪了","那些贵族是谁","玛雷姆家族失踪的孩子"}},{q="这对兄妹最后的消息是从哪里传来的？",a="据最后的消息，在瓦拉里尔与你交谈前的几周，他们曾穿过石爪山脉。",al={"玛雷姆兄妹最后一次露面","他们去了哪里","马车路线"}},{q="瓦拉里尔为什么要寻找他们？",a="他们的父亲担心最坏的情况发生，而瓦拉里尔受托要尽一切可能找到他失踪的孩子们。",al={"谁雇佣了瓦拉里尔","谁想要找到这对兄妹"}},{q="瓦拉里尔想让你找什么？",a="泰拉尼斯和黛琳达·玛雷姆在凄凉之地的马车。如果你找到了，瓦拉里尔要求你立刻通知他。",al={"瓦拉里尔的搜寻是如何开始的","第一步是什么"}}},fp="19,290,18.474.0,18.217.1,30.83.0,40.100.0,28.122.0,38.104.0"}
P.entries["quest:1438"] = {n="瓦拉里尔的搜寻",s="在瓦拉里尔·屠魔者的搜寻任务的第二部分结束后，瓦拉里尔·屠魔者会派你去雷斧堡垒寻找黛琳达和泰拉尼斯·玛雷姆。关于此事的报告被送到了达纳苏斯的瓦拉里尔的上级那里，他们对泰拉尼斯的动机感到担忧，并将黛琳达的安全归来视为重中之重。",h="在瓦拉里尔·屠魔者的搜寻任务的第二部分结束后，瓦拉里尔·屠魔者会派你去雷斧堡垒寻找黛琳达和泰拉尼斯·玛雷姆。关于此事的报告被送到了达纳苏斯的瓦拉里尔的上级那里，他们对泰拉尼斯的动机感到担忧，并将黛琳达的安全归来视为重中之...",kw={"火刃氏族","黛琳达","达纳苏斯","屠魔者","凄凉之地","玛雷姆","雷斧堡垒","泰拉尼斯","瓦拉里尔"},sec={{t="堡垒中的搜寻",b="瓦拉里尔·屠魔者希望你去寻找黛琳达和泰拉尼斯，从堡垒开始，并将你了解到的信息带回。瓦拉里尔会立即联系达纳苏斯的上级。私下里，他们担心泰拉尼斯为何来到凄凉之地，他们最关心的是黛琳达能否平安回家。至于泰拉尼斯，他们希望在让他回家之前先对他进行评估。"},{t="俘虏的自述",b="在面对入口的大型建筑中找到的黛琳达表示，火刃氏族抓住了她和泰拉尼斯并将他们带到了这里，她相信自己将被献祭给他们的恶魔主人。她说这次旅程从一开始就是一个错误。泰拉尼斯违背了他族人的意愿，对奥术知识产生了贪念，尽管有关于这里有恶魔的警告，他还是出发了。她很担心他的遭遇。"}},faq={{q="黛琳达·玛雷姆在哪里？",a="在凄凉之地的雷斧堡垒区域，位于面对入口的那栋大型建筑内。",al={"黛琳达·玛雷姆位置","哪里寻找黛琳达","在凄凉之地寻找黛琳达"}},{q="是谁派你去寻找黛琳达和泰拉尼斯的？",a="瓦拉里尔·屠魔者请你尽可能找到他们两人，从堡垒开始，同时瓦拉里尔会将情况告知达纳苏斯的上级。",al={"谁提供瓦拉里尔的搜寻任务","任务发布者瓦拉里尔","瓦拉里尔·屠魔者任务"}},{q="为什么达纳苏斯比泰拉尼斯更关心黛琳达？",a="瓦拉里尔的上级怀疑泰拉尼斯来到凄凉之地的动机，他们认为黛琳达的平安归来最为重要。",al={"为什么泰拉尼斯受到怀疑","泰拉尼斯的动机","为何优先考虑黛琳达"}},{q="在这部分搜寻任务之前发生了什么？",a="它是紧随瓦拉里尔·屠魔者的搜寻任务的第二部分之后进行的。",al={"前置任务","瓦拉里尔的前置条件","瓦拉里尔的搜寻任务线"}}},fp="19,280,24.374.0,19.390.1,23.92.0,46.132.0,56.118.0,41.50.0"}
P.entries["quest:1439"] = {n="寻找泰拉尼斯",s="黛琳达·玛雷姆告诉你，兽人屠杀了他们所有的守卫和仆从，然后将她和泰兰尼斯带到了这里。泰兰尼斯试图与他们交谈，在得知她兄弟的命运之前，她是不会离开的。她请求你去找到他，并在了解他的命运后再回来。",h="黛琳达·玛雷姆告诉你，兽人屠杀了他们所有的守卫和仆从，然后将她和泰兰尼斯带到了这里。泰兰尼斯试图与他们交谈，在得知她兄弟的命运之前，她是不会离开的。她请求你去找到他，并在了解他的命运后再回来。",kw={"火刃氏族","黛琳达","凄凉之地","玛雷姆","吊坠","雷斧堡垒","泰兰尼斯","瓦拉瑞尔"},sec={{t="被俘的兄弟",b="黛琳达告诉你，兽人在将她和泰兰尼斯拖到这个地方之前，杀死了他们所有的守卫和仆从。她本以为自己会立刻没命，但显然兽人另有打算。泰兰尼斯曾试图与他们交谈，也许是希望他的奥术知识能打动他们，尽管她也说不清原因。在得知他的命运之前，她是不会逃走的，所以她请求你去找到他，并在确认后回来。他就在堡垒入口左侧的一栋建筑里。"},{t="黛琳达的恐惧",b="黛琳达担心泰兰尼斯如果放任自流，会去探寻火刃氏族的秘密并成为他们的一员。力量一直吸引着他，正如魔法诱惑着任何其他人一样。对她的人民来说，研究这些东西本身就是严重的罪行，她怀疑自己是否还能面对家人，并告诉他们泰兰尼斯的灵魂曾玩弄过那样的危险。"},{t="黛琳达的获知",b="当你回来时，黛琳达说这很可怕，但却是必要的。如果不是你亲手终结，她族人也会这么做。如果她的感谢听起来很空洞，她请求你的原谅。既然知道了他的命运，她已经准备好逃离，如果你还愿意帮忙，她会接受你的帮助。"}},faq={{q="泰兰尼斯·玛雷姆是谁？",a="黛琳达的兄弟。他曾与俘虏他们的人交谈，或许是希望用奥术知识打动他们，她说魔法的力量一直吸引着他。",al={"泰兰尼斯是谁","泰兰尼斯背景故事","泰兰尼斯·玛雷姆"}},{q="为什么黛琳达拒绝离开？",a="在得知她兄弟的命运之前，她是不会离开的。她请求你去找到他，并在确认后回来接她。",al={"为什么黛琳达不愿离开","为什么黛琳达留下","为什么要等逃跑"}},{q="守卫和仆从发生了什么事？",a="兽人杀死了他们所有人，然后留下了黛琳达和泰兰尼斯的活口，显然有别的计划。",al={"他们的守卫发生了什么","谁被杀了","守卫和仆从"}},{q="泰兰尼斯在哪里？",a="在凄凉之地的雷斧堡垒，从入口进去，左侧的建筑里。",al={"泰兰尼斯在哪","泰兰尼斯位置"}},{q="这一步之前发生了什么？",a="这紧接在瓦拉瑞尔的搜寻第三部分之后，瓦拉瑞尔派你去寻找黛琳达。",al={"此任务之前是什么任务","任务进程","瓦拉瑞尔任务线"}}},fp="18,276,15.446.0,14.312.0,19.257.1,21.152.0,37.139.0,41.93.0,17.78.0,27.92.0"}
P.entries["quest:144"] = {n="送往西部荒野的信",s="“前往西部荒野的信使”是一项外交差事，将格里安·斯托曼从哨兵岭发出的严肃回复送回给湖畔镇的所罗门镇长。赤脊山当地威胁不断，所罗门镇长曾向人民民兵寻求军事增援，却得知西部荒野也同样被王室遗弃。",h="“前往西部荒野的信使”是一项外交差事，将格里安·斯托曼从哨兵岭发出的严肃回复送回给湖畔镇的所罗门镇长。赤脊山当地威胁不断，所罗门镇长曾向人民民兵寻求军事增援，却得知西部荒野也同样被王室遗弃。",kw={"格里安·斯托曼","湖畔镇","所罗门镇长","前往西部荒野的信使","人民民兵","赤脊山","哨兵岭","西部荒野"},ang={["faction:Alliance"]="这段通信揭露了Stormwind Keep的统治者与边远省份之间的深刻裂痕，表明西部荒野和赤脊山完全被置之不理。",["race:Human"]="对于人类旅行者来说，传递这条消息突显了边境城镇的悲惨孤立，平民和老兵在血战坚守的领土，却是暴风城的贵族们拒绝保护的地方。"},sec={{t="跨越动荡边境的请求",b="湖畔镇的所罗门镇长发现自己在没有暴风城皇家驻军支持的情况下，正面临赤脊山日益严峻的危机。他看向王国的南部地区寻找盟友，并联系了西部荒野人民民兵的指挥官格里安·斯托曼。所罗门希望这支守卫哨兵岭的有组织的志愿者部队能拨出兵力来加强湖畔镇的防御，却不知道西部荒野的平原上正笼罩着多么严峻的现实。"},{t="苦涩的拒绝",b="格里安·斯托曼的回应是一个明确而沉重的拒绝。西部荒野正被自身对抗迪菲亚潜行者和四处劫掠的豺狼人的绝望战争所吞噬，这场斗争之所以必要，仅仅是因为贵族议会和王室遗弃了这个粮仓。斯托曼明确表示，人民民兵的存在纯粹是为了生存；他们每天都在损失优秀的战士，无法抽调哪怕一名士兵去拯救赤脊山。"},{t="分裂的王国疆域",b="将斯托曼的回复带回湖畔镇，粉碎了所罗门镇长的幻想。镇长意识到王国的边境领地有着同样的遭遇：当地镇长和民兵组织只能自生自灭，而暴风城军队却莫名其妙地按兵不动。这种失望驱使所罗门将目光投向南方，试图向暮色森林的夜色镇求援。"}},faq={{q="所罗门镇长为何向西部荒野求援？",a="所罗门镇长在没有暴风城军队支持的情况下，在湖畔镇面临着日益严重的威胁。他知道格里安·斯托曼组织了人民民兵来保卫西部荒野，因此希望这支边境力量有余力能为赤脊山提供军事援助。",al={"为什么向西部荒野求援","所罗门致斯托曼的信","为什么需要西部荒野民兵"}},{q="格里安·斯托曼为何拒绝派遣援助？",a="人民民兵在对抗迪菲亚潜行者和保卫西部荒野农场的战斗中，兵力已经捉襟见肘。斯托曼解释说，如果暴风城没有抛弃西部荒野，民兵组织甚至根本不需要存在，他们已经没有多余的士兵了。",al={"为什么斯托曼拒绝","民兵拒绝湖畔镇","斯托曼的回复"}},{q="在这些危机期间，暴风城军队在哪里？",a="信中无人知晓。所罗门只能纳闷到底是什么行动如此重要，以至于将暴风城军队从其人民身边调走。他和斯托曼都对首都将边远省份置于不顾的行为感到困惑和愤慨。",al={"为什么暴风城不提供援助","军队在哪里","暴风城的遗弃"}},{q="将斯托曼的信送还给所罗门后会发生什么？",a="意识到西部荒野无法提供帮助后，所罗门镇长将注意力转向了暮色森林，派信使前往夜色镇，希望艾罗·埃伯洛克镇长的守夜人能够提供援助。",al={"前往西部荒野的信使后续任务","所罗门下一步的行动"}},{q="什么是人民民兵？",a="人民民兵是由格里安·斯托曼组织并以哨兵岭为基地的志愿军。它由当地农民、退伍军人和居民组成，在王室军队完全缺席的情况下，保卫着西部荒野免受不法之徒和豺狼人的侵害。",al={"人民民兵是谁","西部荒野民兵"}},{q="格里安·斯托曼是谁？",a="格里安·斯托曼是一位接管了西部荒野防务的退伍军人。他以哨兵岭的塔楼为指挥所，召集志愿者并协调对抗迪菲亚潜行者的战争。",al={"格里安·斯托曼背景故事","斯托曼是谁"}}},fp="21,189,32.385.0,16.367.0,30.323.1,49.224.0,46.202.0,48.149.0,61.161.1,29.201.0,25.177.0"}
P.entries["quest:1440"] = {n="回复瓦拉里尔",s="黛琳达·玛雷姆准备离开雷斧堡垒了。她感谢你为她和她的家人所做的一切，并表示动身的时间由你来决定。你护送她离开，然后去寻找瓦拉里尔·屠魔者。",h="黛琳达·玛雷姆准备离开雷斧堡垒了。她感谢你为她和她的家人所做的一切，并表示动身的时间由你来决定。你护送她离开，然后去寻找瓦拉里尔·屠魔者。",kw={"黛琳达·玛雷姆","达纳苏斯","凄凉之地","护送","尼耶尔前哨站","雷斧堡垒","泰拉尼斯","瓦拉里尔"},sec={{t="离开堡垒",b="黛琳达询问是否到了离开的时候，并为如果事情进展不如预期而你为她和她家人所做的一切表示感谢。如果你准备好了，这里便没有什么能留住她了，只要你觉得时机合适，她就会动身。你将她护送出雷斧堡垒，然后在凄凉之地找到瓦拉里尔·屠魔者。"},{t="来自瓦拉里尔的消息",b="瓦拉里尔向你致谢。黛琳达抵达尼耶尔前哨站时的状态比瓦拉里尔所能期望的要好得多，而且她靠自己的力量到达那里是一个好兆头。没有见到兄妹二人同时归来让瓦拉里尔感到痛苦，但泰拉尼斯的选择所带来的尴尬，只能由她在回到达纳苏斯后独自承受了。"}},faq={{q="是谁让你护送她的？",a="黛琳达·玛雷姆，只要你觉得时机合适，她就准备离开雷斧堡垒。",al={"谁给予返回瓦拉里尔","任务发布者返回瓦拉里尔","黛琳达·玛雷姆是谁"}},{q="任务在哪里开始？",a="在凄凉之地的雷斧堡垒，黛琳达就在那里。",al={"黛琳达·玛雷姆位置","黛琳达·玛雷姆在哪里","返回瓦拉里尔在哪里开始"}},{q="把黛琳达送出去后你该去找谁？",a="位于凄凉之地的瓦拉里尔·屠魔者。",al={"哪里提交返回瓦拉里尔","谁完成返回瓦拉里尔","返回瓦拉里尔结束"}},{q="在此步骤之前发生了什么？",a="这是“寻找泰拉尼斯”的后续，属于更宏大的“瓦拉里尔的搜寻”任务线的一部分。",al={"返回瓦拉里尔前置任务","返回瓦拉里尔前序","什么任务在返回瓦拉里尔之前"}}},fp="20,207,20.327.0,20.311.1,27.90.0,22.54.0,38.36.0,27.70.0"}
